-- Ids de cargo en orden estable (menú, enumeraciones de remotos).
RoleDefinitions.Ids = {
	"Estudiante",
	"Director", "Subdirector", "CoordinadorAcademico", "CoordinadorConvivencia",
	"ProfesorTitular", "Tutor", "ProfesorApoyo",
	"Orientador", "Enfermero",
	"Secretario", "AdministradorFinanciero", "Recepcionista",
	"Limpieza", "Seguridad", "Cocinero", "VendedorCafeteria",
}

---------------------------------------------------------------------------------------------------
-- Autocomprobación al cargar (detecta errores de edición en Studio)
---------------------------------------------------------------------------------------------------
do
	local vistos = {}
	for _, id in ipairs(RoleDefinitions.Ids) do
		local rol = RoleDefinitions.Roles[id]
		assert(rol ~= nil, "RoleDefinitions: el cargo '" .. id .. "' está en Ids pero no en Roles")
		assert(rol.Id == id, "RoleDefinitions: el cargo '" .. id .. "' tiene un Id distinto")
		assert(RoleDefinitions.Equipos[rol.Equipo] ~= nil, "RoleDefinitions: equipo desconocido en '" .. id .. "'")
		for permiso in pairs(rol.Permisos) do
			assert(setPermisosConocidos[permiso], "RoleDefinitions: permiso desconocido '" .. tostring(permiso) .. "' en '" .. id .. "'")
		end
		vistos[id] = true
	end
	for id in pairs(RoleDefinitions.Roles) do
		assert(vistos[id], "RoleDefinitions: el cargo '" .. id .. "' no está en Ids")
	end
end

---------------------------------------------------------------------------------------------------
-- Consultas
---------------------------------------------------------------------------------------------------

-- ¿Existe el cargo?
function RoleDefinitions.Existe(cargoId)
	return typeof(cargoId) == "string" and RoleDefinitions.Roles[cargoId] ~= nil
end

-- Definición completa del cargo o nil.
function RoleDefinitions.Obtener(cargoId)
	if typeof(cargoId) ~= "string" then
		return nil
	end
	return RoleDefinitions.Roles[cargoId]
end

-- ¿El cargo tiene el permiso? Cargos o permisos desconocidos -> false.
function RoleDefinitions.Tiene(cargoId, permiso)
	local rol = RoleDefinitions.Obtener(cargoId)
	if not rol or typeof(permiso) ~= "string" then
		return false
	end
	return rol.Permisos[permiso] == true
end

-- Nombre del equipo del cargo ("Docentes") o nil.
function RoleDefinitions.Equipo(cargoId)
	local rol = RoleDefinitions.Obtener(cargoId)
	if not rol then
		return nil
	end
	return rol.Equipo
end

-- Tabla del equipo (Nombre, Color (BrickColor), Color3, Orden, Descripcion) del cargo o nil.
function RoleDefinitions.EquipoInfo(cargoId)
	local equipo = RoleDefinitions.Equipo(cargoId)
	if not equipo then
		return nil
	end
	return RoleDefinitions.Equipos[equipo]
end

-- Nombre visible del cargo (o el id si no existe).
function RoleDefinitions.Nombre(cargoId)
	local rol = RoleDefinitions.Obtener(cargoId)
	if rol then
		return rol.Nombre
	end
	return tostring(cargoId)
end

-- Abreviatura del cargo para etiquetas (o "?" si no existe).
function RoleDefinitions.Abrev(cargoId)
	local rol = RoleDefinitions.Obtener(cargoId)
	if rol then
		return rol.Abrev
	end
	return "?"
end

-- ¿Es un cargo docente (puede abrir sesiones de clase)?
function RoleDefinitions.EsDocente(cargoId)
	return RoleDefinitions.Tiene(cargoId, "aula.docente")
end

-- Lista ordenada (por equipo y luego por Orden) de las definiciones de cargo. Se calcula una vez.
local listaOrdenada = nil
function RoleDefinitions.Lista()
	if listaOrdenada then
		return listaOrdenada
	end
	local lista = {}
	for _, id in ipairs(RoleDefinitions.Ids) do
		table.insert(lista, RoleDefinitions.Roles[id])
	end
	table.sort(lista, function(a, b)
		local ea, eb = RoleDefinitions.Equipos[a.Equipo].Orden, RoleDefinitions.Equipos[b.Equipo].Orden
		if ea ~= eb then
			return ea < eb
		end
		if a.Orden ~= b.Orden then
			return a.Orden < b.Orden
		end
		return a.Id < b.Id
	end)
	listaOrdenada = lista
	return lista
end

-- Ids de los cargos que tienen un permiso.
function RoleDefinitions.ConPermiso(permiso)
	local ids = {}
	for _, rol in ipairs(RoleDefinitions.Lista()) do
		if rol.Permisos[permiso] then
			table.insert(ids, rol.Id)
		end
	end
	return ids
end

-- Ids de los cargos de un equipo, ordenados.
function RoleDefinitions.CargosDeEquipo(nombreEquipo)
	local ids = {}
	for _, rol in ipairs(RoleDefinitions.Lista()) do
		if rol.Equipo == nombreEquipo then
			table.insert(ids, rol.Id)
		end
	end
	return ids
end

-- ¿Puede un cargo administrador asignar el cargo objetivo? (cargos.asignar y no está en CargosNoAsignables)
function RoleDefinitions.PuedeAsignar(cargoAdmin, cargoObjetivo)
	local admin = RoleDefinitions.Obtener(cargoAdmin)
	if not admin or not RoleDefinitions.Existe(cargoObjetivo) then
		return false
	end
	if not admin.Permisos["cargos.asignar"] then
		return false
	end
	if admin.CargosNoAsignables then
		for _, prohibido in ipairs(admin.CargosNoAsignables) do
			if prohibido == cargoObjetivo then
				return false
			end
		end
	end
	return true
end

-- Zona de aparición efectiva: resuelve "AULA_ASIGNADA" con el aula del jugador o el aula de respaldo.
function RoleDefinitions.ZonaSpawnDe(cargoId, aulaAsignada)
	local rol = RoleDefinitions.Obtener(cargoId)
	if not rol then
		return nil
	end
	if rol.ZonaSpawn == RoleDefinitions.ZonaSpawnAulaAsignada then
		if typeof(aulaAsignada) == "string" and aulaAsignada ~= "" then
			return aulaAsignada
		end
		return RoleDefinitions.AulaRespaldo
	end
	return rol.ZonaSpawn
end

-- Resumen público de un cargo para enviar al cliente (sin tablas internas).
function RoleDefinitions.Resumen(cargoId)
	local rol = RoleDefinitions.Obtener(cargoId)
	if not rol then
		return nil
	end
	return {
		Id = rol.Id, Nombre = rol.Nombre, Abrev = rol.Abrev, Equipo = rol.Equipo,
		Descripcion = rol.Descripcion, RequiereAutorizacion = rol.RequiereAutorizacion,
	}
end

return RoleDefinitions
]=] }
FUENTES["ReplicatedStorage/ColegioRP/Shared/TimetableDefinitions"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ReplicatedStorage.ColegioRP.Shared.TimetableDefinitions
	Tipo: ModuleScript
	Periodos de la jornada escolar (máquina de estados de SchoolDayService), materias y tolerancias.
	El reloj escolar avanza desde la HoraEscolar de cada periodo hasta la del siguiente de forma lineal
	con el tiempo real del periodo (ver HoraEscolarEn).
]]

local TimetableDefinitions = {}

-- Estados en el orden en que se suceden. Tras REINICIO vuelve a ESPERA.
TimetableDefinitions.Estados = {
	"ESPERA", "ENTRADA", "CLASE_1", "TRANSICION", "DESCANSO", "CLASE_2", "ALMUERZO", "CLASE_3", "SALIDA", "REINICIO",
}

-- Duracion en segundos reales (por defecto); Nombre visible; HoraEscolar "HH:MM" al inicio del periodo.
-- EsClase: periodo lectivo con asistencia; ComidaGratis: el comedor reparte raciones; Deporte: cancha activa.
TimetableDefinitions.Periodos = {
	{ Estado = "ESPERA", Duracion = 60, Nombre = "Esperando inicio", HoraEscolar = "06:45" },
	{ Estado = "ENTRADA", Duracion = 90, Nombre = "Entrada", HoraEscolar = "07:00" },
	{ Estado = "CLASE_1", Duracion = 300, Nombre = "1ª clase", HoraEscolar = "07:15", EsClase = true, Materia = "MAT" },
	{ Estado = "TRANSICION", Duracion = 45, Nombre = "Cambio de clase", HoraEscolar = "08:15" },
	{ Estado = "DESCANSO", Duracion = 150, Nombre = "Descanso", HoraEscolar = "08:30", ComidaGratis = true, Deporte = true },
	{ Estado = "CLASE_2", Duracion = 300, Nombre = "2ª clase", HoraEscolar = "09:00", EsClase = true, Materia = "ESP" },
	{ Estado = "ALMUERZO", Duracion = 180, Nombre = "Almuerzo", HoraEscolar = "10:30", ComidaGratis = true, Deporte = true },
	{ Estado = "CLASE_3", Duracion = 300, Nombre = "3ª clase", HoraEscolar = "11:15", EsClase = true, Materia = "CIE" },
	{ Estado = "SALIDA", Duracion = 90, Nombre = "Salida", HoraEscolar = "12:30" },
	-- HoraEscolarFin: hora en la que termina el último periodo (el siguiente, ESPERA, es del día siguiente).
	{ Estado = "REINICIO", Duracion = 20, Nombre = "Reinicio de jornada", HoraEscolar = "12:45", HoraEscolarFin = "13:00" },
}

-- Materias disponibles (código -> nombre visible). CoordinadorAcademico puede cambiar la materia de cada clase.
TimetableDefinitions.Materias = {
	MAT = "Matemáticas",
	ESP = "Español",
	CIE = "Ciencias",
	SOC = "Sociales",
	ING = "Inglés",
	TEC = "Tecnología",
	EDF = "Educación física",
	ART = "Artes",
}

-- Códigos de materia en orden estable (selectores de la interfaz).
TimetableDefinitions.OrdenMaterias = { "MAT", "ESP", "CIE", "SOC", "ING", "TEC", "EDF", "ART" }

TimetableDefinitions.ToleranciaTardanzaSeg = 60 -- Segundos tras el inicio de la clase para contar como Presente.
TimetableDefinitions.MarcarAusenciaSeg = 180 -- Segundos tras el inicio de la clase para marcar Ausente.

---------------------------------------------------------------------------------------------------
-- Índices y totales (calculados una vez)
---------------------------------------------------------------------------------------------------
local indicePorEstado = {}
local inicioAcumulado = {}
local total = 0
for i, periodo in ipairs(TimetableDefinitions.Periodos) do
	assert(TimetableDefinitions.Estados[i] == periodo.Estado,
		"TimetableDefinitions: Estados y Periodos no coinciden en la posición " .. i)
	indicePorEstado[periodo.Estado] = i
	inicioAcumulado[periodo.Estado] = total
	total = total + periodo.Duracion
end

-- Duración total de la jornada en segundos reales (escala 1).
TimetableDefinitions.TotalJornadaSeg = total

-- Primer y último estado de la jornada.
TimetableDefinitions.EstadoInicial = TimetableDefinitions.Estados[1]
TimetableDefinitions.EstadoFinal = TimetableDefinitions.Estados[#TimetableDefinitions.Estados]

---------------------------------------------------------------------------------------------------
-- Consultas
---------------------------------------------------------------------------------------------------

-- Convierte "HH:MM" en segundos del día (nil si el formato no es válido).
local function hhmmASegundos(texto)
	if typeof(texto) ~= "string" then
		return nil
	end
	local h, m = string.match(texto, "^(%d%d?):(%d%d)$")
	if not h then
		return nil
	end
	h, m = tonumber(h), tonumber(m)
	if h > 23 or m > 59 then
		return nil
	end
	return h * 3600 + m * 60
end
TimetableDefinitions.HHMMASegundos = hhmmASegundos

-- ¿Es un estado válido?
function TimetableDefinitions.Existe(estado)
	return indicePorEstado[estado] ~= nil
end

-- Índice (1..n) del estado o nil.
function TimetableDefinitions.Indice(estado)
	return indicePorEstado[estado]
end

-- Tabla del periodo del estado o nil.
function TimetableDefinitions.Periodo(estado)
	local i = indicePorEstado[estado]
	if not i then
		return nil
	end
	return TimetableDefinitions.Periodos[i]
end

-- Estado siguiente (tras el último vuelve al primero). Estado desconocido -> primer estado.
function TimetableDefinitions.Siguiente(estado)
	local i = indicePorEstado[estado]
	if not i then
		return TimetableDefinitions.Estados[1]
	end
	local siguiente = i + 1
	if siguiente > #TimetableDefinitions.Estados then
		siguiente = 1
	end
	return TimetableDefinitions.Estados[siguiente]
end

-- Estado anterior (antes del primero está el último).
function TimetableDefinitions.Anterior(estado)
	local i = indicePorEstado[estado]
	if not i then
		return TimetableDefinitions.Estados[1]
	end
	local anterior = i - 1
	if anterior < 1 then
		anterior = #TimetableDefinitions.Estados
	end
	return TimetableDefinitions.Estados[anterior]
end

-- Segundos del día en que empieza el periodo (HoraEscolar "HH:MM" -> segundos). nil si no existe.
function TimetableDefinitions.HoraEscolarSegundos(estado)
	local periodo = TimetableDefinitions.Periodo(estado)
	if not periodo then
		return nil
	end
	return hhmmASegundos(periodo.HoraEscolar)
end

-- Segundos del día en que termina el periodo: HoraEscolarFin si la tiene, si no la HoraEscolar del siguiente.
function TimetableDefinitions.HoraEscolarFinSegundos(estado)
	local periodo = TimetableDefinitions.Periodo(estado)
	if not periodo then
		return nil
	end
	if periodo.HoraEscolarFin then
		return hhmmASegundos(periodo.HoraEscolarFin)
	end
	local inicio = hhmmASegundos(periodo.HoraEscolar)
	local fin = TimetableDefinitions.HoraEscolarSegundos(TimetableDefinitions.Siguiente(estado))
	if fin == nil or inicio == nil or fin <= inicio then
		-- Sin siguiente coherente: el periodo "dura" lo mismo en reloj escolar que en tiempo real.
		return (inicio or 0) + periodo.Duracion
	end
	return fin
end

-- Hora escolar (segundos del día) en un punto del periodo. progreso = 0..1 (tiempo real transcurrido / duración).
function TimetableDefinitions.HoraEscolarEn(estado, progreso)
	local inicio = TimetableDefinitions.HoraEscolarSegundos(estado)
	if inicio == nil then
		return 0
	end
	local fin = TimetableDefinitions.HoraEscolarFinSegundos(estado) or inicio
	progreso = tonumber(progreso) or 0
	if progreso ~= progreso then
		progreso = 0
	end
	progreso = math.max(0, math.min(1, progreso))
	return math.floor(inicio + (fin - inicio) * progreso)
end

-- Nombre visible del periodo ("1ª clase") o el estado si no existe.
function TimetableDefinitions.Nombre(estado)
	local periodo = TimetableDefinitions.Periodo(estado)
	if periodo then
		return periodo.Nombre
	end
	return tostring(estado)
end

-- ¿Es un periodo de clase?
function TimetableDefinitions.EsClase(estado)
	local periodo = TimetableDefinitions.Periodo(estado)
	return periodo ~= nil and periodo.EsClase == true
end

-- ¿El comedor reparte comida gratis en este periodo?
function TimetableDefinitions.EsComidaGratis(estado)
	local periodo = TimetableDefinitions.Periodo(estado)
	return periodo ~= nil and periodo.ComidaGratis == true
end

-- ¿La cancha está activa en este periodo?
function TimetableDefinitions.EsDeporte(estado)
	local periodo = TimetableDefinitions.Periodo(estado)
	return periodo ~= nil and periodo.Deporte == true
end

-- Código de materia del periodo (o nil si no es clase).
function TimetableDefinitions.MateriaDe(estado)
	local periodo = TimetableDefinitions.Periodo(estado)
	if periodo and periodo.EsClase then
		return periodo.Materia
	end
	return nil
end

-- Nombre visible de una materia por código ("MAT" -> "Matemáticas"); devuelve el código si no existe.
function TimetableDefinitions.NombreMateria(codigo)
	if typeof(codigo) ~= "string" then
		return "—"
	end
	return TimetableDefinitions.Materias[codigo] or codigo
end

-- ¿Existe el código de materia?
function TimetableDefinitions.ExisteMateria(codigo)
	return typeof(codigo) == "string" and TimetableDefinitions.Materias[codigo] ~= nil
end

-- Duración real del periodo aplicando una escala (Config.Jornada.EscalaTiempo). Mínimo 5 s.
function TimetableDefinitions.DuracionReal(estado, escala)
	local periodo = TimetableDefinitions.Periodo(estado)
	if not periodo then
		return 0
	end
	escala = tonumber(escala) or 1
	if escala ~= escala or escala <= 0 then
		escala = 1
	end
	return math.max(5, periodo.Duracion * escala)
end

-- Segundos (escala 1) desde el inicio de la jornada hasta el inicio del periodo.
function TimetableDefinitions.InicioAcumulado(estado)
	return inicioAcumulado[estado]
end

-- Estado en el que se encuentra la jornada tras 'transcurrido' segundos reales desde su inicio (escala 1).
-- Devuelve estado, segundos restantes del periodo, progreso 0..1. Si supera el total, devuelve el último.
function TimetableDefinitions.EstadoEnTiempo(transcurrido)
	transcurrido = tonumber(transcurrido) or 0
	if transcurrido ~= transcurrido or transcurrido < 0 then
		transcurrido = 0
	end
	local acumulado = 0
	for _, periodo in ipairs(TimetableDefinitions.Periodos) do
		local fin = acumulado + periodo.Duracion
		if transcurrido < fin then
			local enPeriodo = transcurrido - acumulado
			return periodo.Estado, fin - transcurrido, enPeriodo / periodo.Duracion
		end
		acumulado = fin
	end
	return TimetableDefinitions.EstadoFinal, 0, 1
end

-- Lista de los periodos de clase (para el panel de horario).
function TimetableDefinitions.Clases()
	local lista = {}
	for _, periodo in ipairs(TimetableDefinitions.Periodos) do
		if periodo.EsClase then
			table.insert(lista, periodo)
		end
	end
	return lista
end

return TimetableDefinitions
]=] }
FUENTES["ReplicatedStorage/ColegioRP/Shared/UITheme"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ReplicatedStorage.ColegioRP.Shared.UITheme
	Tipo: ModuleScript
	Tema visual de la interfaz: colores institucionales (del logo), fuentes, tamaños, radios,
	espaciados, animaciones y detección de dispositivo para escalar el texto (PC 1, tableta 0.9, móvil 0.8).
	Es seguro requerirlo en el servidor (Escala() devuelve 1 y Dispositivo() "PC").
]]

local RunService = game:GetService("RunService")

local UITheme = {}

---------------------------------------------------------------------------------------------------
-- Colores
---------------------------------------------------------------------------------------------------
UITheme.Colores = {
	Rojo = Color3.fromRGB(196, 30, 36), -- Color principal institucional (botones primarios, acentos).
	RojoOscuro = Color3.fromRGB(150, 22, 28), -- Hover/pulsado del rojo y bordes de énfasis.
	Blanco = Color3.fromRGB(245, 245, 245), -- Texto sobre fondos oscuros y superficies claras.
	Gris = Color3.fromRGB(34, 36, 40), -- Fondo de paneles secundarios y botones neutros.
	GrisPanel = Color3.fromRGB(24, 25, 28), -- Fondo principal de paneles.
	Amarillo = Color3.fromRGB(246, 196, 34), -- Avisos, destacados, monedas.
	Azul = Color3.fromRGB(31, 78, 160), -- Información, enlaces, equipo Estudiantes.
	Verde = Color3.fromRGB(44, 160, 90), -- Éxito, confirmaciones, equipo Docentes.
	TextoPrincipal = Color3.fromRGB(245, 245, 245),
	TextoSecundario = Color3.fromRGB(190, 190, 195),
	TextoApagado = Color3.fromRGB(130, 132, 138), -- Texto deshabilitado o de ayuda.
	Fondo = Color3.fromRGB(10, 10, 12), -- Fondo de pantalla de carga y menú.
	Borde = Color3.fromRGB(60, 62, 68), -- Bordes (UIStroke) de paneles y entradas.
	Entrada = Color3.fromRGB(44, 46, 52), -- Fondo de TextBox.
	Desactivado = Color3.fromRGB(90, 92, 98), -- Botones deshabilitados.
	Sombra = Color3.fromRGB(0, 0, 0),
	Exito = Color3.fromRGB(44, 160, 90),
	Aviso = Color3.fromRGB(246, 196, 34),
	Error = Color3.fromRGB(196, 30, 36),
	Info = Color3.fromRGB(31, 78, 160),
}

-- Colores de estado para toasts y etiquetas (Tipo -> color).
UITheme.ColoresEstado = {
	Exito = UITheme.Colores.Exito,
	Aviso = UITheme.Colores.Aviso,
	Error = UITheme.Colores.Error,
	Info = UITheme.Colores.Info,
	Neutro = UITheme.Colores.Gris,
}

---------------------------------------------------------------------------------------------------
-- Tipografía
---------------------------------------------------------------------------------------------------
UITheme.Fuentes = {
	Titulo = Enum.Font.GothamBold,
	Subtitulo = Enum.Font.GothamMedium,
	Texto = Enum.Font.Gotham,
	Boton = Enum.Font.GothamMedium,
	Mono = Enum.Font.Code, -- Editor de programación y trazas.
}

-- Tamaños de texto base (se multiplican por Escala()).
UITheme.Tamanos = {
	TituloGrande = 30, -- Título del menú principal.
	Titulo = 24,
	Subtitulo = 18,
	Texto = 16,
	Boton = 16,
	Pequeno = 13,
	Etiqueta = 12, -- Etiquetas sobre la cabeza y pies de panel.
}

-- Escala de texto por dispositivo.
UITheme.EscalaTexto = { PC = 1, Tableta = 0.9, Movil = 0.8, Mando = 1 }

---------------------------------------------------------------------------------------------------
-- Geometría y animación
---------------------------------------------------------------------------------------------------
UITheme.Radio = 8 -- UICorner de paneles y botones.
UITheme.RadioPequeno = 4 -- UICorner de etiquetas y entradas.
UITheme.Espaciado = 8 -- Padding y separación estándar.
UITheme.EspaciadoGrande = 16
UITheme.GrosorBorde = 1 -- UIStroke.Thickness.
UITheme.TamanoMinimoTactil = 44 -- Alto/ancho mínimo (px) de un control táctil.
UITheme.AnchoPanel = 420 -- Ancho de referencia de paneles en PC (px).
UITheme.AnchoPanelAncho = 640
UITheme.Animacion = { Rapida = 0.15, Normal = 0.25, Lenta = 0.4 }
UITheme.Estilo = Enum.EasingStyle.Quad
UITheme.Direccion = Enum.EasingDirection.Out

-- DisplayOrder de cada capa de ScreenGui (docs/ARQUITECTURA.md §7).
UITheme.Capas = { Carga = 100, Menu = 90, Modal = 80, Panel = 50, HUD = 10 }

-- Transparencias estándar.
UITheme.Transparencias = { Panel = 0.05, Fondo = 0.35, Hover = 0.1, Desactivado = 0.5, Sombra = 0.6 }

---------------------------------------------------------------------------------------------------
-- Funciones
---------------------------------------------------------------------------------------------------

-- Color por nombre ("Rojo", "Exito", ...). Si no existe, devuelve TextoPrincipal y avisa una vez.
local avisados = {}
function UITheme.Color(nombre)
	local color = UITheme.Colores[nombre]
	if color then
		return color
	end
	if not avisados[tostring(nombre)] then
		avisados[tostring(nombre)] = true
		warn("[ColegioRP][UITheme] Color desconocido: " .. tostring(nombre))
	end
	return UITheme.Colores.TextoPrincipal
end

-- Fuente por nombre ("Titulo", "Texto", ...), con respaldo a Texto.
function UITheme.Fuente(nombre)
	return UITheme.Fuentes[nombre] or UITheme.Fuentes.Texto
end

-- Mezcla el color hacia blanco (factor 0..1).
function UITheme.Aclarar(color, factor)
	return color:Lerp(Color3.new(1, 1, 1), math.max(0, math.min(1, factor or 0.15)))
end

-- Mezcla el color hacia negro (factor 0..1).
function UITheme.Oscurecer(color, factor)
	return color:Lerp(Color3.new(0, 0, 0), math.max(0, math.min(1, factor or 0.15)))
end

-- Color de texto legible (blanco o gris oscuro) sobre un fondo dado.
function UITheme.TextoSobre(fondo)
	local luminancia = 0.299 * fondo.R + 0.587 * fondo.G + 0.114 * fondo.B
	if luminancia > 0.6 then
		return UITheme.Colores.GrisPanel
	end
	return UITheme.Colores.TextoPrincipal
end

-- Detecta el dispositivo: "PC" | "Tableta" | "Movil" | "Mando". En servidor devuelve "PC".
-- Se recalcula en cada llamada (el jugador puede conectar un mando o teclado durante la sesión).
function UITheme.Dispositivo()
	if not RunService:IsClient() then
		return "PC"
	end
	local ok, resultado = pcall(function()
		local UserInputService = game:GetService("UserInputService")
		local GuiService = game:GetService("GuiService")
		if GuiService:IsTenFootInterface() then
			return "Mando"
		end
		local tactil = UserInputService.TouchEnabled
		local teclado = UserInputService.KeyboardEnabled
		local raton = UserInputService.MouseEnabled
		if tactil and not teclado and not raton then
			local camara = workspace.CurrentCamera
			local tamano = camara and camara.ViewportSize or Vector2.new(0, 0)
			if math.min(tamano.X, tamano.Y) >= 600 then
				return "Tableta"
			end
			return "Movil"
		end
		if UserInputService.GamepadEnabled and not teclado and not raton and not tactil then
			return "Mando"
		end
		return "PC"
	end)
	if ok and typeof(resultado) == "string" then
		return resultado
	end
	return "PC"
end

-- Escala de texto según el dispositivo (1 PC, 0.9 tableta, 0.8 móvil).
function UITheme.Escala()
	return UITheme.EscalaTexto[UITheme.Dispositivo()] or 1
end

-- ¿La entrada principal es táctil?
function UITheme.EsTactil()
	local dispositivo = UITheme.Dispositivo()
	return dispositivo == "Movil" or dispositivo == "Tableta"
end

-- ¿Se navega con mando (foco)?
function UITheme.EsMando()
	return UITheme.Dispositivo() == "Mando"
end

-- Tamaño de texto escalado y redondeado (nombre de UITheme.Tamanos o número).
function UITheme.Tamano(nombreOValor, escalaUsuario)
	local base = UITheme.Tamanos[nombreOValor] or tonumber(nombreOValor) or UITheme.Tamanos.Texto
	local escala = UITheme.Escala() * (tonumber(escalaUsuario) or 1)
	return math.max(8, math.floor(base * escala + 0.5))
end

-- TweenInfo estándar ("Rapida" | "Normal" | "Lenta" o segundos). Con movimientoReducido dura 0.
function UITheme.TweenInfo(velocidad, movimientoReducido)
	local duracion = UITheme.Animacion[velocidad] or tonumber(velocidad) or UITheme.Animacion.Normal
	if movimientoReducido then
		duracion = 0
	end
	return TweenInfo.new(duracion, UITheme.Estilo, UITheme.Direccion)
end

return UITheme
]=] }
FUENTES["ReplicatedStorage/ColegioRP/Shared/Util"] = { clase = "Folder" }
FUENTES["ReplicatedStorage/ColegioRP/Shared/Util/Format"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ReplicatedStorage.ColegioRP.Shared.Util.Format
	Tipo: ModuleScript
	Formato de textos para la interfaz en español: horas (12/24 h), moneda escolar, duraciones,
	truncado seguro de UTF-8, fechas y números con separador de miles.
]]

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RP = ReplicatedStorage:WaitForChild("ColegioRP")
local Shared = RP:WaitForChild("Shared")
local Config = require(Shared:WaitForChild("Config"))

local Format = {}

Format.Elipsis = "…"
Format.SeparadorMiles = "."
Format.SeparadorDecimal = ","

local function aNumero(valor, porDefecto)
	local n = tonumber(valor)
	if n == nil or n ~= n or n == math.huge or n == -math.huge then
		return porDefecto
	end
	return n
end

-- Número entero con separador de miles ("1.250"). Los decimales se redondean.
function Format.Numero(n)
	n = aNumero(n, 0)
	local negativo = n < 0
	local entero = math.floor(math.abs(n) + 0.5)
	local texto = tostring(entero)
	local resultado = ""
	local contador = 0
	for i = #texto, 1, -1 do
		resultado = string.sub(texto, i, i) .. resultado
		contador = contador + 1
		if contador % 3 == 0 and i > 1 then
			resultado = Format.SeparadorMiles .. resultado
		end
	end
	if negativo then
		return "-" .. resultado
	end
	return resultado
end

-- Número con decimales fijos y coma decimal ("3,14").
function Format.Decimal(n, decimales)
	n = aNumero(n, 0)
	decimales = decimales or 2
	local texto = string.format("%." .. decimales .. "f", n)
	texto = string.gsub(texto, "%.", Format.SeparadorDecimal)
	return texto
end

-- Hora escolar a partir de segundos del día. formato12 = true -> "7:15 a. m."; si no -> "07:15".
function Format.HoraHHMM(segundosDia, formato12)
	local total = math.floor(aNumero(segundosDia, 0)) % 86400
	local h = math.floor(total / 3600)
	local m = math.floor((total % 3600) / 60)
	if formato12 then
		local sufijo = "a. m."
		if h >= 12 then
			sufijo = "p. m."
		end
		local h12 = h % 12
		if h12 == 0 then
			h12 = 12
		end
		return string.format("%d:%02d %s", h12, m, sufijo)
	end
	return string.format("%02d:%02d", h, m)
end

-- Convierte "HH:MM" a segundos del día (nil si el formato es inválido).
function Format.SegundosDeHHMM(texto)
	if typeof(texto) ~= "string" then
		return nil
	end
	local h, m = string.match(texto, "^(%d%d?):(%d%d)$")
	if not h then
		return nil
	end
	h, m = tonumber(h), tonumber(m)
	if h > 23 or m > 59 then
		return nil
	end
	return h * 3600 + m * 60
end

-- Importe en moneda escolar ("◎ 1.250"). conNombre = true añade el nombre de la moneda.
function Format.Moneda(n, conNombre)
	local simbolo = (Config.Economia and Config.Economia.MonedaSimbolo) or "◎"
	local texto = simbolo .. " " .. Format.Numero(n)
	if conNombre then
		local nombre = (Config.Economia and Config.Economia.MonedaNombre) or "Monedas"
		return texto .. " " .. string.lower(nombre)
	end
	return texto
end

-- Tiempo restante "mm:ss" (o "h:mm:ss" si supera una hora). Nunca negativo.
function Format.Tiempo(seg)
	local total = math.max(0, math.floor(aNumero(seg, 0) + 0.5))
	local h = math.floor(total / 3600)
	local m = math.floor((total % 3600) / 60)
	local s = total % 60
	if h > 0 then
		return string.format("%d:%02d:%02d", h, m, s)
	end
	return string.format("%02d:%02d", m, s)
end

-- Duración legible ("45 s", "5 min", "1 h 20 min").
function Format.Duracion(seg)
	local total = math.max(0, math.floor(aNumero(seg, 0) + 0.5))
	if total < 60 then
		return total .. " s"
	end
	local h = math.floor(total / 3600)
	local m = math.floor((total % 3600) / 60)
	if h > 0 then
		if m > 0 then
			return string.format("%d h %d min", h, m)
		end
		return h .. " h"
	end
	return m .. " min"
end

-- Longitud en caracteres (UTF-8); si el texto es inválido cuenta bytes.
function Format.Longitud(texto)
	if typeof(texto) ~= "string" then
		return 0
	end
	local n = utf8.len(texto)
	if n == nil then
		return #texto
	end
	return n
end

-- Recorta el texto a n caracteres (UTF-8) añadiendo "…" si hace falta.
function Format.Truncar(texto, n)
	if typeof(texto) ~= "string" then
		texto = tostring(texto or "")
	end
	n = math.max(1, math.floor(aNumero(n, 1)))
	local longitud = utf8.len(texto)
	if longitud == nil then
		-- UTF-8 inválido: recorte por bytes como último recurso.
		if #texto <= n then
			return texto
		end
		return string.sub(texto, 1, math.max(n - 1, 0)) .. Format.Elipsis
	end
	if longitud <= n then
		return texto
	end
	local caracteres = math.max(n - 1, 0)
	if caracteres == 0 then
		return Format.Elipsis
	end
	local corte = utf8.offset(texto, caracteres + 1)
	if corte == nil then
		return texto
	end
	return string.sub(texto, 1, corte - 1) .. Format.Elipsis
end

-- Fecha legible a partir de un tiempo Unix ("26/10/2026 14:05"); conHora = false omite la hora.
function Format.Fecha(unix, conHora)
	unix = math.floor(aNumero(unix, os.time()))
	local ok, t = pcall(os.date, "*t", unix)
	if not ok or typeof(t) ~= "table" then
		return "--/--/----"
	end
	local texto = string.format("%02d/%02d/%04d", t.day, t.month, t.year)
	if conHora == false then
		return texto
	end
	return texto .. string.format(" %02d:%02d", t.hour, t.min)
end

-- Fecha corta "AAAA-MM-DD" (clave de día para límites diarios).
function Format.ClaveDia(unix)
	unix = math.floor(aNumero(unix, os.time()))
	local ok, t = pcall(os.date, "!*t", unix)
	if not ok or typeof(t) ~= "table" then
		return "0000-00-00"
	end
	return string.format("%04d-%02d-%02d", t.year, t.month, t.day)
end

-- Singular/plural según la cantidad ("1 página", "3 páginas").
function Format.Plural(n, singular, plural)
	n = aNumero(n, 0)
	if n == 1 then
		return Format.Numero(n) .. " " .. singular
	end
	return Format.Numero(n) .. " " .. (plural or (singular .. "s"))
end

-- Porcentaje entero ("75 %"); acepta fracción 0..1 o valor 0..100 (si esFraccion = true se multiplica).
function Format.Porcentaje(valor, esFraccion)
	valor = aNumero(valor, 0)
	if esFraccion then
		valor = valor * 100
	end
	return string.format("%d %%", math.floor(math.max(0, math.min(100, valor)) + 0.5))
end

-- Primera letra en mayúscula (sin tocar el resto).
function Format.Capitalizar(texto)
	if typeof(texto) ~= "string" or texto == "" then
		return ""
	end
	local primera = utf8.offset(texto, 2)
	if primera == nil then
		return string.upper(texto)
	end
	return string.upper(string.sub(texto, 1, primera - 1)) .. string.sub(texto, primera)
end

-- Elimina espacios al inicio y al final.
function Format.Recortar(texto)
	if typeof(texto) ~= "string" then
		return ""
	end
	local resultado = string.gsub(texto, "^%s+", "")
	resultado = string.gsub(resultado, "%s+$", "")
	return resultado
end

-- Nombre de equipo deportivo ("Equipo A").
function Format.Equipo(letra)
	return "Equipo " .. tostring(letra or "?")
end

-- Marcador "2 - 1".
function Format.Marcador(a, b)
	return string.format("%d - %d", math.floor(aNumero(a, 0)), math.floor(aNumero(b, 0)))
end

return Format
]=] }
FUENTES["ReplicatedStorage/ColegioRP/Shared/Util/Maid"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ReplicatedStorage.ColegioRP.Shared.Util.Maid
	Tipo: ModuleScript
	Recolector de tareas de limpieza: acumula conexiones, instancias, funciones, hilos y objetos
	con Destroy/Disconnect/DoCleaning y los libera todos con :DoCleaning() (o :Destroy()).
	También admite claves: maid.Nombre = tarea (reemplazar una clave limpia la tarea anterior).
]]

local Maid = {}
Maid.ClassName = "Maid"

-- Libera una única tarea según su tipo. Nunca lanza: los errores se registran con warn.
local function limpiarTarea(tarea)
	local tipo = typeof(tarea)
	local ok, err = pcall(function()
		if tipo == "function" then
			tarea()
		elseif tipo == "RBXScriptConnection" then
			tarea:Disconnect()
		elseif tipo == "Instance" then
			tarea:Destroy()
		elseif tipo == "thread" then
			task.cancel(tarea)
		elseif tipo == "table" then
			if typeof(tarea.Disconnect) == "function" then
				tarea:Disconnect()
			elseif typeof(tarea.Destroy) == "function" then
				tarea:Destroy()
			elseif typeof(tarea.DoCleaning) == "function" then
				tarea:DoCleaning()
			end
		end
	end)
	if not ok then
		warn("[ColegioRP][Maid] Error al limpiar una tarea: " .. tostring(err))
	end
end

-- Crea un Maid vacío.
function Maid.new()
	local self = { _tareas = {}, _siguienteId = 0 }
	return setmetatable(self, Maid)
end

-- Comprueba si un valor es un Maid.
function Maid.Es(valor)
	return typeof(valor) == "table" and getmetatable(valor) == Maid
end

-- Acceso: métodos del Maid o tarea guardada bajo esa clave.
function Maid.__index(self, clave)
	if Maid[clave] ~= nil then
		return Maid[clave]
	end
	return rawget(self, "_tareas")[clave]
end

-- Asignación por clave: maid.Clave = tarea (nil limpia y quita la tarea).
function Maid.__newindex(self, clave, tarea)
	if Maid[clave] ~= nil then
		error("Maid: no se puede sobrescribir el método '" .. tostring(clave) .. "'", 2)
	end
	local tareas = rawget(self, "_tareas")
	local anterior = tareas[clave]
	tareas[clave] = tarea
	if anterior ~= nil and anterior ~= tarea then
		limpiarTarea(anterior)
	end
end

-- Añade una tarea y devuelve su id numérico (para quitarla luego con :Remove(id)).
function Maid:GiveTask(tarea)
	assert(tarea ~= nil, "Maid:GiveTask recibió nil")
	local tipo = typeof(tarea)
	assert(
		tipo == "function" or tipo == "RBXScriptConnection" or tipo == "Instance" or tipo == "thread" or tipo == "table",
		"Maid:GiveTask: tipo de tarea no admitido (" .. tipo .. ")"
	)
	local id = rawget(self, "_siguienteId") + 1
	rawset(self, "_siguienteId", id)
	rawget(self, "_tareas")[id] = tarea
	return id
end

Maid.Add = Maid.GiveTask

-- Atajo: crea y registra una conexión a una señal (RBXScriptSignal o Signal propio).
function Maid:Conectar(senal, fn)
	local conexion = senal:Connect(fn)
	self:GiveTask(conexion)
	return conexion
end

-- Limpia y quita la tarea con ese id o clave.
function Maid:Remove(idOClave)
	local tareas = rawget(self, "_tareas")
	local tarea = tareas[idOClave]
	if tarea ~= nil then
		tareas[idOClave] = nil
		limpiarTarea(tarea)
	end
end

-- Libera todas las tareas. El Maid queda vacío y puede reutilizarse.
function Maid:DoCleaning()
	local tareas = rawget(self, "_tareas")
	rawset(self, "_tareas", {})
	-- Primero las conexiones (evita que disparen durante la limpieza), luego el resto.
	for clave, tarea in pairs(tareas) do
		if typeof(tarea) == "RBXScriptConnection" then
			limpiarTarea(tarea)
			tareas[clave] = nil
		end
	end
	for _, tarea in pairs(tareas) do
		limpiarTarea(tarea)
	end
end

Maid.Destroy = Maid.DoCleaning

-- Número de tareas pendientes.
function Maid:Cantidad()
	local n = 0
	for _ in pairs(rawget(self, "_tareas")) do
		n = n + 1
	end
	return n
end

return Maid
]=] }
FUENTES["ReplicatedStorage/ColegioRP/Shared/Util/Net"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ReplicatedStorage.ColegioRP.Shared.Util.Net
	Tipo: ModuleScript
	Acceso seguro a los remotos de ReplicatedStorage.ColegioRP.Remotes desde cliente y servidor.
	Evento/Funcion esperan la instancia (WaitForChild con timeout); en cliente, Invocar hace pcall de
	InvokeServer y devuelve siempre (ok, tablaRespuesta), y Disparar hace FireServer con pcall.
]]

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")

local RP = ReplicatedStorage:WaitForChild("ColegioRP")
local Shared = RP:WaitForChild("Shared")
local Config = require(Shared:WaitForChild("Config"))

local Net = {}

-- Segundos máximos de espera por la carpeta o por cada remoto.
Net.Timeout = (Config.Red and Config.Red.TimeoutRemotosSeg) or 30
-- Nombre de la carpeta de remotos (la crea RemoteService en el servidor).
Net.NombreCarpeta = (Config.Nombres and Config.Nombres.CarpetaRemotos) or "Remotes"
-- Nombre del canal multiplexado servidor -> cliente.
Net.NombreEventoCliente = "EventoCliente"

local esCliente = RunService:IsClient()
local esServidor = RunService:IsServer()
local cache = {}
local avisados = {}

local function avisarUnaVez(clave, mensaje)
	if avisados[clave] then
		return
	end
	avisados[clave] = true
	warn("[ColegioRP][Net] " .. mensaje)
end

---------------------------------------------------------------------------------------------------
-- Carpeta de remotos
---------------------------------------------------------------------------------------------------

-- Devuelve la carpeta Remotes. En servidor, con crearSiFalta = true, la crea si no existe.
-- En cliente (o sin crear) espera hasta Net.Timeout y devuelve nil si no aparece.
function Net.Carpeta(crearSiFalta)
	local carpeta = RP:FindFirstChild(Net.NombreCarpeta)
	if carpeta then
		return carpeta
	end
	if crearSiFalta and esServidor then
		carpeta = Instance.new("Folder")
		carpeta.Name = Net.NombreCarpeta
		carpeta.Parent = RP
		return carpeta
	end
	carpeta = RP:WaitForChild(Net.NombreCarpeta, Net.Timeout)
	if not carpeta then
		avisarUnaVez("carpeta", "La carpeta " .. Net.NombreCarpeta .. " no apareció en " .. Net.Timeout .. " s")
	end
	return carpeta
end

local function obtener(nombre, clase)
	if typeof(nombre) ~= "string" or nombre == "" then
		return nil
	end
	local enCache = cache[nombre]
	if enCache and enCache.Parent ~= nil then
		return enCache
	end
	local carpeta = Net.Carpeta(false)
	if not carpeta then
		return nil
	end
	local instancia = carpeta:FindFirstChild(nombre)
	if not instancia then
		instancia = carpeta:WaitForChild(nombre, Net.Timeout)
	end
	if not instancia then
		avisarUnaVez("remoto:" .. nombre, "El remoto '" .. nombre .. "' no apareció en " .. Net.Timeout .. " s")
		return nil
	end
	if not instancia:IsA(clase) then
		avisarUnaVez("clase:" .. nombre, "El remoto '" .. nombre .. "' es " .. instancia.ClassName .. " y se esperaba " .. clase)
		return nil
	end
	cache[nombre] = instancia
	return instancia
end

-- RemoteEvent por nombre (o nil tras el timeout, con warn).
function Net.Evento(nombre)
	return obtener(nombre, "RemoteEvent")
end

-- RemoteFunction por nombre (o nil tras el timeout, con warn).
function Net.Funcion(nombre)
	return obtener(nombre, "RemoteFunction")
end

-- Olvida una entrada de la caché (útil si RemoteService recrea un remoto).
function Net.Olvidar(nombre)
	cache[nombre] = nil
end

---------------------------------------------------------------------------------------------------
-- Cliente -> servidor
---------------------------------------------------------------------------------------------------

local function respuestaError(mensaje)
	return { ok = false, error = mensaje }
end

-- (Cliente) Invoca una RemoteFunction con una tabla de datos. Devuelve ok, respuesta.
-- 'respuesta' siempre es una tabla { ok, error, datos }; ok es true solo si la red funcionó y el
-- servidor respondió ok = true. Nunca lanza errores.
function Net.Invocar(nombre, datos)
	if not esCliente then
		return false, respuestaError("Net.Invocar solo puede usarse en el cliente")
	end
	if datos == nil then
		datos = {}
	end
	if typeof(datos) ~= "table" then
		return false, respuestaError("los datos deben ser una tabla")
	end
	local remoto = Net.Funcion(nombre)
	if not remoto then
		return false, respuestaError("remoto no disponible: " .. tostring(nombre))
	end
	local exito, respuesta = pcall(remoto.InvokeServer, remoto, datos)
	if not exito then
		return false, respuestaError("error de red: " .. tostring(respuesta))
	end
	if typeof(respuesta) ~= "table" then
		return false, respuestaError("respuesta inválida del servidor")
	end
	if respuesta.ok ~= true then
		if respuesta.error == nil then
			respuesta.error = "rechazado"
		end
		respuesta.ok = false
		return false, respuesta
	end
	return true, respuesta
end

-- (Cliente) Dispara un RemoteEvent con una tabla de datos. Devuelve true si se envió.
function Net.Disparar(nombre, datos)
	if not esCliente then
		warn("[ColegioRP][Net] Net.Disparar solo puede usarse en el cliente")
		return false
	end
	if datos == nil then
		datos = {}
	end
	if typeof(datos) ~= "table" then
		return false
	end
	local remoto = Net.Evento(nombre)
	if not remoto then
		return false
	end
	local exito, err = pcall(remoto.FireServer, remoto, datos)
	if not exito then
		warn("[ColegioRP][Net] Error al disparar '" .. tostring(nombre) .. "': " .. tostring(err))
		return false
	end
	return true
end

---------------------------------------------------------------------------------------------------
-- Servidor -> cliente (canal EventoCliente: { Tipo = string, Datos = tabla })
---------------------------------------------------------------------------------------------------

-- (Cliente) Se suscribe a EventoCliente filtrando por Tipo. callback(datos, carga).
-- Devuelve la RBXScriptConnection (o nil si el remoto no existe) para guardarla en un Maid.
function Net.Escuchar(tipo, callback)
	assert(typeof(callback) == "function", "Net.Escuchar espera una función")
	if not esCliente then
		warn("[ColegioRP][Net] Net.Escuchar solo puede usarse en el cliente")
		return nil
	end
	local remoto = Net.Evento(Net.NombreEventoCliente)
	if not remoto then
		return nil
	end
	return remoto.OnClientEvent:Connect(function(carga)
		if typeof(carga) ~= "table" then
			return
		end
		if tipo ~= nil and carga.Tipo ~= tipo then
			return
		end
		local datos = carga.Datos
		if datos == nil then
			datos = {}
		end
		local ok, err = pcall(callback, datos, carga)
		if not ok then
			warn("[ColegioRP][Net] Error en manejador de '" .. tostring(carga.Tipo) .. "': " .. tostring(err))
		end
	end)
end

-- (Servidor) Envía por EventoCliente a un jugador. RemoteService lo usa internamente.
function Net.EnviarA(player, tipo, datos)
	if not esServidor then
		return false
	end
	local remoto = Net.Evento(Net.NombreEventoCliente)
	if not remoto or typeof(player) ~= "Instance" or not player:IsA("Player") then
		return false
	end
	local exito, err = pcall(remoto.FireClient, remoto, player, { Tipo = tipo, Datos = datos or {} })
	if not exito then
		warn("[ColegioRP][Net] Error al enviar '" .. tostring(tipo) .. "': " .. tostring(err))
		return false
	end
	return true
end

-- (Servidor) Envía por EventoCliente a todos los jugadores.
function Net.EnviarATodos(tipo, datos)
	if not esServidor then
		return false
	end
	local remoto = Net.Evento(Net.NombreEventoCliente)
	if not remoto then
		return false
	end
	local exito, err = pcall(remoto.FireAllClients, remoto, { Tipo = tipo, Datos = datos or {} })
	if not exito then
		warn("[ColegioRP][Net] Error al enviar a todos '" .. tostring(tipo) .. "': " .. tostring(err))
		return false
	end
	return true
end

-- Construye la respuesta estándar de éxito de una RemoteFunction.
function Net.Ok(datos)
	return { ok = true, datos = datos }
end

-- Construye la respuesta estándar de error de una RemoteFunction.
function Net.Error(mensaje)
	return { ok = false, error = tostring(mensaje or "error") }
end

Net.EsCliente = esCliente
Net.EsServidor = esServidor

return Net
]=] }
FUENTES["ReplicatedStorage/ColegioRP/Shared/Util/Signal"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ReplicatedStorage.ColegioRP.Shared.Util.Signal
	Tipo: ModuleScript
	Señal ligera (patrón BindableEvent en Lua puro) para comunicar módulos del mismo lado
	sin crear instancias. API: Signal.new() -> :Connect(fn), :Once(fn), :Fire(...), :Wait(), :Destroy().
]]

local Signal = {}
Signal.__index = Signal

local Conexion = {}
Conexion.__index = Conexion

-- Conexión devuelta por :Connect; imita a RBXScriptConnection (Connected, Disconnect).
function Conexion.new(senal, fn)
	return setmetatable({ _senal = senal, _fn = fn, Connected = true }, Conexion)
end

function Conexion:Disconnect()
	if not self.Connected then
		return
	end
	self.Connected = false
	local lista = self._senal and self._senal._conexiones
	if lista then
		for i = #lista, 1, -1 do
			if lista[i] == self then
				table.remove(lista, i)
				break
			end
		end
	end
	self._senal = nil
	self._fn = nil
end

Conexion.Destroy = Conexion.Disconnect

-- Crea una señal nueva.
function Signal.new()
	return setmetatable({ _conexiones = {}, _destruida = false }, Signal)
end

-- Comprueba si un valor es una señal creada con este módulo.
function Signal.Es(valor)
	return typeof(valor) == "table" and getmetatable(valor) == Signal
end

-- Conecta una función; devuelve una conexión con :Disconnect().
function Signal:Connect(fn)
	assert(typeof(fn) == "function", "Signal:Connect espera una función")
	if self._destruida then
		-- Señal destruida: devolvemos una conexión ya desconectada para no romper al llamador.
		local muerta = Conexion.new(nil, fn)
		muerta.Connected = false
		return muerta
	end
	local conexion = Conexion.new(self, fn)
	table.insert(self._conexiones, conexion)
	return conexion
end

-- Conecta una función que se desconecta sola tras el primer disparo.
function Signal:Once(fn)
	assert(typeof(fn) == "function", "Signal:Once espera una función")
	local conexion
	conexion = self:Connect(function(...)
		if conexion then
			conexion:Disconnect()
		end
		fn(...)
	end)
	return conexion
end

-- Dispara la señal; cada manejador corre en su propio hilo (un error no afecta a los demás).
function Signal:Fire(...)
	if self._destruida then
		return
	end
	local copia = {}
	for i, conexion in ipairs(self._conexiones) do
		copia[i] = conexion
	end
	for _, conexion in ipairs(copia) do
		if conexion.Connected and conexion._fn then
			task.spawn(conexion._fn, ...)
		end
	end
end

-- Bloquea el hilo actual hasta el siguiente disparo y devuelve sus argumentos.
function Signal:Wait()
	if self._destruida then
		return
	end
	local hilo = coroutine.running()
	local conexion
	conexion = self:Connect(function(...)
		if conexion then
			conexion:Disconnect()
		end
		task.spawn(hilo, ...)
	end)
	return coroutine.yield()
end

-- Desconecta todas las conexiones sin destruir la señal.
function Signal:DisconnectAll()
	for _, conexion in ipairs(self._conexiones) do
		conexion.Connected = false
		conexion._senal = nil
		conexion._fn = nil
	end
	table.clear(self._conexiones)
end

-- Número de conexiones activas (útil para pruebas y métricas).
function Signal:Cantidad()
	return #self._conexiones
end

-- Destruye la señal: desconecta todo y rechaza nuevas conexiones.
function Signal:Destroy()
	self:DisconnectAll()
	self._destruida = true
end

return Signal
]=] }
FUENTES["ReplicatedStorage/ColegioRP/Shared/Util/Validate"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ReplicatedStorage.ColegioRP.Shared.Util.Validate
	Tipo: ModuleScript
	Validación declarativa de datos (peticiones de remotos y cualquier tabla). Un esquema describe
	campos y tipos; Validate.Comprobar(esquema, valor) devuelve ok y un mensaje legible en español.
	Por defecto los esquemas son estrictos (rechazan claves desconocidas) y acotan tamaño y anidación.

	Descriptores de campo admitidos (todos aceptan opcional = true):
		{ tipo = "string",  min = n, max = n, enum = {...}, patron = "...", sinSaltos = true }
		{ tipo = "number",  min = n, max = n, entero = true }
		{ tipo = "boolean" }
		{ tipo = "enum",    valores = { ... } }               -- strings o números
		{ tipo = "Vector3", magnitud = n }                    -- magnitud máxima (con tolerancia)
		{ tipo = "table",   campos = { ... } | esquema, estricto = bool }  -- tabla con campos
		{ tipo = "table",   libre = true }                    -- tabla libre acotada (claves/valores simples)
		{ tipo = "array",   de = descriptor, maxItems = n, minItems = n }
		{ tipo = "any" }                                      -- valor simple o tabla libre acotada
	Atajos: Validate.Str(max, opcional, min), Int(min, max, opcional), Num(min, max, opcional), Bool(opcional),
		Enum(valores, opcional), V3(magnitud, opcional), Tabla(campos, opcional, estricto), TablaLibre(opcional),
		Array(de, maxItems, opcional), Cualquiera(opcional).
]]

local Validate = {}

-- Límites de seguridad globales (protegen al servidor de tablas enormes o muy anidadas).
Validate.ProfundidadMax = 6 -- Niveles de anidación permitidos.
Validate.ClavesMax = 256 -- Claves totales recorridas por comprobación.
Validate.ClaveMaxCaracteres = 48 -- Longitud máxima de una clave de tabla libre.
Validate.TextoLibreMax = 2000 -- Longitud por defecto de un texto sin max explícito.
Validate.ArrayLibreMax = 128 -- Elementos por defecto de una lista sin maxItems.
Validate.ToleranciaMagnitud = 0.001 -- Tolerancia al comparar magnitudes de Vector3.

---------------------------------------------------------------------------------------------------
-- Utilidades internas
---------------------------------------------------------------------------------------------------
local function esFinito(n)
	return typeof(n) == "number" and n == n and n ~= math.huge and n ~= -math.huge
end

local function esEntero(n)
	return esFinito(n) and math.floor(n) == n
end

local function nombreRuta(ruta)
	if ruta == nil or ruta == "" then
		return "datos"
	end
	return ruta
end

-- Las claves pueden venir del cliente: solo se muestran si son identificadores cortos (nunca texto libre).
local function claveSegura(clave)
	if typeof(clave) == "number" then
		return tostring(clave)
	end
	if typeof(clave) == "string" and #clave <= 24 and string.match(clave, "^[%w_]+$") then
		return clave
	end
	return "?"
end

local function unirRuta(ruta, clave)
	if ruta == nil or ruta == "" then
		return claveSegura(clave)
	end
	return ruta .. "." .. claveSegura(clave)
end

local function enLista(lista, valor)
	for _, v in ipairs(lista) do
		if v == valor then
			return true
		end
	end
	return false
end

local function listarValores(lista)
	local partes = {}
	for i, v in ipairs(lista) do
		if i > 8 then
			table.insert(partes, "...")
			break
		end
		table.insert(partes, tostring(v))
	end
	return table.concat(partes, ", ")
end

local comprobarDescriptor
local comprobarTablaLibre

-- Valor "libre": texto, número finito, booleano, Vector3/Vector2/Color3 o tabla libre acotada.
local function comprobarValorLibre(valor, ruta, ctx, profundidad)
	local tipo = typeof(valor)
	if tipo == "string" then
		local n = utf8.len(valor)
		if not n then
			return false, nombreRuta(ruta) .. " contiene texto inválido"
		end
		if n > Validate.TextoLibreMax then
			return false, string.format("%s supera los %d caracteres", nombreRuta(ruta), Validate.TextoLibreMax)
		end
		return true
	elseif tipo == "number" then
		if not esFinito(valor) then
			return false, nombreRuta(ruta) .. " no es un número finito"
		end
		return true
	elseif tipo == "boolean" or tipo == "Vector2" or tipo == "Color3" then
		return true
	elseif tipo == "Vector3" then
		if not (esFinito(valor.X) and esFinito(valor.Y) and esFinito(valor.Z)) then
			return false, nombreRuta(ruta) .. " tiene componentes no finitas"
		end
		return true
	elseif tipo == "table" then
		return comprobarTablaLibre(valor, ruta, ctx, profundidad)
	end
	return false, string.format("%s tiene un tipo no permitido (%s)", nombreRuta(ruta), tipo)
end

-- Tabla libre: claves string cortas o enteros; valores libres; tamaño y profundidad acotados.
function comprobarTablaLibre(valor, ruta, ctx, profundidad)
	if profundidad > Validate.ProfundidadMax then
		return false, nombreRuta(ruta) .. " está anidado en exceso"
	end
	for clave, v in pairs(valor) do
		ctx.claves = ctx.claves + 1
		if ctx.claves > Validate.ClavesMax then
			return false, "demasiados datos en la petición"
		end
		local tipoClave = typeof(clave)
		if tipoClave == "string" then
			if #clave > Validate.ClaveMaxCaracteres then
				return false, nombreRuta(ruta) .. " tiene una clave demasiado larga"
			end
		elseif tipoClave == "number" then
			if not esEntero(clave) then
				return false, nombreRuta(ruta) .. " tiene una clave numérica no entera"
			end
		else
			return false, nombreRuta(ruta) .. " tiene una clave de tipo no permitido (" .. tipoClave .. ")"
		end
		local ok, err = comprobarValorLibre(v, unirRuta(ruta, clave), ctx, profundidad + 1)
		if not ok then
			return false, err
		end
	end
	return true
end

-- Tabla con campos declarados.
local function comprobarCampos(campos, estricto, valor, ruta, ctx, profundidad)
	if profundidad > Validate.ProfundidadMax then
		return false, nombreRuta(ruta) .. " está anidado en exceso"
	end
	for nombre, descriptor in pairs(campos) do
		ctx.claves = ctx.claves + 1
		if ctx.claves > Validate.ClavesMax then
			return false, "demasiados datos en la petición"
		end
		local ok, err = comprobarDescriptor(descriptor, valor[nombre], unirRuta(ruta, nombre), ctx, profundidad)
		if not ok then
			return false, err
		end
	end
	local total = 0
	for clave in pairs(valor) do
		total = total + 1
		if total > Validate.ClavesMax then
			return false, "demasiados datos en la petición"
		end
		if estricto and (typeof(clave) ~= "string" or campos[clave] == nil) then
			return false, string.format("%s tiene una clave desconocida (%s)", nombreRuta(ruta), claveSegura(clave))
		end
	end
	return true
end

-- Comprueba un valor contra un descriptor de campo.
function comprobarDescriptor(descriptor, valor, ruta, ctx, profundidad)
	if typeof(descriptor) ~= "table" or typeof(descriptor.tipo) ~= "string" then
		return false, "esquema inválido en " .. nombreRuta(ruta)
	end
	if valor == nil then
		if descriptor.opcional then
			return true
		end
		return false, nombreRuta(ruta) .. " es obligatorio"
	end
	local tipo = descriptor.tipo

	if tipo == "string" then
		if typeof(valor) ~= "string" then
			return false, nombreRuta(ruta) .. " debe ser texto"
		end
		local n = utf8.len(valor)
		if not n then
			return false, nombreRuta(ruta) .. " contiene caracteres inválidos"
		end
		local min = descriptor.min or 0
		local max = descriptor.max or Validate.TextoLibreMax
		if n < min then
			return false, string.format("%s debe tener al menos %d caracteres", nombreRuta(ruta), min)
		end
		if n > max then
			return false, string.format("%s supera los %d caracteres", nombreRuta(ruta), max)
		end
		if descriptor.sinSaltos and string.find(valor, "\n", 1, true) then
			return false, nombreRuta(ruta) .. " no admite saltos de línea"
		end
		if descriptor.patron and not string.match(valor, descriptor.patron) then
			return false, nombreRuta(ruta) .. " tiene un formato inválido"
		end
		if descriptor.enum and not enLista(descriptor.enum, valor) then
			return false, string.format("%s debe ser uno de: %s", nombreRuta(ruta), listarValores(descriptor.enum))
		end
		return true

	elseif tipo == "number" then
		if typeof(valor) ~= "number" or not esFinito(valor) then
			return false, nombreRuta(ruta) .. " debe ser un número"
		end
		if descriptor.entero and math.floor(valor) ~= valor then
			return false, nombreRuta(ruta) .. " debe ser un número entero"
		end
		if descriptor.min ~= nil and valor < descriptor.min then
			return false, string.format("%s debe ser mayor o igual que %s", nombreRuta(ruta), tostring(descriptor.min))
		end
		if descriptor.max ~= nil and valor > descriptor.max then
			return false, string.format("%s debe ser menor o igual que %s", nombreRuta(ruta), tostring(descriptor.max))
		end
		return true

	elseif tipo == "boolean" then
		if typeof(valor) ~= "boolean" then
			return false, nombreRuta(ruta) .. " debe ser verdadero o falso"
		end
		return true

	elseif tipo == "enum" then
		local valores = descriptor.valores or descriptor.enum
		if typeof(valores) ~= "table" then
			return false, "esquema inválido (enum sin valores) en " .. nombreRuta(ruta)
		end
		local tv = typeof(valor)
		if tv ~= "string" and tv ~= "number" then
			return false, nombreRuta(ruta) .. " debe ser texto o número"
		end
		if not enLista(valores, valor) then
			return false, string.format("%s debe ser uno de: %s", nombreRuta(ruta), listarValores(valores))
		end
		return true

	elseif tipo == "Vector3" then
		if typeof(valor) ~= "Vector3" then
			return false, nombreRuta(ruta) .. " debe ser un Vector3"
		end
		if not (esFinito(valor.X) and esFinito(valor.Y) and esFinito(valor.Z)) then
			return false, nombreRuta(ruta) .. " tiene componentes no finitas"
		end
		if descriptor.magnitud ~= nil and valor.Magnitude > descriptor.magnitud + Validate.ToleranciaMagnitud then
			return false, string.format("%s supera la magnitud máxima (%s)", nombreRuta(ruta), tostring(descriptor.magnitud))
		end
		return true

	elseif tipo == "table" then
		if typeof(valor) ~= "table" then
			return false, nombreRuta(ruta) .. " debe ser una tabla"
		end
		if descriptor.libre or descriptor.campos == nil then
			return comprobarTablaLibre(valor, ruta, ctx, profundidad + 1)
		end
		local campos = descriptor.campos
		local estricto = descriptor.estricto
		if campos.__esquema then
			if estricto == nil then
				estricto = campos.estricto
			end
			campos = campos.campos
		end
		if estricto == nil then
			estricto = true
		end
		return comprobarCampos(campos, estricto, valor, ruta, ctx, profundidad + 1)

	elseif tipo == "array" then
		if typeof(valor) ~= "table" then
			return false, nombreRuta(ruta) .. " debe ser una lista"
		end
		if profundidad + 1 > Validate.ProfundidadMax then
			return false, nombreRuta(ruta) .. " está anidado en exceso"
		end
		local n = #valor
		local total = 0
		for _ in pairs(valor) do
			total = total + 1
			if total > Validate.ClavesMax then
				return false, "demasiados datos en la petición"
			end
		end
		if total ~= n then
			return false, nombreRuta(ruta) .. " no es una lista continua"
		end
		local maxItems = descriptor.maxItems or Validate.ArrayLibreMax
		if n > maxItems then
			return false, string.format("%s supera los %d elementos", nombreRuta(ruta), maxItems)
		end
		if descriptor.minItems ~= nil and n < descriptor.minItems then
			return false, string.format("%s debe tener al menos %d elementos", nombreRuta(ruta), descriptor.minItems)
		end
		ctx.claves = ctx.claves + n
		if ctx.claves > Validate.ClavesMax then
			return false, "demasiados datos en la petición"
		end
		for i = 1, n do
			local rutaElemento = nombreRuta(ruta) .. "[" .. i .. "]"
			local ok, err
			if descriptor.de then
				ok, err = comprobarDescriptor(descriptor.de, valor[i], rutaElemento, ctx, profundidad + 1)
			else
				ok, err = comprobarValorLibre(valor[i], rutaElemento, ctx, profundidad + 1)
			end
			if not ok then
				return false, err
			end
		end
		return true

	elseif tipo == "any" then
		return comprobarValorLibre(valor, ruta, ctx, profundidad + 1)
	end

	return false, string.format("esquema inválido (tipo %s) en %s", tostring(tipo), nombreRuta(ruta))
end

---------------------------------------------------------------------------------------------------
-- API pública
---------------------------------------------------------------------------------------------------

-- Construye un esquema a partir de una tabla { campo = descriptor }.
-- opciones.estricto = false permite claves no declaradas (por defecto se rechazan).
function Validate.Esquema(campos, opciones)
	assert(typeof(campos) == "table", "Validate.Esquema: campos debe ser una tabla")
	for nombre, descriptor in pairs(campos) do
		assert(typeof(nombre) == "string", "Validate.Esquema: los nombres de campo deben ser texto")
		assert(typeof(descriptor) == "table" and typeof(descriptor.tipo) == "string",
			"Validate.Esquema: descriptor inválido en el campo '" .. tostring(nombre) .. "'")
	end
	local estricto = true
	if typeof(opciones) == "table" and opciones.estricto == false then
		estricto = false
	end
	return { __esquema = true, campos = campos, estricto = estricto }
end

-- Comprueba si un valor es un esquema creado con Validate.Esquema.
function Validate.EsEsquema(valor)
	return typeof(valor) == "table" and valor.__esquema == true and typeof(valor.campos) == "table"
end

-- Comprueba una tabla contra un esquema. Devuelve ok (bool) y, si falla, un mensaje en español.
function Validate.Comprobar(esquema, valor)
	if typeof(esquema) ~= "table" then
		return false, "esquema inválido"
	end
	if typeof(valor) ~= "table" then
		return false, "los datos deben ser una tabla"
	end
	local campos, estricto = esquema, true
	if esquema.__esquema then
		campos = esquema.campos
		estricto = esquema.estricto
	end
	local ctx = { claves = 0 }
	local ok, err = comprobarCampos(campos, estricto, valor, "", ctx, 1)
	if not ok then
		return false, err
	end
	return true, nil
end

-- Comprueba un único valor contra un descriptor de campo (p. ej. Validate.Str(40)).
function Validate.ComprobarValor(descriptor, valor, nombre)
	local ctx = { claves = 0 }
	return comprobarDescriptor(descriptor, valor, nombre or "valor", ctx, 1)
end

-- Atajo: ¿es un texto válido (UTF-8) con longitud entre min y max?
function Validate.TextoOk(texto, max, min)
	local ok = comprobarDescriptor({ tipo = "string", max = max, min = min }, texto, "texto", { claves = 0 }, 1)
	return ok == true
end

Validate.EsFinito = esFinito
Validate.EsEntero = esEntero

---------------------------------------------------------------------------------------------------
-- Atajos para construir descriptores (notación de docs/ARQUITECTURA.md §5)
---------------------------------------------------------------------------------------------------
function Validate.Str(max, opcional, min)
	return { tipo = "string", max = max, min = min, opcional = opcional == true }
end

function Validate.Int(min, max, opcional)
	return { tipo = "number", entero = true, min = min, max = max, opcional = opcional == true }
end

function Validate.Num(min, max, opcional)
	return { tipo = "number", min = min, max = max, opcional = opcional == true }
end

function Validate.Bool(opcional)
	return { tipo = "boolean", opcional = opcional == true }
end

function Validate.Enum(valores, opcional)
	assert(typeof(valores) == "table" and #valores > 0, "Validate.Enum: lista de valores vacía")
	return { tipo = "enum", valores = valores, opcional = opcional == true }
end

function Validate.V3(magnitud, opcional)
	return { tipo = "Vector3", magnitud = magnitud, opcional = opcional == true }
end

function Validate.Tabla(campos, opcional, estricto)
	assert(typeof(campos) == "table", "Validate.Tabla: campos debe ser una tabla")
	return { tipo = "table", campos = campos, estricto = estricto ~= false, opcional = opcional == true }
end

function Validate.TablaLibre(opcional)
	return { tipo = "table", libre = true, opcional = opcional == true }
end

function Validate.Array(de, maxItems, opcional)
	return { tipo = "array", de = de, maxItems = maxItems, opcional = opcional == true }
end

function Validate.Cualquiera(opcional)
	return { tipo = "any", opcional = opcional == true }
end

return Validate
]=] }
FUENTES["ReplicatedStorage/ColegioRP/Shared/Util/Zones"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ReplicatedStorage.ColegioRP.Shared.Util.Zones
	Tipo: ModuleScript
	Consultas geométricas sobre MapaLogico (zonas como cajas alineadas a los ejes: Centro ± Tamano/2).
	Funciona en cliente y servidor; no crea instancias. ZonaDe(posicion) prioriza la zona más pequeña
	cuando varias contienen el punto (p. ej. un aula dentro de un patio amplio).
]]

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RP = ReplicatedStorage:WaitForChild("ColegioRP")
local Shared = RP:WaitForChild("Shared")
local MapaLogico = require(Shared:WaitForChild("MapaLogico"))

local Zones = {}

-- Margen (studs) añadido a cada lado de la caja al comprobar pertenencia. 0 = caja exacta.
Zones.Margen = 0

---------------------------------------------------------------------------------------------------
-- Preparación: lista de zonas ordenadas por volumen ascendente (para ZonaDe)
---------------------------------------------------------------------------------------------------
local function volumen(zona)
	local t = zona.Tamano
	return t.X * t.Y * t.Z
end

local zonasPorVolumen = {}
for _, id in ipairs(MapaLogico.OrdenZonas) do
	local zona = MapaLogico.Zonas[id]
	if zona and typeof(zona.Centro) == "Vector3" and typeof(zona.Tamano) == "Vector3" then
		table.insert(zonasPorVolumen, zona)
	end
end
table.sort(zonasPorVolumen, function(a, b)
	local va, vb = volumen(a), volumen(b)
	if va == vb then
		return a.Id < b.Id
	end
	return va < vb
end)

local setAulas = {}
for _, id in ipairs(MapaLogico.Aulas) do
	setAulas[id] = true
end

---------------------------------------------------------------------------------------------------
-- Resolución de argumentos
---------------------------------------------------------------------------------------------------

-- Acepta un id de zona (string) o la propia tabla de zona; devuelve la tabla o nil.
function Zones.Zona(zonaOId)
	if typeof(zonaOId) == "string" then
		return MapaLogico.Zonas[zonaOId]
	end
	if typeof(zonaOId) == "table" and typeof(zonaOId.Centro) == "Vector3" and typeof(zonaOId.Tamano) == "Vector3" then
		return zonaOId
	end
	return nil
end

-- Devuelve la definición de una puerta de MapaLogico.Puertas o nil.
function Zones.Puerta(puertaId)
	if typeof(puertaId) ~= "string" then
		return nil
	end
	return MapaLogico.Puertas[puertaId]
end

---------------------------------------------------------------------------------------------------
-- Consultas
---------------------------------------------------------------------------------------------------

-- ¿La posición está dentro de la caja de la zona? (zona = id o tabla; posicion = Vector3)
function Zones.Contiene(zonaOId, posicion)
	local zona = Zones.Zona(zonaOId)
	if not zona or typeof(posicion) ~= "Vector3" then
		return false
	end
	local c, t = zona.Centro, zona.Tamano
	local m = Zones.Margen
	return math.abs(posicion.X - c.X) <= t.X / 2 + m
		and math.abs(posicion.Y - c.Y) <= t.Y / 2 + m
		and math.abs(posicion.Z - c.Z) <= t.Z / 2 + m
end

-- Zona que contiene la posición (la más pequeña si hay varias) o nil si está fuera de todas.
function Zones.ZonaDe(posicion)
	if typeof(posicion) ~= "Vector3" then
		return nil
	end
	for _, zona in ipairs(zonasPorVolumen) do
		if Zones.Contiene(zona, posicion) then
			return zona
		end
	end
	return nil
end

-- Id de la zona que contiene la posición o nil.
function Zones.IdDe(posicion)
	local zona = Zones.ZonaDe(posicion)
	if zona then
		return zona.Id
	end
	return nil
end

-- Todas las zonas que contienen la posición, de menor a mayor volumen.
function Zones.ZonasEn(posicion)
	local lista = {}
	if typeof(posicion) ~= "Vector3" then
		return lista
	end
	for _, zona in ipairs(zonasPorVolumen) do
		if Zones.Contiene(zona, posicion) then
			table.insert(lista, zona)
		end
	end
	return lista
end

-- Zonas de un tipo ("aula", "patio", "oficina", ...) en el orden de MapaLogico.OrdenZonas.
function Zones.ZonasTipo(tipo)
	local lista = {}
	for _, id in ipairs(MapaLogico.OrdenZonas) do
		local zona = MapaLogico.Zonas[id]
		if zona and zona.Tipo == tipo then
			table.insert(lista, zona)
		end
	end
	return lista
end

-- Zonas de un piso (0 planta baja, 1 planta alta).
function Zones.ZonasPiso(piso)
	local lista = {}
	for _, id in ipairs(MapaLogico.OrdenZonas) do
		local zona = MapaLogico.Zonas[id]
		if zona and zona.Piso == piso then
			table.insert(lista, zona)
		end
	end
	return lista
end

-- Distancia (studs) desde la posición hasta la caja de la zona; 0 si está dentro.
function Zones.DistanciaA(zonaOId, posicion)
	local zona = Zones.Zona(zonaOId)
	if not zona or typeof(posicion) ~= "Vector3" then
		return math.huge
	end
	local c, t = zona.Centro, zona.Tamano
	local dx = math.max(math.abs(posicion.X - c.X) - t.X / 2, 0)
	local dy = math.max(math.abs(posicion.Y - c.Y) - t.Y / 2, 0)
	local dz = math.max(math.abs(posicion.Z - c.Z) - t.Z / 2, 0)
	return math.sqrt(dx * dx + dy * dy + dz * dz)
end

-- Distancia horizontal (ignora Y) del punto al centro de la zona.
function Zones.DistanciaAlCentro(zonaOId, posicion)
	local zona = Zones.Zona(zonaOId)
	if not zona or typeof(posicion) ~= "Vector3" then
		return math.huge
	end
	local dx = posicion.X - zona.Centro.X
	local dz = posicion.Z - zona.Centro.Z
	return math.sqrt(dx * dx + dz * dz)
end

-- Zona más cercana a la posición (opcionalmente solo de un tipo). Devuelve zona, distancia.
function Zones.MasCercana(posicion, tipo)
	if typeof(posicion) ~= "Vector3" then
		return nil, math.huge
	end
	local mejor, mejorDist = nil, math.huge
	for _, id in ipairs(MapaLogico.OrdenZonas) do
		local zona = MapaLogico.Zonas[id]
		if zona and (tipo == nil or zona.Tipo == tipo) then
			local d = Zones.DistanciaA(zona, posicion)
			if d < mejorDist then
				mejor, mejorDist = zona, d
			end
		end
	end
	return mejor, mejorDist
end

-- Lista de aulas (tablas de zona) en el orden de MapaLogico.Aulas.
function Zones.Aulas()
	local lista = {}
	for _, id in ipairs(MapaLogico.Aulas) do
		local zona = MapaLogico.Zonas[id]
		if zona then
			table.insert(lista, zona)
		end
	end
	return lista
end

-- ¿El id corresponde a un aula (aula / aula_especial / aula_pc)?
function Zones.EsAula(zonaId)
	return setAulas[zonaId] == true
end

-- Piso (0/1) de una posición según MapaLogico.Pisos; usa la zona si la hay, si no la altura Y.
function Zones.PisoDe(posicion)
	local zona = Zones.ZonaDe(posicion)
	if zona then
		return zona.Piso
	end
	if typeof(posicion) ~= "Vector3" then
		return 0
	end
	local mejor, mejorDif = 0, math.huge
	for piso, info in pairs(MapaLogico.Pisos) do
		local dif = math.abs(posicion.Y - info.SueloY)
		if dif < mejorDif then
			mejor, mejorDif = piso, dif
		end
	end
	return mejor
end

-- Altura Y del suelo de la zona (según su piso) y altura Y recomendada de aparición.
function Zones.AlturasDe(zonaOId)
	local zona = Zones.Zona(zonaOId)
	local info = zona and MapaLogico.Pisos[zona.Piso] or MapaLogico.Pisos[0]
	return info.SueloY, info.SpawnY
end

-- Punto de aparición de la zona: Spawn.Punto si existe; si no, el centro a la altura de spawn del piso.
-- Devuelve Vector3, estado ("confirmado" | "provisional" | "derivado").
function Zones.PuntoSpawn(zonaOId)
	local zona = Zones.Zona(zonaOId)
	if not zona then
		return nil, "inexistente"
	end
	if zona.Spawn and typeof(zona.Spawn.Punto) == "Vector3" then
		return zona.Spawn.Punto, zona.Spawn.Estado or "confirmado"
	end
	local _, spawnY = Zones.AlturasDe(zona)
	return Vector3.new(zona.Centro.X, spawnY, zona.Centro.Z), "derivado"
end

-- Punto aleatorio dentro de la caja de la zona (en el plano del suelo), con margen interior.
function Zones.PuntoAleatorio(zonaOId, margenInterior)
	local zona = Zones.Zona(zonaOId)
	if not zona then
		return nil
	end
	local margen = margenInterior or 2
	local hx = math.max(zona.Tamano.X / 2 - margen, 0)
	local hz = math.max(zona.Tamano.Z / 2 - margen, 0)
	local _, spawnY = Zones.AlturasDe(zona)
	local x = zona.Centro.X + (math.random() * 2 - 1) * hx
	local z = zona.Centro.Z + (math.random() * 2 - 1) * hz
	return Vector3.new(x, spawnY, z)
end

-- Esquinas mínima y máxima de la caja de la zona (Vector3, Vector3).
function Zones.Limites(zonaOId)
	local zona = Zones.Zona(zonaOId)
	if not zona then
		return nil, nil
	end
	local medio = zona.Tamano / 2
	return zona.Centro - medio, zona.Centro + medio
end

-- CFrame del centro de la zona a nivel de suelo (útil para colocar Parts de zona).
function Zones.CFrameSuelo(zonaOId)
	local zona = Zones.Zona(zonaOId)
	if not zona then
		return nil
	end
	local sueloY = Zones.AlturasDe(zona)
	return CFrame.new(zona.Centro.X, sueloY, zona.Centro.Z)
end

-- Número total de zonas conocidas.
function Zones.Cantidad()
	return #zonasPorVolumen
end

return Zones
]=] }
