FUENTES["ServerScriptService/ColegioRP/Services/AnnouncementService"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ServerScriptService.ColegioRP.Services.AnnouncementService
	Tipo: ModuleScript
	Avisos oficiales (docs/ARQUITECTURA.md §6): Anunciar(player|nil, texto, alcance, roomId) filtra el texto
	con TextService, lo limita a Config.Limites.MaxAvisoCaracteres y lo emite por EventoCliente "Aviso"
	{ Texto, Autor, Cargo, T, Alcance } a todo el servidor (Global) o a la zona del aula (Aula). Atiende
	AnnouncementBroadcast (Aula: docente de la sesión abierta) y crea el TextChatCommand /anuncio (alias /h),
	validado en el servidor con anuncios.global y limitado a 1 uso cada 15 s. Guarda los 10 últimos avisos
	globales (Ultimos / Historial) para el snapshot de los clientes que entran después.
]]

local Players = game:GetService("Players")
local TextService = game:GetService("TextService")

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RP = ReplicatedStorage:WaitForChild("ColegioRP")
local Shared = RP:WaitForChild("Shared")
local Config = require(Shared:WaitForChild("Config"))
local RoleDefinitions = require(Shared:WaitForChild("RoleDefinitions"))
local RemoteContracts = require(Shared:WaitForChild("RemoteContracts"))
local Util = Shared:WaitForChild("Util")
local Signal = require(Util:WaitForChild("Signal"))
local Format = require(Util:WaitForChild("Format"))

local AnnouncementService = {}
AnnouncementService.Nombre = "AnnouncementService"

local PREFIJO = "[ColegioRP][AnnouncementService]"
local CHAT = Config.Chat or {}

-- Longitud máxima de un aviso (caracteres).
AnnouncementService.MaxCaracteres = math.max(10, tonumber(Config.Limites and Config.Limites.MaxAvisoCaracteres) or 160)
-- Avisos globales conservados para el snapshot (Ultimos / Historial).
AnnouncementService.MaxHistorial = math.max(1, tonumber(CHAT.HistorialAnuncios) or 10)
-- Avisos de aula conservados por aula (solo se devuelven al pedir Ultimos(roomId)).
AnnouncementService.MaxHistorialAula = 5
-- Segundos mínimos entre usos del comando de chat por el mismo jugador.
AnnouncementService.CooldownComandoSeg = 15
-- Nombre de la instancia TextChatCommand y alias.
AnnouncementService.NombreComando = "ColegioRP_Anuncio"
AnnouncementService.AliasPrincipal = CHAT.ComandoAnuncio or "/anuncio"
AnnouncementService.AliasSecundario = CHAT.AliasAnuncio or "/h"
-- Prefijo de los mensajes de sistema del chat.
AnnouncementService.PrefijoSistema = "[Colegio] "
-- Autor mostrado en los avisos del sistema (Anunciar sin jugador).
AnnouncementService.AutorSistema = Config.NombreCorto or "Colegio"

local ALCANCES = { Global = true, Aula = true }

---------------------------------------------------------------------------------------------------
-- Utilidades
---------------------------------------------------------------------------------------------------
local function esJugador(player)
	return typeof(player) == "Instance" and player:IsA("Player")
end

-- Texto de una línea: UTF-8 válido, sin caracteres de control, sin espacios repetidos. nil si no es válido.
local function limpiar(texto)
	if typeof(texto) ~= "string" or utf8.len(texto) == nil then
		return nil
	end
	local limpio = string.gsub(texto, "%c", " ")
	limpio = string.gsub(limpio, "%s%s+", " ")
	return Format.Recortar(limpio)
end

local function copiaAviso(aviso)
	return {
		Id = aviso.Id, Texto = aviso.Texto, Autor = aviso.Autor, Cargo = aviso.Cargo, T = aviso.T,
		Alcance = aviso.Alcance, RoomId = aviso.RoomId, Oficial = aviso.Oficial,
	}
end

-- Quita el alias del comando al principio del mensaje ("/anuncio Hola" -> "Hola").
local function sinAlias(texto, alias)
	local resultado = texto
	for _, a in ipairs(alias) do
		if typeof(a) == "string" and a ~= "" then
			local n = #a
			if string.lower(string.sub(resultado, 1, n)) == string.lower(a) then
				local siguiente = string.sub(resultado, n + 1, n + 1)
				if siguiente == "" or string.match(siguiente, "%s") then
					return string.sub(resultado, n + 1)
				end
			end
		end
	end
	return resultado
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function AnnouncementService:Init(registro)
	self.registro = registro
	self.Historial = {} -- avisos globales (el más reciente al final)
	self.HistorialAula = {} -- roomId -> avisos de aula
	self.UltimoComando = {} -- userId -> os.clock() del último /anuncio aceptado
	self.Contador = 0
	self.Conexiones = {}
	self.Comando = nil
	self.Anunciado = Signal.new() -- (aviso)
end

function AnnouncementService:Start()
	local RemoteService = self:Servicio("RemoteService")
	if RemoteService and typeof(RemoteService.Registrar) == "function" then
		RemoteService:Registrar("AnnouncementBroadcast", function(player, datos)
			return self:ManejarRemoto(player, datos)
		end)
	else
		warn(PREFIJO .. " RemoteService no disponible: AnnouncementBroadcast no tendrá handler.")
	end

	local ok, err = pcall(function()
		self:CrearComando()
	end)
	if not ok then
		warn(PREFIJO .. " No se pudo crear el comando de chat " .. tostring(self.AliasPrincipal) .. ": " .. tostring(err))
	end

	table.insert(self.Conexiones, Players.PlayerRemoving:Connect(function(player)
		self.UltimoComando[player.UserId] = nil
	end))
end

-- Servicio por nombre a través del registro (nil si no existe).
function AnnouncementService:Servicio(nombre)
	local registro = self.registro
	if registro and typeof(registro.Get) == "function" then
		return registro.Get(nombre)
	end
	return nil
end

-- Llama servicio:metodo(...) en pcall si existe. Devuelve ok, r1, r2.
function AnnouncementService:Llamar(nombreServicio, metodo, ...)
	local servicio = self:Servicio(nombreServicio)
	if not servicio or typeof(servicio[metodo]) ~= "function" then
		return false, nil, nil
	end
	local resultado = table.pack(pcall(servicio[metodo], servicio, ...))
	if not resultado[1] then
		warn(PREFIJO .. " " .. nombreServicio .. ":" .. metodo .. "() falló: " .. tostring(resultado[2]))
		return false, nil, nil
	end
	return true, resultado[2], resultado[3]
end

function AnnouncementService:Auditar(categoria, player, accion, detalle)
	self:Llamar("AuditLogService", "Registrar", categoria, player, accion, detalle)
end

---------------------------------------------------------------------------------------------------
-- Filtrado y difusión
---------------------------------------------------------------------------------------------------

-- Filtra el texto para todo el servidor. Devuelve true, filtrado | false, mensaje (nunca el original).
function AnnouncementService:Filtrar(texto, player)
	local okFiltro, resultado = pcall(function()
		return TextService:FilterStringAsync(texto, player.UserId, Enum.TextFilterContext.PublicChat)
	end)
	if not okFiltro or resultado == nil then
		return false, "No se pudo filtrar el texto. Inténtalo de nuevo en unos segundos."
	end
	local okTexto, filtrado = pcall(function()
		return resultado:GetNonChatStringForBroadcastAsync()
	end)
	if not okTexto or typeof(filtrado) ~= "string" then
		return false, "No se pudo filtrar el texto. Inténtalo de nuevo en unos segundos."
	end
	return true, filtrado
end

-- Id de la zona física de un aula (MapService:Aula(roomId).Zona o, si no, el propio roomId).
function AnnouncementService:ZonaDeAula(roomId)
	local ok, aula = self:Llamar("MapService", "Aula", roomId)
	if ok and typeof(aula) == "table" then
		local zona = aula.Zona
		if typeof(zona) == "table" and typeof(zona.Id) == "string" then
			return zona.Id
		end
		if typeof(zona) == "string" and zona ~= "" then
			return zona
		end
	end
	return roomId
end

-- Envía el aviso de aula a los jugadores de su zona y, además, al emisor si no está dentro.
function AnnouncementService:EnviarAula(roomId, datos, emisor)
	local RemoteService = self:Servicio("RemoteService")
	if not RemoteService then
		return 0
	end
	local zonaId = self:ZonaDeAula(roomId)
	if typeof(RemoteService.JugadoresEnZona) == "function" and typeof(RemoteService.EnviarALista) == "function" then
		local okLista, lista = pcall(RemoteService.JugadoresEnZona, RemoteService, zonaId)
		if okLista and typeof(lista) == "table" then
			local incluido = false
			for _, p in ipairs(lista) do
				if p == emisor then
					incluido = true
				end
			end
			if esJugador(emisor) and not incluido then
				table.insert(lista, emisor)
			end
			local okEnvio, enviados = pcall(RemoteService.EnviarALista, RemoteService, lista, "Aviso", datos)
			if okEnvio and typeof(enviados) == "number" then
				return enviados
			end
			return 0
		end
	end
	local okZona, enviados = self:Llamar("RemoteService", "EnviarAZona", zonaId, "Aviso", datos)
	local total = (okZona and typeof(enviados) == "number") and enviados or 0
	if esJugador(emisor) then
		self:Llamar("RemoteService", "Enviar", emisor, "Aviso", datos)
		total = total + 1
	end
	return total
end

-- Publica un aviso. player nil = aviso del sistema (texto definido por el juego, sin filtrar).
-- alcance: "Global" (por defecto) | "Aula" (requiere roomId). Devuelve true, nil, aviso | false, mensaje.
function AnnouncementService:Anunciar(player, texto, alcance, roomId)
	if player ~= nil and not esJugador(player) then
		return false, "Jugador no válido."
	end
	alcance = alcance or "Global"
	if not ALCANCES[alcance] then
		return false, "Alcance de aviso no válido."
	end
	if alcance == "Aula" and (typeof(roomId) ~= "string" or roomId == "") then
		return false, "Falta el aula del aviso."
	end
	local limpio = limpiar(texto)
	if limpio == nil then
		return false, "El texto del aviso no es válido."
	end
	if limpio == "" then
		return false, "Escribe el texto del aviso."
	end
	if Format.Longitud(limpio) > self.MaxCaracteres then
		limpio = Format.Truncar(limpio, self.MaxCaracteres)
	end

	local final = limpio
	local autor = self.AutorSistema
	local cargo = nil
	if player then
		local okFiltro, filtrado = self:Filtrar(limpio, player)
		if not okFiltro then
			self:Auditar("Sistema", player, "AnuncioRechazado", "filtro no disponible")
			return false, filtrado
		end
		final = filtrado
		if Format.Recortar(final) == "" then
			return false, "El aviso quedó vacío tras el filtrado."
		end
		autor = player.DisplayName ~= "" and player.DisplayName or player.Name
		local okCargo, c = self:Llamar("RoleService", "Cargo", player)
		if okCargo and RoleDefinitions.Existe(c) then
			cargo = c
		end
	end

	self.Contador = self.Contador + 1
	local aviso = {
		Id = self.Contador,
		Texto = final,
		Autor = autor,
		Cargo = cargo,
		T = os.time(),
		Alcance = alcance,
		RoomId = alcance == "Aula" and roomId or nil,
		Oficial = player == nil,
	}
	local datos = copiaAviso(aviso)

	local enviados = 0
	if alcance == "Global" then
		local okTodos, enviado = self:Llamar("RemoteService", "EnviarATodos", "Aviso", datos)
		if okTodos and enviado == true then
			enviados = #Players:GetPlayers()
		end
		table.insert(self.Historial, aviso)
		while #self.Historial > self.MaxHistorial do
			table.remove(self.Historial, 1)
		end
	else
		enviados = self:EnviarAula(roomId, datos, player)
		local lista = self.HistorialAula[roomId]
		if not lista then
			lista = {}
			self.HistorialAula[roomId] = lista
		end
		table.insert(lista, aviso)
		while #lista > self.MaxHistorialAula do
			table.remove(lista, 1)
		end
	end

	local detalle = alcance .. (roomId and alcance == "Aula" and (" " .. roomId) or "") .. " · " .. enviados .. " destinatarios · " .. final
	self:Auditar(alcance == "Aula" and "Clase" or "Sistema", player, "Anuncio", detalle)
	local okSenal, errSenal = pcall(function()
		self.Anunciado:Fire(copiaAviso(aviso))
	end)
	if not okSenal then
		warn(PREFIJO .. " Error en un oyente de Anunciado: " .. tostring(errSenal))
	end
	return true, nil, copiaAviso(aviso)
end

-- Últimos avisos (copias, el más antiguo primero). Sin roomId: solo los globales; con roomId: los de esa aula.
function AnnouncementService:Ultimos(roomId)
	local origen = self.Historial
	if typeof(roomId) == "string" then
		origen = self.HistorialAula[roomId] or {}
	end
	local lista = {}
	for _, aviso in ipairs(origen) do
		table.insert(lista, copiaAviso(aviso))
	end
	return lista
end

-- Alias usado por RemoteService:ConstruirSnapshot y SchoolDayService.
function AnnouncementService:Historial()
	return self:Ultimos()
end

function AnnouncementService:Snapshot()
	return self:Ultimos()
end

---------------------------------------------------------------------------------------------------
-- Comprobaciones comunes (remoto y comando)
---------------------------------------------------------------------------------------------------
function AnnouncementService:EstaSilenciado(player)
	local ok, silenciado = self:Llamar("ModerationService", "EstaSilenciado", player)
	if ok then
		return silenciado == true
	end
	return player:GetAttribute("Silenciado") == true
end

-- Aula de la sesión que dirige el jugador (ClassroomService). Devuelve roomId | nil, mensaje.
function AnnouncementService:AulaDelDocente(player)
	local ClassroomService = self:Servicio("ClassroomService")
	if not ClassroomService or typeof(ClassroomService.SesionDeJugador) ~= "function" then
		return nil, "Las sesiones de clase no están disponibles; no se puede enviar un aviso al aula."
	end
	local ok, sesion = pcall(ClassroomService.SesionDeJugador, ClassroomService, player)
	if not ok or typeof(sesion) ~= "table" or typeof(sesion.RoomId) ~= "string" then
		return nil, "Para enviar un aviso al aula debes tener una sesión de clase abierta."
	end
	local esDocente = sesion.TeacherUserId == player.UserId
	if typeof(ClassroomService.EsDocenteDe) == "function" then
		local okDocente, resultado = pcall(ClassroomService.EsDocenteDe, ClassroomService, player, sesion.RoomId)
		if okDocente then
			esDocente = resultado == true
		end
	end
	if not esDocente then
		return nil, "Solo el docente que dirige la sesión puede enviar avisos a esta aula."
	end
	return sesion.RoomId
end

---------------------------------------------------------------------------------------------------
-- Handler de AnnouncementBroadcast (RemoteService ya validó esquema, límite 2/30 s y permiso:
-- anuncios.global para Global, anuncios.aula para Aula)
---------------------------------------------------------------------------------------------------
function AnnouncementService:ManejarRemoto(player, datos)
	if self:EstaSilenciado(player) then
		self:Auditar("Moderacion", player, "AnuncioRechazado", "jugador silenciado")
		return RemoteContracts.Error("Estás silenciado/a: no puedes publicar avisos.")
	end
	local alcance = datos.Alcance
	local roomId = nil
	if alcance == "Aula" then
		local aula, err = self:AulaDelDocente(player)
		if not aula then
			self:Auditar("Clase", player, "AnuncioRechazado", "Aula: " .. tostring(err))
			return RemoteContracts.Error(err)
		end
		roomId = aula
	elseif alcance ~= "Global" then
		return RemoteContracts.Error("Alcance de aviso no válido.")
	end
	local ok, err, aviso = self:Anunciar(player, datos.Texto, alcance, roomId)
	if not ok then
		return RemoteContracts.Error(err)
	end
	return RemoteContracts.Ok({
		Anuncio = aviso,
		Texto = aviso.Texto,
		Alcance = alcance,
		RoomId = roomId,
		Mensaje = alcance == "Aula" and ("Aviso enviado al aula " .. roomId .. ".") or "Anuncio enviado a todo el colegio.",
	})
end

---------------------------------------------------------------------------------------------------
-- Comando de chat /anuncio (TextChatService)
---------------------------------------------------------------------------------------------------
function AnnouncementService:CrearComando()
	local okServicio, tcs = pcall(game.GetService, game, "TextChatService")
	if not okServicio or not tcs then
		warn(PREFIJO .. " TextChatService no disponible: se omite el comando " .. tostring(self.AliasPrincipal) .. ".")
		return
	end
	local okVersion, version = pcall(function()
		return tcs.ChatVersion
	end)
	if not okVersion or version ~= Enum.ChatVersion.TextChatService then
		warn(PREFIJO .. " El lugar no usa TextChatService (ChatVersion = " .. tostring(version)
			.. "): se omite el comando " .. tostring(self.AliasPrincipal) .. ". Usa el panel de dirección para anunciar.")
		return
	end
	self.TextChatService = tcs

	-- Idempotente: se reutiliza el comando si ya existe (reinicio de servicios o instalación repetida).
	local comando = nil
	for _, d in ipairs(tcs:GetDescendants()) do
		if d:IsA("TextChatCommand") and d.Name == self.NombreComando then
			comando = d
		end
	end
	if not comando then
		comando = Instance.new("TextChatCommand")
		comando.Name = self.NombreComando
	end
	comando.PrimaryAlias = self.AliasPrincipal
	comando.SecondaryAlias = self.AliasSecundario
	local carpeta = tcs:FindFirstChild("TextChatCommands")
	if carpeta then
		comando.Parent = carpeta
	else
		comando.Parent = tcs
	end
	self.Comando = comando
	table.insert(self.Conexiones, comando.Triggered:Connect(function(fuente, mensaje)
		task.spawn(function()
			local ok, err = pcall(function()
				self:AlComando(fuente, mensaje)
			end)
			if not ok then
				warn(PREFIJO .. " Error en el comando " .. tostring(self.AliasPrincipal) .. ": " .. tostring(err))
			end
		end)
	end))
end

-- Respuesta privada al emisor del comando: mensaje de sistema del chat o, si no es posible desde el
-- servidor, notificación del HUD.
function AnnouncementService:ResponderChat(player, fuente, texto, nivel)
	local mostrado = false
	local canal = fuente and fuente.Parent
	if typeof(canal) == "Instance" and canal:IsA("TextChannel") then
		local ok = pcall(function()
			canal:DisplaySystemMessage(self.PrefijoSistema .. texto)
		end)
		mostrado = ok
	end
	if not mostrado then
		self:Llamar("RemoteService", "Enviar", player, "Notificacion", {
			Titulo = "Anuncios", Texto = texto, Nivel = nivel or "info", Tipo = nivel or "info",
		})
	end
end

function AnnouncementService:AlComando(fuente, mensaje)
	if typeof(fuente) ~= "Instance" or not fuente:IsA("TextSource") then
		return
	end
	local player = Players:GetPlayerByUserId(fuente.UserId)
	if not player then
		return
	end
	local okTiene, tiene = self:Llamar("RoleService", "Tiene", player, "anuncios.global")
	if not okTiene or tiene ~= true then
		self:Auditar("Remoto", player, "ComandoAnuncio", "rechazado: sin permiso anuncios.global")
		self:ResponderChat(player, fuente, "No tienes permiso para enviar anuncios.", "error")
		return
	end
	if self:EstaSilenciado(player) then
		self:Auditar("Moderacion", player, "AnuncioRechazado", "jugador silenciado (comando)")
		self:ResponderChat(player, fuente, "Estás silenciado/a: no puedes publicar anuncios.", "error")
		return
	end
	local userId = player.UserId
	local ultimo = self.UltimoComando[userId]
	if ultimo and os.clock() - ultimo < self.CooldownComandoSeg then
		local espera = math.ceil(self.CooldownComandoSeg - (os.clock() - ultimo))
		self:ResponderChat(player, fuente, "Espera " .. espera .. " s antes de enviar otro anuncio.", "aviso")
		return
	end
	local texto = typeof(mensaje) == "string" and mensaje or ""
	texto = sinAlias(Format.Recortar(texto), { self.AliasPrincipal, self.AliasSecundario })
	texto = limpiar(texto)
	if texto == nil then
		self:ResponderChat(player, fuente, "El texto del anuncio no es válido.", "error")
		return
	end
	if texto == "" then
		self:ResponderChat(player, fuente, "Uso: " .. tostring(self.AliasPrincipal) .. " <mensaje>", "info")
		return
	end
	if Format.Longitud(texto) > self.MaxCaracteres then
		self:ResponderChat(player, fuente, "El anuncio admite como máximo " .. self.MaxCaracteres .. " caracteres.", "aviso")
		return
	end
	self.UltimoComando[userId] = os.clock()
	local ok, err = self:Anunciar(player, texto, "Global", nil)
	if not ok then
		self:ResponderChat(player, fuente, tostring(err), "error")
		return
	end
	self:ResponderChat(player, fuente, "Anuncio enviado a todo el colegio.", "exito")
end

return AnnouncementService
]=] }
FUENTES["ServerScriptService/ColegioRP/Services/AuditLogService"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ServerScriptService.ColegioRP.Services.AuditLogService
	Tipo: ModuleScript
	Registro de auditoría del servidor: buffer circular (Config.Auditoria.TamanoBuffer) con entradas
	{ Id, T, Categoria, UserId, Jugador, Accion, Detalle }. Categorías: Remoto, Cargo, Moderacion,
	Economia, Clase, Sistema. Otros servicios lo consultan con Listar(n) y se suscriben a Registrado.
]]

local Players = game:GetService("Players")

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RP = ReplicatedStorage:WaitForChild("ColegioRP")
local Shared = RP:WaitForChild("Shared")
local Config = require(Shared:WaitForChild("Config"))
local Signal = require(Shared:WaitForChild("Util"):WaitForChild("Signal"))

local AuditLogService = {}
AuditLogService.Nombre = "AuditLogService"

-- Categorías conocidas (docs/ARQUITECTURA.md §6). Una categoría desconocida se guarda como "Sistema".
AuditLogService.Categorias = { "Remoto", "Cargo", "Moderacion", "Economia", "Clase", "Sistema" }
-- Categorías que además se imprimen en la salida del servidor (las demás solo se guardan).
AuditLogService.CategoriasImpresas = { Sistema = true, Moderacion = true, Cargo = true }
-- Longitud máxima del detalle guardado.
AuditLogService.MaxDetalleCaracteres = 400

local setCategorias = {}
for _, categoria in ipairs(AuditLogService.Categorias) do
	setCategorias[categoria] = true
end

---------------------------------------------------------------------------------------------------
-- Utilidades
---------------------------------------------------------------------------------------------------

-- Convierte cualquier valor en un texto corto y seguro para el registro.
local function aTexto(valor, profundidad)
	local tipo = typeof(valor)
	if valor == nil then
		return ""
	elseif tipo == "string" then
		return valor
	elseif tipo == "number" or tipo == "boolean" then
		return tostring(valor)
	elseif tipo == "Instance" then
		return valor:GetFullName()
	elseif tipo == "table" then
		if (profundidad or 0) >= 2 then
			return "{...}"
		end
		local partes = {}
		local n = 0
		for clave, v in pairs(valor) do
			n = n + 1
			if n > 12 then
				table.insert(partes, "...")
				break
			end
			table.insert(partes, tostring(clave) .. "=" .. aTexto(v, (profundidad or 0) + 1))
		end
		return "{" .. table.concat(partes, ", ") .. "}"
	end
	return tostring(valor)
end

local function recortar(texto, max)
	if typeof(texto) ~= "string" then
		return ""
	end
	texto = string.gsub(texto, "[\r\n]+", " ")
	local n = utf8.len(texto)
	if n == nil then
		return string.sub(texto, 1, max)
	end
	if n <= max then
		return texto
	end
	local corte = utf8.offset(texto, max + 1)
	if corte == nil then
		return texto
	end
	return string.sub(texto, 1, corte - 1) .. "…"
end

-- Resuelve el jugador (Player, userId o nil) a UserId y nombre.
local function resolverJugador(player)
	if typeof(player) == "Instance" and player:IsA("Player") then
		return player.UserId, player.Name
	elseif typeof(player) == "number" then
		local instancia = Players:GetPlayerByUserId(player)
		if instancia then
			return player, instancia.Name
		end
		return player, tostring(player)
	end
	return nil, nil
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function AuditLogService:Init(registro)
	self.registro = registro
	self.Tamano = math.max(10, (Config.Auditoria and Config.Auditoria.TamanoBuffer) or 500)
	self.Buffer = table.create(self.Tamano)
	self.Indice = 0 -- posición del último escrito (1..Tamano); 0 = vacío
	self.Total = 0 -- entradas registradas desde el arranque (también sirve de Id)
	self.PorCategoria = {}
	for _, categoria in ipairs(self.Categorias) do
		self.PorCategoria[categoria] = 0
	end
	self.Registrado = Signal.new()
	self.InicioClock = os.clock()
end

function AuditLogService:Start()
	self:Registrar("Sistema", nil, "Arranque", "AuditLogService activo · buffer de " .. self.Tamano .. " entradas")
end

---------------------------------------------------------------------------------------------------
-- Registro
---------------------------------------------------------------------------------------------------

-- Registra una entrada. categoria: string; player: Player | userId | nil; accion: string; detalle: cualquier valor.
-- Devuelve la entrada creada.
function AuditLogService:Registrar(categoria, player, accion, detalle)
	if typeof(categoria) ~= "string" or not setCategorias[categoria] then
		detalle = "[" .. tostring(categoria) .. "] " .. aTexto(detalle)
		categoria = "Sistema"
	end
	local userId, nombre = resolverJugador(player)
	self.Total = self.Total + 1
	local entrada = {
		Id = self.Total,
		T = os.time(),
		Reloj = os.clock() - self.InicioClock,
		Categoria = categoria,
		UserId = userId,
		Jugador = nombre,
		Accion = recortar(aTexto(accion), 64),
		Detalle = recortar(aTexto(detalle), self.MaxDetalleCaracteres),
	}

	self.Indice = self.Indice + 1
	if self.Indice > self.Tamano then
		self.Indice = 1
	end
	self.Buffer[self.Indice] = entrada
	self.PorCategoria[categoria] = (self.PorCategoria[categoria] or 0) + 1

	if self.CategoriasImpresas[categoria] then
		print("[ColegioRP][Auditoría] " .. self:Formatear(entrada))
	end

	self.Registrado:Fire(entrada)
	return entrada
end

-- Formatea una entrada en una línea legible.
function AuditLogService:Formatear(entrada)
	if typeof(entrada) ~= "table" then
		return ""
	end
	local okFecha, fecha = pcall(os.date, "%H:%M:%S", entrada.T or 0)
	if not okFecha then
		fecha = tostring(entrada.T)
	end
	local quien = ""
	if entrada.Jugador then
		quien = " " .. tostring(entrada.Jugador) .. "(" .. tostring(entrada.UserId) .. ")"
	end
	local detalle = ""
	if entrada.Detalle and entrada.Detalle ~= "" then
		detalle = " · " .. entrada.Detalle
	end
	return string.format("%s [%s]%s %s%s", fecha, tostring(entrada.Categoria), quien, tostring(entrada.Accion), detalle)
end

---------------------------------------------------------------------------------------------------
-- Consultas
---------------------------------------------------------------------------------------------------

-- Devuelve las últimas n entradas (la más reciente primero). filtro opcional: { Categoria, UserId, Accion }.
function AuditLogService:Listar(n, filtro)
	n = math.max(1, math.min(tonumber(n) or 50, self.Tamano))
	local resultado = {}
	local disponibles = math.min(self.Total, self.Tamano)
	local posicion = self.Indice
	local revisadas = 0
	while revisadas < disponibles and #resultado < n do
		local entrada = self.Buffer[posicion]
		if entrada then
			local pasa = true
			if typeof(filtro) == "table" then
				if filtro.Categoria ~= nil and entrada.Categoria ~= filtro.Categoria then
					pasa = false
				end
				if filtro.UserId ~= nil and entrada.UserId ~= filtro.UserId then
					pasa = false
				end
				if filtro.Accion ~= nil and entrada.Accion ~= filtro.Accion then
					pasa = false
				end
			end
			if pasa then
				table.insert(resultado, entrada)
			end
		end
		revisadas = revisadas + 1
		posicion = posicion - 1
		if posicion < 1 then
			posicion = self.Tamano
		end
	end
	return resultado
end

-- Últimas n entradas de una categoría.
function AuditLogService:ListarCategoria(categoria, n)
	return self:Listar(n, { Categoria = categoria })
end

-- Últimas n entradas de un jugador (Player o userId).
function AuditLogService:ListarJugador(player, n)
	local userId = resolverJugador(player)
	if not userId then
		return {}
	end
	return self:Listar(n, { UserId = userId })
end

-- Número total de entradas registradas desde el arranque.
function AuditLogService:Contar()
	return self.Total
end

-- Entradas actualmente guardadas en el buffer.
function AuditLogService:EnBuffer()
	return math.min(self.Total, self.Tamano)
end

-- Copia de los contadores por categoría.
function AuditLogService:Contadores()
	local copia = {}
	for categoria, cantidad in pairs(self.PorCategoria) do
		copia[categoria] = cantidad
	end
	copia.Total = self.Total
	return copia
end

-- Versión plana y segura de las últimas n entradas para enviar a un panel de cliente.
function AuditLogService:ParaCliente(n, filtro)
	local lista = {}
	for _, entrada in ipairs(self:Listar(n, filtro)) do
		table.insert(lista, {
			Id = entrada.Id,
			T = entrada.T,
			Categoria = entrada.Categoria,
			UserId = entrada.UserId,
			Jugador = entrada.Jugador,
			Accion = entrada.Accion,
			Detalle = entrada.Detalle,
		})
	end
	return lista
end

-- Texto multilínea con las últimas n entradas (para la salida del servidor).
function AuditLogService:Exportar(n, filtro)
	local lineas = {}
	for _, entrada in ipairs(self:Listar(n, filtro)) do
		table.insert(lineas, self:Formatear(entrada))
	end
	return table.concat(lineas, "\n")
end

-- Vacía el buffer (los contadores totales se conservan).
function AuditLogService:Limpiar()
	self.Buffer = table.create(self.Tamano)
	self.Indice = 0
	self:Registrar("Sistema", nil, "Limpiar", "Buffer de auditoría vaciado")
end

return AuditLogService
]=] }
FUENTES["ServerScriptService/ColegioRP/Services/BathroomService"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ServerScriptService.ColegioRP.Services.BathroomService
	Tipo: ModuleScript
	Interacciones de baño (docs/ARQUITECTURA.md §6): para cada zona de tipo "banos" de MapaLogico y sus Objetos
	(Inodoros, Urinarios, Lavamanos: puntos) busca la BasePart real más cercana (<= 3 studs, sin Seats ni piezas de
	Workspace.ColegioRP_Mapa) y añade un ProximityPrompt (RPTipo = "Bano", RPId = ObjetoId, RPAccion = "LavarManos"
	| "Usar", HoldDuration 0.5) en un Attachment propio situado en el punto lógico. Acciones con cooldown de 20 s
	por objeto y 10 s por jugador; "Usar" reproduce el Sound original de "Workspace/Bathroom Toilet/Handle/Sound"
	más cercano (<= 6 studs) sin modificarlo; mensajes neutros ("Te lavas las manos", "Listo"); recompensa 0.
	Remoto BathroomAction { ObjetoId, Accion } (distancia <= 10; "Limpiar" requiere limpieza.tareas).
]]

local Players = game:GetService("Players")
local CollectionService = game:GetService("CollectionService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local RP = ReplicatedStorage:WaitForChild("ColegioRP")
local Shared = RP:WaitForChild("Shared")
local Config = require(Shared:WaitForChild("Config"))
local MapaLogico = require(Shared:WaitForChild("MapaLogico"))
local Util = Shared:WaitForChild("Util")
local Zones = require(Util:WaitForChild("Zones"))
local Signal = require(Util:WaitForChild("Signal"))

local BathroomService = {}
BathroomService.Nombre = "BathroomService"

local PREFIJO = "[ColegioRP][BathroomService]"
local DISTANCIA_MAX = (Config.Distancias and tonumber(Config.Distancias.Bano)) or 10
local TAG_BANO = (Config.Tags and Config.Tags.Bano) or "ColegioRP_Bano"
local NOMBRE_CARPETA_MAPA = (Config.Nombres and Config.Nombres.CarpetaMapa) or "ColegioRP_Mapa"

---------------------------------------------------------------------------------------------------
-- Parámetros
---------------------------------------------------------------------------------------------------
BathroomService.RadioBusqueda = 3 -- Distancia máxima punto lógico -> BasePart real.
BathroomService.CooldownObjetoSeg = 20 -- Un mismo objeto no se puede volver a usar antes de esto.
BathroomService.CooldownJugadorSeg = 10 -- Un jugador no puede usar otro objeto antes de esto.
BathroomService.CooldownLimpiezaSeg = 15 -- Entre dos limpiezas del mismo objeto.
BathroomService.DistanciaSonido = 6 -- Sonido de cisterna más cercano admitido.
BathroomService.DistanciaPrompt = 6 -- MaxActivationDistance de los prompts.
BathroomService.HoldDuration = 0.5
BathroomService.ToleranciaDistancia = 2
BathroomService.TamanoMaxPieza = 12 -- Piezas con alguna dimensión mayor (suelos, muros) no se toman como objeto.
BathroomService.BonusNombre = 1.5 -- Studs de ventaja para piezas cuyo nombre coincide con el tipo de objeto.
BathroomService.IntervaloAuditoriaSeg = 10

-- Tipos de objeto: clave en Zona.Objetos -> definición.
local TIPOS = {
	{ Clave = "Inodoros", Tipo = "Inodoro", Accion = "Usar", ActionText = "Usar", ObjectText = "Inodoro",
		Palabras = { "toilet", "inodoro", "sanitario", "bowl", "tank", "taza" } },
	{ Clave = "Urinarios", Tipo = "Urinario", Accion = "Usar", ActionText = "Usar", ObjectText = "Urinario",
		Palabras = { "urinario", "urinal", "orinal" } },
	{ Clave = "Lavamanos", Tipo = "Lavamanos", Accion = "LavarManos", ActionText = "Lavar manos", ObjectText = "Lavamanos",
		Palabras = { "lavamanos", "lavabo", "sink", "grifo", "llave", "faucet", "lavaman" } },
}

local MENSAJES = {
	LavarManos = "Te lavas las manos",
	Usar = "Listo",
	Limpiar = "Dejas el lugar limpio",
}

local MOTIVOS_AUDITADOS = { objeto_inexistente = true, accion_invalida = true, distancia = true, permiso = true }

---------------------------------------------------------------------------------------------------
-- Utilidades
---------------------------------------------------------------------------------------------------
local function esJugador(valor)
	return typeof(valor) == "Instance" and valor:IsA("Player")
end

local function posicionJugador(player)
	local personaje = player and player.Character
	if not personaje then
		return nil
	end
	local raiz = personaje:FindFirstChild("HumanoidRootPart")
	if raiz and raiz:IsA("BasePart") then
		return raiz.Position
	end
	return nil
end

-- Distancia de un punto a la caja orientada de una BasePart (0 si está dentro).
local function distanciaAParte(parte, punto)
	local rel = parte.CFrame:PointToObjectSpace(punto)
	local s = parte.Size
	local dx = math.max(math.abs(rel.X) - s.X / 2, 0)
	local dy = math.max(math.abs(rel.Y) - s.Y / 2, 0)
	local dz = math.max(math.abs(rel.Z) - s.Z / 2, 0)
	return math.sqrt(dx * dx + dy * dy + dz * dz)
end

-- ¿El nombre de la pieza o de sus dos primeros ancestros contiene alguna palabra clave?
local function coincideNombre(parte, palabras)
	local actual = parte
	for _ = 1, 3 do
		if not actual or actual == workspace then
			return false
		end
		local nombre = string.lower(actual.Name)
		for _, palabra in ipairs(palabras) do
			if string.find(nombre, palabra, 1, true) then
				return true
			end
		end
		actual = actual.Parent
	end
	return false
end

local function esPersonaje(parte)
	local modelo = parte:FindFirstAncestorOfClass("Model")
	while modelo do
		if modelo:FindFirstChildOfClass("Humanoid") and Players:GetPlayerFromCharacter(modelo) then
			return true
		end
		modelo = modelo:FindFirstAncestorOfClass("Model")
	end
	return false
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function BathroomService:Init(registro)
	self.registro = registro
	self.Objetos = {} -- objetoId -> registro
	self.Orden = {} -- ids en orden de creación
	self.Sonidos = {} -- { { Sonido = Sound, Posicion = Vector3 } }
	self.UltimoUsoJugador = {} -- userId -> os.clock()
	self.UltimaAuditoria = {} -- userId -> { ["id|motivo"] = os.clock() }
	self.Conexiones = {}
	self.Advertencias = {}
	self.SinPieza = {} -- ids sin BasePart real cercana (sin prompt; el remoto sigue disponible)
	self.UsosTotales = 0
	self.Activo = false
	self.Usado = Signal.new() -- (player, objetoId, accion)
end

function BathroomService:Start()
	self.Activo = true
	local okSonidos, errSonidos = pcall(self.BuscarSonidos, self)
	if not okSonidos then
		self:Advertir("No se pudieron localizar los sonidos de cisterna: " .. tostring(errSonidos))
	end
	local okObjetos, errObjetos = pcall(self.ConstruirObjetos, self)
	if not okObjetos then
		warn(PREFIJO .. " Error al preparar los objetos de baño: " .. tostring(errObjetos))
	end

	local RemoteService = self:Servicio("RemoteService")
	if RemoteService and typeof(RemoteService.Registrar) == "function" then
		RemoteService:Registrar("BathroomAction", function(player, datos)
			return self:ManejarBathroomAction(player, datos)
		end, {
			Posicion = function(datos)
				local objeto = typeof(datos) == "table" and typeof(datos.ObjetoId) == "string" and self.Objetos[datos.ObjetoId] or nil
				if objeto then
					return objeto.Punto
				end
				return nil
			end,
		})
	else
		warn(PREFIJO .. " RemoteService no disponible: BathroomAction no tendrá handler (los prompts siguen funcionando).")
	end

	table.insert(self.Conexiones, Players.PlayerRemoving:Connect(function(player)
		self.UltimoUsoJugador[player.UserId] = nil
		self.UltimaAuditoria[player.UserId] = nil
	end))

	local conParte = 0
	for _, id in ipairs(self.Orden) do
		if self.Objetos[id].Parte then
			conParte = conParte + 1
		end
	end
	local AuditLog = self:Servicio("AuditLogService")
	if AuditLog then
		pcall(AuditLog.Registrar, AuditLog, "Sistema", nil, "Banos", string.format(
			"%d objetos de baño (%d con prompt), %d sonidos de cisterna", #self.Orden, conParte, #self.Sonidos))
	end
	for _, aviso in ipairs(self.Advertencias) do
		warn(PREFIJO .. " " .. aviso)
	end
end

function BathroomService:Servicio(nombre)
	local registro = self.registro
	if registro and typeof(registro.Get) == "function" then
		local ok, servicio = pcall(registro.Get, nombre)
		if ok then
			return servicio
		end
	end
	return nil
end

function BathroomService:Advertir(texto)
	table.insert(self.Advertencias, tostring(texto))
end

---------------------------------------------------------------------------------------------------
-- Construcción
---------------------------------------------------------------------------------------------------

-- Sonidos existentes Workspace/Bathroom Toilet/Handle/Sound (no se modifican; solo se reproducen).
function BathroomService:BuscarSonidos()
	for _, hijo in ipairs(workspace:GetChildren()) do
		if hijo.Name == "Bathroom Toilet" then
			local asa = hijo:FindFirstChild("Handle")
			local sonido = asa and asa:FindFirstChild("Sound")
			if sonido and sonido:IsA("Sound") then
				local posicion = nil
				if asa:IsA("BasePart") then
					posicion = asa.Position
				elseif hijo:IsA("Model") then
					local ok, cf = pcall(function()
						local caja = hijo:GetBoundingBox()
						return caja
					end)
					if ok and typeof(cf) == "CFrame" then
						posicion = cf.Position
					end
				end
				if posicion then
					table.insert(self.Sonidos, { Sonido = sonido, Posicion = posicion })
				end
			end
		end
	end
end

-- Parámetros de consulta: se excluye la carpeta propia del mapa.
function BathroomService:ParametrosConsulta()
	local params = OverlapParams.new()
	local excluir = {}
	local carpeta = workspace:FindFirstChild(NOMBRE_CARPETA_MAPA)
	if carpeta then
		table.insert(excluir, carpeta)
	end
	params.FilterDescendantsInstances = excluir
	pcall(function()
		params.FilterType = Enum.RaycastFilterType.Exclude
	end)
	return params, carpeta
end

-- BasePart real más cercana al punto (<= RadioBusqueda), sin Seats, piezas propias, personajes ni muros/suelos.
function BathroomService:ParteCercana(punto, palabras, params, carpeta)
	local okConsulta, partes = pcall(function()
		return workspace:GetPartBoundsInRadius(punto, self.RadioBusqueda, params)
	end)
	if not okConsulta or typeof(partes) ~= "table" then
		return nil
	end
	local mejor, mejorPuntaje, mejorDist = nil, math.huge, math.huge
	for _, parte in ipairs(partes) do
		if parte:IsA("BasePart") and not parte:IsA("Seat") and not parte:IsA("VehicleSeat") and not parte:IsA("Terrain")
			and not (carpeta and parte:IsDescendantOf(carpeta)) and not esPersonaje(parte) then
			local s = parte.Size
			if math.max(s.X, s.Y, s.Z) <= self.TamanoMaxPieza then
				local d = distanciaAParte(parte, punto)
				if d <= self.RadioBusqueda then
					local puntaje = d
					if coincideNombre(parte, palabras) then
						puntaje = puntaje - self.BonusNombre
					end
					if puntaje < mejorPuntaje then
						mejor, mejorPuntaje, mejorDist = parte, puntaje, d
					end
				end
			end
		end
	end
	return mejor, mejorDist
end

function BathroomService:ConstruirObjetos()
	local zonas = Zones.ZonasTipo("banos")
	if #zonas == 0 and typeof(MapaLogico.ZonasPorTipo) == "function" then
		zonas = MapaLogico.ZonasPorTipo("banos")
	end
	local params, carpeta = self:ParametrosConsulta()
	local MapService = self:Servicio("MapService")
	if #zonas == 0 then
		self:Advertir("No hay zonas de tipo \"banos\" en MapaLogico.")
	end
	for _, zona in ipairs(zonas) do
		local objetos = zona.Objetos
		if typeof(objetos) == "table" then
			for _, def in ipairs(TIPOS) do
				local puntos = objetos[def.Clave]
				if typeof(puntos) == "table" then
					for i, punto in ipairs(puntos) do
						if typeof(punto) == "Vector3" then
							local id = zona.Id .. "_" .. def.Tipo .. "_" .. tostring(i)
							local ok, err = pcall(self.CrearObjeto, self, id, zona, def, punto, params, carpeta, MapService)
							if not ok then
								self:Advertir("Objeto " .. id .. " con error: " .. tostring(err))
							end
						end
					end
				end
			end
		end
	end
	if #self.SinPieza > 0 then
		self:Advertir(string.format("%d objetos sin pieza real a <= %d studs (sin prompt; el remoto sigue disponible): %s",
			#self.SinPieza, self.RadioBusqueda, table.concat(self.SinPieza, " ")))
	end
end

function BathroomService:CrearObjeto(id, zona, def, punto, params, carpeta, MapService)
	local parte, distancia = self:ParteCercana(punto, def.Palabras, params, carpeta)
	local objeto = {
		Id = id,
		Zona = zona.Id,
		Tipo = def.Tipo,
		Accion = def.Accion,
		Punto = punto,
		Parte = parte,
		Distancia = distancia,
		UltimoUso = -math.huge,
		UltimaLimpieza = -math.huge,
		Usos = 0,
		Token = 0,
	}
	self.Objetos[id] = objeto
	table.insert(self.Orden, id)
	if not parte then
		table.insert(self.SinPieza, id)
		return
	end

	-- Attachment propio en el punto lógico (varios objetos pueden compartir pieza, p. ej. un mueble doble).
	local ancla = Instance.new("Attachment")
	ancla.Name = "ColegioRP_Bano_" .. id
	ancla.Position = parte.CFrame:PointToObjectSpace(punto)
	ancla.Parent = parte
	objeto.Ancla = ancla

	local prompt = Instance.new("ProximityPrompt")
	prompt.Name = "ColegioRP_PromptBano"
	prompt.ActionText = def.ActionText
	prompt.ObjectText = def.ObjectText
	prompt.HoldDuration = self.HoldDuration
	prompt.MaxActivationDistance = self.DistanciaPrompt
	prompt.RequiresLineOfSight = false
	prompt.ClickablePrompt = true
	prompt.Enabled = true
	prompt:SetAttribute("RPTipo", "Bano")
	prompt:SetAttribute("RPId", id)
	prompt:SetAttribute("RPAccion", def.Accion)
	prompt:SetAttribute("RPZona", zona.Id)
	prompt.Parent = ancla
	objeto.Prompt = prompt
	table.insert(self.Conexiones, prompt.Triggered:Connect(function(player)
		self:AlActivarPrompt(objeto, player)
	end))

	-- Tag y atributo ObjetoId en la pieza real (§8); vía MapService para que su Limpiar los retire.
	local marcarTag = MapService and typeof(MapService.MarcarTag) == "function"
	local marcarAtributo = MapService and typeof(MapService.MarcarAtributo) == "function"
	if marcarTag then
		pcall(MapService.MarcarTag, MapService, parte, TAG_BANO)
	else
		pcall(CollectionService.AddTag, CollectionService, parte, TAG_BANO)
	end
	if parte:GetAttribute("ObjetoId") == nil then
		if marcarAtributo then
			pcall(MapService.MarcarAtributo, MapService, parte, "ObjetoId", id)
		else
			pcall(parte.SetAttribute, parte, "ObjetoId", id)
		end
		objeto.MarcoAtributo = true
	end
end

---------------------------------------------------------------------------------------------------
-- Acciones
---------------------------------------------------------------------------------------------------

-- Sonido de cisterna más cercano (<= DistanciaSonido) al punto; se reproduce sin cambiar sus propiedades.
function BathroomService:ReproducirCisterna(punto)
	local mejor, mejorDist = nil, self.DistanciaSonido
	for _, entrada in ipairs(self.Sonidos) do
		local d = (entrada.Posicion - punto).Magnitude
		if d <= mejorDist and entrada.Sonido.Parent ~= nil then
			mejor, mejorDist = entrada.Sonido, d
		end
	end
	if mejor then
		local ok = pcall(function()
			mejor:Play()
		end)
		return ok
	end
	return false
end

-- Deshabilita el prompt mientras dura el cooldown del objeto (todos ven que está en uso).
function BathroomService:BloquearTemporal(objeto, segundos)
	objeto.Token = objeto.Token + 1
	local token = objeto.Token
	local prompt = objeto.Prompt
	if not prompt then
		return
	end
	pcall(function()
		prompt.Enabled = false
	end)
	task.delay(segundos, function()
		if objeto.Token == token and prompt.Parent ~= nil and self.Activo then
			pcall(function()
				prompt.Enabled = true
			end)
		end
	end)
end

function BathroomService:Desbloquear(objeto)
	objeto.Token = objeto.Token + 1
	if objeto.Prompt then
		pcall(function()
			objeto.Prompt.Enabled = true
		end)
	end
end

-- Ejecuta una acción. Devuelve ok, mensaje, codigo.
function BathroomService:Usar(player, objetoId, accion, origen)
	local objeto = typeof(objetoId) == "string" and self.Objetos[objetoId] or nil
	if not objeto then
		return false, "Ese objeto no está disponible.", "objeto_inexistente"
	end
	if accion ~= "LavarManos" and accion ~= "Usar" and accion ~= "Limpiar" then
		return false, "Acción no válida.", "accion_invalida"
	end
	if accion ~= "Limpiar" and accion ~= objeto.Accion then
		return false, "Esa acción no está disponible aquí.", "accion_invalida"
	end
	if not esJugador(player) then
		return false, "Jugador no válido.", "accion_invalida"
	end
	local pos = posicionJugador(player)
	if not pos then
		return false, "Necesitas tu personaje para hacerlo.", "sin_personaje"
	end
	if (pos - objeto.Punto).Magnitude > DISTANCIA_MAX + self.ToleranciaDistancia then
		return false, "Acércate más.", "distancia"
	end
	local ahora = os.clock()

	if accion == "Limpiar" then
		-- El remoto ya exige limpieza.tareas; otros servicios que llamen aquí pasan por la misma comprobación.
		if origen ~= "Remoto" then
			local RoleService = self:Servicio("RoleService")
			local tiene = false
			if RoleService and typeof(RoleService.Tiene) == "function" then
				local okTiene, resultado = pcall(RoleService.Tiene, RoleService, player, "limpieza.tareas")
				tiene = okTiene and resultado == true
			end
			if not tiene then
				return false, "Solo el personal de limpieza puede hacerlo.", "permiso"
			end
		end
		if ahora - objeto.UltimaLimpieza < self.CooldownLimpiezaSeg then
			return false, "Este lugar ya está limpio.", "cooldown_objeto"
		end
		objeto.UltimaLimpieza = ahora
		objeto.UltimoUso = -math.huge
		self:Desbloquear(objeto)
	else
		local ultimoJugador = self.UltimoUsoJugador[player.UserId]
		if ultimoJugador and ahora - ultimoJugador < self.CooldownJugadorSeg then
			return false, "Espera unos segundos antes de volver a hacerlo.", "cooldown_jugador"
		end
		if ahora - objeto.UltimoUso < self.CooldownObjetoSeg then
			return false, "Está en uso. Prueba con otro.", "cooldown_objeto"
		end
		self.UltimoUsoJugador[player.UserId] = ahora
		objeto.UltimoUso = ahora
		self:BloquearTemporal(objeto, self.CooldownObjetoSeg)
		if accion == "Usar" then
			self:ReproducirCisterna(objeto.Punto)
		end
	end

	objeto.Usos = objeto.Usos + 1
	self.UsosTotales = self.UsosTotales + 1
	pcall(function()
		self.Usado:Fire(player, objeto.Id, accion)
	end)
	return true, MENSAJES[accion], "ok"
end

function BathroomService:Notificar(player, texto, nivel)
	local RemoteService = self:Servicio("RemoteService")
	if RemoteService and typeof(RemoteService.Enviar) == "function" and esJugador(player) then
		pcall(RemoteService.Enviar, RemoteService, player, "Notificacion", { Texto = texto, Nivel = nivel or "info", Duracion = 3 })
	end
end

function BathroomService:AlActivarPrompt(objeto, player)
	if not self.Activo or not esJugador(player) then
		return
	end
	local ok, mensaje, codigo = self:Usar(player, objeto.Id, objeto.Accion, "Prompt")
	if not ok then
		self:RegistrarRechazo(player, codigo, objeto.Id, objeto.Accion, "Prompt")
		self:Notificar(player, mensaje, "aviso")
	else
		self:Notificar(player, mensaje, "info")
	end
end

-- Handler del remoto BathroomAction { ObjetoId, Accion }.
function BathroomService:ManejarBathroomAction(player, datos)
	local ok, mensaje, codigo = self:Usar(player, datos.ObjetoId, datos.Accion, "Remoto")
	if not ok then
		self:RegistrarRechazo(player, codigo, datos.ObjetoId, datos.Accion, "Remoto")
		return { ok = false, error = mensaje, datos = { ObjetoId = datos.ObjetoId, Codigo = codigo } }
	end
	return { ok = true, datos = { ObjetoId = datos.ObjetoId, Accion = datos.Accion, Mensaje = mensaje } }
end

function BathroomService:RegistrarRechazo(player, codigo, objetoId, accion, origen)
	if not MOTIVOS_AUDITADOS[codigo] then
		return
	end
	if esJugador(player) then
		local porJugador = self.UltimaAuditoria[player.UserId]
		if not porJugador then
			porJugador = {}
			self.UltimaAuditoria[player.UserId] = porJugador
		end
		local clave = tostring(objetoId) .. "|" .. tostring(codigo)
		local ahora = os.clock()
		if porJugador[clave] and ahora - porJugador[clave] < self.IntervaloAuditoriaSeg then
			return
		end
		porJugador[clave] = ahora
	end
	local AuditLog = self:Servicio("AuditLogService")
	if AuditLog then
		pcall(AuditLog.Registrar, AuditLog, "Remoto", player, "BathroomAction",
			string.format("logica:%s objeto=%s accion=%s origen=%s", tostring(codigo), tostring(objetoId), tostring(accion), tostring(origen)))
	end
	if codigo ~= "permiso" then
		local Metrics = self:Servicio("MetricsService")
		if Metrics and typeof(Metrics.IncrementarRechazo) == "function" then
			pcall(Metrics.IncrementarRechazo, Metrics, "BathroomAction", tostring(codigo))
		end
	end
end

---------------------------------------------------------------------------------------------------
-- API
---------------------------------------------------------------------------------------------------

-- Estado de los baños: totales y lista por objeto { Id, Zona, Tipo, Accion, Disponible, EnUsoSeg, Usos, ConPrompt }.
function BathroomService:Estado()
	local ahora = os.clock()
	local lista, porZona = {}, {}
	local conParte = 0
	for _, id in ipairs(self.Orden) do
		local objeto = self.Objetos[id]
		local restante = math.max(0, self.CooldownObjetoSeg - (ahora - objeto.UltimoUso))
		if objeto.Parte then
			conParte = conParte + 1
		end
		porZona[objeto.Zona] = (porZona[objeto.Zona] or 0) + 1
		table.insert(lista, {
			Id = id,
			Zona = objeto.Zona,
			Tipo = objeto.Tipo,
			Accion = objeto.Accion,
			Disponible = restante <= 0,
			EnUsoSeg = math.floor(restante + 0.5),
			Usos = objeto.Usos,
			ConPrompt = objeto.Prompt ~= nil,
		})
	end
	return {
		Total = #self.Orden,
		ConPrompt = conParte,
		Sonidos = #self.Sonidos,
		UsosTotales = self.UsosTotales,
		PorZona = porZona,
		Objetos = lista,
	}
end

BathroomService.Snapshot = BathroomService.Estado

-- Registro interno de un objeto (sin instancias en la copia) o nil.
function BathroomService:Objeto(objetoId)
	local objeto = self.Objetos[objetoId]
	if not objeto then
		return nil
	end
	return { Id = objeto.Id, Zona = objeto.Zona, Tipo = objeto.Tipo, Accion = objeto.Accion, Punto = objeto.Punto, Usos = objeto.Usos }
end

-- Retira prompts y attachments propios y los atributos/tags puestos (desinstalación).
function BathroomService:Restaurar()
	self.Activo = false
	for _, conexion in ipairs(self.Conexiones) do
		pcall(function()
			conexion:Disconnect()
		end)
	end
	self.Conexiones = {}
	for _, id in ipairs(self.Orden) do
		local objeto = self.Objetos[id]
		if objeto.Ancla then
			pcall(function()
				objeto.Ancla:Destroy()
			end)
		end
		if objeto.Parte then
			pcall(CollectionService.RemoveTag, CollectionService, objeto.Parte, TAG_BANO)
			if objeto.MarcoAtributo then
				pcall(objeto.Parte.SetAttribute, objeto.Parte, "ObjetoId", nil)
			end
		end
	end
	self.Objetos = {}
	self.Orden = {}
end

return BathroomService
]=] }
FUENTES["ServerScriptService/ColegioRP/Services/BoardService"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ServerScriptService.ColegioRP.Services.BoardService
	Tipo: ModuleScript
	Tablero de cada aula (docs/ARQUITECTURA.md §6). Mantiene un BoardState por RoomId
	{ Texto, Trazos, Plantilla, ImagenId, Autor, Actualizado, Proyeccion } con autoridad total del servidor y:
	  - atiende BoardAction: Escribir (filtrado con TextService), Limpiar, Plantilla (índice de Catalogs.Plantillas),
	    Trazo (puntos normalizados 0..1; acumula hasta Config.Tablero.MaxTrazos y descarta el más antiguo) e
	    Imagen (ImagenId numérico, solo docente);
	  - autoriza al docente de la sesión (ClassroomService:EsDocenteDe) o al estudiante con turno vigente
	    (ConcederTurno / RevocarTurno con expiración; al expirar avisa al jugador y al aula);
	  - replica solo a la zona del aula (EventoCliente "Tablero") y envía el estado completo a quien entra en el
	    aula (ciclo de 2 s, solo si su copia está desactualizada);
	  - dibuja el estado en la SurfaceGui del tablero físico creado por MapService (TextLabel, Frames por trazo
	    -1 Frame cada 2 puntos, máx. 600 por tablero- e ImageLabel), actualizando solo cuando cambia.

	Formato de red de un trazo: { Id, Color (1..4), Grosor (1..4), Autor (userId), P = "<puntos>" } donde cada
	punto ocupa 4 caracteres: x e y cuantizados a 0..4095 y escritos en base 64 con el alfabeto ALFABETO
	(2 caracteres por coordenada). Así un tablero lleno (300 trazos x 60 puntos) cabe en ~72 KB.
	Estilo de un trazo recibido por BoardAction: la componente Z del primer punto codifica
	Color * 0.1 + Grosor * 0.01 (p. ej. Z = 0.23 -> color 2, grosor 3); x e y van en 0..1 (izquierda->derecha,
	arriba->abajo).

	Eventos "Tablero" (todos con Sub y RoomId):
	  Estado  -> snapshot completo (ver BoardService:Estado).
	  Texto   -> { Version, Texto, Plantilla, PlantillaTexto, ImagenId, Proyeccion, Autor, AutorNombre, Actualizado }
	  Trazo   -> { Version, Trazo = <trazo de red>, Descartados = { ids }, Autor, AutorNombre, Actualizado }
	  Limpiar -> { Version, Todo = true, Completo = bool (también borra la proyección), Motivo }
	  Turno   -> { Activo, UserId, Nombre, Expira (workspace:GetServerTimeNow()), Segundos, Motivo, Anterior,
	               DocenteUserId, RequiereSesion }
]]

local Players = game:GetService("Players")
local TextService = game:GetService("TextService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local RP = ReplicatedStorage:WaitForChild("ColegioRP")
local Shared = RP:WaitForChild("Shared")
local Config = require(Shared:WaitForChild("Config"))
local Catalogs = require(Shared:WaitForChild("Catalogs"))
local Util = Shared:WaitForChild("Util")
local Zones = require(Util:WaitForChild("Zones"))
local Signal = require(Util:WaitForChild("Signal"))
local Maid = require(Util:WaitForChild("Maid"))

local BoardService = {}
BoardService.Nombre = "BoardService"

local PREFIJO = "[ColegioRP][BoardService]"
local TABLERO = Config.Tablero or {}

---------------------------------------------------------------------------------------------------
-- Parámetros (ajustables sin tocar la lógica)
---------------------------------------------------------------------------------------------------
BoardService.MaxCaracteres = tonumber(TABLERO.MaxCaracteres) or 400 -- Texto máximo del tablero.
BoardService.MaxTrazos = tonumber(TABLERO.MaxTrazos) or 300 -- Trazos guardados por tablero (FIFO).
BoardService.MaxTrazoPuntos = tonumber(TABLERO.MaxTrazoPuntos) or 60 -- Puntos por trazo.
BoardService.TurnoSeg = tonumber(TABLERO.TurnoSeg) or 90 -- Duración por defecto del turno de un invitado.
BoardService.TurnoMinSeg = 10 -- Turno mínimo aceptado por ConcederTurno.
BoardService.TurnoMaxSeg = 600 -- Turno máximo aceptado por ConcederTurno.
BoardService.DistanciaMax = (Config.Distancias and tonumber(Config.Distancias.Tablero)) or 30 -- Studs al tablero si se está fuera de la zona del aula.
BoardService.ToleranciaDistancia = 2 -- Margen por latencia y tamaño del personaje.
BoardService.IntervaloCicloSeg = 2 -- Ciclo de entrada en aulas, docente de la sesión y turnos vencidos.
BoardService.MaxLineas = 12 -- Saltos de línea máximos del texto del tablero.
BoardService.MaxFramesTablero = 600 -- Frames de trazos por tablero físico.
BoardService.MaxFramesGlobal = 6000 -- Frames de trazos sumando todos los tableros físicos.
BoardService.PuntosPorFrame = 2 -- Un Frame (segmento) por cada 2 puntos del trazo.
BoardService.ToleranciaPunto = 0.002 -- Margen aceptado fuera de 0..1 antes de rechazar un punto.
BoardService.PermitirDocenteSinSesion = false -- true: un cargo con tablero.escribir puede usar el tablero de un aula sin sesión abierta.
BoardService.AspectoPorDefecto = 10 / 6 -- Ancho/alto si el aula no tiene tablero físico.
-- Espera mínima (s) entre acciones del mismo tipo por jugador (además del límite de RemoteService).
BoardService.EsperaAccion = { Escribir = 1, Plantilla = 0.5, Imagen = 2, Limpiar = 1, Trazo = 0.08 }

-- Paleta de tiza (índice = Color del trazo). BoardController usa la misma.
BoardService.ColoresTiza = {
	Color3.fromRGB(240, 240, 232), -- 1 Blanco tiza
	Color3.fromRGB(246, 206, 70), -- 2 Amarillo
	Color3.fromRGB(240, 110, 110), -- 3 Rojo claro
	Color3.fromRGB(120, 180, 250), -- 4 Azul claro
}
-- Grosor (índice = Grosor del trazo) como fracción del alto del tablero. BoardController usa los mismos.
BoardService.Grosores = { 0.008, 0.014, 0.022, 0.032 }
BoardService.ColorFondo = Color3.fromRGB(30, 56, 44) -- Verde pizarra (solo visible cuando hay contenido).
BoardService.TransparenciaFondo = 0.04
BoardService.ColorTexto = Color3.fromRGB(240, 240, 232)
BoardService.ColorPlantilla = Color3.fromRGB(246, 206, 70)

-- Motivos de rechazo que sugieren una petición manipulada (se cuentan en MetricsService).
local MOTIVOS_SOSPECHOSOS = { aula_desconocida = true, puntos_invalidos = true, accion_desconocida = true }

-- Mensajes al jugador cuando termina su turno (por motivo).
local MENSAJES_FIN_TURNO = {
	Expirado = "Tu turno en el tablero de %s terminó.",
	Revocado = "El docente retiró tu turno en el tablero de %s.",
	Reemplazado = "El docente dio el turno del tablero de %s a otra persona.",
	SesionCerrada = "La sesión de clase de %s terminó; tu turno en el tablero se cerró.",
	Limpieza = "El tablero de %s se reinició; tu turno terminó.",
	CambioCargo = "Cambiaste de cargo; tu turno en el tablero de %s terminó.",
	OtraAula = "Recibiste turno en otro tablero; el de %s se cerró.",
}

---------------------------------------------------------------------------------------------------
-- Codificación de puntos (base 64, 2 caracteres por coordenada cuantizada a 0..4095)
---------------------------------------------------------------------------------------------------
local ALFABETO = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"
local CUANTOS = 4095
local CARACTERES = {}
for i = 1, 64 do
	CARACTERES[i] = string.sub(ALFABETO, i, i)
end
BoardService.Alfabeto = ALFABETO
BoardService.Cuantos = CUANTOS

local function clamp(valor, minimo, maximo)
	if valor < minimo then
		return minimo
	end
	if valor > maximo then
		return maximo
	end
	return valor
end

local function cuantizar(valor)
	return clamp(math.floor(valor * CUANTOS + 0.5), 0, CUANTOS)
end

-- puntos = { {x, y}, ... } ya cuantizados -> cadena de 4 caracteres por punto.
local function codificarPuntos(puntos)
	local partes = table.create(#puntos * 4)
	for _, punto in ipairs(puntos) do
		local qx = cuantizar(punto[1])
		local qy = cuantizar(punto[2])
		table.insert(partes, CARACTERES[math.floor(qx / 64) + 1])
		table.insert(partes, CARACTERES[(qx % 64) + 1])
		table.insert(partes, CARACTERES[math.floor(qy / 64) + 1])
		table.insert(partes, CARACTERES[(qy % 64) + 1])
	end
	return table.concat(partes)
end

-- Z del primer punto -> color (1..4) y grosor (1..4). Valores fuera de rango usan blanco / medio.
local function decodificarEstilo(z, colores, grosores)
	local codigo = 0
	if typeof(z) == "number" and z == z then
		codigo = math.floor(clamp(z, 0, 1) * 100 + 0.5)
	end
	local color = math.floor(codigo / 10)
	local grosor = codigo % 10
	if color < 1 or color > #colores then
		color = 1
	end
	if grosor < 1 or grosor > #grosores then
		grosor = 2
	end
	return color, grosor
end

---------------------------------------------------------------------------------------------------
-- Utilidades
---------------------------------------------------------------------------------------------------
local function esJugador(player)
	return typeof(player) == "Instance" and player:IsA("Player")
end

local function posicionDe(player)
	local personaje = player.Character
	if not personaje then
		return nil
	end
	local raiz = personaje:FindFirstChild("HumanoidRootPart")
	if raiz and raiz:IsA("BasePart") then
		return raiz.Position
	end
	return nil
end

local function ahoraServidor()
	local ok, t = pcall(function()
		return workspace:GetServerTimeNow()
	end)
	if ok and typeof(t) == "number" then
		return t
	end
	return os.time()
end

local function nombreJugador(player)
	if not esJugador(player) then
		return ""
	end
	local nombre = player.DisplayName
	if typeof(nombre) ~= "string" or nombre == "" then
		nombre = player.Name
	end
	return nombre
end

local function nombreAula(roomId)
	local zona = Zones.Zona(roomId)
	if zona and typeof(zona.Nombre) == "string" and zona.Nombre ~= "" then
		return zona.Nombre
	end
	return tostring(roomId)
end

local function fuenteSegura(nombre, respaldo)
	local ok, fuente = pcall(function()
		return Enum.Font[nombre]
	end)
	if ok and fuente ~= nil then
		return fuente
	end
	return respaldo
end

local FUENTE_TIZA = fuenteSegura("PatrickHand", Enum.Font.Gotham)
local FUENTE_TITULO = fuenteSegura("GothamBold", Enum.Font.SourceSansBold)
local FUENTE_TEXTO = fuenteSegura("Gotham", Enum.Font.SourceSans)

-- Conecta a una señal Lua (Signal) o de Roblox; devuelve la conexión o nil.
local function conectar(senal, fn)
	if typeof(senal) == "RBXScriptSignal" then
		return senal:Connect(fn)
	end
	if typeof(senal) == "table" and typeof(senal.Connect) == "function" then
		local ok, conexion = pcall(senal.Connect, senal, fn)
		if ok then
			return conexion
		end
	end
	return nil
end

-- Caracteres invisibles o de control de dirección que no se aceptan en el tablero.
local function esInvisible(codigo)
	return (codigo >= 0x200B and codigo <= 0x200F)
		or (codigo >= 0x202A and codigo <= 0x202E)
		or (codigo >= 0x2060 and codigo <= 0x2064)
		or (codigo >= 0x2066 and codigo <= 0x2069)
		or codigo == 0xFEFF or codigo == 0x00AD
end

-- Normaliza el texto: quita controles e invisibles, limita caracteres y líneas, recorta espacios.
local function sanearTexto(texto, maxCaracteres, maxLineas)
	if typeof(texto) ~= "string" or utf8.len(texto) == nil then
		return ""
	end
	local partes = {}
	local lineas = 1
	local cuenta = 0
	local ok = pcall(function()
		for _, codigo in utf8.codes(texto) do
			if cuenta >= maxCaracteres then
				break
			end
			if codigo == 10 then
				if lineas < maxLineas then
					lineas = lineas + 1
					table.insert(partes, "\n")
					cuenta = cuenta + 1
				end
			elseif codigo == 9 then
				table.insert(partes, " ")
				cuenta = cuenta + 1
			elseif codigo >= 32 and codigo ~= 127 and not (codigo >= 128 and codigo < 160) and not esInvisible(codigo) then
				table.insert(partes, utf8.char(codigo))
				cuenta = cuenta + 1
			end
		end
	end)
	if not ok then
		return ""
	end
	local resultado = table.concat(partes)
	resultado = string.gsub(resultado, " +\n", "\n")
	resultado = string.match(resultado, "^%s*(.-)%s*$") or ""
	return resultado
end

local function estadoVacio(estado)
	return estado == nil or (estado.Texto == "" and estado.Plantilla == 0 and #estado.Trazos == 0
		and estado.ImagenId == 0 and estado.Proyeccion == "")
end

local function framesNecesarios(numPuntos, puntosPorFrame)
	if numPuntos <= 1 then
		return 1
	end
	return math.ceil((numPuntos - 1) / puntosPorFrame)
end

-- Trazo en formato de red (se calcula una vez por trazo).
local function trazoRed(trazo)
	if trazo.Red == nil then
		trazo.Red = { Id = trazo.Id, Color = trazo.Color, Grosor = trazo.Grosor, Autor = trazo.Autor, P = trazo.P }
	end
	return trazo.Red
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function BoardService:Init(registro)
	self.registro = registro
	self.Estados = {} -- roomId -> BoardState
	self.Turnos = {} -- roomId -> { UserId, Nombre, Expira (os.clock), ExpiraServidor, Segundos, Token, Otorgante }
	self.Vistas = {} -- roomId -> vista del tablero físico
	self.Enviado = {} -- userId -> { RoomId, Version } (última copia completa/sincronizada del cliente)
	self.UltimaAccion = {} -- userId -> { accion -> os.clock() }
	self.Filtrando = {} -- userId -> true mientras su texto se filtra (una escritura a la vez por jugador)
	self.DocenteConocido = {} -- roomId -> userId | 0 (detección de apertura/cierre de sesión)
	self.CacheRed = {} -- roomId -> { Version, Trazos }
	self.FramesGlobal = 0
	self.TokenTurno = 0
	self.SiguienteTrazo = 0
	self.Activo = false
	self.CicloPendiente = false
	self.Maid = Maid.new()
	self.Cambiado = Signal.new() -- (roomId, sub) tras cada cambio de contenido
	self.TurnoCambiado = Signal.new() -- (roomId, turno | nil, motivo)
	self.Estadisticas = { Escrituras = 0, Trazos = 0, Limpiezas = 0, Imagenes = 0, Rechazos = 0, FiltrosFallidos = 0, Snapshots = 0 }
end

function BoardService:Start()
	self.Activo = true

	local RemoteService = self.registro.Get("RemoteService")
	if RemoteService and typeof(RemoteService.Registrar) == "function" then
		RemoteService:Registrar("BoardAction", function(player, datos)
			return self:ManejarAccion(player, datos)
		end)
	else
		warn(PREFIJO .. " RemoteService no disponible: BoardAction no tendrá handler.")
	end

	self.Maid:GiveTask(Players.PlayerRemoving:Connect(function(player)
		self:AlSalir(player)
	end))

	-- Fin de jornada: si ClassroomService no limpió los tableros al cerrar las sesiones, se limpian aquí.
	local SchoolDayService = self.registro.Get("SchoolDayService")
	if SchoolDayService then
		local conexion = conectar(SchoolDayService.JornadaTerminada, function()
			self:LimpiarTodos("FinJornada")
		end)
		if conexion then
			self.Maid:GiveTask(conexion)
		end
	end

	-- Reconstrucción del mapa: las SurfaceGui son nuevas, se redibuja todo.
	local MapService = self.registro.Get("MapService")
	if MapService then
		local conexion = conectar(MapService.Construido, function()
			task.defer(function()
				self:RedibujarTodo()
			end)
		end)
		if conexion then
			self.Maid:GiveTask(conexion)
		end
	end

	-- Cambio de cargo: el turno de tablero pertenece a la situación anterior.
	local RoleService = self.registro.Get("RoleService")
	if RoleService then
		local conexion = conectar(RoleService.CargoCambiado, function(player)
			if esJugador(player) then
				self:_FinTurnosDe(player.UserId, "CambioCargo")
			end
		end)
		if conexion then
			self.Maid:GiveTask(conexion)
		end
	end

	-- Sesiones de clase: al abrir se avisa del docente al aula; al cerrar se limpia el tablero
	-- (si ClassroomService ya lo limpió, Limpiar no hace nada).
	local Classroom = self.registro.Get("ClassroomService")
	if Classroom then
		local function aulaDeSesion(sesion)
			if typeof(sesion) == "table" and typeof(sesion.RoomId) == "string" then
				return sesion.RoomId
			end
			if typeof(sesion) == "string" then
				return sesion
			end
			return nil
		end
		local abierta = conectar(Classroom.SesionAbierta, function(sesion)
			local roomId = aulaDeSesion(sesion)
			if roomId and self:EsAula(roomId) then
				self.DocenteConocido[roomId] = self:DocenteDe(roomId) or 0
				self:_Difundir(roomId, self:_DatosTurno(roomId, "Sesion"))
			end
		end)
		if abierta then
			self.Maid:GiveTask(abierta)
		end
		local cerrada = conectar(Classroom.SesionCerrada, function(sesion)
			local roomId = aulaDeSesion(sesion)
			if roomId and self:EsAula(roomId) then
				self:Limpiar(roomId, "SesionCerrada")
				self.DocenteConocido[roomId] = self:DocenteDe(roomId) or 0
				self:_Difundir(roomId, self:_DatosTurno(roomId, "Sesion"))
			end
		end)
		if cerrada then
			self.Maid:GiveTask(cerrada)
		end
	end

	-- Ocupación de asientos: adelanta el ciclo para que quien se sienta reciba el tablero enseguida.
	local RoomService = self.registro.Get("RoomService")
	if RoomService then
		local conexion = conectar(RoomService.OcupacionCambiada, function()
			self:_ProgramarCiclo()
		end)
		if conexion then
			self.Maid:GiveTask(conexion)
		end
	end

	local hilo = task.spawn(function()
		while self.Activo do
			task.wait(self.IntervaloCicloSeg)
			if not self.Activo then
				break
			end
			local ok, err = pcall(self._Ciclo, self)
			if not ok then
				warn(PREFIJO .. " Error en el ciclo: " .. tostring(err))
			end
		end
	end)
	self.Maid:GiveTask(function()
		self.Activo = false
		if coroutine.status(hilo) == "suspended" then
			pcall(task.cancel, hilo)
		end
	end)
end

-- Detiene el ciclo y desconecta (uso de pruebas o desinstalación). El estado se conserva.
function BoardService:Detener()
	self.Activo = false
	self.Maid:DoCleaning()
end

---------------------------------------------------------------------------------------------------
-- Consultas de aula y autorización
---------------------------------------------------------------------------------------------------

-- ¿El id corresponde a un aula (construida por MapService o listada en MapaLogico.Aulas)?
function BoardService:EsAula(roomId)
	if typeof(roomId) ~= "string" or roomId == "" or #roomId > 16 then
		return false
	end
	local MapService = self.registro.Get("MapService")
	if MapService and typeof(MapService.Aula) == "function" then
		local ok, aula = pcall(MapService.Aula, MapService, roomId)
		if ok and aula ~= nil then
			return true
		end
	end
	return Zones.EsAula(roomId) == true
end

-- Registro del aula en MapService ({ Tablero, TableroGui, Zona, ... }) o nil.
function BoardService:_InfoAula(roomId)
	local MapService = self.registro.Get("MapService")
	if not MapService or typeof(MapService.Aula) ~= "function" then
		return nil
	end
	local ok, aula = pcall(MapService.Aula, MapService, roomId)
	if ok and typeof(aula) == "table" then
		return aula
	end
	return nil
end

-- Id de la zona del aula (MapaLogico usa la misma id que el aula).
function BoardService:ZonaDeAula(roomId)
	local aula = self:_InfoAula(roomId)
	if aula and typeof(aula.Zona) == "table" and typeof(aula.Zona.Id) == "string" then
		return aula.Zona.Id
	end
	return roomId
end

-- Relación ancho/alto del tablero físico (la usa el cliente para el lienzo).
function BoardService:Aspecto(roomId)
	local aula = self:_InfoAula(roomId)
	local tablero = aula and aula.Tablero
	if typeof(tablero) == "Instance" and tablero:IsA("BasePart") and tablero.Size.Y > 0 then
		return tablero.Size.X / tablero.Size.Y
	end
	return self.AspectoPorDefecto
end

-- ¿La autorización depende de una sesión de ClassroomService?
function BoardService:RequiereSesion()
	return self.registro.Get("ClassroomService") ~= nil
end

-- userId del docente de la sesión abierta en el aula, o nil.
function BoardService:DocenteDe(roomId)
	local Classroom = self.registro.Get("ClassroomService")
	if not Classroom or typeof(Classroom.SesionDe) ~= "function" then
		return nil
	end
	local ok, sesion = pcall(Classroom.SesionDe, Classroom, roomId)
	if not ok or typeof(sesion) ~= "table" then
		return nil
	end
	if sesion.State == "Cerrada" or sesion.Estado == "Cerrada" then
		return nil
	end
	return tonumber(sesion.TeacherUserId or sesion.DocenteUserId)
end

local function tienePermiso(registro, player, permiso)
	local RoleService = registro.Get("RoleService")
	if RoleService and typeof(RoleService.Tiene) == "function" then
		local ok, tiene = pcall(RoleService.Tiene, RoleService, player, permiso)
		return ok and tiene == true
	end
	return false
end

-- ¿Es el docente del aula? Con ClassroomService: docente de la sesión; sin él: permiso tablero.escribir.
function BoardService:EsDocenteDe(player, roomId)
	local Classroom = self.registro.Get("ClassroomService")
	if Classroom then
		local es = false
		if typeof(Classroom.EsDocenteDe) == "function" then
			local ok, resultado = pcall(Classroom.EsDocenteDe, Classroom, player, roomId)
			es = ok and resultado == true
		else
			local docente = self:DocenteDe(roomId)
			es = docente ~= nil and docente == player.UserId
		end
		if not es and self.PermitirDocenteSinSesion and self:DocenteDe(roomId) == nil then
			es = tienePermiso(self.registro, player, "tablero.escribir")
		end
		return es
	end
	return tienePermiso(self.registro, player, "tablero.escribir")
end

-- Rol del jugador en el tablero: "Docente" | "Invitado" | nil.
function BoardService:RolDe(player, roomId)
	if not esJugador(player) then
		return nil
	end
	if self:EsDocenteDe(player, roomId) then
		return "Docente"
	end
	local turno = self:TurnoDe(roomId)
	if turno and turno.UserId == player.UserId then
		return "Invitado"
	end
	return nil
end

-- ¿Puede escribir ahora? Devuelve bool y el rol.
function BoardService:PuedeEscribir(player, roomId)
	local rol = self:RolDe(player, roomId)
	return rol ~= nil, rol
end

-- ¿Está dentro de la zona del aula o cerca del tablero físico (sin estar dentro de otra aula)?
function BoardService:EstaCerca(player, roomId)
	local posicion = posicionDe(player)
	if not posicion then
		return false
	end
	local zonaId = self:ZonaDeAula(roomId)
	if Zones.Zona(zonaId) and Zones.Contiene(zonaId, posicion) then
		return true
	end
	local otraAula = self:AulaDePosicion(posicion)
	if otraAula ~= nil and otraAula ~= roomId and otraAula ~= zonaId then
		return false
	end
	local aula = self:_InfoAula(roomId)
	local tablero = aula and aula.Tablero
	if typeof(tablero) == "Instance" and tablero:IsA("BasePart") then
		return (tablero.Position - posicion).Magnitude <= self.DistanciaMax + self.ToleranciaDistancia
	end
	local RoomService = self.registro.Get("RoomService")
	if RoomService and typeof(RoomService.EstaEn) == "function" then
		local ok, esta = pcall(RoomService.EstaEn, RoomService, player, roomId)
		return ok and esta == true
	end
	return false
end

function BoardService:EstaSilenciado(player)
	local Moderation = self.registro.Get("ModerationService")
	if Moderation and typeof(Moderation.EstaSilenciado) == "function" then
		local ok, silenciado = pcall(Moderation.EstaSilenciado, Moderation, player)
		if ok then
			return silenciado == true
		end
	end
	return player:GetAttribute("Silenciado") == true
end

-- Aula (zona) en la que está físicamente el jugador, o nil.
function BoardService:AulaDePosicion(posicion)
	if typeof(posicion) ~= "Vector3" then
		return nil
	end
	for _, zona in ipairs(Zones.ZonasEn(posicion)) do
		if self:EsAula(zona.Id) then
			return zona.Id
		end
	end
	return nil
end

---------------------------------------------------------------------------------------------------
-- Estado
---------------------------------------------------------------------------------------------------
function BoardService:_Estado(roomId)
	local estado = self.Estados[roomId]
	if not estado then
		estado = {
			RoomId = roomId,
			Texto = "",
			TextoAutor = 0,
			Trazos = {},
			Plantilla = 0,
			ImagenId = 0,
			Autor = 0,
			AutorNombre = "",
			Actualizado = 0,
			Proyeccion = "",
			Version = 0,
		}
		self.Estados[roomId] = estado
	end
	return estado
end

function BoardService:_MarcarCambio(estado, player)
	estado.Version = estado.Version + 1
	estado.Actualizado = os.time()
	if esJugador(player) then
		estado.Autor = player.UserId
		estado.AutorNombre = nombreJugador(player)
	end
	self.CacheRed[estado.RoomId] = nil
end

function BoardService:_DatosTexto(estado)
	return {
		Sub = "Texto",
		RoomId = estado.RoomId,
		Version = estado.Version,
		Texto = estado.Texto,
		Plantilla = estado.Plantilla,
		PlantillaTexto = Catalogs.Plantillas[estado.Plantilla] or "",
		ImagenId = estado.ImagenId,
		Proyeccion = estado.Proyeccion,
		Autor = estado.Autor,
		AutorNombre = estado.AutorNombre,
		Actualizado = estado.Actualizado,
	}
end

function BoardService:_TrazosRed(roomId, estado)
	local cache = self.CacheRed[roomId]
	if cache and cache.Version == estado.Version then
		return cache.Trazos
	end
	local lista = table.create(#estado.Trazos)
	for i, trazo in ipairs(estado.Trazos) do
		lista[i] = trazoRed(trazo)
	end
	self.CacheRed[roomId] = { Version = estado.Version, Trazos = lista }
	return lista
end

-- Turno vigente del aula (o nil). Comprueba la expiración al consultar.
function BoardService:TurnoDe(roomId)
	local turno = self.Turnos[roomId]
	if not turno then
		return nil
	end
	if os.clock() >= turno.Expira then
		self:_FinTurno(roomId, "Expirado")
		return nil
	end
	return turno
end

-- ¿El jugador tiene turno vigente en el aula?
function BoardService:TieneTurno(player, roomId)
	local turno = self:TurnoDe(roomId)
	return turno ~= nil and esJugador(player) and turno.UserId == player.UserId
end

-- Snapshot completo para el cliente (lo envía este servicio al entrar en el aula y lo incluye
-- ClassroomService en ConsultarEstado). opciones.Puntos = true añade Puntos = { {x, y}, ... } a cada trazo.
-- La lista Trazos se comparte con la caché: no modificarla.
function BoardService:Estado(roomId, opciones)
	if not self:EsAula(roomId) then
		return nil
	end
	local estado = self:_Estado(roomId)
	local datos = self:_DatosTexto(estado)
	datos.Sub = "Estado"
	datos.Nombre = nombreAula(roomId)
	datos.Aspecto = self:Aspecto(roomId)
	datos.Trazos = self:_TrazosRed(roomId, estado)
	if typeof(opciones) == "table" and opciones.Puntos == true then
		local detallados = table.create(#estado.Trazos)
		for i, trazo in ipairs(estado.Trazos) do
			local puntos = table.create(#trazo.Puntos)
			for j, punto in ipairs(trazo.Puntos) do
				puntos[j] = { punto[1], punto[2] }
			end
			detallados[i] = { Id = trazo.Id, Color = trazo.Color, Grosor = trazo.Grosor, Autor = trazo.Autor, P = trazo.P, Puntos = puntos }
		end
		datos.Trazos = detallados
	end
	local turno = self:TurnoDe(roomId)
	if turno then
		datos.Turno = { UserId = turno.UserId, Nombre = turno.Nombre, Expira = turno.ExpiraServidor, Segundos = turno.Segundos }
	end
	datos.DocenteUserId = self:DocenteDe(roomId)
	datos.RequiereSesion = self:RequiereSesion()
	datos.Limites = {
		MaxCaracteres = self.MaxCaracteres,
		MaxTrazos = self.MaxTrazos,
		MaxTrazoPuntos = self.MaxTrazoPuntos,
		TurnoSeg = self.TurnoSeg,
	}
	datos.Vacio = estadoVacio(estado)
	return datos
end

---------------------------------------------------------------------------------------------------
-- Envío a clientes
---------------------------------------------------------------------------------------------------
function BoardService:_JugadoresEnZona(zonaId)
	local lista = {}
	if not Zones.Zona(zonaId) then
		return lista
	end
	for _, player in ipairs(Players:GetPlayers()) do
		local posicion = posicionDe(player)
		if posicion and Zones.Contiene(zonaId, posicion) then
			table.insert(lista, player)
		end
	end
	return lista
end

-- Envía a la zona del aula; si 'actor' está fuera de la zona también lo recibe.
function BoardService:_Difundir(roomId, datos, actor)
	local RemoteService = self.registro.Get("RemoteService")
	if not RemoteService then
		return
	end
	local zonaId = self:ZonaDeAula(roomId)
	local enZona = self:_JugadoresEnZona(zonaId)
	if Zones.Zona(zonaId) and typeof(RemoteService.EnviarAZona) == "function" then
		pcall(RemoteService.EnviarAZona, RemoteService, zonaId, "Tablero", datos)
	elseif typeof(RemoteService.EnviarAAula) == "function" then
		pcall(RemoteService.EnviarAAula, RemoteService, roomId, "Tablero", datos)
	end
	-- Sincronía: los que tenían la versión anterior pasan a tener la nueva; un snapshot sincroniza a todos.
	local version = datos.Version
	local recibido = {}
	for _, player in ipairs(enZona) do
		recibido[player] = true
		if typeof(version) == "number" then
			local enviado = self.Enviado[player.UserId]
			if datos.Sub == "Estado" then
				self.Enviado[player.UserId] = { RoomId = roomId, Version = version }
			elseif enviado and enviado.RoomId == roomId and enviado.Version == version - 1 then
				enviado.Version = version
			end
		end
	end
	if esJugador(actor) and actor.Parent ~= nil and not recibido[actor] and typeof(RemoteService.Enviar) == "function" then
		pcall(RemoteService.Enviar, RemoteService, actor, "Tablero", datos)
	end
	self.Cambiado:Fire(roomId, datos.Sub)
end

-- Envía el snapshot completo a un jugador y marca su copia como sincronizada.
function BoardService:EnviarEstado(player, roomId)
	if not esJugador(player) then
		return false
	end
	local RemoteService = self.registro.Get("RemoteService")
	local datos = self:Estado(roomId)
	if not RemoteService or not datos then
		return false
	end
	local ok, enviado = pcall(RemoteService.Enviar, RemoteService, player, "Tablero", datos)
	if ok and enviado ~= false then
		self.Enviado[player.UserId] = { RoomId = roomId, Version = datos.Version }
		self.Estadisticas.Snapshots = self.Estadisticas.Snapshots + 1
		return true
	end
	return false
end

function BoardService:_Notificar(player, texto, nivel)
	local RemoteService = self.registro.Get("RemoteService")
	if RemoteService and esJugador(player) and player.Parent ~= nil then
		pcall(RemoteService.Enviar, RemoteService, player, "Notificacion", { Texto = texto, Nivel = nivel or "info", Duracion = 5 })
	end
end

function BoardService:_Auditar(player, accion, detalle)
	local AuditLog = self.registro.Get("AuditLogService")
	if AuditLog and typeof(AuditLog.Registrar) == "function" then
		pcall(AuditLog.Registrar, AuditLog, "Clase", player, accion, detalle)
	end
end

function BoardService:_Rechazo(player, motivo, mensaje, detalle)
	self.Estadisticas.Rechazos = self.Estadisticas.Rechazos + 1
	local texto = motivo
	if detalle ~= nil then
		texto = motivo .. ": " .. tostring(detalle)
	end
	self:_Auditar(player, "TableroRechazo", texto)
	if MOTIVOS_SOSPECHOSOS[motivo] then
		local Metrics = self.registro.Get("MetricsService")
		if Metrics and typeof(Metrics.IncrementarRechazo) == "function" then
			pcall(Metrics.IncrementarRechazo, Metrics, "BoardAction", motivo)
		end
	end
	return { ok = false, error = mensaje or ("rechazado:" .. motivo), Motivo = motivo }
end

-- Espera mínima entre acciones del mismo tipo. Devuelve true si se puede continuar.
function BoardService:_Espera(player, accion)
	local espera = self.EsperaAccion[accion] or 0.2
	local porJugador = self.UltimaAccion[player.UserId]
	if not porJugador then
		porJugador = {}
		self.UltimaAccion[player.UserId] = porJugador
	end
	local ahora = os.clock()
	local ultimo = porJugador[accion]
	if ultimo and ahora - ultimo < espera then
		return false
	end
	porJugador[accion] = ahora
	return true
end

---------------------------------------------------------------------------------------------------
-- Filtrado de texto
---------------------------------------------------------------------------------------------------

-- Filtra con TextService para mostrar a todos. Devuelve ok, textoFiltrado. Si falla, no se muestra nada.
function BoardService:Filtrar(texto, player)
	if typeof(texto) ~= "string" or texto == "" then
		return true, ""
	end
	if not esJugador(player) then
		return false, nil
	end
	local okFiltro, resultado = pcall(function()
		return TextService:FilterStringAsync(texto, player.UserId, Enum.TextFilterContext.PublicChat)
	end)
	if not okFiltro or resultado == nil then
		warn(PREFIJO .. " FilterStringAsync falló: " .. tostring(resultado))
		return false, nil
	end
	local okTexto, filtrado = pcall(function()
		return resultado:GetNonChatStringForBroadcastAsync()
	end)
	if not okTexto or typeof(filtrado) ~= "string" then
		warn(PREFIJO .. " GetNonChatStringForBroadcastAsync falló: " .. tostring(filtrado))
		return false, nil
	end
	return true, filtrado
end

---------------------------------------------------------------------------------------------------
-- Handler de BoardAction
---------------------------------------------------------------------------------------------------
function BoardService:ManejarAccion(player, datos)
	if not esJugador(player) or typeof(datos) ~= "table" then
		return { ok = false, error = "rechazado:datos" }
	end
	local accion = datos.Accion
	local roomId = datos.Salon
	if not self:EsAula(roomId) then
		return self:_Rechazo(player, "aula_desconocida", "Ese salón no tiene tablero.", roomId)
	end
	local rol = self:RolDe(player, roomId)
	if rol == nil then
		local mensaje = "Solo el docente de la sesión o un estudiante con turno puede usar el tablero."
		if self:RequiereSesion() and self:DocenteDe(roomId) == nil then
			mensaje = "No hay una sesión de clase abierta en este salón."
		end
		return self:_Rechazo(player, "sin_turno", mensaje, accion)
	end
	if accion == "Imagen" and rol ~= "Docente" then
		return self:_Rechazo(player, "solo_docente", "Solo el docente puede mostrar imágenes en el tablero.")
	end
	if not self:EstaCerca(player, roomId) then
		return self:_Rechazo(player, "distancia", "Acércate al tablero del salón para usarlo.", roomId)
	end
	if accion ~= "Limpiar" and self:EstaSilenciado(player) then
		return self:_Rechazo(player, "silenciado", "Estás silenciado: no puedes escribir en el tablero.")
	end
	if not self:_Espera(player, tostring(accion)) then
		self.Estadisticas.Rechazos = self.Estadisticas.Rechazos + 1
		return { ok = false, error = "rechazado:cooldown", Motivo = "cooldown" }
	end

	if accion == "Escribir" then
		return self:_Escribir(player, roomId, datos.Texto)
	elseif accion == "Trazo" then
		return self:_Trazo(player, roomId, datos.Trazo)
	elseif accion == "Plantilla" then
		return self:_Plantilla(player, roomId, datos.Plantilla)
	elseif accion == "Imagen" then
		return self:_Imagen(player, roomId, datos.ImagenId)
	elseif accion == "Limpiar" then
		return self:_LimpiarPor(player, roomId, rol)
	end
	return self:_Rechazo(player, "accion_desconocida", "Acción de tablero desconocida.", accion)
end

function BoardService:_Escribir(player, roomId, texto)
	if typeof(texto) ~= "string" then
		return self:_Rechazo(player, "texto_requerido", "Escribe un texto para el tablero (o envía un texto vacío para borrarlo).")
	end
	local limpio = sanearTexto(texto, self.MaxCaracteres, self.MaxLineas)
	local final = ""
	if limpio ~= "" then
		-- Una escritura a la vez por jugador: el filtrado cede el hilo y dos peticiones solapadas podrían
		-- aplicarse en orden inverso.
		if self.Filtrando[player.UserId] then
			self.Estadisticas.Rechazos = self.Estadisticas.Rechazos + 1
			return { ok = false, error = "rechazado:cooldown", Motivo = "cooldown" }
		end
		self.Filtrando[player.UserId] = true
		local ok, filtrado = self:Filtrar(limpio, player)
		self.Filtrando[player.UserId] = nil
		if not ok then
			self.Estadisticas.FiltrosFallidos = self.Estadisticas.FiltrosFallidos + 1
			return self:_Rechazo(player, "filtro", "No se pudo filtrar el texto; inténtalo de nuevo en unos segundos.", roomId)
		end
		final = sanearTexto(filtrado, self.MaxCaracteres, self.MaxLineas)
		-- El filtrado cede el hilo: se comprueba de nuevo que siga autorizado.
		if self:RolDe(player, roomId) == nil then
			return self:_Rechazo(player, "sin_turno", "Tu turno en el tablero terminó antes de publicar el texto.")
		end
	end
	local estado = self:_Estado(roomId)
	if estado.Texto == final then
		return { ok = true, datos = { Version = estado.Version, Texto = final, SinCambios = true } }
	end
	estado.Texto = final
	estado.TextoAutor = player.UserId
	self:_MarcarCambio(estado, player)
	self.Estadisticas.Escrituras = self.Estadisticas.Escrituras + 1
	self:_Auditar(player, "TableroTexto", string.format("%s · %d caracteres", roomId, utf8.len(final) or #final))
	self:_Renderizar(roomId, "Texto")
	self:_Difundir(roomId, self:_DatosTexto(estado), player)
	return { ok = true, datos = { Version = estado.Version, Texto = final } }
end

function BoardService:_Plantilla(player, roomId, indice)
	local valor = 0
	if indice ~= nil then
		if typeof(indice) ~= "number" or math.floor(indice) ~= indice or Catalogs.Plantillas[indice] == nil then
			return self:_Rechazo(player, "plantilla_invalida", "Esa plantilla no existe.", indice)
		end
		valor = indice
	end
	local estado = self:_Estado(roomId)
	if estado.Plantilla == valor then
		return { ok = true, datos = { Version = estado.Version, Plantilla = valor, SinCambios = true } }
	end
	estado.Plantilla = valor
	self:_MarcarCambio(estado, player)
	self:_Renderizar(roomId, "Texto")
	self:_Difundir(roomId, self:_DatosTexto(estado), player)
	return { ok = true, datos = { Version = estado.Version, Plantilla = valor } }
end

function BoardService:_Imagen(player, roomId, imagenId)
	local valor = 0
	if imagenId ~= nil then
		if typeof(imagenId) ~= "number" or imagenId ~= imagenId or math.floor(imagenId) ~= imagenId or imagenId < 0 then
			return self:_Rechazo(player, "imagen_invalida", "El id de imagen debe ser un número entero positivo.", imagenId)
		end
		valor = imagenId
	end
	local estado = self:_Estado(roomId)
	if estado.ImagenId == valor then
		return { ok = true, datos = { Version = estado.Version, ImagenId = valor, SinCambios = true } }
	end
	estado.ImagenId = valor
	self:_MarcarCambio(estado, player)
	self.Estadisticas.Imagenes = self.Estadisticas.Imagenes + 1
	self:_Auditar(player, "TableroImagen", roomId .. " · " .. tostring(valor))
	self:_Renderizar(roomId, "Texto")
	self:_Difundir(roomId, self:_DatosTexto(estado), player)
	return { ok = true, datos = { Version = estado.Version, ImagenId = valor } }
end

function BoardService:_Trazo(player, roomId, puntos)
	if typeof(puntos) ~= "table" or #puntos == 0 then
		return self:_Rechazo(player, "trazo_vacio", "El trazo no tiene puntos.")
	end
	if #puntos > self.MaxTrazoPuntos then
		return self:_Rechazo(player, "puntos_invalidos", "El trazo tiene demasiados puntos.", #puntos)
	end
	local primero = puntos[1]
	if typeof(primero) ~= "Vector3" then
		return self:_Rechazo(player, "puntos_invalidos", "El trazo no es válido.")
	end
	local color, grosor = decodificarEstilo(primero.Z, self.ColoresTiza, self.Grosores)
	local tolerancia = self.ToleranciaPunto
	local lista = {}
	local ultimoX, ultimoY = nil, nil
	for i = 1, #puntos do
		local v = puntos[i]
		if typeof(v) ~= "Vector3" then
			return self:_Rechazo(player, "puntos_invalidos", "El trazo no es válido.", i)
		end
		local x, y = v.X, v.Y
		if x ~= x or y ~= y or x < -tolerancia or x > 1 + tolerancia or y < -tolerancia or y > 1 + tolerancia then
			return self:_Rechazo(player, "puntos_invalidos", "Hay puntos fuera del tablero.", string.format("%d (%.3f, %.3f)", i, x, y))
		end
		x = cuantizar(clamp(x, 0, 1)) / CUANTOS
		y = cuantizar(clamp(y, 0, 1)) / CUANTOS
		if ultimoX == nil or x ~= ultimoX or y ~= ultimoY then
			table.insert(lista, { x, y })
			ultimoX, ultimoY = x, y
		end
	end
	self.SiguienteTrazo = self.SiguienteTrazo + 1
	local trazo = {
		Id = self.SiguienteTrazo,
		Puntos = lista,
		Color = color,
		Grosor = grosor,
		Autor = player.UserId,
	}
	trazo.P = codificarPuntos(lista)

	local estado = self:_Estado(roomId)
	table.insert(estado.Trazos, trazo)
	local descartados = {}
	while #estado.Trazos > self.MaxTrazos do
		local viejo = table.remove(estado.Trazos, 1)
		table.insert(descartados, viejo.Id)
	end
	self:_MarcarCambio(estado, player)
	self.Estadisticas.Trazos = self.Estadisticas.Trazos + 1
	self:_RenderTrazo(roomId, trazo, descartados)
	local red = trazoRed(trazo)
	self:_Difundir(roomId, {
		Sub = "Trazo",
		RoomId = roomId,
		Version = estado.Version,
		Trazo = red,
		Descartados = descartados,
		Autor = estado.Autor,
		AutorNombre = estado.AutorNombre,
		Actualizado = estado.Actualizado,
	}, player)
	return { ok = true, datos = { Version = estado.Version, Trazo = red, Descartados = descartados } }
end

-- Docente: borra todo el contenido (la proyección del PC se conserva). Invitado: solo sus trazos y su texto.
function BoardService:_LimpiarPor(player, roomId, rol)
	local estado = self:_Estado(roomId)
	if rol == "Docente" then
		if estado.Texto == "" and estado.Plantilla == 0 and #estado.Trazos == 0 and estado.ImagenId == 0 then
			return { ok = true, datos = { Version = estado.Version, SinCambios = true } }
		end
		estado.Texto = ""
		estado.TextoAutor = 0
		estado.Plantilla = 0
		estado.Trazos = {}
		estado.ImagenId = 0
		self:_MarcarCambio(estado, player)
		self.Estadisticas.Limpiezas = self.Estadisticas.Limpiezas + 1
		self:_Auditar(player, "TableroLimpiar", roomId)
		self:_Renderizar(roomId, "Todo")
		self:_Difundir(roomId, {
			Sub = "Limpiar", RoomId = roomId, Version = estado.Version, Todo = true, Completo = false,
			Autor = estado.Autor, AutorNombre = estado.AutorNombre, Actualizado = estado.Actualizado,
		}, player)
		return { ok = true, datos = { Version = estado.Version, Todo = true } }
	end

	local restantes = {}
	local quitados = 0
	for _, trazo in ipairs(estado.Trazos) do
		if trazo.Autor == player.UserId then
			quitados = quitados + 1
		else
			table.insert(restantes, trazo)
		end
	end
	local textoPropio = estado.Texto ~= "" and estado.TextoAutor == player.UserId
	if quitados == 0 and not textoPropio then
		return { ok = true, datos = { Version = estado.Version, SinCambios = true } }
	end
	estado.Trazos = restantes
	if textoPropio then
		estado.Texto = ""
		estado.TextoAutor = 0
	end
	self:_MarcarCambio(estado, player)
	self:_Auditar(player, "TableroLimpiarPropio", string.format("%s · %d trazos%s", roomId, quitados, textoPropio and " y texto" or ""))
	self:_Renderizar(roomId, "Todo")
	self:_Difundir(roomId, self:Estado(roomId), player)
	return { ok = true, datos = { Version = estado.Version, Todo = false, Quitados = quitados } }
end

---------------------------------------------------------------------------------------------------
-- API para otros servicios
---------------------------------------------------------------------------------------------------

-- Concede (o renueva) el turno de tablero de un aula a un jugador. Un jugador solo tiene turno en un aula y
-- un aula solo tiene un invitado. Devuelve true, expiraServidor | false, motivo.
function BoardService:ConcederTurno(roomId, player, segundos, otorgante)
	if not self:EsAula(roomId) then
		return false, "aula_desconocida"
	end
	if not esJugador(player) or player.Parent == nil then
		return false, "jugador_invalido"
	end
	local duracion = tonumber(segundos) or self.TurnoSeg
	if duracion ~= duracion then
		duracion = self.TurnoSeg
	end
	duracion = clamp(math.floor(duracion + 0.5), self.TurnoMinSeg, self.TurnoMaxSeg)

	local otras = {}
	for otraAula, turno in pairs(self.Turnos) do
		if otraAula ~= roomId and turno.UserId == player.UserId then
			table.insert(otras, otraAula)
		end
	end
	for _, otraAula in ipairs(otras) do
		self:_FinTurno(otraAula, "OtraAula")
	end
	local actual = self.Turnos[roomId]
	if actual and actual.UserId ~= player.UserId then
		self:_FinTurno(roomId, "Reemplazado")
	end

	self.TokenTurno = self.TokenTurno + 1
	local token = self.TokenTurno
	local turno = {
		UserId = player.UserId,
		Nombre = nombreJugador(player),
		Expira = os.clock() + duracion,
		ExpiraServidor = ahoraServidor() + duracion,
		Segundos = duracion,
		Token = token,
		Otorgante = esJugador(otorgante) and otorgante.UserId or nil,
		Concedido = os.time(),
	}
	self.Turnos[roomId] = turno
	task.delay(duracion + 0.05, function()
		local vigente = self.Turnos[roomId]
		if vigente and vigente.Token == token then
			self:_FinTurno(roomId, "Expirado")
		end
	end)

	self:_Difundir(roomId, self:_DatosTurno(roomId, "Concedido"), player)
	self:_Notificar(player, string.format("Tienes turno en el tablero de %s durante %d s.", nombreAula(roomId), duracion), "exito")
	self:_Auditar(esJugador(otorgante) and otorgante or player, "TableroTurno",
		string.format("%s · %s (%d) · %d s", roomId, player.Name, player.UserId, duracion))
	self.TurnoCambiado:Fire(roomId, turno, "Concedido")
	return true, turno.ExpiraServidor
end

-- Retira el turno vigente del aula (si lo hay). Devuelve true si había turno.
function BoardService:RevocarTurno(roomId, motivo)
	if self.Turnos[roomId] == nil then
		return false
	end
	if typeof(motivo) ~= "string" or motivo == "" then
		motivo = "Revocado"
		-- ClassroomService revoca sin motivo al cerrar la sesión (ya marcada como Cerrada): se avisa como tal.
		if self:RequiereSesion() and self:DocenteDe(roomId) == nil then
			motivo = "SesionCerrada"
		end
	end
	return self:_FinTurno(roomId, motivo)
end

function BoardService:_DatosTurno(roomId, motivo)
	local turno = self.Turnos[roomId]
	if turno and os.clock() >= turno.Expira then
		turno = nil
	end
	local datos = {
		Sub = "Turno",
		RoomId = roomId,
		Activo = turno ~= nil,
		Motivo = motivo,
		DocenteUserId = self:DocenteDe(roomId),
		RequiereSesion = self:RequiereSesion(),
	}
	if turno then
		datos.UserId = turno.UserId
		datos.Nombre = turno.Nombre
		datos.Expira = turno.ExpiraServidor
		datos.Segundos = turno.Segundos
	end
	return datos
end

function BoardService:_FinTurno(roomId, motivo)
	local turno = self.Turnos[roomId]
	if not turno then
		return false
	end
	self.Turnos[roomId] = nil
	local player = Players:GetPlayerByUserId(turno.UserId)
	local datos = self:_DatosTurno(roomId, motivo)
	datos.Anterior = turno.UserId
	datos.AnteriorNombre = turno.Nombre
	self:_Difundir(roomId, datos, player)
	local plantilla = MENSAJES_FIN_TURNO[motivo]
	if player and plantilla then
		self:_Notificar(player, string.format(plantilla, nombreAula(roomId)), "info")
	end
	self:_Auditar(player or turno.UserId, "TableroFinTurno", roomId .. " · " .. tostring(motivo))
	self.TurnoCambiado:Fire(roomId, nil, motivo)
	return true
end

function BoardService:_FinTurnosDe(userId, motivo)
	local aulas = {}
	for roomId, turno in pairs(self.Turnos) do
		if turno.UserId == userId then
			table.insert(aulas, roomId)
		end
	end
	for _, roomId in ipairs(aulas) do
		self:_FinTurno(roomId, motivo)
	end
end

-- Borra todo el tablero (texto, plantilla, trazos, imagen y proyección) y retira el turno.
-- Lo llama ClassroomService al cerrar una sesión y este servicio al terminar la jornada.
function BoardService:Limpiar(roomId, motivo)
	if not self:EsAula(roomId) then
		return false, "aula_desconocida"
	end
	if self.Turnos[roomId] then
		self:_FinTurno(roomId, "Limpieza")
	end
	local estado = self.Estados[roomId]
	if estadoVacio(estado) then
		return true
	end
	estado.Texto = ""
	estado.TextoAutor = 0
	estado.Plantilla = 0
	estado.Trazos = {}
	estado.ImagenId = 0
	estado.Proyeccion = ""
	estado.Autor = 0
	estado.AutorNombre = ""
	self:_MarcarCambio(estado, nil)
	self.Estadisticas.Limpiezas = self.Estadisticas.Limpiezas + 1
	self:_Renderizar(roomId, "Todo")
	self:_Difundir(roomId, {
		Sub = "Limpiar", RoomId = roomId, Version = estado.Version, Todo = true, Completo = true,
		Motivo = typeof(motivo) == "string" and motivo or "Sistema", Actualizado = estado.Actualizado,
	})
	self:_Auditar(nil, "TableroReinicio", roomId .. " · " .. tostring(motivo or "Sistema"))
	return true
end

-- Limpia todos los tableros con contenido o turno.
function BoardService:LimpiarTodos(motivo)
	local aulas = {}
	for roomId in pairs(self.Estados) do
		aulas[roomId] = true
	end
	for roomId in pairs(self.Turnos) do
		aulas[roomId] = true
	end
	local n = 0
	for roomId in pairs(aulas) do
		local ok = self:Limpiar(roomId, motivo)
		if ok then
			n = n + 1
		end
	end
	return n
end

-- Texto proyectado (PCService: pantalla de clase). texto vacío/nil quita la proyección. Si se pasa 'player',
-- el texto se filtra a su nombre; si no, se asume ya filtrado por el servicio que llama.
function BoardService:Proyectar(roomId, texto, player)
	if not self:EsAula(roomId) then
		return false, "aula_desconocida"
	end
	local limpio = sanearTexto(tostring(texto or ""), self.MaxCaracteres, self.MaxLineas)
	if limpio ~= "" and esJugador(player) then
		local ok, filtrado = self:Filtrar(limpio, player)
		if not ok then
			self.Estadisticas.FiltrosFallidos = self.Estadisticas.FiltrosFallidos + 1
			return false, "filtro"
		end
		limpio = sanearTexto(filtrado, self.MaxCaracteres, self.MaxLineas)
	end
	local estado = self:_Estado(roomId)
	if estado.Proyeccion == limpio then
		return true
	end
	estado.Proyeccion = limpio
	self:_MarcarCambio(estado, player)
	self:_Renderizar(roomId, "Texto")
	self:_Difundir(roomId, self:_DatosTexto(estado), player)
	return true
end

-- Resumen para métricas y paneles de dirección.
function BoardService:Resumen()
	local tableros, conContenido, trazos = 0, 0, 0
	for _, estado in pairs(self.Estados) do
		tableros = tableros + 1
		trazos = trazos + #estado.Trazos
		if not estadoVacio(estado) then
			conContenido = conContenido + 1
		end
	end
	local turnos = 0
	for _ in pairs(self.Turnos) do
		turnos = turnos + 1
	end
	local copia = {}
	for clave, valor in pairs(self.Estadisticas) do
		copia[clave] = valor
	end
	copia.Tableros = tableros
	copia.ConContenido = conContenido
	copia.TrazosGuardados = trazos
	copia.TurnosActivos = turnos
	copia.FramesFisicos = self.FramesGlobal
	return copia
end

---------------------------------------------------------------------------------------------------
-- Jugadores y ciclo periódico
---------------------------------------------------------------------------------------------------
function BoardService:AlSalir(player)
	local userId = player.UserId
	self:_FinTurnosDe(userId, "Salida")
	self.Enviado[userId] = nil
	self.UltimaAccion[userId] = nil
	self.Filtrando[userId] = nil
end

-- Adelanta el siguiente ciclo (agrupa varios avisos en uno).
function BoardService:_ProgramarCiclo()
	if self.CicloPendiente or not self.Activo then
		return
	end
	self.CicloPendiente = true
	task.delay(0.3, function()
		self.CicloPendiente = false
		local ok, err = pcall(self._Ciclo, self)
		if not ok then
			warn(PREFIJO .. " Error en el ciclo: " .. tostring(err))
		end
	end)
end

function BoardService:_Ciclo()
	-- 1. Turnos vencidos (respaldo de task.delay).
	local vencidos = {}
	local ahora = os.clock()
	for roomId, turno in pairs(self.Turnos) do
		if ahora >= turno.Expira then
			table.insert(vencidos, roomId)
		end
	end
	for _, roomId in ipairs(vencidos) do
		self:_FinTurno(roomId, "Expirado")
	end

	-- 2. Quien entra en un aula (o tiene una copia vieja) recibe el estado completo.
	local presentes = {}
	for _, player in ipairs(Players:GetPlayers()) do
		local roomId = self:AulaDePosicion(posicionDe(player))
		if roomId then
			presentes[roomId] = true
			local estado = self.Estados[roomId]
			local version = estado and estado.Version or 0
			local enviado = self.Enviado[player.UserId]
			if not enviado or enviado.RoomId ~= roomId or enviado.Version ~= version then
				self:EnviarEstado(player, roomId)
			end
		end
	end

	-- 3. Cambios de docente de la sesión (apertura/cierre) en aulas con gente: avisa y cierra turnos huérfanos.
	if self:RequiereSesion() then
		for roomId in pairs(self.Turnos) do
			presentes[roomId] = true
		end
		for roomId in pairs(presentes) do
			local docente = self:DocenteDe(roomId) or 0
			local anterior = self.DocenteConocido[roomId]
			self.DocenteConocido[roomId] = docente
			if anterior ~= nil and anterior ~= docente then
				if docente == 0 and self.Turnos[roomId] then
					self:_FinTurno(roomId, "SesionCerrada")
				else
					self:_Difundir(roomId, self:_DatosTurno(roomId, "Sesion"))
				end
			end
		end
	end
end

---------------------------------------------------------------------------------------------------
-- Tablero físico (SurfaceGui creada por MapService)
---------------------------------------------------------------------------------------------------
local NOMBRE_VISTA = "ColegioRP_TableroVista"

local function nuevoTexto(nombre, padre, props)
	local label = Instance.new("TextLabel")
	label.Name = nombre
	label.BackgroundTransparency = 1
	label.BorderSizePixel = 0
	label.RichText = false
	label.TextWrapped = true
	label.TextScaled = true
	label.Font = props.Fuente or FUENTE_TIZA
	label.TextColor3 = props.Color or BoardService.ColorTexto
	label.TextXAlignment = props.AlineacionX or Enum.TextXAlignment.Left
	label.TextYAlignment = props.AlineacionY or Enum.TextYAlignment.Top
	label.Position = props.Position or UDim2.fromScale(0, 0)
	label.Size = props.Size or UDim2.fromScale(1, 1)
	label.ZIndex = props.ZIndex or 3
	label.Text = ""
	if props.MaxTexto then
		local limite = Instance.new("UITextSizeConstraint")
		limite.MaxTextSize = math.max(8, math.floor(props.MaxTexto))
		limite.MinTextSize = 6
		limite.Parent = label
	end
	label.Parent = padre
	return label
end

function BoardService:_CrearVista(roomId, gui, tablero)
	local anterior = gui:FindFirstChild(NOMBRE_VISTA)
	if anterior then
		pcall(function()
			anterior:Destroy()
		end)
	end
	local alto = 6
	local aspecto = self.AspectoPorDefecto
	if typeof(tablero) == "Instance" and tablero:IsA("BasePart") and tablero.Size.Y > 0 then
		alto = tablero.Size.Y
		aspecto = tablero.Size.X / tablero.Size.Y
	end
	local pixeles = 50
	pcall(function()
		pixeles = gui.PixelsPerStud
	end)
	local altoPx = math.max(60, alto * pixeles)

	local raiz = Instance.new("Frame")
	raiz.Name = NOMBRE_VISTA
	raiz.BackgroundColor3 = self.ColorFondo
	raiz.BackgroundTransparency = self.TransparenciaFondo
	raiz.BorderSizePixel = 0
	raiz.Size = UDim2.fromScale(1, 1)
	raiz.ClipsDescendants = true
	raiz.ZIndex = 1
	raiz.Visible = false
	raiz:SetAttribute("RoomId", roomId)

	local imagen = Instance.new("ImageLabel")
	imagen.Name = "Imagen"
	imagen.BackgroundTransparency = 1
	imagen.BorderSizePixel = 0
	imagen.ScaleType = Enum.ScaleType.Fit
	imagen.AnchorPoint = Vector2.new(0.5, 0.5)
	imagen.Position = UDim2.fromScale(0.5, 0.5)
	imagen.Size = UDim2.fromScale(0.92, 0.86)
	imagen.ZIndex = 2
	imagen.Visible = false
	imagen.Parent = raiz

	local encabezado = nuevoTexto("Plantilla", raiz, {
		Fuente = FUENTE_TITULO, Color = self.ColorPlantilla, Position = UDim2.fromScale(0.04, 0.03),
		Size = UDim2.fromScale(0.92, 0.12), AlineacionY = Enum.TextYAlignment.Center, MaxTexto = altoPx * 0.1,
	})
	encabezado.Visible = false
	local texto = nuevoTexto("Texto", raiz, {
		Position = UDim2.fromScale(0.04, 0.05), Size = UDim2.fromScale(0.92, 0.85), MaxTexto = altoPx * 0.11,
	})

	local capa = Instance.new("Frame")
	capa.Name = "Trazos"
	capa.BackgroundTransparency = 1
	capa.BorderSizePixel = 0
	capa.Size = UDim2.fromScale(1, 1)
	capa.ClipsDescendants = true
	capa.ZIndex = 4
	capa.Parent = raiz

	local proyeccion = Instance.new("Frame")
	proyeccion.Name = "Proyeccion"
	proyeccion.BackgroundColor3 = Color3.fromRGB(18, 34, 26)
	proyeccion.BackgroundTransparency = 0.15
	proyeccion.BorderSizePixel = 0
	proyeccion.Position = UDim2.fromScale(0.03, 0.8)
	proyeccion.Size = UDim2.fromScale(0.94, 0.12)
	proyeccion.ZIndex = 5
	proyeccion.Visible = false
	proyeccion.Parent = raiz
	local textoProyeccion = nuevoTexto("Texto", proyeccion, {
		Fuente = FUENTE_TEXTO, Color = Color3.fromRGB(200, 230, 255), Position = UDim2.fromScale(0.02, 0.08),
		Size = UDim2.fromScale(0.96, 0.84), AlineacionY = Enum.TextYAlignment.Center, ZIndex = 6, MaxTexto = altoPx * 0.06,
	})

	local autor = nuevoTexto("Autor", raiz, {
		Fuente = FUENTE_TEXTO, Color = Color3.fromRGB(170, 190, 175), Position = UDim2.fromScale(0.5, 0.935),
		Size = UDim2.fromScale(0.48, 0.055), AlineacionX = Enum.TextXAlignment.Right,
		AlineacionY = Enum.TextYAlignment.Center, ZIndex = 5, MaxTexto = altoPx * 0.04,
	})

	raiz.Parent = gui
	return {
		RoomId = roomId,
		Gui = gui,
		Raiz = raiz,
		Imagen = imagen,
		Encabezado = encabezado,
		Texto = texto,
		Capa = capa,
		Proyeccion = proyeccion,
		ProyeccionTexto = textoProyeccion,
		Autor = autor,
		Aspecto = aspecto,
		Frames = {}, -- trazoId -> { Frame... }
		Orden = {}, -- trazoIds dibujados, del más antiguo al más reciente
		Total = 0,
		Nueva = true,
	}
end

function BoardService:_DestruirVista(roomId)
	local vista = self.Vistas[roomId]
	if not vista then
		return
	end
	self.Vistas[roomId] = nil
	self.FramesGlobal = math.max(0, self.FramesGlobal - vista.Total)
	vista.Total = 0
	pcall(function()
		vista.Raiz:Destroy()
	end)
end

-- Vista actual del tablero físico del aula (la crea o la rehace si la SurfaceGui cambió). nil si no hay tablero.
function BoardService:_Vista(roomId)
	local aula = self:_InfoAula(roomId)
	local gui = aula and aula.TableroGui
	if typeof(gui) ~= "Instance" or gui.Parent == nil then
		if self.Vistas[roomId] then
			self:_DestruirVista(roomId)
		end
		return nil
	end
	local vista = self.Vistas[roomId]
	if vista and vista.Gui == gui and vista.Raiz.Parent == gui then
		return vista
	end
	if vista then
		self:_DestruirVista(roomId)
	end
	vista = self:_CrearVista(roomId, gui, aula.Tablero)
	self.Vistas[roomId] = vista
	return vista
end

-- Segmento de tiza entre dos puntos normalizados, con posición y tamaño en escala (se adapta a cualquier
-- resolución). aspecto = ancho / alto del lienzo; grosor = fracción del alto.
function BoardService.CrearSegmento(padre, a, b, color, grosor, aspecto, zIndex)
	local dx = b[1] - a[1]
	local dy = b[2] - a[2]
	local dyAncho = dy / aspecto
	local largo = math.sqrt(dx * dx + dyAncho * dyAncho)
	local frame = Instance.new("Frame")
	frame.Name = "T"
	frame.BorderSizePixel = 0
	frame.BackgroundColor3 = color
	frame.AnchorPoint = Vector2.new(0.5, 0.5)
	frame.Position = UDim2.fromScale((a[1] + b[1]) / 2, (a[2] + b[2]) / 2)
	frame.Size = UDim2.fromScale(largo + grosor / aspecto, grosor)
	frame.Rotation = math.deg(math.atan2(dy, dx * aspecto))
	frame.ZIndex = zIndex or 4
	frame.Parent = padre
	return frame
end

function BoardService:_FramesDeTrazo(vista, trazo)
	local puntos = trazo.Puntos
	local n = #puntos
	local color = self.ColoresTiza[trazo.Color] or self.ColoresTiza[1]
	local grosor = self.Grosores[trazo.Grosor] or self.Grosores[2]
	local frames = {}
	if n == 0 then
		return frames
	end
	if n == 1 then
		table.insert(frames, BoardService.CrearSegmento(vista.Capa, puntos[1], puntos[1], color, grosor, vista.Aspecto, 4))
		return frames
	end
	local i = 1
	while i < n do
		local j = math.min(i + self.PuntosPorFrame, n)
		table.insert(frames, BoardService.CrearSegmento(vista.Capa, puntos[i], puntos[j], color, grosor, vista.Aspecto, 4))
		i = j
	end
	return frames
end

function BoardService:_QuitarFramesTrazo(vista, trazoId)
	local frames = vista.Frames[trazoId]
	if not frames then
		return
	end
	vista.Frames[trazoId] = nil
	for _, frame in ipairs(frames) do
		frame:Destroy()
	end
	vista.Total = math.max(0, vista.Total - #frames)
	self.FramesGlobal = math.max(0, self.FramesGlobal - #frames)
	for i, id in ipairs(vista.Orden) do
		if id == trazoId then
			table.remove(vista.Orden, i)
			break
		end
	end
end

-- Dibuja un trazo respetando los límites (quita los trazos dibujados más antiguos si hace falta).
function BoardService:_DibujarTrazo(vista, trazo)
	local necesarios = framesNecesarios(#trazo.Puntos, self.PuntosPorFrame)
	local function excede()
		return vista.Total + necesarios > self.MaxFramesTablero or self.FramesGlobal + necesarios > self.MaxFramesGlobal
	end
	while excede() and #vista.Orden > 0 do
		self:_QuitarFramesTrazo(vista, vista.Orden[1])
	end
	if excede() then
		return false
	end
	local frames = self:_FramesDeTrazo(vista, trazo)
	vista.Frames[trazo.Id] = frames
	table.insert(vista.Orden, trazo.Id)
	vista.Total = vista.Total + #frames
	self.FramesGlobal = self.FramesGlobal + #frames
	return true
end

function BoardService:_RenderTrazosCompleto(vista, estado)
	for _, id in ipairs(table.clone(vista.Orden)) do
		self:_QuitarFramesTrazo(vista, id)
	end
	vista.Frames = {}
	vista.Orden = {}
	if not estado then
		return
	end
	-- Se eligen los trazos más recientes que caben en el presupuesto y se dibujan en orden cronológico.
	local presupuesto = math.min(self.MaxFramesTablero, math.max(0, self.MaxFramesGlobal - self.FramesGlobal))
	local desde = #estado.Trazos + 1
	local suma = 0
	for i = #estado.Trazos, 1, -1 do
		local n = framesNecesarios(#estado.Trazos[i].Puntos, self.PuntosPorFrame)
		if suma + n > presupuesto then
			break
		end
		suma = suma + n
		desde = i
	end
	for i = desde, #estado.Trazos do
		self:_DibujarTrazo(vista, estado.Trazos[i])
	end
end

function BoardService:_RenderTextos(vista, estado)
	local plantilla = Catalogs.Plantillas[estado.Plantilla]
	vista.Encabezado.Visible = plantilla ~= nil
	vista.Encabezado.Text = plantilla or ""
	local proyecta = estado.Proyeccion ~= ""
	local arriba = 0.05
	if plantilla then
		arriba = 0.16
	end
	local abajo = 0.92
	if proyecta then
		abajo = 0.78
	end
	vista.Texto.Position = UDim2.fromScale(0.04, arriba)
	vista.Texto.Size = UDim2.fromScale(0.92, math.max(0.1, abajo - arriba))
	vista.Texto.Text = estado.Texto
	vista.Proyeccion.Visible = proyecta
	vista.ProyeccionTexto.Text = proyecta and ("Proyección: " .. estado.Proyeccion) or ""
	if estado.ImagenId > 0 then
		vista.Imagen.Image = string.format("rbxthumb://type=Asset&id=%.0f&w=420&h=420", estado.ImagenId)
		vista.Imagen.Visible = true
	else
		vista.Imagen.Image = ""
		vista.Imagen.Visible = false
	end
	if estado.AutorNombre ~= "" then
		vista.Autor.Text = "Última edición: " .. estado.AutorNombre
	else
		vista.Autor.Text = ""
	end
end

-- Actualiza el tablero físico. que = "Texto" (solo textos, plantilla, imagen y proyección) | "Todo".
function BoardService:_Renderizar(roomId, que)
	local ok, err = pcall(function()
		local vista = self:_Vista(roomId)
		if not vista then
			return
		end
		local estado = self.Estados[roomId]
		if que == "Todo" or vista.Nueva then
			self:_RenderTrazosCompleto(vista, estado)
			vista.Nueva = false
		end
		if estado then
			self:_RenderTextos(vista, estado)
		end
		vista.Raiz.Visible = not estadoVacio(estado)
	end)
	if not ok then
		warn(PREFIJO .. " No se pudo dibujar el tablero de " .. tostring(roomId) .. ": " .. tostring(err))
	end
end

-- Añade un trazo al tablero físico y quita los descartados (sin redibujar todo).
function BoardService:_RenderTrazo(roomId, trazo, descartados)
	local ok, err = pcall(function()
		local vista = self:_Vista(roomId)
		if not vista then
			return
		end
		if vista.Nueva then
			self:_RenderTrazosCompleto(vista, self.Estados[roomId])
			self:_RenderTextos(vista, self.Estados[roomId])
			vista.Nueva = false
		else
			for _, id in ipairs(descartados or {}) do
				self:_QuitarFramesTrazo(vista, id)
			end
			self:_DibujarTrazo(vista, trazo)
		end
		vista.Raiz.Visible = not estadoVacio(self.Estados[roomId])
	end)
	if not ok then
		warn(PREFIJO .. " No se pudo dibujar el trazo en " .. tostring(roomId) .. ": " .. tostring(err))
	end
end

-- Redibuja todos los tableros físicos (tras reconstruir el mapa).
function BoardService:RedibujarTodo()
	local aulas = {}
	for roomId in pairs(self.Vistas) do
		aulas[roomId] = true
	end
	for roomId in pairs(self.Estados) do
		aulas[roomId] = true
	end
	for roomId in pairs(aulas) do
		self:_DestruirVista(roomId)
		if self.Estados[roomId] and not estadoVacio(self.Estados[roomId]) then
			self:_Renderizar(roomId, "Todo")
		end
	end
end

return BoardService
]=] }
FUENTES["ServerScriptService/ColegioRP/Services/CafeteriaService"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ServerScriptService.ColegioRP.Services.CafeteriaService
	Tipo: ModuleScript
	Tienda escolar / cafetería (docs/ARQUITECTURA.md §6, prueba P9). Inventario y precios en memoria del servidor a
	partir de Catalogs.Productos; puesto Abierto/Cerrado por el vendedor (VendedorUserId) o atención automática
	(NPC) si no hay vendedor conectado y Config.Cafeteria.NPCVendedorSiNoHayVendedor. El ProximityPrompt del
	mostrador (MapService o uno propio) abre el panel del cliente con el catálogo. CafeteriaPurchase: compra
	atómica (producto, cantidad, stock, precio DEL SERVIDOR, distancia al mostrador, puesto abierto, cooldown;
	EconomyService:Debitar ANTES de descontar stock y reembolso si el descuento falla) con recibo. CafeteriaManage:
	abrir/cerrar, precios en [PrecioMin, PrecioMax], reposición, inventario y cierre de caja. Emite "Cafeteria"
	{ Sub = "Estado" | "Recibo" | "Inventario" | "AbrirPanel" }.
]]

local Players = game:GetService("Players")

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RP = ReplicatedStorage:WaitForChild("ColegioRP")
local Shared = RP:WaitForChild("Shared")
local Config = require(Shared:WaitForChild("Config"))
local Catalogs = require(Shared:WaitForChild("Catalogs"))
local MapaLogico = require(Shared:WaitForChild("MapaLogico"))
local RoleDefinitions = require(Shared:WaitForChild("RoleDefinitions"))
local RemoteContracts = require(Shared:WaitForChild("RemoteContracts"))
local Util = Shared:WaitForChild("Util")
local Signal = require(Util:WaitForChild("Signal"))
local Maid = require(Util:WaitForChild("Maid"))
local Zones = require(Util:WaitForChild("Zones"))
local Format = require(Util:WaitForChild("Format"))

local CafeteriaService = {}
CafeteriaService.Nombre = "CafeteriaService"

local PREFIJO = "[ColegioRP][CafeteriaService]"
local CFG = Config.Cafeteria or {}

CafeteriaService.ZonaTienda = "TIENDA"
CafeteriaService.PrecioMin = math.max(0, math.floor(tonumber(CFG.PrecioMin) or 1))
CafeteriaService.PrecioMax = math.max(CafeteriaService.PrecioMin, math.floor(tonumber(CFG.PrecioMax) or 200))
CafeteriaService.CooldownCompra = math.max(0, tonumber(CFG.CooldownCompra) or 3)
CafeteriaService.CantidadMax = math.max(1, math.floor(tonumber(CFG.CantidadMaxPorCompra) or 5))
CafeteriaService.DistanciaCompra = tonumber(Config.Distancias and Config.Distancias.Mostrador) or 14
CafeteriaService.DistanciaGestion = 20 -- el vendedor abre y repone desde el puesto
CafeteriaService.DistanciaCierrePanel = 20 -- el cliente cierra el panel al alejarse más
CafeteriaService.Tolerancia = 2
CafeteriaService.FactorStockMax = 2 -- stock máximo = stock inicial del catálogo x factor
CafeteriaService.ReposicionMax = 100 -- unidades máximas por reposición
CafeteriaService.CooldownReponerSeg = 2
CafeteriaService.IntervaloPromptSeg = 0.5
CafeteriaService.TamanoVentas = 200
CafeteriaService.ObservadorSeg = 600 -- tiempo que un jugador recibe actualizaciones tras abrir el panel

local MENSAJES = {
	producto_inexistente = "Ese producto no existe en la tienda.",
	cantidad_invalida = "Cantidad no válida (entre 1 y %d).",
	lejos = "Acércate al mostrador de la tienda para comprar.",
	lejos_gestion = "Debes estar en el puesto de la tienda.",
	sin_personaje = "Tu personaje no está disponible en este momento.",
	cerrado = "La tienda está cerrada.",
	cerrado_vendedor = "La tienda está cerrada: el vendedor aún no la ha abierto.",
	cooldown = "Espera %d s antes de otra compra.",
	sin_stock = "No queda stock suficiente de %s (quedan %d).",
	saldo_insuficiente = "No te alcanza: cuesta %s y tienes %s.",
	en_curso = "Ya tienes una compra en curso.",
	perfil = "Tu perfil aún se está cargando. Inténtalo en unos segundos.",
	pago = "No se pudo cobrar la compra. No se descontó nada.",
	sin_economia = "La economía no está disponible ahora mismo.",
	permiso = "No tienes permiso para esta acción.",
	precio_invalido = "El precio debe estar entre %d y %d.",
	reponer_espera = "Espera un momento antes de volver a reponer.",
	reponer_lleno = "El inventario ya está lleno.",
	accion_invalida = "Acción no válida.",
	error_interno = "No se pudo completar la operación. Inténtalo de nuevo.",
}

---------------------------------------------------------------------------------------------------
-- Utilidades
---------------------------------------------------------------------------------------------------
local function esJugador(player)
	return typeof(player) == "Instance" and player:IsA("Player")
end

local function esFinito(n)
	return typeof(n) == "number" and n == n and n ~= math.huge and n ~= -math.huge
end

local function posicionDe(player)
	if not esJugador(player) then
		return nil
	end
	local personaje = player.Character
	if not personaje then
		return nil
	end
	local raiz = personaje:FindFirstChild("HumanoidRootPart") or personaje.PrimaryPart
	if raiz and raiz:IsA("BasePart") then
		return raiz.Position
	end
	return nil
end

-- Posición mundial de una instancia (BasePart, Attachment o Model) o nil.
local function posicionInstancia(instancia)
	if typeof(instancia) ~= "Instance" or instancia.Parent == nil then
		return nil
	end
	if instancia:IsA("BasePart") then
		return instancia.Position
	end
	if instancia:IsA("Attachment") then
		return instancia.WorldPosition
	end
	if instancia:IsA("Model") then
		local ok, pivote = pcall(function()
			return instancia:GetPivot()
		end)
		if ok then
			return pivote.Position
		end
	end
	return nil
end

local function fallo(codigo, ...)
	local plantilla = MENSAJES[codigo] or MENSAJES.error_interno
	local ok, mensaje = pcall(string.format, plantilla, ...)
	if not ok then
		mensaje = plantilla
	end
	return false, codigo, mensaje
end

local function nuevaCaja()
	return { Desde = os.time(), Ventas = 0, Unidades = 0, Ingresos = 0, Reembolsos = 0, PorProducto = {} }
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function CafeteriaService:Init(registro)
	self.registro = registro
	self.Productos = {} -- id -> producto en memoria
	self.Orden = {}
	for _, base in ipairs(Catalogs.Productos or {}) do
		if typeof(base) == "table" and typeof(base.Id) == "string" and not self.Productos[base.Id] then
			local stock = math.max(0, math.floor(tonumber(base.Stock) or 0))
			local precio = math.clamp(math.floor(tonumber(base.Precio) or self.PrecioMin), self.PrecioMin, self.PrecioMax)
			self.Productos[base.Id] = {
				Id = base.Id,
				Nombre = tostring(base.Nombre or base.Id),
				Categoria = tostring(base.Categoria or ""),
				Descripcion = tostring(base.Descripcion or ""),
				Precio = precio,
				PrecioBase = precio,
				Stock = stock,
				StockInicial = stock,
				StockMax = math.max(stock * self.FactorStockMax, stock, 10),
				Vendidos = 0,
			}
			table.insert(self.Orden, base.Id)
		end
	end
	self.AbiertoManual = false
	self.VendedorUserId = nil
	self.VendedorNombre = nil
	self.UltimaCompra = {} -- userId -> os.clock()
	self.Comprando = {} -- userId -> true (bloqueo de compra)
	self.UltimaGestion = {} -- userId -> os.clock() de la última reposición
	self.UltimoPrompt = {} -- userId -> os.clock()
	self.Observadores = {} -- userId -> os.clock() en que abrió el panel
	self.VentasBuffer = table.create(self.TamanoVentas)
	self.IndiceVentas = 0
	self.TotalVentas = 0
	self.SiguienteRecibo = 0
	self.Caja = nuevaCaja()
	self.Estadisticas = { Ventas = 0, Unidades = 0, Ingresos = 0, Reembolsos = 0, Rechazos = 0 }
	self.Cambiado = Signal.new() -- (estado)
	self.Vendido = Signal.new() -- (player, recibo)
	self.maidPrompt = Maid.new()
	self.Conexiones = {}
	self.Activo = true
	self._firmaEstado = ""
	self._estadoPendiente = false
	self._inventarioPendiente = false
	self.Puesto = nil -- { Parte, Prompt }
end

function CafeteriaService:Start()
	local RemoteService = self:_S("RemoteService")
	if RemoteService and typeof(RemoteService.Registrar) == "function" then
		RemoteService:Registrar("CafeteriaPurchase", function(player, datos)
			return self:ManejarCompra(player, datos)
		end)
		RemoteService:Registrar("CafeteriaManage", function(player, datos)
			return self:ManejarGestion(player, datos)
		end)
	else
		warn(PREFIJO .. " RemoteService no disponible: CafeteriaPurchase y CafeteriaManage no tendrán handler.")
	end

	local okPrompt, errPrompt = pcall(self.EnlazarPrompt, self)
	if not okPrompt then
		warn(PREFIJO .. " No se pudo enlazar el prompt del mostrador: " .. tostring(errPrompt))
	end
	local MapService = self:_S("MapService")
	if MapService and typeof(MapService.Construido) == "table" and typeof(MapService.Construido.Connect) == "function" then
		table.insert(self.Conexiones, MapService.Construido:Connect(function()
			task.defer(function()
				local ok, err = pcall(self.EnlazarPrompt, self)
				if not ok then
					warn(PREFIJO .. " Error al reenlazar el prompt: " .. tostring(err))
				end
			end)
		end))
	end

	local SchoolDay = self:_S("SchoolDayService")
	if SchoolDay and typeof(SchoolDay.JornadaTerminada) == "table" and typeof(SchoolDay.JornadaTerminada.Connect) == "function" then
		table.insert(self.Conexiones, SchoolDay.JornadaTerminada:Connect(function()
			pcall(self.Reabastecer, self, "Nueva jornada")
		end))
	end

	local RoleService = self:_S("RoleService")
	if RoleService and typeof(RoleService.CargoCambiado) == "table" and typeof(RoleService.CargoCambiado.Connect) == "function" then
		table.insert(self.Conexiones, RoleService.CargoCambiado:Connect(function(player)
			pcall(self._RevisarVendedor, self, player)
		end))
	end

	table.insert(self.Conexiones, Players.PlayerRemoving:Connect(function(player)
		local userId = player.UserId
		self.Comprando[userId] = nil
		self.UltimaCompra[userId] = nil
		self.UltimoPrompt[userId] = nil
		self.Observadores[userId] = nil
		self.UltimaGestion[userId] = nil
		if self.VendedorUserId == userId then
			self.AbiertoManual = false
			self.VendedorUserId = nil
			self.VendedorNombre = nil
			self:_Auditar(nil, "TiendaCerrada", "El vendedor " .. player.Name .. " salió del servidor")
			self:_ProgramarEstado()
		end
	end))

	task.spawn(function()
		while self.Activo do
			task.wait(2)
			local ok, err = pcall(self._Tick, self)
			if not ok then
				warn(PREFIJO .. " Error en el ciclo de la tienda: " .. tostring(err))
			end
		end
	end)
	self._firmaEstado = self:_FirmaEstado()
end

function CafeteriaService:_S(nombre)
	local registro = self.registro
	if typeof(registro) ~= "table" or typeof(registro.Get) ~= "function" then
		return nil
	end
	local ok, servicio = pcall(registro.Get, nombre)
	if ok and typeof(servicio) == "table" then
		return servicio
	end
	return nil
end

function CafeteriaService:_Auditar(player, accion, detalle)
	local AuditLog = self:_S("AuditLogService")
	if AuditLog and typeof(AuditLog.Registrar) == "function" then
		pcall(AuditLog.Registrar, AuditLog, "Economia", player, accion, detalle)
	end
end

function CafeteriaService:_Enviar(player, tipo, datos)
	local RemoteService = self:_S("RemoteService")
	if RemoteService and typeof(RemoteService.Enviar) == "function" and esJugador(player) then
		pcall(RemoteService.Enviar, RemoteService, player, tipo, datos)
	end
end

function CafeteriaService:_Notificar(player, texto, nivel, duracion)
	self:_Enviar(player, "Notificacion", { Texto = texto, Nivel = nivel or "info", Duracion = duracion or 5 })
end

function CafeteriaService:_Tiene(player, permiso)
	local RoleService = self:_S("RoleService")
	if RoleService and typeof(RoleService.Tiene) == "function" then
		local ok, tiene = pcall(RoleService.Tiene, RoleService, player, permiso)
		return ok and tiene == true
	end
	return esJugador(player) and RoleDefinitions.Tiene(player:GetAttribute("Cargo"), permiso)
end

-- ¿Puede fijar precios? cafeteria.precios (lo exige RemoteContracts para "Precio") o el propio vendedor
-- si el contrato no fija permiso para esa acción.
function CafeteriaService:PuedeFijarPrecios(player)
	if self:_Tiene(player, "cafeteria.precios") then
		return true
	end
	local permiso = RemoteContracts.PermisoPara("CafeteriaManage", { Accion = "Precio" })
	if permiso == nil then
		return self:_Tiene(player, "cafeteria.vender")
	end
	if permiso ~= RemoteContracts.DENEGADO and permiso ~= "cafeteria.precios" then
		return self:_Tiene(player, permiso) and self:_Tiene(player, "cafeteria.vender")
	end
	return false
end

function CafeteriaService:_HayVendedor()
	local RoleService = self:_S("RoleService")
	if RoleService and typeof(RoleService.ConPermiso) == "function" then
		local ok, lista = pcall(RoleService.ConPermiso, RoleService, "cafeteria.vender")
		if ok and typeof(lista) == "table" then
			return #lista > 0
		end
	end
	for _, player in ipairs(Players:GetPlayers()) do
		if RoleDefinitions.Tiene(player:GetAttribute("Cargo"), "cafeteria.vender") then
			return true
		end
	end
	return false
end

-- Si el vendedor que abrió perdió el cargo, el puesto se cierra.
function CafeteriaService:_RevisarVendedor(player)
	if not self.VendedorUserId then
		return
	end
	if player and player.UserId ~= self.VendedorUserId then
		return
	end
	local vendedor = Players:GetPlayerByUserId(self.VendedorUserId)
	if not vendedor or not self:_Tiene(vendedor, "cafeteria.vender") then
		self.AbiertoManual = false
		self.VendedorUserId = nil
		self.VendedorNombre = nil
		self:_Auditar(vendedor, "TiendaCerrada", "El vendedor dejó el cargo")
		self:_ProgramarEstado()
	end
end

function CafeteriaService:_Tick()
	self:_RevisarVendedor(nil)
	local ahora = os.clock()
	for userId, desde in pairs(self.Observadores) do
		if ahora - desde > self.ObservadorSeg or not Players:GetPlayerByUserId(userId) then
			self.Observadores[userId] = nil
		end
	end
	-- Cambios de modo (llega o se va el último vendedor) -> se avisa a quien mira la tienda.
	local firma = self:_FirmaEstado()
	if firma ~= self._firmaEstado then
		self:_ProgramarEstado()
	end
end

---------------------------------------------------------------------------------------------------
-- Estado e inventario
---------------------------------------------------------------------------------------------------

-- { Abierto, Modo = "Vendedor" | "NPC" | "Cerrado", VendedorUserId, Vendedor, HayVendedor, AbiertoManual }
function CafeteriaService:Estado()
	local hayVendedor = self:_HayVendedor()
	local abierto, modo = false, "Cerrado"
	local vendedorActivo = self.VendedorUserId and Players:GetPlayerByUserId(self.VendedorUserId)
	if self.AbiertoManual and vendedorActivo then
		abierto, modo = true, "Vendedor"
	elseif not hayVendedor and CFG.NPCVendedorSiNoHayVendedor ~= false then
		abierto, modo = true, "NPC"
	end
	local nombre = nil
	if modo == "Vendedor" then
		nombre = self.VendedorNombre
	elseif modo == "NPC" then
		nombre = "Atención automática"
	end
	return {
		Abierto = abierto,
		Modo = modo,
		VendedorUserId = self.VendedorUserId,
		Vendedor = nombre,
		HayVendedor = hayVendedor,
		AbiertoManual = self.AbiertoManual,
	}
end

function CafeteriaService:_FirmaEstado()
	local e = self:Estado()
	return tostring(e.Abierto) .. "|" .. e.Modo .. "|" .. tostring(e.VendedorUserId)
end

-- Catálogo público (sin datos internos), en el orden de Catalogs.Productos.
function CafeteriaService:Catalogo()
	local lista = {}
	for _, id in ipairs(self.Orden) do
		local p = self.Productos[id]
		table.insert(lista, {
			Id = p.Id, Nombre = p.Nombre, Categoria = p.Categoria, Descripcion = p.Descripcion,
			Precio = p.Precio, Stock = p.Stock,
		})
	end
	return lista
end

-- Inventario completo (vendedor / finanzas).
function CafeteriaService:Inventario()
	local lista = {}
	for _, id in ipairs(self.Orden) do
		local p = self.Productos[id]
		table.insert(lista, {
			Id = p.Id, Nombre = p.Nombre, Categoria = p.Categoria, Descripcion = p.Descripcion,
			Precio = p.Precio, PrecioBase = p.PrecioBase, Stock = p.Stock, StockInicial = p.StockInicial,
			StockMax = p.StockMax, Vendidos = p.Vendidos,
		})
	end
	return lista
end

function CafeteriaService:ResumenCaja()
	local caja = self.Caja
	local productos = {}
	for id, datos in pairs(caja.PorProducto) do
		table.insert(productos, { Id = id, Nombre = datos.Nombre, Unidades = datos.Unidades, Ingresos = datos.Ingresos })
	end
	table.sort(productos, function(a, b)
		if a.Ingresos == b.Ingresos then
			return a.Id < b.Id
		end
		return a.Ingresos > b.Ingresos
	end)
	return {
		Desde = caja.Desde,
		Hasta = os.time(),
		Ventas = caja.Ventas,
		Unidades = caja.Unidades,
		Ingresos = caja.Ingresos,
		Reembolsos = caja.Reembolsos,
		Productos = productos,
	}
end

function CafeteriaService:Snapshot()
	return {
		Estado = self:Estado(),
		Catalogo = self:Catalogo(),
		Caja = self:ResumenCaja(),
		TotalVentas = self.TotalVentas,
		Limites = self:_Limites(),
	}
end

-- Últimos n recibos (copia, el más reciente primero).
function CafeteriaService:Ventas(n)
	local limite = math.clamp(math.floor(tonumber(n) or 50), 1, self.TamanoVentas)
	local lista = {}
	local disponibles = math.min(self.TotalVentas, self.TamanoVentas)
	local indice = self.IndiceVentas
	for _ = 1, math.min(limite, disponibles) do
		local v = self.VentasBuffer[indice]
		if v then
			local items = {}
			for _, item in ipairs(v.Items) do
				table.insert(items, { Id = item.Id, Nombre = item.Nombre, Cantidad = item.Cantidad, PrecioUnitario = item.PrecioUnitario, Subtotal = item.Subtotal })
			end
			table.insert(lista, {
				Id = v.Id, Fecha = v.Fecha, UserId = v.UserId, Comprador = v.Comprador, Items = items,
				Total = v.Total, Modo = v.Modo, Vendedor = v.Vendedor,
			})
		end
		indice = indice - 1
		if indice < 1 then
			indice = self.TamanoVentas
		end
	end
	return lista
end

function CafeteriaService:_Limites()
	return {
		PrecioMin = self.PrecioMin,
		PrecioMax = self.PrecioMax,
		CantidadMax = self.CantidadMax,
		Cooldown = self.CooldownCompra,
		DistanciaCierre = self.DistanciaCierrePanel,
		ReposicionMax = self.ReposicionMax,
	}
end

-- Destinatarios de actualizaciones: quien abrió el panel hace poco y sigue cerca, y los vendedores.
function CafeteriaService:_Destinatarios()
	local lista = {}
	local centro = self:PosicionMostrador()
	for _, player in ipairs(Players:GetPlayers()) do
		local incluir = false
		if self.Observadores[player.UserId] then
			local pos = posicionDe(player)
			incluir = centro == nil or (pos ~= nil and (pos - centro).Magnitude <= self.DistanciaCierrePanel * 2)
		end
		if not incluir and (self:_Tiene(player, "cafeteria.vender") or player.UserId == self.VendedorUserId) then
			incluir = true
		end
		if incluir then
			table.insert(lista, player)
		end
	end
	return lista
end

function CafeteriaService:_ProgramarEstado()
	if self._estadoPendiente then
		return
	end
	self._estadoPendiente = true
	task.delay(0.3, function()
		self._estadoPendiente = false
		local estado = self:Estado()
		self._firmaEstado = self:_FirmaEstado()
		local datos = {
			Sub = "Estado", Abierto = estado.Abierto, Modo = estado.Modo, Vendedor = estado.Vendedor,
			VendedorUserId = estado.VendedorUserId, HayVendedor = estado.HayVendedor,
		}
		for _, player in ipairs(self:_Destinatarios()) do
			self:_Enviar(player, "Cafeteria", datos)
		end
		self.Cambiado:Fire(estado)
	end)
end

function CafeteriaService:_ProgramarInventario()
	if self._inventarioPendiente then
		return
	end
	self._inventarioPendiente = true
	task.delay(0.5, function()
		self._inventarioPendiente = false
		local datos = { Sub = "Inventario", Catalogo = self:Catalogo() }
		for _, player in ipairs(self:_Destinatarios()) do
			self:_Enviar(player, "Cafeteria", datos)
		end
	end)
end

-- Repone todo el inventario hasta el stock inicial (nueva jornada: llega el proveedor).
function CafeteriaService:Reabastecer(motivo)
	local unidades = 0
	for _, id in ipairs(self.Orden) do
		local p = self.Productos[id]
		if p.Stock < p.StockInicial then
			unidades = unidades + (p.StockInicial - p.Stock)
			p.Stock = p.StockInicial
		end
	end
	if unidades > 0 then
		self:_Auditar(nil, "TiendaReabastecida", tostring(motivo or "Reabastecimiento") .. ": +" .. unidades .. " unidades")
		self:_ProgramarInventario()
	end
	return unidades
end

---------------------------------------------------------------------------------------------------
-- Mostrador y prompt
---------------------------------------------------------------------------------------------------
function CafeteriaService:PosicionMostrador()
	local enMapa = self.Puesto and posicionInstancia(self.Puesto.Parte)
	if enMapa then
		return enMapa
	end
	local zona = MapaLogico.Zonas[self.ZonaTienda]
	if zona and typeof(zona.Mostrador) == "table" and typeof(zona.Mostrador.Centro) == "Vector3" then
		return zona.Mostrador.Centro
	end
	return nil
end

function CafeteriaService:_Distancia(player)
	local pos = posicionDe(player)
	if not pos then
		return nil
	end
	local centro = self:PosicionMostrador()
	if not centro then
		return 0
	end
	return (pos - centro).Magnitude
end

-- El vendedor gestiona desde el puesto: dentro de la zona TIENDA o cerca del mostrador.
function CafeteriaService:_EnPuesto(player)
	local pos = posicionDe(player)
	if not pos then
		return false, "sin_personaje"
	end
	if Zones.Contiene(self.ZonaTienda, pos) then
		return true
	end
	local distancia = self:_Distancia(player)
	if distancia and distancia <= self.DistanciaGestion + self.Tolerancia then
		return true
	end
	return false, "lejos_gestion"
end

function CafeteriaService:EnlazarPrompt()
	self.maidPrompt:DoCleaning()
	self.Puesto = nil
	local parte, prompt = nil, nil
	local MapService = self:_S("MapService")
	if MapService and typeof(MapService.Cafeteria) == "function" then
		local ok, info = pcall(MapService.Cafeteria, MapService)
		if ok and typeof(info) == "table" and typeof(info.Prompt) == "Instance" and info.Prompt.Parent ~= nil then
			prompt = info.Prompt
			parte = info.Mostrador or info.Prompt.Parent
		end
	end
	if not prompt then
		local raiz = workspace:FindFirstChild((Config.Nombres and Config.Nombres.CarpetaMapa) or "ColegioRP_Mapa")
		local carpeta = raiz and raiz:FindFirstChild("Cafeteria")
		if carpeta then
			for _, d in ipairs(carpeta:GetDescendants()) do
				if d:IsA("ProximityPrompt") and d:GetAttribute("RPTipo") == "Cafeteria" then
					prompt = d
					parte = d.Parent
					break
				end
			end
		end
	end
	if not prompt then
		-- Sin mostrador del mapa: se crea uno propio en el punto de MapaLogico.Zonas.TIENDA.Mostrador.
		local zona = MapaLogico.Zonas[self.ZonaTienda]
		if not zona or typeof(zona.Mostrador) ~= "table" or typeof(zona.Mostrador.Centro) ~= "Vector3" then
			warn(PREFIJO .. " Sin mostrador de tienda (MapaLogico.Zonas.TIENDA.Mostrador); la compra solo funcionará por panel.")
			return
		end
		local padre = nil
		if MapService and typeof(MapService.Carpeta) == "function" then
			local ok, carpeta = pcall(MapService.Carpeta, MapService, "Cafeteria")
			if ok and typeof(carpeta) == "Instance" and carpeta.Parent ~= nil then
				padre = carpeta
			end
		end
		if not padre then
			padre = Instance.new("Folder")
			padre.Name = "ColegioRP_Tienda"
			padre.Parent = workspace
			self.maidPrompt:GiveTask(padre)
		end
		parte = Instance.new("Part")
		parte.Name = "Mostrador"
		parte.Size = Vector3.new(4, 2, 2)
		parte.CFrame = CFrame.new(zona.Mostrador.Centro)
		parte.Anchored = true
		parte.CanCollide = false
		parte.CanQuery = false
		parte.CanTouch = false
		parte.CastShadow = false
		parte.Transparency = 1
		parte.Parent = padre
		self.maidPrompt:GiveTask(parte)
		prompt = Instance.new("ProximityPrompt")
		prompt.Name = "ColegioRP_Prompt"
		prompt.ActionText = "Comprar"
		prompt.ObjectText = "Tienda escolar"
		prompt.MaxActivationDistance = 10
		prompt.HoldDuration = 0
		prompt.RequiresLineOfSight = false
		prompt.Parent = parte
	end
	prompt:SetAttribute("RPTipo", "Cafeteria")
	if prompt:GetAttribute("RPId") == nil then
		prompt:SetAttribute("RPId", self.ZonaTienda)
	end
	if prompt:GetAttribute("RPAccion") == nil then
		prompt:SetAttribute("RPAccion", "AbrirPanel")
	end
	self.Puesto = { Parte = parte, Prompt = prompt }
	self.maidPrompt:GiveTask(prompt.Triggered:Connect(function(player)
		local ok, err = pcall(self.AbrirPanel, self, player)
		if not ok then
			warn(PREFIJO .. " Error al abrir el panel: " .. tostring(err))
		end
	end))
end

-- Envía al jugador el panel de la tienda (catálogo con precios del servidor y estado).
function CafeteriaService:AbrirPanel(player)
	if not esJugador(player) then
		return false
	end
	local ahora = os.clock()
	local ultimo = self.UltimoPrompt[player.UserId]
	if ultimo and ahora - ultimo < self.IntervaloPromptSeg then
		return false
	end
	self.UltimoPrompt[player.UserId] = ahora
	local distancia = self:_Distancia(player)
	if not distancia or distancia > self.DistanciaCompra + self.Tolerancia then
		self:_Notificar(player, MENSAJES.lejos, "aviso", 4)
		return false
	end
	self.Observadores[player.UserId] = ahora
	local estado = self:Estado()
	local Economy = self:_S("EconomyService")
	local saldo = nil
	if Economy and typeof(Economy.Saldo) == "function" then
		local ok, valor = pcall(Economy.Saldo, Economy, player)
		if ok then
			saldo = valor
		end
	end
	local esVendedor = self:_Tiene(player, "cafeteria.vender")
	local datos = {
		Sub = "AbrirPanel",
		Catalogo = self:Catalogo(),
		Abierto = estado.Abierto,
		Modo = estado.Modo,
		Vendedor = estado.Vendedor,
		VendedorUserId = estado.VendedorUserId,
		Saldo = saldo,
		EsVendedor = esVendedor,
		PuedePrecios = self:PuedeFijarPrecios(player),
		Mostrador = self:PosicionMostrador(),
		Limites = self:_Limites(),
	}
	if esVendedor then
		datos.Caja = self:ResumenCaja()
	end
	self:_Enviar(player, "Cafeteria", datos)
	return true
end

---------------------------------------------------------------------------------------------------
-- Compra
---------------------------------------------------------------------------------------------------
function CafeteriaService:_RegistrarVenta(recibo, player)
	self.TotalVentas = self.TotalVentas + 1
	self.IndiceVentas = self.IndiceVentas + 1
	if self.IndiceVentas > self.TamanoVentas then
		self.IndiceVentas = 1
	end
	self.VentasBuffer[self.IndiceVentas] = {
		Id = recibo.Id, Fecha = recibo.Fecha, UserId = player.UserId, Comprador = player.Name, Items = recibo.Items,
		Total = recibo.Total, Modo = recibo.Modo, Vendedor = recibo.Vendedor,
	}
	local caja = self.Caja
	caja.Ventas = caja.Ventas + 1
	caja.Ingresos = caja.Ingresos + recibo.Total
	for _, item in ipairs(recibo.Items) do
		caja.Unidades = caja.Unidades + item.Cantidad
		local porProducto = caja.PorProducto[item.Id]
		if not porProducto then
			porProducto = { Nombre = item.Nombre, Unidades = 0, Ingresos = 0 }
			caja.PorProducto[item.Id] = porProducto
		end
		porProducto.Unidades = porProducto.Unidades + item.Cantidad
		porProducto.Ingresos = porProducto.Ingresos + item.Subtotal
		self.Estadisticas.Unidades = self.Estadisticas.Unidades + item.Cantidad
	end
	self.Estadisticas.Ventas = self.Estadisticas.Ventas + 1
	self.Estadisticas.Ingresos = self.Estadisticas.Ingresos + recibo.Total
end

function CafeteriaService:_Reembolsar(player, total, detalle, motivo)
	local Economy = self:_S("EconomyService")
	local ok = false
	if Economy and typeof(Economy.Acreditar) == "function" then
		local exito, resultado = pcall(Economy.Acreditar, Economy, player, total, "Reembolso", "Reembolso: " .. detalle)
		ok = exito and resultado == true
	end
	self.Caja.Reembolsos = self.Caja.Reembolsos + 1
	self.Estadisticas.Reembolsos = self.Estadisticas.Reembolsos + 1
	self:_Auditar(player, "Reembolso", detalle .. " (" .. total .. "): " .. tostring(motivo) .. (ok and "" or " · REEMBOLSO FALLIDO"))
	return ok
end

-- Compra atómica. Devuelve ok, recibo | (false, codigo, mensaje).
function CafeteriaService:Comprar(player, productoId, cantidad)
	if not esJugador(player) then
		return fallo("sin_personaje")
	end
	local userId = player.UserId
	if self.Comprando[userId] then
		return fallo("en_curso")
	end
	self.Comprando[userId] = true
	local ok, a, b, c = pcall(self._Comprar, self, player, productoId, cantidad)
	self.Comprando[userId] = nil
	if not ok then
		warn(PREFIJO .. " Error en la compra de " .. player.Name .. ": " .. tostring(a))
		self:_Auditar(player, "CompraError", tostring(a))
		return fallo("error_interno")
	end
	return a, b, c
end

function CafeteriaService:_Comprar(player, productoId, cantidad)
	local userId = player.UserId
	local producto = self.Productos[productoId]
	if typeof(productoId) ~= "string" or not producto then
		return fallo("producto_inexistente")
	end
	if not esFinito(cantidad) or cantidad ~= math.floor(cantidad) or cantidad < 1 or cantidad > self.CantidadMax then
		return fallo("cantidad_invalida", self.CantidadMax)
	end
	local distancia = self:_Distancia(player)
	if not distancia then
		return fallo("sin_personaje")
	end
	if distancia > self.DistanciaCompra + self.Tolerancia then
		self.Estadisticas.Rechazos = self.Estadisticas.Rechazos + 1
		self:_Auditar(player, "CompraRechazada", string.format("distancia %.1f > %.0f", distancia, self.DistanciaCompra))
		return fallo("lejos")
	end
	local estado = self:Estado()
	if not estado.Abierto then
		if estado.HayVendedor then
			return fallo("cerrado_vendedor")
		end
		return fallo("cerrado")
	end
	local ultima = self.UltimaCompra[userId]
	if ultima and os.clock() - ultima < self.CooldownCompra then
		return fallo("cooldown", math.max(1, math.ceil(self.CooldownCompra - (os.clock() - ultima))))
	end
	if producto.Stock < cantidad then
		return fallo("sin_stock", producto.Nombre, producto.Stock)
	end

	-- Precio del servidor (nunca del cliente).
	local precio = producto.Precio
	local total = precio * cantidad
	local detalle = cantidad .. "x " .. producto.Nombre
	local Economy = self:_S("EconomyService")
	if not Economy or typeof(Economy.Debitar) ~= "function" then
		return fallo("sin_economia")
	end

	-- 1. Cobro atómico ANTES de tocar el stock.
	local okDebito, saldoOError = Economy:Debitar(player, total, "Compra", detalle)
	if not okDebito then
		if saldoOError == "saldo_insuficiente" then
			local saldo = 0
			if typeof(Economy.Saldo) == "function" then
				saldo = Economy:Saldo(player)
			end
			return fallo("saldo_insuficiente", Format.Moneda(total), Format.Moneda(saldo))
		elseif saldoOError == "transaccion_en_curso" then
			return fallo("en_curso")
		elseif saldoOError == "perfil_no_cargado" then
			return fallo("perfil")
		end
		self:_Auditar(player, "CompraRechazada", "débito fallido: " .. tostring(saldoOError))
		return fallo("pago")
	end

	-- 2. Doble verificación del stock y descuento; si falla, se reembolsa.
	if producto.Stock < cantidad then
		self:_Reembolsar(player, total, detalle, "stock agotado durante el cobro")
		return fallo("sin_stock", producto.Nombre, producto.Stock)
	end
	local okStock, errStock = pcall(function()
		producto.Stock = producto.Stock - cantidad
		producto.Vendidos = producto.Vendidos + cantidad
	end)
	if not okStock then
		self:_Reembolsar(player, total, detalle, "error al descontar stock: " .. tostring(errStock))
		return fallo("error_interno")
	end

	self.UltimaCompra[userId] = os.clock()
	self.SiguienteRecibo = self.SiguienteRecibo + 1
	local fecha = os.time()
	local saldoFinal = saldoOError
	local recibo = {
		Id = string.format("R-%05d", self.SiguienteRecibo),
		Items = {
			{ Id = producto.Id, Nombre = producto.Nombre, Cantidad = cantidad, PrecioUnitario = precio, Subtotal = total },
		},
		Total = total,
		Saldo = saldoFinal,
		Fecha = fecha,
		FechaTexto = Format.Fecha(fecha),
		Modo = estado.Modo,
		Vendedor = estado.Vendedor,
	}
	-- El cobro y el stock ya están aplicados: un fallo al registrar o avisar no convierte la venta en error
	-- (el cliente creería que no pagó). Se audita y se devuelve el recibo igualmente.
	local okRegistro, errRegistro = pcall(function()
		self:_RegistrarVenta(recibo, player)
		self:_Enviar(player, "Cafeteria", { Sub = "Recibo", Recibo = recibo })
		self.Vendido:Fire(player, recibo)
		self:_ProgramarInventario()
		-- Aviso al vendedor que atiende (si no es el comprador).
		if estado.Modo == "Vendedor" and self.VendedorUserId and self.VendedorUserId ~= userId then
			local vendedor = Players:GetPlayerByUserId(self.VendedorUserId)
			if vendedor then
				self:_Notificar(vendedor, "Venta: " .. detalle .. " a " .. player.DisplayName .. " (" .. Format.Moneda(total) .. ").", "info", 3)
			end
		end
	end)
	if not okRegistro then
		warn(PREFIJO .. " Venta cobrada pero con error al registrarla (" .. recibo.Id .. "): " .. tostring(errRegistro))
		self:_Auditar(player, "CompraRegistroError", recibo.Id .. ": " .. tostring(errRegistro))
	end
	return true, recibo
end

function CafeteriaService:ManejarCompra(player, datos)
	local ok, a, b = self:Comprar(player, datos.ProductoId, datos.Cantidad)
	if ok then
		local producto = self.Productos[datos.ProductoId]
		return { ok = true, datos = { Recibo = a, Producto = { Id = producto.Id, Stock = producto.Stock } } }
	end
	return { ok = false, error = b or MENSAJES.error_interno, datos = { Codigo = a } }
end

---------------------------------------------------------------------------------------------------
-- Gestión del puesto (vendedor / precios)
---------------------------------------------------------------------------------------------------
function CafeteriaService:_RespuestaGestion(player, mensaje, extra)
	local datos = {
		Mensaje = mensaje,
		Estado = self:Estado(),
		Catalogo = self:Catalogo(),
		Inventario = self:Inventario(),
		PuedePrecios = self:PuedeFijarPrecios(player),
		EsVendedor = self:_Tiene(player, "cafeteria.vender"),
		Limites = self:_Limites(),
	}
	if datos.EsVendedor then
		datos.Caja = self:ResumenCaja()
	end
	for clave, valor in pairs(extra or {}) do
		datos[clave] = valor
	end
	return { ok = true, datos = datos }
end

-- Fija el precio validado en [PrecioMin, PrecioMax]. Devuelve ok, mensaje | (false, codigo, mensaje).
function CafeteriaService:_FijarPrecio(productoId, valor, player)
	local producto = typeof(productoId) == "string" and self.Productos[productoId] or nil
	if not producto then
		return fallo("producto_inexistente")
	end
	if not esFinito(valor) then
		return fallo("precio_invalido", self.PrecioMin, self.PrecioMax)
	end
	local precio = math.floor(valor + 0.5)
	if precio < self.PrecioMin or precio > self.PrecioMax then
		return fallo("precio_invalido", self.PrecioMin, self.PrecioMax)
	end
	local anterior = producto.Precio
	producto.Precio = precio
	self:_Auditar(player, "PrecioCambiado", producto.Id .. ": " .. anterior .. " -> " .. precio)
	self:_ProgramarInventario()
	return true, "Precio de " .. producto.Nombre .. ": " .. Format.Moneda(precio) .. "."
end

-- API para otros servicios (StaffService): FijarPrecio(productoId, precio, actor?) -> ok, mensajeOError.
-- Si se indica el jugador que actúa, debe poder fijar precios (cafeteria.precios).
function CafeteriaService:FijarPrecio(productoId, precio, player)
	if esJugador(player) and not self:PuedeFijarPrecios(player) then
		return false, MENSAJES.permiso
	end
	local ok, a, b = self:_FijarPrecio(productoId, precio, player)
	if ok then
		return true, a
	end
	return false, b
end

-- Devuelve ok, mensaje | (false, codigo, mensaje), extra.
function CafeteriaService:Gestionar(player, datos)
	local accion = datos.Accion
	local esVendedor = self:_Tiene(player, "cafeteria.vender")
	if accion == "Precio" then
		if not self:PuedeFijarPrecios(player) then
			return fallo("permiso")
		end
		local ok, codigoOMensaje, mensaje = self:_FijarPrecio(datos.ProductoId, datos.Valor, player)
		if not ok then
			return false, codigoOMensaje, mensaje
		end
		return true, codigoOMensaje
	end

	-- El resto de acciones son del vendedor (cafeteria.vender; RemoteService ya lo exige).
	if not esVendedor then
		return fallo("permiso")
	end
	if accion == "Abrir" then
		local enPuesto, codigo = self:_EnPuesto(player)
		if not enPuesto then
			return fallo(codigo or "lejos_gestion")
		end
		self.AbiertoManual = true
		self.VendedorUserId = player.UserId
		self.VendedorNombre = player.DisplayName
		self:_Auditar(player, "TiendaAbierta", "Atiende " .. player.Name)
		self:_ProgramarEstado()
		return true, "Abriste la tienda escolar."
	elseif accion == "Cerrar" then
		self.AbiertoManual = false
		self.VendedorUserId = nil
		self.VendedorNombre = nil
		self:_Auditar(player, "TiendaCerrada", "Cerrada por " .. player.Name)
		self:_ProgramarEstado()
		return true, "Cerraste la tienda escolar."
	elseif accion == "Reponer" then
		local enPuesto, codigo = self:_EnPuesto(player)
		if not enPuesto then
			return fallo(codigo or "lejos_gestion")
		end
		local ultimo = self.UltimaGestion[player.UserId]
		if ultimo and os.clock() - ultimo < self.CooldownReponerSeg then
			return fallo("reponer_espera")
		end
		local objetivos = {}
		if datos.ProductoId ~= nil then
			local producto = self.Productos[datos.ProductoId]
			if not producto then
				return fallo("producto_inexistente")
			end
			table.insert(objetivos, producto)
		else
			for _, id in ipairs(self.Orden) do
				table.insert(objetivos, self.Productos[id])
			end
		end
		local cantidad = nil
		if datos.Valor ~= nil then
			if not esFinito(datos.Valor) then
				return fallo("accion_invalida")
			end
			cantidad = math.clamp(math.floor(datos.Valor), 1, self.ReposicionMax)
		end
		local total = 0
		for _, producto in ipairs(objetivos) do
			local nuevo = producto.Stock
			if cantidad then
				nuevo = math.min(producto.StockMax, producto.Stock + cantidad)
			else
				nuevo = math.max(producto.Stock, producto.StockInicial)
			end
			total = total + (nuevo - producto.Stock)
			producto.Stock = nuevo
		end
		if total <= 0 then
			return fallo("reponer_lleno")
		end
		self.UltimaGestion[player.UserId] = os.clock()
		self:_Auditar(player, "TiendaRepuesta", "+" .. total .. " unidades (" .. (datos.ProductoId or "todo") .. ")")
		self:_ProgramarInventario()
		return true, "Repusiste " .. Format.Plural(total, "unidad", "unidades") .. "."
	elseif accion == "Inventario" then
		self.Observadores[player.UserId] = os.clock()
		return true, nil
	elseif accion == "Cierre" then
		local resumen = self:ResumenCaja()
		self.Caja = nuevaCaja()
		self:_Auditar(player, "CierreCaja", string.format("%d ventas, %d unidades, %d monedas", resumen.Ventas, resumen.Unidades, resumen.Ingresos))
		return true, "Cierre de caja: " .. Format.Plural(resumen.Ventas, "venta", "ventas") .. " por " .. Format.Moneda(resumen.Ingresos) .. ".", { Resumen = resumen }
	end
	return fallo("accion_invalida")
end

function CafeteriaService:ManejarGestion(player, datos)
	local ok, a, b = self:Gestionar(player, datos)
	if ok then
		return self:_RespuestaGestion(player, a, b)
	end
	if a == "permiso" or a == "lejos_gestion" or a == "producto_inexistente" then
		self:_Auditar(player, "GestionRechazada", tostring(datos.Accion) .. ": " .. tostring(a))
	end
	return { ok = false, error = b or MENSAJES.error_interno, datos = { Codigo = a, Estado = self:Estado() } }
end

return CafeteriaService
]=] }
FUENTES["ServerScriptService/ColegioRP/Services/ClassroomService"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ServerScriptService.ColegioRP.Services.ClassroomService
	Tipo: ModuleScript
	Sesiones de clase por aula (docs/ARQUITECTURA.md §6, pruebas P4 y P7). Modelo ClassSession / Activity en el
	servidor, handler de RequestClassAction con todas las acciones del contrato (abrir/cerrar sesión, tema, aviso,
	asistencia, actividades de texto u opciones con tiempo, respuestas únicas con corrección automática,
	calificación privada, resultados anónimos, manos levantadas, invitación y turno de tablero, consulta de estado).
	Todo el estado vive aquí; el cliente solo pide y renderiza. Los envíos "Aula" van exclusivamente a jugadores
	presentes en esa aula (RoomService) y al docente de la sesión: nunca a otra aula. La sesión se cancela si el
	docente sale del servidor, cambia de cargo, termina el periodo de clase o termina la jornada.
]]

local Players = game:GetService("Players")
local TextService = game:GetService("TextService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local RP = ReplicatedStorage:WaitForChild("ColegioRP")
local Shared = RP:WaitForChild("Shared")
local Config = require(Shared:WaitForChild("Config"))
local MapaLogico = require(Shared:WaitForChild("MapaLogico"))
local RoleDefinitions = require(Shared:WaitForChild("RoleDefinitions"))
local TimetableDefinitions = require(Shared:WaitForChild("TimetableDefinitions"))
local Util = Shared:WaitForChild("Util")
local Zones = require(Util:WaitForChild("Zones"))
local Signal = require(Util:WaitForChild("Signal"))
local Maid = require(Util:WaitForChild("Maid"))

local ClassroomService = {}
ClassroomService.Nombre = "ClassroomService"

local PREFIJO = "[ColegioRP][ClassroomService]"

---------------------------------------------------------------------------------------------------
-- Parámetros
---------------------------------------------------------------------------------------------------
local LIMITES = Config.Limites or {}
local RECOMPENSAS = (Config.Economia and Config.Economia.Recompensas) or {}

ClassroomService.MaxActividadesPorSesion = 30 -- Actividades que admite una misma sesión.
ClassroomService.SegundosMin = 30 -- Duración mínima de una actividad.
ClassroomService.SegundosMax = 600 -- Duración máxima de una actividad.
ClassroomService.SegundosPorDefecto = 120
ClassroomService.MinOpciones = 2
ClassroomService.MaxOpciones = 4
ClassroomService.MaxPreguntaCaracteres = 200
ClassroomService.MaxOpcionCaracteres = 60
ClassroomService.MaxComentarioCaracteres = 120
ClassroomService.MaxTemaCaracteres = LIMITES.MaxTemaCaracteres or 80
ClassroomService.MaxAvisoCaracteres = LIMITES.MaxAvisoCaracteres or 160
ClassroomService.MaxRespuestaCaracteres = LIMITES.MaxRespuestaCaracteres or 300
ClassroomService.InvitacionSeg = 20 -- Caducidad de una invitación al tablero.
ClassroomService.TurnoTableroSeg = (Config.Tablero and Config.Tablero.TurnoSeg) or 90
ClassroomService.DistanciaAperturaMax = 12 -- Studs fuera de la caja del aula para abrir sesión.
ClassroomService.SoloEnPeriodoClase = true -- Abrir sesión, actividades, respuestas, manos y tablero solo en CLASE_n.
ClassroomService.CerrarAlTerminarPeriodo = true -- Al pasar a un periodo que no es de clase se cierran las sesiones.
ClassroomService.IntervaloEstadoDocenteSeg = 1 -- Agrupa las actualizaciones de ocupación enviadas al docente.
ClassroomService.LimpiarTableroAlCerrar = true -- Al cerrar la sesión se limpia el tablero del aula (BoardService:Limpiar).

-- Segundos mínimos entre dos acciones iguales y aceptadas del mismo jugador.
ClassroomService.Cooldowns = {
	AbrirSesion = 3, FijarTema = 2, EnviarAviso = 5, TomarAsistencia = 3, CrearActividad = 3,
	InvitarTablero = 2, PublicarResultados = 3, LevantarMano = 2,
}

---------------------------------------------------------------------------------------------------
-- Utilidades
---------------------------------------------------------------------------------------------------
local function esJugador(valor)
	return typeof(valor) == "Instance" and valor:IsA("Player")
end

local function ahora()
	local ok, valor = pcall(function()
		return workspace:GetServerTimeNow()
	end)
	if ok and typeof(valor) == "number" then
		return valor
	end
	return os.time()
end

local function esFinito(n)
	return typeof(n) == "number" and n == n and n ~= math.huge and n ~= -math.huge
end

local function entero(valor, minimo, maximo)
	local n = tonumber(valor)
	if not esFinito(n) or math.floor(n) ~= n then
		return nil
	end
	if (minimo and n < minimo) or (maximo and n > maximo) then
		return nil
	end
	return n
end

local function contar(tabla)
	local n = 0
	for _ in pairs(tabla or {}) do
		n = n + 1
	end
	return n
end

-- Limpia un texto del jugador: quita caracteres de control (conserva saltos si se permiten), recorta espacios
-- y comprueba UTF-8 y longitud. Devuelve texto | nil, motivo.
local function limpiarTexto(texto, maximo, permitirSaltos)
	if typeof(texto) ~= "string" or utf8.len(texto) == nil then
		return nil, "invalido"
	end
	local limpio = string.gsub(texto, "%c", function(c)
		if c == "\n" and permitirSaltos then
			return "\n"
		end
		if c == "\n" or c == "\t" then
			return " "
		end
		return ""
	end)
	limpio = string.gsub(limpio, "^%s+", "")
	limpio = string.gsub(limpio, "%s+$", "")
	if limpio == "" then
		return nil, "vacio"
	end
	local n = utf8.len(limpio)
	if n == nil then
		return nil, "invalido"
	end
	if n > maximo then
		return nil, "largo"
	end
	return limpio
end

-- Filtra con TextService. paraUserId = nil -> texto apto para todos (broadcast). Devuelve texto | nil.
local function filtrar(texto, deUserId, paraUserId)
	local okFiltro, resultado = pcall(function()
		return TextService:FilterStringAsync(texto, deUserId, Enum.TextFilterContext.PublicChat)
	end)
	if not okFiltro or resultado == nil then
		return nil
	end
	local okTexto, filtrado = pcall(function()
		if paraUserId then
			return resultado:GetNonChatStringForUserAsync(paraUserId)
		end
		return resultado:GetNonChatStringForBroadcastAsync()
	end)
	if not okTexto or typeof(filtrado) ~= "string" then
		return nil
	end
	return filtrado
end

local function nombreAula(roomId)
	local zona = MapaLogico.Zonas[roomId]
	if zona and typeof(zona.Nombre) == "string" and zona.Nombre ~= "" then
		return zona.Nombre
	end
	return tostring(roomId)
end

local function nombreDe(userId, respaldo)
	local player = Players:GetPlayerByUserId(userId)
	if player then
		return player.DisplayName
	end
	return respaldo or ("Usuario " .. tostring(userId))
end

local function raizDe(player)
	local personaje = player and player.Character
	local raiz = personaje and personaje:FindFirstChild("HumanoidRootPart")
	if raiz and raiz:IsA("BasePart") then
		return raiz
	end
	return nil
end

local function conectar(senal, fn)
	if senal == nil then
		return nil
	end
	local ok, conexion = pcall(function()
		return senal:Connect(fn)
	end)
	if ok then
		return conexion
	end
	return nil
end

-- Normaliza la asistencia de SchoolDayService (array de registros o mapa userId -> estado) a un array seguro
-- para enviar por red: { {UserId, Nombre, Estado} }.
local function normalizarAsistencia(valor)
	local lista = {}
	if typeof(valor) ~= "table" then
		return lista
	end
	local fuente = valor
	if typeof(valor.Registros) == "table" then
		fuente = valor.Registros
	elseif typeof(valor.Lista) == "table" then
		fuente = valor.Lista
	elseif typeof(valor.Alumnos) == "table" then
		fuente = valor.Alumnos
	end
	for clave, registro in pairs(fuente) do
		if #lista >= 60 then
			break
		end
		local userId, estado = nil, nil
		if typeof(registro) == "table" then
			userId = tonumber(registro.UserId) or tonumber(clave)
			estado = registro.Estado
		elseif typeof(registro) == "string" then
			userId = tonumber(clave)
			estado = registro
		end
		if userId and typeof(estado) == "string" then
			table.insert(lista, { UserId = userId, Nombre = nombreDe(userId), Estado = string.sub(estado, 1, 24) })
		end
	end
	table.sort(lista, function(a, b)
		return a.Nombre < b.Nombre
	end)
	return lista
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function ClassroomService:Init(registro)
	self.registro = registro
	self.Sesiones = {} -- roomId -> sesion
	self.SesionPorDocente = {} -- userId del docente -> roomId
	self.Invitaciones = {} -- roomId -> { UserId, Nombre, Expira, SessionId }
	self.UltimaAccion = {} -- userId -> { accion -> os.clock() }
	self.Contador = 0
	self._estadoPendiente = {} -- roomId -> true mientras hay un envío de Estado programado
	self.SesionAbierta = Signal.new() -- (sesion)
	self.SesionCerrada = Signal.new() -- (sesion, motivo)
	self.ActividadCreada = Signal.new() -- (sesion, actividad)
	self.ActividadCerrada = Signal.new() -- (sesion, actividad)
	self.maid = Maid.new()
	self.Acciones = {
		AbrirSesion = ClassroomService.AccionAbrirSesion,
		CerrarSesion = ClassroomService.AccionCerrarSesion,
		FijarTema = ClassroomService.AccionFijarTema,
		EnviarAviso = ClassroomService.AccionEnviarAviso,
		TomarAsistencia = ClassroomService.AccionTomarAsistencia,
		CrearActividad = ClassroomService.AccionCrearActividad,
		CerrarActividad = ClassroomService.AccionCerrarActividad,
		InvitarTablero = ClassroomService.AccionInvitarTablero,
		RevocarTablero = ClassroomService.AccionRevocarTablero,
		Calificar = ClassroomService.AccionCalificar,
		Responder = ClassroomService.AccionResponder,
		LevantarMano = ClassroomService.AccionLevantarMano,
		AceptarInvitacion = ClassroomService.AccionAceptarInvitacion,
		ConsultarEstado = ClassroomService.AccionConsultarEstado,
		PublicarResultados = ClassroomService.AccionPublicarResultados,
	}
end

function ClassroomService:Start()
	local RemoteService = self.registro.Get("RemoteService")
	if RemoteService and typeof(RemoteService.Registrar) == "function" then
		RemoteService:Registrar("RequestClassAction", function(player, datos)
			return self:Manejar(player, datos)
		end)
	else
		warn(PREFIJO .. " RemoteService no disponible: RequestClassAction no tendrá handler.")
	end

	self.maid:GiveTask(Players.PlayerRemoving:Connect(function(player)
		self:AlSalirJugador(player)
	end))

	local RoleService = self.registro.Get("RoleService")
	if RoleService and RoleService.CargoCambiado then
		local conexion = conectar(RoleService.CargoCambiado, function(player, cargo, anterior)
			self:AlCambiarCargo(player, cargo, anterior)
		end)
		if conexion then
			self.maid:GiveTask(conexion)
		end
	end

	local SchoolDayService = self.registro.Get("SchoolDayService")
	if SchoolDayService then
		local fin = conectar(SchoolDayService.JornadaTerminada, function()
			self:CerrarTodas("Terminó la jornada escolar.")
		end)
		if fin then
			self.maid:GiveTask(fin)
		end
		local cambio = conectar(SchoolDayService.EstadoCambiado, function(estado, snapshot)
			self:AlCambiarPeriodo(estado, snapshot)
		end)
		if cambio then
			self.maid:GiveTask(cambio)
		end
	end

	local RoomService = self.registro.Get("RoomService")
	if RoomService and RoomService.OcupacionCambiada then
		local conexion = conectar(RoomService.OcupacionCambiada, function(roomId)
			self:ProgramarEstadoDocente(roomId)
		end)
		if conexion then
			self.maid:GiveTask(conexion)
		end
	end

	-- BoardService puede terminar el turno por su cuenta (vence, limpieza, otra aula, sesión cerrada):
	-- la sesión se sincroniza para no bloquear nuevas invitaciones con un turno que ya no existe.
	local BoardService = self.registro.Get("BoardService")
	if BoardService and BoardService.TurnoCambiado then
		local conexion = conectar(BoardService.TurnoCambiado, function(roomId, turno, motivo)
			self:AlCambiarTurnoTablero(roomId, turno, motivo)
		end)
		if conexion then
			self.maid:GiveTask(conexion)
		end
	end
end

---------------------------------------------------------------------------------------------------
-- Acceso a otros servicios (tolerante a ausencia)
---------------------------------------------------------------------------------------------------
function ClassroomService:Servicio(nombre)
	return self.registro and self.registro.Get(nombre) or nil
end

-- Llama servicio:metodo(...) en pcall. Devuelve ok, r1, r2 (ok = false si no existe o falla).
function ClassroomService:Llamar(nombre, metodo, ...)
	local servicio = self:Servicio(nombre)
	if not servicio or typeof(servicio[metodo]) ~= "function" then
		return false
	end
	local resultado = table.pack(pcall(servicio[metodo], servicio, ...))
	if not resultado[1] then
		warn(PREFIJO .. " " .. nombre .. ":" .. metodo .. " falló: " .. tostring(resultado[2]))
		return false
	end
	return true, resultado[2], resultado[3]
end

function ClassroomService:Auditar(player, accion, detalle)
	local AuditLog = self:Servicio("AuditLogService")
	if AuditLog and typeof(AuditLog.Registrar) == "function" then
		pcall(AuditLog.Registrar, AuditLog, "Clase", player, accion, detalle)
	end
end

function ClassroomService:EnviarA(player, tipo, datos)
	local RemoteService = self:Servicio("RemoteService")
	if RemoteService and esJugador(player) then
		return RemoteService:Enviar(player, tipo, datos)
	end
	return false
end

-- Evento "Aula" a un jugador concreto (Sub = subtipo).
function ClassroomService:Enviar(player, sub, datos)
	datos = datos or {}
	datos.Sub = sub
	return self:EnviarA(player, "Aula", datos)
end

function ClassroomService:Notificar(player, texto, nivel, duracion)
	return self:EnviarA(player, "Notificacion", { Texto = texto, Nivel = nivel or "info", Duracion = duracion })
end

-- Respuesta de rechazo de lógica: { ok=false, error="rechazado:<codigo>", mensaje }. auditar = true la registra.
function ClassroomService:Rechazo(player, accion, codigo, mensaje, auditar)
	if auditar then
		self:Auditar(player, "Rechazo:" .. tostring(accion), tostring(codigo) .. " · " .. tostring(mensaje))
		self:Llamar("MetricsService", "IncrementarRechazo", "RequestClassAction", "clase_" .. tostring(codigo))
	end
	return { ok = false, error = "rechazado:" .. tostring(codigo), mensaje = mensaje }
end

local function exito(datos)
	return { ok = true, datos = datos or {} }
end

function ClassroomService:EsAulaValida(roomId)
	if typeof(roomId) ~= "string" or roomId == "" then
		return false
	end
	local MapService = self:Servicio("MapService")
	if MapService and typeof(MapService.EsAula) == "function" then
		local ok, es = pcall(MapService.EsAula, MapService, roomId)
		if ok and es == true then
			return true
		end
	end
	return Zones.EsAula(roomId)
end

function ClassroomService:CargoDe(player)
	local ok, cargo = self:Llamar("RoleService", "Cargo", player)
	if ok and typeof(cargo) == "string" then
		return cargo
	end
	return player:GetAttribute("Cargo")
end

function ClassroomService:Tiene(player, permiso)
	local ok, tiene = self:Llamar("RoleService", "Tiene", player, permiso)
	if ok then
		return tiene == true
	end
	local cargo = player:GetAttribute("Cargo")
	return typeof(cargo) == "string" and RoleDefinitions.Tiene(cargo, permiso)
end

function ClassroomService:SalonDe(player)
	local ok, salon = self:Llamar("RoleService", "Salon", player)
	if ok and typeof(salon) == "string" and salon ~= "" then
		return salon
	end
	local atributo = player:GetAttribute("Salon")
	if typeof(atributo) == "string" and atributo ~= "" then
		return atributo
	end
	return nil
end

-- ¿Puede el jugador dirigir clases en esa aula? aula.docente y (su Salon o horario.editar).
function ClassroomService:PuedeDirigir(player, roomId)
	if not self:Tiene(player, "aula.docente") then
		return false
	end
	if self:Tiene(player, "horario.editar") then
		return true
	end
	return self:SalonDe(player) == roomId
end

-- Jugadores presentes en el aula (RoomService; respaldo por zona).
function ClassroomService:JugadoresEnAula(roomId)
	local ok, lista = self:Llamar("RoomService", "JugadoresEn", roomId)
	if ok and typeof(lista) == "table" then
		return lista
	end
	local resultado = {}
	for _, player in ipairs(Players:GetPlayers()) do
		local raiz = raizDe(player)
		if raiz and Zones.Contiene(roomId, raiz.Position) then
			table.insert(resultado, player)
		end
	end
	return resultado
end

function ClassroomService:EstaEnAula(player, roomId)
	if not esJugador(player) then
		return false
	end
	local ok, esta = self:Llamar("RoomService", "EstaEn", player, roomId)
	if ok then
		return esta == true
	end
	local raiz = raizDe(player)
	return raiz ~= nil and Zones.Contiene(roomId, raiz.Position)
end

function ClassroomService:CercaDelAula(player, roomId)
	if self:EstaEnAula(player, roomId) then
		return true
	end
	local raiz = raizDe(player)
	if not raiz then
		return false
	end
	return Zones.DistanciaA(roomId, raiz.Position) <= self.DistanciaAperturaMax
end

-- ¿Estamos en un periodo de clase? Devuelve true | false, nombreDelPeriodo. Sin SchoolDayService: true.
function ClassroomService:EnClase()
	if not self.SoloEnPeriodoClase then
		return true
	end
	local ok, enClase = self:Llamar("SchoolDayService", "EnPeriodoClase")
	if not ok or enClase == true then
		return true
	end
	local nombre = "fuera de clase"
	local okSnap, snapshot = self:Llamar("SchoolDayService", "Snapshot")
	if okSnap and typeof(snapshot) == "table" and typeof(snapshot.Nombre) == "string" then
		nombre = snapshot.Nombre
	end
	return false, nombre
end

function ClassroomService:MateriaActual()
	local ok, snapshot = self:Llamar("SchoolDayService", "Snapshot")
	if ok and typeof(snapshot) == "table" and TimetableDefinitions.ExisteMateria(snapshot.Materia) then
		return snapshot.Materia
	end
	return nil
end

function ClassroomService:Acreditar(player, monto, tipo, detalle)
	monto = tonumber(monto) or 0
	if monto <= 0 then
		return false
	end
	local ok, resultado = self:Llamar("EconomyService", "Acreditar", player, monto, tipo, detalle)
	return ok and resultado ~= false
end

function ClassroomService:SumarProgreso(player, clave, cantidad)
	local ok, perfil = self:Llamar("DataService", "Obtener", player)
	if not ok or typeof(perfil) ~= "table" then
		return
	end
	if typeof(perfil.Progreso) ~= "table" then
		perfil.Progreso = {}
	end
	perfil.Progreso[clave] = (tonumber(perfil.Progreso[clave]) or 0) + (cantidad or 1)
	self:Llamar("DataService", "Marcar", player)
end

---------------------------------------------------------------------------------------------------
-- Cooldowns por acción
---------------------------------------------------------------------------------------------------
function ClassroomService:EsperaRestante(player, accion)
	local segundos = self.Cooldowns[accion]
	if not segundos then
		return 0
	end
	local porJugador = self.UltimaAccion[player.UserId]
	local ultimo = porJugador and porJugador[accion]
	if not ultimo then
		return 0
	end
	local restante = segundos - (os.clock() - ultimo)
	if restante > 0 then
		return restante
	end
	return 0
end

function ClassroomService:MarcarAccion(player, accion)
	if not self.Cooldowns[accion] then
		return
	end
	local porJugador = self.UltimaAccion[player.UserId]
	if not porJugador then
		porJugador = {}
		self.UltimaAccion[player.UserId] = porJugador
	end
	porJugador[accion] = os.clock()
end

---------------------------------------------------------------------------------------------------
-- Entrada del remoto
---------------------------------------------------------------------------------------------------
function ClassroomService:Manejar(player, datos)
	if not esJugador(player) or typeof(datos) ~= "table" then
		return { ok = false, error = "rechazado:datos" }
	end
	local accion = datos.Accion
	local roomId = datos.Salon
	local d = datos.Datos
	if typeof(d) ~= "table" then
		d = {}
	end
	local metodo = self.Acciones[accion]
	if not metodo then
		return self:Rechazo(player, accion, "accion_desconocida", "Acción de clase desconocida.", true)
	end
	if not self:EsAulaValida(roomId) then
		return self:Rechazo(player, accion, "aula_desconocida", "Esa aula no existe.", true)
	end
	local espera = self:EsperaRestante(player, accion)
	if espera > 0 then
		return {
			ok = false, error = "rechazado:cooldown",
			mensaje = string.format("Espera %d s antes de repetir esta acción.", math.ceil(espera)),
		}
	end
	local respuesta = metodo(self, player, roomId, d)
	if typeof(respuesta) == "table" and respuesta.ok == true then
		self:MarcarAccion(player, accion)
	end
	return respuesta
end

---------------------------------------------------------------------------------------------------
-- Sesiones: consultas
---------------------------------------------------------------------------------------------------

-- Sesión abierta del aula (tabla interna; solo lectura para otros servicios) o nil.
function ClassroomService:SesionDe(roomId)
	return self.Sesiones[roomId]
end

-- ¿El jugador es el docente de la sesión abierta en el aula?
function ClassroomService:EsDocenteDe(player, roomId)
	local sesion = self.Sesiones[roomId]
	return sesion ~= nil and esJugador(player) and sesion.TeacherUserId == player.UserId
end

-- Sesión relevante para el jugador: la que dirige o, si no, la del aula donde está presente.
function ClassroomService:SesionDeJugador(player)
	if not esJugador(player) then
		return nil
	end
	local propia = self.SesionPorDocente[player.UserId]
	if propia and self.Sesiones[propia] then
		return self.Sesiones[propia]
	end
	local ok, aula = self:Llamar("RoomService", "AulaActualDe", player)
	if ok and typeof(aula) == "string" and self.Sesiones[aula] then
		return self.Sesiones[aula]
	end
	if not ok then
		for roomId, sesion in pairs(self.Sesiones) do
			if self:EstaEnAula(player, roomId) then
				return sesion
			end
		end
	end
	return nil
end

-- Sesión que dirige el jugador en esa aula o nil, rechazo.
function ClassroomService:SesionDelDocente(player, roomId, accion)
	local sesion = self.Sesiones[roomId]
	if not sesion then
		return nil, self:Rechazo(player, accion, "sin_sesion", "No hay una sesión abierta en esta aula.")
	end
	if sesion.TeacherUserId ~= player.UserId then
		return nil, self:Rechazo(player, accion, "no_es_tu_sesion", "Esta sesión la dirige " .. tostring(sesion.TeacherName) .. ".", true)
	end
	return sesion
end

-- Actividad por id (o la activa, o la última) de una sesión.
local function actividadDe(sesion, id)
	if typeof(id) == "string" and sesion.Actividades[id] then
		return sesion.Actividades[id]
	end
	if id == nil then
		local activa = sesion.ActiveActivityId and sesion.Actividades[sesion.ActiveActivityId]
		if activa then
			return activa
		end
		return sesion.UltimaActividadId and sesion.Actividades[sesion.UltimaActividadId] or nil
	end
	return nil
end

---------------------------------------------------------------------------------------------------
-- Envíos a la sala (P4: solo presentes en el aula + docente de la sesión)
---------------------------------------------------------------------------------------------------

-- opciones: { SinDocente = bool, SoloEstudiantes = bool (excluye al docente) }
function ClassroomService:EnviarAula(sesion, sub, datos, opciones)
	opciones = opciones or {}
	datos = datos or {}
	datos.Sub = sub
	datos.RoomId = sesion.RoomId
	datos.SessionId = sesion.SessionId
	local enviados = {}
	local total = 0
	for _, player in ipairs(self:JugadoresEnAula(sesion.RoomId)) do
		local esDocente = player.UserId == sesion.TeacherUserId
		if not (esDocente and (opciones.SoloEstudiantes or opciones.SinDocente)) then
			if not enviados[player.UserId] then
				enviados[player.UserId] = true
				if self:EnviarA(player, "Aula", datos) then
					total = total + 1
				end
			end
		end
	end
	if not opciones.SinDocente and not opciones.SoloEstudiantes and not enviados[sesion.TeacherUserId] then
		local docente = Players:GetPlayerByUserId(sesion.TeacherUserId)
		if docente and self:EnviarA(docente, "Aula", datos) then
			total = total + 1
		end
	end
	return total
end

function ClassroomService:EnviarDocente(sesion, sub, datos)
	local docente = Players:GetPlayerByUserId(sesion.TeacherUserId)
	if not docente then
		return false
	end
	datos = datos or {}
	datos.RoomId = sesion.RoomId
	datos.SessionId = sesion.SessionId
	return self:Enviar(docente, sub, datos)
end

---------------------------------------------------------------------------------------------------
-- Representaciones para el cliente (solo arrays y diccionarios con claves de texto)
---------------------------------------------------------------------------------------------------
local function copiarOpciones(opciones)
	if typeof(opciones) ~= "table" then
		return nil
	end
	local copia = {}
	for i, texto in ipairs(opciones) do
		copia[i] = texto
	end
	return copia
end

function ClassroomService:ActividadPublica(act, paraDocente)
	local datos = {
		Id = act.Id,
		Type = act.Type,
		Prompt = act.Prompt,
		Options = copiarOpciones(act.Options),
		CreatedAt = act.CreatedAt,
		DueAt = act.DueAt,
		Segundos = act.Segundos,
		Estado = act.Estado,
		Respuestas = contar(act.Submissions),
	}
	if paraDocente then
		datos.Correcta = act.Correcta
		datos.Calificadas = contar(act.Grades)
	end
	return datos
end

function ClassroomService:ListaRespuestas(act)
	local lista = {}
	for userId, envio in pairs(act.Submissions) do
		local nota = act.Grades[userId]
		table.insert(lista, {
			UserId = userId,
			Nombre = nombreDe(userId, envio.Nombre),
			Respuesta = envio.Respuesta,
			Indice = envio.Indice,
			Correcta = envio.Correcta,
			T = envio.T,
			Puntos = nota and nota.Puntos or nil,
			Comentario = nota and nota.Comentario or nil,
		})
	end
	table.sort(lista, function(a, b)
		return (a.T or 0) < (b.T or 0)
	end)
	return lista
end

function ClassroomService:ListaManos(sesion)
	local lista = {}
	for userId, t in pairs(sesion.ManosLevantadas) do
		table.insert(lista, { UserId = userId, Nombre = nombreDe(userId), T = t })
	end
	table.sort(lista, function(a, b)
		return a.T < b.T
	end)
	return lista
end

-- Ocupación con nombres, sin el docente de la sesión: { Sentados, DePie, Capacidad, Total }.
function ClassroomService:OcupacionConNombres(roomId, docenteUserId)
	local ocupacion = nil
	local ok, resultado = self:Llamar("RoomService", "Ocupacion", roomId)
	if ok and typeof(resultado) == "table" then
		ocupacion = resultado
	else
		ocupacion = { Sentados = {}, DePie = {}, Capacidad = 0 }
		for _, player in ipairs(self:JugadoresEnAula(roomId)) do
			table.insert(ocupacion.DePie, player.UserId)
		end
	end
	local function conNombres(ids)
		local lista = {}
		for _, userId in ipairs(ids or {}) do
			if userId ~= docenteUserId then
				table.insert(lista, { UserId = userId, Nombre = nombreDe(userId) })
			end
		end
		table.sort(lista, function(a, b)
			return a.Nombre < b.Nombre
		end)
		return lista
	end
	local sentados = conNombres(ocupacion.Sentados)
	local dePie = conNombres(ocupacion.DePie)
	return { Sentados = sentados, DePie = dePie, Capacidad = ocupacion.Capacidad or 0, Total = #sentados + #dePie }
end

function ClassroomService:DatosBase(sesion)
	return {
		SesionAbierta = sesion.State == "Abierta",
		SessionId = sesion.SessionId,
		RoomId = sesion.RoomId,
		NombreAula = sesion.NombreAula,
		Docente = sesion.TeacherName,
		DocenteUserId = sesion.TeacherUserId,
		Tema = sesion.Tema,
		Materia = sesion.Materia,
		NombreMateria = sesion.Materia and TimetableDefinitions.NombreMateria(sesion.Materia) or nil,
		StartedAt = sesion.StartedAt,
		HoraServidor = ahora(),
	}
end

function ClassroomService:InvitacionPublica(roomId, sesion)
	local inv = self.Invitaciones[roomId]
	if inv and inv.SessionId == sesion.SessionId and ahora() <= inv.Expira then
		return inv
	end
	return nil
end

function ClassroomService:TurnoPublico(sesion)
	if sesion.InvitadoTablero and sesion.TurnoHasta and ahora() <= sesion.TurnoHasta then
		return { UserId = sesion.InvitadoTablero, Nombre = nombreDe(sesion.InvitadoTablero), Hasta = sesion.TurnoHasta }
	end
	return nil
end

-- Vista completa del docente.
function ClassroomService:SnapshotDocente(sesion)
	local datos = self:DatosBase(sesion)
	datos.Rol = "Docente"
	local activa = sesion.ActiveActivityId and sesion.Actividades[sesion.ActiveActivityId] or nil
	if activa then
		datos.ActividadActiva = self:ActividadPublica(activa, true)
	end
	local referencia = actividadDe(sesion, nil)
	if referencia then
		datos.ActividadRespuestas = self:ActividadPublica(referencia, true)
		datos.Respuestas = self:ListaRespuestas(referencia)
	else
		datos.Respuestas = {}
	end
	datos.Actividades = {}
	for _, id in ipairs(sesion.OrdenActividades) do
		local act = sesion.Actividades[id]
		if act then
			table.insert(datos.Actividades, {
				Id = act.Id, Type = act.Type, Prompt = act.Prompt, Estado = act.Estado,
				Respuestas = contar(act.Submissions), Calificadas = contar(act.Grades), Publicada = act.Publicada == true,
			})
		end
	end
	datos.Manos = self:ListaManos(sesion)
	local inv = self:InvitacionPublica(sesion.RoomId, sesion)
	if inv then
		datos.Invitacion = { UserId = inv.UserId, Nombre = inv.Nombre, Expira = inv.Expira }
	end
	datos.TurnoTablero = self:TurnoPublico(sesion)
	datos.Ocupacion = self:OcupacionConNombres(sesion.RoomId, sesion.TeacherUserId)
	return datos
end

-- Vista del estudiante: solo lo suyo (su respuesta, sus resultados, su mano, su invitación).
function ClassroomService:SnapshotEstudiante(sesion, player)
	local userId = player.UserId
	local datos = self:DatosBase(sesion)
	datos.Rol = "Estudiante"
	local activa = sesion.ActiveActivityId and sesion.Actividades[sesion.ActiveActivityId] or nil
	if activa then
		local publica = self:ActividadPublica(activa, false)
		publica.Respuestas = nil
		local envio = activa.Submissions[userId]
		if envio then
			publica.MiRespuesta = { Respuesta = envio.Respuesta, Indice = envio.Indice, T = envio.T }
		end
		datos.ActividadActiva = publica
	end
	datos.MisResultados = {}
	for _, id in ipairs(sesion.OrdenActividades) do
		local act = sesion.Actividades[id]
		local nota = act and act.Grades[userId]
		local envio = act and act.Submissions[userId]
		if act and (nota or (envio and act.Estado == "Cerrada" and envio.Correcta ~= nil)) then
			local correcta = nil
			if act.Estado == "Cerrada" and envio and envio.Correcta ~= nil then
				correcta = envio.Correcta == true
			end
			table.insert(datos.MisResultados, {
				ActividadId = act.Id,
				Prompt = act.Prompt,
				Puntos = nota and nota.Puntos or nil,
				Comentario = nota and nota.Comentario or nil,
				Correcta = correcta,
			})
		end
	end
	datos.ManoLevantada = sesion.ManosLevantadas[userId] ~= nil
	local inv = self:InvitacionPublica(sesion.RoomId, sesion)
	if inv and inv.UserId == userId then
		datos.Invitacion = { Expira = inv.Expira, Docente = sesion.TeacherName }
	end
	local turno = self:TurnoPublico(sesion)
	if turno then
		turno.EsMio = turno.UserId == userId
		datos.TurnoTablero = turno
	end
	return datos
end

-- Snapshot para StateSnapshot: sesión que dirige el jugador o la del aula en la que está (nil si ninguna).
function ClassroomService:Snapshot(player)
	if not esJugador(player) then
		return nil
	end
	local propia = self.SesionPorDocente[player.UserId]
	if propia and self.Sesiones[propia] then
		return self:SnapshotDocente(self.Sesiones[propia])
	end
	local sesion = self:SesionDeJugador(player)
	if sesion then
		return self:SnapshotEstudiante(sesion, player)
	end
	return nil
end

-- Resumen de todas las sesiones abiertas (paneles de dirección/coordinación).
function ClassroomService:Resumen()
	local lista = {}
	for roomId, sesion in pairs(self.Sesiones) do
		local activa = sesion.ActiveActivityId and sesion.Actividades[sesion.ActiveActivityId] or nil
		table.insert(lista, {
			RoomId = roomId,
			NombreAula = sesion.NombreAula,
			Docente = sesion.TeacherName,
			Tema = sesion.Tema,
			Materia = sesion.Materia,
			StartedAt = sesion.StartedAt,
			Presentes = #self:JugadoresEnAula(roomId),
			Actividades = #sesion.OrdenActividades,
			ActividadActiva = activa and activa.Prompt or nil,
		})
	end
	table.sort(lista, function(a, b)
		return a.RoomId < b.RoomId
	end)
	return lista
end

---------------------------------------------------------------------------------------------------
-- Cierre de actividades y sesiones
---------------------------------------------------------------------------------------------------
function ClassroomService:CerrarActividadInterna(sesion, act, motivo)
	if not act or act.Estado ~= "Abierta" then
		return false
	end
	act.Estado = "Cerrada"
	act.CerradaEn = ahora()
	if sesion.ActiveActivityId == act.Id then
		sesion.ActiveActivityId = nil
	end
	sesion.UltimaActividadId = act.Id

	-- Corrección automática: resultado privado a cada alumno y bonificación por acierto.
	if act.Type == "Opciones" and act.Correcta then
		local textoCorrecta = act.Options and act.Options[act.Correcta] or nil
		for userId, envio in pairs(act.Submissions) do
			local alumno = Players:GetPlayerByUserId(userId)
			if alumno then
				if envio.Correcta then
					self:Acreditar(alumno, RECOMPENSAS.Participacion, "Participacion", "Respuesta correcta · " .. sesion.RoomId)
					self:SumarProgreso(alumno, "RespuestasCorrectas", 1)
				end
				self:Enviar(alumno, "Resultado", {
					RoomId = sesion.RoomId, SessionId = sesion.SessionId, ActividadId = act.Id, Prompt = act.Prompt,
					Automatico = true, Correcta = envio.Correcta == true, TuRespuesta = envio.Respuesta,
					RespuestaCorrecta = textoCorrecta,
				})
			end
		end
	end

	self:EnviarAula(sesion, "ActividadCerrada", {
		ActividadId = act.Id, Motivo = motivo or "El docente cerró la actividad.", Respuestas = contar(act.Submissions),
	}, { SinDocente = true })
	self:EnviarDocente(sesion, "ActividadCerrada", {
		ActividadId = act.Id, Motivo = motivo, Actividad = self:ActividadPublica(act, true),
		Respuestas = self:ListaRespuestas(act),
	})
	self.ActividadCerrada:Fire(sesion, act)
	return true
end

function ClassroomService:CerrarSesionInterna(sesion, motivo, actor)
	if not sesion or sesion.State ~= "Abierta" then
		return false
	end
	local roomId = sesion.RoomId
	local activa = sesion.ActiveActivityId and sesion.Actividades[sesion.ActiveActivityId] or nil
	if activa then
		self:CerrarActividadInterna(sesion, activa, "La sesión se cerró.")
	end
	sesion.State = "Cerrada"
	sesion.ClosedAt = os.time()
	if sesion.InvitadoTablero then
		sesion.InvitadoTablero = nil
		sesion.TurnoHasta = nil
		self:Llamar("BoardService", "RevocarTurno", roomId)
	end
	self.Invitaciones[roomId] = nil
	-- La próxima clase empieza con el tablero limpio (BoardService también limpia al terminar la jornada).
	if self.LimpiarTableroAlCerrar then
		self:Llamar("BoardService", "Limpiar", roomId, "Fin de la sesión")
	end

	-- Presentes al cierre cuentan como asistentes; clase completada para los estudiantes conectados.
	for _, player in ipairs(self:JugadoresEnAula(roomId)) do
		if player.UserId ~= sesion.TeacherUserId then
			sesion.PresentUserIds[player.UserId] = true
		end
	end
	for userId in pairs(sesion.PresentUserIds) do
		local alumno = Players:GetPlayerByUserId(userId)
		if alumno and userId ~= sesion.TeacherUserId then
			self:SumarProgreso(alumno, "ClasesCompletadas", 1)
		end
	end

	self:EnviarAula(sesion, "SesionCerrada", { Motivo = motivo or "La sesión terminó.", Docente = sesion.TeacherName })
	if self.Sesiones[roomId] == sesion then
		self.Sesiones[roomId] = nil
	end
	if self.SesionPorDocente[sesion.TeacherUserId] == roomId then
		self.SesionPorDocente[sesion.TeacherUserId] = nil
	end
	self:Auditar(actor, "CerrarSesion", string.format("%s · %s · %s · %d actividades · %d asistentes",
		roomId, tostring(sesion.TeacherName), tostring(motivo), #sesion.OrdenActividades, contar(sesion.PresentUserIds)))
	self.SesionCerrada:Fire(sesion, motivo)
	return true
end

-- Cierra todas las sesiones abiertas (fin de jornada, fin de periodo, mantenimiento).
function ClassroomService:CerrarTodas(motivo)
	local lista = {}
	for _, sesion in pairs(self.Sesiones) do
		table.insert(lista, sesion)
	end
	for _, sesion in ipairs(lista) do
		self:CerrarSesionInterna(sesion, motivo or "Se cerraron todas las sesiones.")
	end
	return #lista
end

---------------------------------------------------------------------------------------------------
-- Cancelación automática
---------------------------------------------------------------------------------------------------
function ClassroomService:QuitarAlumno(userId, motivo)
	for roomId, sesion in pairs(self.Sesiones) do
		if sesion.ManosLevantadas[userId] then
			sesion.ManosLevantadas[userId] = nil
			self:EnviarDocente(sesion, "Mano", { UserId = userId, Levantada = false, Manos = self:ListaManos(sesion) })
		end
		local inv = self.Invitaciones[roomId]
		if inv and inv.UserId == userId then
			self.Invitaciones[roomId] = nil
			self:EnviarDocente(sesion, "Invitacion", { UserId = userId, Nombre = inv.Nombre, Caducada = true, Motivo = motivo })
		end
		if sesion.InvitadoTablero == userId then
			sesion.InvitadoTablero = nil
			sesion.TurnoHasta = nil
			sesion.TurnoToken = (sesion.TurnoToken or 0) + 1
			self:Llamar("BoardService", "RevocarTurno", roomId)
			self:EnviarAula(sesion, "TurnoTablero", { Fin = true, UserId = userId, Motivo = motivo })
		end
	end
end

function ClassroomService:AlSalirJugador(player)
	local userId = player.UserId
	local roomId = self.SesionPorDocente[userId]
	if roomId and self.Sesiones[roomId] then
		self:CerrarSesionInterna(self.Sesiones[roomId], "El docente salió del servidor.", player)
	end
	self:QuitarAlumno(userId, "El estudiante salió del servidor.")
	self.UltimaAccion[userId] = nil
end

function ClassroomService:AlCambiarCargo(player, cargo, anterior)
	if not esJugador(player) or cargo == anterior then
		return
	end
	local roomId = self.SesionPorDocente[player.UserId]
	if roomId and self.Sesiones[roomId] then
		self:CerrarSesionInterna(self.Sesiones[roomId], "El docente cambió de cargo.", player)
	end
	self:QuitarAlumno(player.UserId, "Cambio de cargo.")
end

function ClassroomService:AlCambiarPeriodo(estado, snapshot)
	if typeof(estado) == "table" then
		snapshot = estado
		estado = estado.Estado
	end
	if typeof(estado) ~= "string" and typeof(snapshot) == "table" then
		estado = snapshot.Estado
	end
	if typeof(estado) ~= "string" or not self.CerrarAlTerminarPeriodo then
		return
	end
	if not TimetableDefinitions.EsClase(estado) and next(self.Sesiones) ~= nil then
		self:CerrarTodas("Terminó el periodo de clase (" .. TimetableDefinitions.Nombre(estado) .. ").")
	end
end

-- Fin de turno decidido por BoardService (turno = nil): limpia el invitado de la sesión y avisa a la sala.
function ClassroomService:AlCambiarTurnoTablero(roomId, turno, motivo)
	local sesion = typeof(roomId) == "string" and self.Sesiones[roomId] or nil
	if not sesion or sesion.State ~= "Abierta" or turno ~= nil or not sesion.InvitadoTablero then
		return
	end
	local userId = sesion.InvitadoTablero
	sesion.InvitadoTablero = nil
	sesion.TurnoHasta = nil
	sesion.TurnoToken = (sesion.TurnoToken or 0) + 1
	self:EnviarAula(sesion, "TurnoTablero", { Fin = true, UserId = userId, Motivo = "Terminó el turno." })
end

-- Agrupa los cambios de ocupación y envía al docente la lista actualizada (Sub "Estado", Parcial = true).
-- También baja las manos de quienes ya no están en el aula.
function ClassroomService:ProgramarEstadoDocente(roomId)
	if typeof(roomId) ~= "string" or not self.Sesiones[roomId] or self._estadoPendiente[roomId] then
		return
	end
	self._estadoPendiente[roomId] = true
	task.delay(self.IntervaloEstadoDocenteSeg, function()
		self._estadoPendiente[roomId] = nil
		local sesion = self.Sesiones[roomId]
		if not sesion then
			return
		end
		local presentes = {}
		for _, player in ipairs(self:JugadoresEnAula(roomId)) do
			presentes[player.UserId] = true
		end
		for userId in pairs(sesion.ManosLevantadas) do
			if not presentes[userId] then
				sesion.ManosLevantadas[userId] = nil
			end
		end
		self:EnviarDocente(sesion, "Estado", {
			Parcial = true,
			Ocupacion = self:OcupacionConNombres(roomId, sesion.TeacherUserId),
			Manos = self:ListaManos(sesion),
		})
	end)
end

---------------------------------------------------------------------------------------------------
-- Acciones del docente
---------------------------------------------------------------------------------------------------
function ClassroomService:AccionAbrirSesion(player, roomId, d)
	if not self:PuedeDirigir(player, roomId) then
		local salon = self:SalonDe(player)
		local texto = "Solo puedes abrir sesión en tu aula asignada."
		if salon then
			texto = "Solo puedes abrir sesión en tu aula asignada: " .. nombreAula(salon) .. " (" .. salon .. ")."
		end
		return self:Rechazo(player, "AbrirSesion", "no_es_tu_aula", texto, true)
	end
	local enClase, periodo = self:EnClase()
	if not enClase then
		return self:Rechazo(player, "AbrirSesion", "fuera_de_clase",
			"Solo se puede abrir sesión durante un periodo de clase (ahora: " .. tostring(periodo) .. ").")
	end
	if not self:CercaDelAula(player, roomId) then
		return self:Rechazo(player, "AbrirSesion", "lejos_del_aula", "Debes estar dentro del aula " .. nombreAula(roomId) .. " para abrir la sesión.")
	end
	local existente = self.Sesiones[roomId]
	if existente then
		if existente.TeacherUserId == player.UserId then
			return exito(self:SnapshotDocente(existente))
		end
		return self:Rechazo(player, "AbrirSesion", "aula_ocupada",
			"Ya hay una sesión abierta en esta aula (" .. tostring(existente.TeacherName) .. ").")
	end

	local tema = ""
	if d.Tema ~= nil and d.Tema ~= "" then
		local limpio, motivo = limpiarTexto(d.Tema, self.MaxTemaCaracteres, false)
		if not limpio then
			if motivo == "largo" then
				return self:Rechazo(player, "AbrirSesion", "texto", "El tema supera los " .. self.MaxTemaCaracteres .. " caracteres.")
			end
			return self:Rechazo(player, "AbrirSesion", "texto", "El tema no es válido.")
		end
		local filtrado = filtrar(limpio, player.UserId, nil)
		if not filtrado then
			return self:Rechazo(player, "AbrirSesion", "filtro", "No se pudo filtrar el tema; inténtalo de nuevo.")
		end
		tema = filtrado
	end

	-- Un docente = una sesión: si dirige otra, se cierra.
	local otra = self.SesionPorDocente[player.UserId]
	if otra and self.Sesiones[otra] then
		self:CerrarSesionInterna(self.Sesiones[otra], "El docente abrió una sesión en otra aula.", player)
	end
	-- La comprobación anterior pudo ceder (filtrado): se revisa de nuevo que el aula siga libre.
	if self.Sesiones[roomId] then
		return self:Rechazo(player, "AbrirSesion", "aula_ocupada", "Otra persona acaba de abrir sesión en esta aula.")
	end

	self.Contador = self.Contador + 1
	local sesion = {
		SessionId = string.format("S%d_%s", self.Contador, roomId),
		RoomId = roomId,
		NombreAula = nombreAula(roomId),
		TeacherUserId = player.UserId,
		TeacherName = player.DisplayName,
		StartedAt = os.time(),
		State = "Abierta",
		Tema = tema,
		Materia = self:MateriaActual(),
		PresentUserIds = {},
		ActiveActivityId = nil,
		UltimaActividadId = nil,
		Actividades = {},
		OrdenActividades = {},
		ContadorActividades = 0,
		ManosLevantadas = {},
		InvitadoTablero = nil,
		TurnoHasta = nil,
		TurnoToken = 0,
	}
	self.Sesiones[roomId] = sesion
	self.SesionPorDocente[player.UserId] = roomId

	local presentes = {}
	for _, alumno in ipairs(self:JugadoresEnAula(roomId)) do
		if alumno ~= player then
			sesion.PresentUserIds[alumno.UserId] = true
			presentes[alumno.UserId] = true
		end
	end

	local datosApertura = self:DatosBase(sesion)
	self:EnviarAula(sesion, "SesionAbierta", datosApertura)

	-- Estudiantes de esta aula que no están presentes: solo un recordatorio (sin datos de la clase).
	for _, alumno in ipairs(Players:GetPlayers()) do
		if alumno ~= player and not presentes[alumno.UserId] and self:SalonDe(alumno) == roomId
			and self:Tiene(alumno, "aula.estudiante") and not self:Tiene(alumno, "aula.docente") then
			self:Notificar(alumno, "Comenzó tu clase en " .. sesion.NombreAula .. ". Dirígete a tu salón.", "info", 6)
		end
	end

	self:Auditar(player, "AbrirSesion", string.format("%s · %s · tema: %s", roomId, sesion.SessionId, tema ~= "" and tema or "-"))
	self.SesionAbierta:Fire(sesion)
	return exito(self:SnapshotDocente(sesion))
end

function ClassroomService:AccionCerrarSesion(player, roomId, d)
	local sesion = self.Sesiones[roomId]
	if not sesion then
		return self:Rechazo(player, "CerrarSesion", "sin_sesion", "No hay una sesión abierta en esta aula.")
	end
	local esDocente = sesion.TeacherUserId == player.UserId
	if not esDocente and not self:Tiene(player, "horario.editar") then
		return self:Rechazo(player, "CerrarSesion", "no_es_tu_sesion", "Solo el docente de la sesión puede cerrarla.", true)
	end
	local motivo = "El docente cerró la sesión."
	if not esDocente then
		motivo = "Coordinación cerró la sesión."
	end
	self:CerrarSesionInterna(sesion, motivo, player)
	return exito({ Cerrada = true, RoomId = roomId })
end

function ClassroomService:AccionFijarTema(player, roomId, d)
	local sesion, rechazo = self:SesionDelDocente(player, roomId, "FijarTema")
	if not sesion then
		return rechazo
	end
	local limpio, motivo = limpiarTexto(d.Tema, self.MaxTemaCaracteres, false)
	if not limpio then
		if motivo == "largo" then
			return self:Rechazo(player, "FijarTema", "texto", "El tema supera los " .. self.MaxTemaCaracteres .. " caracteres.")
		end
		return self:Rechazo(player, "FijarTema", "texto", "Escribe un tema válido.")
	end
	local filtrado = filtrar(limpio, player.UserId, nil)
	if not filtrado then
		return self:Rechazo(player, "FijarTema", "filtro", "No se pudo filtrar el tema; inténtalo de nuevo.")
	end
	if self.Sesiones[roomId] ~= sesion then
		return self:Rechazo(player, "FijarTema", "sin_sesion", "La sesión ya no está abierta.")
	end
	sesion.Tema = filtrado
	self:EnviarAula(sesion, "Tema", { Tema = filtrado, Docente = sesion.TeacherName })
	self:Auditar(player, "FijarTema", roomId .. " · " .. filtrado)
	return exito({ Tema = filtrado })
end

function ClassroomService:AccionEnviarAviso(player, roomId, d)
	local sesion, rechazo = self:SesionDelDocente(player, roomId, "EnviarAviso")
	if not sesion then
		return rechazo
	end
	local limpio, motivo = limpiarTexto(d.Texto, self.MaxAvisoCaracteres, false)
	if not limpio then
		if motivo == "largo" then
			return self:Rechazo(player, "EnviarAviso", "texto", "El aviso supera los " .. self.MaxAvisoCaracteres .. " caracteres.")
		end
		return self:Rechazo(player, "EnviarAviso", "texto", "Escribe un aviso válido.")
	end
	local filtrado = filtrar(limpio, player.UserId, nil)
	if not filtrado then
		return self:Rechazo(player, "EnviarAviso", "filtro", "No se pudo filtrar el aviso; no se envió.")
	end
	if self.Sesiones[roomId] ~= sesion then
		return self:Rechazo(player, "EnviarAviso", "sin_sesion", "La sesión ya no está abierta.")
	end
	local enviados = self:EnviarAula(sesion, "Aviso", {
		Texto = filtrado, Docente = sesion.TeacherName, Cargo = self:CargoDe(player), T = ahora(),
	})
	self:Auditar(player, "EnviarAviso", roomId .. " · " .. filtrado)
	return exito({ Enviado = true, Destinatarios = enviados })
end

function ClassroomService:AccionTomarAsistencia(player, roomId, d)
	local sesion, rechazo = self:SesionDelDocente(player, roomId, "TomarAsistencia")
	if not sesion then
		return rechazo
	end
	local ocupacion = self:OcupacionConNombres(roomId, sesion.TeacherUserId)
	local sentados = {}
	for _, registro in ipairs(ocupacion.Sentados) do
		sesion.PresentUserIds[registro.UserId] = true
		sentados[registro.UserId] = true
	end
	for _, registro in ipairs(ocupacion.DePie) do
		sesion.PresentUserIds[registro.UserId] = true
	end
	local oficial = {}
	local ok, asistencia = self:Llamar("SchoolDayService", "Asistencia", roomId)
	if ok then
		oficial = normalizarAsistencia(asistencia)
	end
	local datos = {
		Sentados = ocupacion.Sentados,
		DePie = ocupacion.DePie,
		Capacidad = ocupacion.Capacidad,
		Total = ocupacion.Total,
		Oficial = oficial,
		T = ahora(),
	}
	self:EnviarDocente(sesion, "Asistencia", datos)
	for _, alumno in ipairs(self:JugadoresEnAula(roomId)) do
		if alumno.UserId ~= sesion.TeacherUserId then
			self:Enviar(alumno, "Asistencia", {
				RoomId = roomId, SessionId = sesion.SessionId, Propia = true, Estado = "Presente",
				Sentado = sentados[alumno.UserId] == true,
			})
		end
	end
	self:Auditar(player, "TomarAsistencia", string.format("%s · %d sentados · %d de pie", roomId, #ocupacion.Sentados, #ocupacion.DePie))
	return exito(datos)
end

function ClassroomService:AccionCrearActividad(player, roomId, d)
	local sesion, rechazo = self:SesionDelDocente(player, roomId, "CrearActividad")
	if not sesion then
		return rechazo
	end
	local enClase, periodo = self:EnClase()
	if not enClase then
		return self:Rechazo(player, "CrearActividad", "fuera_de_clase", "Las actividades solo se crean en periodo de clase (ahora: " .. tostring(periodo) .. ").")
	end
	if #sesion.OrdenActividades >= self.MaxActividadesPorSesion then
		return self:Rechazo(player, "CrearActividad", "limite", "Esta sesión alcanzó el máximo de " .. self.MaxActividadesPorSesion .. " actividades.")
	end
	local tipo = d.Type or d.Tipo
	if tipo ~= "Texto" and tipo ~= "Opciones" then
		return self:Rechazo(player, "CrearActividad", "tipo", "El tipo de actividad debe ser Texto u Opciones.", true)
	end
	local segundos = self.SegundosPorDefecto
	if d.Segundos ~= nil then
		segundos = entero(d.Segundos, self.SegundosMin, self.SegundosMax)
		if not segundos then
			return self:Rechazo(player, "CrearActividad", "tiempo",
				string.format("El tiempo debe ser un número entero entre %d y %d segundos.", self.SegundosMin, self.SegundosMax))
		end
	end
	local pregunta, motivo = limpiarTexto(d.Prompt or d.Pregunta, self.MaxPreguntaCaracteres, true)
	if not pregunta then
		if motivo == "largo" then
			return self:Rechazo(player, "CrearActividad", "texto", "La pregunta supera los " .. self.MaxPreguntaCaracteres .. " caracteres.")
		end
		return self:Rechazo(player, "CrearActividad", "texto", "Escribe la pregunta de la actividad.")
	end

	local opcionesLimpias = nil
	local correcta = nil
	if tipo == "Opciones" then
		local fuente = d.Options or d.Opciones
		if typeof(fuente) ~= "table" then
			return self:Rechazo(player, "CrearActividad", "opciones", "Añade entre 2 y 4 opciones.")
		end
		local n = #fuente
		if n < self.MinOpciones or n > self.MaxOpciones or contar(fuente) ~= n then
			return self:Rechazo(player, "CrearActividad", "opciones", "Añade entre " .. self.MinOpciones .. " y " .. self.MaxOpciones .. " opciones.")
		end
		opcionesLimpias = {}
		for i = 1, n do
			local opcion = limpiarTexto(fuente[i], self.MaxOpcionCaracteres, false)
			if not opcion then
				return self:Rechazo(player, "CrearActividad", "opciones",
					"La opción " .. i .. " está vacía o supera los " .. self.MaxOpcionCaracteres .. " caracteres.")
			end
			opcionesLimpias[i] = opcion
		end
		if d.Correcta ~= nil and d.Correcta ~= 0 then
			correcta = entero(d.Correcta, 1, n)
			if not correcta then
				return self:Rechazo(player, "CrearActividad", "correcta", "La opción correcta no es válida.")
			end
		end
	end

	-- Filtrado (cede): pregunta y opciones para toda la clase.
	local preguntaFiltrada = filtrar(pregunta, player.UserId, nil)
	if not preguntaFiltrada then
		return self:Rechazo(player, "CrearActividad", "filtro", "No se pudo filtrar la pregunta; inténtalo de nuevo.")
	end
	local opcionesFiltradas = nil
	if opcionesLimpias then
		opcionesFiltradas = {}
		for i, opcion in ipairs(opcionesLimpias) do
			local filtrada = filtrar(opcion, player.UserId, nil)
			if not filtrada then
				return self:Rechazo(player, "CrearActividad", "filtro", "No se pudo filtrar la opción " .. i .. "; inténtalo de nuevo.")
			end
			opcionesFiltradas[i] = filtrada
		end
	end
	if self.Sesiones[roomId] ~= sesion or sesion.State ~= "Abierta" then
		return self:Rechazo(player, "CrearActividad", "sin_sesion", "La sesión ya no está abierta.")
	end

	-- Una actividad activa a la vez: la anterior se cierra.
	local anterior = sesion.ActiveActivityId and sesion.Actividades[sesion.ActiveActivityId] or nil
	if anterior then
		self:CerrarActividadInterna(sesion, anterior, "El docente inició una nueva actividad.")
	end

	sesion.ContadorActividades = sesion.ContadorActividades + 1
	local creada = ahora()
	local act = {
		Id = "A" .. sesion.ContadorActividades,
		Type = tipo,
		Prompt = preguntaFiltrada,
		Options = opcionesFiltradas,
		Correcta = correcta,
		CreatedAt = creada,
		DueAt = creada + segundos,
		Segundos = segundos,
		Estado = "Abierta",
		Submissions = {},
		Grades = {},
		Pendientes = {},
		Destinatarios = {},
		Publicada = false,
	}
	sesion.Actividades[act.Id] = act
	table.insert(sesion.OrdenActividades, act.Id)
	sesion.ActiveActivityId = act.Id

	-- Solo los estudiantes presentes en la zona reciben la actividad.
	local publica = self:ActividadPublica(act, false)
	publica.Respuestas = nil
	local destinatarios = 0
	for _, alumno in ipairs(self:JugadoresEnAula(roomId)) do
		if alumno.UserId ~= sesion.TeacherUserId then
			act.Destinatarios[alumno.UserId] = true
			sesion.PresentUserIds[alumno.UserId] = true
			local datos = { RoomId = roomId, SessionId = sesion.SessionId, Actividad = publica }
			if self:Enviar(alumno, "Actividad", datos) then
				destinatarios = destinatarios + 1
			end
		end
	end
	self:EnviarDocente(sesion, "Actividad", { Docente = true, Actividad = self:ActividadPublica(act, true), Destinatarios = destinatarios })

	-- Cierre automático al vencer el tiempo.
	task.delay(segundos + 0.25, function()
		if self.Sesiones[roomId] == sesion and act.Estado == "Abierta" then
			self:CerrarActividadInterna(sesion, act, "Se acabó el tiempo.")
		end
	end)

	self:Auditar(player, "CrearActividad", string.format("%s · %s · %s · %d s · %d destinatarios", roomId, act.Id, tipo, segundos, destinatarios))
	self.ActividadCreada:Fire(sesion, act)
	return exito({ Actividad = self:ActividadPublica(act, true), Destinatarios = destinatarios })
end

function ClassroomService:AccionCerrarActividad(player, roomId, d)
	local sesion, rechazo = self:SesionDelDocente(player, roomId, "CerrarActividad")
	if not sesion then
		return rechazo
	end
	local act = actividadDe(sesion, d.ActividadId)
	if not act then
		return self:Rechazo(player, "CerrarActividad", "actividad_desconocida", "No hay una actividad activa.")
	end
	if act.Estado ~= "Abierta" then
		return self:Rechazo(player, "CerrarActividad", "actividad_cerrada", "La actividad ya está cerrada.")
	end
	self:CerrarActividadInterna(sesion, act, "El docente cerró la actividad.")
	self:Auditar(player, "CerrarActividad", roomId .. " · " .. act.Id .. " · " .. contar(act.Submissions) .. " respuestas")
	return exito({ Actividad = self:ActividadPublica(act, true), Respuestas = self:ListaRespuestas(act) })
end

function ClassroomService:AccionInvitarTablero(player, roomId, d)
	local sesion, rechazo = self:SesionDelDocente(player, roomId, "InvitarTablero")
	if not sesion then
		return rechazo
	end
	local enClase, periodo = self:EnClase()
	if not enClase then
		return self:Rechazo(player, "InvitarTablero", "fuera_de_clase", "El tablero solo se comparte en periodo de clase (ahora: " .. tostring(periodo) .. ").")
	end
	local BoardService = self:Servicio("BoardService")
	if not BoardService or typeof(BoardService.ConcederTurno) ~= "function" then
		return self:Rechazo(player, "InvitarTablero", "sin_tablero", "El tablero no está disponible en este servidor.")
	end
	local userId = entero(d.ObjetivoUserId, 1, nil)
	local objetivo = userId and Players:GetPlayerByUserId(userId) or nil
	if not objetivo or objetivo == player then
		return self:Rechazo(player, "InvitarTablero", "objetivo", "Elige a un estudiante conectado.")
	end
	if not self:Tiene(objetivo, "aula.estudiante") then
		return self:Rechazo(player, "InvitarTablero", "objetivo", objetivo.DisplayName .. " no es estudiante; solo se invita a estudiantes.")
	end
	if not self:EstaEnAula(objetivo, roomId) then
		return self:Rechazo(player, "InvitarTablero", "objetivo_ausente", objetivo.DisplayName .. " no está en el aula.", true)
	end
	local turno = self:TurnoPublico(sesion)
	if turno then
		return self:Rechazo(player, "InvitarTablero", "turno_activo", turno.Nombre .. " ya está en el tablero; revoca su turno primero.")
	end
	local invitacion = {
		UserId = objetivo.UserId, Nombre = objetivo.DisplayName, Expira = ahora() + self.InvitacionSeg, SessionId = sesion.SessionId,
	}
	self.Invitaciones[roomId] = invitacion
	if sesion.ManosLevantadas[objetivo.UserId] then
		sesion.ManosLevantadas[objetivo.UserId] = nil
	end
	self:Enviar(objetivo, "Invitacion", {
		RoomId = roomId, SessionId = sesion.SessionId, Expira = invitacion.Expira, Segundos = self.InvitacionSeg,
		Docente = sesion.TeacherName,
	})
	self:EnviarDocente(sesion, "Invitacion", {
		Pendiente = true, UserId = invitacion.UserId, Nombre = invitacion.Nombre, Expira = invitacion.Expira,
		Manos = self:ListaManos(sesion),
	})
	task.delay(self.InvitacionSeg + 0.25, function()
		if self.Invitaciones[roomId] == invitacion then
			self.Invitaciones[roomId] = nil
			local actual = self.Sesiones[roomId]
			if actual == sesion then
				self:EnviarDocente(sesion, "Invitacion", { Caducada = true, UserId = invitacion.UserId, Nombre = invitacion.Nombre })
			end
			local alumno = Players:GetPlayerByUserId(invitacion.UserId)
			if alumno then
				self:Enviar(alumno, "Invitacion", { RoomId = roomId, SessionId = sesion.SessionId, Caducada = true })
			end
		end
	end)
	self:Auditar(player, "InvitarTablero", roomId .. " · " .. objetivo.Name)
	return exito({ Invitado = invitacion.Nombre, UserId = invitacion.UserId, Expira = invitacion.Expira })
end

function ClassroomService:AccionRevocarTablero(player, roomId, d)
	local sesion, rechazo = self:SesionDelDocente(player, roomId, "RevocarTablero")
	if not sesion then
		return rechazo
	end
	local habia = sesion.InvitadoTablero
	sesion.InvitadoTablero = nil
	sesion.TurnoHasta = nil
	sesion.TurnoToken = (sesion.TurnoToken or 0) + 1
	self:Llamar("BoardService", "RevocarTurno", roomId)
	local inv = self.Invitaciones[roomId]
	self.Invitaciones[roomId] = nil
	if inv then
		local alumno = Players:GetPlayerByUserId(inv.UserId)
		if alumno then
			self:Enviar(alumno, "Invitacion", { RoomId = roomId, SessionId = sesion.SessionId, Caducada = true, Revocada = true })
		end
	end
	self:EnviarAula(sesion, "TurnoTablero", { Fin = true, Revocado = true, UserId = habia })
	self:Auditar(player, "RevocarTablero", roomId .. " · " .. tostring(habia or "-"))
	return exito({ Revocado = true })
end

function ClassroomService:AccionCalificar(player, roomId, d)
	local sesion, rechazo = self:SesionDelDocente(player, roomId, "Calificar")
	if not sesion then
		return rechazo
	end
	local act = actividadDe(sesion, d.ActividadId)
	if not act then
		return self:Rechazo(player, "Calificar", "actividad_desconocida", "Elige una actividad de esta sesión.")
	end
	local userId = entero(d.ObjetivoUserId, 1, nil)
	if not userId or userId == player.UserId then
		return self:Rechazo(player, "Calificar", "objetivo", "Elige a un estudiante.")
	end
	local alumno = Players:GetPlayerByUserId(userId)
	if not act.Submissions[userId] and not (alumno and self:EstaEnAula(alumno, roomId)) then
		return self:Rechazo(player, "Calificar", "objetivo", "Ese estudiante no respondió ni está en el aula.", true)
	end
	local puntos = tonumber(d.Puntos)
	if not esFinito(puntos) or puntos < 0 or puntos > 10 then
		return self:Rechazo(player, "Calificar", "puntos", "La nota debe estar entre 0 y 10.")
	end
	puntos = math.floor(puntos * 10 + 0.5) / 10
	local comentario = nil
	if d.Comentario ~= nil and d.Comentario ~= "" then
		local limpio, motivo = limpiarTexto(d.Comentario, self.MaxComentarioCaracteres, false)
		if not limpio then
			if motivo == "largo" then
				return self:Rechazo(player, "Calificar", "texto", "El comentario supera los " .. self.MaxComentarioCaracteres .. " caracteres.")
			end
			return self:Rechazo(player, "Calificar", "texto", "El comentario no es válido.")
		end
		comentario = filtrar(limpio, player.UserId, alumno and userId or nil)
		if not comentario then
			return self:Rechazo(player, "Calificar", "filtro", "No se pudo filtrar el comentario; inténtalo de nuevo.")
		end
	end
	act.Grades[userId] = { Puntos = puntos, Comentario = comentario, T = ahora() }
	sesion.PresentUserIds[userId] = true
	if alumno then
		local envio = act.Submissions[userId]
		self:Enviar(alumno, "Resultado", {
			RoomId = roomId, SessionId = sesion.SessionId, ActividadId = act.Id, Prompt = act.Prompt,
			Puntos = puntos, Comentario = comentario, Docente = sesion.TeacherName,
			TuRespuesta = envio and envio.Respuesta or nil,
		})
	end
	self:Auditar(player, "Calificar", string.format("%s · %s · %s · %.1f", roomId, act.Id, tostring(userId), puntos))
	return exito({ UserId = userId, Puntos = puntos, Comentario = comentario, ActividadId = act.Id })
end

-- Resumen anónimo de una actividad (sin nombres).
function ClassroomService:ResumenAnonimo(sesion, act)
	local total = contar(act.Submissions)
	local presentes = 0
	for _, alumno in ipairs(self:JugadoresEnAula(sesion.RoomId)) do
		if alumno.UserId ~= sesion.TeacherUserId then
			presentes = presentes + 1
		end
	end
	local resumen = {
		ActividadId = act.Id, Prompt = act.Prompt, Type = act.Type, Total = total, Presentes = presentes,
		Cerrada = act.Estado == "Cerrada",
	}
	if act.Type == "Opciones" and act.Options then
		local votos = {}
		for i = 1, #act.Options do
			votos[i] = 0
		end
		local correctas = 0
		for _, envio in pairs(act.Submissions) do
			if envio.Indice and votos[envio.Indice] then
				votos[envio.Indice] = votos[envio.Indice] + 1
			end
			if envio.Correcta then
				correctas = correctas + 1
			end
		end
		resumen.Opciones = {}
		for i, texto in ipairs(act.Options) do
			table.insert(resumen.Opciones, { Texto = texto, Votos = votos[i], EsCorrecta = act.Correcta == i })
		end
		if act.Correcta then
			resumen.Correctas = correctas
			if total > 0 then
				resumen.PorcentajeCorrectas = math.floor(correctas / total * 100 + 0.5)
			else
				resumen.PorcentajeCorrectas = 0
			end
		end
	end
	local suma, calificadas = 0, 0
	for _, nota in pairs(act.Grades) do
		suma = suma + nota.Puntos
		calificadas = calificadas + 1
	end
	resumen.Calificadas = calificadas
	if calificadas > 0 then
		resumen.Promedio = math.floor(suma / calificadas * 10 + 0.5) / 10
	end
	return resumen
end

function ClassroomService:AccionPublicarResultados(player, roomId, d)
	local sesion, rechazo = self:SesionDelDocente(player, roomId, "PublicarResultados")
	if not sesion then
		return rechazo
	end
	local act = actividadDe(sesion, d.ActividadId)
	if not act then
		return self:Rechazo(player, "PublicarResultados", "actividad_desconocida", "Todavía no hay actividades en esta sesión.")
	end
	-- Publicar revela la respuesta correcta: la actividad se cierra antes.
	if act.Estado == "Abierta" then
		self:CerrarActividadInterna(sesion, act, "Se publicaron los resultados.")
	end
	act.Publicada = true
	local resumen = self:ResumenAnonimo(sesion, act)
	self:EnviarAula(sesion, "Resultados", resumen)
	self:Auditar(player, "PublicarResultados", roomId .. " · " .. act.Id .. " · " .. resumen.Total .. " respuestas")
	return exito(resumen)
end

---------------------------------------------------------------------------------------------------
-- Acciones del estudiante
---------------------------------------------------------------------------------------------------

-- Comprobaciones comunes: sesión abierta, presente en el aula, no es el docente. Devuelve sesion | nil, rechazo.
function ClassroomService:SesionDelAlumno(player, roomId, accion, exigirClase)
	local sesion = self.Sesiones[roomId]
	if not sesion then
		return nil, self:Rechazo(player, accion, "sin_sesion", "No hay una clase abierta en esta aula.")
	end
	if sesion.TeacherUserId == player.UserId then
		return nil, self:Rechazo(player, accion, "docente", "El docente no puede hacer esto en su propia sesión.")
	end
	if not self:EstaEnAula(player, roomId) then
		return nil, self:Rechazo(player, accion, "fuera_del_aula", "Debes estar dentro del aula " .. sesion.NombreAula .. ".", true)
	end
	if exigirClase then
		local enClase, periodo = self:EnClase()
		if not enClase then
			return nil, self:Rechazo(player, accion, "fuera_de_clase", "No es periodo de clase (ahora: " .. tostring(periodo) .. ").")
		end
	end
	return sesion
end

function ClassroomService:AccionResponder(player, roomId, d)
	local sesion, rechazo = self:SesionDelAlumno(player, roomId, "Responder", true)
	if not sesion then
		return rechazo
	end
	local userId = player.UserId
	local act = nil
	if typeof(d.ActividadId) == "string" then
		act = sesion.Actividades[d.ActividadId]
	elseif d.ActividadId == nil and sesion.ActiveActivityId then
		act = sesion.Actividades[sesion.ActiveActivityId]
	end
	if not act then
		return self:Rechazo(player, "Responder", "actividad_desconocida", "Esa actividad no existe en esta clase.", true)
	end
	if act.Estado ~= "Abierta" or ahora() > act.DueAt then
		return self:Rechazo(player, "Responder", "actividad_cerrada", "La actividad ya está cerrada.")
	end
	if act.Submissions[userId] or act.Pendientes[userId] then
		return self:Rechazo(player, "Responder", "ya_respondido", "Ya respondiste esta actividad.", true)
	end

	local respuesta, indice, correcta = nil, nil, nil
	if act.Type == "Opciones" then
		indice = entero(d.Indice, 1, act.Options and #act.Options or 0)
		if not indice then
			return self:Rechazo(player, "Responder", "opcion", "Elige una de las opciones.")
		end
		respuesta = act.Options[indice]
		if act.Correcta then
			correcta = indice == act.Correcta
		end
	else
		local limpio, motivo = limpiarTexto(d.Respuesta, self.MaxRespuestaCaracteres, true)
		if not limpio then
			if motivo == "largo" then
				return self:Rechazo(player, "Responder", "texto", "La respuesta supera los " .. self.MaxRespuestaCaracteres .. " caracteres.")
			end
			return self:Rechazo(player, "Responder", "texto", "Escribe tu respuesta.")
		end
		-- Marca de pendiente: evita dos respuestas mientras el filtrado cede.
		act.Pendientes[userId] = true
		local filtrada = filtrar(limpio, userId, sesion.TeacherUserId)
		act.Pendientes[userId] = nil
		if not filtrada then
			return self:Rechazo(player, "Responder", "filtro", "No se pudo filtrar tu respuesta; inténtalo de nuevo.")
		end
		if act.Estado ~= "Abierta" or act.Submissions[userId] then
			return self:Rechazo(player, "Responder", "actividad_cerrada", "La actividad se cerró mientras enviabas.")
		end
		respuesta = filtrada
	end

	local t = ahora()
	act.Submissions[userId] = { Respuesta = respuesta, Indice = indice, Correcta = correcta, T = t, Nombre = player.DisplayName }
	sesion.PresentUserIds[userId] = true
	self:Acreditar(player, RECOMPENSAS.Respuesta, "Respuesta", "Actividad " .. act.Id .. " · " .. roomId)
	self:EnviarDocente(sesion, "Respuesta", {
		ActividadId = act.Id,
		Respuesta = {
			UserId = userId, Nombre = player.DisplayName, Respuesta = respuesta, Indice = indice, Correcta = correcta, T = t,
		},
		Total = contar(act.Submissions),
	})
	self:Auditar(player, "Responder", roomId .. " · " .. act.Id)
	return exito({ Recibida = true, ActividadId = act.Id, T = t, Indice = indice })
end

function ClassroomService:AccionLevantarMano(player, roomId, d)
	local sesion, rechazo = self:SesionDelAlumno(player, roomId, "LevantarMano", true)
	if not sesion then
		return rechazo
	end
	local userId = player.UserId
	local levantar = d.Levantar
	if typeof(levantar) ~= "boolean" then
		levantar = sesion.ManosLevantadas[userId] == nil
	end
	if levantar then
		sesion.ManosLevantadas[userId] = sesion.ManosLevantadas[userId] or ahora()
	else
		sesion.ManosLevantadas[userId] = nil
	end
	sesion.PresentUserIds[userId] = true
	self:EnviarDocente(sesion, "Mano", {
		UserId = userId, Nombre = player.DisplayName, Levantada = levantar, Manos = self:ListaManos(sesion),
	})
	return exito({ Levantada = levantar })
end

function ClassroomService:AccionAceptarInvitacion(player, roomId, d)
	local sesion = self.Sesiones[roomId]
	local inv = self.Invitaciones[roomId]
	if not sesion or not inv or inv.UserId ~= player.UserId or inv.SessionId ~= sesion.SessionId or ahora() > inv.Expira then
		return self:Rechazo(player, "AceptarInvitacion", "sin_invitacion", "No tienes una invitación vigente al tablero.", true)
	end
	if d.Aceptar == false then
		self.Invitaciones[roomId] = nil
		self:EnviarDocente(sesion, "Invitacion", { Rechazada = true, UserId = inv.UserId, Nombre = inv.Nombre })
		return exito({ Aceptada = false })
	end
	local sesionAlumno, rechazo = self:SesionDelAlumno(player, roomId, "AceptarInvitacion", true)
	if not sesionAlumno then
		return rechazo
	end
	local turnoSeg = self.TurnoTableroSeg
	local ok, resultado, expira = self:Llamar("BoardService", "ConcederTurno", roomId, player, turnoSeg)
	if not ok or resultado == false then
		return self:Rechazo(player, "AceptarInvitacion", "tablero", "El tablero no está disponible ahora mismo.")
	end
	self.Invitaciones[roomId] = nil
	sesion.InvitadoTablero = player.UserId
	sesion.TurnoHasta = ahora() + turnoSeg
	if esFinito(expira) and expira > ahora() then
		-- BoardService acota la duración del turno: se usa su caducidad real.
		sesion.TurnoHasta = expira
		turnoSeg = math.max(1, math.floor(expira - ahora() + 0.5))
	end
	sesion.TurnoToken = (sesion.TurnoToken or 0) + 1
	local token = sesion.TurnoToken
	self:EnviarAula(sesion, "TurnoTablero", {
		UserId = player.UserId, Nombre = player.DisplayName, Segundos = turnoSeg, Hasta = sesion.TurnoHasta,
	})
	task.delay(turnoSeg + 0.25, function()
		if self.Sesiones[roomId] == sesion and sesion.TurnoToken == token and sesion.InvitadoTablero == player.UserId then
			sesion.InvitadoTablero = nil
			sesion.TurnoHasta = nil
			self:EnviarAula(sesion, "TurnoTablero", { Fin = true, UserId = player.UserId, Motivo = "Terminó el turno." })
		end
	end)
	self:Auditar(player, "AceptarInvitacion", roomId .. " · turno " .. turnoSeg .. " s")
	return exito({ Aceptada = true, Segundos = turnoSeg, Hasta = sesion.TurnoHasta })
end

