function DataService.PerfilPorDefecto()
	local graficos = Config.Graficos or {}
	local economia = Config.Economia or {}
	local spawns = Config.Spawns or {}
	return {
		Version = ESQUEMA_VERSION,
		Ajustes = {
			ModoGraficos = graficos.ModoPorDefecto or "Medio",
			Particulas = true,
			DecoracionLejana = true,
			Postprocesado = false,
			SonidosAmbiente = true,
			AnimacionesCosmeticas = false,
			LimiteEfectos = 1,
			EscalaTexto = 1,
			MovimientoReducido = false,
			Subtitulos = true,
			FormatoHora = 24,
			OcultarEtiquetas = false,
			IntroVista = false,
		},
		Economia = { Saldo = economia.SaldoInicial or 50, GanadoHoy = 0, DiaUltimo = "", Historial = {} },
		Cuaderno = { Titulo = "Mi cuaderno", Paginas = { { Materia = "MAT", Texto = "", Actualizado = 0 } } },
		Progreso = {
			Asistencias = 0, Tardanzas = 0, Ausencias = 0, RespuestasCorrectas = 0, ClasesCompletadas = 0,
			Goles = 0, TareasLimpieza = 0, UltimoCargo = spawns.CargoPorDefecto or "Estudiante",
		},
		Moderacion = { Advertencias = {}, BloqueoHasta = 0 },
		Meta = { Creado = 0, UltimaEntrada = 0, Entradas = 0 },
	}
end

---------------------------------------------------------------------------------------------------
-- Migraciones: Migraciones[versionOrigen](perfil) -> perfil en versionOrigen + 1
---------------------------------------------------------------------------------------------------
DataService.Migraciones = {
	-- Perfiles sin Version (anteriores a 2.0.0) o con Version 0 -> esquema 1.
	[0] = function(perfil)
		if typeof(perfil.Ajustes) ~= "table" then
			perfil.Ajustes = {}
		end
		if typeof(perfil.Economia) ~= "table" then
			perfil.Economia = {}
		end
		-- Nombres antiguos posibles de campos de monedas.
		if perfil.Economia.Saldo == nil and esFinito(perfil.Monedas) then
			perfil.Economia.Saldo = perfil.Monedas
		end
		perfil.Monedas = nil
		perfil.Version = 1
		return perfil
	end,
}

function DataService:Migrar(perfil)
	if typeof(perfil) ~= "table" then
		return self.PerfilPorDefecto(), false
	end
	local version = perfil.Version
	if not esFinito(version) then
		version = 0
	end
	version = math.floor(version)
	if version > ESQUEMA_VERSION then
		-- Datos de una versión más nueva del juego: no se persisten para no destruir campos desconocidos.
		warn(PREFIJO .. " Perfil con esquema v" .. version .. " superior al soportado (v" .. ESQUEMA_VERSION .. "); se usa en modo solo sesión.")
		return perfil, true
	end
	local iteraciones = 0
	while version < ESQUEMA_VERSION and iteraciones < 32 do
		local migracion = self.Migraciones[version]
		if typeof(migracion) ~= "function" then
			warn(PREFIJO .. " No existe migración desde el esquema v" .. version .. "; se completa con valores por defecto.")
			perfil.Version = ESQUEMA_VERSION
			break
		end
		local ok, resultado = pcall(migracion, perfil)
		if ok and typeof(resultado) == "table" then
			perfil = resultado
		else
			warn(PREFIJO .. " Error en la migración v" .. version .. ": " .. tostring(resultado))
			perfil.Version = version + 1
		end
		if not esFinito(perfil.Version) or perfil.Version <= version then
			perfil.Version = version + 1
		end
		version = math.floor(perfil.Version)
		iteraciones = iteraciones + 1
	end
	perfil.Version = ESQUEMA_VERSION
	return perfil, false
end

---------------------------------------------------------------------------------------------------
-- Saneamiento: devuelve una copia del perfil con tipos y límites garantizados
---------------------------------------------------------------------------------------------------
local camposAjustes = RemoteContracts.EsquemaAjustes and RemoteContracts.EsquemaAjustes.campos or {}

function DataService:Sanear(origen)
	local base = self.PerfilPorDefecto()
	if typeof(origen) ~= "table" then
		return base
	end
	local limites = Config.Limites or {}
	local cuadernoCfg = Config.Cuaderno or {}
	local moderacionCfg = Config.Moderacion or {}

	-- Ajustes: cada clave debe pasar su descriptor de RemoteContracts.EsquemaAjustes.
	local ajustes = typeof(origen.Ajustes) == "table" and origen.Ajustes or {}
	for _, clave in ipairs(RemoteContracts.ClavesAjustes or {}) do
		local descriptor = camposAjustes[clave]
		local valor = ajustes[clave]
		if valor ~= nil and descriptor then
			local ok = Validate.ComprobarValor(descriptor, valor, clave)
			if ok then
				base.Ajustes[clave] = valor
			end
		end
	end

	-- Economía.
	local eco = typeof(origen.Economia) == "table" and origen.Economia or {}
	base.Economia.Saldo = numero(eco.Saldo, base.Economia.Saldo, 0, MAX_SALDO, true)
	base.Economia.GanadoHoy = numero(eco.GanadoHoy, 0, 0, MAX_SALDO, true)
	base.Economia.DiaUltimo = texto(eco.DiaUltimo, "", 10)
	base.Economia.Historial = {}
	for _, mov in ipairs(ultimos(eco.Historial, MAX_HISTORIAL)) do
		if typeof(mov) == "table" then
			table.insert(base.Economia.Historial, {
				T = numero(mov.T, 0, 0, nil, true),
				Tipo = texto(mov.Tipo, "", 24),
				Monto = numero(mov.Monto, 0, -MAX_SALDO, MAX_SALDO, true),
				Detalle = texto(mov.Detalle, "", 80),
			})
		end
	end

	-- Cuaderno.
	local cuaderno = typeof(origen.Cuaderno) == "table" and origen.Cuaderno or {}
	base.Cuaderno.Titulo = texto(cuaderno.Titulo, "Mi cuaderno", limites.MaxNombreCaracteres or 24)
	if base.Cuaderno.Titulo == "" then
		base.Cuaderno.Titulo = "Mi cuaderno"
	end
	local paginas = {}
	if typeof(cuaderno.Paginas) == "table" then
		for i = 1, math.min(#cuaderno.Paginas, cuadernoCfg.MaxPaginas or 20) do
			local pagina = cuaderno.Paginas[i]
			if typeof(pagina) == "table" then
				-- Código de materia libre (máx. 8 caracteres); vacío o inválido -> "MAT".
				local materia = texto(pagina.Materia, "MAT", 8)
				if materia == "" then
					materia = "MAT"
				end
				local entrada = {
					Materia = materia,
					Texto = texto(pagina.Texto, "", cuadernoCfg.MaxCaracteresPagina or 1200),
					Actualizado = numero(pagina.Actualizado, 0, 0, nil, true),
				}
				if typeof(pagina.Compartida) == "boolean" then
					entrada.Compartida = pagina.Compartida
				end
				table.insert(paginas, entrada)
			end
		end
	end
	if #paginas > 0 then
		base.Cuaderno.Paginas = paginas
	end

	-- Progreso.
	local progreso = typeof(origen.Progreso) == "table" and origen.Progreso or {}
	for clave, defecto in pairs(base.Progreso) do
		if clave ~= "UltimoCargo" then
			base.Progreso[clave] = numero(progreso[clave], defecto, 0, MAX_SALDO, true)
		end
	end
	if RoleDefinitions.Existe(progreso.UltimoCargo) then
		base.Progreso.UltimoCargo = progreso.UltimoCargo
	end

	-- Moderación.
	local moderacion = typeof(origen.Moderacion) == "table" and origen.Moderacion or {}
	base.Moderacion.BloqueoHasta = numero(moderacion.BloqueoHasta, 0, 0, nil, true)
	base.Moderacion.Advertencias = {}
	for _, adv in ipairs(ultimos(moderacion.Advertencias, moderacionCfg.MaxAdvertencias or 20)) do
		if typeof(adv) == "table" then
			table.insert(base.Moderacion.Advertencias, {
				T = numero(adv.T, 0, 0, nil, true),
				Motivo = texto(adv.Motivo, "", limites.MaxMotivoCaracteres or 120),
				Autor = texto(adv.Autor, "", 32),
			})
		end
	end

	-- Meta.
	local meta = typeof(origen.Meta) == "table" and origen.Meta or {}
	base.Meta.Creado = numero(meta.Creado, 0, 0, nil, true)
	base.Meta.UltimaEntrada = numero(meta.UltimaEntrada, 0, 0, nil, true)
	base.Meta.Entradas = numero(meta.Entradas, 0, 0, nil, true)

	base.Version = ESQUEMA_VERSION
	return base
end

-- Prepara los datos leídos (o nil) para su uso: migra y sanea. Devuelve perfil, soloSesion.
function DataService:Preparar(datos)
	if datos == nil then
		local nuevo = self.PerfilPorDefecto()
		nuevo.Meta.Creado = os.time()
		return nuevo, false
	end
	if typeof(datos) ~= "table" then
		warn(PREFIJO .. " Datos guardados con tipo inesperado (" .. typeof(datos) .. "); se crea un perfil nuevo.")
		local nuevo = self.PerfilPorDefecto()
		nuevo.Meta.Creado = os.time()
		return nuevo, false
	end
	local migrado, soloSesion = self:Migrar(copiaProfunda(datos))
	return self:Sanear(migrado), soloSesion
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function DataService:Init(registro)
	self.registro = registro
	self.Perfiles = {} -- userId -> perfil (caché)
	self.Meta = {} -- userId -> { Estado, Clave, Sucio, SoloSesion, Guardando, Saliendo, UltimoGuardado }
	self.ModoMemoria = false
	self.MemoriaPerfiles = {} -- clave -> perfil saneado (persistencia dentro de la sesión de Studio)
	self.MemoriaReportes = {} -- clave -> reporte
	self.Store = nil
	self.StoreReportes = nil
	self.Activo = true
	self.PerfilCargado = Signal.new() -- (player, perfil)
	self.PerfilGuardado = Signal.new() -- (userId, ok, motivo)
	self.Estadisticas = {
		Cargas = 0, CargasNuevas = 0, CargasFallidas = 0,
		Guardados = 0, GuardadosFallidos = 0, Reportes = 0, ReportesFallidos = 0,
		UltimoError = "",
	}
	self.Conexiones = {}
	self.ClavesReporte = {} -- clave base R_<unix>_<userId> -> repeticiones en esta sesión
end

function DataService:Start()
	self.AuditLog = self.registro.Get("AuditLogService")
	self:ConectarAlmacenes()

	-- SettingsUpdate (RemoteEvent): RemoteService ya validó tabla, esquema y límite.
	local RemoteService = self.registro.Get("RemoteService")
	if RemoteService and typeof(RemoteService.Registrar) == "function" then
		RemoteService:Registrar("SettingsUpdate", function(player, datos)
			local ok, resultado = self:ActualizarAjustes(player, datos.Ajustes)
			if not ok then
				return RemoteContracts.Error(resultado)
			end
			return RemoteContracts.Ok({ Cambios = resultado })
		end)
	else
		warn(PREFIJO .. " RemoteService no disponible: SettingsUpdate no tendrá handler.")
	end

	table.insert(self.Conexiones, Players.PlayerAdded:Connect(function(player)
		task.spawn(function()
			self:Cargar(player)
		end)
	end))
	table.insert(self.Conexiones, Players.PlayerRemoving:Connect(function(player)
		task.spawn(function()
			self:AlSalir(player)
		end)
	end))
	for _, player in ipairs(Players:GetPlayers()) do
		task.spawn(function()
			self:Cargar(player)
		end)
	end

	local okBind, errBind = pcall(function()
		game:BindToClose(function()
			self:AlCerrar()
		end)
	end)
	if not okBind then
		warn(PREFIJO .. " No se pudo registrar BindToClose: " .. tostring(errBind))
	end

	task.spawn(function()
		self:BucleAutoguardado()
	end)
end

-- Obtiene los DataStores con pcall; si falla, activa el modo memoria.
function DataService:ConectarAlmacenes()
	local nombrePerfiles = CFG.NombreDataStore or "ColegioRP_Perfiles"
	local nombreReportes = CFG.NombreDataStoreReportes or "ColegioRP_Reportes"
	local ok, store = pcall(DataStoreService.GetDataStore, DataStoreService, nombrePerfiles)
	if ok and store then
		self.Store = store
	else
		self:ActivarModoMemoria("GetDataStore(" .. nombrePerfiles .. "): " .. tostring(store))
		return
	end
	local okR, storeR = pcall(DataStoreService.GetDataStore, DataStoreService, nombreReportes)
	if okR and storeR then
		self.StoreReportes = storeR
	else
		warn(PREFIJO .. " No se pudo obtener el DataStore de reportes: " .. tostring(storeR) .. ". Los reportes se guardarán en memoria.")
	end
end

-- Pasa a modo memoria (Studio sin acceso a la API o DataStore inaccesible). Nunca lanza.
function DataService:ActivarModoMemoria(motivo)
	if self.ModoMemoria then
		return
	end
	self.ModoMemoria = true
	self.Estadisticas.UltimoError = tostring(motivo)
	warn(PREFIJO .. " MODO MEMORIA activado: los perfiles no se persisten en esta sesión. Motivo: " .. tostring(motivo))
	if RunService:IsStudio() then
		warn(PREFIJO .. " En Studio: activa 'Enable Studio Access to API Services' en Game Settings > Security para probar DataStore.")
	end
	if self.AuditLog then
		self.AuditLog:Registrar("Sistema", nil, "ModoMemoria", motivo)
	end
	-- Perfiles que quedaron en "solo sesión" por fallos de lectura pasan a memoria para no bloquear a nadie.
	for userId, meta in pairs(self.Meta) do
		if meta.SoloSesion and meta.MotivoSoloSesion == "fallo_lectura" then
			meta.SoloSesion = false
			meta.Estado = "memoria"
		end
	end
end

---------------------------------------------------------------------------------------------------
-- Presupuesto y reintentos
---------------------------------------------------------------------------------------------------

-- Espera (hasta ESPERA_PRESUPUESTO_MAX s) a que haya presupuesto para el tipo de petición.
function DataService:EsperarPresupuesto(tipo)
	local esperado = 0
	while esperado < ESPERA_PRESUPUESTO_MAX do
		local ok, presupuesto = pcall(DataStoreService.GetRequestBudgetForRequestType, DataStoreService, tipo)
		if not ok or typeof(presupuesto) ~= "number" or presupuesto > 0 then
			return true
		end
		task.wait(1)
		esperado = esperado + 1
	end
	return false
end

-- Ejecuta una operación de DataStore con reintentos y backoff 1/2/4 s. Devuelve ok, resultado|error.
function DataService:ConReintentos(tipoPresupuesto, operacion, descripcion)
	local ultimoError = "desconocido"
	for intento = 1, REINTENTOS_MAX do
		if self.ModoMemoria then
			return false, "modo_memoria"
		end
		self:EsperarPresupuesto(tipoPresupuesto)
		local ok, resultado = pcall(operacion)
		if ok then
			return true, resultado
		end
		ultimoError = tostring(resultado)
		self.Estadisticas.UltimoError = ultimoError
		if esErrorDeAccesoApi(ultimoError) and RunService:IsStudio() then
			self:ActivarModoMemoria(ultimoError)
			return false, "modo_memoria"
		end
		warn(string.format("%s %s falló (intento %d/%d): %s", PREFIJO, tostring(descripcion), intento, REINTENTOS_MAX, ultimoError))
		if intento < REINTENTOS_MAX then
			task.wait(2 ^ (intento - 1))
		end
	end
	return false, ultimoError
end

---------------------------------------------------------------------------------------------------
-- Carga
---------------------------------------------------------------------------------------------------
function DataService:Clave(userId)
	return "P_" .. tostring(userId)
end

local function resolverUserId(player)
	if typeof(player) == "Instance" and player:IsA("Player") then
		return player.UserId
	elseif typeof(player) == "number" then
		return player
	end
	return nil
end

-- Carga (o devuelve de caché) el perfil del jugador. Nunca lanza; devuelve perfil o nil si el jugador se fue.
function DataService:Cargar(player)
	if typeof(player) ~= "Instance" or not player:IsA("Player") then
		return nil
	end
	local userId = player.UserId
	if self.Perfiles[userId] and self.Meta[userId] and not self.Meta[userId].Saliendo then
		return self.Perfiles[userId]
	end

	-- Si el jugador acaba de salir y su guardado sigue en curso, esperamos a que termine.
	local esperado = 0
	while self.Meta[userId] and self.Meta[userId].Saliendo and esperado < 15 do
		task.wait(0.25)
		esperado = esperado + 0.25
	end
	if self.Meta[userId] and self.Meta[userId].Estado == "cargando" then
		return self:EsperarPerfil(player, 30)
	end

	local clave = self:Clave(userId)
	local meta = { Estado = "cargando", Clave = clave, Sucio = false, SoloSesion = false, Guardando = false, Saliendo = false, UltimoGuardado = os.clock() }
	self.Meta[userId] = meta

	local datos = nil
	local origen = "datastore"
	if self.ModoMemoria or not self.Store then
		datos = self.MemoriaPerfiles[clave]
		origen = "memoria"
	else
		local ok, resultado = self:ConReintentos(Enum.DataStoreRequestType.GetAsync, function()
			return self.Store:GetAsync(clave)
		end, "GetAsync(" .. clave .. ")")
		if ok then
			datos = resultado
		elseif self.ModoMemoria then
			datos = self.MemoriaPerfiles[clave]
			origen = "memoria"
		else
			origen = "fallo"
			self.Estadisticas.CargasFallidas = self.Estadisticas.CargasFallidas + 1
			meta.SoloSesion = true
			meta.MotivoSoloSesion = "fallo_lectura"
			warn(PREFIJO .. " No se pudo cargar el perfil de " .. player.Name .. " (" .. tostring(resultado) .. "); se usa un perfil temporal sin guardado.")
			if self.AuditLog then
				self.AuditLog:Registrar("Sistema", player, "CargaFallida", resultado)
			end
		end
	end

	local perfil, soloSesionPorVersion = self:Preparar(datos)
	if soloSesionPorVersion then
		meta.SoloSesion = true
		meta.MotivoSoloSesion = "version_superior"
	end
	perfil.Meta.UltimaEntrada = os.time()
	perfil.Meta.Entradas = perfil.Meta.Entradas + 1
	if perfil.Meta.Creado == 0 then
		perfil.Meta.Creado = os.time()
	end

	if player.Parent == nil then
		-- El jugador se fue durante la carga: no hay nada que guardar.
		if self.Meta[userId] == meta then
			self.Meta[userId] = nil
		end
		return nil
	end

	self.Perfiles[userId] = perfil
	-- Ajustes que necesita la pantalla de carga de la siguiente sesión (lee atributos del Player)
	if typeof(perfil.Ajustes) == "table" then
		pcall(function()
			player:SetAttribute("IntroVista", perfil.Ajustes.IntroVista == true)
			player:SetAttribute("MovimientoReducido", perfil.Ajustes.MovimientoReducido == true)
		end)
	end
	if datos == nil then
		meta.Estado = "nuevo"
		meta.Sucio = true
		self.Estadisticas.CargasNuevas = self.Estadisticas.CargasNuevas + 1
	elseif origen == "fallo" then
		meta.Estado = "temporal"
	elseif origen == "memoria" then
		meta.Estado = "memoria"
	else
		meta.Estado = "cargado"
	end
	self.Estadisticas.Cargas = self.Estadisticas.Cargas + 1

	if origen == "fallo" then
		local RemoteService = self.registro.Get("RemoteService")
		if RemoteService and typeof(RemoteService.Enviar) == "function" then
			task.delay(5, function()
				if player.Parent then
					RemoteService:Enviar(player, "Notificacion", {
						Titulo = "Progreso temporal",
						Texto = "No se pudo cargar tu progreso guardado. Puedes jugar, pero los cambios de esta sesión no se guardarán.",
						Nivel = "aviso",
						Tipo = "aviso",
						Duracion = 8,
					})
				end
			end)
		end
	end

	self.PerfilCargado:Fire(player, perfil)
	return perfil
end

-- Perfil en caché del jugador (Player o userId) o nil si aún no está cargado.
function DataService:Obtener(player)
	local userId = resolverUserId(player)
	if not userId then
		return nil
	end
	return self.Perfiles[userId]
end

-- Marca el perfil como modificado (se guardará en el próximo autoguardado o al salir).
function DataService:Marcar(player)
	local userId = resolverUserId(player)
	local meta = userId and self.Meta[userId]
	if meta then
		meta.Sucio = true
		return true
	end
	return false
end

-- Aplica ajustes del cliente a Perfil.Ajustes: solo claves conocidas que pasan su descriptor de
-- RemoteContracts.EsquemaAjustes. Devuelve true, cambios | false, motivo.
function DataService:ActualizarAjustes(player, ajustes)
	if typeof(ajustes) ~= "table" then
		return false, "ajustes_invalidos"
	end
	local perfil = self:Obtener(player)
	if not perfil then
		return false, "sin_perfil"
	end
	if typeof(perfil.Ajustes) ~= "table" then
		perfil.Ajustes = {}
	end
	local cambios = 0
	for _, clave in ipairs(RemoteContracts.ClavesAjustes or {}) do
		local valor = ajustes[clave]
		local descriptor = camposAjustes[clave]
		if valor ~= nil and descriptor and Validate.ComprobarValor(descriptor, valor, clave) then
			if perfil.Ajustes[clave] ~= valor then
				perfil.Ajustes[clave] = valor
				cambios = cambios + 1
			end
		end
	end
	if cambios > 0 then
		self:Marcar(player)
	end
	return true, cambios
end

-- Espera a que el perfil esté cargado (hasta timeout segundos). Devuelve perfil o nil.
function DataService:EsperarPerfil(player, timeout)
	local userId = resolverUserId(player)
	if not userId then
		return nil
	end
	timeout = tonumber(timeout) or 15
	local inicio = os.clock()
	while os.clock() - inicio < timeout do
		local perfil = self.Perfiles[userId]
		local meta = self.Meta[userId]
		if perfil and meta and not meta.Saliendo then
			return perfil
		end
		if typeof(player) == "Instance" and player.Parent == nil then
			return nil
		end
		task.wait(0.1)
	end
	return self.Perfiles[userId]
end

-- Estado del perfil: "cargando" | "cargado" | "nuevo" | "memoria" | "temporal" | nil.
function DataService:Estado(player)
	local userId = resolverUserId(player)
	local meta = userId and self.Meta[userId]
	if meta then
		return meta.Estado
	end
	return nil
end

-- ¿El perfil se persistirá (no es solo de sesión)?
function DataService:SePersiste(player)
	local userId = resolverUserId(player)
	local meta = userId and self.Meta[userId]
	return meta ~= nil and not meta.SoloSesion
end

---------------------------------------------------------------------------------------------------
-- Guardado
---------------------------------------------------------------------------------------------------

-- Guarda el perfil del jugador (Player o userId). Devuelve ok, motivo.
function DataService:Guardar(player, motivo)
	local userId = resolverUserId(player)
	if not userId then
		return false, "jugador_invalido"
	end
	local perfil = self.Perfiles[userId]
	local meta = self.Meta[userId]
	if not perfil or not meta then
		return false, "sin_perfil"
	end
	if meta.SoloSesion then
		return false, "solo_sesion"
	end

	-- Evitar guardados concurrentes del mismo perfil.
	local esperado = 0
	while meta.Guardando and esperado < 10 do
		task.wait(0.25)
		esperado = esperado + 0.25
	end
	if meta.Guardando then
		return false, "en_curso"
	end
	meta.Guardando = true
	-- Se limpia antes de guardar: un cambio hecho mientras UpdateAsync cede vuelve a marcarlo y no se pierde.
	local estabaSucio = meta.Sucio
	meta.Sucio = false

	local saneado = self:Sanear(perfil)
	saneado.Meta.UltimaSalida = os.time()
	local ok, err

	if self.ModoMemoria or not self.Store then
		self.MemoriaPerfiles[meta.Clave] = saneado
		ok = true
	else
		ok, err = self:ConReintentos(Enum.DataStoreRequestType.UpdateAsync, function()
			return self.Store:UpdateAsync(meta.Clave, function()
				return saneado
			end)
		end, "UpdateAsync(" .. meta.Clave .. ")")
		if not ok and self.ModoMemoria then
			self.MemoriaPerfiles[meta.Clave] = saneado
			ok = true
		end
	end

	meta.Guardando = false
	if ok then
		meta.UltimoGuardado = os.clock()
		self.Estadisticas.Guardados = self.Estadisticas.Guardados + 1
		self.PerfilGuardado:Fire(userId, true, motivo)
		return true
	end
	if estabaSucio then
		meta.Sucio = true
	end
	self.Estadisticas.GuardadosFallidos = self.Estadisticas.GuardadosFallidos + 1
	if self.AuditLog then
		self.AuditLog:Registrar("Sistema", userId, "GuardadoFallido", tostring(err))
	end
	self.PerfilGuardado:Fire(userId, false, tostring(err))
	return false, tostring(err)
end

-- Guarda todos los perfiles sucios (o todos si forzar = true), espaciando las peticiones.
function DataService:GuardarTodos(forzar, motivo)
	local guardados = 0
	for userId, meta in pairs(self.Meta) do
		if self.Perfiles[userId] and not meta.SoloSesion and (forzar or meta.Sucio) then
			local ok = self:Guardar(userId, motivo or "autoguardado")
			if ok then
				guardados = guardados + 1
			end
			if not self.ModoMemoria then
				task.wait(0.5)
			end
		end
	end
	return guardados
end

function DataService:BucleAutoguardado()
	while self.Activo do
		task.wait(AUTOGUARDADO_SEG)
		if not self.Activo then
			break
		end
		local ok, err = pcall(function()
			self:GuardarTodos(false, "autoguardado")
		end)
		if not ok then
			warn(PREFIJO .. " Error en el autoguardado: " .. tostring(err))
		end
	end
end

function DataService:AlSalir(player)
	if typeof(player) ~= "Instance" then
		return
	end
	local userId = player.UserId
	local meta = self.Meta[userId]
	if not meta then
		return
	end
	meta.Saliendo = true
	if self.Perfiles[userId] then
		local ok, err = pcall(function()
			self:Guardar(userId, "salida")
		end)
		if not ok then
			warn(PREFIJO .. " Error al guardar al salir " .. player.Name .. ": " .. tostring(err))
		end
	end
	-- Solo se limpia si no se ha vuelto a cargar mientras guardábamos (reconexión rápida).
	if self.Meta[userId] == meta then
		self.Meta[userId] = nil
		self.Perfiles[userId] = nil
	end
end

-- ¿Queda algún guardado en curso (salida de jugador o guardado lanzado)?
function DataService:HayGuardadosEnCurso()
	for _, meta in pairs(self.Meta) do
		if meta.Saliendo or meta.Guardando then
			return true
		end
	end
	return false
end

-- BindToClose: guarda todos los perfiles en paralelo y espera (máx. TIEMPO_CIERRE_MAX s), incluidos los
-- guardados de PlayerRemoving que ya estaban en curso.
function DataService:AlCerrar()
	self.Activo = false
	local pendientes = 0
	for userId, meta in pairs(self.Meta) do
		if self.Perfiles[userId] and not meta.SoloSesion and not meta.Saliendo then
			pendientes = pendientes + 1
			task.spawn(function()
				pcall(function()
					self:Guardar(userId, "cierre")
				end)
				pendientes = pendientes - 1
			end)
		end
	end
	if self.ModoMemoria then
		return
	end
	local inicio = os.clock()
	while (pendientes > 0 or self:HayGuardadosEnCurso()) and os.clock() - inicio < TIEMPO_CIERRE_MAX do
		task.wait(0.2)
	end
	if pendientes > 0 or self:HayGuardadosEnCurso() then
		warn(PREFIJO .. " Cierre con guardados sin confirmar (" .. pendientes .. " de cierre en curso).")
	end
end

---------------------------------------------------------------------------------------------------
-- Reportes de soporte
---------------------------------------------------------------------------------------------------

-- Guarda un reporte { UserId, Categoria, Ubicacion, Descripcion, ... } con clave R_<unix>_<userId>.
-- Devuelve ok, clave|error.
function DataService:GuardarReporte(reporte)
	if typeof(reporte) ~= "table" then
		return false, "reporte_invalido"
	end
	local userId = numero(reporte.UserId, 0, 0, nil, true)
	local clave = string.format("R_%d_%d", os.time(), userId)
	-- Dos reportes del mismo jugador en el mismo segundo no se sobrescriben: R_<unix>_<userId>_<n>.
	local repeticiones = self.ClavesReporte[clave]
	self.ClavesReporte[clave] = (repeticiones or 0) + 1
	if repeticiones then
		clave = clave .. "_" .. repeticiones
	end
	local copia = copiaProfunda(reporte)
	copia.UserId = userId
	copia.Guardado = os.time()
	copia.Version = Config.Version

	if self.ModoMemoria or not self.StoreReportes then
		local sufijo = 0
		local claveFinal = clave
		while self.MemoriaReportes[claveFinal] do
			sufijo = sufijo + 1
			claveFinal = clave .. "_" .. sufijo
		end
		self.MemoriaReportes[claveFinal] = copia
		self.Estadisticas.Reportes = self.Estadisticas.Reportes + 1
		return true, claveFinal
	end

	local ok, err = self:ConReintentos(Enum.DataStoreRequestType.SetIncrementAsync, function()
		return self.StoreReportes:SetAsync(clave, copia)
	end, "SetAsync(" .. clave .. ")")
	if ok then
		self.Estadisticas.Reportes = self.Estadisticas.Reportes + 1
		return true, clave
	end
	self.Estadisticas.ReportesFallidos = self.Estadisticas.ReportesFallidos + 1
	-- Como respaldo se conserva en memoria para que moderación pueda verlo en esta sesión.
	self.MemoriaReportes[clave] = copia
	return false, tostring(err)
end

-- Reportes guardados en memoria durante esta sesión (lista, el más reciente al final).
function DataService:ReportesEnMemoria()
	local lista = {}
	for clave, reporte in pairs(self.MemoriaReportes) do
		local copia = copiaProfunda(reporte)
		copia.Clave = clave
		table.insert(lista, copia)
	end
	table.sort(lista, function(a, b)
		return (a.Guardado or 0) < (b.Guardado or 0)
	end)
	return lista
end

---------------------------------------------------------------------------------------------------
-- Métricas
---------------------------------------------------------------------------------------------------
-- Resumen numérico para MetricsService (el campo self.Estadisticas guarda los contadores internos).
function DataService:ObtenerEstadisticas()
	local enCache = 0
	local sucios = 0
	for userId, meta in pairs(self.Meta) do
		if self.Perfiles[userId] then
			enCache = enCache + 1
			if meta.Sucio then
				sucios = sucios + 1
			end
		end
	end
	return {
		ModoMemoria = self.ModoMemoria,
		PerfilesEnCache = enCache,
		PerfilesSucios = sucios,
		Cargas = self.Estadisticas.Cargas,
		CargasNuevas = self.Estadisticas.CargasNuevas,
		CargasFallidas = self.Estadisticas.CargasFallidas,
		Guardados = self.Estadisticas.Guardados,
		GuardadosFallidos = self.Estadisticas.GuardadosFallidos,
		Reportes = self.Estadisticas.Reportes,
		ReportesFallidos = self.Estadisticas.ReportesFallidos,
		UltimoError = self.Estadisticas.UltimoError,
	}
end

return DataService
]=] }
FUENTES["ServerScriptService/ColegioRP/Services/DoorService"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ServerScriptService.ColegioRP.Services.DoorService
	Tipo: ModuleScript
	Puertas del colegio (docs/ARQUITECTURA.md §6): resuelve cada puerta de MapaLogico.Puertas (MapService:Puerta o
	ruta propia con desempate por Centro), detecta la hoja y sus piezas pegadas (pomos, paneles), guarda los valores
	originales (Transparency, CanCollide, CFrame) y añade ProximityPrompts (RPTipo = "Puerta") sobre un Attachment
	propio en la hoja. Estados: Abierta / Cerrada / Bloqueada / Privada (atributo Estado en la hoja).
	Modos: "estado" (abrir = Transparency 0.7 + CanCollide false en la hoja, cerrar = restaurar), "privacidad"
	(baños: quien está dentro bloquea 60 s solo contra la entrada) y "giro" (tween de 90° sobre la arista de la
	bisagra; solo con Config.Puertas.PermitirGiro y con caída a "estado" si falla).
	Reglas: nunca encierra (desde dentro siempre se abre: el bloqueo solo impide entrar desde fuera, calculado con el
	plano de la hoja), cooldown por puerta, autocierre (no si el personal la fijó abierta), bloqueo según
	CargosBloqueo o permiso puertas.aulas / puertas.oficinas. Remoto DoorAction (distancia <= 14) y eventos
	EventoCliente "Puerta" { Sub = "Estado" | "Mensaje", PuertaId, Estado, ... } a la zona de la puerta.
	Estado inicial: todas las puertas "Abierta" y transitables con su aspecto original (como en el mapa); el
	Porton_Blanco conserva su Transparency pero sus hojas quedan con CanCollide = false para no encerrar a nadie.
]]

local Players = game:GetService("Players")
local TweenService = game:GetService("TweenService")
local CollectionService = game:GetService("CollectionService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local RP = ReplicatedStorage:WaitForChild("ColegioRP")
local Shared = RP:WaitForChild("Shared")
local Config = require(Shared:WaitForChild("Config"))
local MapaLogico = require(Shared:WaitForChild("MapaLogico"))
local Util = Shared:WaitForChild("Util")
local Zones = require(Util:WaitForChild("Zones"))
local Signal = require(Util:WaitForChild("Signal"))

local DoorService = {}
DoorService.Nombre = "DoorService"

local PREFIJO = "[ColegioRP][DoorService]"

---------------------------------------------------------------------------------------------------
-- Parámetros (Config.Puertas y ajustes finos del servicio)
---------------------------------------------------------------------------------------------------
local CFG = Config.Puertas or {}
local COOLDOWN_SEG = tonumber(CFG.CooldownSeg) or 1
local AUTOCIERRE_SEG = tonumber(CFG.AutoCierreSeg) or 8
local PERMITIR_GIRO = CFG.PermitirGiro == true
local PRIVACIDAD_SEG = tonumber(CFG.PrivacidadSeg) or 60
local DISTANCIA_MAX = (Config.Distancias and tonumber(Config.Distancias.Puerta)) or 14
local SONIDO_ID = tonumber(Config.Sonidos and Config.Sonidos.Puerta) or 0
local TAG_HOJA = (Config.Tags and Config.Tags.Puerta) or "ColegioRP_Puerta"

DoorService.TagPrompt = "ColegioRP_PromptPuerta" -- Prompt principal (Abrir/Cerrar) de cada puerta.
DoorService.TagPromptBloqueo = "ColegioRP_PromptBloqueo" -- Prompt de bloqueo para el personal autorizado.
DoorService.TagPromptPrivacidad = "ColegioRP_PromptPrivacidad" -- Prompt de privacidad (solo baños).
DoorService.ToleranciaDistancia = 2 -- Studs añadidos a la distancia máxima (latencia y tamaño del personaje).
DoorService.TransparenciaAbierta = 0.7 -- Transparencia de la hoja abierta en modo "estado".
DoorService.DistanciaPrompt = 8 -- MaxActivationDistance de los prompts.
DoorService.HoldBloqueo = 0.5 -- Pulsación sostenida del prompt de bloqueo/privacidad (evita toques accidentales).
DoorService.DistanciaAvisoVecinos = 20 -- Jugadores fuera de la zona a esta distancia también reciben el evento.
DoorService.CooldownPrivacidadJugador = 20 -- Segundos entre activaciones de privacidad de un mismo jugador.
DoorService.GraciaVaciaSeg = 3 -- Si nadie queda dentro del baño durante este tiempo, la privacidad se libera.
DoorService.UmbralGrosor = 2.5 -- Medio fondo (studs) del umbral: alguien aquí impide el autocierre.
DoorService.ReintentoAutocierreSeg = 2 -- Reintento del autocierre si hay alguien en el umbral.
DoorService.DistanciaReferenciaBano = 9 -- Distancia máxima puerta-inodoro para tomarlo como "dentro" del cubículo.
DoorService.DuracionGiro = 0.5 -- Duración del tween de giro.
DoorService.AnguloGiro = 90 -- Grados de apertura en modo "giro".
DoorService.MargenGrosor = 0.6 -- Margen (studs) en el grosor para incluir pomos y paneles pegados a la hoja.
DoorService.MargenPlano = 0.05 -- Margen en el plano de la hoja para esas piezas.
DoorService.MaxDistanciaCentro = 10 -- Si la instancia resuelta está más lejos de Centro, se buscan homónimas.
DoorService.VisitasMaxRuta = 60000 -- Límite de nodos visitados al resolver rutas con nombres repetidos.
DoorService.IntervaloPromptSeg = 0.25 -- Activaciones de prompt más rápidas que esto (por jugador) se ignoran.
DoorService.IntervaloAuditoriaSeg = 10 -- Un mismo rechazo (jugador, puerta, motivo) se audita como mucho una vez en este tiempo.

local ACCIONES = { Abrir = true, Cerrar = true, Bloquear = true, Desbloquear = true, Privacidad = true }
local TIPOS_AULA = { aula = true, aula_especial = true, aula_pc = true }
-- Piezas de marco que nunca forman parte de la hoja (se buscan en minúsculas dentro del nombre).
local NOMBRES_MARCO = { "marco", "jamba", "dintel", "umbral", "bisagra", "poste", "montante", "pared", "muro", "columna" }
-- Motivos de rechazo que se auditan (los de cooldown, sin cambio u ocupado no aportan información).
local MOTIVOS_AUDITADOS = {
	puerta_inexistente = true, accion_invalida = true, distancia = true, sin_permiso_bloqueo = true,
	bloqueada = true, jugador_invalido = true, fuera = true,
}
-- Motivos que además cuentan como rechazo en MetricsService (peticiones manipuladas o sin permiso).
local MOTIVOS_METRICAS = { puerta_inexistente = true, accion_invalida = true, distancia = true, sin_permiso_bloqueo = true }

---------------------------------------------------------------------------------------------------
-- Utilidades
---------------------------------------------------------------------------------------------------
local function esJugador(valor)
	return typeof(valor) == "Instance" and valor:IsA("Player")
end

local function posicionJugador(player)
	local personaje = player and player.Character
	if not personaje then
		return nil
	end
	local raiz = personaje:FindFirstChild("HumanoidRootPart")
	if raiz and raiz:IsA("BasePart") then
		return raiz.Position
	end
	return nil
end

local function plano(v)
	return Vector3.new(v.X, 0, v.Z)
end

local function unitarioPlano(v)
	local h = plano(v)
	if h.Magnitude < 0.01 then
		return nil
	end
	return h.Unit
end

local function volumen(parte)
	local s = parte.Size
	return s.X * s.Y * s.Z
end

local function esMarco(nombre)
	local minus = string.lower(tostring(nombre))
	for _, clave in ipairs(NOMBRES_MARCO) do
		if string.find(minus, clave, 1, true) then
			return true
		end
	end
	return false
end

local function contieneHoja(nombre)
	return string.find(string.lower(tostring(nombre)), "hoja", 1, true) ~= nil
end

local function esAsiento(parte)
	return parte:IsA("Seat") or parte:IsA("VehicleSeat")
end

-- Extensión total (studs) de la caja de una BasePart a lo largo de una dirección unitaria.
local function extension(cf, s, direccion)
	return math.abs(cf.RightVector:Dot(direccion)) * s.X
		+ math.abs(cf.UpVector:Dot(direccion)) * s.Y
		+ math.abs(cf.LookVector:Dot(direccion)) * s.Z
end

-- Ejes locales de una parte clasificados: índice del más vertical, del más fino y del más ancho (de los otros dos).
local function clasificarEjes(parte)
	local cf, s = parte.CFrame, parte.Size
	local ejes = { { cf.RightVector, s.X }, { cf.UpVector, s.Y }, { cf.LookVector, s.Z } }
	local iVertical, mejor = 2, -1
	for i, eje in ipairs(ejes) do
		local alineacion = math.abs(eje[1].Y)
		if alineacion > mejor then
			mejor = alineacion
			iVertical = i
		end
	end
	local iFino, iAncho = nil, nil
	for i, eje in ipairs(ejes) do
		if i ~= iVertical then
			if iFino == nil then
				iFino = i
			elseif eje[2] < ejes[iFino][2] then
				iAncho = iFino
				iFino = i
			else
				iAncho = i
			end
		end
	end
	return ejes, iVertical, iFino, iAncho
end

-- Posición representativa de una instancia (BasePart, Model o contenedor con BaseParts).
local function posicionInstancia(instancia)
	if instancia:IsA("BasePart") then
		return instancia.Position
	end
	if instancia:IsA("Model") then
		local ok, cf = pcall(function()
			local caja = instancia:GetBoundingBox()
			return caja
		end)
		if ok and typeof(cf) == "CFrame" then
			return cf.Position
		end
	end
	local suma, n = Vector3.new(0, 0, 0), 0
	local okD, descendientes = pcall(instancia.GetDescendants, instancia)
	if okD then
		for _, d in ipairs(descendientes) do
			if d:IsA("BasePart") then
				suma = suma + d.Position
				n = n + 1
			end
		end
	end
	if n > 0 then
		return suma / n
	end
	return nil
end

-- Lista "a,b,c" -> set y texto.
local function conjuntoCargos(lista)
	local set, textos = {}, {}
	if typeof(lista) == "table" then
		for _, cargo in ipairs(lista) do
			if typeof(cargo) == "string" and cargo ~= "" then
				set[cargo] = true
				table.insert(textos, cargo)
			end
		end
	end
	return set, table.concat(textos, ",")
end

local function ahoraServidor()
	local ok, t = pcall(function()
		return workspace:GetServerTimeNow()
	end)
	if ok and typeof(t) == "number" then
		return t
	end
	return os.time()
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function DoorService:Init(registro)
	self.registro = registro
	self.Puertas = {} -- puertaId -> registro de puerta (ver ConstruirPuerta)
	self.Orden = {} -- ids resueltos en el orden de MapaLogico.OrdenPuertas
	self.NoResueltas = {} -- ids sin instancia en el mapa
	self.Advertencias = {}
	self.Conexiones = {}
	self.UltimaPrivacidad = {} -- userId -> os.clock() de su última activación de privacidad
	self.UltimoPrompt = {} -- userId -> os.clock() de su última activación de prompt de puerta
	self.UltimaAuditoria = {} -- userId -> { ["puerta|motivo"] = os.clock() }
	self.Activo = false
	self.Listo = false
	self.EstadoCambiado = Signal.new() -- (puertaId, estado, datosEstado)
end

function DoorService:Start()
	self.Activo = true
	local okConstruir, errConstruir = pcall(function()
		self:ConstruirTodas()
	end)
	if not okConstruir then
		warn(PREFIJO .. " Error al preparar las puertas: " .. tostring(errConstruir))
	end
	self.Listo = true

	-- Remoto DoorAction (RemoteService ya validó esquema, límite y permiso fijo; aquí va la lógica).
	local RemoteService = self:Servicio("RemoteService")
	if RemoteService and typeof(RemoteService.Registrar) == "function" then
		RemoteService:Registrar("DoorAction", function(player, datos)
			return self:ManejarDoorAction(player, datos)
		end, {
			Posicion = function(datos)
				local puerta = typeof(datos) == "table" and typeof(datos.PuertaId) == "string" and self.Puertas[datos.PuertaId] or nil
				if puerta then
					return puerta.Punto
				end
				return nil
			end,
		})
		-- Estados de las puertas en el StateSnapshot (el cliente se resincroniza tras reaparecer).
		if typeof(RemoteService.AportarSnapshot) == "function" then
			pcall(RemoteService.AportarSnapshot, RemoteService, "Puertas", function()
				return self:Snapshot()
			end)
		end
	else
		warn(PREFIJO .. " RemoteService no disponible: DoorAction no tendrá handler (los prompts siguen funcionando).")
	end

	table.insert(self.Conexiones, Players.PlayerRemoving:Connect(function(player)
		self.UltimaPrivacidad[player.UserId] = nil
		self.UltimoPrompt[player.UserId] = nil
		self.UltimaAuditoria[player.UserId] = nil
		-- Si su privacidad seguía activa, se libera enseguida.
		for _, id in ipairs(self.Orden) do
			local puerta = self.Puertas[id]
			if puerta and puerta.Privacidad and puerta.Privacidad.UserId == player.UserId then
				self:LiberarPrivacidad(puerta, "salida")
			end
		end
	end))

	-- Revisión periódica de la privacidad de los baños (caducidad y baño vacío). 1 vez por segundo.
	task.spawn(function()
		while self.Activo do
			task.wait(1)
			local ok, err = pcall(self.RevisarPrivacidad, self)
			if not ok then
				warn(PREFIJO .. " Error revisando la privacidad: " .. tostring(err))
			end
		end
	end)

	local AuditLog = self:Servicio("AuditLogService")
	if AuditLog then
		pcall(AuditLog.Registrar, AuditLog, "Sistema", nil, "Puertas", string.format(
			"%d/%d puertas listas (%d no resueltas, giro %s)", #self.Orden, #self.Orden + #self.NoResueltas,
			#self.NoResueltas, PERMITIR_GIRO and "permitido" or "desactivado"))
	end
	for _, aviso in ipairs(self.Advertencias) do
		warn(PREFIJO .. " " .. aviso)
	end
end

-- Servicio por nombre a través del registro (nil si no existe).
function DoorService:Servicio(nombre)
	local registro = self.registro
	if registro and typeof(registro.Get) == "function" then
		local ok, servicio = pcall(registro.Get, nombre)
		if ok then
			return servicio
		end
	end
	return nil
end

function DoorService:Advertir(texto)
	table.insert(self.Advertencias, tostring(texto))
end

---------------------------------------------------------------------------------------------------
-- Resolución de instancias
---------------------------------------------------------------------------------------------------
local function segmentosDe(ruta)
	local segmentos = {}
	if typeof(ruta) ~= "string" then
		return segmentos
	end
	for parte in string.gmatch(ruta, "[^/]+") do
		table.insert(segmentos, parte)
	end
	return segmentos
end

local function raizDe(primero)
	if primero == "Workspace" or primero == "workspace" then
		return workspace
	end
	if primero == "game" then
		return game
	end
	local ok, servicio = pcall(game.FindFirstChild, game, primero)
	if ok then
		return servicio
	end
	return nil
end

-- Recorre todos los caminos que cumplen la ruta (hay hermanos con el mismo nombre, p. ej. varios "Model").
local function candidatosRuta(actual, segmentos, i, salida, contador, limite)
	if i > #segmentos then
		table.insert(salida, actual)
		return
	end
	local okHijos, hijos = pcall(actual.GetChildren, actual)
	if not okHijos then
		return
	end
	for _, hijo in ipairs(hijos) do
		contador.n = contador.n + 1
		if contador.n > limite then
			return
		end
		if hijo.Name == segmentos[i] then
			candidatosRuta(hijo, segmentos, i + 1, salida, contador, limite)
		end
	end
end

-- Instancia de la puerta: la de MapService si está cerca de Centro; si no, la homónima más cercana a Centro
-- (en el mapa hay nombres repetidos, p. ej. dos "Workspace/Puerta_Infantil").
function DoorService:ResolverInstancia(cfg)
	local deMapa = nil
	local MapService = self:Servicio("MapService")
	if MapService and typeof(MapService.Puerta) == "function" then
		local ok, info = pcall(MapService.Puerta, MapService, cfg.Id)
		if ok and typeof(info) == "table" and typeof(info.Instancia) == "Instance" then
			deMapa = info.Instancia
		end
	end
	local centro = cfg.Centro
	if deMapa then
		if typeof(centro) ~= "Vector3" then
			return deMapa
		end
		local pos = posicionInstancia(deMapa)
		if pos and (pos - centro).Magnitude <= self.MaxDistanciaCentro then
			return deMapa
		end
	end

	local segmentos = segmentosDe(cfg.Ruta)
	if #segmentos == 0 then
		return deMapa
	end
	local raiz = raizDe(segmentos[1])
	if not raiz then
		return deMapa
	end
	local resto = {}
	for i = 2, #segmentos do
		table.insert(resto, segmentos[i])
	end
	local candidatos = {}
	if #resto == 0 then
		table.insert(candidatos, raiz)
	else
		candidatosRuta(raiz, resto, 1, candidatos, { n = 0 }, self.VisitasMaxRuta)
	end
	if #candidatos == 0 then
		return deMapa
	end
	if typeof(centro) ~= "Vector3" then
		return candidatos[1]
	end
	local mejor, mejorDist = nil, math.huge
	for _, candidato in ipairs(candidatos) do
		local pos = posicionInstancia(candidato)
		if pos then
			local d = (pos - centro).Magnitude
			if d < mejorDist then
				mejor, mejorDist = candidato, d
			end
		end
	end
	if mejor and deMapa and mejor ~= deMapa then
		self:Advertir("Puerta " .. tostring(cfg.Id) .. ": la ruta " .. tostring(cfg.Ruta) .. " tiene homónimos; se usa la instancia a "
			.. string.format("%.1f", mejorDist) .. " studs de Centro.")
	end
	return mejor or deMapa
end

-- Raíces de la hoja (BasePart o Model), lista de BaseParts de la hoja y parte principal.
-- Orden: Hoja de MapaLogico > contenedores con "hoja" en el nombre (portón) > BasePart con "hoja" > mayor volumen
-- que no sea marco > mayor volumen. Si la puerta es un Model, se añaden las piezas pegadas a la hoja principal.
function DoorService:ResolverHojas(instancia, cfg)
	local raices = {}
	if typeof(cfg.Hoja) == "string" and cfg.Hoja ~= "" and not instancia:IsA("BasePart") then
		local hoja = instancia:FindFirstChild(cfg.Hoja) or instancia:FindFirstChild(cfg.Hoja, true)
		if hoja and (hoja:IsA("BasePart") or hoja:IsA("Model") or hoja:IsA("Folder")) then
			table.insert(raices, hoja)
		else
			self:Advertir("Puerta " .. tostring(cfg.Id) .. ": no se encontró la hoja '" .. cfg.Hoja .. "'; se detecta automáticamente.")
		end
	end

	local descendientes = {}
	if not instancia:IsA("BasePart") or #raices == 0 then
		local okD, lista = pcall(instancia.GetDescendants, instancia)
		if okD then
			descendientes = lista
		end
	end

	if #raices == 0 then
		if instancia:IsA("BasePart") then
			table.insert(raices, instancia)
		else
			-- Contenedores "Hoja_Izquierda" / "Hoja_Derecha" (portón de dos hojas).
			local contenedores = {}
			for _, d in ipairs(descendientes) do
				if (d:IsA("Model") or d:IsA("Folder")) and contieneHoja(d.Name) then
					table.insert(contenedores, d)
				end
			end
			for _, c in ipairs(contenedores) do
				local anidado = false
				for _, otro in ipairs(contenedores) do
					if otro ~= c and c:IsDescendantOf(otro) then
						anidado = true
						break
					end
				end
				if not anidado and c:FindFirstChildWhichIsA("BasePart", true) then
					table.insert(raices, c)
				end
			end
			if #raices == 0 then
				local conNombre, volNombre = nil, -1
				local sinMarco, volSinMarco = nil, -1
				local cualquiera, volCualquiera = nil, -1
				for _, d in ipairs(descendientes) do
					if d:IsA("BasePart") and not esAsiento(d) then
						local v = volumen(d)
						if contieneHoja(d.Name) and v > volNombre then
							conNombre, volNombre = d, v
						end
						if not esMarco(d.Name) and v > volSinMarco then
							sinMarco, volSinMarco = d, v
						end
						if v > volCualquiera then
							cualquiera, volCualquiera = d, v
						end
					end
				end
				local elegida = conNombre or sinMarco or cualquiera
				if elegida then
					table.insert(raices, elegida)
				end
			end
		end
	end

	local partes, vistos = {}, {}
	local function agregar(parte)
		if not vistos[parte] and not esAsiento(parte) then
			vistos[parte] = true
			table.insert(partes, parte)
		end
	end
	for _, raiz in ipairs(raices) do
		if raiz:IsA("BasePart") then
			agregar(raiz)
		end
		local okR, lista = pcall(raiz.GetDescendants, raiz)
		if okR then
			for _, d in ipairs(lista) do
				if d:IsA("BasePart") then
					agregar(d)
				end
			end
		end
	end

	-- Principal: la raíz si es una BasePart; si no, la BasePart de mayor volumen de las hojas.
	local principal = nil
	if raices[1] and raices[1]:IsA("BasePart") then
		principal = raices[1]
	else
		local mejorVol = -1
		for _, parte in ipairs(partes) do
			local v = volumen(parte)
			if v > mejorVol then
				principal, mejorVol = parte, v
			end
		end
	end

	-- Piezas pegadas a la hoja principal (pomos, paneles en relieve, cerraduras) dentro del mismo modelo.
	if principal and #raices == 1 and raices[1] == principal and not instancia:IsA("BasePart") then
		local _, _, iFino = clasificarEjes(principal)
		local cf, s = principal.CFrame, principal.Size
		local tam = { s.X, s.Y, s.Z }
		local margenes = { self.MargenPlano, self.MargenPlano, self.MargenPlano }
		margenes[iFino] = self.MargenGrosor
		local volPrincipal = volumen(principal)
		for _, d in ipairs(descendientes) do
			if d:IsA("BasePart") and not vistos[d] and not esAsiento(d) and not esMarco(d.Name) and volumen(d) <= volPrincipal then
				local rel = cf:PointToObjectSpace(d.Position)
				local r = { rel.X, rel.Y, rel.Z }
				local dentro = true
				for i = 1, 3 do
					if math.abs(r[i]) > tam[i] / 2 + margenes[i] then
						dentro = false
					end
				end
				if dentro then
					agregar(d)
				end
			end
		end
	end
	return raices, partes, principal
end

---------------------------------------------------------------------------------------------------
-- Construcción de cada puerta
---------------------------------------------------------------------------------------------------
function DoorService:ConstruirTodas()
	local ids = MapaLogico.OrdenPuertas
	if typeof(ids) ~= "table" or #ids == 0 then
		ids = {}
		for id in pairs(MapaLogico.Puertas or {}) do
			table.insert(ids, id)
		end
		table.sort(ids)
	end
	for _, id in ipairs(ids) do
		local cfg = MapaLogico.Puertas and MapaLogico.Puertas[id]
		if typeof(cfg) == "table" then
			local ok, resultado = pcall(self.ConstruirPuerta, self, id, cfg)
			if ok and resultado then
				self.Puertas[id] = resultado
				table.insert(self.Orden, id)
			else
				table.insert(self.NoResueltas, id)
				if not ok then
					self:Advertir("Puerta " .. id .. " con error: " .. tostring(resultado))
				end
			end
		end
	end
end

-- Nombre visible en el prompt.
local function nombreVisible(cfg, zona)
	if cfg.Modo == "privacidad" then
		return "Baño"
	end
	if string.find(string.lower(tostring(cfg.Id)), "porton", 1, true) then
		return "Portón principal"
	end
	if zona and typeof(zona.Nombre) == "string" and (utf8.len(zona.Nombre) or #zona.Nombre) <= 24 then
		return "Puerta · " .. zona.Nombre
	end
	return "Puerta " .. tostring(cfg.Zona or cfg.Id)
end

local function nuevoPrompt(padre, nombre, props, atributos)
	local prompt = Instance.new("ProximityPrompt")
	prompt.Name = nombre
	prompt.ActionText = props.ActionText or "Usar"
	prompt.ObjectText = props.ObjectText or ""
	prompt.HoldDuration = props.HoldDuration or 0
	prompt.MaxActivationDistance = props.MaxActivationDistance or 8
	prompt.RequiresLineOfSight = false
	prompt.ClickablePrompt = true
	if props.KeyboardKeyCode then
		pcall(function()
			prompt.KeyboardKeyCode = props.KeyboardKeyCode
		end)
	end
	if props.GamepadKeyCode then
		pcall(function()
			prompt.GamepadKeyCode = props.GamepadKeyCode
		end)
	end
	if props.UIOffset then
		pcall(function()
			prompt.UIOffset = props.UIOffset
		end)
	end
	for clave, valor in pairs(atributos or {}) do
		pcall(prompt.SetAttribute, prompt, clave, valor)
	end
	prompt.Parent = padre
	return prompt
end

function DoorService:ConstruirPuerta(id, cfg)
	local instancia = self:ResolverInstancia(cfg)
	if not instancia then
		self:Advertir("Puerta " .. id .. " no encontrada en el mapa: " .. tostring(cfg.Ruta))
		return nil
	end
	local raices, partes, principal = self:ResolverHojas(instancia, cfg)
	if not principal or #partes == 0 then
		self:Advertir("Puerta " .. id .. ": no se encontró ninguna pieza que sirva de hoja en " .. tostring(cfg.Ruta))
		return nil
	end
	local zona = Zones.Zona(cfg.Zona)
	if not zona then
		self:Advertir("Puerta " .. id .. ": la zona '" .. tostring(cfg.Zona) .. "' no existe en MapaLogico (dentro/fuera por la normal).")
	end

	-- Valores originales de cada pieza de la hoja.
	local registros = {}
	local principales = {}
	principales[principal] = true
	for _, parte in ipairs(partes) do
		local okLeer, rec = pcall(function()
			return {
				Parte = parte,
				Transparency = parte.Transparency,
				CanCollide = parte.CanCollide,
				CFrame = parte.CFrame,
				Anchored = parte.Anchored,
				Principal = principales[parte] == true,
			}
		end)
		if okLeer and rec then
			table.insert(registros, rec)
		end
	end

	-- Geometría: centro (caja alineada a los ejes de todas las piezas), normal y eje de anchura de la hoja.
	local minV, maxV = nil, nil
	for _, rec in ipairs(registros) do
		local cf, s = rec.CFrame, rec.Parte.Size
		local ex = extension(cf, s, Vector3.new(1, 0, 0)) / 2
		local ey = extension(cf, s, Vector3.new(0, 1, 0)) / 2
		local ez = extension(cf, s, Vector3.new(0, 0, 1)) / 2
		local p = cf.Position
		local a = Vector3.new(p.X - ex, p.Y - ey, p.Z - ez)
		local b = Vector3.new(p.X + ex, p.Y + ey, p.Z + ez)
		if minV == nil then
			minV, maxV = a, b
		else
			minV = Vector3.new(math.min(minV.X, a.X), math.min(minV.Y, a.Y), math.min(minV.Z, a.Z))
			maxV = Vector3.new(math.max(maxV.X, b.X), math.max(maxV.Y, b.Y), math.max(maxV.Z, b.Z))
		end
	end
	local punto = (minV + maxV) / 2
	local ejes, _, iFino, iAncho = clasificarEjes(principal)
	local normal = unitarioPlano(ejes[iFino][1])
	local ejeAncho = unitarioPlano(ejes[iAncho][1])
	if not normal and zona then
		normal = unitarioPlano(zona.Centro - punto)
	end
	if not normal then
		normal = Vector3.new(0, 0, 1)
	end
	if not ejeAncho then
		ejeAncho = Vector3.new(normal.Z, 0, -normal.X)
	end
	local minW, maxW = math.huge, -math.huge
	for _, rec in ipairs(registros) do
		local centro = rec.CFrame.Position:Dot(ejeAncho)
		local medio = extension(rec.CFrame, rec.Parte.Size, ejeAncho) / 2
		minW = math.min(minW, centro - medio)
		maxW = math.max(maxW, centro + medio)
	end
	local proyPunto = punto:Dot(ejeAncho)

	-- Referencia "dentro": inodoro/urinario más cercano (cubículos de baño) o el centro de la zona.
	local modo = cfg.Modo
	if modo ~= "privacidad" and modo ~= "giro" then
		modo = "estado"
	end
	local referencia = zona and zona.Centro or nil
	if modo == "privacidad" and zona and typeof(zona.Objetos) == "table" then
		local mejor, mejorDist = nil, self.DistanciaReferenciaBano
		for _, clave in ipairs({ "Inodoros", "Urinarios" }) do
			local lista = zona.Objetos[clave]
			if typeof(lista) == "table" then
				for _, p in ipairs(lista) do
					if typeof(p) == "Vector3" then
						local d = plano(p - punto).Magnitude
						if d < mejorDist then
							mejor, mejorDist = p, d
						end
					end
				end
			end
		end
		if mejor then
			referencia = mejor
		end
	end

	local cargosSet, cargosTexto = conjuntoCargos(cfg.CargosBloqueo)
	local permiso = "puertas.oficinas"
	if zona and TIPOS_AULA[zona.Tipo] then
		permiso = "puertas.aulas"
	end

	local puerta = {
		Id = id,
		Config = cfg,
		Modo = modo,
		ModoEfectivo = "estado",
		Zona = cfg.Zona,
		ZonaDef = zona,
		Instancia = instancia,
		Raices = raices,
		Partes = registros,
		Principal = principal,
		Punto = punto,
		Normal = normal,
		EjeAncho = ejeAncho,
		MedioAncho = math.max(0.5, (maxW - minW) / 2),
		MedioGrosor = math.max(0, ejes[iFino][2] / 2),
		Referencia = referencia,
		CargosBloqueo = cargosSet,
		CargosTexto = cargosTexto,
		PermisoBloqueo = permiso,
		NombreVisible = nombreVisible(cfg, zona),
		Abierta = true,
		Cerrojo = false,
		Fijada = false,
		Privacidad = nil,
		VisualOriginal = true,
		UltimaAccion = -math.huge,
		TokenCierre = 0,
		Usos = 0,
	}

	-- Modo giro (opcional): bisagra en la arista vertical de la hoja; si algo falta, se queda en "estado".
	if modo == "giro" then
		if PERMITIR_GIRO and typeof(cfg.Hoja) == "string" and cfg.Hoja ~= "" then
			local okGiro, errGiro = pcall(function()
				self:PrepararGiro(puerta, minW, maxW, proyPunto)
			end)
			if not okGiro then
				self:Advertir("Puerta " .. id .. ": giro no disponible (" .. tostring(errGiro) .. "); se usa el modo estado.")
				puerta.Giro = nil
			end
			if puerta.Giro then
				puerta.ModoEfectivo = "giro"
			end
		end
		puerta.Modo = "estado"
		if puerta.ModoEfectivo == "giro" then
			puerta.Modo = "giro"
		end
	end

	self:CrearInstanciasPropias(puerta)
	self:MarcarHojas(puerta)
	self:AplicarVisual(puerta)
	self:ActualizarAtributos(puerta)
	self:ActualizarPrompts(puerta)
	return puerta
end

-- Calcula el pivote (arista de la bisagra) y el ángulo de apertura (hacia dentro).
function DoorService:PrepararGiro(puerta, minW, maxW, proyPunto)
	for _, rec in ipairs(puerta.Partes) do
		if not rec.Anchored then
			error("la hoja tiene piezas sin anclar")
		end
	end
	local eje = puerta.EjeAncho
	local base = puerta.Punto - eje * proyPunto
	local aristaA = base + eje * minW
	local aristaB = base + eje * maxW
	aristaA = Vector3.new(aristaA.X, puerta.Punto.Y, aristaA.Z)
	aristaB = Vector3.new(aristaB.X, puerta.Punto.Y, aristaB.Z)

	-- 1) Bisagras del modelo; 2) extremo más cercano al centro del modelo padre (regla del contrato).
	local objetivo = nil
	local suma, n = Vector3.new(0, 0, 0), 0
	local okD, lista = pcall(puerta.Instancia.GetDescendants, puerta.Instancia)
	if okD then
		for _, d in ipairs(lista) do
			if d:IsA("BasePart") and string.find(string.lower(d.Name), "bisagra", 1, true) then
				suma = suma + d.Position
				n = n + 1
			end
		end
	end
	if n > 0 then
		objetivo = suma / n
	else
		local padre = puerta.Instancia
		if padre == puerta.Principal then
			padre = puerta.Principal.Parent
		end
		if padre and padre ~= workspace then
			objetivo = posicionInstancia(padre)
		end
	end
	local arista = aristaA
	if objetivo and plano(aristaB - objetivo).Magnitude < plano(aristaA - objetivo).Magnitude then
		arista = aristaB
	end
	local pivote = CFrame.new(arista)
	local angulo = math.rad(self.AnguloGiro)
	-- Sentido: la hoja gira hacia el lado de la referencia (dentro del aula/cubículo).
	local signo = 1
	if puerta.Referencia then
		local dr = plano(puerta.Referencia - puerta.Punto):Dot(puerta.Normal)
		local cMas = (pivote * CFrame.Angles(0, angulo, 0) * pivote:Inverse()) * puerta.Punto
		local cMenos = (pivote * CFrame.Angles(0, -angulo, 0) * pivote:Inverse()) * puerta.Punto
		local dMas = plano(cMas - puerta.Punto):Dot(puerta.Normal)
		local dMenos = plano(cMenos - puerta.Punto):Dot(puerta.Normal)
		if (dr >= 0 and dMenos > dMas) or (dr < 0 and dMenos < dMas) then
			signo = -1
		end
	end
	puerta.Giro = { Pivote = pivote, Angulo = angulo * signo }
end

-- Attachment propio en la hoja (centro de la puerta) con los prompts y el sonido.
function DoorService:CrearInstanciasPropias(puerta)
	local principal = puerta.Principal
	local ancla = Instance.new("Attachment")
	ancla.Name = "ColegioRP_Puerta"
	ancla.Position = principal.CFrame:PointToObjectSpace(puerta.Punto)
	ancla.Parent = principal
	puerta.Ancla = ancla

	local zonaId = typeof(puerta.Zona) == "string" and puerta.Zona or ""
	puerta.Prompt = nuevoPrompt(ancla, "ColegioRP_PromptPuerta", {
		ActionText = "Cerrar",
		ObjectText = puerta.NombreVisible,
		HoldDuration = 0,
		MaxActivationDistance = self.DistanciaPrompt,
	}, {
		RPTipo = "Puerta", RPId = puerta.Id, RPAccion = "Alternar", RPZona = zonaId,
	})
	pcall(CollectionService.AddTag, CollectionService, puerta.Prompt, self.TagPrompt)
	table.insert(self.Conexiones, puerta.Prompt.Triggered:Connect(function(player)
		self:AlActivarPrompt(puerta, "Alternar", player)
	end))

	if puerta.Modo == "privacidad" then
		puerta.PromptPrivacidad = nuevoPrompt(ancla, "ColegioRP_PromptPrivacidad", {
			ActionText = "Privacidad",
			ObjectText = "Baño",
			HoldDuration = self.HoldBloqueo,
			MaxActivationDistance = self.DistanciaPrompt,
			KeyboardKeyCode = Enum.KeyCode.R,
			GamepadKeyCode = Enum.KeyCode.ButtonY,
			UIOffset = Vector2.new(0, 64),
		}, {
			RPTipo = "Puerta", RPId = puerta.Id, RPAccion = "Privacidad", RPZona = zonaId,
			RPPunto = puerta.Punto, RPNormal = puerta.Normal, RPReferencia = puerta.Referencia or puerta.Punto,
		})
		pcall(CollectionService.AddTag, CollectionService, puerta.PromptPrivacidad, self.TagPromptPrivacidad)
		table.insert(self.Conexiones, puerta.PromptPrivacidad.Triggered:Connect(function(player)
			self:AlActivarPrompt(puerta, "Privacidad", player)
		end))
	end

	puerta.PromptBloqueo = nuevoPrompt(ancla, "ColegioRP_PromptBloqueo", {
		ActionText = "Bloquear",
		ObjectText = "Personal autorizado",
		HoldDuration = self.HoldBloqueo,
		MaxActivationDistance = self.DistanciaPrompt,
		KeyboardKeyCode = Enum.KeyCode.G,
		GamepadKeyCode = Enum.KeyCode.ButtonR1,
		UIOffset = Vector2.new(0, 128),
	}, {
		RPTipo = "Puerta", RPId = puerta.Id, RPAccion = "Bloqueo", RPZona = zonaId,
		RPCargos = puerta.CargosTexto, RPPermiso = puerta.PermisoBloqueo,
	})
	pcall(CollectionService.AddTag, CollectionService, puerta.PromptBloqueo, self.TagPromptBloqueo)
	table.insert(self.Conexiones, puerta.PromptBloqueo.Triggered:Connect(function(player)
		self:AlActivarPrompt(puerta, "Bloqueo", player)
	end))

	if SONIDO_ID > 0 then
		pcall(function()
			local sonido = Instance.new("Sound")
			sonido.Name = "ColegioRP_SonidoPuerta"
			sonido.SoundId = "rbxassetid://" .. tostring(math.floor(SONIDO_ID))
			sonido.Volume = 0.6
			sonido.RollOffMaxDistance = 45
			sonido.Parent = ancla
			puerta.Sonido = sonido
		end)
	end
end

-- Tag y atributo PuertaId en las hojas (vía MapService para que su Limpiar los retire; si no, directo).
function DoorService:MarcarHojas(puerta)
	local MapService = self:Servicio("MapService")
	local marcarTag = MapService and typeof(MapService.MarcarTag) == "function"
	local marcarAtributo = MapService and typeof(MapService.MarcarAtributo) == "function"
	local destinos = {}
	local vistos = {}
	for _, raiz in ipairs(puerta.Raices) do
		if not vistos[raiz] then
			vistos[raiz] = true
			table.insert(destinos, raiz)
		end
	end
	if not vistos[puerta.Principal] then
		table.insert(destinos, puerta.Principal)
	end
	puerta.Marcadas = destinos
	for _, destino in ipairs(destinos) do
		if marcarTag then
			pcall(MapService.MarcarTag, MapService, destino, TAG_HOJA)
		else
			pcall(CollectionService.AddTag, CollectionService, destino, TAG_HOJA)
		end
		for _, nombre in ipairs({ "PuertaId", "Estado", "Bloqueada", "Fijada" }) do
			local valor = nil
			if nombre == "PuertaId" then
				valor = puerta.Id
			end
			if marcarAtributo then
				pcall(MapService.MarcarAtributo, MapService, destino, nombre, valor)
			else
				pcall(destino.SetAttribute, destino, nombre, valor)
			end
		end
	end
end

---------------------------------------------------------------------------------------------------
-- Estado visual y textos
---------------------------------------------------------------------------------------------------
function DoorService:EstadoTexto(puerta)
	if puerta.Privacidad then
		return "Privada"
	end
	if puerta.Abierta then
		return "Abierta"
	end
	if puerta.Cerrojo then
		return "Bloqueada"
	end
	return "Cerrada"
end

-- Aplica Transparency / CanCollide (y CFrame en modo giro) según el estado. Nunca toca los marcos.
function DoorService:AplicarVisual(puerta)
	if puerta.ModoEfectivo == "giro" and puerta.Giro then
		local okGiro, errGiro = pcall(function()
			local info = TweenInfo.new(self.DuracionGiro, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			local rotar = puerta.Abierta and not puerta.VisualOriginal
			local transformacion = puerta.Giro.Pivote * CFrame.Angles(0, puerta.Giro.Angulo, 0) * puerta.Giro.Pivote:Inverse()
			for _, rec in ipairs(puerta.Partes) do
				local destino = rec.CFrame
				if rotar then
					destino = transformacion * rec.CFrame
				end
				TweenService:Create(rec.Parte, info, { CFrame = destino }):Play()
			end
		end)
		if not okGiro then
			warn(PREFIJO .. " Puerta " .. puerta.Id .. ": el giro falló (" .. tostring(errGiro) .. "); se pasa al modo estado.")
			puerta.ModoEfectivo = "estado"
			puerta.Modo = "estado"
			for _, rec in ipairs(puerta.Partes) do
				pcall(function()
					rec.Parte.CFrame = rec.CFrame
				end)
			end
		end
	end
	local usarTransparencia = puerta.ModoEfectivo == "estado" and puerta.Abierta and not puerta.VisualOriginal
	for _, rec in ipairs(puerta.Partes) do
		pcall(function()
			if puerta.Abierta then
				if usarTransparencia then
					rec.Parte.Transparency = math.max(rec.Transparency, self.TransparenciaAbierta)
				else
					rec.Parte.Transparency = rec.Transparency
				end
				rec.Parte.CanCollide = false
			else
				rec.Parte.Transparency = rec.Transparency
				rec.Parte.CanCollide = rec.CanCollide or rec.Principal
			end
		end)
	end
end

function DoorService:ActualizarAtributos(puerta)
	local estado = self:EstadoTexto(puerta)
	local bloqueada = puerta.Cerrojo or puerta.Fijada
	for _, destino in ipairs(puerta.Marcadas or {}) do
		pcall(destino.SetAttribute, destino, "Estado", estado)
		pcall(destino.SetAttribute, destino, "Bloqueada", bloqueada)
		pcall(destino.SetAttribute, destino, "Fijada", puerta.Fijada)
	end
	if puerta.Prompt then
		pcall(puerta.Prompt.SetAttribute, puerta.Prompt, "Estado", estado)
		pcall(puerta.Prompt.SetAttribute, puerta.Prompt, "Bloqueada", bloqueada)
		pcall(puerta.Prompt.SetAttribute, puerta.Prompt, "Fijada", puerta.Fijada)
	end
end

function DoorService:ActualizarPrompts(puerta)
	pcall(function()
		local prompt = puerta.Prompt
		if prompt then
			local estado = self:EstadoTexto(puerta)
			if estado == "Abierta" then
				prompt.ActionText = "Cerrar"
			elseif estado == "Cerrada" then
				prompt.ActionText = "Abrir"
			else
				prompt.ActionText = "Bloqueada"
			end
			local objeto = puerta.NombreVisible
			if estado == "Privada" then
				objeto = "Baño ocupado"
			elseif estado == "Bloqueada" then
				objeto = puerta.NombreVisible .. " · solo salida"
			elseif puerta.Fijada then
				objeto = puerta.NombreVisible .. " · fijada abierta"
			end
			prompt.ObjectText = objeto
		end
		if puerta.PromptBloqueo then
			if puerta.Cerrojo or puerta.Fijada then
				puerta.PromptBloqueo.ActionText = "Desbloquear"
			elseif puerta.Abierta then
				puerta.PromptBloqueo.ActionText = "Fijar abierta"
			else
				puerta.PromptBloqueo.ActionText = "Bloquear"
			end
		end
		if puerta.PromptPrivacidad then
			if puerta.Privacidad then
				puerta.PromptPrivacidad.ActionText = "Quitar privacidad"
			else
				puerta.PromptPrivacidad.ActionText = "Privacidad (" .. tostring(math.floor(PRIVACIDAD_SEG)) .. " s)"
			end
		end
	end)
end

function DoorService:Sonar(puerta)
	if puerta.Sonido then
		pcall(function()
			puerta.Sonido:Play()
		end)
	end
end

---------------------------------------------------------------------------------------------------
-- Reglas: dentro/fuera, permisos, umbral
---------------------------------------------------------------------------------------------------

-- ¿La posición está "dentro" respecto a la puerta? Lado del plano de la hoja donde está la referencia (centro de la
-- zona o inodoro del cubículo); en el umbral siempre cuenta como dentro (nunca se encierra a nadie).
function DoorService:EsDentro(puerta, posicion)
	if typeof(posicion) ~= "Vector3" then
		return false
	end
	local rel = plano(posicion - puerta.Punto)
	local dp = rel:Dot(puerta.Normal)
	local lateral = math.abs(rel:Dot(puerta.EjeAncho))
	-- Con la hoja cerrada (sólida) solo cuenta como umbral quien quedó dentro de la propia hoja: pegarse a ella
	-- desde fuera no basta para abrir una puerta bloqueada ni un baño con privacidad. Sin referencia ni zona no hay
	-- otra forma de saber el lado, así que se mantiene el umbral amplio (nunca se encierra a nadie).
	local umbral = 0.75
	if not puerta.Abierta and (puerta.Referencia or puerta.ZonaDef) then
		umbral = math.min(umbral, (puerta.MedioGrosor or 0) + 0.25)
	end
	if math.abs(dp) < umbral and lateral <= puerta.MedioAncho + 1 then
		return true
	end
	local zona = puerta.ZonaDef
	local dentroPlano = false
	if puerta.Referencia then
		local dr = plano(puerta.Referencia - puerta.Punto):Dot(puerta.Normal)
		if math.abs(dr) >= 0.5 then
			dentroPlano = (dp > 0) == (dr > 0)
		elseif zona then
			dentroPlano = Zones.Contiene(zona, posicion)
		end
	elseif zona then
		dentroPlano = Zones.Contiene(zona, posicion)
	end
	if dentroPlano then
		return true
	end
	-- Puertas de aula con la hoja girada (abierta en el mapa): dentro de la caja de la zona y más hacia su centro.
	if puerta.Modo ~= "privacidad" and zona and Zones.Contiene(zona, posicion) then
		local dJugador = plano(posicion - zona.Centro).Magnitude
		local dPuerta = plano(puerta.Punto - zona.Centro).Magnitude
		if dJugador + 1 < dPuerta then
			return true
		end
	end
	return false
end

-- ¿El jugador puede bloquear/desbloquear? Cargo en CargosBloqueo o permiso puertas.aulas / puertas.oficinas.
function DoorService:PuedeBloquear(player, puerta)
	local RoleService = self:Servicio("RoleService")
	if not RoleService then
		return false
	end
	if typeof(RoleService.Cargo) == "function" then
		local ok, cargo = pcall(RoleService.Cargo, RoleService, player)
		if ok and typeof(cargo) == "string" and puerta.CargosBloqueo[cargo] then
			return true
		end
	end
	if typeof(RoleService.Tiene) == "function" then
		local ok, tiene = pcall(RoleService.Tiene, RoleService, player, puerta.PermisoBloqueo)
		if ok and tiene == true then
			return true
		end
	end
	return false
end

-- ¿Hay algún jugador en el umbral? (el autocierre espera para no empujar a nadie)
function DoorService:HayAlguienEnUmbral(puerta)
	for _, player in ipairs(Players:GetPlayers()) do
		local pos = posicionJugador(player)
		if pos then
			local rel = pos - puerta.Punto
			if math.abs(rel.Y) <= 8 then
				local h = plano(rel)
				if math.abs(h:Dot(puerta.Normal)) <= self.UmbralGrosor and math.abs(h:Dot(puerta.EjeAncho)) <= puerta.MedioAncho + 1 then
					return true
				end
			end
		end
	end
	return false
end

---------------------------------------------------------------------------------------------------
-- Acciones (misma lógica para prompts, remoto y otros servicios)
---------------------------------------------------------------------------------------------------

-- Abre o cierra físicamente (sin comprobar reglas).
function DoorService:CambiarApertura(puerta, abierta)
	if puerta.Abierta == abierta then
		return
	end
	puerta.Abierta = abierta
	puerta.TokenCierre = puerta.TokenCierre + 1
	if not abierta then
		puerta.VisualOriginal = false
	end
	self:AplicarVisual(puerta)
	self:Sonar(puerta)
end

function DoorService:ProgramarAutocierre(puerta)
	if AUTOCIERRE_SEG <= 0 or puerta.Fijada then
		return
	end
	puerta.TokenCierre = puerta.TokenCierre + 1
	local token = puerta.TokenCierre
	task.delay(AUTOCIERRE_SEG, function()
		self:IntentarAutocierre(puerta, token)
	end)
end

function DoorService:IntentarAutocierre(puerta, token)
	if not self.Activo or puerta.TokenCierre ~= token or not puerta.Abierta or puerta.Fijada then
		return
	end
	if self:HayAlguienEnUmbral(puerta) then
		task.delay(self.ReintentoAutocierreSeg, function()
			self:IntentarAutocierre(puerta, token)
		end)
		return
	end
	self:CambiarApertura(puerta, false)
	self:Publicar(puerta, nil, "Autocierre")
end

-- Ejecuta una acción. player = nil para acciones del sistema (sin distancia, cooldown ni permisos).
-- Devuelve ok, mensaje, codigo ("ok" | "sin_cambio" | motivo de rechazo).
function DoorService:Accion(player, puertaId, accion, origen)
	local puerta = typeof(puertaId) == "string" and self.Puertas[puertaId] or nil
	if not puerta then
		return false, "Esa puerta no está disponible.", "puerta_inexistente"
	end
	if typeof(accion) ~= "string" or not ACCIONES[accion] then
		return false, "Acción no válida.", "accion_invalida"
	end
	local ahora = os.clock()
	local dentro = true
	local autorizado = true
	if player ~= nil then
		if not esJugador(player) then
			return false, "Jugador no válido.", "jugador_invalido"
		end
		local pos = posicionJugador(player)
		if not pos then
			return false, "Necesitas tu personaje para usar la puerta.", "sin_personaje"
		end
		if (pos - puerta.Punto).Magnitude > DISTANCIA_MAX + self.ToleranciaDistancia then
			return false, "Acércate más a la puerta.", "distancia"
		end
		if ahora - puerta.UltimaAccion < COOLDOWN_SEG then
			return false, "Espera un momento.", "cooldown"
		end
		dentro = self:EsDentro(puerta, pos)
		autorizado = self:PuedeBloquear(player, puerta)
	end

	local mensaje = nil
	if accion == "Abrir" then
		if puerta.Abierta then
			return true, "La puerta ya está abierta.", "sin_cambio"
		end
		if puerta.Privacidad and not dentro then
			return false, "El baño está ocupado. Espera un momento.", "ocupado"
		end
		if puerta.Cerrojo and not dentro and not autorizado then
			return false, "La puerta está bloqueada: solo se abre desde dentro o por el personal autorizado.", "bloqueada"
		end
		puerta.Privacidad = nil
		self:CambiarApertura(puerta, true)
		self:ProgramarAutocierre(puerta)
	elseif accion == "Cerrar" then
		if not puerta.Abierta then
			return true, "La puerta ya está cerrada.", "sin_cambio"
		end
		if puerta.Fijada and not autorizado then
			return false, "El personal dejó esta puerta fijada abierta.", "fijada"
		end
		if puerta.Fijada then
			-- El personal cierra una puerta fijada: queda cerrada y bloqueada contra la entrada.
			puerta.Fijada = false
			puerta.Cerrojo = true
		end
		self:CambiarApertura(puerta, false)
	elseif accion == "Bloquear" then
		if not autorizado then
			return false, "No tienes permiso para bloquear esta puerta.", "sin_permiso_bloqueo"
		end
		if puerta.Cerrojo or puerta.Fijada then
			return true, "La puerta ya está bloqueada.", "sin_cambio"
		end
		if puerta.Abierta then
			puerta.Fijada = true
			puerta.TokenCierre = puerta.TokenCierre + 1 -- cancela el autocierre pendiente
			mensaje = "Puerta fijada abierta (sin cierre automático)."
		else
			puerta.Cerrojo = true
			mensaje = "Puerta bloqueada: desde dentro siempre se puede salir."
		end
	elseif accion == "Desbloquear" then
		if not autorizado then
			return false, "No tienes permiso para desbloquear esta puerta.", "sin_permiso_bloqueo"
		end
		if not puerta.Cerrojo and not puerta.Fijada then
			return true, "La puerta no estaba bloqueada.", "sin_cambio"
		end
		local estabaFijada = puerta.Fijada
		puerta.Cerrojo = false
		puerta.Fijada = false
		if puerta.Abierta and estabaFijada then
			self:ProgramarAutocierre(puerta)
		end
		mensaje = "Puerta desbloqueada."
	elseif accion == "Privacidad" then
		if puerta.Modo ~= "privacidad" then
			return false, "Esta puerta no tiene modo privacidad.", "sin_privacidad"
		end
		if player == nil then
			if puerta.Privacidad then
				puerta.Privacidad = nil
				mensaje = "Privacidad desactivada."
			else
				return true, "Sin cambios.", "sin_cambio"
			end
		elseif not dentro then
			return false, "La privacidad solo se activa desde dentro del baño.", "fuera"
		elseif puerta.Privacidad then
			puerta.Privacidad = nil
			mensaje = "Privacidad desactivada."
		else
			local ultima = self.UltimaPrivacidad[player.UserId]
			if ultima and ahora - ultima < self.CooldownPrivacidadJugador then
				return false, "Espera unos segundos para volver a activar la privacidad.", "cooldown"
			end
			self.UltimaPrivacidad[player.UserId] = ahora
			if puerta.Abierta then
				self:CambiarApertura(puerta, false)
			end
			puerta.Privacidad = {
				Hasta = ahora + PRIVACIDAD_SEG,
				HastaServidor = ahoraServidor() + PRIVACIDAD_SEG,
				UserId = player.UserId,
				VacioDesde = nil,
			}
			mensaje = "Privacidad activada durante " .. tostring(math.floor(PRIVACIDAD_SEG)) .. " s."
		end
	end

	puerta.UltimaAccion = ahora
	puerta.Usos = puerta.Usos + 1
	self:Publicar(puerta, player, accion)
	if accion == "Bloquear" or accion == "Desbloquear" then
		local AuditLog = self:Servicio("AuditLogService")
		if AuditLog then
			pcall(AuditLog.Registrar, AuditLog, "Sistema", player, "Puerta", puerta.Id .. " " .. accion .. " (" .. tostring(origen or "Sistema") .. ")")
		end
	end
	return true, mensaje, "ok"
end

-- Prompt físico activado (el evento llega al servidor con el jugador).
function DoorService:AlActivarPrompt(puerta, tipo, player)
	if not self.Activo or not esJugador(player) then
		return
	end
	local ahora = os.clock()
	local ultimo = self.UltimoPrompt[player.UserId]
	if ultimo and ahora - ultimo < self.IntervaloPromptSeg then
		return
	end
	self.UltimoPrompt[player.UserId] = ahora
	local accion
	if tipo == "Bloqueo" then
		if puerta.Cerrojo or puerta.Fijada then
			accion = "Desbloquear"
		else
			accion = "Bloquear"
		end
	elseif tipo == "Privacidad" then
		accion = "Privacidad"
	elseif puerta.Abierta then
		accion = "Cerrar"
	else
		accion = "Abrir"
	end
	local ok, mensaje, codigo = self:Accion(player, puerta.Id, accion, "Prompt")
	if not ok then
		self:RegistrarRechazo(player, "Prompt", codigo, puerta.Id, accion)
		self:EnviarMensaje(player, puerta, mensaje, "aviso")
	elseif mensaje and codigo == "ok" and accion ~= "Abrir" and accion ~= "Cerrar" then
		self:EnviarMensaje(player, puerta, mensaje, "exito")
	end
end

-- Handler del remoto DoorAction { PuertaId, Accion }.
function DoorService:ManejarDoorAction(player, datos)
	local puertaId = datos.PuertaId
	local accion = datos.Accion
	local ok, mensaje, codigo = self:Accion(player, puertaId, accion, "Remoto")
	if not ok then
		self:RegistrarRechazo(player, "DoorAction", codigo, puertaId, accion)
		return { ok = false, error = mensaje, datos = { PuertaId = puertaId, Codigo = codigo } }
	end
	local puerta = self.Puertas[puertaId]
	return {
		ok = true,
		datos = {
			PuertaId = puertaId,
			Estado = puerta and self:EstadoTexto(puerta) or nil,
			Mensaje = mensaje,
			Codigo = codigo,
		},
	}
end

function DoorService:RegistrarRechazo(player, origen, codigo, puertaId, accion)
	if not MOTIVOS_AUDITADOS[codigo] then
		return
	end
	-- Un mismo rechazo repetido (p. ej. pulsar sin parar una puerta bloqueada) se audita una vez cada 10 s.
	if esJugador(player) then
		local porJugador = self.UltimaAuditoria[player.UserId]
		if not porJugador then
			porJugador = {}
			self.UltimaAuditoria[player.UserId] = porJugador
		end
		local clave = tostring(puertaId) .. "|" .. tostring(codigo)
		local ahora = os.clock()
		if porJugador[clave] and ahora - porJugador[clave] < self.IntervaloAuditoriaSeg then
			return
		end
		porJugador[clave] = ahora
	end
	local AuditLog = self:Servicio("AuditLogService")
	if AuditLog then
		pcall(AuditLog.Registrar, AuditLog, "Remoto", player, "DoorAction",
			string.format("logica:%s puerta=%s accion=%s origen=%s", tostring(codigo), tostring(puertaId), tostring(accion), tostring(origen)))
	end
	if MOTIVOS_METRICAS[codigo] then
		local Metrics = self:Servicio("MetricsService")
		if Metrics and typeof(Metrics.IncrementarRechazo) == "function" then
			pcall(Metrics.IncrementarRechazo, Metrics, "DoorAction", tostring(codigo))
		end
	end
end

---------------------------------------------------------------------------------------------------
-- Privacidad de baños
---------------------------------------------------------------------------------------------------
function DoorService:LiberarPrivacidad(puerta, motivo)
	local privacidad = puerta.Privacidad
	if not privacidad then
		return
	end
	puerta.Privacidad = nil
	self:Publicar(puerta, nil, "PrivacidadTerminada")
	local dueno = Players:GetPlayerByUserId(privacidad.UserId)
	if dueno and motivo ~= "salida" then
		self:EnviarMensaje(dueno, puerta, "La privacidad del baño terminó.", "info")
	end
end

function DoorService:RevisarPrivacidad()
	local ahora = os.clock()
	for _, id in ipairs(self.Orden) do
		local puerta = self.Puertas[id]
		local privacidad = puerta and puerta.Privacidad
		if privacidad then
			if ahora >= privacidad.Hasta then
				self:LiberarPrivacidad(puerta, "caducidad")
			else
				local alguien = false
				for _, player in ipairs(Players:GetPlayers()) do
					local pos = posicionJugador(player)
					if pos and (pos - puerta.Punto).Magnitude <= DISTANCIA_MAX and self:EsDentro(puerta, pos) then
						alguien = true
						break
					end
				end
				if alguien then
					privacidad.VacioDesde = nil
				elseif privacidad.VacioDesde == nil then
					privacidad.VacioDesde = ahora
				elseif ahora - privacidad.VacioDesde >= self.GraciaVaciaSeg then
					self:LiberarPrivacidad(puerta, "vacio")
				end
			end
		end
	end
end

---------------------------------------------------------------------------------------------------
-- Publicación al cliente
---------------------------------------------------------------------------------------------------
function DoorService:DatosEstado(puerta)
	return {
		PuertaId = puerta.Id,
		Estado = self:EstadoTexto(puerta),
		Abierta = puerta.Abierta,
		Bloqueada = puerta.Cerrojo or puerta.Fijada,
		Fijada = puerta.Fijada,
		Privada = puerta.Privacidad ~= nil,
		PrivadaHasta = puerta.Privacidad and puerta.Privacidad.HastaServidor or nil,
		Zona = puerta.Zona,
		Modo = puerta.Modo,
	}
end

-- Atributos, prompts y evento "Puerta" { Sub = "Estado" } a la zona, a los cercanos y al actor.
function DoorService:Publicar(puerta, actor, accion)
	self:ActualizarAtributos(puerta)
	self:ActualizarPrompts(puerta)
	local datos = self:DatosEstado(puerta)
	datos.Sub = "Estado"
	datos.Accion = accion
	if esJugador(actor) then
		datos.ActorUserId = actor.UserId
	end
	pcall(function()
		self.EstadoCambiado:Fire(puerta.Id, datos.Estado, datos)
	end)
	local RemoteService = self:Servicio("RemoteService")
	if not RemoteService then
		return
	end
	local zona = puerta.ZonaDef
	if zona and typeof(RemoteService.EnviarAZona) == "function" then
		pcall(RemoteService.EnviarAZona, RemoteService, puerta.Zona, "Puerta", datos)
	end
	if typeof(RemoteService.Enviar) ~= "function" then
		return
	end
	for _, player in ipairs(Players:GetPlayers()) do
		local pos = posicionJugador(player)
		local enZona = zona ~= nil and pos ~= nil and Zones.Contiene(zona, pos)
		if not enZona then
			local cerca = pos ~= nil and (pos - puerta.Punto).Magnitude <= self.DistanciaAvisoVecinos
			if cerca or player == actor then
				pcall(RemoteService.Enviar, RemoteService, player, "Puerta", datos)
			end
		end
	end
end

function DoorService:EnviarMensaje(player, puerta, texto, nivel)
	if not esJugador(player) or typeof(texto) ~= "string" or texto == "" then
		return
	end
	local RemoteService = self:Servicio("RemoteService")
	if RemoteService and typeof(RemoteService.Enviar) == "function" then
		pcall(RemoteService.Enviar, RemoteService, player, "Puerta", {
			Sub = "Mensaje", PuertaId = puerta and puerta.Id or nil, Texto = texto, Nivel = nivel or "info",
		})
	end
end

---------------------------------------------------------------------------------------------------
-- API para otros servicios
---------------------------------------------------------------------------------------------------

-- Estado de una puerta (tabla serializable) o, sin id, de todas { [puertaId] = estado }.
function DoorService:Estado(puertaId)
	if puertaId == nil then
		local todas = {}
		for _, id in ipairs(self.Orden) do
			todas[id] = self:DatosEstado(self.Puertas[id])
		end
		return todas
	end
	local puerta = self.Puertas[puertaId]
	if not puerta then
		return nil
	end
	return self:DatosEstado(puerta)
end

-- Resumen compacto para StateSnapshot: { [puertaId] = { Estado, Bloqueada, Fijada } }.
function DoorService:Snapshot()
	local resumen = {}
	for _, id in ipairs(self.Orden) do
		local puerta = self.Puertas[id]
		resumen[id] = { Estado = self:EstadoTexto(puerta), Bloqueada = puerta.Cerrojo or puerta.Fijada, Fijada = puerta.Fijada }
	end
	return resumen
end

-- Ids de las puertas resueltas (copia) y de las que no se encontraron en el mapa.
function DoorService:Lista()
	local copia = {}
	for i, id in ipairs(self.Orden) do
		copia[i] = id
	end
	return copia
end

function DoorService:NoEncontradas()
	local copia = {}
	for i, id in ipairs(self.NoResueltas) do
		copia[i] = id
	end
	return copia
end

-- Abre / cierra. player opcional: con jugador se aplican todas las reglas; sin él es una acción del sistema.
function DoorService:Abrir(puertaId, player)
	return self:Accion(player, puertaId, "Abrir", "Servicio")
end

function DoorService:Cerrar(puertaId, player)
	return self:Accion(player, puertaId, "Cerrar", "Servicio")
end

-- Bloquea (true) o desbloquea (false). Con player se exige CargosBloqueo o permiso puertas.*. Devuelve ok, mensaje.
function DoorService:Bloquear(puertaId, bloquear, player)
	local accion = "Desbloquear"
	if bloquear then
		accion = "Bloquear"
	end
	local ok, mensaje = self:Accion(player, puertaId, accion, "Servicio")
	return ok, mensaje
end

-- Emergencia / fin de jornada: quita bloqueos y privacidad y abre todas las puertas.
function DoorService:AbrirTodas(motivo)
	local n = 0
	for _, id in ipairs(self.Orden) do
		local puerta = self.Puertas[id]
		puerta.Cerrojo = false
		puerta.Fijada = false
		puerta.Privacidad = nil
		if not puerta.Abierta then
			self:CambiarApertura(puerta, true)
			n = n + 1
		end
		self:Publicar(puerta, nil, "AbrirTodas")
	end
	local AuditLog = self:Servicio("AuditLogService")
	if AuditLog then
		pcall(AuditLog.Registrar, AuditLog, "Sistema", nil, "Puertas", "Abrir todas: " .. tostring(motivo or "sin motivo") .. " (" .. n .. " abiertas)")
	end
	return n
end

-- Restaura las hojas a sus valores originales y retira prompts, sonidos, atributos y tags (desinstalación).
function DoorService:Restaurar()
	self.Activo = false
	for _, conexion in ipairs(self.Conexiones) do
		pcall(function()
			conexion:Disconnect()
		end)
	end
	self.Conexiones = {}
	for _, id in ipairs(self.Orden) do
		local puerta = self.Puertas[id]
		for _, rec in ipairs(puerta.Partes) do
			pcall(function()
				rec.Parte.CFrame = rec.CFrame
				rec.Parte.Transparency = rec.Transparency
				rec.Parte.CanCollide = rec.CanCollide
			end)
		end
		for _, destino in ipairs(puerta.Marcadas or {}) do
			for _, nombre in ipairs({ "PuertaId", "Estado", "Bloqueada", "Fijada" }) do
				pcall(destino.SetAttribute, destino, nombre, nil)
			end
			pcall(CollectionService.RemoveTag, CollectionService, destino, TAG_HOJA)
		end
		if puerta.Ancla then
			pcall(function()
				puerta.Ancla:Destroy()
			end)
		end
	end
	self.Puertas = {}
	self.Orden = {}
end

-- Informe para Output / MetricsService.
function DoorService:Inventario()
	local lineas = { string.format("Puertas: %d resueltas, %d no encontradas", #self.Orden, #self.NoResueltas) }
	for _, id in ipairs(self.Orden) do
		local puerta = self.Puertas[id]
		table.insert(lineas, string.format("  %s [%s/%s] %s · %d piezas · zona %s", id, puerta.Modo, puerta.ModoEfectivo,
			self:EstadoTexto(puerta), #puerta.Partes, tostring(puerta.Zona)))
	end
	if #self.NoResueltas > 0 then
		table.insert(lineas, "  No encontradas: " .. table.concat(self.NoResueltas, " "))
	end
	return {
		Resueltas = #self.Orden,
		NoResueltas = self:NoEncontradas(),
		Advertencias = self.Advertencias,
		Texto = table.concat(lineas, "\n"),
	}
end

return DoorService
]=] }
FUENTES["ServerScriptService/ColegioRP/Services/EconomyService"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ServerScriptService.ColegioRP.Services.EconomyService
	Tipo: ModuleScript
	Economía escolar (docs/ARQUITECTURA.md §6, prueba P9): saldo en Perfil.Economia (DataService), créditos con
	límite diario (GanadoHoy / DiaUltimo por os.date("%Y-%m-%d")), débitos atómicos con bloqueo por jugador
	("en transacción"), historial por perfil (máx. Config.Datos.MaxHistorialEconomia), buffer circular de las
	últimas 200 transacciones para finanzas, resumen global y evento "Economia" { Sub = "Saldo", Saldo, Delta,
	Detalle } al jugador en cada movimiento. Sin DataService funciona en memoria (solo durante la sesión).
]]

local Players = game:GetService("Players")

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RP = ReplicatedStorage:WaitForChild("ColegioRP")
local Shared = RP:WaitForChild("Shared")
local Config = require(Shared:WaitForChild("Config"))
local Util = Shared:WaitForChild("Util")
local Signal = require(Util:WaitForChild("Signal"))
local Format = require(Util:WaitForChild("Format"))

local EconomyService = {}
EconomyService.Nombre = "EconomyService"

local PREFIJO = "[ColegioRP][EconomyService]"
local CFG = Config.Economia or {}
local MAX_SALDO = 1000000000

-- Entradas del historial por perfil (DataService sanea con el mismo límite).
EconomyService.MaxHistorial = math.max(1, math.floor(tonumber(Config.Datos and Config.Datos.MaxHistorialEconomia) or 30))
-- Tamaño del buffer circular de transacciones (panel de finanzas / auditoría económica).
EconomyService.TamanoTransacciones = 200
-- Tipos de crédito que no cuentan para el límite diario (devoluciones y saldo de bienvenida).
EconomyService.TiposSinLimite = { Reembolso = true, Inicial = true }
-- Longitudes máximas guardadas (coinciden con el saneamiento de DataService).
EconomyService.MaxTipoCaracteres = 24
EconomyService.MaxDetalleCaracteres = 80

---------------------------------------------------------------------------------------------------
-- Utilidades
---------------------------------------------------------------------------------------------------
local function esFinito(n)
	return typeof(n) == "number" and n == n and n ~= math.huge and n ~= -math.huge
end

-- Monto entero no negativo o nil si no es válido.
local function montoValido(valor)
	if not esFinito(valor) then
		return nil
	end
	local n = math.floor(valor + 0.5)
	if n < 0 or n > MAX_SALDO then
		return nil
	end
	return n
end

-- Resuelve Player o userId a (player|nil, userId|nil).
local function resolver(objetivo)
	if typeof(objetivo) == "Instance" and objetivo:IsA("Player") then
		return objetivo, objetivo.UserId
	end
	if typeof(objetivo) == "number" and esFinito(objetivo) then
		local userId = math.floor(objetivo)
		return Players:GetPlayerByUserId(userId), userId
	end
	return nil, nil
end

local function texto(valor, max)
	if valor == nil then
		return ""
	end
	local t = tostring(valor)
	t = string.gsub(t, "[%c]", " ")
	return Format.Truncar(t, max)
end

-- Clave del día ("AAAA-MM-DD") para el límite diario.
local function claveDia()
	local ok, valor = pcall(os.date, "%Y-%m-%d")
	if ok and typeof(valor) == "string" and string.match(valor, "^%d%d%d%d%-%d%d%-%d%d$") then
		return valor
	end
	return Format.ClaveDia(os.time())
end

local function copiarMovimiento(m)
	return { T = m.T, Tipo = m.Tipo, Monto = m.Monto, Detalle = m.Detalle }
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function EconomyService:Init(registro)
	self.registro = registro
	self.EnTransaccion = {} -- userId -> true mientras dura un débito (bloqueo por jugador)
	self.Memoria = {} -- userId -> { Economia = {...} } si no hay DataService
	self.BufferTx = table.create(self.TamanoTransacciones) -- buffer circular (no confundir con el método Transacciones)
	self.IndiceTx = 0 -- última posición escrita en el buffer circular
	self.TotalTx = 0 -- transacciones registradas desde el arranque (también Id)
	self.Totales = { Acreditado = 0, Debitado = 0, RechazosSaldo = 0, RechazosLimite = 0, RechazosBloqueo = 0, PorTipo = {} }
	self.LimiteAvisado = {} -- userId -> clave del día en que ya se avisó del límite
	self.InicioUnix = os.time()
	self.SaldoCambiado = Signal.new() -- (player, saldo, delta, tipo, detalle)
	self.Conexiones = {}
end

function EconomyService:Start()
	local DataService = self:_S("DataService")
	if DataService and DataService.PerfilCargado and typeof(DataService.PerfilCargado.Connect) == "function" then
		table.insert(self.Conexiones, DataService.PerfilCargado:Connect(function(player, perfil)
			local ok, err = pcall(self._AlCargarPerfil, self, player, perfil)
			if not ok then
				warn(PREFIJO .. " Error al preparar la economía de " .. tostring(player) .. ": " .. tostring(err))
			end
		end))
	elseif not DataService then
		warn(PREFIJO .. " DataService no disponible: los saldos solo vivirán en memoria durante la sesión.")
	end

	-- Perfiles que ya estaban cargados antes de este Start.
	for _, player in ipairs(Players:GetPlayers()) do
		local perfil = DataService and DataService:Obtener(player)
		if perfil then
			pcall(self._AlCargarPerfil, self, player, perfil)
		end
	end

	table.insert(self.Conexiones, Players.PlayerRemoving:Connect(function(player)
		self.EnTransaccion[player.UserId] = nil
		self.LimiteAvisado[player.UserId] = nil
		self.Memoria[player.UserId] = nil
	end))
end

function EconomyService:_S(nombre)
	local registro = self.registro
	if typeof(registro) ~= "table" or typeof(registro.Get) ~= "function" then
		return nil
	end
	local ok, servicio = pcall(registro.Get, nombre)
	if ok and typeof(servicio) == "table" then
		return servicio
	end
	return nil
end

function EconomyService:_Auditar(player, accion, detalle)
	local AuditLog = self:_S("AuditLogService")
	if AuditLog and typeof(AuditLog.Registrar) == "function" then
		pcall(AuditLog.Registrar, AuditLog, "Economia", player, accion, detalle)
	end
end

function EconomyService:_Enviar(player, tipo, datos)
	if typeof(player) ~= "Instance" or player.Parent == nil then
		return false
	end
	local RemoteService = self:_S("RemoteService")
	if RemoteService and typeof(RemoteService.Enviar) == "function" then
		local ok, resultado = pcall(RemoteService.Enviar, RemoteService, player, tipo, datos)
		return ok and resultado == true
	end
	return false
end

---------------------------------------------------------------------------------------------------
-- Acceso al bloque Economia del perfil
---------------------------------------------------------------------------------------------------

-- Normaliza el bloque Economia (tipos y campos) y aplica el cambio de día. Devuelve la tabla.
function EconomyService:_Normalizar(eco)
	if not esFinito(eco.Saldo) then
		eco.Saldo = math.floor(tonumber(CFG.SaldoInicial) or 50)
	end
	eco.Saldo = math.clamp(math.floor(eco.Saldo), 0, MAX_SALDO)
	if not esFinito(eco.GanadoHoy) then
		eco.GanadoHoy = 0
	end
	if typeof(eco.DiaUltimo) ~= "string" then
		eco.DiaUltimo = ""
	end
	if typeof(eco.Historial) ~= "table" then
		eco.Historial = {}
	end
	local hoy = claveDia()
	if eco.DiaUltimo ~= hoy then
		eco.DiaUltimo = hoy
		eco.GanadoHoy = 0
	end
	return eco
end

-- Bloque Economia del jugador (Player o userId) o nil si el perfil aún no está cargado.
function EconomyService:_Economia(objetivo)
	local player, userId = resolver(objetivo)
	if not userId then
		return nil, nil
	end
	local DataService = self:_S("DataService")
	if DataService and typeof(DataService.Obtener) == "function" then
		local ok, perfil = pcall(DataService.Obtener, DataService, player or userId)
		if not ok or typeof(perfil) ~= "table" then
			return nil, player
		end
		if typeof(perfil.Economia) ~= "table" then
			perfil.Economia = { Saldo = math.floor(tonumber(CFG.SaldoInicial) or 50), GanadoHoy = 0, DiaUltimo = "", Historial = {} }
		end
		return self:_Normalizar(perfil.Economia), player
	end
	-- Sin DataService: perfil en memoria de la sesión (solo jugadores conectados).
	if not player then
		return nil, nil
	end
	local memoria = self.Memoria[userId]
	if not memoria then
		local saldoInicial = math.floor(tonumber(CFG.SaldoInicial) or 50)
		memoria = { Economia = { Saldo = saldoInicial, GanadoHoy = 0, DiaUltimo = "", Historial = {} } }
		table.insert(memoria.Economia.Historial, { T = os.time(), Tipo = "Inicial", Monto = saldoInicial, Detalle = "Saldo inicial de bienvenida" })
		self.Memoria[userId] = memoria
	end
	return self:_Normalizar(memoria.Economia), player
end

function EconomyService:_Marcar(player)
	local DataService = self:_S("DataService")
	if DataService and typeof(DataService.Marcar) == "function" then
		pcall(DataService.Marcar, DataService, player)
	end
end

-- Al cargar un perfil: normaliza, registra el saldo de bienvenida en perfiles nuevos y envía el saldo.
function EconomyService:_AlCargarPerfil(player, perfil)
	if typeof(perfil) ~= "table" then
		return
	end
	local eco = self:_Economia(player)
	if not eco then
		return
	end
	local DataService = self:_S("DataService")
	local estado = nil
	if DataService and typeof(DataService.Estado) == "function" then
		local ok, valor = pcall(DataService.Estado, DataService, player)
		if ok then
			estado = valor
		end
	end
	-- DataService ya pone Saldo = Config.Economia.SaldoInicial en perfiles nuevos (§4); aquí solo se deja constancia.
	if estado == "nuevo" and #eco.Historial == 0 then
		table.insert(eco.Historial, { T = os.time(), Tipo = "Inicial", Monto = eco.Saldo, Detalle = "Saldo inicial de bienvenida" })
		self:_Marcar(player)
	end
	self:_Enviar(player, "Economia", self:_DatosEvento(eco, 0, "", "Sincronizacion"))
end

---------------------------------------------------------------------------------------------------
-- Registro interno de movimientos
---------------------------------------------------------------------------------------------------
function EconomyService:_DatosEvento(eco, delta, detalle, tipo)
	return {
		Sub = "Saldo",
		Saldo = eco.Saldo,
		Delta = delta,
		Detalle = detalle,
		Tipo = tipo,
		GanadoHoy = eco.GanadoHoy,
		LimiteDiario = self:LimiteDiario(),
		Simbolo = CFG.MonedaSimbolo or "◎",
	}
end

function EconomyService:_AgregarHistorial(eco, tipo, monto, detalle)
	table.insert(eco.Historial, { T = os.time(), Tipo = tipo, Monto = monto, Detalle = detalle })
	while #eco.Historial > self.MaxHistorial do
		table.remove(eco.Historial, 1)
	end
end

function EconomyService:_RegistrarTransaccion(player, userId, tipo, monto, saldo, detalle)
	self.TotalTx = self.TotalTx + 1
	self.IndiceTx = self.IndiceTx + 1
	if self.IndiceTx > self.TamanoTransacciones then
		self.IndiceTx = 1
	end
	local nombre = ""
	if typeof(player) == "Instance" then
		nombre = player.Name
	end
	self.BufferTx[self.IndiceTx] = {
		Id = self.TotalTx,
		T = os.time(),
		UserId = userId,
		Jugador = nombre,
		Tipo = tipo,
		Monto = monto,
		Saldo = saldo,
		Detalle = detalle,
	}
	local porTipo = self.Totales.PorTipo[tipo]
	if not porTipo then
		porTipo = { Cantidad = 0, Entradas = 0, Salidas = 0 }
		self.Totales.PorTipo[tipo] = porTipo
	end
	porTipo.Cantidad = porTipo.Cantidad + 1
	if monto >= 0 then
		porTipo.Entradas = porTipo.Entradas + monto
		self.Totales.Acreditado = self.Totales.Acreditado + monto
	else
		porTipo.Salidas = porTipo.Salidas - monto
		self.Totales.Debitado = self.Totales.Debitado - monto
	end
end

-- Aplica un movimiento ya validado (monto con signo). Devuelve el saldo nuevo.
function EconomyService:_Aplicar(player, userId, eco, tipo, monto, detalle)
	eco.Saldo = math.clamp(eco.Saldo + monto, 0, MAX_SALDO)
	self:_AgregarHistorial(eco, tipo, monto, detalle)
	self:_RegistrarTransaccion(player, userId, tipo, monto, eco.Saldo, detalle)
	if player then
		self:_Marcar(player)
		self:_Enviar(player, "Economia", self:_DatosEvento(eco, monto, detalle, tipo))
	end
	self.SaldoCambiado:Fire(player, eco.Saldo, monto, tipo, detalle)
	return eco.Saldo
end

---------------------------------------------------------------------------------------------------
-- API pública
---------------------------------------------------------------------------------------------------

-- Límite diario de créditos por jugador.
function EconomyService:LimiteDiario()
	return math.max(0, math.floor(tonumber(CFG.LimiteDiario) or 300))
end

-- Saldo actual del jugador (0 si el perfil aún no está cargado).
function EconomyService:Saldo(player)
	local eco = self:_Economia(player)
	if not eco then
		return 0
	end
	return eco.Saldo
end

-- ¿El perfil económico del jugador está disponible?
function EconomyService:Disponible(player)
	return self:_Economia(player) ~= nil
end

-- Acredita 'monto' al jugador respetando Config.Economia.LimiteDiario (salvo TiposSinLimite).
-- Si solo cabe una parte del monto en el límite, se acredita esa parte.
-- Devuelve ok, saldoOError, acreditado.
function EconomyService:Acreditar(player, monto, tipo, detalle)
	local objetivo, userId = resolver(player)
	if not userId then
		return false, "jugador_invalido", 0
	end
	local n = montoValido(monto)
	if not n or n <= 0 then
		return false, "monto_invalido", 0
	end
	local eco = self:_Economia(objetivo or userId)
	if not eco then
		return false, "perfil_no_cargado", 0
	end
	tipo = texto(tipo or "Recompensa", self.MaxTipoCaracteres)
	if tipo == "" then
		tipo = "Recompensa"
	end
	detalle = texto(detalle, self.MaxDetalleCaracteres)

	local acreditable = n
	if not self.TiposSinLimite[tipo] then
		local limite = self:LimiteDiario()
		local restante = math.max(0, limite - eco.GanadoHoy)
		if restante <= 0 then
			self.Totales.RechazosLimite = self.Totales.RechazosLimite + 1
			local hoy = claveDia()
			if self.LimiteAvisado[userId] ~= hoy then
				self.LimiteAvisado[userId] = hoy
				self:_Auditar(objetivo or userId, "LimiteDiario", "Alcanzado el límite diario de " .. limite .. " (" .. tipo .. ")")
				if objetivo then
					self:_Enviar(objetivo, "Notificacion", {
						Texto = "Has alcanzado el límite diario de " .. Format.Moneda(limite) .. ". Mañana podrás ganar más.",
						Nivel = "aviso",
						Duracion = 6,
					})
				end
			end
			return false, "limite_diario", 0
		end
		acreditable = math.min(n, restante)
		eco.GanadoHoy = eco.GanadoHoy + acreditable
	end
	local saldo = self:_Aplicar(objetivo, userId, eco, tipo, acreditable, detalle)
	return true, saldo, acreditable
end

-- Recompensa por clave de Config.Economia.Recompensas (Asistencia, Respuesta, ...). Devuelve como Acreditar.
function EconomyService:Recompensar(player, clave, detalle)
	local recompensas = CFG.Recompensas or {}
	local monto = tonumber(recompensas[clave])
	if not monto or monto <= 0 then
		return false, "recompensa_desconocida", 0
	end
	return self:Acreditar(player, monto, clave, detalle)
end

-- Debita 'monto' de forma atómica: bloqueo por jugador, comprobación de saldo y registro en un único paso.
-- Devuelve ok, saldoOError ("saldo_insuficiente" | "transaccion_en_curso" | "perfil_no_cargado" | ...).
function EconomyService:Debitar(player, monto, tipo, detalle)
	local objetivo, userId = resolver(player)
	if not userId then
		return false, "jugador_invalido"
	end
	local n = montoValido(monto)
	if not n then
		return false, "monto_invalido"
	end
	if self.EnTransaccion[userId] then
		self.Totales.RechazosBloqueo = self.Totales.RechazosBloqueo + 1
		self:_Auditar(objetivo or userId, "DebitoBloqueado", "Débito concurrente rechazado (" .. tostring(tipo) .. ", " .. n .. ")")
		return false, "transaccion_en_curso"
	end
	self.EnTransaccion[userId] = true
	local ok, resultado, extra = pcall(function()
		local eco = self:_Economia(objetivo or userId)
		if not eco then
			return false, "perfil_no_cargado"
		end
		if n == 0 then
			return true, eco.Saldo
		end
		if eco.Saldo < n then
			self.Totales.RechazosSaldo = self.Totales.RechazosSaldo + 1
			return false, "saldo_insuficiente"
		end
		local tipoTexto = texto(tipo or "Compra", self.MaxTipoCaracteres)
		if tipoTexto == "" then
			tipoTexto = "Compra"
		end
		local saldo = self:_Aplicar(objetivo, userId, eco, tipoTexto, -n, texto(detalle, self.MaxDetalleCaracteres))
		return true, saldo
	end)
	self.EnTransaccion[userId] = nil
	if not ok then
		warn(PREFIJO .. " Error en Debitar: " .. tostring(resultado))
		self:_Auditar(objetivo or userId, "ErrorDebito", tostring(resultado))
		return false, "error_interno"
	end
	return resultado, extra
end

-- ¿Hay un débito en curso para el jugador?
function EconomyService:EnTransaccionActiva(player)
	local _, userId = resolver(player)
	return userId ~= nil and self.EnTransaccion[userId] == true
end

-- Historial del jugador (copia, el más reciente primero). n opcional.
function EconomyService:Historial(player, n)
	local eco = self:_Economia(player)
	local lista = {}
	if not eco then
		return lista
	end
	local limite = math.floor(tonumber(n) or #eco.Historial)
	for i = #eco.Historial, 1, -1 do
		if #lista >= limite then
			break
		end
		table.insert(lista, copiarMovimiento(eco.Historial[i]))
	end
	return lista
end

-- Datos económicos del jugador para el cliente (StateSnapshot, panel de cafetería).
function EconomyService:Snapshot(player)
	local eco = self:_Economia(player)
	local base = {
		Saldo = 0,
		GanadoHoy = 0,
		LimiteDiario = self:LimiteDiario(),
		Simbolo = CFG.MonedaSimbolo or "◎",
		Nombre = CFG.MonedaNombre or "Monedas escolares",
		Disponible = eco ~= nil,
		Historial = {},
	}
	if eco then
		base.Saldo = eco.Saldo
		base.GanadoHoy = eco.GanadoHoy
		base.Historial = self:Historial(player, 10)
	end
	return base
end

-- Últimas n transacciones del servidor (copia, la más reciente primero; máx. TamanoTransacciones).
function EconomyService:Transacciones(n)
	local limite = math.clamp(math.floor(tonumber(n) or 50), 1, self.TamanoTransacciones)
	local lista = {}
	local disponibles = math.min(self.TotalTx, self.TamanoTransacciones)
	local indice = self.IndiceTx
	for _ = 1, math.min(limite, disponibles) do
		local tx = self.BufferTx[indice]
		if tx then
			table.insert(lista, {
				Id = tx.Id, T = tx.T, UserId = tx.UserId, Jugador = tx.Jugador, Tipo = tx.Tipo,
				Monto = tx.Monto, Saldo = tx.Saldo, Detalle = tx.Detalle,
			})
		end
		indice = indice - 1
		if indice < 1 then
			indice = self.TamanoTransacciones
		end
	end
	return lista
end

-- Resumen global para finanzas / dirección.
function EconomyService:ResumenGlobal()
	local circulante, jugadores = 0, 0
	for _, player in ipairs(Players:GetPlayers()) do
		local eco = self:_Economia(player)
		if eco then
			circulante = circulante + eco.Saldo
			jugadores = jugadores + 1
		end
	end
	local porTipo = {}
	for tipo, datos in pairs(self.Totales.PorTipo) do
		porTipo[tipo] = { Cantidad = datos.Cantidad, Entradas = datos.Entradas, Salidas = datos.Salidas }
	end
	local medio = 0
	if jugadores > 0 then
		medio = math.floor(circulante / jugadores + 0.5)
	end
	return {
		Moneda = CFG.MonedaNombre or "Monedas escolares",
		Simbolo = CFG.MonedaSimbolo or "◎",
		Transacciones = self.TotalTx,
		TotalAcreditado = self.Totales.Acreditado,
		TotalDebitado = self.Totales.Debitado,
		Neto = self.Totales.Acreditado - self.Totales.Debitado,
		Circulante = circulante,
		Jugadores = jugadores,
		SaldoMedio = medio,
		LimiteDiario = self:LimiteDiario(),
		RechazosSaldo = self.Totales.RechazosSaldo,
		RechazosLimite = self.Totales.RechazosLimite,
		RechazosBloqueo = self.Totales.RechazosBloqueo,
		PorTipo = porTipo,
		Desde = self.InicioUnix,
	}
end

return EconomyService
]=] }
FUENTES["ServerScriptService/ColegioRP/Services/FoodService"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ServerScriptService.ColegioRP.Services.FoodService
	Tipo: ModuleScript
	Comedor gratuito y cocina por pasos (docs/ARQUITECTURA.md §6, prueba P9). Lotes de raciones por jornada
	(Config.Comedor.RacionesPorLote x LotesPorJornada); reclamo gratuito (coste 0) con cooldown por jugador y solo
	en periodos ComidaGratis (o Config.Comedor.PermitirFueraDeHorario); cocina: receta activa de Catalogs.Recetas
	con sus Pasos en orden en las estaciones (Preparacion, Coccion, Emplatado), cada paso dura SegPorPaso y la
	receta terminada se entrega en la estación Entrega (añade sus raciones); Reposicion (comedor.reponer) añade un
	lote si quedan; NPC de servicio que repone al inicio de cada periodo ComidaGratis si no hay cocinero.
	Los ProximityPrompt (los de MapService o, si faltan, unos propios) se manejan aquí, en el servidor. Bandeja
	visual soldada a la mano durante 20 s. Handler del remoto FoodAction. Emite "Comida"
	{ Sub = "Estado" | "Paso" | "Reclamado" | "Lote" | "AbrirPanel" }.
]]

local Players = game:GetService("Players")

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RP = ReplicatedStorage:WaitForChild("ColegioRP")
local Shared = RP:WaitForChild("Shared")
local Config = require(Shared:WaitForChild("Config"))
local Catalogs = require(Shared:WaitForChild("Catalogs"))
local MapaLogico = require(Shared:WaitForChild("MapaLogico"))
local RoleDefinitions = require(Shared:WaitForChild("RoleDefinitions"))
local TimetableDefinitions = require(Shared:WaitForChild("TimetableDefinitions"))
local Util = Shared:WaitForChild("Util")
local Signal = require(Util:WaitForChild("Signal"))
local Maid = require(Util:WaitForChild("Maid"))
local Zones = require(Util:WaitForChild("Zones"))
local Format = require(Util:WaitForChild("Format"))

local FoodService = {}
FoodService.Nombre = "FoodService"

local PREFIJO = "[ColegioRP][FoodService]"
local CFG = Config.Comedor or {}

FoodService.RacionesPorLote = math.max(1, math.floor(tonumber(CFG.RacionesPorLote) or 40))
FoodService.LotesPorJornada = math.max(1, math.floor(tonumber(CFG.LotesPorJornada) or 3))
FoodService.CooldownReclamo = math.max(0, tonumber(CFG.CooldownReclamo) or 120)
FoodService.DistanciaMax = 12 -- studs hasta la ventana de servicio (reclamo por FoodAction y prompt)
-- studs hasta una estación de cocina (FoodAction "Paso"/"Entregar"/"Reponer" y prompts): Config.Distancias.Estacion.
FoodService.DistanciaEstacion = math.max(1, tonumber(Config.Distancias and Config.Distancias.Estacion) or 10)
FoodService.Tolerancia = 2 -- latencia y tamaño del personaje
FoodService.DuracionBandeja = 20 -- segundos que el jugador sostiene la bandeja
FoodService.InactividadRecetaSeg = 180 -- una receta sin actividad durante este tiempo se cancela
FoodService.CooldownReponerSeg = 5 -- entre reposiciones manuales del mismo jugador
FoodService.IntervaloPromptSeg = 0.4 -- antirrebote de ProximityPrompt por jugador
FoodService.ZonaCocina = "COCINA"
FoodService.MaxHistorial = 60

-- Estaciones de cocina en orden y acción RP de su prompt (atributo RPAccion).
local ORDEN_ESTACIONES = { "Preparacion", "Coccion", "Emplatado", "Entrega", "Reposicion" }
local ACCION_RP = { Preparacion = "Paso", Coccion = "Paso", Emplatado = "Paso", Entrega = "Entregar", Reposicion = "Reponer" }
local TEXTO_ACCION = { Preparacion = "Preparar", Coccion = "Cocinar", Emplatado = "Emplatar", Entrega = "Entregar", Reposicion = "Reponer" }

local MENSAJES = {
	cerrado = "El comedor solo sirve almuerzo gratis en el descanso y el almuerzo (ahora: %s).",
	cooldown = "Ya recibiste tu almuerzo. Podrás reclamar otro en %s.",
	sin_raciones = "No quedan raciones. Espera a que la cocina prepare o reponga un lote.",
	lejos_reclamo = "Acércate a la ventana de servicio del comedor para reclamar tu almuerzo.",
	lejos_estacion = "Acércate a la estación: %s.",
	lejos_cocina = "Debes estar dentro de la cocina.",
	sin_personaje = "Tu personaje no está disponible en este momento.",
	permiso_cocina = "Solo el personal de cocina puede usar esta estación.",
	permiso_reponer = "Solo el personal autorizado puede reponer raciones.",
	sin_receta = "No hay ninguna receta en preparación. Elige una en el panel de cocina.",
	receta_en_curso = "Ya hay una receta en preparación: %s.",
	sin_lotes = "La cocina ya usó los %d lotes de esta jornada.",
	paso_incorrecto = "Paso incorrecto: ahora toca «%s».",
	paso_en_curso = "Espera a que termine el paso actual (%s).",
	receta_lista = "La receta ya está lista: llévala al mostrador de entrega.",
	receta_no_lista = "La receta aún no está lista para entregar.",
	receta_invalida = "Receta desconocida.",
	estacion_invalida = "Estación desconocida.",
	accion_invalida = "Acción no válida.",
	reponer_espera = "Espera unos segundos antes de volver a reponer.",
	reponer_lleno = "Todavía quedan %d raciones; repón cuando bajen de %d.",
	error_interno = "No se pudo completar la acción. Inténtalo de nuevo.",
}

---------------------------------------------------------------------------------------------------
-- Utilidades
---------------------------------------------------------------------------------------------------
local function esJugador(player)
	return typeof(player) == "Instance" and player:IsA("Player")
end

local function posicionDe(player)
	if not esJugador(player) then
		return nil
	end
	local personaje = player.Character
	if not personaje then
		return nil
	end
	local raiz = personaje:FindFirstChild("HumanoidRootPart") or personaje.PrimaryPart
	if raiz and raiz:IsA("BasePart") then
		return raiz.Position
	end
	return nil
end

-- Posición mundial de una instancia (BasePart, Attachment o Model) o nil.
local function posicionInstancia(instancia)
	if typeof(instancia) ~= "Instance" or instancia.Parent == nil then
		return nil
	end
	if instancia:IsA("BasePart") then
		return instancia.Position
	end
	if instancia:IsA("Attachment") then
		return instancia.WorldPosition
	end
	if instancia:IsA("Model") then
		local ok, pivote = pcall(function()
			return instancia:GetPivot()
		end)
		if ok then
			return pivote.Position
		end
	end
	return nil
end

local function ahoraServidor()
	local ok, t = pcall(function()
		return workspace:GetServerTimeNow()
	end)
	if ok and typeof(t) == "number" then
		return t
	end
	return os.time()
end

local function nombreEstacion(nombre)
	return (Catalogs.Estaciones and Catalogs.Estaciones[nombre]) or tostring(nombre)
end

local function copiarArray(t)
	local copia = {}
	for i, v in ipairs(t or {}) do
		copia[i] = v
	end
	return copia
end

-- Devuelve false, codigo, mensaje formateado.
local function fallo(codigo, ...)
	local plantilla = MENSAJES[codigo] or MENSAJES.error_interno
	local ok, mensaje = pcall(string.format, plantilla, ...)
	if not ok then
		mensaje = plantilla
	end
	return false, codigo, mensaje
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function FoodService:Init(registro)
	self.registro = registro
	self.Raciones = 0
	self.LotesUsados = 0
	self.Receta = nil -- receta activa (ver IniciarReceta)
	self.TokenReceta = 0
	self.Menu = nil -- nombre del menú que se sirve
	self.IndiceMenu = 0
	self.Abierto = false
	self.EstadoJornada = nil
	self.UltimaNuevaJornada = -math.huge
	self.InicioJornadaLocal = os.clock()
	self.UltimoReclamo = {} -- userId -> os.clock() (se conserva aunque el jugador salga: evita reclamar al reconectar)
	self._ultimaPoda = os.clock() -- última limpieza de reclamos ya vencidos (evita que la tabla crezca sin límite)
	self.UltimoPrompt = {} -- userId -> os.clock()
	self.UltimaReposicion = {} -- userId -> os.clock()
	self.Bandejas = {} -- userId -> Model
	self.Puntos = { Estaciones = {}, Reclamo = nil }
	self.Historial = {}
	self.Estadisticas = { Reclamos = 0, LotesCocina = 0, LotesReposicion = 0, LotesNPC = 0, RacionesProducidas = 0, RecetasCanceladas = 0 }
	self.Cambiado = Signal.new() -- (snapshot)
	self.maidPrompts = Maid.new()
	self.Conexiones = {}
	self.Activo = true
	self._difusionPendiente = false
end

function FoodService:Start()
	local RemoteService = self:_S("RemoteService")
	if RemoteService and typeof(RemoteService.Registrar) == "function" then
		RemoteService:Registrar("FoodAction", function(player, datos)
			return self:ManejarAccion(player, datos)
		end)
	else
		warn(PREFIJO .. " RemoteService no disponible: FoodAction no tendrá handler.")
	end

	local okPrompts, errPrompts = pcall(self.EnlazarPrompts, self)
	if not okPrompts then
		warn(PREFIJO .. " No se pudieron enlazar los prompts de la cocina: " .. tostring(errPrompts))
	end
	local MapService = self:_S("MapService")
	if MapService and typeof(MapService.Construido) == "table" and typeof(MapService.Construido.Connect) == "function" then
		table.insert(self.Conexiones, MapService.Construido:Connect(function()
			task.defer(function()
				local ok, err = pcall(self.EnlazarPrompts, self)
				if not ok then
					warn(PREFIJO .. " Error al reenlazar los prompts: " .. tostring(err))
				end
			end)
		end))
	end

	local SchoolDay = self:_S("SchoolDayService")
	if SchoolDay then
		if typeof(SchoolDay.EstadoCambiado) == "table" and typeof(SchoolDay.EstadoCambiado.Connect) == "function" then
			table.insert(self.Conexiones, SchoolDay.EstadoCambiado:Connect(function()
				pcall(self._RevisarPeriodo, self)
			end))
		end
		if typeof(SchoolDay.JornadaTerminada) == "table" and typeof(SchoolDay.JornadaTerminada.Connect) == "function" then
			table.insert(self.Conexiones, SchoolDay.JornadaTerminada:Connect(function()
				pcall(self.NuevaJornada, self, "Fin de jornada")
			end))
		end
	end

	table.insert(self.Conexiones, Players.PlayerRemoving:Connect(function(player)
		local userId = player.UserId
		self.UltimoPrompt[userId] = nil
		self.UltimaReposicion[userId] = nil
		local bandeja = self.Bandejas[userId]
		self.Bandejas[userId] = nil
		if bandeja then
			pcall(function()
				bandeja:Destroy()
			end)
		end
	end))

	pcall(self._RevisarPeriodo, self)
	self:_ProgramarDifusion()

	task.spawn(function()
		while self.Activo do
			task.wait(1)
			local ok, err = pcall(self._Tick, self)
			if not ok then
				warn(PREFIJO .. " Error en el ciclo del comedor: " .. tostring(err))
			end
		end
	end)
end

function FoodService:_S(nombre)
	local registro = self.registro
	if typeof(registro) ~= "table" or typeof(registro.Get) ~= "function" then
		return nil
	end
	local ok, servicio = pcall(registro.Get, nombre)
	if ok and typeof(servicio) == "table" then
		return servicio
	end
	return nil
end

function FoodService:_Auditar(player, accion, detalle)
	local AuditLog = self:_S("AuditLogService")
	if AuditLog and typeof(AuditLog.Registrar) == "function" then
		pcall(AuditLog.Registrar, AuditLog, "Economia", player, accion, detalle)
	end
end

function FoodService:_Enviar(player, tipo, datos)
	local RemoteService = self:_S("RemoteService")
	if RemoteService and typeof(RemoteService.Enviar) == "function" and esJugador(player) then
		pcall(RemoteService.Enviar, RemoteService, player, tipo, datos)
	end
end

function FoodService:_Notificar(player, texto, nivel, duracion)
	self:_Enviar(player, "Notificacion", { Texto = texto, Nivel = nivel or "info", Duracion = duracion or 5 })
end

function FoodService:_EnviarATodos(tipo, datos)
	local RemoteService = self:_S("RemoteService")
	if RemoteService and typeof(RemoteService.EnviarATodos) == "function" then
		pcall(RemoteService.EnviarATodos, RemoteService, tipo, datos)
	end
end

-- Envía a los jugadores dentro de la cocina y además a los indicados en 'extra' (array de Players).
function FoodService:_EnviarCocina(tipo, datos, extra)
	local RemoteService = self:_S("RemoteService")
	if not RemoteService then
		return
	end
	local lista = {}
	local vistos = {}
	if typeof(RemoteService.JugadoresEnZona) == "function" then
		local ok, enZona = pcall(RemoteService.JugadoresEnZona, RemoteService, self.ZonaCocina)
		if ok and typeof(enZona) == "table" then
			for _, player in ipairs(enZona) do
				vistos[player] = true
				table.insert(lista, player)
			end
		end
	end
	for _, player in ipairs(extra or {}) do
		if esJugador(player) and not vistos[player] then
			vistos[player] = true
			table.insert(lista, player)
		end
	end
	for _, player in ipairs(lista) do
		self:_Enviar(player, tipo, datos)
	end
end

function FoodService:_RegistrarHistorial(tipo, detalle)
	table.insert(self.Historial, { T = os.time(), Tipo = tipo, Detalle = detalle })
	while #self.Historial > self.MaxHistorial do
		table.remove(self.Historial, 1)
	end
end

function FoodService:_Tiene(player, permiso)
	local RoleService = self:_S("RoleService")
	if RoleService and typeof(RoleService.Tiene) == "function" then
		local ok, tiene = pcall(RoleService.Tiene, RoleService, player, permiso)
		return ok and tiene == true
	end
	return esJugador(player) and RoleDefinitions.Tiene(player:GetAttribute("Cargo"), permiso)
end

function FoodService:_HayCocinero()
	local RoleService = self:_S("RoleService")
	if RoleService and typeof(RoleService.ConPermiso) == "function" then
		local ok, lista = pcall(RoleService.ConPermiso, RoleService, "cocina.operar")
		if ok and typeof(lista) == "table" then
			return #lista > 0
		end
	end
	for _, player in ipairs(Players:GetPlayers()) do
		if RoleDefinitions.Tiene(player:GetAttribute("Cargo"), "cocina.operar") then
			return true
		end
	end
	return false
end

---------------------------------------------------------------------------------------------------
-- Jornada y periodos
---------------------------------------------------------------------------------------------------
function FoodService:_HayJornada()
	local SchoolDay = self:_S("SchoolDayService")
	return SchoolDay ~= nil and typeof(SchoolDay.Estado) == "function"
end

function FoodService:_EstadoJornada()
	local SchoolDay = self:_S("SchoolDayService")
	if SchoolDay and typeof(SchoolDay.Estado) == "function" then
		local ok, estado = pcall(SchoolDay.Estado, SchoolDay)
		if ok and typeof(estado) == "string" then
			return estado
		end
	end
	return nil
end

function FoodService:_NombrePeriodo()
	local SchoolDay = self:_S("SchoolDayService")
	if SchoolDay and typeof(SchoolDay.Snapshot) == "function" then
		local ok, snap = pcall(SchoolDay.Snapshot, SchoolDay)
		if ok and typeof(snap) == "table" and typeof(snap.Nombre) == "string" then
			return snap.Nombre
		end
	end
	if self.EstadoJornada then
		return TimetableDefinitions.Nombre(self.EstadoJornada) or self.EstadoJornada
	end
	return "sin jornada"
end

-- ¿Se puede reclamar comida gratis ahora?
function FoodService:_CalcularAbierto(estado)
	if CFG.PermitirFueraDeHorario == true then
		return true
	end
	local SchoolDay = self:_S("SchoolDayService")
	if SchoolDay and typeof(SchoolDay.PermiteComidaGratis) == "function" then
		local ok, valor = pcall(SchoolDay.PermiteComidaGratis, SchoolDay)
		if ok then
			return valor == true
		end
	end
	if estado then
		return TimetableDefinitions.EsComidaGratis(estado) == true
	end
	-- Sin servicio de jornada el comedor no se bloquea por horario.
	return true
end

function FoodService:_RevisarPeriodo()
	local estado = self:_EstadoJornada()
	local abierto = self:_CalcularAbierto(estado)
	local cambio = false
	if estado ~= self.EstadoJornada then
		local anterior = self.EstadoJornada
		self.EstadoJornada = estado
		cambio = true
		if anterior ~= nil and estado == TimetableDefinitions.EstadoFinal then
			self:NuevaJornada("Reinicio de jornada")
		end
		if estado ~= nil and TimetableDefinitions.EsComidaGratis(estado) then
			self:_ServicioNPC("Inicio de " .. (TimetableDefinitions.Nombre(estado) or estado))
		end
	end
	if abierto ~= self.Abierto then
		self.Abierto = abierto
		cambio = true
	end
	if cambio then
		self:_ProgramarDifusion()
	end
end

-- NPC de servicio: si no hay cocinero conectado repone un lote al inicio de un periodo ComidaGratis.
function FoodService:_ServicioNPC(motivo)
	if CFG.NPCServicioSiNoHayCocinero == false then
		return false
	end
	if self:_HayCocinero() then
		return false
	end
	if self.Raciones >= self.RacionesPorLote then
		return false
	end
	local ok = self:_AgregarLote(self.RacionesPorLote, "NPC", nil, nil)
	if ok then
		self:_RegistrarHistorial("NPC", motivo or "Servicio automático")
	end
	return ok
end

function FoodService:_Tick()
	self:_RevisarPeriodo()
	-- Poda periódica de cooldowns vencidos (jugadores que ya se fueron incluidos).
	local ahora = os.clock()
	if ahora - self._ultimaPoda >= 60 then
		self._ultimaPoda = ahora
		for userId, instante in pairs(self.UltimoReclamo) do
			if ahora - instante >= self.CooldownReclamo then
				self.UltimoReclamo[userId] = nil
			end
		end
	end
	local receta = self.Receta
	if receta and not receta.PasoEnCurso and os.clock() - receta.UltimaActividad > self.InactividadRecetaSeg then
		self:_CancelarReceta("Receta abandonada por inactividad")
	end
	if not self:_HayJornada() then
		-- Sin SchoolDayService: los lotes se renuevan cada jornada teórica y el NPC atiende cuando se agotan.
		local total = tonumber(TimetableDefinitions.TotalJornadaSeg) or 1320
		if os.clock() - self.InicioJornadaLocal >= math.max(60, total) then
			self:NuevaJornada("Nueva jornada (sin servicio de jornada)")
		end
		if self.Raciones <= 0 then
			self:_ServicioNPC("Raciones agotadas")
		end
	end
end

-- Reinicia los lotes y las raciones de la jornada (fin de jornada / reinicio).
function FoodService:NuevaJornada(motivo)
	if os.clock() - self.UltimaNuevaJornada < 5 then
		return
	end
	self.UltimaNuevaJornada = os.clock()
	self.InicioJornadaLocal = os.clock()
	if self.Receta then
		self:_CancelarReceta("Fin de la jornada")
	end
	self.LotesUsados = 0
	self.Raciones = 0
	self.Menu = nil
	self:_RegistrarHistorial("Jornada", motivo or "Nueva jornada")
	self:_Auditar(nil, "ComedorNuevaJornada", motivo or "Nueva jornada")
	self:_ProgramarDifusion()
end

---------------------------------------------------------------------------------------------------
-- Lotes y raciones
---------------------------------------------------------------------------------------------------
function FoodService:_LotesRestantes()
	local reservado = 0
	if self.Receta then
		reservado = 1
	end
	return math.max(0, self.LotesPorJornada - self.LotesUsados - reservado)
end

function FoodService:_MaxRaciones()
	return self.RacionesPorLote * self.LotesPorJornada
end

-- Añade un lote. origen: "Cocina" (lote ya reservado por la receta), "Reposicion", "NPC" o "Admin" (sin límite).
function FoodService:_AgregarLote(cantidad, origen, menu, player)
	cantidad = tonumber(cantidad) or self.RacionesPorLote
	-- NaN / infinito (llamadas de otros servicios) se rechazan: math.min(max, NaN) llenaría el comedor.
	if cantidad ~= cantidad or cantidad == math.huge or cantidad == -math.huge then
		return false, "cantidad_invalida"
	end
	cantidad = math.floor(cantidad)
	if cantidad <= 0 then
		return false, "cantidad_invalida"
	end
	if origen ~= "Cocina" and origen ~= "Admin" and self:_LotesRestantes() <= 0 then
		return false, "sin_lotes"
	end
	if origen ~= "Admin" then
		self.LotesUsados = math.min(self.LotesPorJornada, self.LotesUsados + 1)
	end
	if not menu then
		local recetas = Catalogs.Recetas or {}
		if #recetas > 0 then
			self.IndiceMenu = (self.IndiceMenu % #recetas) + 1
			menu = recetas[self.IndiceMenu].Nombre
		else
			menu = "Menú del día"
		end
	end
	self.Menu = menu
	local anterior = self.Raciones
	self.Raciones = math.min(self:_MaxRaciones(), anterior + cantidad)
	-- Lo que realmente se añadió (el tope de la jornada recorta cantidades grandes).
	cantidad = math.max(0, self.Raciones - anterior)
	self.Estadisticas.RacionesProducidas = self.Estadisticas.RacionesProducidas + cantidad
	if origen == "Cocina" then
		self.Estadisticas.LotesCocina = self.Estadisticas.LotesCocina + 1
	elseif origen == "Reposicion" then
		self.Estadisticas.LotesReposicion = self.Estadisticas.LotesReposicion + 1
	elseif origen == "NPC" then
		self.Estadisticas.LotesNPC = self.Estadisticas.LotesNPC + 1
	end
	self:_RegistrarHistorial("Lote", origen .. ": +" .. cantidad .. " (" .. menu .. ")")
	self:_Auditar(player, "ComedorLote", origen .. " +" .. cantidad .. " raciones (" .. menu .. ") · lote " .. self.LotesUsados .. "/" .. self.LotesPorJornada)
	self:_EnviarATodos("Comida", {
		Sub = "Lote",
		Raciones = cantidad,
		RacionesDisponibles = self.Raciones,
		LoteActual = self.LotesUsados,
		LotesPorJornada = self.LotesPorJornada,
		Origen = origen,
		Menu = menu,
	})
	self:_ProgramarDifusion()
	return true, self.Raciones
end

-- API: añade 'cantidad' raciones (por defecto un lote) desde 'origen'. Devuelve ok, racionesOError.
function FoodService:Reponer(cantidad, origen)
	origen = tostring(origen or "Reposicion")
	if origen == "Cocina" then
		-- "Cocina" solo se usa con el lote reservado por una receta; desde fuera cuenta como reposición.
		origen = "Reposicion"
	end
	return self:_AgregarLote(cantidad or self.RacionesPorLote, origen, nil, nil)
end

---------------------------------------------------------------------------------------------------
-- Estado
---------------------------------------------------------------------------------------------------
function FoodService:_DatosReceta()
	local receta = self.Receta
	if not receta then
		return nil
	end
	local enCurso = nil
	if receta.PasoEnCurso then
		enCurso = {
			Estacion = receta.PasoEnCurso.Estacion,
			NombreEstacion = nombreEstacion(receta.PasoEnCurso.Estacion),
			FinServidor = receta.PasoEnCurso.FinServidor,
			Duracion = receta.PasoEnCurso.Duracion,
		}
	end
	return {
		Id = receta.Id,
		Nombre = receta.Nombre,
		Pasos = copiarArray(receta.Pasos),
		PasoActual = receta.Indice,
		Lista = receta.Lista,
		SegPorPaso = receta.SegPorPaso,
		Raciones = receta.Raciones,
		Cocinero = receta.CocineroNombre,
		PasoEnCurso = enCurso,
	}
end

function FoodService:_PasoEsperado()
	local receta = self.Receta
	if not receta then
		return nil
	end
	if receta.Lista then
		return "Entrega"
	end
	return receta.Pasos[receta.Indice]
end

-- Estado público del comedor (también en Snapshot y en el evento "Comida" Sub = "Estado").
function FoodService:Estado()
	local receta = self.Receta
	local npc = CFG.NPCServicioSiNoHayCocinero ~= false and not self:_HayCocinero()
	return {
		RacionesDisponibles = self.Raciones,
		LoteActual = self.LotesUsados,
		LotesPorJornada = self.LotesPorJornada,
		LotesRestantes = self:_LotesRestantes(),
		RacionesPorLote = self.RacionesPorLote,
		RecetaActiva = receta and receta.Id or nil,
		Receta = self:_DatosReceta(),
		PasoActual = receta and receta.Indice or 0,
		PasoEsperado = self:_PasoEsperado(),
		Cocinero = receta and receta.CocineroNombre or nil,
		Abierto = self.Abierto,
		EstadoJornada = self.EstadoJornada,
		Periodo = self:_NombrePeriodo(),
		Menu = self.Menu,
		ModoNPC = npc,
		CooldownReclamo = self.CooldownReclamo,
		HoraServidor = ahoraServidor(),
	}
end

function FoodService:Snapshot()
	local datos = self:Estado()
	datos.Estadisticas = {
		Reclamos = self.Estadisticas.Reclamos,
		LotesCocina = self.Estadisticas.LotesCocina,
		LotesReposicion = self.Estadisticas.LotesReposicion,
		LotesNPC = self.Estadisticas.LotesNPC,
		RacionesProducidas = self.Estadisticas.RacionesProducidas,
		RecetasCanceladas = self.Estadisticas.RecetasCanceladas,
	}
	return datos
end

-- Historial de eventos del comedor (copia, el más reciente primero).
function FoodService:HistorialEventos(n)
	local lista = {}
	local limite = math.floor(tonumber(n) or #self.Historial)
	for i = #self.Historial, 1, -1 do
		if #lista >= limite then
			break
		end
		local e = self.Historial[i]
		table.insert(lista, { T = e.T, Tipo = e.Tipo, Detalle = e.Detalle })
	end
	return lista
end

-- Segundos que faltan para que el jugador pueda volver a reclamar (0 = ya puede).
function FoodService:CooldownRestante(player)
	if not esJugador(player) then
		return 0
	end
	local ultimo = self.UltimoReclamo[player.UserId]
	if not ultimo then
		return 0
	end
	return math.max(0, self.CooldownReclamo - (os.clock() - ultimo))
end

-- Estado + datos personales del jugador (respuesta de FoodAction).
function FoodService:_DatosJugador(player)
	local datos = self:Estado()
	local restante = self:CooldownRestante(player)
	local puede, codigo = self:PuedeReclamar(player)
	local proximo = 0
	if restante > 0 then
		proximo = ahoraServidor() + restante
	end
	datos.Personal = {
		CooldownRestante = math.ceil(restante),
		ProximoReclamo = proximo,
		PuedeReclamar = puede,
		Motivo = codigo,
		EsCocina = self:_Tiene(player, "cocina.operar"),
		PuedeReponer = self:_Tiene(player, "comedor.reponer"),
	}
	return datos
end

function FoodService:_ProgramarDifusion()
	if self._difusionPendiente then
		return
	end
	self._difusionPendiente = true
	task.delay(0.5, function()
		self._difusionPendiente = false
		local ok, err = pcall(self._Difundir, self)
		if not ok then
			warn(PREFIJO .. " Error al difundir el estado: " .. tostring(err))
		end
	end)
end

function FoodService:_Difundir()
	local datos = self:Estado()
	datos.Sub = "Estado"
	self:_EnviarATodos("Comida", datos)
	self:_ActualizarPrompts()
	self.Cambiado:Fire(self:Estado())
end

---------------------------------------------------------------------------------------------------
-- Distancias
---------------------------------------------------------------------------------------------------
function FoodService:_PosicionEstacion(nombre)
	local punto = self.Puntos.Estaciones[nombre]
	local enMapa = punto and posicionInstancia(punto.Parte)
	if enMapa then
		return enMapa
	end
	local zona = MapaLogico.Zonas[self.ZonaCocina]
	if zona and typeof(zona.Estaciones) == "table" and typeof(zona.Estaciones[nombre]) == "Vector3" then
		return zona.Estaciones[nombre]
	end
	return nil
end

-- ¿El jugador está a <= DistanciaEstacion de la estación? Si la estación no tiene posición, basta con estar en la cocina.
function FoodService:_CercaDeEstacion(player, nombre, extra)
	local pos = posicionDe(player)
	if not pos then
		return false, "sin_personaje"
	end
	local objetivo = self:_PosicionEstacion(nombre)
	if not objetivo then
		if Zones.Contiene(self.ZonaCocina, pos) then
			return true
		end
		return false, "lejos_cocina"
	end
	local limite = self.DistanciaEstacion + self.Tolerancia + (extra or 0)
	if (pos - objetivo).Magnitude <= limite then
		return true
	end
	return false, "lejos_estacion"
end

function FoodService:_PosicionReclamo()
	local reclamo = self.Puntos.Reclamo
	local enMapa = reclamo and posicionInstancia(reclamo.Parte)
	if enMapa then
		return enMapa
	end
	local zona = MapaLogico.Zonas[self.ZonaCocina]
	if zona then
		if typeof(zona.FilaEstudiantes) == "table" and typeof(zona.FilaEstudiantes.Centro) == "Vector3" then
			return zona.FilaEstudiantes.Centro
		end
		if typeof(zona.Mostrador) == "table" and typeof(zona.Mostrador.Centro) == "Vector3" then
			return zona.Mostrador.Centro
		end
	end
	return nil
end

-- ¿Está en la fila / ventana de servicio? (a <= DistanciaMax del punto de reclamo o dentro de la caja de la fila)
function FoodService:_CercaDeReclamo(pos)
	if typeof(pos) ~= "Vector3" then
		return false
	end
	local limite = self.DistanciaMax + self.Tolerancia
	local objetivo = self:_PosicionReclamo()
	if objetivo and (pos - objetivo).Magnitude <= limite then
		return true
	end
	local zona = MapaLogico.Zonas[self.ZonaCocina]
	local fila = zona and zona.FilaEstudiantes
	if typeof(fila) == "table" and typeof(fila.Centro) == "Vector3" and typeof(fila.Tamano) == "Vector3" then
		local d = pos - fila.Centro
		local m = self.Tolerancia
		if math.abs(d.X) <= fila.Tamano.X / 2 + m and math.abs(d.Y) <= fila.Tamano.Y / 2 + m and math.abs(d.Z) <= fila.Tamano.Z / 2 + m then
			return true
		end
	end
	local mostrador = zona and zona.Mostrador
	if typeof(mostrador) == "table" and typeof(mostrador.Centro) == "Vector3" and (pos - mostrador.Centro).Magnitude <= limite then
		return true
	end
	return false
end

---------------------------------------------------------------------------------------------------
-- Reclamo de almuerzo (gratis)
---------------------------------------------------------------------------------------------------

-- ¿Puede reclamar ahora (sin mirar la distancia)? Devuelve ok, codigo, mensaje, restante.
function FoodService:PuedeReclamar(player)
	if not self.Abierto then
		local ok, codigo, mensaje = fallo("cerrado", self:_NombrePeriodo())
		return ok, codigo, mensaje, 0
	end
	local restante = self:CooldownRestante(player)
	if restante > 0 then
		local ok, codigo, mensaje = fallo("cooldown", Format.Tiempo(restante))
		return ok, codigo, mensaje, restante
	end
	if self.Raciones <= 0 then
		local ok, codigo, mensaje = fallo("sin_raciones")
		return ok, codigo, mensaje, 0
	end
	return true, nil, nil, 0
end

-- Reclamo gratuito (coste 0). desdeRemoto = true audita los rechazos por distancia.
-- Devuelve ok, codigo, mensaje.
function FoodService:Reclamar(player, desdeRemoto)
	if not esJugador(player) then
		return fallo("sin_personaje")
	end
	local pos = posicionDe(player)
	if not pos then
		return fallo("sin_personaje")
	end
	if not self:_CercaDeReclamo(pos) then
		if desdeRemoto then
			self:_Auditar(player, "ComedorRechazo", "distancia al punto de reclamo")
		end
		return fallo("lejos_reclamo")
	end
	-- Por si el periodo acaba de cambiar y el ciclo aún no lo vio.
	self.Abierto = self:_CalcularAbierto(self:_EstadoJornada())
	local puede, codigo, mensaje = self:PuedeReclamar(player)
	if not puede then
		return false, codigo, mensaje
	end
	self.Raciones = self.Raciones - 1
	self.UltimoReclamo[player.UserId] = os.clock()
	self.Estadisticas.Reclamos = self.Estadisticas.Reclamos + 1
	local menu = self.Menu or "Menú del día"
	local okBandeja, errBandeja = pcall(self._EntregarBandeja, self, player)
	if not okBandeja then
		warn(PREFIJO .. " No se pudo crear la bandeja: " .. tostring(errBandeja))
	end
	self:_Enviar(player, "Comida", {
		Sub = "Reclamado",
		Menu = menu,
		RacionesDisponibles = self.Raciones,
		Cooldown = self.CooldownReclamo,
		ProximoReclamo = ahoraServidor() + self.CooldownReclamo,
		DuracionBandeja = self.DuracionBandeja,
	})
	self:_Notificar(player, "¡Buen provecho! Hoy hay: " .. menu .. ".", "exito", 5)
	self:_ProgramarDifusion()
	return true
end

-- Bandeja visual (Model "ColegioRP_Bandeja") soldada a la mano derecha durante DuracionBandeja s.
local function parteBandeja(nombre, tamano, color, material)
	local parte = Instance.new("Part")
	parte.Name = nombre
	parte.Size = tamano
	parte.Color = color
	parte.Material = material or Enum.Material.SmoothPlastic
	parte.Anchored = false
	parte.CanCollide = false
	parte.CanTouch = false
	parte.CanQuery = false
	parte.CastShadow = false
	parte.Massless = true
	parte.TopSurface = Enum.SurfaceType.Smooth
	parte.BottomSurface = Enum.SurfaceType.Smooth
	return parte
end

function FoodService:_EntregarBandeja(player)
	local personaje = player.Character
	if not personaje then
		return
	end
	local mano = personaje:FindFirstChild("RightHand") or personaje:FindFirstChild("Right Arm")
	if not mano or not mano:IsA("BasePart") then
		return
	end
	local userId = player.UserId
	local previa = self.Bandejas[userId]
	if previa then
		self.Bandejas[userId] = nil
		pcall(function()
			previa:Destroy()
		end)
	end

	local desplazamiento = CFrame.new(0, -0.15, -0.95)
	if mano.Name == "Right Arm" then
		desplazamiento = CFrame.new(0, -1.05, -0.9)
	end

	local modelo = Instance.new("Model")
	modelo.Name = "ColegioRP_Bandeja"
	local base = parteBandeja("Bandeja", Vector3.new(2, 0.14, 1.4), Color3.fromRGB(196, 30, 36), Enum.Material.SmoothPlastic)
	local cframeBase = mano.CFrame * desplazamiento
	base.CFrame = cframeBase
	base.Parent = modelo

	local plato = parteBandeja("Plato", Vector3.new(0.1, 1.1, 1.1), Color3.fromRGB(245, 245, 245), Enum.Material.SmoothPlastic)
	plato.Shape = Enum.PartType.Cylinder
	plato.CFrame = cframeBase * CFrame.new(-0.4, 0.12, 0) * CFrame.Angles(0, 0, math.rad(90))
	plato.Parent = modelo

	local comida = parteBandeja("Comida", Vector3.new(0.7, 0.22, 0.7), Color3.fromRGB(230, 180, 60), Enum.Material.Sand)
	comida.CFrame = cframeBase * CFrame.new(-0.4, 0.27, 0)
	comida.Parent = modelo

	local vaso = parteBandeja("Vaso", Vector3.new(0.5, 0.35, 0.35), Color3.fromRGB(246, 160, 40), Enum.Material.Glass)
	vaso.Shape = Enum.PartType.Cylinder
	vaso.Transparency = 0.2
	vaso.CFrame = cframeBase * CFrame.new(0.6, 0.32, 0.2) * CFrame.Angles(0, 0, math.rad(90))
	vaso.Parent = modelo

	for _, parte in ipairs({ plato, comida, vaso }) do
		local union = Instance.new("WeldConstraint")
		union.Part0 = base
		union.Part1 = parte
		union.Parent = base
	end
	local soldadura = Instance.new("Weld")
	soldadura.Name = "SoldaduraMano"
	soldadura.Part0 = mano
	soldadura.Part1 = base
	soldadura.C0 = desplazamiento
	soldadura.Parent = base

	modelo.PrimaryPart = base
	modelo:SetAttribute("ColegioRP", true)
	modelo.Parent = personaje
	self.Bandejas[userId] = modelo

	task.delay(self.DuracionBandeja, function()
		if self.Bandejas[userId] == modelo then
			self.Bandejas[userId] = nil
		end
		pcall(function()
			modelo:Destroy()
		end)
	end)
end

---------------------------------------------------------------------------------------------------
-- Cocina: recetas por pasos
---------------------------------------------------------------------------------------------------
function FoodService:_SiguienteReceta()
	local recetas = Catalogs.Recetas or {}
	if #recetas == 0 then
		return nil
	end
	return recetas[(self.IndiceMenu % #recetas) + 1]
end

-- Inicia una receta (cocina.operar). Devuelve ok, codigo, mensaje.
function FoodService:IniciarReceta(player, recetaId)
	if not self:_Tiene(player, "cocina.operar") then
		return fallo("permiso_cocina")
	end
	if self.Receta then
		return fallo("receta_en_curso", self.Receta.Nombre)
	end
	if self:_LotesRestantes() <= 0 then
		return fallo("sin_lotes", self.LotesPorJornada)
	end
	local receta = nil
	if recetaId ~= nil then
		receta = Catalogs.Receta(recetaId)
	else
		receta = self:_SiguienteReceta()
	end
	if not receta or typeof(receta.Pasos) ~= "table" or #receta.Pasos == 0 then
		return fallo("receta_invalida")
	end
	local pos = posicionDe(player)
	if not pos then
		return fallo("sin_personaje")
	end
	if not Zones.Contiene(self.ZonaCocina, pos) then
		local cerca = self:_CercaDeEstacion(player, receta.Pasos[1])
		if not cerca then
			return fallo("lejos_cocina")
		end
	end
	local pasos = {}
	for _, paso in ipairs(receta.Pasos) do
		if typeof(paso) == "string" and Catalogs.Estaciones and Catalogs.Estaciones[paso] then
			table.insert(pasos, paso)
		end
	end
	if #pasos == 0 then
		return fallo("receta_invalida")
	end
	self.TokenReceta = self.TokenReceta + 1
	self.Receta = {
		Token = self.TokenReceta,
		Id = receta.Id,
		Nombre = receta.Nombre or receta.Id,
		Pasos = pasos,
		Indice = 1,
		Lista = false,
		SegPorPaso = math.clamp(tonumber(receta.SegPorPaso) or 6, 1, 60),
		Raciones = math.max(1, math.floor(tonumber(receta.Raciones) or self.RacionesPorLote)),
		CocineroUserId = player.UserId,
		CocineroNombre = player.DisplayName,
		IniciadaEn = os.clock(),
		UltimaActividad = os.clock(),
		PasoEnCurso = nil,
	}
	self:_RegistrarHistorial("Receta", player.Name .. " inicia " .. self.Receta.Nombre)
	self:_Auditar(player, "RecetaIniciada", self.Receta.Nombre)
	self:_Notificar(player, "Receta iniciada: " .. self.Receta.Nombre .. ". Primer paso: " .. nombreEstacion(pasos[1]) .. ".", "info", 5)
	self:_ProgramarDifusion()
	return true
end

-- Ejecuta el paso de la estación indicada (debe ser el siguiente de la receta). Devuelve ok, codigo, mensaje.
function FoodService:Paso(player, estacion)
	if not self:_Tiene(player, "cocina.operar") then
		return fallo("permiso_cocina")
	end
	local receta = self.Receta
	if not receta then
		return fallo("sin_receta")
	end
	if receta.Lista then
		if estacion == nil or estacion == "Entrega" then
			return self:Entregar(player)
		end
		return fallo("receta_lista")
	end
	if receta.PasoEnCurso then
		return fallo("paso_en_curso", nombreEstacion(receta.PasoEnCurso.Estacion))
	end
	local esperado = receta.Pasos[receta.Indice]
	if estacion == nil then
		estacion = esperado
	end
	if typeof(estacion) ~= "string" or not (Catalogs.Estaciones and Catalogs.Estaciones[estacion]) then
		return fallo("estacion_invalida")
	end
	if estacion ~= esperado then
		return fallo("paso_incorrecto", nombreEstacion(esperado))
	end
	local cerca, codigo = self:_CercaDeEstacion(player, estacion)
	if not cerca then
		if codigo == "lejos_estacion" then
			return fallo("lejos_estacion", nombreEstacion(estacion))
		end
		return fallo(codigo or "lejos_cocina")
	end
	local duracion = receta.SegPorPaso
	receta.PasoEnCurso = {
		Estacion = estacion,
		UserId = player.UserId,
		Inicio = os.clock(),
		Duracion = duracion,
		FinServidor = ahoraServidor() + duracion,
	}
	receta.UltimaActividad = os.clock()
	self:_EnviarCocina("Comida", {
		Sub = "Paso",
		Fase = "Inicio",
		RecetaId = receta.Id,
		RecetaNombre = receta.Nombre,
		Estacion = estacion,
		NombreEstacion = nombreEstacion(estacion),
		Indice = receta.Indice,
		Total = #receta.Pasos,
		Duracion = duracion,
		FinServidor = receta.PasoEnCurso.FinServidor,
		Cocinero = player.DisplayName,
	}, { player })
	local token = receta.Token
	task.delay(duracion, function()
		local ok, err = pcall(self._TerminarPaso, self, token, estacion, player)
		if not ok then
			warn(PREFIJO .. " Error al terminar el paso: " .. tostring(err))
		end
	end)
	self:_ProgramarDifusion()
	return true
end

function FoodService:_TerminarPaso(token, estacion, player)
	local receta = self.Receta
	if not receta or receta.Token ~= token or not receta.PasoEnCurso or receta.PasoEnCurso.Estacion ~= estacion then
		return
	end
	receta.PasoEnCurso = nil
	receta.UltimaActividad = os.clock()
	local base = {
		Sub = "Paso",
		RecetaId = receta.Id,
		RecetaNombre = receta.Nombre,
		Estacion = estacion,
		NombreEstacion = nombreEstacion(estacion),
		Indice = receta.Indice,
		Total = #receta.Pasos,
	}
	-- El cocinero debe seguir junto a la estación y con su cargo para completar el paso.
	local sigue = player.Parent ~= nil and self:_Tiene(player, "cocina.operar") and self:_CercaDeEstacion(player, estacion, 4)
	if not sigue then
		base.Fase = "Cancelado"
		base.Motivo = "Te alejaste de la estación antes de terminar el paso."
		self:_EnviarCocina("Comida", base, { player })
		self:_ProgramarDifusion()
		return
	end
	base.Fase = "Completado"
	self:_EnviarCocina("Comida", base, { player })
	receta.Indice = receta.Indice + 1
	if receta.Indice > #receta.Pasos then
		if receta.Pasos[#receta.Pasos] == "Entrega" then
			self:_CompletarReceta(player)
			return
		end
		receta.Lista = true
		self:_Notificar(player, "¡" .. receta.Nombre .. " está lista! Llévala al " .. string.lower(nombreEstacion("Entrega")) .. ".", "exito", 6)
	end
	self:_ProgramarDifusion()
end

-- Entrega la receta terminada en el mostrador: añade sus raciones. Devuelve ok, codigo, mensaje.
function FoodService:Entregar(player)
	if not self:_Tiene(player, "cocina.operar") then
		return fallo("permiso_cocina")
	end
	local receta = self.Receta
	if not receta then
		return fallo("sin_receta")
	end
	if not receta.Lista then
		if receta.Pasos[receta.Indice] == "Entrega" then
			return self:Paso(player, "Entrega")
		end
		return fallo("receta_no_lista")
	end
	local cerca, codigo = self:_CercaDeEstacion(player, "Entrega")
	if not cerca then
		if codigo == "lejos_estacion" then
			return fallo("lejos_estacion", nombreEstacion("Entrega"))
		end
		return fallo(codigo or "lejos_cocina")
	end
	self:_CompletarReceta(player)
	return true
end

function FoodService:_CompletarReceta(player)
	local receta = self.Receta
	if not receta then
		return
	end
	self.Receta = nil
	local ok = self:_AgregarLote(receta.Raciones, "Cocina", receta.Nombre, player)
	if ok then
		self:_RegistrarHistorial("Receta", "Entregada: " .. receta.Nombre)
		if esJugador(player) then
			self:_Notificar(player, "Entregaste " .. receta.Nombre .. ": +" .. receta.Raciones .. " raciones en el comedor.", "exito", 5)
		end
	end
	self:_ProgramarDifusion()
end

function FoodService:_CancelarReceta(motivo)
	local receta = self.Receta
	if not receta then
		return
	end
	self.Receta = nil
	self.Estadisticas.RecetasCanceladas = self.Estadisticas.RecetasCanceladas + 1
	self:_RegistrarHistorial("Receta", "Cancelada: " .. receta.Nombre .. " (" .. tostring(motivo) .. ")")
	self:_Auditar(nil, "RecetaCancelada", receta.Nombre .. ": " .. tostring(motivo))
	local cocinero = Players:GetPlayerByUserId(receta.CocineroUserId)
	if cocinero then
		self:_Notificar(cocinero, "Se canceló la receta " .. receta.Nombre .. ": " .. tostring(motivo) .. ".", "aviso", 6)
	end
	self:_ProgramarDifusion()
end

-- Reposición manual desde los congeladores (comedor.reponer). Devuelve ok, codigo, mensaje.
function FoodService:ReponerPorJugador(player)
	if not self:_Tiene(player, "comedor.reponer") then
		return fallo("permiso_reponer")
	end
	local cerca, codigo = self:_CercaDeEstacion(player, "Reposicion")
	if not cerca then
		if codigo == "lejos_estacion" then
			return fallo("lejos_estacion", nombreEstacion("Reposicion"))
		end
		return fallo(codigo or "lejos_cocina")
	end
	local ultimo = self.UltimaReposicion[player.UserId]
	if ultimo and os.clock() - ultimo < self.CooldownReponerSeg then
		return fallo("reponer_espera")
	end
	if self.Raciones >= self.RacionesPorLote then
		return fallo("reponer_lleno", self.Raciones, self.RacionesPorLote)
	end
	if self:_LotesRestantes() <= 0 then
		return fallo("sin_lotes", self.LotesPorJornada)
	end
	self.UltimaReposicion[player.UserId] = os.clock()
	local ok = self:_AgregarLote(self.RacionesPorLote, "Reposicion", nil, player)
	if not ok then
		return fallo("sin_lotes", self.LotesPorJornada)
	end
	self:_Notificar(player, "Repusiste un lote: +" .. self.RacionesPorLote .. " raciones.", "exito", 5)
	return true
end

---------------------------------------------------------------------------------------------------
-- Remoto FoodAction
---------------------------------------------------------------------------------------------------
local CODIGOS_AUDITADOS = { lejos_estacion = true, lejos_cocina = true, lejos_reclamo = true, permiso_cocina = true, permiso_reponer = true, estacion_invalida = true, receta_invalida = true }

function FoodService:ManejarAccion(player, datos)
	local accion = datos.Accion
	if accion == "Estado" then
		return { ok = true, datos = self:_DatosJugador(player) }
	end
	local ok, codigo, mensaje = false, "accion_invalida", MENSAJES.accion_invalida
	if accion == "Reclamar" then
		ok, codigo, mensaje = self:Reclamar(player, true)
	elseif accion == "IniciarReceta" then
		ok, codigo, mensaje = self:IniciarReceta(player, datos.RecetaId)
	elseif accion == "Paso" then
		ok, codigo, mensaje = self:Paso(player, datos.Estacion)
	elseif accion == "Entregar" then
		ok, codigo, mensaje = self:Entregar(player)
	elseif accion == "Reponer" then
		ok, codigo, mensaje = self:ReponerPorJugador(player)
	end
	if ok then
		return { ok = true, datos = self:_DatosJugador(player) }
	end
	if CODIGOS_AUDITADOS[codigo] and accion ~= "Reclamar" then
		self:_Auditar(player, "FoodAction", tostring(accion) .. " rechazado: " .. tostring(codigo))
	end
	local respuesta = self:_DatosJugador(player)
	respuesta.Codigo = codigo
	return { ok = false, error = mensaje or MENSAJES.error_interno, datos = respuesta }
end

---------------------------------------------------------------------------------------------------
-- ProximityPrompts (manejados en el servidor)
---------------------------------------------------------------------------------------------------
function FoodService:_PromptPermitido(player)
	if not esJugador(player) then
		return false
	end
	local ahora = os.clock()
	local ultimo = self.UltimoPrompt[player.UserId]
	if ultimo and ahora - ultimo < self.IntervaloPromptSeg then
		return false
	end
	self.UltimoPrompt[player.UserId] = ahora
	return true
end

function FoodService:_AlActivarEstacion(player, nombre)
	if not self:_PromptPermitido(player) then
		return
	end
	local permiso = "cocina.operar"
	if nombre == "Reposicion" then
		permiso = "comedor.reponer"
	end
	if not self:_Tiene(player, permiso) then
		if nombre == "Reposicion" then
			self:_Notificar(player, MENSAJES.permiso_reponer, "aviso", 4)
		else
			self:_Notificar(player, MENSAJES.permiso_cocina, "aviso", 4)
		end
		return
	end
	local ok, codigo, mensaje = true, nil, nil
	if nombre == "Reposicion" then
		ok, codigo, mensaje = self:ReponerPorJugador(player)
	elseif not self.Receta then
		-- Sin receta activa: el cliente abre el panel de cocina para elegir una.
		self:_Enviar(player, "Comida", { Sub = "AbrirPanel", Seccion = "Cocina" })
		self:_Notificar(player, MENSAJES.sin_receta, "info", 5)
		return
	elseif nombre == "Entrega" then
		ok, codigo, mensaje = self:Entregar(player)
	else
		ok, codigo, mensaje = self:Paso(player, nombre)
		if ok then
			self:_Notificar(player, nombreEstacion(nombre) .. ": en curso…", "info", 3)
		end
	end
	if not ok and mensaje then
		self:_Notificar(player, mensaje, "aviso", 5)
	end
end

function FoodService:_AlActivarReclamo(player)
	if not self:_PromptPermitido(player) then
		return
	end
	local ok, _, mensaje = self:Reclamar(player, false)
	if not ok and mensaje then
		self:_Notificar(player, mensaje, "aviso", 5)
	end
end

-- Busca los prompts de la cocina creados por MapService. Devuelve { Estaciones = {nombre = {Parte, Prompt}}, Reclamo }.
function FoodService:_BuscarPrompts()
	local resultado = { Estaciones = {}, Reclamo = nil }
	local MapService = self:_S("MapService")
	if MapService and typeof(MapService.Cocina) == "function" then
		local ok, info = pcall(MapService.Cocina, MapService)
		if ok and typeof(info) == "table" then
			for nombre, prompt in pairs(info.Prompts or {}) do
				local parte = (info.Estaciones or {})[nombre]
				if typeof(prompt) == "Instance" and prompt.Parent ~= nil then
					resultado.Estaciones[nombre] = { Parte = parte or prompt.Parent, Prompt = prompt }
				end
			end
			if typeof(info.ReclamoPrompt) == "Instance" and info.ReclamoPrompt.Parent ~= nil then
				resultado.Reclamo = { Parte = info.Reclamo or info.ReclamoPrompt.Parent, Prompt = info.ReclamoPrompt }
			end
		end
	end
	-- Respaldo: búsqueda por atributos en Workspace.ColegioRP_Mapa.Cocina.
	if next(resultado.Estaciones) == nil or resultado.Reclamo == nil then
		local carpeta = nil
		if MapService and typeof(MapService.Carpeta) == "function" then
			local ok, valor = pcall(MapService.Carpeta, MapService, "Cocina")
			if ok and typeof(valor) == "Instance" then
				carpeta = valor
			end
		end
		if not carpeta then
			local raiz = workspace:FindFirstChild((Config.Nombres and Config.Nombres.CarpetaMapa) or "ColegioRP_Mapa")
			carpeta = raiz and raiz:FindFirstChild("Cocina")
		end
		if carpeta then
			for _, d in ipairs(carpeta:GetDescendants()) do
				if d:IsA("ProximityPrompt") then
					local tipo = d:GetAttribute("RPTipo")
					if tipo == "Cocina" then
						local nombre = d:GetAttribute("RPId") or (d.Parent and d.Parent.Name)
						if typeof(nombre) == "string" and not resultado.Estaciones[nombre] then
							resultado.Estaciones[nombre] = { Parte = d.Parent, Prompt = d }
						end
					elseif tipo == "Comida" and d:GetAttribute("RPAccion") == "Reclamar" and not resultado.Reclamo then
						resultado.Reclamo = { Parte = d.Parent, Prompt = d }
					end
				end
			end
		end
	end
	return resultado
end

-- Carpeta donde crear prompts propios si el mapa no los tiene.
function FoodService:_CarpetaPropia()
	local MapService = self:_S("MapService")
	if MapService and typeof(MapService.Carpeta) == "function" then
		local ok, carpeta = pcall(MapService.Carpeta, MapService, "Cocina")
		if ok and typeof(carpeta) == "Instance" and carpeta.Parent ~= nil then
			return carpeta, false
		end
	end
	local carpeta = Instance.new("Folder")
	carpeta.Name = "ColegioRP_Comedor"
	carpeta.Parent = workspace
	self.maidPrompts:GiveTask(carpeta)
	return carpeta, true
end

local function nuevoMarcador(nombre, posicion, padre)
	local parte = Instance.new("Part")
	parte.Name = nombre
	parte.Size = Vector3.new(2, 2, 2)
	parte.CFrame = CFrame.new(posicion)
	parte.Anchored = true
	parte.CanCollide = false
	parte.CanQuery = false
	parte.CanTouch = false
	parte.CastShadow = false
	parte.Transparency = 1
	parte.Parent = padre
	return parte
end

local function nuevoPrompt(parte, accion, objeto, distancia, espera)
	local prompt = Instance.new("ProximityPrompt")
	prompt.Name = "ColegioRP_Prompt"
	prompt.ActionText = accion
	prompt.ObjectText = objeto
	prompt.MaxActivationDistance = distancia
	prompt.HoldDuration = espera
	prompt.RequiresLineOfSight = false
	prompt.ClickablePrompt = true
	prompt.Parent = parte
	return prompt
end

-- Crea los prompts que falten en los puntos de MapaLogico.Zonas.COCINA.
function FoodService:_CrearFaltantes(puntos)
	local zona = MapaLogico.Zonas[self.ZonaCocina]
	if not zona then
		return
	end
	local carpeta = nil
	local function asegurarCarpeta()
		if not carpeta then
			carpeta = self:_CarpetaPropia()
		end
		return carpeta
	end
	if typeof(zona.Estaciones) == "table" then
		for _, nombre in ipairs(ORDEN_ESTACIONES) do
			local punto = zona.Estaciones[nombre]
			if typeof(punto) == "Vector3" and not puntos.Estaciones[nombre] then
				local parte = nuevoMarcador(nombre, punto, asegurarCarpeta())
				self.maidPrompts:GiveTask(parte)
				local prompt = nuevoPrompt(parte, TEXTO_ACCION[nombre] or "Usar", "Cocina", 8, 0.5)
				prompt:SetAttribute("RPTipo", "Cocina")
				prompt:SetAttribute("RPId", nombre)
				puntos.Estaciones[nombre] = { Parte = parte, Prompt = prompt }
			end
		end
	end
	if not puntos.Reclamo then
		local centro = self:_PosicionReclamo()
		if centro then
			local parte = nuevoMarcador("Reclamo", centro, asegurarCarpeta())
			self.maidPrompts:GiveTask(parte)
			local prompt = nuevoPrompt(parte, "Reclamar almuerzo", "Comedor", 12, 0.3)
			prompt:SetAttribute("RPTipo", "Comida")
			prompt:SetAttribute("RPAccion", "Reclamar")
			puntos.Reclamo = { Parte = parte, Prompt = prompt }
		end
	end
end

-- Enlaza (o reenlaza tras reconstruir el mapa) los Triggered de las estaciones y del punto de reclamo.
function FoodService:EnlazarPrompts()
	self.maidPrompts:DoCleaning()
	local puntos = self:_BuscarPrompts()
	self:_CrearFaltantes(puntos)
	self.Puntos = puntos
	for nombre, punto in pairs(puntos.Estaciones) do
		local prompt = punto.Prompt
		if prompt:GetAttribute("RPTipo") == nil then
			prompt:SetAttribute("RPTipo", "Cocina")
		end
		if prompt:GetAttribute("RPId") == nil then
			prompt:SetAttribute("RPId", nombre)
		end
		if prompt:GetAttribute("RPAccion") == nil then
			prompt:SetAttribute("RPAccion", ACCION_RP[nombre] or "Paso")
		end
		self.maidPrompts:GiveTask(prompt.Triggered:Connect(function(player)
			local ok, err = pcall(self._AlActivarEstacion, self, player, nombre)
			if not ok then
				warn(PREFIJO .. " Error en la estación " .. tostring(nombre) .. ": " .. tostring(err))
			end
		end))
	end
	if puntos.Reclamo then
		local prompt = puntos.Reclamo.Prompt
		prompt:SetAttribute("RPTipo", "Comida")
		prompt:SetAttribute("RPAccion", "Reclamar")
		if prompt:GetAttribute("RPId") == nil then
			prompt:SetAttribute("RPId", "Reclamo")
		end
		self.maidPrompts:GiveTask(prompt.Triggered:Connect(function(player)
			local ok, err = pcall(self._AlActivarReclamo, self, player)
			if not ok then
				warn(PREFIJO .. " Error en el reclamo: " .. tostring(err))
			end
		end))
	else
		warn(PREFIJO .. " Sin punto de reclamo de almuerzo (MapaLogico.Zonas.COCINA sin FilaEstudiantes ni Mostrador).")
	end
	self:_ActualizarPrompts()
end

-- Textos de los prompts según el estado (los ve todo el mundo; el cliente oculta las estaciones a quien no cocina).
function FoodService:_ActualizarPrompts()
	local reclamo = self.Puntos and self.Puntos.Reclamo
	if reclamo and reclamo.Prompt and reclamo.Prompt.Parent ~= nil then
		local texto = "Comedor · " .. Format.Plural(self.Raciones, "ración", "raciones")
		if not self.Abierto then
			texto = "Comedor cerrado"
		elseif self.Raciones <= 0 then
			texto = "Comedor · sin raciones"
		end
		pcall(function()
			reclamo.Prompt.ObjectText = texto
		end)
	end
	local esperado = self:_PasoEsperado()
	for nombre, punto in pairs((self.Puntos and self.Puntos.Estaciones) or {}) do
		if punto.Prompt and punto.Prompt.Parent ~= nil then
			local texto = "Cocina"
			if nombre == esperado then
				texto = "Cocina · siguiente paso"
			end
			pcall(function()
				punto.Prompt.ObjectText = texto
			end)
		end
	end
end

return FoodService
]=] }
FUENTES["ServerScriptService/ColegioRP/Services/FootballService"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ServerScriptService.ColegioRP.Services.FootballService
	Tipo: ModuleScript
	Cancha y fútbol (docs/ARQUITECTURA.md §6, prueba P11). Usa el balón, los arcos y el marcador que crea
	MapService en Workspace.ColegioRP_Mapa.Futbol (si faltan, los crea desde MapaLogico.Zonas.CANCHA.Futbol).
	El balón es una esfera física con autoridad del servidor (SetNetworkOwner(nil)) que solo se simula cuando hay
	al menos un jugador en la zona CANCHA (bucle de presencia de 1 s); con la cancha vacía queda anclado en el
	centro y no corre el bucle de goles. FootballKick valida personaje vivo, distancia, cooldown, dirección y
	fuerza antes de aplicar AssemblyLinearVelocity. Goles por volumen de arco (muestreo cada 0.1 s con barrido
	del segmento recorrido), rescate por límites o velocidad anómala, equipos A/B por atributo EquipoFutbol del
	Player, partido con reloj, marcador físico (SurfaceGui) y recompensa Economia.Recompensas.Partido.
	Convención: el equipo A defiende ArcoA y el B defiende ArcoB; un balón dentro de ArcoA es gol del equipo B.
]]

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local RP = ReplicatedStorage:WaitForChild("ColegioRP")
local Shared = RP:WaitForChild("Shared")
local Config = require(Shared:WaitForChild("Config"))
local MapaLogico = require(Shared:WaitForChild("MapaLogico"))
local RemoteContracts = require(Shared:WaitForChild("RemoteContracts"))
local UITheme = require(Shared:WaitForChild("UITheme"))
local Util = Shared:WaitForChild("Util")
local Zones = require(Util:WaitForChild("Zones"))
local Signal = require(Util:WaitForChild("Signal"))
local Format = require(Util:WaitForChild("Format"))

local FootballService = {}
FootballService.Nombre = "FootballService"

local PREFIJO = "[ColegioRP][FootballService]"
local CFG = Config.Futbol or {}
local ECO = Config.Economia or {}
local EQUIPOS = { "A", "B" }
local EJES = { "X", "Y", "Z" }
local ATRIBUTO_EQUIPO = "EquipoFutbol"
local PERMISO_ARBITRO = "futbol.arbitro"
local REMOTO_PATADA = "FootballKick"
local REMOTO_ACCION = "FootballAction"

---------------------------------------------------------------------------------------------------
-- Parámetros (Config.Futbol con respaldo; el resto son ajustes propios del servicio)
---------------------------------------------------------------------------------------------------
FootballService.ZonaPorDefecto = "CANCHA" -- Zona de MapaLogico con la definición Futbol.
FootballService.DistanciaPatada = tonumber(CFG.DistanciaPatada) or 9 -- Studs HumanoidRootPart-balón.
FootballService.FuerzaMax = tonumber(CFG.FuerzaMax) or 60 -- Velocidad (studs/s) con Fuerza = 1.
FootballService.CooldownPatada = tonumber(CFG.CooldownPatada) or 0.6 -- Segundos entre patadas del mismo jugador.
FootballService.DuracionPartidoSeg = tonumber(CFG.DuracionPartidoSeg) or 300 -- Duración del partido.
FootballService.ResetTrasGolSeg = tonumber(CFG.ResetTrasGolSeg) or 3 -- Espera antes de recolocar el balón tras un gol.
FootballService.JugadoresPorEquipoMax = tonumber(CFG.JugadoresPorEquipoMax) or 7 -- Máximo por equipo.

FootballService.ToleranciaCooldownSeg = 0.08 -- Margen por variación de latencia entre dos patadas legítimas.
FootballService.ToleranciaDistanciaBase = 0.5 -- Studs extra de tolerancia en la distancia de patada.
FootballService.LatenciaAsumidaSeg = 0.12 -- Tolerancia extra = velocidad del balón × esta latencia...
FootballService.ToleranciaDistanciaMax = 3 -- ...con este máximo (studs).
FootballService.FraccionVerticalMax = 0.35 -- Componente vertical máxima de la patada (fracción de la fuerza).
FootballService.ProductoSentidoMin = -0.25 -- Producto escalar mínimo dirección·(jugador->balón): impide "atraer" el balón.
FootballService.VelocidadAnomala = 150 -- |AssemblyLinearVelocity| por encima de la cual se rescata el balón.
FootballService.PeriodoFisicaSeg = 0.1 -- Muestreo de goles y rescate (Heartbeat con acumulador).
FootballService.PeriodoPresenciaSeg = 1 -- Bucle de presencia, reloj del partido y marcador.
FootballService.EnfriamientoGolSeg = 3 -- No se cuenta otro gol durante estos segundos.
FootballService.GraciaCanchaVaciaSeg = 3 -- Segundos sin jugadores en la cancha antes de anclar el balón.
FootballService.VentanaAutorGolSeg = 8 -- Una patada dentro de esta ventana se atribuye como autora del gol.
FootballService.BalanceEquipos = true -- true = impide unirse si los equipos quedarían muy desequilibrados.
FootballService.DiferenciaEquiposMax = 2 -- Diferencia máxima de jugadores entre equipos con BalanceEquipos.
FootballService.MinJugadoresPorEquipo = 1 -- Jugadores mínimos por equipo para iniciar un partido.
FootballService.MargenZonaUnirse = 6 -- Studs fuera de la caja de la cancha en los que aún se puede unir a un equipo.
FootballService.SalidaAutomaticaSeg = 90 -- Fuera de la cancha más de esto -> se sale del equipo automáticamente.
FootballService.AutoInicio = true -- Sin árbitro conectado y con deporte permitido, el partido arranca solo.
FootballService.AutoInicioSeg = 15 -- Cuenta atrás del inicio automático.
FootballService.PausaTrasPartidoSeg = 20 -- Pausa tras un partido antes de una nueva cuenta atrás automática.
FootballService.FraccionParticipacionMin = 0.5 -- Fracción mínima (del partido y de presencia) para la recompensa.
FootballService.DuracionLibreMinSeg = 60 -- Duración mínima de un partido sin árbitro recortado al resto del periodo.
FootballService.AuditoriaRepeticionSeg = 5 -- Un mismo rechazo (jugador+motivo) se audita como máximo cada N s.
FootballService.AvisoRechazoSeg = 2 -- Aviso al jugador de una patada rechazada como máximo cada N s.
FootballService.TamanoBalon = 2 -- Diámetro del balón (studs).
FootballService.DensidadBalon = 0.5
FootballService.FriccionBalon = 0.6
FootballService.ElasticidadBalon = 0.5

-- Textos para el jugador según el motivo de rechazo de una patada.
local TEXTOS_PATADA = {
	sin_personaje = "Necesitas tu personaje para patear.",
	sin_balon = "El balón no está disponible.",
	reinicio_tras_gol = "Espera: el balón vuelve al centro.",
	cooldown = "Espera un momento antes de volver a patear.",
	direccion_nula = "Dirección de patada no válida.",
	fuerza = "Fuerza de patada no válida.",
	distancia = "Estás demasiado lejos del balón.",
	sentido = "Patea el balón hacia delante.",
}

---------------------------------------------------------------------------------------------------
-- Utilidades
---------------------------------------------------------------------------------------------------
local function esJugador(player)
	return typeof(player) == "Instance" and player:IsA("Player")
end

local function valida(instancia)
	return typeof(instancia) == "Instance" and instancia.Parent ~= nil
end

local function esVector(v)
	return typeof(v) == "Vector3"
end

local function esFinito(n)
	return typeof(n) == "number" and n == n and n ~= math.huge and n ~= -math.huge
end

local function vectorFinito(v)
	return esVector(v) and esFinito(v.X) and esFinito(v.Y) and esFinito(v.Z)
end

local function contar(t)
	local n = 0
	for _ in pairs(t) do
		n = n + 1
	end
	return n
end

local function copiarTabla(t)
	if typeof(t) ~= "table" then
		return t
	end
	local copia = {}
	for clave, valor in pairs(t) do
		copia[clave] = copiarTabla(valor)
	end
	return copia
end

local function otroEquipo(letra)
	if letra == "A" then
		return "B"
	end
	return "A"
end

local function servidorAhora()
	local ok, t = pcall(function()
		return workspace:GetServerTimeNow()
	end)
	if ok and esFinito(t) then
		return t
	end
	return os.time()
end

-- HumanoidRootPart y Humanoid si el personaje existe y está vivo; nil si no.
local function personajeVivo(player)
	local personaje = player.Character
	if not personaje or personaje.Parent == nil then
		return nil
	end
	local humanoide = personaje:FindFirstChildOfClass("Humanoid")
	if not humanoide or humanoide.Health <= 0 then
		return nil
	end
	local raiz = personaje:FindFirstChild("HumanoidRootPart")
	if not raiz or not raiz:IsA("BasePart") then
		return nil
	end
	return raiz, humanoide
end

local function posicionDe(player)
	local personaje = player.Character
	if not personaje then
		return nil
	end
	local raiz = personaje:FindFirstChild("HumanoidRootPart")
	if raiz and raiz:IsA("BasePart") then
		return raiz.Position
	end
	return nil
end

-- ¿El segmento p0 -> p1 toca la caja de la parte? (método de las franjas en el espacio local de la parte).
-- Con p0 == p1 equivale a comprobar si el punto está dentro de la caja.
local function segmentoCruzaCaja(parte, p0, p1)
	local a = parte.CFrame:PointToObjectSpace(p0)
	local b = parte.CFrame:PointToObjectSpace(p1)
	local d = b - a
	local medio = parte.Size / 2
	local tmin, tmax = 0, 1
	for _, eje in ipairs(EJES) do
		local origen, delta, h = a[eje], d[eje], medio[eje]
		if math.abs(delta) < 1e-6 then
			if math.abs(origen) > h then
				return false
			end
		else
			local t1 = (-h - origen) / delta
			local t2 = (h - origen) / delta
			if t1 > t2 then
				t1, t2 = t2, t1
			end
			if t1 > tmin then
				tmin = t1
			end
			if t2 < tmax then
				tmax = t2
			end
			if tmin > tmax then
				return false
			end
		end
	end
	return true
end

-- Primera zona de MapaLogico con definición Futbol (prioridad a CANCHA). Devuelve zonaId, def.
local function buscarZonaFutbol(preferida)
	local zona = MapaLogico.Zonas[preferida]
	if zona and typeof(zona.Futbol) == "table" then
		return preferida, zona.Futbol
	end
	for _, id in ipairs(MapaLogico.OrdenZonas or {}) do
		local z = MapaLogico.Zonas[id]
		if z and typeof(z.Futbol) == "table" then
			return id, z.Futbol
		end
	end
	return preferida, nil
end

-- Part invisible, anclada y sin colisiones (volumen lógico de arco).
local function nuevaParteInvisible(nombre, tamano, cframe, padre)
	local parte = Instance.new("Part")
	parte.Name = nombre
	parte.Anchored = true
	parte.CanCollide = false
	parte.CanQuery = false
	parte.CanTouch = false
	parte.CastShadow = false
	parte.Transparency = 1
	parte.Locked = true
	parte.Size = tamano
	parte.CFrame = cframe
	parte.Parent = padre
	return parte
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function FootballService:Init(registro)
	self.registro = registro
	self.zonaId = self.ZonaPorDefecto
	self.equipos = { A = {}, B = {} } -- letra -> { [userId] = true }
	self.equipoDe = {} -- userId -> "A" | "B"
	self.ingreso = {} -- userId -> os.clock() de entrada al equipo
	self.fueraDesde = {} -- userId -> os.clock() desde que está fuera de la cancha
	self.ultimaPatada = {} -- userId -> os.clock() de la última patada aceptada
	self.ultimaAuditoria = {} -- "userId|accion|motivo" -> { T, Omitidos }
	self.ultimoAviso = {} -- userId -> os.clock() del último aviso de patada rechazada
	self.erroresAvisados = {} -- clave -> os.clock() (evita repetir warn)
	self.enCancha = {} -- Player -> true (último muestreo de presencia)
	self.ultimoPateador = nil -- { UserId, Equipo, T }
	self.activo = false -- ¿el balón se está simulando?
	self.reinicioPendiente = false
	self.tokenReinicio = 0
	self.ultimoGolClock = -math.huge
	self.ultimoConJugadores = -math.huge
	self.finPartidoClock = -math.huge
	self.autoInicioClock = nil
	self.autoInicioServidor = nil
	self.posAnterior = nil
	self.acumPresencia = 0
	self.acumFisica = 0
	self.contadorPartidos = 0
	self.partido = self:_PartidoVacio()
	self.ultimoResultado = nil
	self.conexiones = {}
	self.conexionFisica = nil
	self.emisionPendiente = false
	self.inicioLibreContrato = false
	self.estadisticas = {
		Patadas = 0, Rechazos = 0, Goles = 0, GolesAmistosos = 0, Partidos = 0, Rescates = 0, PorMotivo = {},
	}
	self.instancias = { Carpeta = nil, Balon = nil, ArcoA = nil, ArcoB = nil, Marcador = nil, MarcadorGui = nil }
	self.limites = nil
	self.inicio = nil
	self.marcadorUI = nil
	self.GolMarcado = Signal.new() -- (equipoAnotador, playerAutorOrNil, marcador)
	self.PartidoIniciado = Signal.new() -- (estado)
	self.PartidoTerminado = Signal.new() -- (resultado)
	self.EquiposCambiados = Signal.new() -- (player, equipoNuevoOrNil, equipoAnterior)
end

function FootballService:Start()
	self.AuditLog = self:_Servicio("AuditLogService")

	-- ¿El contrato permite que cualquier jugador pida "Iniciar"? (si no, el inicio libre es automático).
	local okPermiso, permisoIniciar = pcall(RemoteContracts.PermisoPara, REMOTO_ACCION, { Accion = "Iniciar" })
	self.inicioLibreContrato = okPermiso and permisoIniciar == nil

	local okInst, errInst = pcall(self._ResolverInstancias, self)
	if not okInst then
		warn(PREFIJO .. " No se pudieron preparar el balón, los arcos o el marcador: " .. tostring(errInst))
	end

	local RemoteService = self:_Servicio("RemoteService")
	if RemoteService and typeof(RemoteService.Registrar) == "function" then
		RemoteService:Registrar(REMOTO_PATADA, function(player, datos)
			return self:_ManejarPatada(player, datos)
		end)
		RemoteService:Registrar(REMOTO_ACCION, function(player, datos)
			return self:_ManejarAccion(player, datos)
		end)
		if typeof(RemoteService.AportarSnapshot) == "function" then
			pcall(RemoteService.AportarSnapshot, RemoteService, "Futbol", function(player)
				return self:Snapshot(player)
			end)
		end
	else
		warn(PREFIJO .. " RemoteService no disponible: FootballKick y FootballAction no tendrán handler.")
	end

	self:_ConectarJornada()

	table.insert(self.conexiones, Players.PlayerRemoving:Connect(function(player)
		local ok, err = pcall(self._AlSalirJugador, self, player)
		if not ok then
			warn(PREFIJO .. " Error al limpiar al jugador " .. player.Name .. ": " .. tostring(err))
		end
	end))

	-- Bucle de presencia (1 s): activa/desactiva la física, reloj del partido, marcador y auto-inicio.
	table.insert(self.conexiones, RunService.Heartbeat:Connect(function(dt)
		self.acumPresencia = self.acumPresencia + dt
		if self.acumPresencia < self.PeriodoPresenciaSeg then
			return
		end
		self.acumPresencia = 0
		local ok, err = pcall(self._Tick, self)
		if not ok then
			self:_AvisarError("tick", err)
		end
	end))

	self:_ActualizarMarcador()
	self:_Registrar("Sistema", nil, "Futbol", string.format(
		"Cancha %s lista · balón %s · arcos %s/%s · marcador %s · inicio libre por contrato: %s",
		tostring(self.zonaId),
		valida(self.instancias.Balon) and "sí" or "no",
		valida(self.instancias.ArcoA) and "sí" or "no",
		valida(self.instancias.ArcoB) and "sí" or "no",
		valida(self.instancias.MarcadorGui) and "sí" or "no",
		self.inicioLibreContrato and "sí" or "no (inicio automático)"))
end

-- Desconecta los bucles y deja el balón anclado (uso en pruebas o al recargar el sistema).
function FootballService:Detener()
	self:_DetenerFisica()
	for _, conexion in ipairs(self.conexiones) do
		pcall(function()
			conexion:Disconnect()
		end)
	end
	self.conexiones = {}
	self.activo = false
	self:_CancelarReinicio()
	pcall(self._RecolocarBalon, self, "detener")
end

---------------------------------------------------------------------------------------------------
-- Acceso a otros servicios (tolerante a ausencia)
---------------------------------------------------------------------------------------------------
function FootballService:_Servicio(nombre)
	local registro = self.registro
	if registro and typeof(registro.Get) == "function" then
		return registro.Get(nombre)
	end
	return nil
end

function FootballService:_Registrar(categoria, player, accion, detalle)
	local AuditLog = self.AuditLog or self:_Servicio("AuditLogService")
	if AuditLog and typeof(AuditLog.Registrar) == "function" then
		pcall(AuditLog.Registrar, AuditLog, categoria, player, accion, detalle)
	end
end

-- Auditoría de un rechazo con supresión de repeticiones (jugador + acción + motivo). categoria por defecto
-- "Remoto" (cuenta también en MetricsService); otra categoría solo se registra en AuditLogService.
function FootballService:_AuditarRechazo(player, accion, motivo, detalle, categoria)
	local uid = esJugador(player) and player.UserId or 0
	local clave = tostring(uid) .. "|" .. tostring(accion) .. "|" .. tostring(motivo)
	local ahora = os.clock()
	local previo = self.ultimaAuditoria[clave]
	if previo and ahora - previo.T < self.AuditoriaRepeticionSeg then
		previo.Omitidos = previo.Omitidos + 1
		return
	end
	local texto = tostring(motivo)
	if detalle ~= nil and detalle ~= "" then
		texto = texto .. ": " .. tostring(detalle)
	end
	if previo and previo.Omitidos > 0 then
		texto = texto .. string.format(" (+%d repetidos)", previo.Omitidos)
	end
	self.ultimaAuditoria[clave] = { T = ahora, Omitidos = 0 }
	self:_Registrar(categoria or "Remoto", player, accion, texto)
	if categoria ~= nil and categoria ~= "Remoto" then
		return
	end
	local Metrics = self:_Servicio("MetricsService")
	if Metrics and typeof(Metrics.IncrementarRechazo) == "function" then
		pcall(Metrics.IncrementarRechazo, Metrics, accion, motivo)
	end
end

-- warn como máximo una vez cada 30 s por clave.
function FootballService:_AvisarError(clave, err)
	local ahora = os.clock()
	local previo = self.erroresAvisados[clave]
	if previo and ahora - previo < 30 then
		return
	end
	self.erroresAvisados[clave] = ahora
	warn(PREFIJO .. " Error en " .. tostring(clave) .. ": " .. tostring(err))
end

function FootballService:_Notificar(player, texto, nivel)
	local RemoteService = self:_Servicio("RemoteService")
	if RemoteService and typeof(RemoteService.Enviar) == "function" and esJugador(player) then
		pcall(RemoteService.Enviar, RemoteService, player, "Notificacion", {
			Titulo = "Fútbol", Texto = texto, Nivel = nivel or "info", Tipo = nivel or "info",
		})
	end
end

function FootballService:_EsArbitro(player)
	local RoleService = self:_Servicio("RoleService")
	if RoleService and typeof(RoleService.Tiene) == "function" then
		local ok, tiene = pcall(RoleService.Tiene, RoleService, player, PERMISO_ARBITRO)
		return ok and tiene == true
	end
	return false
end

-- ¿Hay algún jugador conectado con futbol.arbitro?
function FootballService:_HayArbitroConectado()
	local RoleService = self:_Servicio("RoleService")
	if not RoleService then
		return false
	end
	if typeof(RoleService.ConPermiso) == "function" then
		local ok, lista = pcall(RoleService.ConPermiso, RoleService, PERMISO_ARBITRO)
		if ok and typeof(lista) == "table" then
			return #lista > 0
		end
	end
	for _, player in ipairs(Players:GetPlayers()) do
		if self:_EsArbitro(player) then
			return true
		end
	end
	return false
end

-- SchoolDayService:PermiteDeporte(); sin el servicio no se restringe el deporte.
function FootballService:_PermiteDeporte()
	local SchoolDay = self:_Servicio("SchoolDayService")
	if SchoolDay and typeof(SchoolDay.PermiteDeporte) == "function" then
		local ok, permite = pcall(SchoolDay.PermiteDeporte, SchoolDay)
		if ok then
			return permite == true
		end
	end
	return true
end

function FootballService:_ConectarSenal(senal, fn)
	if typeof(senal) ~= "table" or typeof(senal.Connect) ~= "function" then
		return false
	end
	local ok, conexion = pcall(function()
		return senal:Connect(fn)
	end)
	if ok and conexion ~= nil then
		table.insert(self.conexiones, conexion)
		return true
	end
	return false
end

function FootballService:_ConectarJornada()
	local SchoolDay = self:_Servicio("SchoolDayService")
	if not SchoolDay then
		return
	end
	self:_ConectarSenal(SchoolDay.EstadoCambiado, function()
		task.defer(function()
			local ok, err = pcall(self._AlCambiarJornada, self)
			if not ok then
				self:_AvisarError("jornada", err)
			end
		end)
	end)
	self:_ConectarSenal(SchoolDay.JornadaTerminada, function()
		task.defer(function()
			if self.partido.Estado == "EnJuego" then
				pcall(self._TerminarPartido, self, "Fin de la jornada escolar", false)
			end
		end)
	end)
end

-- Un partido iniciado sin árbitro termina si la jornada deja de permitir deporte.
function FootballService:_AlCambiarJornada()
	if self.partido.Estado == "EnJuego" and self.partido.Libre and not self:_PermiteDeporte() then
		self:_TerminarPartido("La jornada pasó a otra actividad", false)
		return
	end
	self:_EmitirEstado()
end

---------------------------------------------------------------------------------------------------
-- Instancias del mapa (balón, arcos, marcador)
---------------------------------------------------------------------------------------------------
function FootballService:_CarpetaPropia(MapService)
	if MapService and typeof(MapService.Carpeta) == "function" then
		local ok, carpeta = pcall(MapService.Carpeta, MapService, "Futbol")
		if ok and valida(carpeta) then
			return carpeta
		end
	end
	local nombreRaiz = (Config.Nombres and Config.Nombres.CarpetaMapa) or "ColegioRP_Mapa"
	local raiz = workspace:FindFirstChild(nombreRaiz)
	if not raiz then
		raiz = Instance.new("Folder")
		raiz.Name = nombreRaiz
		raiz.Parent = workspace
	end
	local carpeta = raiz:FindFirstChild("Futbol")
	if not carpeta then
		carpeta = Instance.new("Folder")
		carpeta.Name = "Futbol"
		carpeta.Parent = raiz
	end
	return carpeta
end

function FootballService:_ResolverInstancias()
	self:_DetenerFisica()
	self.activo = false
	self.posAnterior = nil

	local MapService = self:_Servicio("MapService")
	local info = nil
	if MapService and typeof(MapService.Futbol) == "function" then
		local ok, resultado = pcall(MapService.Futbol, MapService)
		if ok and typeof(resultado) == "table" then
			info = resultado
		end
	end
	info = info or {}

	local zonaId, def = nil, nil
	if typeof(info.ZonaId) == "string" then
		zonaId, def = buscarZonaFutbol(info.ZonaId)
	else
		zonaId, def = buscarZonaFutbol(self.ZonaPorDefecto)
	end
	self.zonaId = zonaId or self.ZonaPorDefecto
	def = def or {}
	local zona = Zones.Zona(self.zonaId)

	local carpeta = info.Carpeta
	if not valida(carpeta) then
		carpeta = self:_CarpetaPropia(MapService)
	end
	self.instancias.Carpeta = carpeta

	-- Límites de rescate.
	local limites = info.Limites
	if not (typeof(limites) == "table" and esVector(limites.Min) and esVector(limites.Max)) then
		limites = def.Limites
	end
	if not (typeof(limites) == "table" and esVector(limites.Min) and esVector(limites.Max)) then
		limites = nil
		local minZona, maxZona = Zones.Limites(self.zonaId)
		if minZona and maxZona then
			limites = { Min = minZona - Vector3.new(6, 6, 6), Max = maxZona + Vector3.new(6, 30, 6) }
		end
	end
	if limites then
		self.limites = { Min = limites.Min, Max = limites.Max }
	else
		self.limites = nil
	end

	-- Punto de saque (centro).
	local inicio = info.Inicio
	if not esVector(inicio) then
		inicio = def.Balon
	end
	if not esVector(inicio) and zona then
		local _, spawnY = Zones.AlturasDe(zona)
		inicio = Vector3.new(zona.Centro.X, spawnY + 1, zona.Centro.Z)
	end
	if not esVector(inicio) then
		inicio = Vector3.new(0, 5, 0)
	end
	self.inicio = inicio

	-- Balón.
	local balon = info.Balon
	if not (valida(balon) and balon:IsA("BasePart")) then
		balon = carpeta:FindFirstChild("Balon")
	end
	if not (valida(balon) and balon:IsA("BasePart")) then
		balon = Instance.new("Part")
		balon.Name = "Balon"
		balon.Color = Color3.fromRGB(245, 245, 245)
		balon.Material = Enum.Material.SmoothPlastic
		balon.TopSurface = Enum.SurfaceType.Smooth
		balon.BottomSurface = Enum.SurfaceType.Smooth
		balon.Anchored = true
		balon.CFrame = CFrame.new(inicio)
		balon:SetAttribute("Inicio", inicio)
		balon.Parent = carpeta
		warn(PREFIJO .. " MapService no aportó el balón; se creó uno propio en " .. carpeta:GetFullName())
	end
	self:_PrepararBalon(balon)

	-- Arcos (volúmenes de gol).
	for _, letra in ipairs(EQUIPOS) do
		local nombre = "Arco" .. letra
		local arco = info[nombre]
		if not (valida(arco) and arco:IsA("BasePart")) then
			arco = carpeta:FindFirstChild(nombre)
		end
		if not (valida(arco) and arco:IsA("BasePart")) then
			arco = self:_CrearArco(carpeta, letra, def[nombre], zona)
		end
		if arco then
			pcall(function()
				arco:SetAttribute("Equipo", letra)
			end)
		end
		self.instancias[nombre] = arco
	end

	-- Marcador físico.
	local marcador = info.Marcador
	if not (valida(marcador) and marcador:IsA("BasePart")) then
		marcador = carpeta:FindFirstChild("Marcador")
	end
	if not (valida(marcador) and marcador:IsA("BasePart")) then
		marcador = self:_CrearMarcador(carpeta, def, zona)
	end
	self.instancias.Marcador = marcador
	local gui = info.MarcadorGui
	if not (valida(gui) and gui:IsA("SurfaceGui")) and marcador then
		gui = marcador:FindFirstChildOfClass("SurfaceGui")
	end
	if not (valida(gui) and gui:IsA("SurfaceGui")) and marcador then
		gui = Instance.new("SurfaceGui")
		gui.Name = "MarcadorGui"
		gui.Face = Enum.NormalId.Front
		gui.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud
		gui.PixelsPerStud = 50
		gui.LightInfluence = 0
		gui.ClipsDescendants = true
		gui.Parent = marcador
	end
	self.instancias.MarcadorGui = gui
	self:_ConstruirMarcadorGui()

	pcall(function()
		carpeta:SetAttribute("ZoneId", self.zonaId)
		carpeta:SetAttribute("Activo", false)
		carpeta:SetAttribute("DistanciaPatada", self.DistanciaPatada)
		carpeta:SetAttribute("CooldownPatada", self.CooldownPatada)
	end)
end

function FootballService:_PropiedadesBalon()
	local ok, propiedades = pcall(PhysicalProperties.new, self.DensidadBalon, self.FriccionBalon, self.ElasticidadBalon, 1, 1)
	if ok then
		return propiedades
	end
	return nil
end

-- Propiedades físicas estables y estado anclado en el centro.
function FootballService:_PrepararBalon(balon)
	self.instancias.Balon = balon
	local tamano = self.TamanoBalon
	pcall(function()
		if balon:IsA("Part") then
			balon.Shape = Enum.PartType.Ball
		end
		balon.Size = Vector3.new(tamano, tamano, tamano)
		balon.CanCollide = true
		balon.CanTouch = true
		balon.CanQuery = true
		balon.Massless = false
		balon.Locked = true
		local propiedades = self:_PropiedadesBalon()
		if propiedades then
			balon.CustomPhysicalProperties = propiedades
		end
		balon:SetAttribute("ColegioRP_Balon", true)
	end)
	pcall(function()
		balon.Anchored = true
		balon.CFrame = CFrame.new(self.inicio)
		balon.AssemblyLinearVelocity = Vector3.zero
		balon.AssemblyAngularVelocity = Vector3.zero
	end)
end

function FootballService:_CrearArco(carpeta, letra, arcoDef, zona)
	local centro, tamano = nil, nil
	if typeof(arcoDef) == "table" and esVector(arcoDef.Centro) and esVector(arcoDef.Tamano) then
		centro, tamano = arcoDef.Centro, arcoDef.Tamano
	elseif zona then
		local sueloY = Zones.AlturasDe(zona)
		local signo = -1
		if letra == "B" then
			signo = 1
		end
		centro = Vector3.new(zona.Centro.X + signo * (zona.Tamano.X / 2 - 3), sueloY + 3.5, zona.Centro.Z)
		tamano = Vector3.new(3, 7, 12)
	end
	if not centro then
		warn(PREFIJO .. " Sin datos para crear Arco" .. letra .. "; no habrá goles en ese arco.")
		return nil
	end
	local arco = nuevaParteInvisible("Arco" .. letra, tamano, CFrame.new(centro), carpeta)
	warn(PREFIJO .. " MapService no aportó Arco" .. letra .. "; se creó un volumen propio.")
	return arco
end

function FootballService:_CrearMarcador(carpeta, def, zona)
	local posicion, normal = nil, Vector3.new(0, 0, -1)
	if typeof(def.Marcador) == "table" and esVector(def.Marcador.Centro) then
		posicion = def.Marcador.Centro
		if esVector(def.Marcador.Normal) and def.Marcador.Normal.Magnitude > 1e-3 then
			normal = def.Marcador.Normal.Unit
		end
	elseif esVector(def.Marcador) then
		posicion = def.Marcador
	elseif zona then
		local sueloY = Zones.AlturasDe(zona)
		posicion = Vector3.new(zona.Centro.X, sueloY + 12, zona.Centro.Z + zona.Tamano.Z / 2)
	end
	if not posicion then
		return nil
	end
	local marcador = Instance.new("Part")
	marcador.Name = "Marcador"
	marcador.Anchored = true
	marcador.CanCollide = false
	marcador.CanQuery = false
	marcador.CanTouch = false
	marcador.CastShadow = false
	marcador.Locked = true
	marcador.Material = Enum.Material.SmoothPlastic
	marcador.Color = Color3.fromRGB(20, 20, 24)
	marcador.Size = Vector3.new(12, 4, 0.4)
	marcador.CFrame = CFrame.lookAt(posicion, posicion + normal * 2)
	marcador.Parent = carpeta
	warn(PREFIJO .. " MapService no aportó el marcador; se creó uno propio.")
	return marcador
end

-- Construye el contenido de la SurfaceGui del marcador (equipos, goles, tiempo y estado).
function FootballService:_ConstruirMarcadorGui()
	local gui = self.instancias.MarcadorGui
	self.marcadorUI = nil
	if not valida(gui) then
		return
	end
	local previo = gui:FindFirstChild("ColegioRP_Marcador")
	if previo then
		previo:Destroy()
	end
	local Colores = UITheme.Colores
	local fondo = Instance.new("Frame")
	fondo.Name = "ColegioRP_Marcador"
	fondo.Size = UDim2.fromScale(1, 1)
	fondo.BackgroundColor3 = Color3.fromRGB(14, 14, 18)
	fondo.BorderSizePixel = 0

	local function etiqueta(nombre, x, y, ancho, alto, color, fuente, texto, alineacion)
		local label = Instance.new("TextLabel")
		label.Name = nombre
		label.BackgroundTransparency = 1
		label.Position = UDim2.fromScale(x, y)
		label.Size = UDim2.fromScale(ancho, alto)
		label.Font = fuente or UITheme.Fuente("Titulo")
		label.TextColor3 = color or Colores.Blanco
		label.TextScaled = true
		label.TextXAlignment = alineacion or Enum.TextXAlignment.Center
		label.Text = texto or ""
		label.Parent = fondo
		return label
	end

	local franja = Instance.new("Frame")
	franja.Name = "Franja"
	franja.BackgroundColor3 = Colores.Rojo
	franja.BorderSizePixel = 0
	franja.Position = UDim2.fromScale(0, 0)
	franja.Size = UDim2.fromScale(1, 0.03)
	franja.Parent = fondo

	local azulClaro = UITheme.Aclarar(Colores.Azul, 0.35)
	local nombreCorto = string.upper(tostring(Config.NombreCorto or "Colegio"))
	local ui = { Fondo = fondo }
	ui.Titulo = etiqueta("Titulo", 0.05, 0.05, 0.9, 0.14, Colores.TextoSecundario, UITheme.Fuente("Subtitulo"), "CANCHA · " .. nombreCorto)
	ui.EquipoA = etiqueta("EquipoA", 0.03, 0.22, 0.34, 0.16, Colores.Rojo, nil, "EQUIPO A")
	ui.EquipoB = etiqueta("EquipoB", 0.63, 0.22, 0.34, 0.16, azulClaro, nil, "EQUIPO B")
	ui.GolesA = etiqueta("GolesA", 0.05, 0.38, 0.3, 0.42, Colores.Blanco, nil, "0")
	ui.Separador = etiqueta("Separador", 0.4, 0.42, 0.2, 0.34, Colores.TextoSecundario, nil, "-")
	ui.GolesB = etiqueta("GolesB", 0.65, 0.38, 0.3, 0.42, Colores.Blanco, nil, "0")
	ui.Estado = etiqueta("Estado", 0.04, 0.82, 0.58, 0.14, Colores.TextoSecundario, UITheme.Fuente("Subtitulo"), "CANCHA LIBRE", Enum.TextXAlignment.Left)
	ui.Tiempo = etiqueta("Tiempo", 0.64, 0.8, 0.32, 0.17, Colores.Amarillo, nil, Format.Tiempo(self.DuracionPartidoSeg), Enum.TextXAlignment.Right)
	fondo.Parent = gui
	self.marcadorUI = ui
end

-- Refresca los textos del marcador físico (1 vez/s durante el partido y en cada evento).
function FootballService:_ActualizarMarcador()
	local ui = self.marcadorUI
	if not ui or not valida(ui.Fondo) then
		return
	end
	local p = self.partido
	local goles = p.Goles
	ui.GolesA.Text = tostring(goles.A)
	ui.GolesB.Text = tostring(goles.B)
	ui.EquipoA.Text = string.format("EQUIPO A (%d)", contar(self.equipos.A))
	ui.EquipoB.Text = string.format("EQUIPO B (%d)", contar(self.equipos.B))
	if p.Estado == "EnJuego" then
		ui.Tiempo.Text = Format.Tiempo(self:_Restante())
		ui.Estado.Text = "EN JUEGO"
	elseif self.autoInicioClock then
		-- La cuenta atrás del inicio automático tiene prioridad sobre el resultado del partido anterior.
		ui.Tiempo.Text = Format.Tiempo(self.DuracionPartidoSeg)
		ui.Estado.Text = string.format("INICIO EN %d s", math.max(0, math.ceil(self.autoInicioClock - os.clock())))
	elseif p.Estado == "Terminado" then
		ui.Tiempo.Text = "FINAL"
		local resultado = self.ultimoResultado
		if resultado and resultado.Ganador == "A" then
			ui.Estado.Text = "GANA EL EQUIPO A"
		elseif resultado and resultado.Ganador == "B" then
			ui.Estado.Text = "GANA EL EQUIPO B"
		else
			ui.Estado.Text = "EMPATE"
		end
	else
		ui.Tiempo.Text = Format.Tiempo(self.DuracionPartidoSeg)
		if self.autoInicioClock then
			ui.Estado.Text = string.format("INICIO EN %d s", math.max(0, math.ceil(self.autoInicioClock - os.clock())))
		else
			ui.Estado.Text = "CANCHA LIBRE"
		end
	end
end

---------------------------------------------------------------------------------------------------
-- Simulación del balón
---------------------------------------------------------------------------------------------------
function FootballService:_AsegurarPropietario(forzar)
	local balon = self.instancias.Balon
	if not valida(balon) or balon.Anchored then
		return
	end
	pcall(function()
		if forzar or balon:GetNetworkOwner() ~= nil or balon:GetNetworkOwnershipAuto() then
			balon:SetNetworkOwner(nil)
		end
	end)
end

function FootballService:_Activar()
	local balon = self.instancias.Balon
	if not valida(balon) then
		return false
	end
	self.activo = true
	self.posAnterior = nil
	-- Cuenta como presencia: evita que el siguiente tick ancle el balón justo después de una patada.
	self.ultimoConJugadores = os.clock()
	pcall(function()
		balon.Anchored = false
	end)
	self:_AsegurarPropietario(true)
	if not self.conexionFisica then
		self.acumFisica = 0
		self.conexionFisica = RunService.Heartbeat:Connect(function(dt)
			self.acumFisica = self.acumFisica + dt
			if self.acumFisica < self.PeriodoFisicaSeg then
				return
			end
			self.acumFisica = 0
			local ok, err = pcall(self._PasoFisica, self)
			if not ok then
				self:_AvisarError("fisica", err)
			end
		end)
	end
	pcall(function()
		self.instancias.Carpeta:SetAttribute("Activo", true)
	end)
	return true
end

function FootballService:_DetenerFisica()
	if self.conexionFisica then
		pcall(function()
			self.conexionFisica:Disconnect()
		end)
		self.conexionFisica = nil
	end
end

-- Cancha vacía: sin bucle de goles y balón anclado en el centro.
function FootballService:_Desactivar()
	self:_DetenerFisica()
	self.activo = false
	self:_CancelarReinicio()
	self:_RecolocarBalon("cancha_vacia")
	pcall(function()
		self.instancias.Carpeta:SetAttribute("Activo", false)
	end)
end

-- Coloca el balón en el centro con velocidad 0 (anclado si la cancha está vacía).
function FootballService:_RecolocarBalon(_motivo)
	local balon = self.instancias.Balon
	if not valida(balon) then
		return
	end
	self.posAnterior = nil
	-- Tras recolocar, un gol posterior no se atribuye a quien pateó antes del saque.
	self.ultimoPateador = nil
	local destino = CFrame.new(self.inicio or balon.Position)
	pcall(function()
		balon.Anchored = not self.activo
		balon.CFrame = destino
		balon.AssemblyLinearVelocity = Vector3.zero
		balon.AssemblyAngularVelocity = Vector3.zero
	end)
	if self.activo then
		self:_AsegurarPropietario(true)
	end
end

function FootballService:_ProgramarReinicio(segundos)
	self.reinicioPendiente = true
	self.tokenReinicio = self.tokenReinicio + 1
	local token = self.tokenReinicio
	task.delay(math.max(0, segundos), function()
		if self.tokenReinicio ~= token then
			return
		end
		self.reinicioPendiente = false
		local ok, err = pcall(self._RecolocarBalon, self, "saque")
		if not ok then
			self:_AvisarError("saque", err)
		end
		self:_EnviarCancha({ Sub = "Saque" })
	end)
end

function FootballService:_CancelarReinicio()
	self.tokenReinicio = self.tokenReinicio + 1
	self.reinicioPendiente = false
end

-- Muestreo cada 0.1 s: rescate (límites, caída, velocidad anómala) y detección de goles.
function FootballService:_PasoFisica()
	local balon = self.instancias.Balon
	if not valida(balon) or balon.Anchored then
		return
	end
	local posicion = balon.Position
	local velocidad = balon.AssemblyLinearVelocity
	local motivo = nil
	if not vectorFinito(posicion) or not vectorFinito(velocidad) then
		motivo = "valores_invalidos"
	elseif velocidad.Magnitude > self.VelocidadAnomala then
		motivo = "velocidad_anomala"
	elseif self.limites then
		local minimo, maximo = self.limites.Min, self.limites.Max
		if posicion.Y < minimo.Y then
			motivo = "caida"
		elseif posicion.X < minimo.X or posicion.X > maximo.X or posicion.Z < minimo.Z or posicion.Z > maximo.Z or posicion.Y > maximo.Y then
			motivo = "fuera_de_limites"
		end
	end
	if motivo then
		self:_Rescatar(motivo, velocidad)
		return
	end

	local anterior = self.posAnterior or posicion
	self.posAnterior = posicion
	if self.reinicioPendiente or os.clock() - self.ultimoGolClock < self.EnfriamientoGolSeg then
		return
	end
	for _, letra in ipairs(EQUIPOS) do
		local arco = self.instancias["Arco" .. letra]
		if valida(arco) and segmentoCruzaCaja(arco, anterior, posicion) then
			self:_Gol(letra)
			return
		end
	end
end

function FootballService:_Rescatar(motivo, velocidad)
	self.estadisticas.Rescates = self.estadisticas.Rescates + 1
	if motivo == "velocidad_anomala" or motivo == "valores_invalidos" then
		local detalle = motivo
		if vectorFinito(velocidad) then
			detalle = string.format("%s (%.0f studs/s)", motivo, velocidad.Magnitude)
		end
		local up = self.ultimoPateador
		local sospechoso = nil
		if up and os.clock() - up.T < 2 then
			sospechoso = Players:GetPlayerByUserId(up.UserId)
		end
		self:_AuditarRechazo(sospechoso, "FutbolRescate", motivo, detalle, "Sistema")
	end
	self:_CancelarReinicio()
	self:_RecolocarBalon(motivo)
	self:_EnviarCancha({ Sub = "Rescate", Motivo = motivo })
end

-- Gol en el arco 'arcoLetra' (lo marca el equipo contrario).
function FootballService:_Gol(arcoLetra)
	local anotador = otroEquipo(arcoLetra)
	local ahora = os.clock()
	self.ultimoGolClock = ahora
	local p = self.partido
	local autor, autorNombre, equipoAutor = nil, nil, nil
	local up = self.ultimoPateador
	if up and ahora - up.T <= self.VentanaAutorGolSeg then
		local jugador = Players:GetPlayerByUserId(up.UserId)
		if jugador then
			autor = jugador
			autorNombre = jugador.DisplayName
			equipoAutor = up.Equipo
		end
	end
	if p.Estado == "EnJuego" then
		p.Goles[anotador] = p.Goles[anotador] + 1
		self.estadisticas.Goles = self.estadisticas.Goles + 1
		local autogol = autor ~= nil and equipoAutor ~= nil and equipoAutor ~= anotador
		if autor and equipoAutor == anotador then
			self:_SumarGolPerfil(autor)
		end
		self:_EnviarCancha({
			Sub = "Gol", Equipo = anotador, Marcador = { A = p.Goles.A, B = p.Goles.B },
			Autor = autorNombre, Autogol = autogol, Arco = arcoLetra, Amistoso = false,
		})
		self:_ActualizarMarcador()
		self:_EmitirEstado()
		self.GolMarcado:Fire(anotador, autor, { A = p.Goles.A, B = p.Goles.B })
	else
		self.estadisticas.GolesAmistosos = self.estadisticas.GolesAmistosos + 1
		self:_EnviarCancha({
			Sub = "Gol", Equipo = anotador, Marcador = { A = p.Goles.A, B = p.Goles.B },
			Autor = autorNombre, Arco = arcoLetra, Amistoso = true,
		})
	end
	self:_ProgramarReinicio(self.ResetTrasGolSeg)
end

function FootballService:_SumarGolPerfil(player)
	local DataService = self:_Servicio("DataService")
	if not DataService or typeof(DataService.Obtener) ~= "function" then
		return
	end
	local ok, perfil = pcall(DataService.Obtener, DataService, player)
	if ok and typeof(perfil) == "table" and typeof(perfil.Progreso) == "table" then
		perfil.Progreso.Goles = (tonumber(perfil.Progreso.Goles) or 0) + 1
		if typeof(DataService.Marcar) == "function" then
			pcall(DataService.Marcar, DataService, player)
		end
	end
end

---------------------------------------------------------------------------------------------------
-- Bucle de presencia (1 s)
---------------------------------------------------------------------------------------------------

-- Jugadores cuyo HumanoidRootPart está dentro de la zona de la cancha.
function FootballService:JugadoresEnCancha()
	local lista = {}
	for _, player in ipairs(Players:GetPlayers()) do
		local posicion = posicionDe(player)
		if posicion and Zones.Contiene(self.zonaId, posicion) then
			table.insert(lista, player)
		end
	end
	return lista
end

function FootballService:_Tick()
	local ahora = os.clock()
	if not valida(self.instancias.Balon) or not valida(self.instancias.Carpeta) then
		self:_ResolverInstancias()
	elseif not (self.marcadorUI and valida(self.marcadorUI.Fondo)) then
		self:_ConstruirMarcadorGui()
	end

	-- Presencia: activa la física con >= 1 jugador; la detiene tras la gracia con la cancha vacía.
	local presentes = self:JugadoresEnCancha()
	local conjunto = {}
	local entrantes = {}
	for _, player in ipairs(presentes) do
		conjunto[player] = true
		if not self.enCancha[player] then
			table.insert(entrantes, player)
		end
	end
	self.enCancha = conjunto
	if #presentes > 0 then
		self.ultimoConJugadores = ahora
		if not self.activo then
			self:_Activar()
		else
			self:_AsegurarPropietario(false)
		end
	elseif self.activo and ahora - self.ultimoConJugadores >= self.GraciaCanchaVaciaSeg then
		self:_Desactivar()
	end

	local cambios = self:_RevisarAusentes(ahora)
	if self.partido.Estado == "EnJuego" then
		self:_AvanzarPartido(ahora)
	end
	if self:_RevisarAutoInicio(ahora) then
		cambios = true
	end
	if self.partido.Estado == "EnJuego" or self.autoInicioClock then
		self:_ActualizarMarcador()
	end
	if cambios then
		self:_ActualizarMarcador()
		self:_EmitirEstado()
	end
	-- Quien acaba de entrar en la cancha recibe el estado completo.
	for _, player in ipairs(entrantes) do
		self:_EnviarEstadoA(player)
	end
end

-- Saca de su equipo a quien lleva demasiado tiempo fuera de la cancha. Devuelve true si hubo cambios.
function FootballService:_RevisarAusentes(ahora)
	local salientes = {}
	for uid in pairs(self.equipoDe) do
		local player = Players:GetPlayerByUserId(uid)
		if not player then
			table.insert(salientes, uid)
		elseif self.enCancha[player] then
			self.fueraDesde[uid] = nil
		else
			local desde = self.fueraDesde[uid]
			if not desde then
				self.fueraDesde[uid] = ahora
			elseif ahora - desde >= self.SalidaAutomaticaSeg then
				table.insert(salientes, player)
			end
		end
	end
	for _, objetivo in ipairs(salientes) do
		self:_QuitarDeEquipo(objetivo, "ausencia", true)
		if esJugador(objetivo) then
			self:_Notificar(objetivo, "Saliste de tu equipo de fútbol por estar fuera de la cancha.", "aviso")
		end
	end
	return #salientes > 0
end

---------------------------------------------------------------------------------------------------
-- Equipos
---------------------------------------------------------------------------------------------------
function FootballService:_ListaEquipo(letra)
	local lista = {}
	for uid in pairs(self.equipos[letra]) do
		local player = Players:GetPlayerByUserId(uid)
		table.insert(lista, { UserId = uid, Nombre = player and player.DisplayName or tostring(uid) })
	end
	table.sort(lista, function(a, b)
		return string.lower(a.Nombre) < string.lower(b.Nombre)
	end)
	return lista
end

function FootballService:EquipoDe(player)
	if not esJugador(player) then
		return nil
	end
	return self.equipoDe[player.UserId]
end

function FootballService:_EquipoSugerido(actual)
	if actual then
		return actual
	end
	if contar(self.equipos.B) < contar(self.equipos.A) then
		return "B"
	end
	return "A"
end

function FootballService:_AsignarEquipo(player, equipo)
	local uid = player.UserId
	local anterior = self.equipoDe[uid]
	if anterior then
		self.equipos[anterior][uid] = nil
	end
	self.equipos[equipo][uid] = true
	self.equipoDe[uid] = equipo
	self.ingreso[uid] = os.clock()
	self.fueraDesde[uid] = nil
	pcall(function()
		player:SetAttribute(ATRIBUTO_EQUIPO, equipo)
	end)
	self.EquiposCambiados:Fire(player, equipo, anterior)
	self:_ActualizarMarcador()
	self:_EmitirEstado()
end

-- objetivo: Player o userId. sinEmitir = true cuando el llamador emite el estado al final.
function FootballService:_QuitarDeEquipo(objetivo, _motivo, sinEmitir)
	local uid = objetivo
	local player = nil
	if esJugador(objetivo) then
		uid = objetivo.UserId
		player = objetivo
	end
	local anterior = self.equipoDe[uid]
	if not anterior then
		return false
	end
	self.equipos[anterior][uid] = nil
	self.equipoDe[uid] = nil
	self.ingreso[uid] = nil
	self.fueraDesde[uid] = nil
	if player then
		pcall(function()
			player:SetAttribute(ATRIBUTO_EQUIPO, nil)
		end)
	end
	self.EquiposCambiados:Fire(player, nil, anterior)
	if self.partido.Estado == "EnJuego" and contar(self.equipos.A) == 0 and contar(self.equipos.B) == 0 then
		self:_TerminarPartido("Ambos equipos quedaron vacíos", true)
		return true
	end
	self:_ActualizarMarcador()
	if not sinEmitir then
		self:_EmitirEstado()
	end
	return true
end

function FootballService:Unirse(player, equipo)
	if not esJugador(player) then
		return { ok = false, error = "Jugador no válido." }
	end
	local raiz = personajeVivo(player)
	if not raiz then
		return self:_Rechazar(player, REMOTO_ACCION, "sin_personaje", "Unirse", "Necesitas estar en la cancha con tu personaje.")
	end
	local distanciaZona = Zones.DistanciaA(self.zonaId, raiz.Position)
	if distanciaZona > self.MargenZonaUnirse then
		return self:_Rechazar(player, REMOTO_ACCION, "fuera_de_zona", string.format("Unirse a %.0f studs de la cancha", distanciaZona),
			"Ve a la cancha para unirte a un equipo.")
	end
	local uid = player.UserId
	local actual = self.equipoDe[uid]
	if equipo == nil then
		equipo = self:_EquipoSugerido(actual)
	end
	if equipo ~= "A" and equipo ~= "B" then
		return self:_Rechazar(player, REMOTO_ACCION, "equipo", tostring(equipo), "Equipo no válido.")
	end
	if actual == equipo then
		return { ok = true, datos = self:Snapshot(player) }
	end
	local cantidad = contar(self.equipos[equipo])
	if cantidad >= self.JugadoresPorEquipoMax then
		return { ok = false, error = string.format("El equipo %s está completo (%d/%d).", equipo, cantidad, self.JugadoresPorEquipoMax), Codigo = "equipo_completo" }
	end
	if self.BalanceEquipos then
		local otro = otroEquipo(equipo)
		local cantidadOtro = contar(self.equipos[otro])
		if actual == otro then
			cantidadOtro = cantidadOtro - 1
		end
		if (cantidad + 1) - cantidadOtro > self.DiferenciaEquiposMax then
			return { ok = false, error = string.format("Los equipos quedarían desequilibrados; únete al equipo %s.", otro), Codigo = "desbalance" }
		end
	end
	self:_AsignarEquipo(player, equipo)
	return { ok = true, datos = self:Snapshot(player) }
end

function FootballService:Salir(player)
	if not esJugador(player) then
		return { ok = false, error = "Jugador no válido." }
	end
	if not self.equipoDe[player.UserId] then
		return { ok = false, error = "No estás en ningún equipo.", Codigo = "sin_equipo" }
	end
	self:_QuitarDeEquipo(player, "salir", false)
	return { ok = true, datos = self:Snapshot(player) }
end

---------------------------------------------------------------------------------------------------
-- Partido
---------------------------------------------------------------------------------------------------
function FootballService:_PartidoVacio()
	return {
		Id = 0, Estado = "Libre", Goles = { A = 0, B = 0 }, InicioClock = nil, InicioServidor = nil,
		Duracion = self.DuracionPartidoSeg, Origen = nil, IniciadoPor = nil, IniciadoPorNombre = nil,
		Libre = false, Participacion = {}, UltimoTick = nil,
	}
end

-- Segundos restantes del partido en curso (Duracion si no hay partido).
function FootballService:_Restante()
	local p = self.partido
	if p.Estado ~= "EnJuego" or not p.InicioClock then
		return p.Duracion or self.DuracionPartidoSeg
	end
	return math.max(0, p.Duracion - (os.clock() - p.InicioClock))
end

-- ¿Puede este jugador pedir "Iniciar"? (árbitro, o inicio libre si el contrato lo permite).
function FootballService:_PuedeIniciar(player, arbitroConectado, permiteDeporte)
	if self.partido.Estado == "EnJuego" then
		return false
	end
	if self:_EsArbitro(player) then
		return true
	end
	if not self.inicioLibreContrato then
		return false
	end
	return not arbitroConectado and permiteDeporte
end

function FootballService:Iniciar(player)
	if not esJugador(player) then
		return { ok = false, error = "Jugador no válido." }
	end
	if self.partido.Estado == "EnJuego" then
		return { ok = false, error = "Ya hay un partido en curso.", Codigo = "en_curso" }
	end
	local esArbitro = self:_EsArbitro(player)
	if not esArbitro then
		if self:_HayArbitroConectado() then
			return self:_Rechazar(player, REMOTO_ACCION, "arbitro_conectado", "Iniciar", "Hay un árbitro conectado: pídele que inicie el partido.")
		end
		if not self:_PermiteDeporte() then
			return self:_Rechazar(player, REMOTO_ACCION, "sin_deporte", "Iniciar", "Ahora no es momento de deporte (solo en descanso o almuerzo).")
		end
	end
	local minimo = self.MinJugadoresPorEquipo
	if contar(self.equipos.A) < minimo or contar(self.equipos.B) < minimo then
		return { ok = false, error = string.format("Cada equipo necesita al menos %d jugador(es).", minimo), Codigo = "faltan_jugadores" }
	end
	local origen = "Libre"
	if esArbitro then
		origen = "Arbitro"
	end
	self:_IniciarPartido(origen, player)
	return { ok = true, datos = self:Snapshot(player) }
end

-- Duración del partido. Uno sin árbitro ("Libre"/"Automatico") termina al acabar el periodo con deporte, así
-- que se recorta a lo que queda del periodo (si la jornada corre): así puede terminar por tiempo y repartir la
-- recompensa (con 300 s fijos, un partido del DESCANSO de 150 s nunca llegaba al 50 % exigido).
function FootballService:_DuracionPartido(origen)
	local duracion = self.DuracionPartidoSeg
	if origen == "Arbitro" then
		return duracion
	end
	local SchoolDay = self:_Servicio("SchoolDayService")
	if not SchoolDay or typeof(SchoolDay.Snapshot) ~= "function" then
		return duracion
	end
	local ok, snap = pcall(SchoolDay.Snapshot, SchoolDay)
	if not ok or typeof(snap) ~= "table" or snap.Pausada == true then
		return duracion
	end
	local restante = tonumber(snap.Restante)
	if not esFinito(restante) or restante <= 0 then
		return duracion
	end
	return math.max(self.DuracionLibreMinSeg, math.min(duracion, math.floor(restante - 1)))
end

function FootballService:_IniciarPartido(origen, player)
	self.contadorPartidos = self.contadorPartidos + 1
	local ahora = os.clock()
	self.partido = {
		Id = self.contadorPartidos, Estado = "EnJuego", Goles = { A = 0, B = 0 },
		InicioClock = ahora, InicioServidor = servidorAhora(), Duracion = self:_DuracionPartido(origen),
		Origen = origen, IniciadoPor = player and player.UserId or nil,
		IniciadoPorNombre = player and player.DisplayName or nil,
		Libre = origen ~= "Arbitro", Participacion = {}, UltimoTick = ahora,
	}
	self.ultimoResultado = nil
	self.ultimoGolClock = -math.huge
	self.autoInicioClock = nil
	self.autoInicioServidor = nil
	self:_CancelarReinicio()
	if not self.activo then
		self:_Activar()
	end
	self:_RecolocarBalon("inicio")
	self.estadisticas.Partidos = self.estadisticas.Partidos + 1
	self:_Registrar("Sistema", player, "PartidoIniciado", string.format("Partido %d (%s) · A %d vs B %d jugadores · %d s",
		self.partido.Id, tostring(origen), contar(self.equipos.A), contar(self.equipos.B), self.partido.Duracion))
	self:_EnviarCancha({
		Sub = "Inicio", Origen = origen, Duracion = self.partido.Duracion, InicioServidor = self.partido.InicioServidor,
		IniciadoPor = self.partido.IniciadoPorNombre,
	})
	self:_ActualizarMarcador()
	self:_EmitirEstado()
	self.PartidoIniciado:Fire(self:Estado())
end

function FootballService:Reiniciar(player)
	if esJugador(player) and not self:_EsArbitro(player) then
		return self:_Rechazar(player, REMOTO_ACCION, "permiso", "Reiniciar", "Solo un árbitro puede reiniciar el partido.")
	end
	local p = self.partido
	if p.Estado == "EnJuego" then
		local ahora = os.clock()
		p.Goles = { A = 0, B = 0 }
		p.InicioClock = ahora
		p.InicioServidor = servidorAhora()
		p.Participacion = {}
		p.UltimoTick = ahora
		self.ultimoGolClock = -math.huge
		self:_CancelarReinicio()
		self:_RecolocarBalon("reinicio")
		self:_EnviarCancha({ Sub = "Reinicio", Duracion = p.Duracion, InicioServidor = p.InicioServidor })
	else
		self.partido = self:_PartidoVacio()
		self.ultimoResultado = nil
		self:_CancelarReinicio()
		self:_RecolocarBalon("reinicio")
	end
	self:_Registrar("Sistema", player, "PartidoReiniciado", "Marcador y reloj a cero")
	self:_ActualizarMarcador()
	self:_EmitirEstado()
	return { ok = true, datos = self:Snapshot(player) }
end

function FootballService:Finalizar(player)
	if esJugador(player) and not self:_EsArbitro(player) then
		return self:_Rechazar(player, REMOTO_ACCION, "permiso", "Finalizar", "Solo un árbitro puede finalizar el partido.")
	end
	if self.partido.Estado ~= "EnJuego" then
		return { ok = false, error = "No hay ningún partido en curso.", Codigo = "sin_partido" }
	end
	local nombre = esJugador(player) and player.DisplayName or "el sistema"
	self:_TerminarPartido("Finalizado por " .. nombre, false)
	return { ok = true, datos = self:Snapshot(player) }
end

-- Suma el tiempo transcurrido desde el último tick a cada miembro de equipo que está en la cancha.
function FootballService:_SumarParticipacion(ahora)
	local p = self.partido
	local dt = math.clamp(ahora - (p.UltimoTick or ahora), 0, 2)
	p.UltimoTick = ahora
	if dt <= 0 then
		return
	end
	for uid in pairs(self.equipoDe) do
		local player = Players:GetPlayerByUserId(uid)
		if player and self.enCancha[player] then
			p.Participacion[uid] = (p.Participacion[uid] or 0) + dt
		end
	end
end

function FootballService:_AvanzarPartido(ahora)
	self:_SumarParticipacion(ahora)
	if self:_Restante() <= 0 then
		self:_TerminarPartido("Tiempo cumplido", false)
	end
end

-- Cierra el partido en curso: resultado, recompensas, marcador y aviso. Devuelve true si había partido.
function FootballService:_TerminarPartido(motivo, sinRecompensa)
	local p = self.partido
	if p.Estado ~= "EnJuego" then
		return false
	end
	local ahora = os.clock()
	self:_SumarParticipacion(ahora)
	local transcurrido = math.min(ahora - (p.InicioClock or ahora), p.Duracion)
	local golesA, golesB = p.Goles.A, p.Goles.B
	local ganador = "Empate"
	if golesA > golesB then
		ganador = "A"
	elseif golesB > golesA then
		ganador = "B"
	end
	local recompensa = tonumber(ECO.Recompensas and ECO.Recompensas.Partido) or 0
	local fraccion = self.FraccionParticipacionMin
	local merece = sinRecompensa ~= true and recompensa > 0 and transcurrido >= p.Duracion * fraccion
	local premiados = {}
	if merece then
		for uid in pairs(self.equipoDe) do
			local jugador = Players:GetPlayerByUserId(uid)
			if jugador and (p.Participacion[uid] or 0) >= transcurrido * fraccion then
				table.insert(premiados, jugador)
			end
		end
	end
	local montoPremio = 0
	if merece then
		montoPremio = recompensa
	end
	local resultado = {
		Id = p.Id, Goles = { A = golesA, B = golesB }, Ganador = ganador, Motivo = tostring(motivo or ""),
		Duracion = math.floor(transcurrido + 0.5), Premiados = #premiados, Recompensa = montoPremio, T = os.time(),
	}
	self.ultimoResultado = resultado
	p.Estado = "Terminado"
	p.FinClock = ahora
	self.finPartidoClock = ahora
	self.autoInicioClock = nil
	self.autoInicioServidor = nil

	self:_Acreditar(premiados, recompensa, resultado)
	self:_Registrar("Sistema", nil, "PartidoTerminado", string.format("Partido %d: A %d - %d B (%s) · %s · %d s · %d premiados",
		p.Id, golesA, golesB, ganador, resultado.Motivo, resultado.Duracion, #premiados))
	self:_EnviarCancha({
		Sub = "Fin", Ganador = ganador, Marcador = { A = golesA, B = golesB }, Motivo = resultado.Motivo,
		Recompensa = montoPremio, Premiados = #premiados,
	})
	self:_ActualizarMarcador()
	self:_EmitirEstado()
	self.PartidoTerminado:Fire(copiarTabla(resultado))
	return true
end

function FootballService:_Acreditar(premiados, monto, resultado)
	if #premiados == 0 or monto <= 0 then
		return
	end
	local Economy = self:_Servicio("EconomyService")
	if not Economy or typeof(Economy.Acreditar) ~= "function" then
		self:_AvisarError("economia", "EconomyService no disponible; no se acreditó la recompensa del partido.")
		return
	end
	local detalle = string.format("Partido de fútbol A %d - %d B", resultado.Goles.A, resultado.Goles.B)
	for _, jugador in ipairs(premiados) do
		task.spawn(function()
			-- Acreditar devuelve ok, saldoOError, acreditado (puede ser parcial por el límite diario).
			local ok, exito, saldo, acreditado = pcall(Economy.Acreditar, Economy, jugador, monto, "Partido", detalle)
			if not ok then
				self:_AvisarError("acreditar", exito)
			elseif exito then
				local cantidad = tonumber(acreditado) or monto
				if cantidad > 0 then
					self:_Notificar(jugador, string.format("+%s por jugar el partido.", Format.Moneda(cantidad)), "exito")
				end
			elseif saldo ~= "limite_diario" then
				-- El límite diario ya lo avisa EconomyService; el resto se explica sin códigos internos.
				self:_Notificar(jugador, "No se pudo acreditar la recompensa del partido; inténtalo más tarde.", "aviso")
				self:_Registrar("Economia", jugador, "RecompensaPartido", "no acreditada: " .. tostring(saldo))
			end
		end)
	end
end

-- Cuenta atrás de inicio automático (sin árbitro conectado y con deporte permitido). true si hubo cambios.
function FootballService:_RevisarAutoInicio(ahora)
	if not self.AutoInicio or self.partido.Estado == "EnJuego" then
		if self.autoInicioClock then
			self.autoInicioClock = nil
			self.autoInicioServidor = nil
			return true
		end
		return false
	end
	local minimo = self.MinJugadoresPorEquipo
	local condiciones = contar(self.equipos.A) >= minimo and contar(self.equipos.B) >= minimo
		and ahora - self.finPartidoClock >= self.PausaTrasPartidoSeg
		and not self:_HayArbitroConectado() and self:_PermiteDeporte()
	if condiciones then
		if not self.autoInicioClock then
			self.autoInicioClock = ahora + self.AutoInicioSeg
			self.autoInicioServidor = servidorAhora() + self.AutoInicioSeg
			return true
		end
		if ahora >= self.autoInicioClock then
			self.autoInicioClock = nil
			self.autoInicioServidor = nil
			self:_IniciarPartido("Automatico", nil)
		end
		return false
	end
	if self.autoInicioClock then
		self.autoInicioClock = nil
		self.autoInicioServidor = nil
		return true
	end
	return false
end

---------------------------------------------------------------------------------------------------
-- Estado y envío a clientes
---------------------------------------------------------------------------------------------------

-- Estado público de la cancha (sin datos del jugador).
function FootballService:Estado()
	local p = self.partido
	local listaA = self:_ListaEquipo("A")
	local listaB = self:_ListaEquipo("B")
	return {
		Estado = p.Estado, -- "Libre" | "EnJuego" | "Terminado"
		PartidoId = p.Id,
		Marcador = { A = p.Goles.A, B = p.Goles.B },
		InicioServidor = p.InicioServidor,
		Duracion = p.Duracion,
		Restante = self:_Restante(),
		Origen = p.Origen,
		IniciadoPor = p.IniciadoPorNombre,
		Equipos = { A = listaA, B = listaB },
		Conteo = { A = #listaA, B = #listaB },
		MaxPorEquipo = self.JugadoresPorEquipoMax,
		ArbitroConectado = self:_HayArbitroConectado(),
		PermiteDeporte = self:_PermiteDeporte(),
		InicioLibrePermitido = self.inicioLibreContrato,
		AutoInicio = self.AutoInicio,
		AutoInicioServidor = self.autoInicioServidor,
		UltimoResultado = copiarTabla(self.ultimoResultado),
		Activo = self.activo,
		ReinicioPendiente = self.reinicioPendiente,
		ZonaId = self.zonaId,
		DistanciaPatada = self.DistanciaPatada,
		CooldownPatada = self.CooldownPatada,
		HoraServidor = servidorAhora(),
	}
end

-- Estado para un jugador concreto: añade MiEquipo, EsArbitro y PuedeIniciar. 'base' (opcional) es un Estado()
-- ya calculado: se copia en superficie para no recalcularlo por cada destinatario.
function FootballService:Snapshot(player, base)
	local estado = nil
	if typeof(base) == "table" then
		estado = {}
		for clave, valor in pairs(base) do
			estado[clave] = valor
		end
	else
		estado = self:Estado()
	end
	if esJugador(player) then
		estado.MiEquipo = self.equipoDe[player.UserId]
		estado.EsArbitro = self:_EsArbitro(player)
		estado.PuedeIniciar = self:_PuedeIniciar(player, estado.ArbitroConectado, estado.PermiteDeporte)
	end
	return estado
end

-- Jugadores en la cancha más los miembros de equipo (aunque estén fuera).
function FootballService:_Destinatarios()
	local lista = {}
	local vistos = {}
	local RemoteService = self:_Servicio("RemoteService")
	local enZona = nil
	if RemoteService and typeof(RemoteService.JugadoresEnZona) == "function" then
		local ok, resultado = pcall(RemoteService.JugadoresEnZona, RemoteService, self.zonaId)
		if ok and typeof(resultado) == "table" then
			enZona = resultado
		end
	end
	if not enZona then
		enZona = self:JugadoresEnCancha()
	end
	for _, player in ipairs(enZona) do
		if not vistos[player] then
			vistos[player] = true
			table.insert(lista, player)
		end
	end
	for uid in pairs(self.equipoDe) do
		local player = Players:GetPlayerByUserId(uid)
		if player and not vistos[player] then
			vistos[player] = true
			table.insert(lista, player)
		end
	end
	return lista
end

-- Agrupa varios cambios del mismo frame en un único envío de "Estado".
function FootballService:_EmitirEstado()
	if self.emisionPendiente then
		return
	end
	self.emisionPendiente = true
	task.defer(function()
		self.emisionPendiente = false
		local ok, err = pcall(function()
			local RemoteService = self:_Servicio("RemoteService")
			if not RemoteService or typeof(RemoteService.Enviar) ~= "function" then
				return
			end
			-- Estado() (equipos, árbitro conectado...) se calcula una vez; por jugador solo se añaden sus campos.
			local base = self:Estado()
			for _, player in ipairs(self:_Destinatarios()) do
				RemoteService:Enviar(player, "Futbol", { Sub = "Estado", Estado = self:Snapshot(player, base) })
			end
		end)
		if not ok then
			self:_AvisarError("estado", err)
		end
	end)
end

function FootballService:_EnviarEstadoA(player)
	local RemoteService = self:_Servicio("RemoteService")
	if RemoteService and typeof(RemoteService.Enviar) == "function" then
		pcall(RemoteService.Enviar, RemoteService, player, "Futbol", { Sub = "Estado", Estado = self:Snapshot(player) })
	end
end

-- Evento "Futbol" a los jugadores que están en la cancha.
function FootballService:_EnviarCancha(datos)
	local RemoteService = self:_Servicio("RemoteService")
	if RemoteService and typeof(RemoteService.EnviarAZona) == "function" then
		pcall(RemoteService.EnviarAZona, RemoteService, self.zonaId, "Futbol", datos)
	end
end

