-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function ModerationService:Init(registro)
	self.registro = registro
	self.Silencios = {} -- userId -> { Id, Hasta, Desde, Motivo, PorUserId, PorNombre }
	self.FuentesSilenciadas = {} -- userId -> { [TextSource] = CanSend original }
	self.Bloqueos = {} -- userId -> { Hasta, Motivo } (respaldo en memoria del bloqueo temporal)
	self.AdvertenciasMemoria = {} -- userId -> número de advertencias si el perfil no estaba disponible
	self.Tokens = {} -- token -> { Accion, AdminUserId, ObjetivoUserId, Motivo, DuracionSeg, Cargo, Expira, Creado }
	self.Registros = {} -- acciones de moderación (la más reciente al final)
	self.UltimaAccion = {} -- "admin:accion:objetivo" -> os.clock()
	self.CacheAdonis = {} -- userId -> { Valor, T }
	self.Maids = {} -- userId -> Maid
	self.Conexiones = {}
	self.ContadorSilencios = 0
	self.ContadorRegistro = 0
	self.Activo = true
	self.ChatModerno = false
	self.TextChatService = nil
	self.AccionAplicada = Signal.new() -- (accion, admin|nil, objetivoUserId, info)
end

function ModerationService:Start()
	local RemoteService = self:Servicio("RemoteService")
	if RemoteService and typeof(RemoteService.Registrar) == "function" then
		RemoteService:Registrar("ModerationAction", function(player, datos)
			return self:ManejarAccion(player, datos)
		end)
	else
		warn(PREFIJO .. " RemoteService no disponible: ModerationAction no tendrá handler.")
	end

	local okChat, errChat = pcall(function()
		self:PrepararChat()
	end)
	if not okChat then
		warn(PREFIJO .. " No se pudo preparar TextChatService: " .. tostring(errChat))
	end

	table.insert(self.Conexiones, Players.PlayerAdded:Connect(function(player)
		self:AlEntrar(player)
	end))
	table.insert(self.Conexiones, Players.PlayerRemoving:Connect(function(player)
		self:AlSalir(player)
	end))
	for _, player in ipairs(Players:GetPlayers()) do
		self:AlEntrar(player)
	end

	task.spawn(function()
		while self.Activo do
			task.wait(self.BarridoSeg)
			local ok, err = pcall(function()
				self:Barrido()
			end)
			if not ok then
				warn(PREFIJO .. " Error en el barrido: " .. tostring(err))
			end
		end
	end)
end

-- Servicio por nombre a través del registro (nil si no existe).
function ModerationService:Servicio(nombre)
	local registro = self.registro
	if registro and typeof(registro.Get) == "function" then
		return registro.Get(nombre)
	end
	return nil
end

-- Llama servicio:metodo(...) en pcall si existe. Devuelve ok, r1, r2 (ok = false si no existe o falló).
function ModerationService:Llamar(nombreServicio, metodo, ...)
	local servicio = self:Servicio(nombreServicio)
	if not servicio or typeof(servicio[metodo]) ~= "function" then
		return false, nil, nil
	end
	local resultado = table.pack(pcall(servicio[metodo], servicio, ...))
	if not resultado[1] then
		warn(PREFIJO .. " " .. nombreServicio .. ":" .. metodo .. "() falló: " .. tostring(resultado[2]))
		return false, nil, nil
	end
	return true, resultado[2], resultado[3]
end

function ModerationService:Auditar(admin, accion, detalle)
	self:Llamar("AuditLogService", "Registrar", "Moderacion", admin, accion, detalle)
end

function ModerationService:Enviar(player, tipo, datos)
	if not esJugador(player) or player.Parent == nil then
		return false
	end
	local ok, enviado = self:Llamar("RemoteService", "Enviar", player, tipo, datos)
	return ok and enviado == true
end

function ModerationService:Notificar(player, titulo, texto, nivel, duracion)
	return self:Enviar(player, "Notificacion", {
		Titulo = titulo, Texto = texto, Nivel = nivel or "info", Tipo = nivel or "info", Duracion = duracion,
	})
end

---------------------------------------------------------------------------------------------------
-- Entrada y salida de jugadores
---------------------------------------------------------------------------------------------------
function ModerationService:AlEntrar(player)
	if not esJugador(player) then
		return
	end
	local userId = player.UserId
	if self.Maids[userId] then
		self.Maids[userId]:DoCleaning()
	end
	local maid = Maid.new()
	self.Maids[userId] = maid

	-- Bloqueo en memoria de este servidor (inmediato, sin esperar al perfil).
	local bloqueo = self.Bloqueos[userId]
	if bloqueo and bloqueo.Hasta > os.time() then
		self:ExpulsarPorBloqueo(player, bloqueo.Hasta)
		return
	end

	-- Silencio vigente al reconectar en el mismo servidor.
	local silencio = self:SilencioActivo(userId)
	if silencio then
		pcall(function()
			player:SetAttribute("Silenciado", true)
			player:SetAttribute("SilenciadoHasta", silencio.Hasta)
		end)
		self:AplicarSilencioChat(userId, true)
	end

	-- Bloqueo temporal guardado en el perfil.
	maid:GiveTask(task.spawn(function()
		local ok, perfil = self:Llamar("DataService", "EsperarPerfil", player, self.EsperaPerfilSeg)
		if not ok or typeof(perfil) ~= "table" or player.Parent == nil or self.Maids[userId] ~= maid then
			return
		end
		local moderacion = perfil.Moderacion
		local hasta = typeof(moderacion) == "table" and tonumber(moderacion.BloqueoHasta) or 0
		if hasta and hasta > os.time() then
			self:ExpulsarPorBloqueo(player, hasta)
		end
	end))
end

function ModerationService:AlSalir(player)
	local userId = player.UserId
	local maid = self.Maids[userId]
	if maid then
		self.Maids[userId] = nil
		maid:DoCleaning()
	end
	-- Las TextSource del jugador desaparecen con él; el silencio se conserva por si vuelve a entrar.
	self.FuentesSilenciadas[userId] = nil
	self.CacheAdonis[userId] = nil
	for token, entrada in pairs(self.Tokens) do
		if entrada.AdminUserId == userId then
			self.Tokens[token] = nil
		end
	end
end

function ModerationService:ExpulsarPorBloqueo(player, hasta)
	local restante = math.max(1, hasta - os.time())
	self:Auditar(player, "BloqueoVigente", "expulsado al entrar; quedan " .. Format.Duracion(restante))
	local mensaje = "Tienes un bloqueo temporal de moderación en Colegio RP. Podrás volver a entrar en "
		.. Format.Duracion(restante) .. "."
	task.defer(function()
		if player.Parent ~= nil then
			pcall(player.Kick, player, mensaje)
		end
	end)
end

-- Barrido periódico: silencios caducados, tokens vencidos, bloqueos en memoria y anti-repetición.
function ModerationService:Barrido()
	local ahora = os.time()
	for userId, silencio in pairs(self.Silencios) do
		if silencio.Hasta <= ahora then
			self:FinalizarSilencio(userId, nil, "caducado")
		end
	end
	self:PurgarTokens()
	for userId, bloqueo in pairs(self.Bloqueos) do
		if bloqueo.Hasta <= ahora then
			self.Bloqueos[userId] = nil
		end
	end
	local reloj = os.clock()
	for clave, t in pairs(self.UltimaAccion) do
		if reloj - t > 60 then
			self.UltimaAccion[clave] = nil
		end
	end
end

---------------------------------------------------------------------------------------------------
-- Permisos, jerarquía y Adonis
---------------------------------------------------------------------------------------------------

-- ¿Es administrador de Adonis? Solo lectura, nunca lanza, con caché corta. Requiere Config.Autorizaciones.UsarAdonis.
function ModerationService:EsAdminAdonis(player)
	if AUT.UsarAdonis ~= true or not esJugador(player) then
		return false
	end
	local cache = self.CacheAdonis[player.UserId]
	if cache and os.clock() - cache.T < self.CacheAdonisSeg then
		return cache.Valor
	end
	local ok, resultado = pcall(function()
		local adonis = _G.Adonis
		return type(adonis) == "table" and type(adonis.CheckAdmin) == "function" and adonis.CheckAdmin(player) == true
	end)
	local valor = ok and resultado == true
	self.CacheAdonis[player.UserId] = { Valor = valor, T = os.clock() }
	return valor
end

-- Permiso adicional que concede la moderación (admins de Adonis -> moderacion.basica).
-- Pensado para que RoleService:Tiene lo consulte (ver pendientes); no concede nada más.
function ModerationService:PermisoExtra(player, permiso)
	return permiso == "moderacion.basica" and self:EsAdminAdonis(player)
end

-- ¿El jugador tiene el permiso? (cargo vía RoleService o permiso extra de Adonis).
function ModerationService:TienePermiso(player, permiso)
	if not esJugador(player) or typeof(permiso) ~= "string" then
		return false
	end
	local ok, tiene = self:Llamar("RoleService", "Tiene", player, permiso)
	if ok and tiene == true then
		return true
	end
	return self:PermisoExtra(player, permiso)
end

-- Cargo del jugador (RoleService o atributo replicado).
function ModerationService:CargoDe(player)
	local ok, cargo = self:Llamar("RoleService", "Cargo", player)
	if ok and typeof(cargo) == "string" then
		return cargo
	end
	local atributo = esJugador(player) and player:GetAttribute("Cargo") or nil
	if typeof(atributo) == "string" then
		return atributo
	end
	return "Estudiante"
end

-- Rango de moderación: Director 4 > Subdirector 3 > Coordinadores 2 > resto 1.
function ModerationService:Rango(player)
	return RANGO_CARGO[self:CargoDe(player)] or RANGO_RESTO
end

-- ¿Puede admin actuar sobre objetivo? admin nil = sistema (siempre). Devuelve ok, mensaje, codigo.
function ModerationService:PuedeActuar(admin, objetivo)
	if admin == nil then
		return true
	end
	if not esJugador(admin) or not esJugador(objetivo) then
		return false, "Jugador no válido.", "jugador_invalido"
	end
	if admin == objetivo then
		return false, "No puedes aplicarte esta acción a ti mismo/a.", "propio"
	end
	-- Ni superiores ni iguales (dos Directores o dos Coordinadores no se moderan entre sí).
	if self:Rango(objetivo) >= self:Rango(admin) then
		return false, "No puedes actuar sobre alguien con un cargo igual o superior al tuyo.", "objetivo_superior"
	end
	return true
end

-- Comprobaciones comunes de la API interna cuando la llama un jugador. Devuelve objetivo | nil, mensaje.
function ModerationService:Comprobar(admin, objetivo, accion, permisos)
	objetivo = resolverJugador(objetivo)
	if not objetivo or objetivo.Parent == nil then
		return nil, "El jugador no está conectado."
	end
	if admin ~= nil then
		if not esJugador(admin) then
			return nil, "Administrador no válido."
		end
		local autorizado = false
		for _, permiso in ipairs(permisos) do
			if self:TienePermiso(admin, permiso) then
				autorizado = true
			end
		end
		if not autorizado then
			self:Auditar(admin, "Rechazo:" .. accion, "sin permiso · objetivo " .. objetivo.Name .. "(" .. objetivo.UserId .. ")")
			return nil, "No tienes permiso para esta acción."
		end
		local puede, mensaje, codigo = self:PuedeActuar(admin, objetivo)
		if not puede then
			self:Auditar(admin, "Rechazo:" .. accion, tostring(codigo) .. " · objetivo " .. objetivo.Name .. "(" .. objetivo.UserId .. ")")
			return nil, mensaje
		end
	end
	return objetivo
end

---------------------------------------------------------------------------------------------------
-- Texto y duraciones
---------------------------------------------------------------------------------------------------

-- Motivo saneado y filtrado (lo verá el objetivo). Devuelve motivo, okFiltro.
function ModerationService:FiltrarMotivo(texto, autor)
	local limpio = limpiarLinea(texto, self.MaxMotivo)
	if limpio == nil then
		return self.TextoNoDisponible, false
	end
	if limpio == "" or not esJugador(autor) then
		return limpio, true
	end
	local okFiltro, resultado = pcall(function()
		return TextService:FilterStringAsync(limpio, autor.UserId, Enum.TextFilterContext.PublicChat)
	end)
	if not okFiltro or resultado == nil then
		return self.TextoNoDisponible, false
	end
	local okTexto, filtrado = pcall(function()
		return resultado:GetNonChatStringForBroadcastAsync()
	end)
	if not okTexto or typeof(filtrado) ~= "string" then
		return self.TextoNoDisponible, false
	end
	return filtrado, true
end

-- Motivo de una petición de remoto: obligatorio en sanciones, por defecto en el resto. Devuelve motivo | nil, error.
function ModerationService:PrepararMotivo(admin, motivo, accion)
	local limpio = limpiarLinea(motivo or "", self.MaxMotivo)
	if limpio == nil then
		return nil, "El motivo no es un texto válido."
	end
	if limpio == "" or Format.Longitud(limpio) < self.MinMotivo then
		if self.MotivoObligatorio[accion] then
			return nil, "Escribe un motivo de al menos " .. self.MinMotivo .. " caracteres."
		end
		if limpio == "" then
			return self.MotivoPorDefecto[accion] or "Sin motivo indicado"
		end
	end
	local filtrado = self:FiltrarMotivo(limpio, admin)
	return filtrado
end

function ModerationService:Duracion(accion, valor)
	local defecto = self.DuracionMuteSeg
	if accion == "BloquearTemporal" then
		defecto = self.DuracionBloqueoSeg
	end
	local n = tonumber(valor)
	if n == nil or n ~= n then
		n = defecto
	end
	return math.clamp(math.floor(n), self.DuracionMinSeg, self.DuracionMaxSeg)
end

---------------------------------------------------------------------------------------------------
-- Registro en memoria y auditoría de acciones aplicadas
---------------------------------------------------------------------------------------------------
function ModerationService:Anotar(admin, objetivo, accion, motivo, extra)
	self.ContadorRegistro = self.ContadorRegistro + 1
	local entrada = {
		Id = self.ContadorRegistro,
		T = os.time(),
		Accion = accion,
		Tipo = self.Etiquetas[accion] or accion,
		AdminUserId = userIdDe(admin) or 0,
		Autor = nombreDe(admin),
		ObjetivoUserId = userIdDe(objetivo) or 0,
		Jugador = esJugador(objetivo) and objetivo.Name or tostring(userIdDe(objetivo) or "?"),
		Nombre = esJugador(objetivo) and objetivo.DisplayName or nil,
		Motivo = motivo or "",
	}
	if typeof(extra) == "table" then
		for clave, valor in pairs(extra) do
			local tipo = typeof(valor)
			if tipo == "string" or tipo == "number" or tipo == "boolean" then
				entrada[clave] = valor
			end
		end
	end
	table.insert(self.Registros, entrada)
	while #self.Registros > self.MaxRegistro do
		table.remove(self.Registros, 1)
	end
	local detalle = string.format("objetivo=%s(%s) · motivo=%s", entrada.Jugador, tostring(entrada.ObjetivoUserId), entrada.Motivo)
	if entrada.DuracionSeg then
		detalle = detalle .. " · duración=" .. Format.Duracion(entrada.DuracionSeg)
	end
	if entrada.Cargo then
		detalle = detalle .. " · cargo=" .. tostring(entrada.Cargo)
	end
	if admin == nil then
		detalle = detalle .. " · por=Sistema"
	end
	self:Auditar(admin, accion, detalle)
	local ok, err = pcall(function()
		self.AccionAplicada:Fire(accion, admin, entrada.ObjetivoUserId, copiaPlana(entrada))
	end)
	if not ok then
		warn(PREFIJO .. " Error en un oyente de AccionAplicada: " .. tostring(err))
	end
	return entrada
end

-- Últimas n acciones de moderación (la más reciente primero). filtroUserId opcional (objetivo o autor).
function ModerationService:Registro(n, filtroUserId)
	n = math.clamp(math.floor(tonumber(n) or 50), 1, self.MaxRegistro)
	local lista = {}
	for i = #self.Registros, 1, -1 do
		if #lista >= n then
			break
		end
		local entrada = self.Registros[i]
		if filtroUserId == nil or entrada.ObjetivoUserId == filtroUserId or entrada.AdminUserId == filtroUserId then
			table.insert(lista, copiaPlana(entrada))
		end
	end
	return lista
end

---------------------------------------------------------------------------------------------------
-- Silencio (TextChatService + atributo)
---------------------------------------------------------------------------------------------------
function ModerationService:PrepararChat()
	local okServicio, tcs = pcall(game.GetService, game, "TextChatService")
	if not okServicio or not tcs then
		warn(PREFIJO .. " TextChatService no disponible: el silencio se aplica solo con el atributo Silenciado.")
		return
	end
	self.TextChatService = tcs
	local okVersion, version = pcall(function()
		return tcs.ChatVersion
	end)
	self.ChatModerno = okVersion and version == Enum.ChatVersion.TextChatService
	if not self.ChatModerno then
		warn(PREFIJO .. " El lugar usa el chat heredado (ChatVersion ~= TextChatService): el silencio se aplica solo con el atributo Silenciado.")
		return
	end
	-- Fuentes nuevas (canales creados o usuarios añadidos después del silencio).
	table.insert(self.Conexiones, tcs.DescendantAdded:Connect(function(descendiente)
		if descendiente:IsA("TextSource") then
			task.defer(function()
				self:AplicarFuente(descendiente)
			end)
		end
	end))
end

-- Canales afectados por el silencio: todos los TextChannel salvo los susurros (RBXWhisper...).
local function esCanalSilenciable(canal)
	if typeof(canal) ~= "Instance" or not canal:IsA("TextChannel") then
		return false
	end
	return string.sub(canal.Name, 1, 10) ~= "RBXWhisper"
end

-- TextSource del usuario en canales silenciables.
function ModerationService:FuentesDe(userId)
	local fuentes = {}
	local tcs = self.TextChatService
	if not tcs or not self.ChatModerno then
		return fuentes
	end
	local ok, descendientes = pcall(tcs.GetDescendants, tcs)
	if not ok then
		return fuentes
	end
	for _, d in ipairs(descendientes) do
		if d:IsA("TextSource") and d.UserId == userId and esCanalSilenciable(d.Parent) then
			table.insert(fuentes, d)
		end
	end
	return fuentes
end

function ModerationService:SilenciarFuente(userId, fuente)
	local registro = self.FuentesSilenciadas[userId]
	if not registro then
		registro = {}
		self.FuentesSilenciadas[userId] = registro
	end
	if registro[fuente] ~= nil then
		return
	end
	local okLeer, original = pcall(function()
		return fuente.CanSend
	end)
	local ok = pcall(function()
		fuente.CanSend = false
	end)
	if ok then
		registro[fuente] = not (okLeer and original == false)
	end
end

-- Aplica el silencio a una TextSource recién creada si su usuario está silenciado.
function ModerationService:AplicarFuente(fuente)
	if not self.ChatModerno or fuente.Parent == nil or not esCanalSilenciable(fuente.Parent) then
		return
	end
	local okId, userId = pcall(function()
		return fuente.UserId
	end)
	if okId and typeof(userId) == "number" and self:SilencioActivo(userId) then
		self:SilenciarFuente(userId, fuente)
	end
end

-- silenciar = true fija CanSend=false en las fuentes del usuario; false restaura su valor original.
-- Devuelve el número de fuentes tocadas.
function ModerationService:AplicarSilencioChat(userId, silenciar)
	if not self.ChatModerno then
		return 0
	end
	local cantidad = 0
	if silenciar then
		for _, fuente in ipairs(self:FuentesDe(userId)) do
			self:SilenciarFuente(userId, fuente)
			cantidad = cantidad + 1
		end
		return cantidad
	end
	local registro = self.FuentesSilenciadas[userId]
	self.FuentesSilenciadas[userId] = nil
	if registro then
		for fuente, original in pairs(registro) do
			if fuente.Parent ~= nil then
				pcall(function()
					fuente.CanSend = original
				end)
				cantidad = cantidad + 1
			end
		end
	end
	return cantidad
end

-- Silencio vigente del usuario (tabla) o nil; los caducados se levantan aquí mismo.
function ModerationService:SilencioActivo(userId)
	local silencio = self.Silencios[userId]
	if not silencio then
		return nil
	end
	if silencio.Hasta <= os.time() then
		self:FinalizarSilencio(userId, nil, "caducado")
		return nil
	end
	return silencio
end

-- ¿Está silenciado? (Player o userId)
function ModerationService:EstaSilenciado(player)
	local userId = userIdDe(player)
	if not userId then
		return false
	end
	return self:SilencioActivo(userId) ~= nil
end

-- Levanta el silencio (admin nil = sistema). origen: "caducado" | "manual".
function ModerationService:FinalizarSilencio(userId, admin, origen)
	local silencio = self.Silencios[userId]
	if not silencio then
		return false
	end
	self.Silencios[userId] = nil
	self:AplicarSilencioChat(userId, false)
	local player = Players:GetPlayerByUserId(userId)
	if player then
		pcall(function()
			player:SetAttribute("Silenciado", nil)
			player:SetAttribute("SilenciadoHasta", nil)
		end)
		self:Enviar(player, "Moderacion", { Sub = "Silenciado", Activo = false, Origen = origen })
		local texto = "Tu silencio ha terminado. Ya puedes volver a escribir en el chat."
		if origen == "manual" then
			texto = "Moderación ha retirado tu silencio. Ya puedes volver a escribir en el chat."
		end
		self:Notificar(player, "Moderación", texto, "info")
	end
	if origen == "caducado" then
		self:Auditar(player or userId, "SilencioCaducado", "fin del silencio de " .. Format.Duracion(os.time() - (silencio.Desde or os.time())))
	end
	return true
end

-- Silencia a objetivo durante seg segundos. Devuelve true, info | false, mensaje.
-- opciones.YaFiltrado = true evita volver a filtrar el motivo.
function ModerationService:Silenciar(admin, objetivo, seg, motivo, opciones)
	opciones = typeof(opciones) == "table" and opciones or {}
	local jugador, err = self:Comprobar(admin, objetivo, "Silenciar", { "moderacion.basica" })
	if not jugador then
		return false, err
	end
	local duracion = self:Duracion("Silenciar", seg)
	local texto = motivo
	if not opciones.YaFiltrado then
		texto = self:FiltrarMotivo(motivo or "", admin)
	end
	if typeof(texto) ~= "string" or texto == "" then
		texto = "Sin motivo indicado"
	end
	local userId = jugador.UserId
	self.ContadorSilencios = self.ContadorSilencios + 1
	local id = self.ContadorSilencios
	local ahora = os.time()
	local hasta = ahora + duracion
	local anterior = self.Silencios[userId]
	self.Silencios[userId] = {
		Id = id, Hasta = hasta, Desde = anterior and anterior.Desde or ahora, Motivo = texto,
		PorUserId = userIdDe(admin) or 0, PorNombre = nombreDe(admin),
	}
	pcall(function()
		jugador:SetAttribute("Silenciado", true)
		jugador:SetAttribute("SilenciadoHasta", hasta)
	end)
	local fuentes = self:AplicarSilencioChat(userId, true)
	task.delay(duracion, function()
		local actual = self.Silencios[userId]
		if actual and actual.Id == id then
			self:FinalizarSilencio(userId, nil, "caducado")
		end
	end)

	self:Enviar(jugador, "Moderacion", {
		Sub = "Silenciado", Activo = true, Hasta = hasta, DuracionSeg = duracion, Motivo = texto, Autor = nombreDe(admin),
	})
	self:Notificar(jugador, "Moderación", "Has sido silenciado/a durante " .. Format.Duracion(duracion) .. ". Motivo: " .. texto, "aviso", 10)
	self:Anotar(admin, jugador, "Silenciar", texto, { DuracionSeg = duracion, Hasta = hasta, FuentesChat = fuentes })
	return true, {
		UserId = userId, Nombre = nombreDe(jugador), Hasta = hasta, DuracionSeg = duracion,
		Chat = self.ChatModerno, FuentesChat = fuentes,
	}
end

-- Quita el silencio a objetivo. Devuelve true, info | false, mensaje.
function ModerationService:QuitarSilencio(admin, objetivo, motivo, opciones)
	opciones = typeof(opciones) == "table" and opciones or {}
	local jugador, err = self:Comprobar(admin, objetivo, "QuitarSilencio", { "moderacion.basica" })
	if not jugador then
		return false, err
	end
	if not self:SilencioActivo(jugador.UserId) then
		return false, nombreDe(jugador) .. " no está silenciado/a."
	end
	local texto = motivo
	if typeof(texto) ~= "string" or texto == "" then
		texto = self.MotivoPorDefecto.QuitarSilencio
	elseif not opciones.YaFiltrado then
		texto = self:FiltrarMotivo(texto, admin)
	end
	self:FinalizarSilencio(jugador.UserId, admin, "manual")
	self:Anotar(admin, jugador, "QuitarSilencio", texto)
	return true, { UserId = jugador.UserId, Nombre = nombreDe(jugador) }
end

-- Usuarios silenciados (lista para paneles).
function ModerationService:Silenciados()
	local lista = {}
	local ahora = os.time()
	for userId, silencio in pairs(self.Silencios) do
		if silencio.Hasta > ahora then
			local player = Players:GetPlayerByUserId(userId)
			table.insert(lista, {
				UserId = userId, Jugador = player and player.Name or tostring(userId), Nombre = player and player.DisplayName or nil,
				Hasta = silencio.Hasta, RestanteSeg = silencio.Hasta - ahora, Motivo = silencio.Motivo, Autor = silencio.PorNombre,
				Conectado = player ~= nil, Tipo = "Silenciado", T = silencio.Desde,
			})
		end
	end
	table.sort(lista, function(a, b)
		return a.Hasta < b.Hasta
	end)
	return lista
end

---------------------------------------------------------------------------------------------------
-- Expulsión, bloqueo temporal y advertencias
---------------------------------------------------------------------------------------------------

-- Expulsa a objetivo del servidor. Devuelve true, info | false, mensaje.
function ModerationService:Expulsar(admin, objetivo, motivo, opciones)
	opciones = typeof(opciones) == "table" and opciones or {}
	local jugador, err = self:Comprobar(admin, objetivo, "Expulsar", { "moderacion.avanzada" })
	if not jugador then
		return false, err
	end
	local texto = motivo
	if not opciones.YaFiltrado then
		texto = self:FiltrarMotivo(motivo or "", admin)
	end
	if typeof(texto) ~= "string" or texto == "" then
		texto = "Sin motivo indicado"
	end
	local info = { UserId = jugador.UserId, Nombre = nombreDe(jugador) }
	self:Anotar(admin, jugador, "Expulsar", texto)
	local okKick, errKick = pcall(jugador.Kick, jugador, "Expulsado por moderación: " .. texto)
	if not okKick then
		warn(PREFIJO .. " No se pudo expulsar a " .. jugador.Name .. ": " .. tostring(errKick))
		return false, "No se pudo expulsar al jugador."
	end
	return true, info
end

-- Bloquea temporalmente a objetivo (perfil Moderacion.BloqueoHasta + respaldo en memoria) y lo expulsa.
-- Devuelve true, info | false, mensaje.
function ModerationService:BloquearTemporal(admin, objetivo, seg, motivo, opciones)
	opciones = typeof(opciones) == "table" and opciones or {}
	local jugador, err = self:Comprobar(admin, objetivo, "BloquearTemporal", { "moderacion.avanzada" })
	if not jugador then
		return false, err
	end
	local duracion = self:Duracion("BloquearTemporal", seg)
	local texto = motivo
	if not opciones.YaFiltrado then
		texto = self:FiltrarMotivo(motivo or "", admin)
	end
	if typeof(texto) ~= "string" or texto == "" then
		texto = "Sin motivo indicado"
	end
	local userId = jugador.UserId
	local hasta = os.time() + duracion
	local previo = self.Bloqueos[userId]
	if previo and previo.Hasta > hasta then
		hasta = previo.Hasta
	end
	self.Bloqueos[userId] = { Hasta = hasta, Motivo = texto }

	-- Perfil: BloqueoHasta (nunca se acorta un bloqueo más largo ya vigente) y guardado inmediato.
	local persistido = false
	local okPerfil, perfil = self:Llamar("DataService", "Obtener", jugador)
	if not okPerfil or typeof(perfil) ~= "table" then
		okPerfil, perfil = self:Llamar("DataService", "EsperarPerfil", jugador, self.EsperaPerfilAccionSeg)
	end
	if okPerfil and typeof(perfil) == "table" then
		if typeof(perfil.Moderacion) ~= "table" then
			perfil.Moderacion = { Advertencias = {}, BloqueoHasta = 0 }
		end
		local actual = tonumber(perfil.Moderacion.BloqueoHasta) or 0
		if actual < hasta then
			perfil.Moderacion.BloqueoHasta = hasta
		end
		self:Llamar("DataService", "Marcar", jugador)
		local DataService = self:Servicio("DataService")
		if DataService and typeof(DataService.Guardar) == "function" then
			local okGuardar, guardado = pcall(DataService.Guardar, DataService, jugador, "bloqueo")
			persistido = okGuardar and guardado == true
		end
	end

	self:Anotar(admin, jugador, "BloquearTemporal", texto, { DuracionSeg = duracion, Hasta = hasta, Persistido = persistido })
	local mensaje = "Bloqueado temporalmente por moderación durante " .. Format.Duracion(duracion) .. ". Motivo: " .. texto
	local okKick, errKick = pcall(jugador.Kick, jugador, mensaje)
	if not okKick then
		warn(PREFIJO .. " No se pudo expulsar a " .. jugador.Name .. " tras el bloqueo: " .. tostring(errKick))
	end
	return true, { UserId = userId, Nombre = nombreDe(jugador), Hasta = hasta, DuracionSeg = duracion, Persistido = persistido }
end

-- Añade una advertencia al perfil del objetivo y se la notifica. Devuelve true, info | false, mensaje.
-- La aceptan moderacion.basica y convivencia.gestionar (StaffService la usa para los casos de convivencia).
function ModerationService:Advertir(admin, objetivo, motivo, opciones)
	opciones = typeof(opciones) == "table" and opciones or {}
	local jugador, err = self:Comprobar(admin, objetivo, "Advertir", { "moderacion.basica", "convivencia.gestionar" })
	if not jugador then
		return false, err
	end
	local texto = motivo
	if not opciones.YaFiltrado then
		texto = self:FiltrarMotivo(motivo or "", admin)
	end
	if typeof(texto) ~= "string" or texto == "" then
		return false, "Escribe el motivo de la advertencia."
	end
	local autor = esJugador(admin) and admin.Name or "Sistema"
	local userId = jugador.UserId
	local total = nil
	local enPerfil = false
	local okPerfil, perfil = self:Llamar("DataService", "Obtener", jugador)
	if not okPerfil or typeof(perfil) ~= "table" then
		okPerfil, perfil = self:Llamar("DataService", "EsperarPerfil", jugador, self.EsperaPerfilAccionSeg)
	end
	if okPerfil and typeof(perfil) == "table" then
		if typeof(perfil.Moderacion) ~= "table" then
			perfil.Moderacion = { Advertencias = {}, BloqueoHasta = 0 }
		end
		if typeof(perfil.Moderacion.Advertencias) ~= "table" then
			perfil.Moderacion.Advertencias = {}
		end
		local lista = perfil.Moderacion.Advertencias
		table.insert(lista, { T = os.time(), Motivo = texto, Autor = autor })
		while #lista > self.MaxAdvertencias do
			table.remove(lista, 1)
		end
		total = #lista
		enPerfil = true
		self:Llamar("DataService", "Marcar", jugador)
	else
		total = (self.AdvertenciasMemoria[userId] or 0) + 1
		self.AdvertenciasMemoria[userId] = total
	end

	self:Enviar(jugador, "Moderacion", {
		Sub = "Advertencia", Motivo = texto, Autor = nombreDe(admin), Total = total, T = os.time(),
	})
	self:Notificar(jugador, "Advertencia de moderación", texto, "aviso", 10)
	self:Anotar(admin, jugador, "Advertir", texto, { Total = total, EnPerfil = enPerfil })
	return true, { UserId = userId, Nombre = nombreDe(jugador), Total = total, EnPerfil = enPerfil }
end

-- Advertencias del perfil de un jugador conectado (copia) o lista vacía.
function ModerationService:AdvertenciasDe(player)
	player = resolverJugador(player)
	if not player then
		return {}
	end
	local ok, perfil = self:Llamar("DataService", "Obtener", player)
	local lista = {}
	if ok and typeof(perfil) == "table" and typeof(perfil.Moderacion) == "table" and typeof(perfil.Moderacion.Advertencias) == "table" then
		for i = #perfil.Moderacion.Advertencias, 1, -1 do
			local adv = perfil.Moderacion.Advertencias[i]
			if typeof(adv) == "table" then
				table.insert(lista, {
					T = adv.T, Motivo = adv.Motivo, Autor = adv.Autor, Tipo = "Advertencia",
					Jugador = player.Name, ObjetivoUserId = player.UserId,
				})
			end
		end
	end
	return lista
end

-- Estado de moderación de un jugador (paneles / StaffService).
function ModerationService:Snapshot(player)
	local userId = userIdDe(player)
	if not userId then
		return nil
	end
	local silencio = self:SilencioActivo(userId)
	return {
		Silenciado = silencio ~= nil,
		SilenciadoHasta = silencio and silencio.Hasta or nil,
		Advertencias = #self:AdvertenciasDe(player),
	}
end

---------------------------------------------------------------------------------------------------
-- Confirmación en dos pasos
---------------------------------------------------------------------------------------------------
-- Los tokens vencidos se conservan GraciaTokenSeg más para poder responder "caducó" en lugar de "no válido".
function ModerationService:PurgarTokens()
	local limite = os.clock() - self.GraciaTokenSeg
	for token, entrada in pairs(self.Tokens) do
		if entrada.Expira <= limite then
			self.Tokens[token] = nil
		end
	end
end

-- Resumen legible de una acción pendiente de confirmar.
function ModerationService:Resumen(accion, objetivo, motivo, duracion, cargo)
	local nombre = nombreDe(objetivo)
	local texto = (self.Etiquetas[accion] or accion) .. " a " .. nombre
	if accion == "BloquearTemporal" then
		texto = texto .. " durante " .. Format.Duracion(duracion)
	elseif accion == "RevocarCargo" then
		texto = "Revocar el cargo de " .. RoleDefinitions.Nombre(self:CargoDe(objetivo)) .. " a " .. nombre
	elseif accion == "AsignarCargo" and cargo then
		texto = "Asignar el cargo " .. RoleDefinitions.Nombre(cargo) .. " a " .. nombre
	end
	return texto .. ". Motivo: " .. tostring(motivo)
end

function ModerationService:EmitirToken(admin, objetivo, accion, motivo, duracion, cargo)
	-- Máximo de tokens pendientes por administrador: se descarta el más antiguo.
	local propios = {}
	local ahora = os.clock()
	for token, entrada in pairs(self.Tokens) do
		if entrada.AdminUserId == admin.UserId then
			if entrada.Expira <= ahora then
				self.Tokens[token] = nil
			else
				table.insert(propios, { Token = token, Creado = entrada.Creado })
			end
		end
	end
	if #propios >= self.MaxTokensPorAdmin then
		table.sort(propios, function(a, b)
			return a.Creado < b.Creado
		end)
		for i = 1, #propios - self.MaxTokensPorAdmin + 1 do
			self.Tokens[propios[i].Token] = nil
		end
	end
	local token = generarToken()
	while self.Tokens[token] ~= nil do
		token = generarToken()
	end
	self.Tokens[token] = {
		Accion = accion,
		AdminUserId = admin.UserId,
		ObjetivoUserId = objetivo.UserId,
		Motivo = motivo,
		DuracionSeg = duracion,
		Cargo = cargo,
		Creado = os.clock(),
		Expira = os.clock() + self.TokenSeg,
	}
	local resumen = self:Resumen(accion, objetivo, motivo, duracion, cargo)
	self:Auditar(admin, "Confirmacion:" .. accion, "pendiente · objetivo=" .. objetivo.Name .. "(" .. objetivo.UserId .. ")")
	return RemoteContracts.Ok({
		RequiereConfirmacion = true,
		Token = token,
		Accion = accion,
		ObjetivoUserId = objetivo.UserId,
		Resumen = resumen,
		Mensaje = "Paso 2 de 2 · Confirma definitivamente: " .. resumen .. " (la confirmación caduca en " .. self.TokenSeg .. " s).",
		ExpiraSeg = self.TokenSeg,
	})
end

-- Segunda llamada: valida el Token (propio, vigente, de un solo uso) y ejecuta con los datos guardados.
function ModerationService:Confirmar(admin, datos)
	local token = datos.Token
	if typeof(token) ~= "string" or token == "" then
		return RemoteContracts.Error("Falta la confirmación. Repite la acción desde el panel.")
	end
	local entrada = self.Tokens[token]
	if not entrada then
		self:Auditar(admin, "Rechazo:ConfirmarAccion", "token inexistente o ya usado")
		return RemoteContracts.Error("La confirmación no es válida o ya se usó. Repite la acción.")
	end
	if entrada.AdminUserId ~= admin.UserId then
		self:Auditar(admin, "Rechazo:ConfirmarAccion", "token de otro administrador")
		return RemoteContracts.Error("La confirmación no es válida o ya se usó. Repite la acción.")
	end
	if entrada.Expira <= os.clock() then
		self.Tokens[token] = nil
		self:Auditar(admin, "Rechazo:ConfirmarAccion", "token caducado (" .. entrada.Accion .. ")")
		return RemoteContracts.Error("La confirmación caducó (" .. self.TokenSeg .. " s). Repite la acción.")
	end
	if datos.Accion ~= "ConfirmarAccion" and datos.Accion ~= entrada.Accion then
		self:Auditar(admin, "Rechazo:ConfirmarAccion", "acción distinta: " .. tostring(datos.Accion) .. " ~= " .. entrada.Accion)
		return RemoteContracts.Error("La confirmación no corresponde a esta acción.")
	end
	if datos.ObjetivoUserId ~= nil and datos.ObjetivoUserId ~= entrada.ObjetivoUserId then
		self:Auditar(admin, "Rechazo:ConfirmarAccion", "objetivo distinto del confirmado")
		return RemoteContracts.Error("La confirmación no corresponde a este jugador.")
	end
	-- Un solo uso: se consume antes de ejecutar.
	self.Tokens[token] = nil
	local permiso = self.Permisos[entrada.Accion]
	if not permiso or not self:TienePermiso(admin, permiso) then
		self:Auditar(admin, "Rechazo:ConfirmarAccion", "sin permiso " .. tostring(permiso) .. " al confirmar " .. entrada.Accion)
		return RemoteContracts.Error("Ya no tienes permiso para esta acción.")
	end
	local objetivo = Players:GetPlayerByUserId(entrada.ObjetivoUserId)
	if not objetivo then
		return RemoteContracts.Error("El jugador ya no está conectado.")
	end
	return self:Ejecutar(admin, objetivo, entrada.Accion, entrada.Motivo, entrada.DuracionSeg, entrada.Cargo)
end

---------------------------------------------------------------------------------------------------
-- Ejecución de acciones (desde el handler)
---------------------------------------------------------------------------------------------------
local function textoRoles(motivo)
	if typeof(motivo) ~= "string" then
		return "No se pudo completar la gestión del cargo."
	end
	local espera = string.match(motivo, "^cooldown:(%d+)$")
	if espera then
		return "Espera " .. espera .. " s antes de otra gestión de cargos."
	end
	return TEXTOS_ROLES[motivo] or motivo
end

function ModerationService:Ejecutar(admin, objetivo, accion, motivo, duracion, cargo)
	local opciones = { YaFiltrado = true }
	local ok, resultado
	if accion == "Silenciar" then
		ok, resultado = self:Silenciar(admin, objetivo, duracion, motivo, opciones)
	elseif accion == "QuitarSilencio" then
		ok, resultado = self:QuitarSilencio(admin, objetivo, motivo, opciones)
	elseif accion == "Advertir" then
		ok, resultado = self:Advertir(admin, objetivo, motivo, opciones)
	elseif accion == "Expulsar" then
		ok, resultado = self:Expulsar(admin, objetivo, motivo, opciones)
	elseif accion == "BloquearTemporal" then
		ok, resultado = self:BloquearTemporal(admin, objetivo, duracion, motivo, opciones)
	elseif accion == "AsignarCargo" or accion == "RevocarCargo" then
		return self:GestionarCargo(admin, objetivo, accion, motivo, cargo)
	else
		return RemoteContracts.Error("Acción de moderación desconocida.")
	end
	if not ok then
		return RemoteContracts.Error(resultado)
	end
	local datos = typeof(resultado) == "table" and resultado or {}
	datos.Accion = accion
	datos.Mensaje = (self.Etiquetas[accion] or accion) .. " aplicado: " .. nombreDe(objetivo) .. "."
	return RemoteContracts.Ok(datos)
end

-- AsignarCargo / RevocarCargo: delega en RoleService (que aplica su propia jerarquía y cooldown).
function ModerationService:GestionarCargo(admin, objetivo, accion, motivo, cargo)
	local RoleService = self:Servicio("RoleService")
	local metodo = accion == "AsignarCargo" and "AsignarPorAdmin" or "Revocar"
	if not RoleService or typeof(RoleService[metodo]) ~= "function" then
		return RemoteContracts.Error("La gestión de cargos no está disponible.")
	end
	local anterior = self:CargoDe(objetivo)
	local okLlamada, ok, info
	if accion == "AsignarCargo" then
		if not RoleDefinitions.Existe(cargo) then
			return RemoteContracts.Error("Selecciona un cargo válido.")
		end
		okLlamada, ok, info = pcall(RoleService.AsignarPorAdmin, RoleService, admin, objetivo, cargo)
	else
		okLlamada, ok, info = pcall(RoleService.Revocar, RoleService, admin, objetivo)
	end
	if not okLlamada then
		warn(PREFIJO .. " RoleService:" .. metodo .. " falló: " .. tostring(ok))
		return RemoteContracts.Error("No se pudo completar la gestión del cargo.")
	end
	if ok ~= true then
		self:Auditar(admin, "Rechazo:" .. accion, tostring(info) .. " · objetivo=" .. objetivo.Name .. "(" .. objetivo.UserId .. ")")
		return RemoteContracts.Error(textoRoles(info))
	end
	local nuevo = typeof(info) == "table" and info.Cargo or self:CargoDe(objetivo)
	self:Anotar(admin, objetivo, accion, motivo, { Cargo = nuevo, Anterior = anterior })
	local datos = {
		Accion = accion,
		UserId = objetivo.UserId,
		Nombre = nombreDe(objetivo),
		Cargo = nuevo,
		Anterior = anterior,
		Mensaje = (self.Etiquetas[accion] or accion) .. " aplicado: " .. nombreDe(objetivo) .. " (" .. RoleDefinitions.Nombre(nuevo) .. ").",
	}
	if typeof(info) == "table" then
		datos.Equipo = info.Equipo
		datos.Salon = info.Salon
	end
	return RemoteContracts.Ok(datos)
end

---------------------------------------------------------------------------------------------------
-- VerRegistro
---------------------------------------------------------------------------------------------------
function ModerationService:AccionVerRegistro(admin, datos)
	local objetivoId = datos.ObjetivoUserId
	local auditoria = {}
	local AuditLog = self:Servicio("AuditLogService")
	if AuditLog and typeof(AuditLog.Listar) == "function" then
		local cantidad = 50
		if objetivoId ~= nil then
			cantidad = 500
		end
		local ok, lista = pcall(AuditLog.Listar, AuditLog, cantidad)
		if ok and typeof(lista) == "table" then
			local clave = objetivoId and tostring(objetivoId) or nil
			for _, entrada in ipairs(lista) do
				if #auditoria >= 50 then
					break
				end
				local pasa = clave == nil or entrada.UserId == objetivoId
					or (typeof(entrada.Detalle) == "string" and string.find(entrada.Detalle, clave, 1, true) ~= nil)
				if pasa then
					table.insert(auditoria, {
						Id = entrada.Id, T = entrada.T, Categoria = entrada.Categoria, UserId = entrada.UserId,
						Jugador = entrada.Jugador, Tipo = entrada.Accion, Accion = entrada.Accion, Detalle = entrada.Detalle,
						Fuente = "Auditoria",
					})
				end
			end
		end
	end

	local reportes = {}
	local okR, listaR = self:Llamar("ReportService", "Listar", 30)
	if okR and typeof(listaR) == "table" then
		for _, reporte in ipairs(listaR) do
			local fila = copiaPlana(reporte)
			fila.Fuente = "Reporte"
			fila.Tipo = "Reporte"
			table.insert(reportes, fila)
		end
	end

	local moderacion = self:Registro(30, objetivoId)
	local advertencias = {}
	local objetivo = nil
	if objetivoId ~= nil then
		objetivo = Players:GetPlayerByUserId(objetivoId)
		if objetivo then
			advertencias = self:AdvertenciasDe(objetivo)
		end
	end

	-- Vista combinada (la más reciente primero) para el panel.
	local combinada = {}
	for _, fila in ipairs(moderacion) do
		local copia = copiaPlana(fila)
		copia.Fuente = "Moderacion"
		copia.Categoria = "Moderacion"
		table.insert(combinada, copia)
	end
	for _, fila in ipairs(advertencias) do
		local copia = copiaPlana(fila)
		copia.Fuente = "Advertencia"
		table.insert(combinada, copia)
	end
	for _, fila in ipairs(auditoria) do
		table.insert(combinada, fila)
	end
	for _, fila in ipairs(reportes) do
		table.insert(combinada, fila)
	end
	table.sort(combinada, function(a, b)
		local ta, tb = tonumber(a.T) or 0, tonumber(b.T) or 0
		if ta ~= tb then
			return ta > tb
		end
		return tostring(a.Fuente) < tostring(b.Fuente)
	end)
	while #combinada > 100 do
		table.remove(combinada)
	end

	local respuesta = {
		Registro = combinada,
		Auditoria = auditoria,
		Reportes = reportes,
		Moderacion = moderacion,
		Advertencias = advertencias,
		Silenciados = self:Silenciados(),
		ObjetivoUserId = objetivoId,
		Objetivo = objetivo and nombreDe(objetivo) or nil,
	}
	self:Auditar(admin, "VerRegistro", objetivoId and ("objetivo=" .. tostring(objetivoId)) or "general")
	self:Enviar(admin, "Moderacion", { Sub = "Registro", ObjetivoUserId = objetivoId, Cantidad = #combinada, Registro = combinada })
	return RemoteContracts.Ok(respuesta)
end

---------------------------------------------------------------------------------------------------
-- Handler de ModerationAction (RemoteService ya validó tabla, esquema, límite y permiso del contrato)
---------------------------------------------------------------------------------------------------
function ModerationService:ManejarAccion(player, datos)
	self:PurgarTokens()
	local accion = datos.Accion

	-- Segundo paso de una acción crítica (ConfirmarAccion, o la propia acción con su Token).
	if accion == "ConfirmarAccion" then
		return self:Confirmar(player, datos)
	end
	if self.Criticas[accion] and typeof(datos.Token) == "string" and datos.Token ~= "" then
		return self:Confirmar(player, datos)
	end

	local permiso = self.Permisos[accion]
	if not permiso then
		return RemoteContracts.Error("Acción de moderación desconocida.")
	end
	if not self:TienePermiso(player, permiso) then
		self:Auditar(player, "Rechazo:" .. tostring(accion), "sin permiso " .. permiso)
		return RemoteContracts.Error("No tienes permiso para esta acción.")
	end
	if accion == "VerRegistro" then
		return self:AccionVerRegistro(player, datos)
	end

	-- Objetivo conectado, distinto de uno mismo y sin cargo superior.
	if typeof(datos.ObjetivoUserId) ~= "number" then
		return RemoteContracts.Error("Selecciona a un jugador.")
	end
	local objetivo = Players:GetPlayerByUserId(datos.ObjetivoUserId)
	if not objetivo then
		return RemoteContracts.Error("El jugador no está conectado.")
	end
	local puede, mensaje, codigo = self:PuedeActuar(player, objetivo)
	if not puede then
		self:Auditar(player, "Rechazo:" .. accion, tostring(codigo) .. " · objetivo=" .. objetivo.Name .. "(" .. objetivo.UserId .. ")")
		return RemoteContracts.Error(mensaje)
	end
	if accion == "AsignarCargo" and not RoleDefinitions.Existe(datos.Cargo) then
		return RemoteContracts.Error("Selecciona un cargo válido.")
	end
	if accion == "QuitarSilencio" and not self:SilencioActivo(objetivo.UserId) then
		return RemoteContracts.Error(nombreDe(objetivo) .. " no está silenciado/a.")
	end

	-- Evita la misma acción repetida por un doble clic.
	local clave = player.UserId .. ":" .. accion .. ":" .. objetivo.UserId
	local ultima = self.UltimaAccion[clave]
	if ultima and os.clock() - ultima < self.AntiRepeticionSeg then
		return RemoteContracts.Error("Acción repetida; espera un momento.")
	end
	self.UltimaAccion[clave] = os.clock()

	local motivo, errMotivo = self:PrepararMotivo(player, datos.Motivo, accion)
	if not motivo then
		return RemoteContracts.Error(errMotivo)
	end
	if objetivo.Parent == nil then
		return RemoteContracts.Error("El jugador ya no está conectado.")
	end
	local duracion = nil
	if accion == "Silenciar" or accion == "BloquearTemporal" then
		duracion = self:Duracion(accion, datos.DuracionSeg)
	end

	if self.Criticas[accion] then
		if accion == "RevocarCargo" and self:CargoDe(objetivo) == ((Config.Spawns and Config.Spawns.CargoPorDefecto) or "Estudiante") then
			return RemoteContracts.Error(TEXTOS_ROLES.sin_cargo)
		end
		return self:EmitirToken(player, objetivo, accion, motivo, duracion, datos.Cargo)
	end
	return self:Ejecutar(player, objetivo, accion, motivo, duracion, datos.Cargo)
end

return ModerationService
]=] }
FUENTES["ServerScriptService/ColegioRP/Services/NotebookService"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ServerScriptService.ColegioRP.Services.NotebookService
	Tipo: ModuleScript
	Cuaderno personal (docs/ARQUITECTURA.md §4 y §6, prueba P6). Vive en Perfil.Cuaderno (DataService) con
	páginas { Materia, Texto, Actualizado, Compartida, TextoFiltrado }. Handler de NotebookUpdate:
	Guardar (página 1..MaxPaginas, texto <= MaxCaracteresPagina, materia válida, máx. 1 guardado cada 10 s por
	jugador), Cargar (cuaderno completo), Compartir (alterna; al compartir filtra el texto con TextService para
	terceros y guarda TextoFiltrado), Vaciar (página o cuaderno) y Ver (solo el docente con sesión abierta, sobre
	un alumno presente en su aula y una página compartida; devuelve solo TextoFiltrado). AgregarEntrada lo usa
	PCService (procesador de texto). Sin DataService, el cuaderno vive solo en memoria de la sesión.
]]

local Players = game:GetService("Players")
local TextService = game:GetService("TextService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local RP = ReplicatedStorage:WaitForChild("ColegioRP")
local Shared = RP:WaitForChild("Shared")
local Config = require(Shared:WaitForChild("Config"))
local TimetableDefinitions = require(Shared:WaitForChild("TimetableDefinitions"))
local Util = Shared:WaitForChild("Util")
local Signal = require(Util:WaitForChild("Signal"))
local Maid = require(Util:WaitForChild("Maid"))

local NotebookService = {}
NotebookService.Nombre = "NotebookService"

local PREFIJO = "[ColegioRP][NotebookService]"
local CUADERNO = Config.Cuaderno or {}

NotebookService.MaxPaginas = tonumber(CUADERNO.MaxPaginas) or 20
NotebookService.MaxCaracteresPagina = tonumber(CUADERNO.MaxCaracteresPagina) or 1200
NotebookService.AutoguardadoSeg = tonumber(CUADERNO.AutoguardadoSeg) or 45
NotebookService.MinIntervaloGuardadoSeg = tonumber(CUADERNO.MinIntervaloGuardadoSeg) or 10
NotebookService.CooldownCompartirSeg = 3
NotebookService.CooldownVaciarSeg = 2
NotebookService.EsperaPerfilSeg = 5 -- Espera máxima al perfil en "Cargar" (el perfil puede estar cargando).
NotebookService.MateriaPorDefecto = "MAT"
NotebookService.TituloPorDefecto = "Mi cuaderno"

---------------------------------------------------------------------------------------------------
-- Utilidades
---------------------------------------------------------------------------------------------------
local function esJugador(valor)
	return typeof(valor) == "Instance" and valor:IsA("Player")
end

-- Quita caracteres de control (conserva saltos de línea; tabulador -> espacio) y recorta a 'maximo' caracteres.
local function sanearTexto(texto, maximo)
	if typeof(texto) ~= "string" or utf8.len(texto) == nil then
		return nil
	end
	local limpio = string.gsub(texto, "%c", function(c)
		if c == "\n" then
			return "\n"
		end
		if c == "\t" then
			return " "
		end
		return ""
	end)
	local n = utf8.len(limpio)
	if n == nil then
		return nil
	end
	if n > maximo then
		local corte = utf8.offset(limpio, maximo + 1)
		if corte then
			limpio = string.sub(limpio, 1, corte - 1)
		end
	end
	return limpio
end

local function recortar(texto)
	local resultado = string.gsub(texto or "", "^%s+", "")
	resultado = string.gsub(resultado, "%s+$", "")
	return resultado
end

local function longitud(texto)
	return utf8.len(texto or "") or #(texto or "")
end

-- Filtra con TextService para terceros (broadcast) o para un usuario concreto. Devuelve texto | nil.
local function filtrar(texto, deUserId, paraUserId)
	local okFiltro, resultado = pcall(function()
		return TextService:FilterStringAsync(texto, deUserId, Enum.TextFilterContext.PublicChat)
	end)
	if not okFiltro or resultado == nil then
		return nil
	end
	local okTexto, filtrado = pcall(function()
		if paraUserId then
			return resultado:GetNonChatStringForUserAsync(paraUserId)
		end
		return resultado:GetNonChatStringForBroadcastAsync()
	end)
	if not okTexto or typeof(filtrado) ~= "string" then
		return nil
	end
	return filtrado
end

local function rechazo(codigo, mensaje, extra)
	return { ok = false, error = "rechazado:" .. tostring(codigo), mensaje = mensaje, datos = extra }
end

local function exito(datos)
	return { ok = true, datos = datos or {} }
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function NotebookService:Init(registro)
	self.registro = registro
	self.UltimoGuardado = {} -- userId -> os.clock() del último "Guardar" aceptado
	self.UltimaAccion = {} -- userId -> { accion -> os.clock() }
	self.Memoria = {} -- userId -> cuaderno (solo si no hay DataService)
	self.CuadernoActualizado = Signal.new() -- (player, pagina|nil)
	self.maid = Maid.new()
end

function NotebookService:Start()
	local RemoteService = self.registro.Get("RemoteService")
	if RemoteService and typeof(RemoteService.Registrar) == "function" then
		RemoteService:Registrar("NotebookUpdate", function(player, datos)
			return self:Manejar(player, datos)
		end)
	else
		warn(PREFIJO .. " RemoteService no disponible: NotebookUpdate no tendrá handler.")
	end
	if not self.registro.Get("DataService") then
		warn(PREFIJO .. " DataService no disponible: los cuadernos solo se guardan en memoria durante la sesión.")
	end
	self.maid:GiveTask(Players.PlayerRemoving:Connect(function(player)
		local userId = player.UserId
		self.UltimoGuardado[userId] = nil
		self.UltimaAccion[userId] = nil
		self.Memoria[userId] = nil
	end))
end

---------------------------------------------------------------------------------------------------
-- Acceso a otros servicios
---------------------------------------------------------------------------------------------------
function NotebookService:Llamar(nombre, metodo, ...)
	local servicio = self.registro and self.registro.Get(nombre)
	if not servicio or typeof(servicio[metodo]) ~= "function" then
		return false
	end
	local resultado = table.pack(pcall(servicio[metodo], servicio, ...))
	if not resultado[1] then
		warn(PREFIJO .. " " .. nombre .. ":" .. metodo .. " falló: " .. tostring(resultado[2]))
		return false
	end
	return true, resultado[2], resultado[3]
end

function NotebookService:Auditar(player, accion, detalle)
	self:Llamar("AuditLogService", "Registrar", "Clase", player, accion, detalle)
end

function NotebookService:Enviar(player, tipo, datos)
	local RemoteService = self.registro.Get("RemoteService")
	if RemoteService and esJugador(player) then
		return RemoteService:Enviar(player, tipo, datos)
	end
	return false
end

function NotebookService:MateriaActual()
	local ok, snapshot = self:Llamar("SchoolDayService", "Snapshot")
	if ok and typeof(snapshot) == "table" and TimetableDefinitions.ExisteMateria(snapshot.Materia) then
		return snapshot.Materia
	end
	return nil
end

function NotebookService:EsperaRestante(player, accion, segundos)
	local porJugador = self.UltimaAccion[player.UserId]
	local ultimo = porJugador and porJugador[accion]
	if not ultimo then
		return 0
	end
	return math.max(0, segundos - (os.clock() - ultimo))
end

function NotebookService:MarcarAccion(player, accion)
	local porJugador = self.UltimaAccion[player.UserId]
	if not porJugador then
		porJugador = {}
		self.UltimaAccion[player.UserId] = porJugador
	end
	porJugador[accion] = os.clock()
end

---------------------------------------------------------------------------------------------------
-- Cuaderno del jugador
---------------------------------------------------------------------------------------------------
local function cuadernoNuevo(materia)
	return {
		Titulo = NotebookService.TituloPorDefecto,
		Paginas = { { Materia = materia or NotebookService.MateriaPorDefecto, Texto = "", Actualizado = 0 } },
	}
end

-- Garantiza la estructura mínima (título y al menos una página válida; páginas contiguas).
function NotebookService:Asegurar(cuaderno)
	if typeof(cuaderno.Titulo) ~= "string" or cuaderno.Titulo == "" then
		cuaderno.Titulo = self.TituloPorDefecto
	end
	if typeof(cuaderno.Paginas) ~= "table" then
		cuaderno.Paginas = {}
	end
	local limpias = {}
	for i = 1, math.min(#cuaderno.Paginas, self.MaxPaginas) do
		local pagina = cuaderno.Paginas[i]
		if typeof(pagina) == "table" then
			if typeof(pagina.Texto) ~= "string" then
				pagina.Texto = ""
			end
			if not TimetableDefinitions.ExisteMateria(pagina.Materia) then
				pagina.Materia = self.MateriaPorDefecto
			end
			pagina.Actualizado = tonumber(pagina.Actualizado) or 0
			table.insert(limpias, pagina)
		end
	end
	if #limpias == 0 then
		table.insert(limpias, { Materia = self:MateriaActual() or self.MateriaPorDefecto, Texto = "", Actualizado = 0 })
	end
	cuaderno.Paginas = limpias
	return cuaderno
end

-- Devuelve el cuaderno (tabla viva del perfil) o nil si el perfil aún no está cargado.
function NotebookService:Cuaderno(player, esperar)
	if not esJugador(player) then
		return nil
	end
	local DataService = self.registro.Get("DataService")
	if not DataService then
		local enMemoria = self.Memoria[player.UserId]
		if not enMemoria then
			enMemoria = cuadernoNuevo(self:MateriaActual())
			self.Memoria[player.UserId] = enMemoria
		end
		return self:Asegurar(enMemoria)
	end
	local ok, perfil = self:Llamar("DataService", "Obtener", player)
	if (not ok or typeof(perfil) ~= "table") and esperar then
		ok, perfil = self:Llamar("DataService", "EsperarPerfil", player, self.EsperaPerfilSeg)
	end
	if not ok or typeof(perfil) ~= "table" then
		return nil
	end
	if typeof(perfil.Cuaderno) ~= "table" then
		perfil.Cuaderno = cuadernoNuevo(self:MateriaActual())
	end
	return self:Asegurar(perfil.Cuaderno)
end

function NotebookService:Marcar(player)
	self:Llamar("DataService", "Marcar", player)
end

-- Crea páginas vacías hasta 'numero' (las páginas deben ser contiguas para el saneamiento del perfil).
function NotebookService:AsegurarPaginas(cuaderno, numero, materia)
	while #cuaderno.Paginas < numero do
		table.insert(cuaderno.Paginas, { Materia = materia or self.MateriaPorDefecto, Texto = "", Actualizado = 0 })
	end
	return cuaderno.Paginas[numero]
end

-- Representación para el propio dueño (sin TextoFiltrado).
function NotebookService:Exportar(cuaderno, player)
	local paginas = {}
	for i, pagina in ipairs(cuaderno.Paginas) do
		table.insert(paginas, {
			Pagina = i,
			Materia = pagina.Materia,
			Texto = pagina.Texto,
			Actualizado = pagina.Actualizado,
			Compartida = pagina.Compartida == true,
		})
	end
	local espera = 0
	if player then
		local ultimo = self.UltimoGuardado[player.UserId]
		if ultimo then
			espera = math.max(0, self.MinIntervaloGuardadoSeg - (os.clock() - ultimo))
		end
	end
	return {
		Titulo = cuaderno.Titulo,
		Paginas = paginas,
		MaxPaginas = self.MaxPaginas,
		MaxCaracteres = self.MaxCaracteresPagina,
		AutoguardadoSeg = self.AutoguardadoSeg,
		MinIntervaloGuardadoSeg = self.MinIntervaloGuardadoSeg,
		EsperaGuardado = espera,
		MateriaActual = self:MateriaActual(),
	}
end

---------------------------------------------------------------------------------------------------
-- Entrada del remoto
---------------------------------------------------------------------------------------------------
function NotebookService:Manejar(player, datos)
	if not esJugador(player) or typeof(datos) ~= "table" then
		return rechazo("datos", "Petición inválida.")
	end
	local accion = datos.Accion
	if accion == "Guardar" then
		return self:Guardar(player, datos)
	elseif accion == "Cargar" then
		return self:Cargar(player)
	elseif accion == "Compartir" then
		return self:Compartir(player, datos)
	elseif accion == "Vaciar" then
		return self:Vaciar(player, datos)
	elseif accion == "Ver" then
		return self:Ver(player, datos)
	end
	return rechazo("accion_desconocida", "Acción de cuaderno desconocida.")
end

function NotebookService:Guardar(player, d)
	local userId = player.UserId
	local ultimo = self.UltimoGuardado[userId]
	if ultimo then
		local restante = self.MinIntervaloGuardadoSeg - (os.clock() - ultimo)
		if restante > 0 then
			return rechazo("cooldown", string.format("Espera %d s para volver a guardar.", math.ceil(restante)),
				{ Reintentar = restante })
		end
	end
	local numero = tonumber(d.Pagina) or 1
	if numero < 1 or numero > self.MaxPaginas or math.floor(numero) ~= numero then
		return rechazo("pagina", "La página debe estar entre 1 y " .. self.MaxPaginas .. ".")
	end
	if d.Texto == nil then
		return rechazo("texto", "Falta el texto de la página.")
	end
	local texto = sanearTexto(d.Texto, self.MaxCaracteresPagina)
	if texto == nil then
		return rechazo("texto", "El texto contiene caracteres no válidos.")
	end
	local materia = nil
	if d.Materia ~= nil then
		if not TimetableDefinitions.ExisteMateria(d.Materia) then
			return rechazo("materia", "Materia desconocida.")
		end
		materia = d.Materia
	end
	local cuaderno = self:Cuaderno(player, false)
	if not cuaderno then
		return rechazo("sin_perfil", "Tu cuaderno aún se está cargando; inténtalo en unos segundos.")
	end

	-- El intervalo cuenta desde ahora (antes de cualquier espera por filtrado).
	self.UltimoGuardado[userId] = os.clock()
	local pagina = self:AsegurarPaginas(cuaderno, numero, materia or self:MateriaActual())
	local cambio = pagina.Texto ~= texto
	pagina.Texto = texto
	if materia then
		pagina.Materia = materia
	end
	local t = os.time()
	pagina.Actualizado = t

	-- Una página compartida que cambia se vuelve a filtrar; si no se puede, deja de estar compartida.
	local avisoCompartida = nil
	if pagina.Compartida and cambio then
		if recortar(texto) == "" then
			pagina.Compartida = false
			pagina.TextoFiltrado = nil
			avisoCompartida = "La página quedó vacía y dejó de estar compartida."
		else
			local filtrado = filtrar(texto, userId, nil)
			if filtrado and pagina.Texto == texto then
				pagina.TextoFiltrado = filtrado
			elseif not filtrado then
				pagina.Compartida = false
				pagina.TextoFiltrado = nil
				avisoCompartida = "No se pudo filtrar la página modificada; dejó de estar compartida."
			end
		end
	end
	self:Marcar(player)
	self.CuadernoActualizado:Fire(player, numero)
	return exito({
		Guardado = true,
		Actualizado = t,
		Pagina = numero,
		Materia = pagina.Materia,
		Compartida = pagina.Compartida == true,
		Paginas = #cuaderno.Paginas,
		Aviso = avisoCompartida,
		ProximoGuardadoSeg = self.MinIntervaloGuardadoSeg,
	})
end

function NotebookService:Cargar(player)
	local cuaderno = self:Cuaderno(player, true)
	if not cuaderno then
		return rechazo("sin_perfil", "Tu cuaderno aún se está cargando; inténtalo en unos segundos.")
	end
	return exito(self:Exportar(cuaderno, player))
end

function NotebookService:Compartir(player, d)
	local espera = self:EsperaRestante(player, "Compartir", self.CooldownCompartirSeg)
	if espera > 0 then
		return rechazo("cooldown", string.format("Espera %d s.", math.ceil(espera)))
	end
	local numero = tonumber(d.Pagina) or 1
	local cuaderno = self:Cuaderno(player, false)
	if not cuaderno then
		return rechazo("sin_perfil", "Tu cuaderno aún se está cargando.")
	end
	local pagina = cuaderno.Paginas[numero]
	if not pagina then
		return rechazo("pagina", "Esa página no existe todavía. Escribe y guarda primero.")
	end
	self:MarcarAccion(player, "Compartir")
	if pagina.Compartida then
		pagina.Compartida = false
		pagina.TextoFiltrado = nil
		self:Marcar(player)
		return exito({ Compartida = false, Pagina = numero })
	end
	local texto = pagina.Texto or ""
	if recortar(texto) == "" then
		return rechazo("vacia", "La página está vacía; escribe algo antes de compartirla.")
	end
	local filtrado = filtrar(texto, player.UserId, nil)
	if not filtrado then
		return rechazo("filtro", "No se pudo filtrar la página; no se compartió. Inténtalo de nuevo.")
	end
	if pagina.Texto ~= texto then
		return rechazo("cambio", "La página cambió mientras se compartía; inténtalo de nuevo.")
	end
	pagina.Compartida = true
	pagina.TextoFiltrado = filtrado
	self:Marcar(player)
	self:Auditar(player, "CompartirCuaderno", "página " .. numero)
	return exito({ Compartida = true, Pagina = numero })
end

function NotebookService:Vaciar(player, d)
	local espera = self:EsperaRestante(player, "Vaciar", self.CooldownVaciarSeg)
	if espera > 0 then
		return rechazo("cooldown", string.format("Espera %d s.", math.ceil(espera)))
	end
	local cuaderno = self:Cuaderno(player, false)
	if not cuaderno then
		return rechazo("sin_perfil", "Tu cuaderno aún se está cargando.")
	end
	self:MarcarAccion(player, "Vaciar")
	local t = os.time()
	local numero = tonumber(d.Pagina)
	if numero then
		local pagina = cuaderno.Paginas[numero]
		if not pagina then
			return rechazo("pagina", "Esa página no existe.")
		end
		pagina.Texto = ""
		pagina.Compartida = false
		pagina.TextoFiltrado = nil
		pagina.Actualizado = t
	else
		cuaderno.Paginas = { { Materia = self:MateriaActual() or self.MateriaPorDefecto, Texto = "", Actualizado = t } }
	end
	self:Marcar(player)
	self.CuadernoActualizado:Fire(player, numero)
	return exito({ Vaciado = true, Pagina = numero, Paginas = #cuaderno.Paginas, Actualizado = t })
end

-- "Ver": solo el docente con sesión abierta, sobre un alumno presente en su aula y páginas compartidas.
function NotebookService:Ver(player, d)
	local objetivoId = tonumber(d.ObjetivoUserId)
	local objetivo = objetivoId and Players:GetPlayerByUserId(objetivoId) or nil
	if not objetivo or objetivo == player then
		return rechazo("objetivo", "Elige a un estudiante conectado.")
	end
	local ClassroomService = self.registro.Get("ClassroomService")
	local sesion = nil
	if ClassroomService and typeof(ClassroomService.SesionDeJugador) == "function" then
		local ok, resultado = pcall(ClassroomService.SesionDeJugador, ClassroomService, player)
		if ok and typeof(resultado) == "table" then
			sesion = resultado
		end
	end
	if not sesion or sesion.TeacherUserId ~= player.UserId or sesion.State ~= "Abierta" then
		self:Auditar(player, "Rechazo:VerCuaderno", "sin sesión propia · objetivo " .. tostring(objetivoId))
		return rechazo("sin_sesion", "Necesitas una sesión de clase abierta para revisar cuadernos.")
	end
	local presente = false
	local ok, esta = self:Llamar("RoomService", "EstaEn", objetivo, sesion.RoomId)
	if ok then
		presente = esta == true
	elseif ClassroomService and typeof(ClassroomService.EstaEnAula) == "function" then
		local okAula, estaAula = pcall(ClassroomService.EstaEnAula, ClassroomService, objetivo, sesion.RoomId)
		presente = okAula and estaAula == true
	end
	if not presente then
		self:Auditar(player, "Rechazo:VerCuaderno", "alumno ausente · " .. objetivo.Name .. " · " .. sesion.RoomId)
		return rechazo("ausente", objetivo.DisplayName .. " no está en tu aula.")
	end
	local cuaderno = self:Cuaderno(objetivo, false)
	if not cuaderno then
		return rechazo("sin_perfil", "El cuaderno de " .. objetivo.DisplayName .. " aún se está cargando.")
	end

	local numero = tonumber(d.Pagina)
	local candidatas = {}
	if numero then
		local pagina = cuaderno.Paginas[numero]
		if not pagina or not pagina.Compartida then
			self:Auditar(player, "Rechazo:VerCuaderno", "página no compartida · " .. objetivo.Name .. " · " .. tostring(numero))
			return rechazo("no_compartida", "Esa página no está compartida.")
		end
		table.insert(candidatas, numero)
	else
		for i, pagina in ipairs(cuaderno.Paginas) do
			if pagina.Compartida then
				table.insert(candidatas, i)
			end
		end
	end

	local paginas = {}
	local modificado = false
	for _, i in ipairs(candidatas) do
		local pagina = cuaderno.Paginas[i]
		local texto = pagina.TextoFiltrado
		if typeof(texto) ~= "string" then
			-- Tras recargar el perfil TextoFiltrado no se conserva: se filtra de nuevo (nunca se muestra sin filtrar).
			local original = pagina.Texto or ""
			texto = filtrar(original, objetivo.UserId, nil)
			-- El filtrado cede: solo se guarda en caché si la página no cambió ni dejó de compartirse mientras tanto.
			if texto and pagina.Texto == original and pagina.Compartida then
				pagina.TextoFiltrado = texto
				modificado = true
			end
		end
		if texto then
			table.insert(paginas, { Pagina = i, Materia = pagina.Materia, Texto = texto, Actualizado = pagina.Actualizado })
		end
	end
	if modificado then
		self:Marcar(objetivo)
	end
	if #paginas > 0 then
		self:Enviar(objetivo, "Notificacion", {
			Texto = "Tu docente revisó tu cuaderno compartido.", Nivel = "info", Duracion = 4,
		})
	end
	self:Auditar(player, "VerCuaderno", objetivo.Name .. " · " .. #paginas .. " páginas · " .. sesion.RoomId)
	return exito({
		ObjetivoUserId = objetivo.UserId,
		Nombre = objetivo.DisplayName,
		Titulo = cuaderno.Titulo,
		Paginas = paginas,
		SinCompartidas = #paginas == 0,
	})
end

---------------------------------------------------------------------------------------------------
-- API para otros servicios
---------------------------------------------------------------------------------------------------

-- Cuaderno completo del jugador (mismo formato que "Cargar") o nil si el perfil no está listo.
function NotebookService:Snapshot(player)
	local cuaderno = self:Cuaderno(player, false)
	if not cuaderno then
		return nil
	end
	return self:Exportar(cuaderno, player)
end

-- Añade texto al cuaderno (p. ej. desde el procesador del PC). Usa la última página si es de la misma materia
-- y cabe; si no, la primera vacía o una nueva. Devuelve true, numeroDePagina | false, motivo.
function NotebookService:AgregarEntrada(player, materia, texto)
	local cuaderno = self:Cuaderno(player, false)
	if not cuaderno then
		return false, "sin_perfil"
	end
	local limpio = sanearTexto(texto, self.MaxCaracteresPagina)
	if not limpio or recortar(limpio) == "" then
		return false, "texto_vacio"
	end
	limpio = recortar(limpio)
	if not TimetableDefinitions.ExisteMateria(materia) then
		materia = self:MateriaActual() or "TEC"
	end

	local numero = nil
	local ultima = cuaderno.Paginas[#cuaderno.Paginas]
	if ultima and ultima.Materia == materia and ultima.Texto ~= ""
		and longitud(ultima.Texto) + 2 + longitud(limpio) <= self.MaxCaracteresPagina then
		numero = #cuaderno.Paginas
	end
	if not numero then
		for i, pagina in ipairs(cuaderno.Paginas) do
			if recortar(pagina.Texto or "") == "" then
				numero = i
				break
			end
		end
	end
	if not numero then
		if #cuaderno.Paginas >= self.MaxPaginas then
			return false, "cuaderno_lleno"
		end
		numero = #cuaderno.Paginas + 1
	end
	local pagina = self:AsegurarPaginas(cuaderno, numero, materia)
	if recortar(pagina.Texto or "") == "" then
		pagina.Texto = limpio
		pagina.Materia = materia
	else
		pagina.Texto = sanearTexto(pagina.Texto .. "\n\n" .. limpio, self.MaxCaracteresPagina) or pagina.Texto
	end
	pagina.Actualizado = os.time()
	local dejoDeCompartirse = false
	if pagina.Compartida then
		pagina.Compartida = false
		pagina.TextoFiltrado = nil
		dejoDeCompartirse = true
	end
	self:Marcar(player)
	self.CuadernoActualizado:Fire(player, numero)
	self:Enviar(player, "Aula", { Sub = "Cuaderno", Pagina = numero, Actualizado = pagina.Actualizado, Origen = "PC" })
	local aviso = "Se guardó en tu cuaderno (página " .. numero .. ")."
	if dejoDeCompartirse then
		aviso = aviso .. " La página dejó de estar compartida."
	end
	self:Enviar(player, "Notificacion", { Texto = aviso, Nivel = "exito", Duracion = 4 })
	return true, numero
end

return NotebookService
]=] }
FUENTES["ServerScriptService/ColegioRP/Services/PCService"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ServerScriptService.ColegioRP.Services.PCService
	Tipo: ModuleScript
	Sala de tecnología y computadores (docs/ARQUITECTURA.md §6). Estado por PC con autoridad total del servidor:
	{ Encendido, OcupanteUserId, Bloqueado, Aplicacion, Proyeccion }. Para cada PC de MapService:PCs() crea una
	SurfaceGui en la pantalla real (fondo negro apagado / escritorio con reloj y nombre del colegio, "Libre" u
	"Ocupado por <nombre>", banda de bloqueo; solo se redibuja al cambiar) y un ProximityPrompt (RPTipo "PC",
	RPId, RPAccion "Usar") cuyo Triggered se resuelve aquí. Handler PCAction: Usar / Salir / Encender / Apagar /
	Aplicacion / Resultado (Procesador -> cuaderno; Cuestionario corregido en servidor con una entrega por
	jornada y recompensa de participación si llega al 60 %; actividad del aula reenviada a ClassroomService;
	Simulador recalculado con Catalogs.Simulador y tolerancia del 2 %; Programación ejecutada con el intérprete
	determinista de Catalogs.Programacion) / Bloquear / Desbloquear / Proyectar (docente con pc.bloquear en
	INFORMATICA o ROBOTICA). Libera el PC al salir, levantarse del Seat, alejarse, morir o abandonar el servidor.
	Nunca simula Internet real ni controla ningún PC real.
	Eventos al cliente: "PC" { Sub = "AbrirEscritorio" | "Estado" | "Resultado" | "Proyeccion" | "Bloqueo" }.
]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local TextService = game:GetService("TextService")

local RP = ReplicatedStorage:WaitForChild("ColegioRP")
local Shared = RP:WaitForChild("Shared")
local Config = require(Shared:WaitForChild("Config"))
local Catalogs = require(Shared:WaitForChild("Catalogs"))
local Respuestas = require(script.Parent.Parent:WaitForChild("Datos"):WaitForChild("CuestionariosRespuestas"))
local TimetableDefinitions = require(Shared:WaitForChild("TimetableDefinitions"))
local MapaLogico = require(Shared:WaitForChild("MapaLogico"))
local UITheme = require(Shared:WaitForChild("UITheme"))
local Util = Shared:WaitForChild("Util")
local Signal = require(Util:WaitForChild("Signal"))
local Maid = require(Util:WaitForChild("Maid"))
local Zones = require(Util:WaitForChild("Zones"))
local Format = require(Util:WaitForChild("Format"))

local PCService = {}
PCService.Nombre = "PCService"

local PREFIJO = "[ColegioRP][PCService]"
local Colores = UITheme.Colores
local DISTANCIA_PC = (Config.Distancias and Config.Distancias.PC) or 6
local RECOMPENSAS = (Config.Economia and Config.Economia.Recompensas) or {}
local CUADERNO = Config.Cuaderno or {}

---------------------------------------------------------------------------------------------------
-- Parámetros (ajustables sin tocar la lógica)
---------------------------------------------------------------------------------------------------
PCService.ToleranciaDistancia = 1 -- Studs sobre Config.Distancias.PC al usar un PC sin Seat (latencia de red).
PCService.MargenAlejarse = 3 -- Studs extra antes de liberar un PC sin Seat cuando el ocupante se aleja.
PCService.DistanciaPromptSinSeat = DISTANCIA_PC -- MaxActivationDistance del prompt de un PC sin Seat.
PCService.DistanciaPromptConSeat = DISTANCIA_PC + 2 -- Sentado, la raíz del personaje queda algo más lejos del monitor.
PCService.PixelesPorStud = 40 -- Resolución de la SurfaceGui de la pantalla.
PCService.ToleranciaSimulador = 0.02 -- 2 % de margen relativo al validar el simulador.
PCService.UmbralParticipacion = 0.6 -- Fracción mínima de aciertos del cuestionario para la recompensa.
PCService.MaxProyeccion = 300 -- Caracteres del texto proyectado por el docente.
PCService.MaxProcesador = CUADERNO.MaxCaracteresPagina or 1200 -- Caracteres del procesador de texto.
PCService.IntervaloProcesadorSeg = CUADERNO.MinIntervaloGuardadoSeg or 10 -- Segundos entre guardados en el cuaderno.
PCService.MaxPaginasCuaderno = CUADERNO.MaxPaginas or 20 -- Solo para el respaldo sin NotebookService.
PCService.MaxAnidamiento = 2 -- Niveles de REPETIR anidados aceptados en el servidor.
PCService.MaxRespuestaAula = (Config.Limites and Config.Limites.MaxRespuestaCaracteres) or 300
PCService.SalasBloqueables = { INFORMATICA = true, ROBOTICA = true } -- Salas que el docente puede bloquear/proyectar.
PCService.AppsExtra = { PantallaClase = "Pantalla de clase" } -- Apps del escritorio que no están en Catalogs.ActividadesPC.
PCService.MateriaPorDefecto = "TEC"
PCService.CooldownPromptSeg = 0.75 -- Pulsaciones del prompt más seguidas se ignoran.
PCService.IntervaloVigilanciaSeg = 1 -- Revisión de ocupantes (presencia, asiento, distancia).
PCService.CiclosReloj = 5 -- Cada cuántas vigilancias se recalcula el reloj de las pantallas.

local NOMBRE_GUI = "ColegioRP_PantallaPC"
local NOMBRE_PROMPT = "ColegioRP_PromptPC"
local CARAS_LATERALES = { Enum.NormalId.Front, Enum.NormalId.Back, Enum.NormalId.Left, Enum.NormalId.Right }
-- Claves que nunca se reenvían al cliente dentro del snapshot de clase (privacidad y respuestas correctas).
local CLAVES_PRIVADAS = {
	Submissions = true, Grades = true, Calificaciones = true, Pendientes = true, Destinatarios = true,
	Correcta = true, RespuestaCorrecta = true, Respuestas = true,
}

---------------------------------------------------------------------------------------------------
-- Utilidades
---------------------------------------------------------------------------------------------------
local function esJugador(valor)
	return typeof(valor) == "Instance" and valor:IsA("Player")
end

local function numeroFinito(valor)
	local n = tonumber(valor)
	if n == nil or n ~= n or n == math.huge or n == -math.huge then
		return nil
	end
	return n
end

local function enteroEn(valor, minimo, maximo)
	if typeof(valor) ~= "number" then
		return nil
	end
	local n = numeroFinito(valor)
	if n == nil or n ~= math.floor(n) or n < minimo or n > maximo then
		return nil
	end
	return n
end

local function nombreVisible(player)
	if not esJugador(player) then
		return "Docente"
	end
	local nombre = player.DisplayName
	if typeof(nombre) ~= "string" or nombre == "" then
		nombre = player.Name
	end
	return nombre
end

local function humanoideVivo(player)
	local personaje = player and player.Character
	if not personaje then
		return nil
	end
	local humanoide = personaje:FindFirstChildOfClass("Humanoid")
	if humanoide and humanoide.Health > 0 then
		return humanoide
	end
	return nil
end

local function posicionDe(player)
	local personaje = player and player.Character
	if not personaje then
		return nil
	end
	local raiz = personaje:FindFirstChild("HumanoidRootPart")
	if raiz and raiz:IsA("BasePart") then
		return raiz.Position
	end
	return nil
end

-- Acepta segundos del día (número) o "HH:MM" (texto).
local function segundosDeHora(valor)
	if typeof(valor) == "number" then
		return numeroFinito(valor)
	end
	if typeof(valor) == "string" then
		return Format.SegundosDeHHMM(valor)
	end
	return nil
end

local function ahoraServidor()
	local ok, valor = pcall(function()
		return workspace:GetServerTimeNow()
	end)
	if ok and typeof(valor) == "number" then
		return valor
	end
	return os.time()
end

local function copiarTabla(origen)
	local copia = {}
	if typeof(origen) == "table" then
		for clave, valor in pairs(origen) do
			copia[clave] = valor
		end
	end
	return copia
end

-- Copia apta para un RemoteEvent: solo textos, números finitos, booleanos y tablas acotadas, sin claves privadas.
-- Si una tabla mezcla claves de texto y numéricas, las numéricas pasan a texto (los remotos no admiten mezclas).
local function copiaSegura(valor, profundidad, presupuesto)
	profundidad = profundidad or 0
	presupuesto = presupuesto or { Claves = 0 }
	local tipo = typeof(valor)
	if tipo == "string" or tipo == "boolean" then
		return valor
	end
	if tipo == "number" then
		return numeroFinito(valor)
	end
	if tipo ~= "table" or profundidad > 5 then
		return nil
	end
	local tieneTexto = false
	for clave in pairs(valor) do
		if typeof(clave) == "string" then
			tieneTexto = true
			break
		end
	end
	local copia = {}
	for clave, v in pairs(valor) do
		presupuesto.Claves = presupuesto.Claves + 1
		if presupuesto.Claves > 300 then
			break
		end
		local tipoClave = typeof(clave)
		local valida = false
		if tipoClave == "string" then
			valida = not CLAVES_PRIVADAS[clave]
		elseif tipoClave == "number" then
			valida = clave >= 1 and clave == math.floor(clave)
		end
		if valida then
			local limpio = copiaSegura(v, profundidad + 1, presupuesto)
			if limpio ~= nil then
				if tieneTexto then
					copia[tostring(clave)] = limpio
				else
					copia[clave] = limpio
				end
			end
		end
	end
	return copia
end

-- Llama servicio:metodo(...) en pcall si existe. Devuelve ok, resultado1, resultado2.
local function invocar(servicio, metodo, ...)
	if typeof(servicio) ~= "table" or typeof(servicio[metodo]) ~= "function" then
		return false, nil, nil
	end
	local resultado = table.pack(pcall(servicio[metodo], servicio, ...))
	if not resultado[1] then
		warn(PREFIJO .. " Error en " .. tostring(servicio.Nombre or "?") .. ":" .. tostring(metodo) .. ": " .. tostring(resultado[2]))
		return false, nil, nil
	end
	return true, resultado[2], resultado[3]
end

local function exito(datos)
	return { ok = true, datos = datos or {} }
end

local function fallo(mensaje)
	return { ok = false, error = tostring(mensaje or "No se pudo completar la acción.") }
end

local function fijarTexto(label, valor)
	if label and label.Text ~= valor then
		label.Text = valor
	end
end

local function fijarVisible(objeto, valor)
	if objeto and objeto.Visible ~= valor then
		objeto.Visible = valor
	end
end

-- Comprueba que no haya más REPETIR anidados de los permitidos (el intérprete de Catalogs admite más).
local function comprobarAnidamiento(lineas, maximo)
	local profundidad = 0
	for i, linea in ipairs(lineas) do
		local limpia = string.upper(Format.Recortar(linea))
		if limpia ~= "" and not string.match(limpia, "^%-%-") then
			if string.match(limpia, "^REPETIR") then
				profundidad = profundidad + 1
				if profundidad > maximo then
					return false, string.format("Línea %d: demasiados REPETIR anidados (máximo %d)", i, maximo)
				end
			elseif limpia == "FIN" then
				profundidad = math.max(0, profundidad - 1)
			end
		end
	end
	return true, nil
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function PCService:Init(registro)
	self.registro = registro
	self.Estados = {} -- pcId -> { Encendido, OcupanteUserId, OcupanteNombre, Bloqueado, Aplicacion, Proyeccion }
	self.Registros = {} -- pcId -> { Id, Pantalla, Seat, RoomId, Marcador, Modelo, Numero }
	self.Orden = {} -- pcIds en el orden de MapService
	self.PorSala = {} -- roomId -> { pcId... }
	self.Salas = {} -- roomId -> { Bloqueado, BloqueadoPor, BloqueadoPorNombre, Proyeccion = { Texto, Autor, AutorUserId, T } }
	self.PcDeJugador = {} -- userId -> pcId
	self.Ocupaciones = {} -- pcId -> Maid con la vigilancia del ocupante
	self.ModoDistancia = {} -- pcId -> true si el ocupante lo usa sin Seat
	self.Pantallas = {} -- pcId -> widgets de la SurfaceGui + Firma
	self.Prompts = {} -- pcId -> ProximityPrompt
	self.Entregas = { Clave = "", PorJugador = {} } -- cuestionarios entregados en la jornada actual
	self.JornadaLocal = 1 -- respaldo de número de jornada si SchoolDayService no lo informa
	self.UltimoPrompt = {} -- userId -> os.clock()
	self.UltimoProcesador = {} -- userId -> os.clock()
	self.RelojTexto = "--:--"
	self.ProgresoCongelado = nil
	self.Estadisticas = { Usos = 0, Resultados = 0, Cuestionarios = 0, Programas = 0, Simulaciones = 0, Textos = 0, Rechazos = 0 }
	self.EstadoCambiado = Signal.new() -- (pcId, estadoPublico)
	self.Maid = Maid.new()
	self.MaidMapa = Maid.new() -- SurfaceGuis, prompts y sus conexiones (se rehacen al reconstruir el mapa)
	self.Activo = false
	self.Listo = false
	self._proyectandoTablero = false
end

function PCService:Start()
	self.Activo = true
	local RemoteService = self:Servicio("RemoteService")
	if RemoteService and typeof(RemoteService.Registrar) == "function" then
		RemoteService:Registrar("PCAction", function(player, datos)
			return self:Manejar(player, datos)
		end)
		-- Parte "PC" del StateSnapshot: el cliente sabe tras reconectar si sigue ocupando un equipo (P10).
		invocar(RemoteService, "AportarSnapshot", "PC", function(player)
			return self:SnapshotJugador(player)
		end)
	else
		warn(PREFIJO .. " RemoteService no disponible: PCAction no tendrá handler.")
	end

	self.RelojTexto = self:CalcularReloj()
	local okConstruir, errConstruir = pcall(self.Construir, self)
	if not okConstruir then
		warn(PREFIJO .. " No se pudieron preparar los PCs: " .. tostring(errConstruir))
	end

	-- Reconstrucción del mapa (MapService:Reconstruir) -> se rehacen pantallas y prompts.
	local MapService = self:Servicio("MapService")
	if MapService and typeof(MapService.Construido) == "table" then
		self:Conectar(MapService.Construido, function()
			task.defer(function()
				local ok, err = pcall(self.Construir, self)
				if not ok then
					warn(PREFIJO .. " Error al reconstruir los PCs: " .. tostring(err))
				end
			end)
		end)
	end

	self:Conectar(Players.PlayerRemoving, function(player)
		self:AlSalirJugador(player)
	end)

	local SchoolDay = self:Servicio("SchoolDayService")
	if SchoolDay then
		if typeof(SchoolDay.JornadaTerminada) == "table" then
			self:Conectar(SchoolDay.JornadaTerminada, function()
				local ok, err = pcall(self.AlTerminarJornada, self)
				if not ok then
					warn(PREFIJO .. " Error al cerrar la jornada: " .. tostring(err))
				end
			end)
		end
		if typeof(SchoolDay.EstadoCambiado) == "table" then
			self:Conectar(SchoolDay.EstadoCambiado, function()
				task.defer(function()
					pcall(self.ActualizarReloj, self)
				end)
			end)
		end
	end

	local RoleService = self:Servicio("RoleService")
	if RoleService and typeof(RoleService.CargoCambiado) == "table" then
		self:Conectar(RoleService.CargoCambiado, function(player)
			pcall(self.AlCambiarCargo, self, player)
		end)
	end

	self.Maid:GiveTask(task.spawn(function()
		self:BucleVigilancia()
	end))
end

-- Detiene el servicio y retira pantallas y prompts (uso desde Studio / desinstalador).
function PCService:Detener()
	self.Activo = false
	for pcId in pairs(self.Ocupaciones) do
		self:Liberar(pcId, "El servicio de computadores se detuvo.")
	end
	self.MaidMapa:DoCleaning()
	self.Maid:DoCleaning()
	self.Pantallas = {}
	self.Prompts = {}
end

-- Servicio por nombre a través del registro (nil si no existe).
function PCService:Servicio(nombre)
	local registro = self.registro
	if registro and typeof(registro.Get) == "function" then
		local ok, servicio = pcall(registro.Get, nombre)
		if ok and typeof(servicio) == "table" then
			return servicio
		end
	end
	return nil
end

-- Conecta una señal (RBXScriptSignal o Signal propio) y guarda la conexión en el Maid indicado.
function PCService:Conectar(senal, fn, maid)
	maid = maid or self.Maid
	if senal == nil then
		return nil
	end
	local ok, conexion = pcall(function()
		return senal:Connect(fn)
	end)
	if ok and conexion ~= nil then
		maid:GiveTask(conexion)
		return conexion
	end
	return nil
end

function PCService:Auditar(categoria, player, accion, detalle)
	local AuditLog = self:Servicio("AuditLogService")
	if AuditLog and typeof(AuditLog.Registrar) == "function" then
		pcall(AuditLog.Registrar, AuditLog, categoria, player, accion, detalle)
	end
end

-- Rechazo lógico de PCAction (estado, distancia, pertenencia, datos): se audita; los sospechosos van a métricas.
function PCService:Rechazo(player, motivo, detalle, sospechoso)
	self.Estadisticas.Rechazos = self.Estadisticas.Rechazos + 1
	local texto = tostring(motivo)
	if detalle ~= nil and detalle ~= "" then
		texto = texto .. ": " .. tostring(detalle)
	end
	self:Auditar("Remoto", player, "PCAction", texto)
	if sospechoso then
		invocar(self:Servicio("MetricsService"), "IncrementarRechazo", "PCAction", motivo)
	end
end

function PCService:Enviar(player, datos)
	if not esJugador(player) or player.Parent == nil then
		return false
	end
	local ok, enviado = invocar(self:Servicio("RemoteService"), "Enviar", player, "PC", datos)
	return ok and enviado == true
end

function PCService:Notificar(player, texto, nivel)
	if not esJugador(player) or typeof(texto) ~= "string" or texto == "" then
		return
	end
	invocar(self:Servicio("RemoteService"), "Enviar", player, "Notificacion", {
		Titulo = "Computador", Texto = texto, Nivel = nivel or "info", Tipo = nivel or "info", Duracion = 4,
	})
end

---------------------------------------------------------------------------------------------------
-- Construcción de PCs (pantallas y prompts) a partir de MapService
---------------------------------------------------------------------------------------------------
function PCService:Sala(roomId)
	local sala = self.Salas[roomId]
	if not sala then
		sala = { RoomId = roomId, Bloqueado = false, BloqueadoPor = nil, BloqueadoPorNombre = nil, Proyeccion = nil }
		self.Salas[roomId] = sala
	end
	return sala
end

function PCService:Construir()
	local MapService = self:Servicio("MapService")
	local lista = {}
	local okLista, resultado = invocar(MapService, "PCs")
	if okLista and typeof(resultado) == "table" then
		lista = resultado
	elseif not MapService then
		warn(PREFIJO .. " MapService no disponible: no hay PCs que preparar.")
	end

	local anteriores = self.Registros
	self.MaidMapa:DoCleaning()
	self.Pantallas = {}
	self.Prompts = {}
	self.Registros = {}
	self.Orden = {}
	self.PorSala = {}

	local conSeat = 0
	for _, registro in ipairs(lista) do
		local valido = typeof(registro) == "table" and typeof(registro.Id) == "string" and registro.Id ~= ""
			and typeof(registro.Pantalla) == "Instance" and registro.Pantalla:IsA("BasePart")
		if valido and self.Registros[registro.Id] == nil then
			local seat = registro.Seat
			if typeof(seat) ~= "Instance" or not seat:IsA("BasePart") then
				seat = nil
			end
			local sala = registro.RoomId
			if typeof(sala) ~= "string" or sala == "" then
				sala = Zones.IdDe(registro.Pantalla.Position) or "SIN_SALA"
			end
			local deSala = self.PorSala[sala]
			if not deSala then
				deSala = {}
				self.PorSala[sala] = deSala
			end
			table.insert(deSala, registro.Id)
			self.Registros[registro.Id] = {
				Id = registro.Id,
				Pantalla = registro.Pantalla,
				Seat = seat,
				RoomId = sala,
				Marcador = registro.Marcador,
				Modelo = registro.Modelo,
				Numero = #deSala,
			}
			table.insert(self.Orden, registro.Id)
			if seat then
				conSeat = conSeat + 1
			end
		end
	end

	-- PCs que desaparecen o cambian de pantalla/asiento: se liberan.
	for pcId, estado in pairs(self.Estados) do
		local actual = self.Registros[pcId]
		if not actual then
			if estado.OcupanteUserId ~= nil then
				self:Liberar(pcId, "El equipo dejó de estar disponible.")
			end
			self.Estados[pcId] = nil
		elseif estado.OcupanteUserId ~= nil then
			local anterior = anteriores[pcId]
			if not anterior or anterior.Seat ~= actual.Seat or anterior.Pantalla ~= actual.Pantalla then
				self:Liberar(pcId, "El equipo se reinició.")
			end
		end
	end

	for _, pcId in ipairs(self.Orden) do
		local info = self.Registros[pcId]
		local sala = self:Sala(info.RoomId)
		local estado = self.Estados[pcId]
		if not estado then
			estado = { Encendido = false, OcupanteUserId = nil, OcupanteNombre = nil, Bloqueado = false, Aplicacion = nil, Proyeccion = nil }
			self.Estados[pcId] = estado
		end
		estado.Bloqueado = sala.Bloqueado == true
		estado.Proyeccion = sala.Proyeccion and sala.Proyeccion.Texto or nil
		local okGui, errGui = pcall(self.CrearPantalla, self, pcId)
		if not okGui then
			warn(PREFIJO .. " No se pudo crear la pantalla de " .. pcId .. ": " .. tostring(errGui))
		end
		local okPrompt, errPrompt = pcall(self.CrearPrompt, self, pcId)
		if not okPrompt then
			warn(PREFIJO .. " No se pudo crear el prompt de " .. pcId .. ": " .. tostring(errPrompt))
		end
		self:ActualizarPantalla(pcId, true)
		self:ActualizarPrompt(pcId)
	end

	local salas = 0
	for _ in pairs(self.PorSala) do
		salas = salas + 1
	end
	self:Auditar("Sistema", nil, "PCs", string.format("%d PCs preparados (%d con Seat) en %d salas", #self.Orden, conSeat, salas))
	self.Listo = true
end

-- Punto hacia el que debe mirar la pantalla: el Seat emparejado o el centro de la sala.
function PCService:PuntoObjetivo(info)
	if info.Seat then
		return info.Seat.Position
	end
	local zona = MapaLogico.Zonas and MapaLogico.Zonas[info.RoomId]
	if zona and typeof(zona.Centro) == "Vector3" then
		return zona.Centro
	end
	return nil
end

-- Cara lateral de la pantalla que mira hacia el objetivo (ponderada por el área: descarta los cantos finos).
function PCService:ElegirCara(pantalla, objetivo)
	if typeof(objetivo) ~= "Vector3" then
		return Enum.NormalId.Front
	end
	local direccion = objetivo - pantalla.Position
	direccion = Vector3.new(direccion.X, 0, direccion.Z)
	if direccion.Magnitude < 0.05 then
		return Enum.NormalId.Front
	end
	direccion = direccion.Unit
	local tamano = pantalla.Size
	local mejor, mejorPuntaje = Enum.NormalId.Front, -math.huge
	for _, cara in ipairs(CARAS_LATERALES) do
		local normal = pantalla.CFrame:VectorToWorldSpace(Vector3.FromNormalId(cara))
		local plano = Vector3.new(normal.X, 0, normal.Z)
		if plano.Magnitude > 0.05 then
			local alineacion = plano.Unit:Dot(direccion) * math.min(1, plano.Magnitude)
			local area = tamano.Z * tamano.Y
			if cara == Enum.NormalId.Front or cara == Enum.NormalId.Back then
				area = tamano.X * tamano.Y
			end
			if alineacion > 0 then
				local puntaje = alineacion * math.sqrt(math.max(area, 0.01))
				if puntaje > mejorPuntaje then
					mejor, mejorPuntaje = cara, puntaje
				end
			end
		end
	end
	return mejor
end

local function nuevoMarco(nombre, padre, color, transparencia, posicion, tamano, z)
	local marco = Instance.new("Frame")
	marco.Name = nombre
	marco.BackgroundColor3 = color
	marco.BackgroundTransparency = transparencia or 0
	marco.BorderSizePixel = 0
	marco.Position = posicion or UDim2.new(0, 0, 0, 0)
	marco.Size = tamano or UDim2.new(1, 0, 1, 0)
	marco.ZIndex = z or 1
	marco.Parent = padre
	return marco
end

local function nuevoTexto(nombre, padre, contenido, fuente, color, posicion, tamano, alineacion, maximo, z)
	local label = Instance.new("TextLabel")
	label.Name = nombre
	label.BackgroundTransparency = 1
	label.BorderSizePixel = 0
	label.Font = fuente
	label.TextColor3 = color
	label.TextScaled = true
	label.TextWrapped = true
	label.Text = contenido
	label.TextXAlignment = alineacion or Enum.TextXAlignment.Center
	label.TextYAlignment = Enum.TextYAlignment.Center
	label.Position = posicion
	label.Size = tamano
	label.ZIndex = z or 2
	local limite = Instance.new("UITextSizeConstraint")
	limite.MaxTextSize = maximo or 40
	limite.MinTextSize = 4
	limite.Parent = label
	label.Parent = padre
	return label
end

-- SurfaceGui de la pantalla. Va dentro del marcador del PC en Workspace.ColegioRP_Mapa.PCs (Adornee = monitor
-- real), así se regenera con el mapa y no se añade nada al modelo original; si no hay marcador, va en el monitor.
function PCService:CrearPantalla(pcId)
	local info = self.Registros[pcId]
	local pantalla = info.Pantalla
	local padre = info.Marcador
	if typeof(padre) ~= "Instance" or padre.Parent == nil then
		padre = pantalla
	end
	local previa = padre:FindFirstChild(NOMBRE_GUI)
	if previa and previa:GetAttribute("ColegioRP") == true then
		previa:Destroy()
	end

	local gui = Instance.new("SurfaceGui")
	gui.Name = NOMBRE_GUI
	gui.Adornee = pantalla
	gui.Face = self:ElegirCara(pantalla, self:PuntoObjetivo(info))
	gui.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud
	gui.PixelsPerStud = self.PixelesPorStud
	gui.LightInfluence = 0
	gui.AlwaysOnTop = false
	gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	gui.ClipsDescendants = true
	gui:SetAttribute("ColegioRP", true)
	gui:SetAttribute("PcId", pcId)

	local etiquetaEquipo = "Equipo " .. tostring(info.Numero) .. " · " .. pcId
	local base = nuevoMarco("Base", gui, Color3.new(0, 0, 0), 0)
	local escritorio = nuevoMarco("Escritorio", base, Colores.Azul, 0, nil, nil, 2)
	local degradado = Instance.new("UIGradient")
	degradado.Color = ColorSequence.new(Colores.Azul, Colores.GrisPanel)
	degradado.Rotation = 90
	degradado.Parent = escritorio
	local barra = nuevoMarco("Barra", escritorio, Colores.RojoOscuro, 0, UDim2.new(0, 0, 0, 0), UDim2.new(1, 0, 0.2, 0), 3)
	nuevoTexto("Colegio", barra, tostring(Config.NombreCorto or Config.NombreColegio or "Colegio"), UITheme.Fuente("Titulo"),
		Colores.Blanco, UDim2.new(0.04, 0, 0.1, 0), UDim2.new(0.62, 0, 0.8, 0), Enum.TextXAlignment.Left, 28, 4)
	local reloj = nuevoTexto("Reloj", barra, self.RelojTexto, UITheme.Fuente("Titulo"), Colores.Amarillo,
		UDim2.new(0.7, 0, 0.1, 0), UDim2.new(0.26, 0, 0.8, 0), Enum.TextXAlignment.Right, 28, 4)
	local centro = nuevoTexto("Centro", escritorio, "Escritorio escolar", UITheme.Fuente("Subtitulo"), Colores.Blanco,
		UDim2.new(0.06, 0, 0.25, 0), UDim2.new(0.88, 0, 0.47, 0), nil, 36, 3)
	local estadoTexto = nuevoTexto("Estado", escritorio, "Libre", UITheme.Fuente("Texto"), Colores.TextoSecundario,
		UDim2.new(0.06, 0, 0.75, 0), UDim2.new(0.88, 0, 0.12, 0), nil, 24, 3)
	nuevoTexto("Equipo", escritorio, etiquetaEquipo, UITheme.Fuente("Texto"), Colores.TextoApagado,
		UDim2.new(0.06, 0, 0.88, 0), UDim2.new(0.88, 0, 0.09, 0), nil, 14, 3)
	local apagado = nuevoMarco("Apagado", base, Color3.new(0, 0, 0), 0, nil, nil, 5)
	local estadoApagado = nuevoTexto("EstadoApagado", apagado, "Libre", UITheme.Fuente("Texto"), Colores.TextoApagado,
		UDim2.new(0.1, 0, 0.74, 0), UDim2.new(0.8, 0, 0.12, 0), nil, 18, 6)
	nuevoTexto("EquipoApagado", apagado, etiquetaEquipo, UITheme.Fuente("Texto"), Color3.fromRGB(70, 72, 78),
		UDim2.new(0.1, 0, 0.87, 0), UDim2.new(0.8, 0, 0.09, 0), nil, 12, 6)
	local bloqueo = nuevoMarco("Bloqueo", base, Colores.RojoOscuro, 0.1, UDim2.new(0, 0, 0.36, 0), UDim2.new(1, 0, 0.28, 0), 8)
	nuevoTexto("TextoBloqueo", bloqueo, "BLOQUEADO POR EL DOCENTE", UITheme.Fuente("Titulo"), Colores.Blanco,
		UDim2.new(0.04, 0, 0.1, 0), UDim2.new(0.92, 0, 0.8, 0), nil, 28, 9)
	escritorio.Visible = false
	bloqueo.Visible = false

	gui.Parent = padre
	self.MaidMapa:GiveTask(gui)
	self.Pantallas[pcId] = {
		Gui = gui, Escritorio = escritorio, Reloj = reloj, Centro = centro, Estado = estadoTexto,
		Apagado = apagado, EstadoApagado = estadoApagado, Bloqueo = bloqueo, Firma = nil,
	}
end

-- ProximityPrompt sobre el monitor real (añadir prompts a objetos existentes está permitido por §0.1; se retira
-- al reconstruir o detener el servicio). Triggered se resuelve en el servidor.
function PCService:CrearPrompt(pcId)
	local info = self.Registros[pcId]
	local pantalla = info.Pantalla
	local previo = pantalla:FindFirstChild(NOMBRE_PROMPT)
	if previo and previo:IsA("ProximityPrompt") and previo:GetAttribute("ColegioRP") == true then
		previo:Destroy()
	end
	local prompt = Instance.new("ProximityPrompt")
	prompt.Name = NOMBRE_PROMPT
	prompt.ActionText = "Usar computador"
	prompt.ObjectText = "Equipo " .. tostring(info.Numero)
	prompt.HoldDuration = 0
	prompt.RequiresLineOfSight = false
	prompt.KeyboardKeyCode = Enum.KeyCode.E
	prompt.GamepadKeyCode = Enum.KeyCode.ButtonX
	if info.Seat then
		prompt.MaxActivationDistance = self.DistanciaPromptConSeat
	else
		prompt.MaxActivationDistance = self.DistanciaPromptSinSeat
	end
	pcall(function()
		prompt.Exclusivity = Enum.ProximityPromptExclusivity.OnePerButton
	end)
	prompt:SetAttribute("RPTipo", "PC")
	prompt:SetAttribute("RPId", pcId)
	prompt:SetAttribute("RPAccion", "Usar")
	prompt:SetAttribute("ColegioRP", true)
	prompt.Parent = pantalla
	self.MaidMapa:GiveTask(prompt)
	self.MaidMapa:GiveTask(prompt.Triggered:Connect(function(player)
		self:AlActivarPrompt(player, pcId)
	end))
	self.Prompts[pcId] = prompt
end

---------------------------------------------------------------------------------------------------
-- Pantallas (solo se redibujan al cambiar)
---------------------------------------------------------------------------------------------------
function PCService:NombreApp(app)
	local actividad = Catalogs.ActividadPC(app)
	if actividad then
		return actividad.Nombre
	end
	return self.AppsExtra[app] or tostring(app)
end

function PCService:AppValida(app)
	return typeof(app) == "string" and (Catalogs.ActividadPC(app) ~= nil or self.AppsExtra[app] ~= nil)
end

function PCService:ActualizarPantalla(pcId, forzar)
	local pantalla = self.Pantallas[pcId]
	local estado = self.Estados[pcId]
	local info = self.Registros[pcId]
	if not pantalla or not estado or not info or not pantalla.Gui or pantalla.Gui.Parent == nil then
		return
	end
	local proyeccion = estado.Proyeccion
	local encendidoVisual = estado.Encendido == true or proyeccion ~= nil
	local textoEstado = "Libre"
	if estado.OcupanteUserId ~= nil then
		textoEstado = "Ocupado por " .. tostring(estado.OcupanteNombre or "un estudiante")
	end
	local centro = "Escritorio escolar"
	if proyeccion ~= nil then
		centro = "Proyección del docente:\n" .. proyeccion
	elseif estado.Aplicacion ~= nil then
		centro = self:NombreApp(estado.Aplicacion)
	elseif estado.OcupanteUserId == nil then
		if info.Seat then
			centro = "Siéntate y pulsa para usar"
		else
			centro = "Acércate y pulsa para usar"
		end
	end
	local reloj = ""
	if encendidoVisual then
		reloj = self.RelojTexto
	end
	local firma = table.concat({
		encendidoVisual and "1" or "0", estado.Bloqueado and "1" or "0", textoEstado, centro, reloj,
	}, "|")
	if not forzar and pantalla.Firma == firma then
		return
	end
	pantalla.Firma = firma
	fijarVisible(pantalla.Escritorio, encendidoVisual)
	fijarVisible(pantalla.Apagado, not encendidoVisual)
	fijarVisible(pantalla.Bloqueo, estado.Bloqueado == true)
	fijarTexto(pantalla.Estado, textoEstado)
	fijarTexto(pantalla.EstadoApagado, textoEstado)
	fijarTexto(pantalla.Centro, centro)
	if encendidoVisual then
		fijarTexto(pantalla.Reloj, reloj)
	end
end

function PCService:ActualizarPrompt(pcId)
	local prompt = self.Prompts[pcId]
	local estado = self.Estados[pcId]
	if not prompt or not estado or prompt.Parent == nil then
		return
	end
	local habilitado = estado.OcupanteUserId == nil
	if prompt.Enabled ~= habilitado then
		prompt.Enabled = habilitado
	end
	local accion = "Usar computador"
	if estado.Bloqueado then
		accion = "Bloqueado por el docente"
	end
	if prompt.ActionText ~= accion then
		prompt.ActionText = accion
	end
end

-- Hora escolar (SchoolDayService) o, sin jornada, la hora del servidor. Formato "HH:MM".
function PCService:CalcularReloj()
	local okS, snap = invocar(self:Servicio("SchoolDayService"), "Snapshot")
	if okS and typeof(snap) == "table" and typeof(snap.Estado) == "string" then
		local inicio = segundosDeHora(snap.HoraEscolarInicio) or TimetableDefinitions.HoraEscolarSegundos(snap.Estado)
		if inicio then
			local fin = segundosDeHora(snap.HoraEscolarFin) or TimetableDefinitions.HoraEscolarFinSegundos(snap.Estado) or inicio
			local duracion = numeroFinito(snap.Duracion)
			if duracion == nil then
				local periodo = TimetableDefinitions.Periodo(snap.Estado)
				duracion = (periodo and periodo.Duracion) or 0
			end
			local progreso = 0
			if snap.Pausada == true then
				progreso = numeroFinito(snap.Progreso)
				if progreso == nil and self.ProgresoCongelado and self.ProgresoCongelado.Estado == snap.Estado then
					progreso = self.ProgresoCongelado.Valor
				end
				progreso = progreso or 0
			else
				local inicioServidor = numeroFinito(snap.InicioServidor)
				if inicioServidor and duracion > 0 then
					progreso = (ahoraServidor() - inicioServidor) / duracion
				end
			end
			progreso = math.clamp(progreso, 0, 1)
			self.ProgresoCongelado = { Estado = snap.Estado, Valor = progreso }
			return Format.HoraHHMM(inicio + (fin - inicio) * progreso)
		end
	end
	local t = os.date("*t")
	if typeof(t) == "table" then
		return string.format("%02d:%02d", t.hour or 0, t.min or 0)
	end
	return "--:--"
end

function PCService:ActualizarReloj()
	local texto = self:CalcularReloj()
	if texto == self.RelojTexto then
		return
	end
	self.RelojTexto = texto
	for _, pcId in ipairs(self.Orden) do
		self:ActualizarPantalla(pcId)
	end
end

---------------------------------------------------------------------------------------------------
-- Estado público
---------------------------------------------------------------------------------------------------
function PCService:EstadoPublico(pcId)
	local estado = self.Estados[pcId]
	if not estado then
		return nil
	end
	local info = self.Registros[pcId]
	return {
		PcId = pcId,
		RoomId = info and info.RoomId or nil,
		Numero = info and info.Numero or nil,
		Encendido = estado.Encendido == true,
		Ocupante = estado.OcupanteUserId,
		OcupanteNombre = estado.OcupanteNombre,
		Bloqueado = estado.Bloqueado == true,
		Aplicacion = estado.Aplicacion,
		Proyeccion = estado.Proyeccion,
		TieneSeat = info ~= nil and info.Seat ~= nil,
	}
end

function PCService:EmitirCambio(pcId)
	local publico = self:EstadoPublico(pcId)
	local ok, err = pcall(function()
		self.EstadoCambiado:Fire(pcId, publico)
	end)
	if not ok then
		warn(PREFIJO .. " Error en EstadoCambiado: " .. tostring(err))
	end
end

function PCService:EnviarEstado(player, pcId, motivo)
	local publico = self:EstadoPublico(pcId) or { PcId = pcId }
	publico.Sub = "Estado"
	publico.Motivo = motivo
	return self:Enviar(player, publico)
end

-- Destinatarios de los avisos de una sala: jugadores dentro de la zona, ocupantes de sus PCs y un actor extra.
function PCService:EnviarASala(roomId, datos, extraJugador)
	local destinatarios, vistos = {}, {}
	local function agregar(player)
		if esJugador(player) and player.Parent ~= nil and not vistos[player] then
			vistos[player] = true
			table.insert(destinatarios, player)
		end
	end
	local okZona, enZona = invocar(self:Servicio("RemoteService"), "JugadoresEnZona", roomId)
	if okZona and typeof(enZona) == "table" then
		for _, player in ipairs(enZona) do
			agregar(player)
		end
	else
		for _, player in ipairs(Players:GetPlayers()) do
			local posicion = posicionDe(player)
			if posicion and Zones.Contiene(roomId, posicion) then
				agregar(player)
			end
		end
	end
	for _, pcId in ipairs(self.PorSala[roomId] or {}) do
		local estado = self.Estados[pcId]
		if estado and estado.OcupanteUserId ~= nil then
			agregar(Players:GetPlayerByUserId(estado.OcupanteUserId))
		end
	end
	agregar(extraJugador)
	for _, player in ipairs(destinatarios) do
		self:Enviar(player, datos)
	end
	return #destinatarios
end

---------------------------------------------------------------------------------------------------
-- Ocupación: Usar / Liberar / vigilancia
---------------------------------------------------------------------------------------------------

-- ¿El humanoide está sentado en el Seat del PC? Acepta los Seats duplicados que MapService asocia al canónico.
function PCService:EstaSentadoEn(humanoide, seat)
	local actual = humanoide and humanoide.SeatPart
	if actual == nil or seat == nil then
		return false
	end
	if actual == seat then
		return true
	end
	local okCanon, canonico = invocar(self:Servicio("MapService"), "AsientoCanonico", actual)
	if okCanon and canonico == seat then
		return true
	end
	return actual:IsA("BasePart") and (actual.Position - seat.Position).Magnitude < 0.6
end

function PCService:AlActivarPrompt(player, pcId)
	if not esJugador(player) then
		return
	end
	local ahora = os.clock()
	local ultimo = self.UltimoPrompt[player.UserId]
	if ultimo and ahora - ultimo < self.CooldownPromptSeg then
		return
	end
	self.UltimoPrompt[player.UserId] = ahora
	local ok, mensaje = self:Usar(player, pcId, "Prompt")
	if not ok then
		self:Notificar(player, mensaje, "aviso")
	end
end

-- Ocupa el PC. origen: "Prompt" | "Remoto" | otro. Devuelve true, estadoPublico | false, mensaje.
function PCService:Usar(player, pcId, origen)
	if not esJugador(player) or player.Parent == nil then
		return false, "Jugador no válido."
	end
	local info = self.Registros[pcId]
	local estado = self.Estados[pcId]
	if not info or not estado then
		self:Rechazo(player, "pc_desconocido", tostring(pcId), origen == "Remoto")
		return false, "Ese equipo no existe."
	end
	local humanoide = humanoideVivo(player)
	if not humanoide then
		return false, "Necesitas tu personaje para usar el equipo."
	end

	-- El mismo jugador vuelve a pedirlo: se reenvía el escritorio (cliente reconectado o doble pulsación).
	if estado.OcupanteUserId == player.UserId then
		self:EnviarEscritorio(player, pcId)
		return true, self:EstadoPublico(pcId)
	end
	if estado.OcupanteUserId ~= nil then
		local ocupante = Players:GetPlayerByUserId(estado.OcupanteUserId)
		if ocupante and ocupante.Parent ~= nil then
			return false, "Este equipo está ocupado por " .. tostring(estado.OcupanteNombre or nombreVisible(ocupante)) .. "."
		end
		self:Liberar(pcId, nil, true)
	end
	local sala = self:Sala(info.RoomId)
	if (estado.Bloqueado or sala.Bloqueado) and not self:EsControlDocente(player) then
		return false, "Este equipo está bloqueado por el docente."
	end

	local modoDistancia = false
	if info.Seat then
		if not self:EstaSentadoEn(humanoide, info.Seat) then
			return false, "Siéntate en la silla de este equipo para usarlo."
		end
	else
		local posicion = posicionDe(player)
		if not posicion then
			return false, "Necesitas tu personaje para usar el equipo."
		end
		local distancia = (posicion - info.Pantalla.Position).Magnitude
		if distancia > DISTANCIA_PC + self.ToleranciaDistancia then
			self:Rechazo(player, "distancia", string.format("%s a %.1f studs", pcId, distancia), origen == "Remoto")
			return false, "Acércate al equipo (máximo " .. tostring(DISTANCIA_PC) .. " studs)."
		end
		modoDistancia = true
	end

	local previo = self.PcDeJugador[player.UserId]
	if previo and previo ~= pcId then
		self:Liberar(previo, "Cambiaste de equipo.", true, player.UserId)
	end

	estado.OcupanteUserId = player.UserId
	estado.OcupanteNombre = nombreVisible(player)
	estado.Encendido = true
	estado.Aplicacion = nil
	self.PcDeJugador[player.UserId] = pcId
	self.ModoDistancia[pcId] = modoDistancia
	self.Estadisticas.Usos = self.Estadisticas.Usos + 1
	self:VigilarOcupante(player, pcId, humanoide)

	-- Sin Seat, la pantalla se orienta hacia quien la usa (portátiles de robótica).
	if modoDistancia then
		local widgets = self.Pantallas[pcId]
		local posicion = posicionDe(player)
		if widgets and widgets.Gui and posicion then
			pcall(function()
				widgets.Gui.Face = self:ElegirCara(info.Pantalla, posicion)
			end)
		end
	end

	self:ActualizarPantalla(pcId)
	self:ActualizarPrompt(pcId)
	self:EnviarEscritorio(player, pcId)
	self:EmitirCambio(pcId)
	return true, self:EstadoPublico(pcId)
end

-- Conexiones que liberan el PC si el ocupante muere, pierde el personaje o se levanta del Seat.
function PCService:VigilarOcupante(player, pcId, humanoide)
	local anterior = self.Ocupaciones[pcId]
	if anterior then
		anterior:DoCleaning()
	end
	local maid = Maid.new()
	self.Ocupaciones[pcId] = maid
	local userId = player.UserId
	local info = self.Registros[pcId]
	maid:GiveTask(humanoide.Died:Connect(function()
		self:Liberar(pcId, "Tu personaje se reinició.", false, userId)
	end))
	maid:GiveTask(player.CharacterRemoving:Connect(function()
		self:Liberar(pcId, nil, false, userId)
	end))
	if info and info.Seat then
		local seat = info.Seat
		maid:GiveTask(humanoide:GetPropertyChangedSignal("SeatPart"):Connect(function()
			if not self:EstaSentadoEn(humanoide, seat) then
				self:Liberar(pcId, "Te levantaste del asiento.", false, userId)
			end
		end))
	end
end

-- Libera el PC. esperadoUserId evita liberar a un ocupante nuevo desde conexiones antiguas.
-- silencioso = true no avisa al ocupante. Devuelve true si se liberó.
function PCService:Liberar(pcId, motivo, silencioso, esperadoUserId)
	local estado = self.Estados[pcId]
	if not estado or estado.OcupanteUserId == nil then
		return false
	end
	if esperadoUserId ~= nil and estado.OcupanteUserId ~= esperadoUserId then
		return false
	end
	local userId = estado.OcupanteUserId
	estado.OcupanteUserId = nil
	estado.OcupanteNombre = nil
	estado.Encendido = false
	estado.Aplicacion = nil
	if self.PcDeJugador[userId] == pcId then
		self.PcDeJugador[userId] = nil
	end
	self.ModoDistancia[pcId] = nil
	local maid = self.Ocupaciones[pcId]
	self.Ocupaciones[pcId] = nil
	if maid then
		maid:DoCleaning()
	end
	self:ActualizarPantalla(pcId)
	self:ActualizarPrompt(pcId)
	if not silencioso then
		local player = Players:GetPlayerByUserId(userId)
		if player and player.Parent ~= nil then
			self:EnviarEstado(player, pcId, motivo)
		end
	end
	self:EmitirCambio(pcId)
	return true
end

function PCService:BucleVigilancia()
	local ciclos = 0
	while self.Activo do
		task.wait(self.IntervaloVigilanciaSeg)
		local ok, err = pcall(self.Vigilar, self)
		if not ok then
			warn(PREFIJO .. " Error al vigilar los PCs: " .. tostring(err))
		end
		ciclos = ciclos + 1
		if ciclos >= self.CiclosReloj then
			ciclos = 0
			local okReloj, errReloj = pcall(self.ActualizarReloj, self)
			if not okReloj then
				warn(PREFIJO .. " Error al actualizar el reloj: " .. tostring(errReloj))
			end
		end
	end
end

-- Respaldo de las conexiones: presencia, vida, asiento y distancia de cada ocupante.
function PCService:Vigilar()
	for _, pcId in ipairs(self.Orden) do
		local estado = self.Estados[pcId]
		if estado and estado.OcupanteUserId ~= nil then
			local userId = estado.OcupanteUserId
			local player = Players:GetPlayerByUserId(userId)
			local info = self.Registros[pcId]
			if not player or player.Parent == nil then
				self:Liberar(pcId, nil, true, userId)
			else
				local humanoide = humanoideVivo(player)
				if not humanoide then
					self:Liberar(pcId, "Tu personaje se reinició.", false, userId)
				elseif info and info.Seat then
					if not self:EstaSentadoEn(humanoide, info.Seat) then
						self:Liberar(pcId, "Te levantaste del asiento.", false, userId)
					end
				elseif info then
					local posicion = posicionDe(player)
					if not posicion or (posicion - info.Pantalla.Position).Magnitude > DISTANCIA_PC + self.MargenAlejarse then
						self:Liberar(pcId, "Te alejaste del equipo.", false, userId)
					end
				end
			end
		end
	end
end

---------------------------------------------------------------------------------------------------
-- Escritorio del cliente
---------------------------------------------------------------------------------------------------
function PCService:MateriaActual()
	local okS, snap = invocar(self:Servicio("SchoolDayService"), "Snapshot")
	if okS and typeof(snap) == "table" and typeof(snap.Materia) == "string" and TimetableDefinitions.Materias[snap.Materia] then
		return snap.Materia
	end
	return self.MateriaPorDefecto
end

-- Clave de la jornada actual: número de jornada de SchoolDayService o, sin él, día + contador local.
function PCService:ClaveJornada()
	local okS, snap = invocar(self:Servicio("SchoolDayService"), "Snapshot")
	if okS and typeof(snap) == "table" and numeroFinito(snap.Jornada) then
		return "J" .. tostring(math.floor(numeroFinito(snap.Jornada)))
	end
	return Format.ClaveDia(os.time()) .. "#" .. tostring(self.JornadaLocal)
end

function PCService:EntregasDe(player)
	local clave = self:ClaveJornada()
	if self.Entregas.Clave ~= clave then
		self.Entregas = { Clave = clave, PorJugador = {} }
	end
	local propias = self.Entregas.PorJugador[player.UserId]
	if not propias then
		propias = {}
		self.Entregas.PorJugador[player.UserId] = propias
	end
	return propias
end

function PCService:ResumenEntregas(player)
	local resumen = {}
	for id, r in pairs(self:EntregasDe(player)) do
		resumen[id] = {
			CuestionarioId = id, Aciertos = r.Aciertos, Total = r.Total, Porcentaje = r.Porcentaje,
			Recompensa = r.Recompensa, Detalle = r.Detalle, Aprobado = r.Aprobado,
		}
	end
	return resumen
end

function PCService:EnviarEscritorio(player, pcId)
	local info = self.Registros[pcId]
	local estado = self.Estados[pcId]
	if not info or not estado then
		return false
	end
	local sala = self:Sala(info.RoomId)
	local actividad = nil
	local okA, snap = invocar(self:Servicio("ClassroomService"), "Snapshot", player)
	if okA and typeof(snap) == "table" then
		actividad = copiaSegura(snap)
	end
	local proyeccion = nil
	if sala.Proyeccion then
		proyeccion = { Texto = sala.Proyeccion.Texto, Autor = sala.Proyeccion.Autor, T = sala.Proyeccion.T }
	end
	local zona = MapaLogico.Zonas and MapaLogico.Zonas[info.RoomId]
	return self:Enviar(player, {
		Sub = "AbrirEscritorio",
		PcId = pcId,
		RoomId = info.RoomId,
		NombreSala = (zona and zona.Nombre) or info.RoomId,
		Apps = Catalogs.ActividadesPC,
		Proyeccion = proyeccion,
		ActividadAula = actividad,
		Estado = self:EstadoPublico(pcId),
		Bloqueado = estado.Bloqueado == true,
		Materia = self:MateriaActual(),
		Entregas = self:ResumenEntregas(player),
		NombreColegio = tostring(Config.NombreCorto or Config.NombreColegio or ""),
		Reloj = self.RelojTexto,
		MaxAnidamiento = self.MaxAnidamiento,
		ToleranciaSimulador = self.ToleranciaSimulador,
		UmbralParticipacion = self.UmbralParticipacion,
	})
end

---------------------------------------------------------------------------------------------------
-- Handler de PCAction
---------------------------------------------------------------------------------------------------
function PCService:Manejar(player, datos)
	if not esJugador(player) or typeof(datos) ~= "table" then
		return fallo("Petición no válida.")
	end
	local accion = datos.Accion
	local pcId = datos.PcId
	local extra = datos.Datos
	if typeof(extra) ~= "table" then
		extra = {}
	end

	if accion == "Usar" then
		local okUsar, resultado = self:Usar(player, pcId, "Remoto")
		if okUsar then
			return exito(resultado)
		end
		return fallo(resultado)
	elseif accion == "Salir" then
		return self:AccionSalir(player, pcId)
	elseif accion == "Encender" or accion == "Apagar" then
		return self:AccionEnergia(player, pcId, accion == "Encender")
	elseif accion == "Aplicacion" then
		return self:AccionAplicacion(player, pcId, extra)
	elseif accion == "Resultado" then
		return self:AccionResultado(player, pcId, extra)
	elseif accion == "Bloquear" or accion == "Desbloquear" then
		return self:AccionBloqueo(player, pcId, accion == "Bloquear")
	elseif accion == "Proyectar" then
		return self:AccionProyectar(player, pcId, extra)
	end
	self:Rechazo(player, "accion_desconocida", tostring(accion), true)
	return fallo("Acción desconocida.")
end

-- Devuelve el estado si el jugador es el ocupante (y, si se pide, el PC está encendido y sin bloqueo).
function PCService:ComprobarOcupante(player, pcId, requiereActivo)
	local estado = self.Estados[pcId]
	if not estado or not self.Registros[pcId] then
		self:Rechazo(player, "pc_desconocido", tostring(pcId), true)
		return nil, "Ese equipo no existe."
	end
	if estado.OcupanteUserId ~= player.UserId then
		self:Rechazo(player, "no_ocupante", pcId, false)
		return nil, "No estás usando este equipo."
	end
	if requiereActivo then
		if estado.Bloqueado and not self:EsControlDocente(player) then
			return nil, "El docente bloqueó este equipo."
		end
		if not estado.Encendido then
			return nil, "Enciende el equipo primero."
		end
	end
	return estado, nil
end

function PCService:AccionSalir(player, pcId)
	local estado = self.Estados[pcId]
	if estado and estado.OcupanteUserId == player.UserId then
		self:Liberar(pcId, nil, false, player.UserId)
	else
		-- Cliente desfasado: si ocupaba otro PC, se libera igualmente. Salir es idempotente.
		local propio = self.PcDeJugador[player.UserId]
		if propio then
			self:Liberar(propio, nil, false, player.UserId)
		end
	end
	return exito({ PcId = pcId, Libre = true })
end

function PCService:AccionEnergia(player, pcId, encender)
	local estado, err = self:ComprobarOcupante(player, pcId, false)
	if not estado then
		return fallo(err)
	end
	if encender and estado.Bloqueado and not self:EsControlDocente(player) then
		return fallo("El docente bloqueó este equipo.")
	end
	if estado.Encendido ~= encender then
		estado.Encendido = encender
		if not encender then
			estado.Aplicacion = nil
		end
		self:ActualizarPantalla(pcId)
		self:EmitirCambio(pcId)
	end
	self:EnviarEstado(player, pcId)
	return exito(self:EstadoPublico(pcId))
end

function PCService:AccionAplicacion(player, pcId, extra)
	local estado, err = self:ComprobarOcupante(player, pcId, true)
	if not estado then
		return fallo(err)
	end
	local app = extra.App
	if app == nil or app == "" or app == "Escritorio" then
		app = nil
	elseif not self:AppValida(app) then
		self:Rechazo(player, "app_invalida", tostring(app), true)
		return fallo("Aplicación desconocida.")
	end
	if estado.Aplicacion ~= app then
		estado.Aplicacion = app
		self:ActualizarPantalla(pcId)
		self:EmitirCambio(pcId)
	end
	return exito({ PcId = pcId, Aplicacion = app })
end

function PCService:AccionResultado(player, pcId, extra)
	local estado, err = self:ComprobarOcupante(player, pcId, true)
	if not estado then
		return fallo(err)
	end
	local app = extra.App
	local resultado, errResultado = nil, nil
	if app == "Procesador" then
		resultado, errResultado = self:ResultadoProcesador(player, pcId, extra)
	elseif app == "Cuestionario" then
		resultado, errResultado = self:ResultadoCuestionario(player, pcId, extra)
	elseif app == "Simulador" then
		resultado, errResultado = self:ResultadoSimulador(player, pcId, extra)
	elseif app == "Programacion" then
		resultado, errResultado = self:ResultadoProgramacion(player, pcId, extra)
	else
		self:Rechazo(player, "app_invalida", tostring(app), true)
		return fallo("Aplicación desconocida.")
	end
	if not resultado then
		return fallo(errResultado)
	end
	self.Estadisticas.Resultados = self.Estadisticas.Resultados + 1
	resultado.App = app
	resultado.PcId = pcId
	local solicitud = enteroEn(extra.Solicitud, 0, 1000000000)
	if solicitud then
		resultado.Solicitud = solicitud
	end
	if estado.Aplicacion ~= app then
		estado.Aplicacion = app
		self:ActualizarPantalla(pcId)
	end
	local evento = copiarTabla(resultado)
	evento.Sub = "Resultado"
	self:Enviar(player, evento)
	return exito(resultado)
end

---------------------------------------------------------------------------------------------------
-- Resultados por aplicación
---------------------------------------------------------------------------------------------------

-- Procesador de texto: el texto (≤ 1200) se añade al cuaderno del jugador.
function PCService:ResultadoProcesador(player, pcId, extra)
	local texto = extra.Texto
	if typeof(texto) ~= "string" then
		return nil, "Escribe algo antes de guardar."
	end
	texto = Format.Recortar(texto)
	local largo = utf8.len(texto)
	if largo == nil then
		self:Rechazo(player, "texto_invalido", pcId, true)
		return nil, "El texto contiene caracteres no válidos."
	end
	if largo == 0 then
		return nil, "El documento está vacío."
	end
	if largo > self.MaxProcesador then
		return nil, "El texto supera los " .. tostring(self.MaxProcesador) .. " caracteres."
	end
	local ahora = os.clock()
	local ultimo = self.UltimoProcesador[player.UserId]
	if ultimo and ahora - ultimo < self.IntervaloProcesadorSeg then
		return nil, string.format("Espera %d s antes de volver a guardar.", math.ceil(self.IntervaloProcesadorSeg - (ahora - ultimo)))
	end
	local materia = extra.Materia
	if typeof(materia) ~= "string" or not TimetableDefinitions.Materias[materia] then
		materia = self:MateriaActual()
	end
	local okGuardar, pagina = self:GuardarEnCuaderno(player, materia, texto)
	if not okGuardar then
		return nil, pagina
	end
	self.UltimoProcesador[player.UserId] = ahora
	self.Estadisticas.Textos = self.Estadisticas.Textos + 1
	return {
		Guardado = true,
		Materia = materia,
		NombreMateria = TimetableDefinitions.NombreMateria(materia),
		Caracteres = largo,
		Pagina = numeroFinito(pagina),
	}
end

local MENSAJES_CUADERNO = {
	sin_perfil = "Tu cuaderno todavía no está cargado; inténtalo en unos segundos.",
	texto_vacio = "El documento está vacío.",
	cuaderno_lleno = "Tu cuaderno está lleno: libera una página antes de guardar.",
}

-- Guarda en el cuaderno con NotebookService:AgregarEntrada; sin él, respaldo directo sobre el perfil (§4).
-- Devuelve true, pagina | false, mensaje.
function PCService:GuardarEnCuaderno(player, materia, texto)
	local Notebook = self:Servicio("NotebookService")
	if Notebook and typeof(Notebook.AgregarEntrada) == "function" then
		local ok, resultado, detalle = invocar(Notebook, "AgregarEntrada", player, materia, texto)
		if not ok then
			return false, "El cuaderno no respondió; inténtalo de nuevo."
		end
		if resultado == false then
			return false, MENSAJES_CUADERNO[detalle] or "No se pudo guardar en el cuaderno."
		end
		return true, detalle
	end

	-- Respaldo: perfil de DataService (Cuaderno = { Titulo, Paginas = { { Materia, Texto, Actualizado } } }).
	local DataService = self:Servicio("DataService")
	local okPerfil, perfil = invocar(DataService, "Obtener", player)
	if not okPerfil or typeof(perfil) ~= "table" then
		return false, MENSAJES_CUADERNO.sin_perfil
	end
	if typeof(perfil.Cuaderno) ~= "table" then
		perfil.Cuaderno = { Titulo = "Mi cuaderno", Paginas = {} }
	end
	if typeof(perfil.Cuaderno.Paginas) ~= "table" then
		perfil.Cuaderno.Paginas = {}
	end
	local paginas = perfil.Cuaderno.Paginas
	local numero = nil
	local ultima = paginas[#paginas]
	if ultima and ultima.Materia == materia and typeof(ultima.Texto) == "string" and ultima.Texto ~= "" then
		local combinado = ultima.Texto .. "\n\n" .. texto
		local largo = utf8.len(combinado)
		if largo and largo <= self.MaxProcesador then
			ultima.Texto = combinado
			ultima.Actualizado = os.time()
			numero = #paginas
		end
	end
	if not numero then
		for i, pagina in ipairs(paginas) do
			if typeof(pagina) == "table" and Format.Recortar(tostring(pagina.Texto or "")) == "" then
				pagina.Texto = texto
				pagina.Materia = materia
				pagina.Actualizado = os.time()
				numero = i
				break
			end
		end
	end
	if not numero then
		if #paginas >= self.MaxPaginasCuaderno then
			return false, MENSAJES_CUADERNO.cuaderno_lleno
		end
		table.insert(paginas, { Materia = materia, Texto = texto, Actualizado = os.time() })
		numero = #paginas
	end
	invocar(DataService, "Marcar", player)
	self:Notificar(player, "Se guardó en tu cuaderno (página " .. tostring(numero) .. ").", "exito")
	return true, numero
end

-- Cuestionario público (corregido aquí) o actividad del aula (reenviada a ClassroomService).
function PCService:ResultadoCuestionario(player, pcId, extra)
	if extra.ActividadId ~= nil then
		return self:ResultadoActividadAula(player, pcId, extra)
	end
	local id = extra.CuestionarioId
	local cuestionario = Catalogs.Cuestionario(id)
	local correctas = cuestionario and Respuestas.Respuestas[id]
	if not cuestionario or typeof(correctas) ~= "table" then
		self:Rechazo(player, "cuestionario_invalido", tostring(id), true)
		return nil, "Ese cuestionario no existe."
	end
	local respuestas = extra.Respuestas
	if typeof(respuestas) ~= "table" then
		return nil, "Faltan las respuestas."
	end
	local preguntas = cuestionario.Preguntas
	local limpias = {}
	local contestadas = 0
	for clave, valor in pairs(respuestas) do
		local indice = enteroEn(clave, 1, #preguntas)
		if indice == nil then
			self:Rechazo(player, "respuestas_formato", tostring(clave), true)
			return nil, "Las respuestas tienen un formato no válido."
		end
		local opcion = enteroEn(valor, 1, #preguntas[indice].Opciones)
		if opcion == nil then
			self:Rechazo(player, "respuesta_fuera_de_rango", id .. "#" .. tostring(indice), true)
			return nil, "Respuesta no válida en la pregunta " .. tostring(indice) .. "."
		end
		if limpias[indice] == nil then
			contestadas = contestadas + 1
		end
		limpias[indice] = opcion
	end
	if contestadas < #preguntas then
		return nil, string.format("Responde todas las preguntas antes de enviar (%d de %d).", contestadas, #preguntas)
	end

	local entregas = self:EntregasDe(player)
	local previa = entregas[id]
	if previa then
		self:Rechazo(player, "cuestionario_repetido", id, false)
		local copia = copiarTabla(previa)
		copia.YaEntregado = true
		return copia
	end

	local aciertos, total, detalle = Respuestas.Corregir(id, limpias)
	local fraccion = 0
	if total > 0 then
		fraccion = aciertos / total
	end
	local aprobado = fraccion >= self.UmbralParticipacion
	local recompensa, saldo, motivoSinRecompensa = 0, nil, nil
	if aprobado then
		local monto = tonumber(RECOMPENSAS.Participacion) or 3
		local Economy = self:Servicio("EconomyService")
		local okE, acreditado, nuevoSaldo = invocar(Economy, "Acreditar", player, monto, "Participacion", "Cuestionario " .. id .. " · " .. pcId)
		if okE and acreditado == true then
			recompensa = monto
			saldo = numeroFinito(nuevoSaldo)
		elseif okE and acreditado == false then
			motivoSinRecompensa = tostring(nuevoSaldo or "")
			if motivoSinRecompensa == "limite_diario" then
				motivoSinRecompensa = "Alcanzaste el límite diario de monedas."
			else
				motivoSinRecompensa = "No se pudo acreditar la recompensa."
			end
		else
			motivoSinRecompensa = "La economía escolar no está disponible."
		end
	end
	local resultado = {
		CuestionarioId = id,
		Titulo = cuestionario.Titulo,
		Aciertos = aciertos,
		Total = total,
		Porcentaje = math.floor(fraccion * 100 + 0.5),
		Detalle = detalle,
		Aprobado = aprobado,
		Recompensa = recompensa,
		Saldo = saldo,
		SinRecompensa = motivoSinRecompensa,
		T = os.time(),
	}
	entregas[id] = resultado
	self.Estadisticas.Cuestionarios = self.Estadisticas.Cuestionarios + 1
	self:SumarProgreso(player, "RespuestasCorrectas", aciertos)
	self:Auditar("Clase", player, "CuestionarioPC", string.format("%s %d/%d (+%d) en %s", id, aciertos, total, recompensa, pcId))
	return copiarTabla(resultado)
end

-- Respuesta a la actividad abierta por el docente: pasa por RemoteService:Procesar("RequestClassAction") para
-- respetar el contrato, los límites y las reglas de ClassroomService (presencia, una respuesta, filtrado).
function PCService:ResultadoActividadAula(player, pcId, extra)
	local actividadId = extra.ActividadId
	if typeof(actividadId) ~= "string" or actividadId == "" or #actividadId > 48 then
		self:Rechazo(player, "actividad_invalida", tostring(actividadId), true)
		return nil, "Actividad no válida."
	end
	local datosClase = { ActividadId = actividadId }
	if typeof(extra.Respuesta) == "string" then
		local texto = Format.Recortar(extra.Respuesta)
		local largo = utf8.len(texto)
		if largo == nil or largo == 0 then
			return nil, "Escribe tu respuesta."
		end
		if largo > self.MaxRespuestaAula then
			return nil, "La respuesta supera los " .. tostring(self.MaxRespuestaAula) .. " caracteres."
		end
		datosClase.Respuesta = texto
	else
		local indice = enteroEn(extra.Respuesta, 1, 20) or enteroEn(extra.Indice, 1, 20)
		if indice == nil then
			return nil, "Elige una opción antes de enviar."
		end
		datosClase.Indice = indice
	end
	local salon = nil
	local okS, sesion = invocar(self:Servicio("ClassroomService"), "SesionDeJugador", player)
	if okS and typeof(sesion) == "table" and typeof(sesion.RoomId) == "string" then
		salon = sesion.RoomId
	end
	if not salon and typeof(extra.Salon) == "string" and extra.Salon ~= "" and #extra.Salon <= 16 then
		salon = extra.Salon
	end
	if not salon then
		return nil, "No hay una clase activa para enviar la respuesta."
	end
	local okP, respuesta = invocar(self:Servicio("RemoteService"), "Procesar", "RequestClassAction", player, {
		Accion = "Responder", Salon = salon, Datos = datosClase,
	})
	if not okP or typeof(respuesta) ~= "table" then
		return nil, "La clase no respondió; inténtalo de nuevo."
	end
	if respuesta.ok ~= true then
		return nil, tostring(respuesta.error or "No se pudo registrar la respuesta.")
	end
	return {
		Aula = true,
		ActividadId = actividadId,
		Salon = salon,
		Enviado = true,
		Mensaje = "Respuesta enviada a tu docente. El resultado es privado y llegará cuando cierre la actividad.",
		Clase = copiaSegura(respuesta.datos),
	}
end

-- Simulador: recalcula con las fórmulas de Catalogs.Simulador y compara cada salida con tolerancia del 2 %.
function PCService:ResultadoSimulador(player, pcId, extra)
	local Simulador = Catalogs.Simulador
	local idExperimento = extra.Experimento
	local experimento = typeof(idExperimento) == "string" and Simulador and Simulador.Experimentos[idExperimento] or nil
	if not experimento then
		self:Rechazo(player, "experimento_invalido", tostring(idExperimento), true)
		return nil, "Experimento desconocido."
	end
	local entradas = extra.Entradas
	if typeof(entradas) ~= "table" then
		return nil, "Faltan los datos de entrada."
	end
	local limpias = {}
	for _, def in ipairs(experimento.Entradas) do
		local valor = numeroFinito(entradas[def.Clave])
		if valor == nil then
			return nil, "Falta el valor de «" .. def.Nombre .. "»."
		end
		if valor < def.Min or valor > def.Max then
			self:Rechazo(player, "entrada_fuera_de_rango", idExperimento .. "." .. def.Clave, false)
			return nil, string.format("«%s» debe estar entre %s y %s.", def.Nombre, Format.Decimal(def.Min, 1), Format.Decimal(def.Max, 1))
		end
		limpias[def.Clave] = valor
	end
	local salidas = extra.Salidas
	if typeof(salidas) ~= "table" then
		return nil, "Faltan tus resultados."
	end
	local calculo, errCalculo = Simulador.Calcular(idExperimento, limpias)
	if not calculo then
		return nil, tostring(errCalculo or "No se pudo calcular el experimento.")
	end
	local correcto = true
	local revision = {}
	for _, def in ipairs(experimento.Salidas) do
		local esperado = numeroFinito(calculo.Salidas[def.Clave])
		local enviado = numeroFinito(salidas[def.Clave])
		local acierto = false
		if esperado ~= nil and enviado ~= nil then
			local tolerancia = math.max(math.abs(esperado) * self.ToleranciaSimulador, 0.01)
			acierto = math.abs(enviado - esperado) <= tolerancia
		end
		revision[def.Clave] = { Enviado = enviado, Esperado = esperado, Correcto = acierto }
		if not acierto then
			correcto = false
		end
	end
	self.Estadisticas.Simulaciones = self.Estadisticas.Simulaciones + 1
	return {
		Experimento = idExperimento,
		Correcto = correcto,
		Revision = revision,
		Esperado = calculo.Salidas,
		Entradas = limpias,
		ToleranciaPorcentaje = math.floor(self.ToleranciaSimulador * 100 + 0.5),
	}
end

-- Programación: ejecuta el intérprete determinista de Catalogs.Programacion en el servidor (8×8, máx. 200 pasos).
function PCService:ResultadoProgramacion(player, pcId, extra)
	local Programacion = Catalogs.Programacion
	if typeof(Programacion) ~= "table" or typeof(Programacion.Ejecutar) ~= "function" then
		return nil, "La programación no está disponible."
	end
	local reto = Programacion.Reto(extra.RetoId)
	if not reto then
		self:Rechazo(player, "reto_invalido", tostring(extra.RetoId), true)
		return nil, "Reto desconocido."
	end
	local crudas = {}
	local programa = extra.Programa
	if typeof(programa) == "string" then
		local sinRetornos = string.gsub(programa, "\r", "")
		for linea in string.gmatch(sinRetornos .. "\n", "([^\n]*)\n") do
			table.insert(crudas, linea)
		end
	elseif typeof(programa) == "table" then
		for _, linea in ipairs(programa) do
			if typeof(linea) ~= "string" then
				return nil, "El programa no es válido."
			end
			table.insert(crudas, linea)
		end
	else
		return nil, "Escribe un programa antes de ejecutarlo."
	end
	while #crudas > 0 and Format.Recortar(crudas[#crudas]) == "" do
		table.remove(crudas)
	end
	if #crudas == 0 then
		return nil, "El programa está vacío."
	end
	local maxLineas = Programacion.MaxLineas or 40
	if #crudas > maxLineas then
		return nil, string.format("El programa tiene %d líneas (máximo %d).", #crudas, maxLineas)
	end
	local maxCaracteres = Programacion.MaxCaracteresLinea or 32
	local lineas = {}
	for i, linea in ipairs(crudas) do
		local limpia = Format.Recortar(linea)
		if #limpia > maxCaracteres then
			return nil, string.format("La línea %d es demasiado larga (máximo %d caracteres).", i, maxCaracteres)
		end
		table.insert(lineas, limpia)
	end

	local resultado = {
		RetoId = reto.Id,
		Nombre = reto.Nombre,
		Inicio = reto.Inicio,
		Meta = reto.Meta,
		MaxPasos = Programacion.MaxPasos,
		Lineas = #lineas,
		Exito = false,
		Pasos = 0,
		Traza = {},
		Posicion = { X = reto.Inicio.X, Y = reto.Inicio.Y, Dir = reto.Inicio.Dir },
	}
	local okAnidamiento, errAnidamiento = comprobarAnidamiento(lineas, self.MaxAnidamiento)
	if not okAnidamiento then
		resultado.Error = errAnidamiento
		return resultado
	end
	local okEjecutar, ejecucion = pcall(Programacion.Ejecutar, reto, lineas)
	if not okEjecutar or typeof(ejecucion) ~= "table" then
		warn(PREFIJO .. " Error del intérprete: " .. tostring(ejecucion))
		return nil, "No se pudo ejecutar el programa."
	end
	resultado.Exito = ejecucion.Exito == true
	resultado.Pasos = numeroFinito(ejecucion.Pasos) or 0
	resultado.Traza = typeof(ejecucion.Traza) == "table" and ejecucion.Traza or {}
	if typeof(ejecucion.Posicion) == "table" then
		resultado.Posicion = ejecucion.Posicion
	end
	resultado.Error = ejecucion.Error
	self.Estadisticas.Programas = self.Estadisticas.Programas + 1
	return resultado
end

function PCService:SumarProgreso(player, clave, cantidad)
	if not cantidad or cantidad <= 0 then
		return
	end
	local DataService = self:Servicio("DataService")
	local okPerfil, perfil = invocar(DataService, "Obtener", player)
	if okPerfil and typeof(perfil) == "table" and typeof(perfil.Progreso) == "table" then
		perfil.Progreso[clave] = (numeroFinito(perfil.Progreso[clave]) or 0) + cantidad
		invocar(DataService, "Marcar", player)
	end
end

---------------------------------------------------------------------------------------------------
-- Control docente: bloqueo y proyección de la sala
---------------------------------------------------------------------------------------------------

-- ¿El jugador controla las salas (pc.bloquear)? El bloqueo de la sala no le impide usar su propio equipo: desde él
-- se desbloquea la sala y se proyecta (si no, quedaría fuera de los controles hasta el fin de la jornada).
function PCService:EsControlDocente(player)
	local okT, tiene = invocar(self:Servicio("RoleService"), "Tiene", player, "pc.bloquear")
	return okT and tiene == true
end

-- Sala que el docente puede controlar a partir de un PcId, un id de sala o su posición. Devuelve roomId | nil, mensaje.
function PCService:SalaDeDocente(player, pcIdOSala)
	local okT, tiene = invocar(self:Servicio("RoleService"), "Tiene", player, "pc.bloquear")
	if not okT or tiene ~= true then
		self:Rechazo(player, "permiso", "pc.bloquear", true)
		return nil, "No tienes permiso para controlar la sala."
	end
	local roomId = nil
	local info = self.Registros[pcIdOSala]
	if info then
		roomId = info.RoomId
	elseif typeof(pcIdOSala) == "string" and self.SalasBloqueables[pcIdOSala] then
		roomId = pcIdOSala
	else
		local posicion = posicionDe(player)
		if posicion then
			local zonaId = Zones.IdDe(posicion)
			if zonaId and self.SalasBloqueables[zonaId] then
				roomId = zonaId
			end
		end
	end
	if not roomId or not self.SalasBloqueables[roomId] then
		self:Rechazo(player, "sala_invalida", tostring(pcIdOSala), false)
		return nil, "Solo se pueden controlar las salas de informática y robótica."
	end
	local okD, esDocente = invocar(self:Servicio("ClassroomService"), "EsDocenteDe", player, roomId)
	if okD and esDocente == true then
		return roomId, nil
	end
	local posicion = posicionDe(player)
	if posicion and Zones.Contiene(roomId, posicion) then
		return roomId, nil
	end
	self:Rechazo(player, "fuera_de_sala", roomId, false)
	return nil, "Debes estar en la sala o dirigir su clase para controlarla."
end

function PCService:AccionBloqueo(player, pcIdOSala, bloquear)
	local roomId, err = self:SalaDeDocente(player, pcIdOSala)
	if not roomId then
		return fallo(err)
	end
	local ok, mensaje = self:BloquearSala(roomId, bloquear, player)
	if not ok then
		return fallo(mensaje)
	end
	return exito({ RoomId = roomId, Bloqueado = bloquear, Mensaje = mensaje })
end

function PCService:AccionProyectar(player, pcIdOSala, extra)
	local roomId, err = self:SalaDeDocente(player, pcIdOSala)
	if not roomId then
		return fallo(err)
	end
	local texto = extra.Texto
	if texto == nil then
		texto = ""
	end
	if typeof(texto) ~= "string" then
		return fallo("El texto no es válido.")
	end
	local ok, resultado = self:Proyectar(roomId, texto, player)
	if not ok then
		return fallo(resultado)
	end
	local datos = { RoomId = roomId }
	if resultado ~= "" then
		datos.Texto = resultado
	end
	return exito(datos)
end

-- Bloquea o desbloquea todos los PCs de la sala. autor (Player) y motivo son opcionales. Devuelve ok, mensaje.
function PCService:BloquearSala(roomId, bloquear, autor, motivo)
	if typeof(roomId) ~= "string" or not self.SalasBloqueables[roomId] then
		return false, "Solo se pueden bloquear las salas de informática y robótica."
	end
	bloquear = bloquear == true
	local sala = self:Sala(roomId)
	if sala.Bloqueado == bloquear then
		if bloquear then
			return true, "La sala ya estaba bloqueada."
		end
		return true, "La sala ya estaba desbloqueada."
	end
	sala.Bloqueado = bloquear
	if bloquear then
		sala.BloqueadoPor = esJugador(autor) and autor.UserId or nil
		sala.BloqueadoPorNombre = nombreVisible(autor)
	else
		sala.BloqueadoPor = nil
		sala.BloqueadoPorNombre = nil
	end
	for _, pcId in ipairs(self.PorSala[roomId] or {}) do
		local estado = self.Estados[pcId]
		if estado then
			estado.Bloqueado = bloquear
			self:ActualizarPantalla(pcId)
			self:ActualizarPrompt(pcId)
			if estado.OcupanteUserId ~= nil then
				local ocupante = Players:GetPlayerByUserId(estado.OcupanteUserId)
				if ocupante then
					self:EnviarEstado(ocupante, pcId)
				end
			end
			self:EmitirCambio(pcId)
		end
	end
	local por = nil
	if esJugador(autor) then
		por = nombreVisible(autor)
	end
	self:EnviarASala(roomId, { Sub = "Bloqueo", RoomId = roomId, Bloqueado = bloquear, Por = por, Motivo = motivo }, autor)
	local detalle = roomId
	if motivo then
		detalle = roomId .. " · " .. tostring(motivo)
	end
	if bloquear then
		self:Auditar("Clase", autor, "BloquearSalaPC", detalle)
	else
		self:Auditar("Clase", autor, "DesbloquearSalaPC", detalle)
	end
	return true, nil
end

-- Proyecta texto (≤ 300) en todas las pantallas de la sala y en el tablero (BoardService:Proyectar si existe).
-- Con autor (Player) el texto se filtra; sin autor se asume ya filtrado por el servicio que llama. "" lo quita.
-- Devuelve true, textoFinal | false, mensaje.
function PCService:Proyectar(roomId, texto, autor)
	if typeof(roomId) ~= "string" or (self.PorSala[roomId] == nil and not self.SalasBloqueables[roomId]) then
		return false, "Sala desconocida."
	end
	if typeof(texto) ~= "string" then
		return false, "El texto no es válido."
	end
	texto = Format.Recortar(texto)
	local largo = utf8.len(texto)
	if largo == nil then
		return false, "El texto contiene caracteres no válidos."
	end
	if largo > self.MaxProyeccion then
		return false, "El texto supera los " .. tostring(self.MaxProyeccion) .. " caracteres."
	end
	local final = texto
	if final ~= "" and esJugador(autor) then
		local filtrado, errFiltro = self:Filtrar(texto, autor)
		if not filtrado then
			return false, errFiltro
		end
		final = filtrado
	end
	local sala = self:Sala(roomId)
	if final == "" then
		sala.Proyeccion = nil
	else
		sala.Proyeccion = {
			Texto = final,
			Autor = nombreVisible(autor),
			AutorUserId = esJugador(autor) and autor.UserId or nil,
			T = os.time(),
		}
	end
	for _, pcId in ipairs(self.PorSala[roomId] or {}) do
		local estado = self.Estados[pcId]
		if estado then
			estado.Proyeccion = sala.Proyeccion and sala.Proyeccion.Texto or nil
			self:ActualizarPantalla(pcId)
		end
	end
	-- Tablero del aula: texto ya filtrado (sin player para no filtrarlo dos veces). Guardia anti-reentrada.
	if final ~= "" and not self._proyectandoTablero then
		local Board = self:Servicio("BoardService")
		if Board then
			self._proyectandoTablero = true
			invocar(Board, "Proyectar", roomId, final)
			self._proyectandoTablero = false
		end
	end
	local evento = { Sub = "Proyeccion", RoomId = roomId }
	if sala.Proyeccion then
		evento.Texto = sala.Proyeccion.Texto
		evento.Autor = sala.Proyeccion.Autor
		evento.T = sala.Proyeccion.T
	end
	self:EnviarASala(roomId, evento, autor)
	if final == "" then
		self:Auditar("Clase", autor, "ProyeccionPC", roomId .. " · (retirada)")
	else
		self:Auditar("Clase", autor, "ProyeccionPC", roomId .. " · " .. Format.Truncar(final, 80))
	end
	return true, final
end

-- Filtrado para difusión (TextService). Si falla, el texto no se muestra a terceros.
function PCService:Filtrar(texto, player)
	local okFiltro, resultado = pcall(function()
		return TextService:FilterStringAsync(texto, player.UserId, Enum.TextFilterContext.PublicChat)
	end)
	if not okFiltro or resultado == nil then
		return nil, "No se pudo filtrar el texto; inténtalo de nuevo."
	end
	local okTexto, filtrado = pcall(function()
		return resultado:GetNonChatStringForBroadcastAsync()
	end)
	if not okTexto or typeof(filtrado) ~= "string" then
		return nil, "No se pudo filtrar el texto; inténtalo de nuevo."
	end
	return filtrado, nil
end

---------------------------------------------------------------------------------------------------
-- Eventos de jugadores y jornada
---------------------------------------------------------------------------------------------------
function PCService:AlSalirJugador(player)
	local userId = player.UserId
	local pcId = self.PcDeJugador[userId]
	if pcId then
		self:Liberar(pcId, nil, true, userId)
	end
	self.UltimoPrompt[userId] = nil
	self.UltimoProcesador[userId] = nil
	self:SoltarControlDocente(player, "El docente salió del servidor.")
end

-- Si el docente pierde pc.bloquear (cambio de cargo) se retiran su bloqueo y su proyección.
function PCService:AlCambiarCargo(player)
	if not esJugador(player) then
		return
	end
	local okT, tiene = invocar(self:Servicio("RoleService"), "Tiene", player, "pc.bloquear")
	if okT and tiene == true then
		return
	end
	self:SoltarControlDocente(player, "El docente cambió de cargo.")
end

function PCService:SoltarControlDocente(player, motivo)
	local userId = player.UserId
	for roomId, sala in pairs(self.Salas) do
		if sala.Bloqueado and sala.BloqueadoPor == userId then
			pcall(self.BloquearSala, self, roomId, false, nil, motivo)
		end
		if sala.Proyeccion and sala.Proyeccion.AutorUserId == userId then
			pcall(self.Proyectar, self, roomId, "", nil)
		end
	end
end

-- Fin de jornada: salas desbloqueadas y proyecciones retiradas (estado temporal). Las entregas de cuestionarios
-- se renuevan solas cuando cambia la clave de jornada (número de SchoolDayService o contador local).
function PCService:AlTerminarJornada()
	self.JornadaLocal = self.JornadaLocal + 1
	for roomId, sala in pairs(self.Salas) do
		if sala.Bloqueado then
			pcall(self.BloquearSala, self, roomId, false, nil, "Fin de la jornada.")
		end
		if sala.Proyeccion then
			pcall(self.Proyectar, self, roomId, "", nil)
		end
	end
end

---------------------------------------------------------------------------------------------------
-- API pública para otros servicios
---------------------------------------------------------------------------------------------------

-- Estado público de un PC (o nil).
function PCService:Estado(pcId)
	return self:EstadoPublico(pcId)
end

-- PC que ocupa el jugador (o nil).
function PCService:PCDeJugador(player)
	if not esJugador(player) then
		return nil
	end
	return self.PcDeJugador[player.UserId]
end

-- Jugadores que ocupan PCs de la sala.
function PCService:Ocupantes(roomId)
	local lista = {}
	for _, pcId in ipairs(self.PorSala[roomId] or {}) do
		local estado = self.Estados[pcId]
		if estado and estado.OcupanteUserId ~= nil then
			local player = Players:GetPlayerByUserId(estado.OcupanteUserId)
			if player then
				table.insert(lista, player)
			end
		end
	end
	return lista
end

-- { RoomId, Bloqueado, BloqueadoPor, Proyeccion, PCs = { estadoPublico... } } de una sala.
function PCService:EstadoSala(roomId)
	local sala = self.Salas[roomId]
	local pcs = {}
	for _, pcId in ipairs(self.PorSala[roomId] or {}) do
		table.insert(pcs, self:EstadoPublico(pcId))
	end
	return {
		RoomId = roomId,
		Bloqueado = sala ~= nil and sala.Bloqueado == true,
		BloqueadoPor = sala and sala.BloqueadoPorNombre or nil,
		Proyeccion = sala and sala.Proyeccion and sala.Proyeccion.Texto or nil,
		PCs = pcs,
	}
end

-- Parte "PC" del StateSnapshot del jugador: equipo ocupado (si hay) y estado de su sala.
function PCService:SnapshotJugador(player)
	local pcId = self:PCDeJugador(player)
	if not pcId then
		return nil
	end
	return { PcId = pcId, Estado = self:EstadoPublico(pcId) }
end

-- Resumen global para paneles de dirección y métricas.
function PCService:Snapshot()
	local pcs, ocupados, encendidos = {}, 0, 0
	for _, pcId in ipairs(self.Orden) do
		local publico = self:EstadoPublico(pcId)
		if publico then
			table.insert(pcs, publico)
			if publico.Ocupante ~= nil then
				ocupados = ocupados + 1
			end
			if publico.Encendido then
				encendidos = encendidos + 1
			end
		end
	end
	local salas = {}
	for roomId, sala in pairs(self.Salas) do
		salas[roomId] = {
			Bloqueado = sala.Bloqueado == true,
			BloqueadoPor = sala.BloqueadoPorNombre,
			Proyeccion = sala.Proyeccion and sala.Proyeccion.Texto or nil,
		}
	end
	return {
		Total = #pcs,
		Ocupados = ocupados,
		Encendidos = encendidos,
		PCs = pcs,
		Salas = salas,
		Estadisticas = copiarTabla(self.Estadisticas),
	}
end

return PCService
]=] }
FUENTES["ServerScriptService/ColegioRP/Services/RemoteService"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ServerScriptService.ColegioRP.Services.RemoteService
	Tipo: ModuleScript
	Puerta de entrada de todos los remotos (docs/ARQUITECTURA.md §5): crea ReplicatedStorage.ColegioRP.Remotes
	desde RemoteContracts, y para cada petición comprueba tabla, esquema (Validate), límite por jugador (ventana
	deslizante), permiso del cargo y distancia opcional antes de llamar al handler registrado en pcall. Los
	rechazos se auditan y alimentan el contador de sospecha. Canal servidor->cliente: Enviar / EnviarATodos /
	EnviarAZona / EnviarAAula sobre el RemoteEvent EventoCliente. Publica además el handler por defecto de
	StateSnapshot (los servicios aportan sus partes con AportarSnapshot).
]]

local Players = game:GetService("Players")

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RP = ReplicatedStorage:WaitForChild("ColegioRP")
local Shared = RP:WaitForChild("Shared")
local Config = require(Shared:WaitForChild("Config"))
local RemoteContracts = require(Shared:WaitForChild("RemoteContracts"))
local Util = Shared:WaitForChild("Util")
local Zones = require(Util:WaitForChild("Zones"))
local Signal = require(Util:WaitForChild("Signal"))

local RemoteService = {}
RemoteService.Nombre = "RemoteService"

local PREFIJO = "[ColegioRP][RemoteService]"
local NOMBRE_CARPETA = (Config.Nombres and Config.Nombres.CarpetaRemotos) or "Remotes"
local NOMBRE_EVENTO_CLIENTE = "EventoCliente"
local RECHAZOS_SOSPECHOSO = (Config.Red and Config.Red.RechazosParaSospechoso) or 20
local VENTANA_SOSPECHOSO = (Config.Red and Config.Red.VentanaSospechosoSeg) or 60

-- Tolerancia (studs) añadida a las comprobaciones de distancia (latencia y tamaño del personaje).
RemoteService.ToleranciaDistancia = 2
-- Motivos de rechazo que no se atribuyen al jugador (no cuentan para la sospecha).
RemoteService.MotivosSinCulpa = { sin_servicio = true, error_interno = true }
-- Segundos mínimos entre entradas de auditoría "limite" del mismo jugador y remoto (evita vaciar el buffer).
RemoteService.IntervaloAuditoriaLimiteSeg = 5
-- Espera máxima (s) del perfil al construir el StateSnapshot por defecto.
RemoteService.EsperaPerfilSnapshotSeg = 5

---------------------------------------------------------------------------------------------------
-- Utilidades
---------------------------------------------------------------------------------------------------
local function esJugador(player)
	return typeof(player) == "Instance" and player:IsA("Player")
end

local function posicionDe(player)
	local personaje = player.Character
	if not personaje then
		return nil
	end
	local raiz = personaje:FindFirstChild("HumanoidRootPart")
	if raiz and raiz:IsA("BasePart") then
		return raiz.Position
	end
	return nil
end

-- Elimina de la lista los instantes anteriores a (ahora - ventana). La lista está ordenada ascendente.
local function podar(lista, ahora, ventana)
	while lista[1] ~= nil and lista[1] <= ahora - ventana do
		table.remove(lista, 1)
	end
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function RemoteService:Init(registro)
	self.registro = registro
	self.Handlers = {} -- nombre -> { Handler = fn(player, datos), Posicion = fn(datos, player) -> Vector3|nil }
	self.Instancias = {} -- nombre -> RemoteEvent | RemoteFunction
	self.Conexiones = {}
	self.Ventanas = {} -- userId -> nombre -> { os.clock ... }
	self.Rechazos = {} -- userId -> { os.clock ... } (ventana de sospecha)
	self.UltimoAvisoSospecha = {} -- userId -> os.clock() del último aviso de sospecha
	self.UltimaAuditoriaLimite = {} -- userId -> nombre -> os.clock() de la última auditoría "limite"
	self.PartesSnapshot = {} -- clave -> fn(player) -> valor (StateSnapshot por defecto)
	self.Estadisticas = {
		Peticiones = 0, Aceptadas = 0, Rechazos = 0, Errores = 0,
		PorMotivo = {}, PorRemoto = {}, Tiempos = {}, Sospechosos = 0,
	}
	self.Sospechoso = Signal.new() -- (player, rechazosEnVentana)
	self.Carpeta = self:CrearCarpeta()
	self:CrearRemotos()
end

function RemoteService:Start()
	self.AuditLog = self.registro.Get("AuditLogService")
	table.insert(self.Conexiones, Players.PlayerRemoving:Connect(function(player)
		self.Ventanas[player.UserId] = nil
		self.Rechazos[player.UserId] = nil
		self.UltimoAvisoSospecha[player.UserId] = nil
		self.UltimaAuditoriaLimite[player.UserId] = nil
	end))
	-- StateSnapshot por defecto (un servicio puede sustituirlo registrando su propio handler).
	if not self.Handlers.StateSnapshot then
		self:Registrar("StateSnapshot", function(player)
			return RemoteContracts.Ok(self:ConstruirSnapshot(player))
		end)
		self.Handlers.StateSnapshot.Defecto = true
	end
	if self.AuditLog then
		self.AuditLog:Registrar("Sistema", nil, "Remotos", #RemoteContracts.Nombres .. " remotos publicados en ReplicatedStorage.ColegioRP." .. NOMBRE_CARPETA)
	end
end

---------------------------------------------------------------------------------------------------
-- Creación de instancias
---------------------------------------------------------------------------------------------------
function RemoteService:CrearCarpeta()
	local carpeta = RP:FindFirstChild(NOMBRE_CARPETA)
	if carpeta and not carpeta:IsA("Folder") then
		warn(PREFIJO .. " " .. NOMBRE_CARPETA .. " existe pero no es Folder; se reemplaza.")
		carpeta:Destroy()
		carpeta = nil
	end
	if not carpeta then
		carpeta = Instance.new("Folder")
		carpeta.Name = NOMBRE_CARPETA
		carpeta.Parent = RP
	end
	return carpeta
end

function RemoteService:CrearRemotos()
	for _, nombre in ipairs(RemoteContracts.Nombres) do
		local def = RemoteContracts.Remotos[nombre]
		local ok, err = pcall(function()
			self:CrearRemoto(nombre, def)
		end)
		if not ok then
			warn(PREFIJO .. " No se pudo crear el remoto " .. nombre .. ": " .. tostring(err))
		end
	end
	-- Instancias huérfanas (no están en el contrato) se avisan pero no se tocan.
	for _, hijo in ipairs(self.Carpeta:GetChildren()) do
		if not RemoteContracts.Existe(hijo.Name) then
			warn(PREFIJO .. " Instancia fuera del contrato en Remotes: " .. hijo.Name)
		end
	end
end

function RemoteService:CrearRemoto(nombre, def)
	local clase = def.Tipo
	if clase ~= "RemoteEvent" and clase ~= "RemoteFunction" then
		warn(PREFIJO .. " Tipo desconocido para " .. nombre .. ": " .. tostring(clase))
		return
	end
	local instancia = self.Carpeta:FindFirstChild(nombre)
	if instancia and not instancia:IsA(clase) then
		instancia:Destroy()
		instancia = nil
	end
	if not instancia then
		instancia = Instance.new(clase)
		instancia.Name = nombre
		instancia.Parent = self.Carpeta
	end
	instancia:SetAttribute("Direccion", def.Direccion)
	self.Instancias[nombre] = instancia
	self.Estadisticas.PorRemoto[nombre] = { Peticiones = 0, Rechazos = 0, Errores = 0 }

	if def.Direccion ~= "C2S" then
		return
	end
	-- Toda petición lleva un único argumento (tabla); los argumentos extra se cuentan para rechazarlos.
	if clase == "RemoteFunction" then
		instancia.OnServerInvoke = function(player, datos, ...)
			return self:Procesar(nombre, player, datos, select("#", ...))
		end
	else
		table.insert(self.Conexiones, instancia.OnServerEvent:Connect(function(player, datos, ...)
			self:Procesar(nombre, player, datos, select("#", ...))
		end))
	end
end

-- Instancia de un remoto por nombre (o nil).
function RemoteService:Instancia(nombre)
	return self.Instancias[nombre]
end

---------------------------------------------------------------------------------------------------
-- Registro de handlers
---------------------------------------------------------------------------------------------------

-- Registra el handler de un remoto C2S: handler(player, datos) -> { ok, error, datos } | tabla de datos | nil.
-- opciones.Posicion = function(datos, player) -> Vector3|nil permite a RemoteService comprobar la distancia
-- (def.Distancia) antes de llamar al handler. Devuelve true si se registró.
function RemoteService:Registrar(nombre, handler, opciones)
	if typeof(handler) ~= "function" then
		warn(PREFIJO .. " Registrar(" .. tostring(nombre) .. "): el handler debe ser una función.")
		return false
	end
	local def = RemoteContracts.Obtener(nombre)
	if not def then
		warn(PREFIJO .. " Registrar: el remoto '" .. tostring(nombre) .. "' no está en RemoteContracts.")
		return false
	end
	if def.Direccion ~= "C2S" then
		warn(PREFIJO .. " Registrar: '" .. nombre .. "' es S2C y no admite handler.")
		return false
	end
	if self.Handlers[nombre] and not self.Handlers[nombre].Defecto then
		warn(PREFIJO .. " El handler de '" .. nombre .. "' ya estaba registrado; se reemplaza.")
	end
	local posicion = nil
	if typeof(opciones) == "table" and typeof(opciones.Posicion) == "function" then
		posicion = opciones.Posicion
	end
	self.Handlers[nombre] = { Handler = handler, Posicion = posicion }
	return true
end

-- Quita el handler de un remoto (las peticiones pasan a responder rechazado:sin_servicio).
function RemoteService:Desregistrar(nombre)
	self.Handlers[nombre] = nil
end

-- ¿Tiene handler registrado?
function RemoteService:TieneHandler(nombre)
	return self.Handlers[nombre] ~= nil
end

---------------------------------------------------------------------------------------------------
-- Límites y sospecha
---------------------------------------------------------------------------------------------------

-- Ventana deslizante por jugador y remoto. Devuelve true si la petición entra en el límite.
function RemoteService:DentroDelLimite(player, nombre)
	local max, ventana = RemoteContracts.LimiteDe(nombre)
	if not max or not ventana then
		return true
	end
	local ahora = os.clock()
	local porJugador = self.Ventanas[player.UserId]
	if not porJugador then
		porJugador = {}
		self.Ventanas[player.UserId] = porJugador
	end
	local lista = porJugador[nombre]
	if not lista then
		lista = {}
		porJugador[nombre] = lista
	end
	podar(lista, ahora, ventana)
	if #lista >= max then
		return false
	end
	table.insert(lista, ahora)
	return true
end

-- Cuenta un rechazo atribuible al jugador; marca Sospechoso al superar el umbral en la ventana.
function RemoteService:ContarSospecha(player)
	local userId = player.UserId
	local ahora = os.clock()
	local lista = self.Rechazos[userId]
	if not lista then
		lista = {}
		self.Rechazos[userId] = lista
	end
	podar(lista, ahora, VENTANA_SOSPECHOSO)
	table.insert(lista, ahora)
	if #lista < RECHAZOS_SOSPECHOSO then
		return
	end
	local cantidad = #lista
	table.clear(lista)
	-- Un jugador ya avisado en esta ventana no repite auditoría ni avisos (no se inunda a moderación).
	local ultimoAviso = self.UltimoAvisoSospecha[userId]
	if ultimoAviso and ahora - ultimoAviso < VENTANA_SOSPECHOSO then
		return
	end
	self.UltimoAvisoSospecha[userId] = ahora
	self.Estadisticas.Sospechosos = self.Estadisticas.Sospechosos + 1
	pcall(function()
		player:SetAttribute("Sospechoso", true)
		player:SetAttribute("SospechosoDesde", os.time())
	end)
	if self.AuditLog then
		self.AuditLog:Registrar("Moderacion", player, "Sospechoso",
			string.format("%d rechazos de remotos en %d s (sin expulsión automática)", cantidad, VENTANA_SOSPECHOSO))
	end
	self.Sospechoso:Fire(player, cantidad)
	-- Aviso a quien tenga moderación básica (sin acciones automáticas).
	local RoleService = self.registro.Get("RoleService")
	if RoleService and typeof(RoleService.ConPermiso) == "function" then
		local okLista, moderadores = pcall(RoleService.ConPermiso, RoleService, "moderacion.basica")
		if okLista and typeof(moderadores) == "table" then
			for _, moderador in ipairs(moderadores) do
				if esJugador(moderador) and moderador ~= player then
					self:Enviar(moderador, "Moderacion", {
						Tipo = "Sospechoso", UserId = userId, Nombre = player.Name, Rechazos = cantidad, VentanaSeg = VENTANA_SOSPECHOSO,
					})
				end
			end
		end
	end
end

-- Registra un rechazo (estadísticas, auditoría, sospecha) y devuelve la respuesta estándar.
function RemoteService:Rechazar(player, nombre, motivo, detalle)
	self.Estadisticas.Rechazos = self.Estadisticas.Rechazos + 1
	self.Estadisticas.PorMotivo[motivo] = (self.Estadisticas.PorMotivo[motivo] or 0) + 1
	local porRemoto = self.Estadisticas.PorRemoto[nombre]
	if porRemoto then
		porRemoto.Rechazos = porRemoto.Rechazos + 1
	end
	local texto = motivo
	if detalle ~= nil and detalle ~= "" then
		texto = motivo .. ": " .. tostring(detalle)
	end
	-- Los rechazos por límite de un mismo jugador y remoto se auditan como máximo uno cada
	-- IntervaloAuditoriaLimiteSeg (una ráfaga no vacía el buffer circular de auditoría).
	local auditar = true
	if motivo == "limite" and esJugador(player) then
		local porJugador = self.UltimaAuditoriaLimite[player.UserId]
		if not porJugador then
			porJugador = {}
			self.UltimaAuditoriaLimite[player.UserId] = porJugador
		end
		local ahora = os.clock()
		local ultimo = porJugador[nombre]
		if ultimo and ahora - ultimo < self.IntervaloAuditoriaLimiteSeg then
			auditar = false
		else
			porJugador[nombre] = ahora
		end
	end
	if auditar and self.AuditLog then
		self.AuditLog:Registrar("Remoto", player, nombre, texto)
	end
	-- Métricas de rechazos (MetricsService es opcional y arranca después).
	local MetricsService = self.registro.Get("MetricsService")
	if MetricsService and typeof(MetricsService.IncrementarRechazo) == "function" then
		local okMetricas, errMetricas = pcall(MetricsService.IncrementarRechazo, MetricsService, nombre, motivo)
		if not okMetricas then
			warn(PREFIJO .. " MetricsService:IncrementarRechazo falló: " .. tostring(errMetricas))
		end
	end
	if esJugador(player) and not self.MotivosSinCulpa[motivo] then
		self:ContarSospecha(player)
	end
	return RemoteContracts.Rechazo(motivo)
end

---------------------------------------------------------------------------------------------------
-- Procesamiento de peticiones
---------------------------------------------------------------------------------------------------
function RemoteService:Procesar(nombre, player, datos, argumentosExtra)
	self.Estadisticas.Peticiones = self.Estadisticas.Peticiones + 1
	local porRemoto = self.Estadisticas.PorRemoto[nombre]
	if porRemoto then
		porRemoto.Peticiones = porRemoto.Peticiones + 1
	end
	if not esJugador(player) then
		return RemoteContracts.Rechazo("jugador_invalido")
	end
	local def = RemoteContracts.Obtener(nombre)
	if not def or def.Direccion ~= "C2S" then
		return self:Rechazar(player, nombre, "remoto_desconocido")
	end

	-- 1. Límite de frecuencia por jugador (ventana deslizante). Va primero para que una ráfaga de cargas
	-- inválidas no esquive el límite ni cueste la validación completa.
	if not self:DentroDelLimite(player, nombre) then
		return self:Rechazar(player, nombre, "limite")
	end

	-- 2. Los datos deben ser una tabla y el único argumento.
	if typeof(datos) ~= "table" then
		return self:Rechazar(player, nombre, "datos_no_tabla", typeof(datos))
	end
	if typeof(argumentosExtra) == "number" and argumentosExtra > 0 then
		return self:Rechazar(player, nombre, "argumentos_extra", argumentosExtra)
	end

	-- 3. Esquema declarado en RemoteContracts.
	local okEsquema, errEsquema = RemoteContracts.Validar(nombre, datos)
	if not okEsquema then
		return self:Rechazar(player, nombre, "esquema", errEsquema)
	end

	-- 4. Permiso del cargo (fijo o según la acción).
	local permiso = RemoteContracts.PermisoPara(nombre, datos)
	if permiso == RemoteContracts.DENEGADO then
		return self:Rechazar(player, nombre, "permiso", "acción no permitida")
	end
	if permiso ~= nil then
		local RoleService = self.registro.Get("RoleService")
		local tiene = false
		if RoleService and typeof(RoleService.Tiene) == "function" then
			local okTiene, resultado = pcall(RoleService.Tiene, RoleService, player, permiso)
			tiene = okTiene and resultado == true
		end
		if not tiene then
			return self:Rechazar(player, nombre, "permiso", permiso)
		end
	end

	-- 5. Handler registrado.
	local registro = self.Handlers[nombre]
	if not registro then
		return self:Rechazar(player, nombre, "sin_servicio")
	end

	-- 6. Distancia (solo si el servicio aportó un resolutor de posición y el contrato fija distancia).
	local distanciaMax = def.Distancia
	if distanciaMax and registro.Posicion then
		local okPos, objetivo = pcall(registro.Posicion, datos, player)
		if okPos and typeof(objetivo) == "Vector3" then
			local posicion = posicionDe(player)
			if not posicion then
				return self:Rechazar(player, nombre, "sin_personaje")
			end
			local distancia = (posicion - objetivo).Magnitude
			if distancia > distanciaMax + self.ToleranciaDistancia then
				return self:Rechazar(player, nombre, "distancia", string.format("%.1f > %.1f", distancia, distanciaMax))
			end
		end
	end

	-- 7. Handler en pcall.
	local t0 = os.clock()
	local okHandler, respuesta = pcall(registro.Handler, player, datos)
	self:RegistrarTiempo(nombre, os.clock() - t0)
	if not okHandler then
		self.Estadisticas.Errores = self.Estadisticas.Errores + 1
		if porRemoto then
			porRemoto.Errores = porRemoto.Errores + 1
		end
		warn(PREFIJO .. " Error en el handler de " .. nombre .. " (" .. player.Name .. "): " .. tostring(respuesta))
		if self.AuditLog then
			self.AuditLog:Registrar("Remoto", player, nombre, "error_interno: " .. tostring(respuesta))
		end
		return RemoteContracts.Error("error_interno")
	end
	self.Estadisticas.Aceptadas = self.Estadisticas.Aceptadas + 1

	-- Normalización de la respuesta a { ok, error, datos }.
	if respuesta == nil then
		return RemoteContracts.Ok()
	end
	if typeof(respuesta) ~= "table" then
		return RemoteContracts.Ok({ Valor = respuesta })
	end
	if respuesta.ok == nil then
		return RemoteContracts.Ok(respuesta)
	end
	if respuesta.ok ~= true then
		respuesta.ok = false
		if respuesta.error == nil then
			respuesta.error = "error"
		end
	end
	return respuesta
end

function RemoteService:RegistrarTiempo(nombre, duracion)
	local t = self.Estadisticas.Tiempos[nombre]
	if not t then
		t = { Suma = 0, N = 0, Max = 0 }
		self.Estadisticas.Tiempos[nombre] = t
	end
	t.Suma = t.Suma + duracion
	t.N = t.N + 1
	if duracion > t.Max then
		t.Max = duracion
	end
end

---------------------------------------------------------------------------------------------------
-- Servidor -> cliente (canal EventoCliente)
---------------------------------------------------------------------------------------------------
function RemoteService:EventoCliente()
	local remoto = self.Instancias[NOMBRE_EVENTO_CLIENTE]
	if remoto and remoto.Parent then
		return remoto
	end
	local def = RemoteContracts.Obtener(NOMBRE_EVENTO_CLIENTE)
	if def then
		pcall(function()
			self:CrearRemoto(NOMBRE_EVENTO_CLIENTE, def)
		end)
	end
	return self.Instancias[NOMBRE_EVENTO_CLIENTE]
end

local function comprobarTipo(tipo)
	if not RemoteContracts.EsTipoEvento(tipo) then
		warn(PREFIJO .. " Tipo de EventoCliente desconocido: " .. tostring(tipo))
		return false
	end
	return true
end

-- Envía { Tipo, Datos } a un jugador. Devuelve true si se envió.
function RemoteService:Enviar(player, tipo, datos)
	if not esJugador(player) or player.Parent == nil then
		return false
	end
	if not comprobarTipo(tipo) then
		return false
	end
	local remoto = self:EventoCliente()
	if not remoto then
		return false
	end
	local ok, err = pcall(remoto.FireClient, remoto, player, { Tipo = tipo, Datos = datos or {} })
	if not ok then
		warn(PREFIJO .. " Error al enviar '" .. tostring(tipo) .. "' a " .. player.Name .. ": " .. tostring(err))
		return false
	end
	return true
end

-- Envía a todos los jugadores.
function RemoteService:EnviarATodos(tipo, datos)
	if not comprobarTipo(tipo) then
		return false
	end
	local remoto = self:EventoCliente()
	if not remoto then
		return false
	end
	local ok, err = pcall(remoto.FireAllClients, remoto, { Tipo = tipo, Datos = datos or {} })
	if not ok then
		warn(PREFIJO .. " Error al enviar a todos '" .. tostring(tipo) .. "': " .. tostring(err))
		return false
	end
	return true
end

-- Envía a una lista de jugadores (Players o userIds). Devuelve cuántos recibieron.
function RemoteService:EnviarALista(lista, tipo, datos)
	if typeof(lista) ~= "table" or not comprobarTipo(tipo) then
		return 0
	end
	local enviados = 0
	local carga = { Tipo = tipo, Datos = datos or {} }
	local remoto = self:EventoCliente()
	if not remoto then
		return 0
	end
	for _, elemento in ipairs(lista) do
		local player = elemento
		if typeof(elemento) == "number" then
			player = Players:GetPlayerByUserId(elemento)
		end
		if esJugador(player) and player.Parent ~= nil then
			local ok = pcall(remoto.FireClient, remoto, player, carga)
			if ok then
				enviados = enviados + 1
			end
		end
	end
	return enviados
end

-- Jugadores cuyo HumanoidRootPart está dentro de la zona (Util/Zones).
function RemoteService:JugadoresEnZona(zonaId)
	local lista = {}
	local zona = Zones.Zona(zonaId)
	if not zona then
		return lista
	end
	for _, player in ipairs(Players:GetPlayers()) do
		local posicion = posicionDe(player)
		if posicion and Zones.Contiene(zona, posicion) then
			table.insert(lista, player)
		end
	end
	return lista
end

-- Envía a los jugadores que están físicamente dentro de la zona. Devuelve cuántos recibieron.
function RemoteService:EnviarAZona(zonaId, tipo, datos)
	return self:EnviarALista(self:JugadoresEnZona(zonaId), tipo, datos)
end

-- Envía a los jugadores de un aula. La zona del aula tiene la misma id que el aula (MapaLogico), así que se
-- envía por zona; solo si el aula no existe como zona se delega en RoomService:JugadoresEn(roomId).
function RemoteService:EnviarAAula(roomId, tipo, datos)
	if Zones.Zona(roomId) then
		return self:EnviarAZona(roomId, tipo, datos)
	end
	local RoomService = self.registro.Get("RoomService")
	if RoomService and typeof(RoomService.JugadoresEn) == "function" then
		local ok, lista = pcall(RoomService.JugadoresEn, RoomService, roomId)
		if ok and typeof(lista) == "table" then
			return self:EnviarALista(lista, tipo, datos)
		end
	end
	return 0
end

---------------------------------------------------------------------------------------------------
-- StateSnapshot por defecto: { Jornada, Rol, Economia, Ajustes, Aula, Anuncios, Version, HoraServidor }
---------------------------------------------------------------------------------------------------

-- Llama servicio:metodo(...) en pcall si existe; devuelve el primer resultado o nil.
local function consultar(servicio, metodo, ...)
	if typeof(servicio) ~= "table" or typeof(servicio[metodo]) ~= "function" then
		return nil
	end
	local ok, resultado = pcall(servicio[metodo], servicio, ...)
	if not ok then
		warn(PREFIJO .. " " .. tostring(servicio.Nombre) .. ":" .. tostring(metodo) .. "() falló en StateSnapshot: " .. tostring(resultado))
		return nil
	end
	return resultado
end

-- Un servicio aporta (o sustituye) un campo del snapshot: fn(player) -> valor serializable (sin Instances).
-- Ejemplo: RemoteService:AportarSnapshot("Aula", function(player) return ClassroomService:SnapshotDe(player) end)
function RemoteService:AportarSnapshot(clave, fn)
	if typeof(clave) ~= "string" or typeof(fn) ~= "function" then
		return false
	end
	self.PartesSnapshot[clave] = fn
	return true
end

-- Construye el snapshot del jugador con lo que aporten los servicios presentes (tolerante a ausencias).
function RemoteService:ConstruirSnapshot(player)
	local get = self.registro.Get
	local DataService = get("DataService")
	local perfil = consultar(DataService, "Obtener", player)
	if perfil == nil then
		perfil = consultar(DataService, "EsperarPerfil", player, self.EsperaPerfilSnapshotSeg)
	end

	local snapshot = {
		Version = tostring(Config.Version or ""),
		HoraServidor = workspace:GetServerTimeNow(),
	}
	snapshot.Rol = consultar(get("RoleService"), "DatosRol", player)
	snapshot.Jornada = consultar(get("SchoolDayService"), "Snapshot", player)
	local EconomyService = get("EconomyService")
	local economia = consultar(EconomyService, "Snapshot", player)
	if typeof(economia) ~= "table" then
		local saldo = consultar(EconomyService, "Saldo", player)
		if typeof(saldo) == "number" then
			economia = { Saldo = saldo }
		elseif typeof(perfil) == "table" and typeof(perfil.Economia) == "table" then
			economia = { Saldo = perfil.Economia.Saldo, GanadoHoy = perfil.Economia.GanadoHoy }
		end
	end
	snapshot.Economia = economia
	if typeof(perfil) == "table" and typeof(perfil.Ajustes) == "table" then
		local ajustes = {}
		for clave, valor in pairs(perfil.Ajustes) do
			ajustes[clave] = valor
		end
		snapshot.Ajustes = ajustes
	end

	-- Sesión de clase del jugador (si aplica) y últimos anuncios.
	snapshot.Aula = consultar(get("ClassroomService"), "Snapshot", player)
	local AnnouncementService = get("AnnouncementService")
	local anuncios = consultar(AnnouncementService, "Historial")
	if typeof(anuncios) ~= "table" then
		anuncios = consultar(AnnouncementService, "Snapshot", player)
	end
	if typeof(anuncios) == "table" then
		snapshot.Anuncios = anuncios
	end

	-- Partes aportadas con AportarSnapshot; sobrescriben a las anteriores.
	for clave, fn in pairs(self.PartesSnapshot) do
		local ok, valor = pcall(fn, player)
		if ok then
			if valor ~= nil then
				snapshot[clave] = valor
			end
		else
			warn(PREFIJO .. " La parte '" .. clave .. "' del StateSnapshot falló: " .. tostring(valor))
		end
	end
	return snapshot
end

---------------------------------------------------------------------------------------------------
-- Métricas
---------------------------------------------------------------------------------------------------

-- Copia de las estadísticas (peticiones, rechazos por motivo y remoto, tiempos medios).
function RemoteService:ObtenerEstadisticas()
	local tiempos = {}
	for nombre, t in pairs(self.Estadisticas.Tiempos) do
		if t.N > 0 then
			tiempos[nombre] = { Media = t.Suma / t.N, Max = t.Max, N = t.N }
		end
	end
	local porMotivo = {}
	for motivo, n in pairs(self.Estadisticas.PorMotivo) do
		porMotivo[motivo] = n
	end
	local porRemoto = {}
	for nombre, r in pairs(self.Estadisticas.PorRemoto) do
		porRemoto[nombre] = { Peticiones = r.Peticiones, Rechazos = r.Rechazos, Errores = r.Errores }
	end
	return {
		Peticiones = self.Estadisticas.Peticiones,
		Aceptadas = self.Estadisticas.Aceptadas,
		Rechazos = self.Estadisticas.Rechazos,
		Errores = self.Estadisticas.Errores,
		Sospechosos = self.Estadisticas.Sospechosos,
		PorMotivo = porMotivo,
		PorRemoto = porRemoto,
		Tiempos = tiempos,
		HandlersRegistrados = (function()
			local n = 0
			for _ in pairs(self.Handlers) do
				n = n + 1
			end
			return n
		end)(),
	}
end

-- Jugadores marcados como sospechosos actualmente conectados.
function RemoteService:Sospechosos()
	local lista = {}
	for _, player in ipairs(Players:GetPlayers()) do
		if player:GetAttribute("Sospechoso") == true then
			table.insert(lista, player)
		end
	end
	return lista
end

-- Quita la marca de sospechoso (uso de moderación).
function RemoteService:LimpiarSospecha(player)
	if not esJugador(player) then
		return false
	end
	self.Rechazos[player.UserId] = nil
	pcall(function()
		player:SetAttribute("Sospechoso", nil)
		player:SetAttribute("SospechosoDesde", nil)
	end)
	return true
end

return RemoteService
]=] }
FUENTES["ServerScriptService/ColegioRP/Services/ReportService"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ServerScriptService.ColegioRP.Services.ReportService
	Tipo: ModuleScript
	Reportes de soporte y convivencia (docs/ARQUITECTURA.md §6): atiende ReportSubmit (categoría válida,
	ubicación y descripción saneadas y filtradas con TextService, límite propio Config.Reportes.MaxPorMinuto
	además del de RemoteService), genera el id "R_<unix>_<userId>", guarda el reporte con
	DataService:GuardarReporte, conserva los últimos 100 en memoria para moderación (Listar) y avisa a quien
	tenga reportes.ver. Crear(player, ...) permite a otros servicios (StaffService) abrir reportes internos.
]]

local Players = game:GetService("Players")
local TextService = game:GetService("TextService")

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RP = ReplicatedStorage:WaitForChild("ColegioRP")
local Shared = RP:WaitForChild("Shared")
local Config = require(Shared:WaitForChild("Config"))
local RemoteContracts = require(Shared:WaitForChild("RemoteContracts"))
local Util = Shared:WaitForChild("Util")
local Signal = require(Util:WaitForChild("Signal"))
local Zones = require(Util:WaitForChild("Zones"))
local Format = require(Util:WaitForChild("Format"))

local ReportService = {}
ReportService.Nombre = "ReportService"

local PREFIJO = "[ColegioRP][ReportService]"
local CFG = Config.Reportes or {}

-- Reportes conservados en memoria (los más recientes) para el panel de moderación.
ReportService.MaxEnMemoria = 100
-- Reportes por jugador dentro de la ventana (contador propio, además del límite de RemoteService).
ReportService.MaxPorMinuto = math.max(1, tonumber(CFG.MaxPorMinuto) or 2)
-- Ventana (s) del contador anterior.
ReportService.VentanaSeg = 60
-- Longitudes máximas de los campos de texto.
ReportService.MaxDescripcion = math.max(10, tonumber(CFG.MaxCaracteres) or 300)
ReportService.MaxUbicacion = math.max(10, tonumber(CFG.MaxUbicacionCaracteres) or 60)
-- Caracteres mínimos de la descripción (tras recortar espacios).
ReportService.MinDescripcion = 3
-- Texto guardado cuando el filtro de Roblox no está disponible (el original nunca se muestra a terceros).
ReportService.TextoNoDisponible = "[texto no disponible]"
-- Escrituras de reportes en DataStore por minuto en todo el servidor (protección ante un servicio
-- que cree reportes en bucle); por encima del tope el reporte se conserva solo en memoria.
ReportService.MaxEscriturasPorMinuto = 30
-- Mensaje devuelto al jugador al aceptar su reporte.
ReportService.MensajeRecibido = "Reporte recibido"

-- Nombre legible de cada categoría (avisos a moderación).
ReportService.NombresCategoria = {
	Bug = "Error del juego",
	Abuso = "Conducta / abuso",
	Duda = "Duda",
	Sugerencia = "Sugerencia",
}

local setCategorias = {}
for _, categoria in ipairs(RemoteContracts.CategoriasReporte or { "Bug", "Abuso", "Duda", "Sugerencia" }) do
	setCategorias[categoria] = true
end

---------------------------------------------------------------------------------------------------
-- Utilidades
---------------------------------------------------------------------------------------------------
local function esJugador(player)
	return typeof(player) == "Instance" and player:IsA("Player")
end

local function posicionDe(player)
	if not esJugador(player) then
		return nil
	end
	local personaje = player.Character
	if not personaje then
		return nil
	end
	local raiz = personaje:FindFirstChild("HumanoidRootPart")
	if raiz and raiz:IsA("BasePart") then
		return raiz.Position
	end
	return nil
end

-- Normaliza un texto escrito por un jugador: UTF-8 válido, sin caracteres de control (salvo salto de
-- línea y tabulador), sin espacios sobrantes y recortado a max caracteres. Devuelve texto | nil si no es válido.
local function sanear(texto, max, permitirSaltos)
	if typeof(texto) ~= "string" then
		return nil
	end
	if utf8.len(texto) == nil then
		return nil
	end
	local limpio = string.gsub(texto, "\r\n", "\n")
	limpio = string.gsub(limpio, "%c", function(c)
		if c == "\t" then
			return " "
		end
		if c == "\n" and permitirSaltos then
			return c
		end
		if c == "\n" then
			return " "
		end
		return ""
	end)
	limpio = string.gsub(limpio, "\n\n\n+", "\n\n")
	limpio = Format.Recortar(limpio)
	if max and Format.Longitud(limpio) > max then
		limpio = Format.Truncar(limpio, max)
	end
	return limpio
end

-- Copia superficial de un reporte apta para enviar al cliente o a otro servicio.
local function copiaReporte(reporte)
	return {
		Id = reporte.Id,
		UserId = reporte.UserId,
		Jugador = reporte.Jugador,
		Nombre = reporte.Nombre,
		Categoria = reporte.Categoria,
		CategoriaNombre = reporte.CategoriaNombre,
		Ubicacion = reporte.Ubicacion,
		Descripcion = reporte.Descripcion,
		Zona = reporte.Zona,
		T = reporte.T,
		Origen = reporte.Origen,
		Persistido = reporte.Persistido,
		Filtrado = reporte.Filtrado,
	}
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function ReportService:Init(registro)
	self.registro = registro
	self.Reportes = {} -- array; el más reciente al final (máx. MaxEnMemoria)
	self.Envios = {} -- userId -> { os.clock() ... } de los reportes enviados por remoto en la ventana
	self.EscriturasGlobales = {} -- { os.clock() ... } escrituras en DataStore en el último minuto
	self.Conexiones = {}
	self.Estadisticas = { Recibidos = 0, Rechazados = 0, Persistidos = 0, SoloMemoria = 0, FiltroFallido = 0 }
	self.ReporteCreado = Signal.new() -- (reporte)
end

function ReportService:Start()
	local RemoteService = self:Servicio("RemoteService")
	if RemoteService and typeof(RemoteService.Registrar) == "function" then
		RemoteService:Registrar("ReportSubmit", function(player, datos)
			return self:ManejarEnvio(player, datos)
		end)
	else
		warn(PREFIJO .. " RemoteService no disponible: ReportSubmit no tendrá handler.")
	end
	table.insert(self.Conexiones, Players.PlayerRemoving:Connect(function(player)
		self.Envios[player.UserId] = nil
	end))
end

-- Servicio por nombre a través del registro (nil si no existe).
function ReportService:Servicio(nombre)
	local registro = self.registro
	if registro and typeof(registro.Get) == "function" then
		return registro.Get(nombre)
	end
	return nil
end

-- Llama servicio:metodo(...) en pcall si existe. Devuelve ok, r1, r2.
function ReportService:Llamar(nombreServicio, metodo, ...)
	local servicio = self:Servicio(nombreServicio)
	if not servicio or typeof(servicio[metodo]) ~= "function" then
		return false, nil, nil
	end
	local resultado = table.pack(pcall(servicio[metodo], servicio, ...))
	if not resultado[1] then
		warn(PREFIJO .. " " .. nombreServicio .. ":" .. metodo .. "() falló: " .. tostring(resultado[2]))
		return false, nil, nil
	end
	return true, resultado[2], resultado[3]
end

function ReportService:Auditar(player, accion, detalle)
	self:Llamar("AuditLogService", "Registrar", "Moderacion", player, accion, detalle)
end

---------------------------------------------------------------------------------------------------
-- Filtrado y límites
---------------------------------------------------------------------------------------------------

-- Filtra un texto para mostrarlo a terceros. Devuelve texto filtrado, ok (false si el filtro falló y se
-- sustituyó por TextoNoDisponible). Un texto vacío no se filtra.
function ReportService:Filtrar(texto, userId)
	if texto == "" then
		return "", true
	end
	local okFiltro, resultado = pcall(function()
		return TextService:FilterStringAsync(texto, userId, Enum.TextFilterContext.PublicChat)
	end)
	if not okFiltro or resultado == nil then
		return self.TextoNoDisponible, false
	end
	local okTexto, filtrado = pcall(function()
		return resultado:GetNonChatStringForBroadcastAsync()
	end)
	if not okTexto or typeof(filtrado) ~= "string" then
		return self.TextoNoDisponible, false
	end
	return filtrado, true
end

-- Contador propio por jugador (Config.Reportes.MaxPorMinuto en VentanaSeg). Devuelve permitido, restanteSeg.
function ReportService:DentroDelLimite(player)
	local userId = player.UserId
	local ahora = os.clock()
	local lista = self.Envios[userId]
	if not lista then
		lista = {}
		self.Envios[userId] = lista
	end
	while lista[1] ~= nil and lista[1] <= ahora - self.VentanaSeg do
		table.remove(lista, 1)
	end
	if #lista >= self.MaxPorMinuto then
		return false, math.max(1, math.ceil(self.VentanaSeg - (ahora - lista[1])))
	end
	return true, 0
end

function ReportService:AnotarEnvio(player)
	local lista = self.Envios[player.UserId]
	if not lista then
		lista = {}
		self.Envios[player.UserId] = lista
	end
	table.insert(lista, os.clock())
end

-- ¿Queda cupo global de escrituras en DataStore este minuto? (lo consume si lo hay)
function ReportService:CupoEscritura()
	local ahora = os.clock()
	local lista = self.EscriturasGlobales
	while lista[1] ~= nil and lista[1] <= ahora - 60 do
		table.remove(lista, 1)
	end
	if #lista >= self.MaxEscriturasPorMinuto then
		return false
	end
	table.insert(lista, ahora)
	return true
end

-- Id de zona en la que está el jugador (MapService:ZonaDe o, si no existe, Util.Zones).
function ReportService:ZonaDe(player)
	local posicion = posicionDe(player)
	if not posicion then
		return nil
	end
	local zona = nil
	local okMapa, resultado = self:Llamar("MapService", "ZonaDe", posicion)
	if okMapa then
		zona = resultado
	else
		local okZona, z = pcall(Zones.ZonaDe, posicion)
		if okZona then
			zona = z
		end
	end
	if typeof(zona) == "table" and typeof(zona.Id) == "string" then
		return zona.Id
	end
	if typeof(zona) == "string" then
		return zona
	end
	return nil
end

---------------------------------------------------------------------------------------------------
-- Núcleo
---------------------------------------------------------------------------------------------------

-- Crea, guarda y difunde un reporte. player puede ser nil (reporte del sistema).
-- Devuelve true, reporte | false, mensaje.
function ReportService:Procesar(player, categoria, ubicacion, descripcion, origen)
	if not setCategorias[categoria] then
		return false, "Categoría de reporte no válida."
	end
	local ubicacionLimpia = sanear(ubicacion or "", self.MaxUbicacion, false)
	local descripcionLimpia = sanear(descripcion, self.MaxDescripcion, true)
	if ubicacionLimpia == nil or descripcionLimpia == nil then
		return false, "El texto del reporte no es válido."
	end
	if Format.Longitud(descripcionLimpia) < self.MinDescripcion then
		return false, "Describe el problema con al menos " .. self.MinDescripcion .. " caracteres."
	end

	local jugador = esJugador(player) and player or nil
	local userId = jugador and jugador.UserId or 0

	-- Filtrado con TextService (si falla se guarda TextoNoDisponible; nunca el original).
	local filtradoOk = true
	local descripcionFinal, okD = descripcionLimpia, true
	local ubicacionFinal, okU = ubicacionLimpia, true
	if jugador then
		descripcionFinal, okD = self:Filtrar(descripcionLimpia, userId)
		ubicacionFinal, okU = self:Filtrar(ubicacionLimpia, userId)
		filtradoOk = okD and okU
		if not filtradoOk then
			self.Estadisticas.FiltroFallido = self.Estadisticas.FiltroFallido + 1
		end
		-- Si el jugador salió mientras se filtraba, el reporte se conserva igualmente.
	end

	local ahora = os.time()
	local reporte = {
		Id = string.format("R_%d_%d", ahora, userId),
		UserId = userId,
		Jugador = jugador and jugador.Name or "Sistema",
		Nombre = jugador and jugador.DisplayName or "Sistema",
		Categoria = categoria,
		CategoriaNombre = self.NombresCategoria[categoria] or categoria,
		Ubicacion = ubicacionFinal,
		Descripcion = descripcionFinal,
		Zona = jugador and self:ZonaDe(jugador) or nil,
		T = ahora,
		Origen = tostring(origen or "Interno"),
		Filtrado = filtradoOk,
		Persistido = false,
	}
	if jugador then
		local okCargo, cargo = self:Llamar("RoleService", "Cargo", jugador)
		if okCargo and typeof(cargo) == "string" then
			reporte.Cargo = cargo
		end
	end

	-- Persistencia (DataService:GuardarReporte). El id definitivo es la clave que devuelve DataService
	-- (añade un sufijo si coinciden dos reportes del mismo jugador en el mismo segundo).
	local DataService = self:Servicio("DataService")
	if DataService and typeof(DataService.GuardarReporte) == "function" then
		if self:CupoEscritura() then
			local okGuardar, guardado, clave = pcall(DataService.GuardarReporte, DataService, {
				Id = reporte.Id,
				UserId = reporte.UserId,
				Categoria = reporte.Categoria,
				Ubicacion = reporte.Ubicacion,
				Descripcion = reporte.Descripcion,
				Zona = reporte.Zona,
				T = reporte.T,
				Cargo = reporte.Cargo,
				Origen = reporte.Origen,
				Filtrado = reporte.Filtrado,
			})
			if okGuardar and guardado == true then
				reporte.Persistido = true
				if typeof(clave) == "string" and clave ~= "" then
					reporte.Id = clave
				end
				self.Estadisticas.Persistidos = self.Estadisticas.Persistidos + 1
			else
				self.Estadisticas.SoloMemoria = self.Estadisticas.SoloMemoria + 1
				if not okGuardar then
					warn(PREFIJO .. " GuardarReporte falló: " .. tostring(guardado))
				elseif typeof(clave) == "string" then
					warn(PREFIJO .. " El reporte " .. reporte.Id .. " no se pudo persistir: " .. clave)
				end
			end
		else
			self.Estadisticas.SoloMemoria = self.Estadisticas.SoloMemoria + 1
			warn(PREFIJO .. " Tope de escrituras de reportes por minuto alcanzado; " .. reporte.Id .. " queda solo en memoria.")
		end
	else
		self.Estadisticas.SoloMemoria = self.Estadisticas.SoloMemoria + 1
	end

	-- Id único también en memoria (reporte no persistido en el mismo segundo que otro del mismo autor).
	if self:Obtener(reporte.Id) ~= nil then
		local base = reporte.Id
		local sufijo = 1
		while self:Obtener(base .. "_m" .. sufijo) ~= nil do
			sufijo = sufijo + 1
		end
		reporte.Id = base .. "_m" .. sufijo
	end

	-- Memoria (últimos MaxEnMemoria).
	table.insert(self.Reportes, reporte)
	while #self.Reportes > self.MaxEnMemoria do
		table.remove(self.Reportes, 1)
	end
	self.Estadisticas.Recibidos = self.Estadisticas.Recibidos + 1

	self:Auditar(jugador, "Reporte", string.format("%s · %s · %s%s · %s", reporte.Id, categoria,
		reporte.Ubicacion ~= "" and reporte.Ubicacion or "(sin ubicación)",
		reporte.Zona and (" [" .. reporte.Zona .. "]") or "", Format.Truncar(reporte.Descripcion, 160)))

	self:AvisarModeracion(reporte, jugador)

	local okSenal, errSenal = pcall(function()
		self.ReporteCreado:Fire(copiaReporte(reporte))
	end)
	if not okSenal then
		warn(PREFIJO .. " Error en un oyente de ReporteCreado: " .. tostring(errSenal))
	end
	return true, reporte
end

-- Aviso a quien tenga reportes.ver (canal Moderacion, Sub = "Reporte"); el autor no se avisa a sí mismo.
function ReportService:AvisarModeracion(reporte, autor)
	local RemoteService = self:Servicio("RemoteService")
	if not RemoteService or typeof(RemoteService.Enviar) ~= "function" then
		return 0
	end
	local okLista, lista = self:Llamar("RoleService", "ConPermiso", "reportes.ver")
	if not okLista or typeof(lista) ~= "table" then
		return 0
	end
	local avisados = 0
	local resumen = copiaReporte(reporte)
	for _, moderador in ipairs(lista) do
		if esJugador(moderador) and moderador ~= autor and moderador.Parent ~= nil then
			local ok = pcall(RemoteService.Enviar, RemoteService, moderador, "Moderacion", { Sub = "Reporte", Reporte = resumen })
			if ok then
				avisados = avisados + 1
			end
		end
	end
	return avisados
end

---------------------------------------------------------------------------------------------------
-- Handler de ReportSubmit (RemoteService ya validó tabla, esquema y límite 2/60 s)
---------------------------------------------------------------------------------------------------
function ReportService:ManejarEnvio(player, datos)
	local permitido, restante = self:DentroDelLimite(player)
	if not permitido then
		self.Estadisticas.Rechazados = self.Estadisticas.Rechazados + 1
		self:Auditar(player, "ReporteRechazado", "límite de " .. self.MaxPorMinuto .. " reportes por minuto")
		local respuesta = RemoteContracts.Error("Has enviado " .. self.MaxPorMinuto .. " reportes en el último minuto. Espera " .. restante .. " s.")
		respuesta.datos = { RestanteSeg = restante }
		return respuesta
	end
	if not setCategorias[datos.Categoria] then
		self.Estadisticas.Rechazados = self.Estadisticas.Rechazados + 1
		return RemoteContracts.Error("Categoría de reporte no válida.")
	end
	-- El envío cuenta para el límite aunque el contenido resulte inválido (evita sondeos en bucle).
	self:AnotarEnvio(player)
	local ok, resultado = self:Procesar(player, datos.Categoria, datos.Ubicacion, datos.Descripcion, "Formulario")
	if not ok then
		self.Estadisticas.Rechazados = self.Estadisticas.Rechazados + 1
		return RemoteContracts.Error(resultado)
	end
	return RemoteContracts.Ok({
		Id = resultado.Id,
		Mensaje = self.MensajeRecibido,
		Categoria = resultado.Categoria,
		Persistido = resultado.Persistido,
	})
end

---------------------------------------------------------------------------------------------------
-- API para otros servicios
---------------------------------------------------------------------------------------------------

-- Crea un reporte interno (sin el contador por jugador del formulario). player puede ser nil.
-- Devuelve true, id | false, mensaje.
function ReportService:Crear(player, categoria, ubicacion, descripcion)
	if player ~= nil and not esJugador(player) then
		return false, "Jugador no válido."
	end
	local ok, resultado = self:Procesar(player, categoria, ubicacion, descripcion, "Interno")
	if not ok then
		return false, resultado
	end
	return true, resultado.Id
end

-- Últimos n reportes en memoria (el más reciente primero). filtro opcional: { Categoria, UserId }.
function ReportService:Listar(n, filtro)
	n = math.clamp(math.floor(tonumber(n) or 30), 1, self.MaxEnMemoria)
	local lista = {}
	for i = #self.Reportes, 1, -1 do
		if #lista >= n then
			break
		end
		local reporte = self.Reportes[i]
		local pasa = true
		if typeof(filtro) == "table" then
			if filtro.Categoria ~= nil and reporte.Categoria ~= filtro.Categoria then
				pasa = false
			end
			if filtro.UserId ~= nil and reporte.UserId ~= filtro.UserId then
				pasa = false
			end
		end
		if pasa then
			table.insert(lista, copiaReporte(reporte))
		end
	end
	return lista
end

-- Reporte en memoria por id (copia) o nil.
function ReportService:Obtener(id)
	if typeof(id) ~= "string" then
		return nil
	end
	for i = #self.Reportes, 1, -1 do
		if self.Reportes[i].Id == id then
			return copiaReporte(self.Reportes[i])
		end
	end
	return nil
end

-- Resumen para paneles y métricas.
function ReportService:Snapshot()
	local porCategoria = {}
	for categoria in pairs(setCategorias) do
		porCategoria[categoria] = 0
	end
	for _, reporte in ipairs(self.Reportes) do
		porCategoria[reporte.Categoria] = (porCategoria[reporte.Categoria] or 0) + 1
	end
	return {
		EnMemoria = #self.Reportes,
		PorCategoria = porCategoria,
		Recibidos = self.Estadisticas.Recibidos,
		Rechazados = self.Estadisticas.Rechazados,
		Persistidos = self.Estadisticas.Persistidos,
		SoloMemoria = self.Estadisticas.SoloMemoria,
		FiltroFallido = self.Estadisticas.FiltroFallido,
		Ultimos = self:Listar(5),
	}
end

ReportService.ObtenerEstadisticas = ReportService.Snapshot

return ReportService
]=] }
FUENTES["ServerScriptService/ColegioRP/Services/RoleService"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ServerScriptService.ColegioRP.Services.RoleService
	Tipo: ModuleScript
	Autoridad de cargos (docs/ARQUITECTURA.md §6): crea los Teams, guarda el cargo de cada jugador (atributos
	Cargo, Equipo y Salon en el Player), resuelve autorizaciones (lista, grupo, Adonis, Studio, cargos libres),
	aplica uniformes, atiende RequestRoleList / RequestJoinRole y la gestión de cargos por administradores.
]]

local Players = game:GetService("Players")
local Teams = game:GetService("Teams")
local RunService = game:GetService("RunService")

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RP = ReplicatedStorage:WaitForChild("ColegioRP")
local Shared = RP:WaitForChild("Shared")
local Config = require(Shared:WaitForChild("Config"))
local RoleDefinitions = require(Shared:WaitForChild("RoleDefinitions"))
local RemoteContracts = require(Shared:WaitForChild("RemoteContracts"))
local MapaLogico = require(Shared:WaitForChild("MapaLogico"))
local Util = Shared:WaitForChild("Util")
local Signal = require(Util:WaitForChild("Signal"))
local Maid = require(Util:WaitForChild("Maid"))

local RoleService = {}
RoleService.Nombre = "RoleService"

local PREFIJO = "[ColegioRP][RoleService]"
local AUT = Config.Autorizaciones or {}
local CARGO_DEFECTO = (Config.Spawns and Config.Spawns.CargoPorDefecto) or "Estudiante"
if not RoleDefinitions.Existe(CARGO_DEFECTO) then
	CARGO_DEFECTO = "Estudiante"
end

-- Segundos entre cambios de cargo pedidos por el mismo jugador (RequestJoinRole).
RoleService.CooldownCambioSeg = 5
-- Segundos entre acciones de gestión (asignar/revocar) del mismo administrador.
RoleService.CooldownAdminSeg = 5
-- Espera máxima del perfil al entrar antes de fijar el cargo inicial (no bloquea si falla).
RoleService.EsperaPerfilSeg = 15
-- Vigencia (s) de la caché del rango de grupo de cada jugador.
RoleService.CacheRangoSeg = 60

-- Textos legibles de los motivos de Autorizado (para la lista de cargos del menú).
RoleService.TextosMotivo = {
	libre = "Cargo libre",
	lista = "Autorizado por la dirección",
	grupo = "Rango suficiente en el grupo",
	adonis = "Administrador del servidor",
	studio = "Modo pruebas (Studio)",
	no_autorizado = "Requiere autorización de la dirección",
	cargo_invalido = "Cargo desconocido",
	jugador_invalido = "Jugador no válido",
}

-- Jerarquía para la gestión de cargos: nadie actúa sobre un cargo superior al suyo ni se asciende a sí mismo.
local NIVEL_POR_CARGO = { Director = 100, Subdirector = 90 }
local NIVEL_POR_EQUIPO = {
	["Equipo Directivo"] = 70,
	["Docentes"] = 40,
	["Bienestar"] = 40,
	["Administración"] = 40,
	["Servicios"] = 40,
	["Estudiantes"] = 10,
}

---------------------------------------------------------------------------------------------------
-- Utilidades
---------------------------------------------------------------------------------------------------
local function esJugador(player)
	return typeof(player) == "Instance" and player:IsA("Player")
end

local function resolverJugador(player)
	if esJugador(player) then
		return player
	end
	if typeof(player) == "number" then
		return Players:GetPlayerByUserId(player)
	end
	return nil
end

local function nivel(cargo)
	if NIVEL_POR_CARGO[cargo] then
		return NIVEL_POR_CARGO[cargo]
	end
	local equipo = RoleDefinitions.Equipo(cargo)
	return NIVEL_POR_EQUIPO[equipo] or 0
end

local function enLista(lista, valor)
	if typeof(lista) ~= "table" then
		return false
	end
	for _, v in ipairs(lista) do
		if v == valor then
			return true
		end
	end
	return false
end

-- Llama servicio:metodo(...) en pcall si existe. Devuelve ok, resultado1, resultado2.
local function invocar(servicio, metodo, ...)
	if typeof(servicio) ~= "table" or typeof(servicio[metodo]) ~= "function" then
		return false, nil, nil
	end
	local resultado = table.pack(pcall(servicio[metodo], servicio, ...))
	if not resultado[1] then
		warn(PREFIJO .. " Error en " .. tostring(servicio.Nombre) .. ":" .. metodo .. "(): " .. tostring(resultado[2]))
		return false, nil, nil
	end
	return true, resultado[2], resultado[3]
end

local function esAulaValida(salon)
	return typeof(salon) == "string" and salon ~= "" and MapaLogico.Zonas[salon] ~= nil
end

local setCargosLibres = {}
for _, cargo in ipairs(AUT.CargosLibres or { "Estudiante" }) do
	setCargosLibres[cargo] = true
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function RoleService:Init(registro)
	self.registro = registro
	self.Cargos = {} -- userId -> cargoId (solo tras una asignación completa)
	self.UltimoCambio = {} -- userId -> os.clock() del último RequestJoinRole aceptado
	self.UltimaGestion = {} -- userId del administrador -> os.clock() de su última asignación/revocación
	self.CacheRango = {} -- userId -> { Rango, T }
	self.Equipos = {} -- nombre -> Team
	self.Maids = {} -- userId -> Maid con las conexiones del jugador
	self.CambiandoEquipo = {} -- userId -> true mientras RoleService cambia el Team (evita bucles)
	self.CargoCambiado = Signal.new() -- (player, cargoNuevo, cargoAnterior)
	self.Conexiones = {}
end

function RoleService:Start()
	self.AuditLog = self:Servicio("AuditLogService")

	local okEquipos, errEquipos = pcall(function()
		self:CrearEquipos()
	end)
	if not okEquipos then
		warn(PREFIJO .. " No se pudieron crear los equipos: " .. tostring(errEquipos))
	end

	local RemoteService = self:Servicio("RemoteService")
	if RemoteService and typeof(RemoteService.Registrar) == "function" then
		RemoteService:Registrar("RequestRoleList", function(player, datos)
			return self:ManejarLista(player, datos)
		end)
		RemoteService:Registrar("RequestJoinRole", function(player, datos)
			return self:ManejarUnirse(player, datos)
		end)
	else
		warn(PREFIJO .. " RemoteService no disponible: RequestRoleList y RequestJoinRole no tendrán handler.")
	end

	table.insert(self.Conexiones, Players.PlayerAdded:Connect(function(player)
		self:AlEntrar(player)
	end))
	table.insert(self.Conexiones, Players.PlayerRemoving:Connect(function(player)
		self:AlSalir(player)
	end))
	for _, player in ipairs(Players:GetPlayers()) do
		self:AlEntrar(player)
	end
end

-- Servicio por nombre a través del registro (nil si no existe).
function RoleService:Servicio(nombre)
	local registro = self.registro
	if registro and typeof(registro.Get) == "function" then
		return registro.Get(nombre)
	end
	return nil
end

function RoleService:Auditar(player, accion, detalle)
	if self.AuditLog and typeof(self.AuditLog.Registrar) == "function" then
		pcall(self.AuditLog.Registrar, self.AuditLog, "Cargo", player, accion, detalle)
	end
end

---------------------------------------------------------------------------------------------------
-- Equipos (Teams)
---------------------------------------------------------------------------------------------------
function RoleService:CrearEquipos()
	for _, nombre in ipairs(RoleDefinitions.OrdenEquipos) do
		local info = RoleDefinitions.Equipos[nombre]
		local equipo = Teams:FindFirstChild(nombre)
		if equipo and not equipo:IsA("Team") then
			warn(PREFIJO .. " Teams." .. nombre .. " existe pero no es un Team; se crea uno nuevo junto a él.")
			equipo = nil
		end
		if not equipo then
			equipo = Instance.new("Team")
			equipo.Name = nombre
			if info and info.Color then
				equipo.TeamColor = info.Color
			end
			equipo.AutoAssignable = false
			equipo.Parent = Teams
		else
			-- Equipo existente con el mismo nombre: se reutiliza (solo se desactiva la autoasignación).
			equipo.AutoAssignable = false
		end
		self.Equipos[nombre] = equipo
	end
end

-- Team del cargo (o nil).
function RoleService:TeamDe(cargo)
	local nombre = RoleDefinitions.Equipo(cargo)
	if not nombre then
		return nil
	end
	local equipo = self.Equipos[nombre]
	if equipo and equipo.Parent then
		return equipo
	end
	local existente = Teams:FindFirstChild(nombre)
	if existente and existente:IsA("Team") then
		self.Equipos[nombre] = existente
		return existente
	end
	return nil
end

function RoleService:FijarTeam(player, cargo)
	local equipo = self:TeamDe(cargo)
	if not equipo then
		return
	end
	local userId = player.UserId
	self.CambiandoEquipo[userId] = true
	local ok, err = pcall(function()
		player.Neutral = false
		player.Team = equipo
	end)
	self.CambiandoEquipo[userId] = nil
	if not ok then
		warn(PREFIJO .. " No se pudo fijar el equipo de " .. player.Name .. ": " .. tostring(err))
	end
end

---------------------------------------------------------------------------------------------------
-- Entrada y salida de jugadores
---------------------------------------------------------------------------------------------------
function RoleService:AlEntrar(player)
	if not esJugador(player) then
		return
	end
	local userId = player.UserId
	if self.Maids[userId] then
		self.Maids[userId]:DoCleaning()
	end
	local maid = Maid.new()
	self.Maids[userId] = maid

	-- Estado provisional inmediato (sin auditoría ni spawn): cargo por defecto y su equipo.
	pcall(function()
		player:SetAttribute("Cargo", CARGO_DEFECTO)
		player:SetAttribute("Equipo", RoleDefinitions.Equipo(CARGO_DEFECTO))
	end)
	self:FijarTeam(player, CARGO_DEFECTO)

	-- Uniforme tras cada reaparición (el cargo se conserva al morir).
	maid:GiveTask(player.CharacterAppearanceLoaded:Connect(function()
		self:AplicarUniforme(player)
	end))

	-- Si algo externo cambia el Team (p. ej. un SpawnLocation con AllowTeamChangeOnTouch), se restaura.
	maid:GiveTask(player:GetPropertyChangedSignal("Team"):Connect(function()
		if self.CambiandoEquipo[userId] then
			return
		end
		local esperado = self:TeamDe(self:Cargo(player))
		if esperado and player.Team ~= esperado and player.Parent then
			task.defer(function()
				if player.Parent and player.Team ~= esperado then
					self:FijarTeam(player, self:Cargo(player))
				end
			end)
		end
	end))

	-- Cargo inicial tras cargar el perfil (máx. EsperaPerfilSeg; si falla se continúa igualmente).
	maid:GiveTask(task.spawn(function()
		local DataService = self:Servicio("DataService")
		if DataService and typeof(DataService.EsperarPerfil) == "function" then
			local ok, err = pcall(DataService.EsperarPerfil, DataService, player, self.EsperaPerfilSeg)
			if not ok then
				warn(PREFIJO .. " EsperarPerfil falló para " .. player.Name .. ": " .. tostring(err))
			end
		end
		if player.Parent == nil or self.Maids[userId] ~= maid then
			return
		end
		-- Si el jugador ya eligió cargo mientras esperábamos, no se sobrescribe.
		if self.Cargos[userId] == nil then
			self:Asignar(player, CARGO_DEFECTO, "Entrada")
		end
	end))
end

function RoleService:AlSalir(player)
	local userId = player.UserId
	local maid = self.Maids[userId]
	if maid then
		self.Maids[userId] = nil
		maid:DoCleaning()
	end
	self.Cargos[userId] = nil
	self.UltimoCambio[userId] = nil
	self.UltimaGestion[userId] = nil
	self.CacheRango[userId] = nil
	self.CambiandoEquipo[userId] = nil
end

---------------------------------------------------------------------------------------------------
-- Consultas
---------------------------------------------------------------------------------------------------

-- Cargo actual del jugador (Player o userId). Por defecto Config.Spawns.CargoPorDefecto; nil si no es jugador.
function RoleService:Cargo(player)
	player = resolverJugador(player)
	if not player then
		return nil
	end
	local cargo = self.Cargos[player.UserId]
	if cargo then
		return cargo
	end
	local atributo = player:GetAttribute("Cargo")
	if RoleDefinitions.Existe(atributo) then
		return atributo
	end
	return CARGO_DEFECTO
end

-- ¿El cargo del jugador tiene el permiso?
function RoleService:Tiene(player, permiso)
	local cargo = self:Cargo(player)
	if not cargo then
		return false
	end
	return RoleDefinitions.Tiene(cargo, permiso)
end

-- ¿El jugador tiene un cargo docente (aula.docente)?
function RoleService:EsDocente(player)
	local cargo = self:Cargo(player)
	if not cargo then
		return false
	end
	return RoleDefinitions.EsDocente(cargo)
end

-- Nombre del equipo del jugador.
function RoleService:Equipo(player)
	local cargo = self:Cargo(player)
	if not cargo then
		return nil
	end
	return RoleDefinitions.Equipo(cargo)
end

-- Aula asignada (atributo Salon) o nil.
function RoleService:Salon(player)
	player = resolverJugador(player)
	if not player then
		return nil
	end
	local salon = player:GetAttribute("Salon")
	if typeof(salon) == "string" and salon ~= "" then
		return salon
	end
	return nil
end

-- Jugadores conectados cuyo cargo tiene el permiso.
function RoleService:ConPermiso(permiso)
	local lista = {}
	for _, player in ipairs(Players:GetPlayers()) do
		if self:Tiene(player, permiso) then
			table.insert(lista, player)
		end
	end
	return lista
end

-- Jugadores conectados con un cargo concreto.
function RoleService:JugadoresConCargo(cargo)
	local lista = {}
	for _, player in ipairs(Players:GetPlayers()) do
		if self:Cargo(player) == cargo then
			table.insert(lista, player)
		end
	end
	return lista
end

-- Lista ordenada de permisos del cargo (orden de RoleDefinitions.PermisosConocidos).
function RoleService:PermisosDe(cargo)
	local lista = {}
	for _, permiso in ipairs(RoleDefinitions.PermisosConocidos) do
		if RoleDefinitions.Tiene(cargo, permiso) then
			table.insert(lista, permiso)
		end
	end
	return lista
end

-- Datos públicos del rol del jugador (evento "Rol" y snapshot del cliente).
function RoleService:DatosRol(player)
	player = resolverJugador(player)
	if not player then
		return nil
	end
	local cargo = self:Cargo(player)
	local rol = RoleDefinitions.Obtener(cargo)
	return {
		Cargo = cargo,
		Nombre = rol and rol.Nombre or tostring(cargo),
		Abrev = rol and rol.Abrev or "?",
		Equipo = rol and rol.Equipo or nil,
		Descripcion = rol and rol.Descripcion or "",
		Salon = self:Salon(player),
		Permisos = self:PermisosDe(cargo),
		EsDocente = RoleDefinitions.EsDocente(cargo),
	}
end

RoleService.Snapshot = RoleService.DatosRol

---------------------------------------------------------------------------------------------------
-- Autorizaciones
---------------------------------------------------------------------------------------------------

-- Rango del jugador en Config.Autorizaciones.GrupoRoblox (caché de CacheRangoSeg). 0 si falla.
function RoleService:RangoGrupo(player)
	local grupo = AUT.GrupoRoblox or {}
	local groupId = tonumber(grupo.GroupId) or 0
	if groupId <= 0 then
		return 0
	end
	local userId = player.UserId
	local cache = self.CacheRango[userId]
	if cache and os.clock() - cache.T < self.CacheRangoSeg then
		return cache.Rango
	end
	local ok, rango = pcall(player.GetRankInGroup, player, groupId)
	if not ok or typeof(rango) ~= "number" then
		rango = 0
	end
	self.CacheRango[userId] = { Rango = rango, T = os.clock() }
	return rango
end

-- ¿Es administrador de Adonis? (solo lectura; nunca lanza)
local function esAdminAdonis(player)
	if AUT.UsarAdonis ~= true then
		return false
	end
	local ok, resultado = pcall(function()
		local adonis = _G.Adonis
		return adonis ~= nil and type(adonis) == "table" and type(adonis.CheckAdmin) == "function" and adonis.CheckAdmin(player) == true
	end)
	return ok and resultado == true
end

local function listaPorUserId(userId)
	local mapa = AUT.PorUserId
	if typeof(mapa) ~= "table" then
		return nil
	end
	local lista = mapa[userId]
	if lista == nil then
		lista = mapa[tostring(userId)]
	end
	if typeof(lista) == "string" then
		return { lista }
	end
	return lista
end

-- Núcleo de Autorizado con caché de contexto (Adonis y grupo se consultan una vez por lista).
function RoleService:AutorizadoCtx(player, cargo, ctx)
	if not esJugador(player) then
		return false, "jugador_invalido"
	end
	local rol = RoleDefinitions.Obtener(cargo)
	if not rol then
		return false, "cargo_invalido"
	end
	if setCargosLibres[cargo] or rol.RequiereAutorizacion == false then
		return true, "libre"
	end
	local lista = listaPorUserId(player.UserId)
	if lista and (enLista(lista, cargo) or enLista(lista, "*")) then
		return true, "lista"
	end
	local grupo = AUT.GrupoRoblox or {}
	local minimos = grupo.RangosMinimos or {}
	if (tonumber(grupo.GroupId) or 0) > 0 and typeof(minimos[cargo]) == "number" then
		local rango = ctx and ctx.Rango
		if rango == nil then
			rango = self:RangoGrupo(player)
			if ctx then
				ctx.Rango = rango
			end
		end
		if rango >= minimos[cargo] then
			return true, "grupo"
		end
	end
	local adonis = ctx and ctx.Adonis
	if adonis == nil then
		adonis = esAdminAdonis(player)
		if ctx then
			ctx.Adonis = adonis
		end
	end
	if adonis then
		return true, "adonis"
	end
	if AUT.ModoPruebasEnStudio == true and RunService:IsStudio() then
		return true, "studio"
	end
	return false, "no_autorizado"
end

-- ¿Puede el jugador tomar el cargo? Devuelve bool, motivo ("libre"|"lista"|"grupo"|"adonis"|"studio"|"no_autorizado"|...).
function RoleService:Autorizado(player, cargo)
	return self:AutorizadoCtx(player, cargo, {})
end

-- Ids de los cargos que el jugador puede tomar (orden de RoleDefinitions.Lista()) y mapa id -> motivo.
function RoleService:Disponibles(player)
	local ids = {}
	local motivos = {}
	local ctx = {}
	for _, rol in ipairs(RoleDefinitions.Lista()) do
		local ok, motivo = self:AutorizadoCtx(player, rol.Id, ctx)
		motivos[rol.Id] = motivo
		if ok then
			table.insert(ids, rol.Id)
		end
	end
	return ids, motivos
end

-- Lista de cargos para el menú: { {Id, Nombre, Abrev, Equipo, Descripcion, Disponible, Motivo, MotivoTexto} }.
function RoleService:ListaCargos(player)
	local lista = {}
	local ctx = {}
	for _, rol in ipairs(RoleDefinitions.Lista()) do
		local disponible, motivo = self:AutorizadoCtx(player, rol.Id, ctx)
		table.insert(lista, {
			Id = rol.Id,
			Nombre = rol.Nombre,
			Abrev = rol.Abrev,
			Equipo = rol.Equipo,
			Descripcion = rol.Descripcion,
			Disponible = disponible,
			Motivo = motivo,
			MotivoTexto = self.TextosMotivo[motivo] or motivo,
			RequiereAutorizacion = rol.RequiereAutorizacion == true,
			Color = rol.Color,
		})
	end
	return lista
end

---------------------------------------------------------------------------------------------------
-- Uniforme
---------------------------------------------------------------------------------------------------

-- Aplica Shirt/Pants del cargo si sus ids son > 0 (con 0 no se toca la ropa ni los accesorios).
function RoleService:AplicarUniforme(player, cargo)
	if not esJugador(player) then
		return false
	end
	local rol = RoleDefinitions.Obtener(cargo or self:Cargo(player))
	if not rol or typeof(rol.Uniforme) ~= "table" then
		return false
	end
	local camisa = tonumber(rol.Uniforme.Camisa) or 0
	local pantalon = tonumber(rol.Uniforme.Pantalon) or 0
	if camisa <= 0 and pantalon <= 0 then
		return false
	end
	local personaje = player.Character
	if not personaje or not personaje.Parent then
		return false
	end
	local ok, err = pcall(function()
		if camisa > 0 then
			local shirt = personaje:FindFirstChildOfClass("Shirt")
			if not shirt then
				shirt = Instance.new("Shirt")
				shirt.Name = "Shirt"
				shirt.Parent = personaje
			end
			shirt.ShirtTemplate = string.format("rbxassetid://%d", math.floor(camisa))
		end
		if pantalon > 0 then
			local pants = personaje:FindFirstChildOfClass("Pants")
			if not pants then
				pants = Instance.new("Pants")
				pants.Name = "Pants"
				pants.Parent = personaje
			end
			pants.PantsTemplate = string.format("rbxassetid://%d", math.floor(pantalon))
		end
	end)
	if not ok then
		warn(PREFIJO .. " No se pudo aplicar el uniforme a " .. player.Name .. ": " .. tostring(err))
		return false
	end
	return true
end

---------------------------------------------------------------------------------------------------
-- Aula (Salon)
---------------------------------------------------------------------------------------------------

-- Fija (o borra con nil) el aula del jugador y le reenvía su rol. Uso de SchoolDayService/StaffService.
function RoleService:FijarSalon(player, salon, sinAviso)
	player = resolverJugador(player)
	if not player then
		return false
	end
	if salon ~= nil and not esAulaValida(salon) then
		warn(PREFIJO .. " FijarSalon: aula desconocida '" .. tostring(salon) .. "'.")
		return false
	end
	pcall(function()
		player:SetAttribute("Salon", salon)
	end)
	if not sinAviso then
		self:EnviarRol(player)
	end
	return true
end

-- Interpreta el resultado de SchoolDayService:AsignarAula (string, tabla o ok, string).
local function aulaDeResultado(r1, r2)
	if esAulaValida(r1) then
		return r1
	end
	if typeof(r1) == "table" then
		local candidato = r1.RoomId or r1.Salon or r1.Aula or r1.Id
		if esAulaValida(candidato) then
			return candidato
		end
	end
	if r1 == true and esAulaValida(r2) then
		return r2
	end
	return nil
end

-- Resuelve el aula según el cargo nuevo: docentes piden aula; estudiantes la piden si no tienen; resto sin aula.
function RoleService:ResolverAula(player, cargo, anterior)
	local SchoolDayService = self:Servicio("SchoolDayService")
	local esDocente = RoleDefinitions.EsDocente(cargo)
	local eraDocente = anterior ~= nil and RoleDefinitions.EsDocente(anterior)
	local esEstudiante = cargo == "Estudiante"
	local eraEstudiante = anterior == "Estudiante"

	-- Al dejar un cargo con aula (o cambiar de tipo de aula) se libera la anterior.
	local cambiaTipo = (eraDocente and not esDocente) or (eraEstudiante and not esEstudiante)
	if cambiaTipo then
		invocar(SchoolDayService, "LiberarAula", player)
		pcall(function()
			player:SetAttribute("Salon", nil)
		end)
	end

	if not esDocente and not esEstudiante then
		pcall(function()
			player:SetAttribute("Salon", nil)
		end)
		return nil
	end

	local actual = self:Salon(player)
	if esDocente or not esAulaValida(actual) then
		local ok, r1, r2 = invocar(SchoolDayService, "AsignarAula", player, nil)
		if ok then
			local aula = aulaDeResultado(r1, r2)
			if aula then
				pcall(function()
					player:SetAttribute("Salon", aula)
				end)
			end
		end
	end
	local salon = self:Salon(player)
	if salon and not esAulaValida(salon) then
		pcall(function()
			player:SetAttribute("Salon", nil)
		end)
		salon = nil
	end
	return salon
end

---------------------------------------------------------------------------------------------------
-- Asignación
---------------------------------------------------------------------------------------------------

function RoleService:EnviarRol(player, extra)
	local RemoteService = self:Servicio("RemoteService")
	if not RemoteService or typeof(RemoteService.Enviar) ~= "function" then
		return false
	end
	local datos = self:DatosRol(player)
	if not datos then
		return false
	end
	if typeof(extra) == "table" then
		for clave, valor in pairs(extra) do
			datos[clave] = valor
		end
	end
	local ok = invocar(RemoteService, "Enviar", player, "Rol", datos)
	return ok
end

function RoleService:Notificar(player, titulo, texto, nivelAviso)
	local RemoteService = self:Servicio("RemoteService")
	if RemoteService then
		invocar(RemoteService, "Enviar", player, "Notificacion", {
			Titulo = titulo, Texto = texto, Nivel = nivelAviso or "info", Tipo = nivelAviso or "info",
		})
	end
end

-- Zona de aparición del jugador según su cargo y aula (SpawnService si existe).
function RoleService:ZonaDe(player)
	local SpawnService = self:Servicio("SpawnService")
	local ok, zona = invocar(SpawnService, "ZonaPara", player)
	if ok and typeof(zona) == "string" then
		return zona
	end
	return RoleDefinitions.ZonaSpawnDe(self:Cargo(player), self:Salon(player))
end

-- Asigna el cargo al jugador. origen: texto para auditoría ("Entrada", "Menu", "Admin:<nombre>", ...).
-- opciones = { SinAparecer = bool, AsignadoPor = Player }. Devuelve true, info | false, motivo.
function RoleService:Asignar(player, cargo, origen, opciones)
	player = resolverJugador(player)
	if not player or player.Parent == nil then
		return false, "jugador_invalido"
	end
	if not RoleDefinitions.Existe(cargo) then
		return false, "cargo_invalido"
	end
	opciones = typeof(opciones) == "table" and opciones or {}
	origen = tostring(origen or "Sistema")
	local userId = player.UserId
	local anterior = self.Cargos[userId]
	local rol = RoleDefinitions.Obtener(cargo)

	-- 1. Estado en servidor y atributos replicados.
	self.Cargos[userId] = cargo
	pcall(function()
		player:SetAttribute("Cargo", cargo)
		player:SetAttribute("Equipo", rol.Equipo)
	end)

	-- 2. Team.
	self:FijarTeam(player, cargo)

	-- 3. Aula (docentes antes de aparecer, para que el spawn vaya a su aula).
	local salon = self:ResolverAula(player, cargo, anterior)

	-- 4. Uniforme sobre el personaje actual.
	self:AplicarUniforme(player, cargo)

	-- 5. Perfil: último cargo elegido (el cargo por defecto de la entrada no lo sobrescribe, así el menú
	-- puede proponer el último cargo del jugador).
	local DataService = self:Servicio("DataService")
	local okPerfil, perfil = invocar(DataService, "Obtener", player)
	if okPerfil and typeof(perfil) == "table" and origen ~= "Entrada" then
		if typeof(perfil.Progreso) ~= "table" then
			perfil.Progreso = {}
		end
		if perfil.Progreso.UltimoCargo ~= cargo then
			perfil.Progreso.UltimoCargo = cargo
			invocar(DataService, "Marcar", player)
		end
	end

	-- 6. Auditoría.
	self:Auditar(player, "Asignar", string.format("%s -> %s (%s)%s", tostring(anterior or "-"), cargo, origen,
		salon and (" · aula " .. salon) or ""))

	-- 7. Señal para otros servicios (ClassroomService cancela sesiones, SchoolDayService reparte aulas...).
	self.CargoCambiado:Fire(player, cargo, anterior)

	-- 8. Rol al cliente.
	local extra = { Origen = origen, Anterior = anterior }
	if esJugador(opciones.AsignadoPor) then
		extra.AsignadoPor = opciones.AsignadoPor.Name
	end
	self:EnviarRol(player, extra)

	-- 9. Aparición en la zona del cargo (no bloquea la respuesta).
	local SpawnService = self:Servicio("SpawnService")
	local omitir = opciones.SinAparecer == true
	if not omitir and origen == "Entrada" then
		-- Al entrar, si SpawnService ya colocó el personaje actual no se vuelve a mover.
		local ok, yaColocado = invocar(SpawnService, "YaColocado", player)
		omitir = ok and yaColocado == true
	end
	if not omitir and SpawnService and typeof(SpawnService.Aparecer) == "function" then
		task.spawn(function()
			invocar(SpawnService, "Aparecer", player)
		end)
	end

	return true, {
		Cargo = cargo,
		Equipo = rol.Equipo,
		Zona = self:ZonaDe(player),
		Salon = salon,
		Nombre = rol.Nombre,
	}
end

---------------------------------------------------------------------------------------------------
-- Gestión por administradores (ModerationService / StaffService)
---------------------------------------------------------------------------------------------------
function RoleService:EnCooldownGestion(admin)
	local ultimo = self.UltimaGestion[admin.UserId]
	if ultimo and os.clock() - ultimo < self.CooldownAdminSeg then
		return true, math.ceil(self.CooldownAdminSeg - (os.clock() - ultimo))
	end
	return false, 0
end

-- Asigna un cargo a otro jugador. Devuelve true, info | false, motivo.
function RoleService:AsignarPorAdmin(admin, objetivo, cargo)
	admin = resolverJugador(admin)
	objetivo = resolverJugador(objetivo)
	if not admin or not objetivo or objetivo.Parent == nil then
		return false, "jugador_invalido"
	end
	if not RoleDefinitions.Existe(cargo) then
		return false, "cargo_invalido"
	end
	local cargoAdmin = self:Cargo(admin)
	if not self:Tiene(admin, "cargos.asignar") then
		self:Auditar(admin, "AsignarDenegado", "sin permiso cargos.asignar · objetivo " .. objetivo.Name .. " -> " .. cargo)
		return false, "sin_permiso"
	end
	if not RoleDefinitions.PuedeAsignar(cargoAdmin, cargo) then
		self:Auditar(admin, "AsignarDenegado", cargoAdmin .. " no puede asignar " .. cargo)
		return false, "cargo_no_asignable"
	end
	if admin == objetivo then
		if nivel(cargo) > nivel(cargoAdmin) then
			self:Auditar(admin, "AsignarDenegado", "auto-ascenso a " .. cargo)
			return false, "auto_superior"
		end
	elseif nivel(self:Cargo(objetivo)) > nivel(cargoAdmin) then
		self:Auditar(admin, "AsignarDenegado", "objetivo con cargo superior: " .. objetivo.Name .. " (" .. tostring(self:Cargo(objetivo)) .. ")")
		return false, "objetivo_superior"
	end
	local enCooldown, restante = self:EnCooldownGestion(admin)
	if enCooldown then
		return false, "cooldown:" .. tostring(restante)
	end
	self.UltimaGestion[admin.UserId] = os.clock()

	local anterior = self:Cargo(objetivo)
	local ok, info = self:Asignar(objetivo, cargo, "Admin:" .. admin.Name, { AsignadoPor = admin })
	if not ok then
		return false, info
	end
	self:Auditar(admin, "AsignarPorAdmin", string.format("%s(%d): %s -> %s", objetivo.Name, objetivo.UserId, tostring(anterior), cargo))
	self:Notificar(objetivo, "Nuevo cargo", admin.Name .. " te asignó el cargo " .. RoleDefinitions.Nombre(cargo) .. ".", "info")
	return true, info
end

-- Revoca el cargo de un jugador (pasa a Config.Spawns.CargoPorDefecto). Devuelve true, info | false, motivo.
function RoleService:Revocar(admin, objetivo)
	admin = resolverJugador(admin)
	objetivo = resolverJugador(objetivo)
	if not admin or not objetivo or objetivo.Parent == nil then
		return false, "jugador_invalido"
	end
	local cargoAdmin = self:Cargo(admin)
	if not self:Tiene(admin, "cargos.revocar") then
		self:Auditar(admin, "RevocarDenegado", "sin permiso cargos.revocar · objetivo " .. objetivo.Name)
		return false, "sin_permiso"
	end
	local cargoObjetivo = self:Cargo(objetivo)
	if admin ~= objetivo and nivel(cargoObjetivo) > nivel(cargoAdmin) then
		self:Auditar(admin, "RevocarDenegado", "objetivo con cargo superior: " .. objetivo.Name .. " (" .. tostring(cargoObjetivo) .. ")")
		return false, "objetivo_superior"
	end
	if cargoObjetivo == CARGO_DEFECTO then
		return false, "sin_cargo"
	end
	local enCooldown, restante = self:EnCooldownGestion(admin)
	if enCooldown then
		return false, "cooldown:" .. tostring(restante)
	end
	self.UltimaGestion[admin.UserId] = os.clock()

	local ok, info = self:Asignar(objetivo, CARGO_DEFECTO, "Revocado:" .. admin.Name, { AsignadoPor = admin })
	if not ok then
		return false, info
	end
	self:Auditar(admin, "Revocar", string.format("%s(%d): %s -> %s", objetivo.Name, objetivo.UserId, tostring(cargoObjetivo), CARGO_DEFECTO))
	self:Notificar(objetivo, "Cargo revocado", admin.Name .. " revocó tu cargo de " .. RoleDefinitions.Nombre(cargoObjetivo)
		.. ". Ahora eres " .. RoleDefinitions.Nombre(CARGO_DEFECTO) .. ".", "aviso")
	return true, info
end

---------------------------------------------------------------------------------------------------
-- Handlers de remotos (RemoteService ya validó tabla, esquema, límite y permiso)
---------------------------------------------------------------------------------------------------
-- Último cargo elegido guardado en el perfil (Progreso.UltimoCargo) o nil.
function RoleService:UltimoCargo(player)
	local DataService = self:Servicio("DataService")
	local ok, perfil = invocar(DataService, "Obtener", player)
	if ok and typeof(perfil) == "table" and typeof(perfil.Progreso) == "table" and RoleDefinitions.Existe(perfil.Progreso.UltimoCargo) then
		return perfil.Progreso.UltimoCargo
	end
	return nil
end

function RoleService:ManejarLista(player, _datos)
	return RemoteContracts.Ok({
		Cargos = self:ListaCargos(player),
		Actual = self:Cargo(player),
		Salon = self:Salon(player),
		Ultimo = self:UltimoCargo(player),
	})
end

function RoleService:ManejarUnirse(player, datos)
	local cargo = datos.Cargo
	if not RoleDefinitions.Existe(cargo) then
		return RemoteContracts.Error("cargo_invalido")
	end
	local userId = player.UserId
	local ultimo = self.UltimoCambio[userId]
	if ultimo and os.clock() - ultimo < self.CooldownCambioSeg then
		local respuesta = RemoteContracts.Error("cooldown")
		respuesta.datos = { RestanteSeg = math.ceil(self.CooldownCambioSeg - (os.clock() - ultimo)) }
		return respuesta
	end
	local autorizado, motivo = self:Autorizado(player, cargo)
	if not autorizado then
		self:Auditar(player, "IntentoNoAutorizado", cargo .. " (" .. tostring(motivo) .. ")")
		local respuesta = RemoteContracts.Error(motivo or "no_autorizado")
		respuesta.datos = { Motivo = motivo, MotivoTexto = self.TextosMotivo[motivo] or motivo }
		return respuesta
	end
	self.UltimoCambio[userId] = os.clock()
	local ok, info = self:Asignar(player, cargo, "Menu (" .. tostring(motivo) .. ")")
	if not ok then
		return RemoteContracts.Error(info or "error")
	end
	return RemoteContracts.Ok(info)
end

return RoleService
]=] }
FUENTES["ServerScriptService/ColegioRP/Services/RoomService"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ServerScriptService.ColegioRP.Services.RoomService
	Tipo: ModuleScript
	Ocupación de las aulas (docs/ARQUITECTURA.md §6, prueba P5): escucha Seat.Occupant de todos los asientos
	reales de cada aula (MapService:Aulas(), incluidos los duplicados), resuelve el Player desde el Humanoid,
	valida la pertenencia (docente de esa aula o atributo Salon == roomId; si no, avisa sin expulsar) y mantiene
	quién está sentado y quién de pie en cada aula. Cada jugador pertenece como máximo a UN aula a la vez
	(asiento > zona más pequeña que contiene su HumanoidRootPart), de modo que los envíos por aula nunca llegan
	a jugadores de otra aula (P4). Señal OcupacionCambiada(roomId) en cada cambio de asientos o de presencia.
]]

local Players = game:GetService("Players")
local CollectionService = game:GetService("CollectionService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local RP = ReplicatedStorage:WaitForChild("ColegioRP")
local Shared = RP:WaitForChild("Shared")
local Config = require(Shared:WaitForChild("Config"))
local MapaLogico = require(Shared:WaitForChild("MapaLogico"))
local RoleDefinitions = require(Shared:WaitForChild("RoleDefinitions"))
local Util = Shared:WaitForChild("Util")
local Zones = require(Util:WaitForChild("Zones"))
local Signal = require(Util:WaitForChild("Signal"))
local Maid = require(Util:WaitForChild("Maid"))

local RoomService = {}
RoomService.Nombre = "RoomService"

local PREFIJO = "[ColegioRP][RoomService]"

---------------------------------------------------------------------------------------------------
-- Parámetros
---------------------------------------------------------------------------------------------------
RoomService.IntervaloPresenciaSeg = 2 -- Cada cuánto se recalcula quién está de pie en cada aula.
RoomService.CooldownAvisoAsientoSeg = 12 -- Segundos entre avisos de "asiento de otra aula" al mismo jugador.

local TAG_ASIENTO = (Config.Tags and Config.Tags.Asiento) or "ColegioRP_Asiento"

---------------------------------------------------------------------------------------------------
-- Utilidades
---------------------------------------------------------------------------------------------------
local function esJugador(valor)
	return typeof(valor) == "Instance" and valor:IsA("Player")
end

local function esAsiento(valor)
	return typeof(valor) == "Instance" and (valor:IsA("Seat") or valor:IsA("VehicleSeat"))
end

local function raizDe(player)
	local personaje = player.Character
	if not personaje then
		return nil
	end
	local raiz = personaje:FindFirstChild("HumanoidRootPart")
	if raiz and raiz:IsA("BasePart") then
		return raiz
	end
	return nil
end

local function nombreAula(roomId)
	local zona = MapaLogico.Zonas[roomId]
	if zona and typeof(zona.Nombre) == "string" and zona.Nombre ~= "" then
		return zona.Nombre .. " (" .. tostring(roomId) .. ")"
	end
	return tostring(roomId)
end

local function copiarConjunto(conjunto)
	local copia = {}
	for clave, valor in pairs(conjunto) do
		copia[clave] = valor
	end
	return copia
end

local function conjuntosIguales(a, b)
	for clave in pairs(a) do
		if not b[clave] then
			return false
		end
	end
	for clave in pairs(b) do
		if not a[clave] then
			return false
		end
	end
	return true
end

local function ordenarIds(lista)
	table.sort(lista, function(x, y)
		return x < y
	end)
	return lista
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function RoomService:Init(registro)
	self.registro = registro
	self.OcupacionCambiada = Signal.new() -- (roomId)
	self.AsientoCambiado = Signal.new() -- (player, seat|nil, roomId|nil)
	self._infoSeat = {} -- Seat -> { RoomId, Canonico }
	self._ocupante = {} -- Seat -> userId sentado en ese Seat
	self._asientoDe = {} -- userId -> Seat que ocupa
	self._sentados = {} -- roomId -> { [userId] = Seat }
	self._presencia = {} -- roomId -> { [userId] = true } (último cálculo, incluye sentados)
	self._capacidad = {} -- roomId -> n
	self._ultimoAviso = {} -- userId -> os.clock() del último aviso de asiento ajeno
	self._maidAsientos = Maid.new()
	self._maidsJugador = {} -- userId -> Maid
	self.maid = Maid.new()
	self.activo = true
	for _, roomId in ipairs(MapaLogico.Aulas or {}) do
		self._sentados[roomId] = {}
		self._presencia[roomId] = {}
		self._capacidad[roomId] = 0
	end
end

function RoomService:Start()
	self:ConectarAsientos()

	-- Si MapService reconstruye el mapa, se vuelven a conectar los asientos.
	local MapService = self.registro.Get("MapService")
	if MapService and MapService.Construido and typeof(MapService.Construido.Connect) == "function" then
		self.maid:GiveTask(MapService.Construido:Connect(function()
			self:ConectarAsientos()
		end))
	end

	self.maid:GiveTask(Players.PlayerAdded:Connect(function(player)
		self:AlEntrar(player)
	end))
	self.maid:GiveTask(Players.PlayerRemoving:Connect(function(player)
		self:AlSalir(player)
	end))
	for _, player in ipairs(Players:GetPlayers()) do
		self:AlEntrar(player)
	end

	-- Presencia de pie: recálculo periódico de baja frecuencia (sin RenderStepped).
	self.maid:GiveTask(task.spawn(function()
		while self.activo do
			task.wait(self.IntervaloPresenciaSeg)
			local ok, err = pcall(self.RecalcularPresencia, self)
			if not ok then
				warn(PREFIJO .. " Error al recalcular la presencia: " .. tostring(err))
			end
		end
	end))

	local AuditLog = self.registro.Get("AuditLogService")
	if AuditLog then
		local total = 0
		for _ in pairs(self._infoSeat) do
			total = total + 1
		end
		AuditLog:Registrar("Sistema", nil, "Aulas", total .. " asientos de aula vigilados por RoomService")
	end
end

---------------------------------------------------------------------------------------------------
-- Asientos
---------------------------------------------------------------------------------------------------

-- Conecta Occupant en todos los asientos de aula (re-ejecutable: limpia las conexiones anteriores).
function RoomService:ConectarAsientos()
	self._maidAsientos:DoCleaning()
	self._infoSeat = {}
	self._ocupante = {}
	self._asientoDe = {}
	for roomId in pairs(self._sentados) do
		self._sentados[roomId] = {}
		self._capacidad[roomId] = 0
	end

	local MapService = self.registro.Get("MapService")
	local aulas = nil
	if MapService and typeof(MapService.Aulas) == "function" then
		local ok, resultado = pcall(MapService.Aulas, MapService)
		if ok and typeof(resultado) == "table" then
			aulas = resultado
		end
	end

	if aulas then
		for roomId, info in pairs(aulas) do
			if typeof(info) == "table" then
				if not self._sentados[roomId] then
					self._sentados[roomId] = {}
					self._presencia[roomId] = {}
				end
				local seats = info.Seats or {}
				self._capacidad[roomId] = #seats
				for _, seat in ipairs(seats) do
					self:RegistrarAsiento(seat, roomId, seat)
				end
				for _, par in ipairs(info.Duplicados or {}) do
					if typeof(par) == "table" then
						self:RegistrarAsiento(par.Seat, roomId, par.Canonico or par.Seat)
					end
				end
			end
		end
	else
		-- Respaldo sin MapService: Seats etiquetados con atributo RoomId.
		warn(PREFIJO .. " MapService no disponible; se usan los Seats con tag " .. TAG_ASIENTO .. ".")
		local ok, etiquetados = pcall(CollectionService.GetTagged, CollectionService, TAG_ASIENTO)
		if ok and typeof(etiquetados) == "table" then
			for _, seat in ipairs(etiquetados) do
				local roomId = esAsiento(seat) and seat:GetAttribute("RoomId") or nil
				if typeof(roomId) == "string" and Zones.EsAula(roomId) then
					self._capacidad[roomId] = (self._capacidad[roomId] or 0) + 1
					self:RegistrarAsiento(seat, roomId, seat)
				end
			end
		end
	end

	for roomId in pairs(self._sentados) do
		self.OcupacionCambiada:Fire(roomId)
	end
end

function RoomService:RegistrarAsiento(seat, roomId, canonico)
	if not esAsiento(seat) or self._infoSeat[seat] then
		return
	end
	self._infoSeat[seat] = { RoomId = roomId, Canonico = canonico or seat }
	local ok, conexion = pcall(function()
		return seat:GetPropertyChangedSignal("Occupant"):Connect(function()
			self:AlCambiarOcupante(seat)
		end)
	end)
	if ok and conexion then
		self._maidAsientos:GiveTask(conexion)
	end
	-- Asiento ya ocupado al conectar (p. ej. tras reconstruir el mapa).
	if seat.Occupant ~= nil then
		self:AlCambiarOcupante(seat)
	end
end

-- Quita al jugador del asiento que tuviera registrado (sin disparar señales).
function RoomService:_Liberar(userId)
	local seat = self._asientoDe[userId]
	if not seat then
		return nil
	end
	self._asientoDe[userId] = nil
	if self._ocupante[seat] == userId then
		self._ocupante[seat] = nil
	end
	local info = self._infoSeat[seat]
	local roomId = info and info.RoomId or nil
	if roomId and self._sentados[roomId] and self._sentados[roomId][userId] == seat then
		self._sentados[roomId][userId] = nil
	end
	return roomId
end

function RoomService:AlCambiarOcupante(seat)
	local info = self._infoSeat[seat]
	if not info then
		return
	end
	local roomId = info.RoomId
	local afectadas = {}

	-- Ocupante anterior de este Seat.
	local anterior = self._ocupante[seat]
	if anterior then
		self._ocupante[seat] = nil
		if self._asientoDe[anterior] == seat then
			self._asientoDe[anterior] = nil
		end
		if self._sentados[roomId] then
			self._sentados[roomId][anterior] = nil
		end
		afectadas[roomId] = true
		local playerAnterior = Players:GetPlayerByUserId(anterior)
		if playerAnterior then
			self.AsientoCambiado:Fire(playerAnterior, nil, nil)
		end
	end

	-- Nuevo ocupante.
	local humanoid = seat.Occupant
	local player = nil
	if humanoid and humanoid.Parent then
		player = Players:GetPlayerFromCharacter(humanoid.Parent)
	end
	if player then
		local userId = player.UserId
		local previa = self:_Liberar(userId)
		if previa then
			afectadas[previa] = true
		end
		self._ocupante[seat] = userId
		self._asientoDe[userId] = seat
		if not self._sentados[roomId] then
			self._sentados[roomId] = {}
		end
		self._sentados[roomId][userId] = seat
		afectadas[roomId] = true
		self:ValidarPertenencia(player, roomId)
		self.AsientoCambiado:Fire(player, seat, roomId)
	end

	for id in pairs(afectadas) do
		self:_ActualizarPresenciaAula(id)
		self.OcupacionCambiada:Fire(id)
	end
end

-- ¿El jugador pertenece al aula del asiento? (docente de esa aula o Salon == roomId). Si no, solo se avisa.
function RoomService:Pertenece(player, roomId)
	local RoleService = self.registro.Get("RoleService")
	local salon = player:GetAttribute("Salon")
	if RoleService and typeof(RoleService.Salon) == "function" then
		local ok, valor = pcall(RoleService.Salon, RoleService, player)
		if ok and typeof(valor) == "string" then
			salon = valor
		end
	end
	if salon == roomId then
		return true
	end
	local ClassroomService = self.registro.Get("ClassroomService")
	if ClassroomService and typeof(ClassroomService.EsDocenteDe) == "function" then
		local ok, esDocente = pcall(ClassroomService.EsDocenteDe, ClassroomService, player, roomId)
		if ok and esDocente == true then
			return true
		end
	end
	-- Coordinación académica (horario.editar) puede dirigir cualquier aula.
	local cargo = player:GetAttribute("Cargo")
	if RoleService and typeof(RoleService.Cargo) == "function" then
		local ok, valor = pcall(RoleService.Cargo, RoleService, player)
		if ok and typeof(valor) == "string" then
			cargo = valor
		end
	end
	if typeof(cargo) == "string" and RoleDefinitions.Tiene(cargo, "aula.docente") and RoleDefinitions.Tiene(cargo, "horario.editar") then
		return true
	end
	return false, salon
end

function RoomService:ValidarPertenencia(player, roomId)
	local pertenece, salon = self:Pertenece(player, roomId)
	if pertenece then
		return true
	end
	local ahora = os.clock()
	local ultimo = self._ultimoAviso[player.UserId]
	if ultimo and ahora - ultimo < self.CooldownAvisoAsientoSeg then
		return false
	end
	self._ultimoAviso[player.UserId] = ahora
	local texto = "Este asiento pertenece al aula " .. nombreAula(roomId) .. "."
	if typeof(salon) == "string" and salon ~= "" then
		texto = texto .. " Tu salón es " .. nombreAula(salon) .. "."
	end
	local RemoteService = self.registro.Get("RemoteService")
	if RemoteService then
		RemoteService:Enviar(player, "Notificacion", { Texto = texto, Nivel = "aviso", Duracion = 6 })
	end
	return false
end

---------------------------------------------------------------------------------------------------
-- Jugadores
---------------------------------------------------------------------------------------------------
function RoomService:AlEntrar(player)
	if not esJugador(player) then
		return
	end
	local userId = player.UserId
	if self._maidsJugador[userId] then
		self._maidsJugador[userId]:DoCleaning()
	end
	local maid = Maid.new()
	self._maidsJugador[userId] = maid
	local function limpiar()
		local roomId = self:_Liberar(userId)
		if roomId then
			self:_ActualizarPresenciaAula(roomId)
			self.OcupacionCambiada:Fire(roomId)
		end
	end
	maid:GiveTask(player.CharacterRemoving:Connect(limpiar))
	maid:GiveTask(player.CharacterAdded:Connect(limpiar))
end

function RoomService:AlSalir(player)
	local userId = player.UserId
	local maid = self._maidsJugador[userId]
	if maid then
		self._maidsJugador[userId] = nil
		maid:DoCleaning()
	end
	self._ultimoAviso[userId] = nil
	local afectadas = {}
	local roomId = self:_Liberar(userId)
	if roomId then
		afectadas[roomId] = true
	end
	for id, presentes in pairs(self._presencia) do
		if presentes[userId] then
			presentes[userId] = nil
			afectadas[id] = true
		end
	end
	for id in pairs(afectadas) do
		self.OcupacionCambiada:Fire(id)
	end
end

---------------------------------------------------------------------------------------------------
-- Presencia
---------------------------------------------------------------------------------------------------

-- Aula en la que está el jugador ahora: la del asiento que ocupa o, si no está sentado en un aula, la zona
-- de aula más pequeña que contiene su HumanoidRootPart (Zones.Contiene). Un jugador = como máximo un aula.
function RoomService:AulaActualDe(player)
	if not esJugador(player) then
		return nil
	end
	local seat = self._asientoDe[player.UserId]
	if seat then
		local info = self._infoSeat[seat]
		if info and seat.Occupant ~= nil then
			return info.RoomId
		end
	end
	local raiz = raizDe(player)
	if not raiz then
		return nil
	end
	local posicion = raiz.Position
	for _, zona in ipairs(Zones.ZonasEn(posicion)) do
		if Zones.EsAula(zona.Id) and Zones.Contiene(zona, posicion) then
			return zona.Id
		end
	end
	return nil
end

-- ¿El jugador está ahora en el aula (sentado en uno de sus asientos o de pie dentro de su zona)?
function RoomService:EstaEn(player, roomId)
	if typeof(roomId) ~= "string" then
		return false
	end
	return self:AulaActualDe(player) == roomId
end

-- Jugadores presentes en el aula ahora mismo (array de Player).
function RoomService:JugadoresEn(roomId)
	local lista = {}
	if typeof(roomId) ~= "string" then
		return lista
	end
	for _, player in ipairs(Players:GetPlayers()) do
		if self:AulaActualDe(player) == roomId then
			table.insert(lista, player)
		end
	end
	return lista
end

-- UserIds presentes (array ordenado).
function RoomService:Presentes(roomId)
	local lista = {}
	for _, player in ipairs(self:JugadoresEn(roomId)) do
		table.insert(lista, player.UserId)
	end
	return ordenarIds(lista)
end

-- { Sentados = {userId...}, DePie = {userId...}, Capacidad = n, RoomId }. En aulas sin Seats, Sentados queda
-- vacío y DePie lista a todos los presentes.
function RoomService:Ocupacion(roomId)
	local resultado = { RoomId = roomId, Sentados = {}, DePie = {}, Capacidad = self._capacidad[roomId] or 0 }
	if typeof(roomId) ~= "string" then
		return resultado
	end
	local sentados = self._sentados[roomId] or {}
	for _, player in ipairs(self:JugadoresEn(roomId)) do
		local seat = sentados[player.UserId]
		if seat and seat.Occupant ~= nil then
			table.insert(resultado.Sentados, player.UserId)
		else
			table.insert(resultado.DePie, player.UserId)
		end
	end
	ordenarIds(resultado.Sentados)
	ordenarIds(resultado.DePie)
	return resultado
end

-- Seat que ocupa el jugador (o nil).
function RoomService:AsientoDe(player)
	if not esJugador(player) then
		return nil
	end
	local seat = self._asientoDe[player.UserId]
	if seat and seat.Occupant ~= nil then
		return seat
	end
	return nil
end

-- RoomId del aula de un Seat (incluidos los duplicados) o nil.
function RoomService:AulaDeAsiento(seat)
	local info = self._infoSeat[seat]
	if info then
		return info.RoomId
	end
	local MapService = self.registro.Get("MapService")
	if MapService and typeof(MapService.AulaDeAsiento) == "function" then
		local ok, roomId = pcall(MapService.AulaDeAsiento, MapService, seat)
		if ok and typeof(roomId) == "string" then
			return roomId
		end
	end
	return nil
end

-- Capacidad (asientos reales) del aula.
function RoomService:Capacidad(roomId)
	return self._capacidad[roomId] or 0
end

-- Recalcula la presencia de un aula y devuelve true si cambió (no dispara la señal).
function RoomService:_ActualizarPresenciaAula(roomId)
	local nueva = {}
	for _, player in ipairs(self:JugadoresEn(roomId)) do
		nueva[player.UserId] = true
	end
	local anterior = self._presencia[roomId] or {}
	self._presencia[roomId] = nueva
	return not conjuntosIguales(anterior, nueva)
end

-- Recalcula la presencia de todas las aulas en una sola pasada y dispara OcupacionCambiada donde cambió.
function RoomService:RecalcularPresencia()
	local nuevas = {}
	for roomId in pairs(self._presencia) do
		nuevas[roomId] = {}
	end
	for _, player in ipairs(Players:GetPlayers()) do
		local roomId = self:AulaActualDe(player)
		if roomId then
			if not nuevas[roomId] then
				nuevas[roomId] = {}
			end
			nuevas[roomId][player.UserId] = true
		end
	end
	for roomId, nueva in pairs(nuevas) do
		local anterior = self._presencia[roomId] or {}
		self._presencia[roomId] = nueva
		if not conjuntosIguales(anterior, nueva) then
			self.OcupacionCambiada:Fire(roomId)
		end
	end
end

-- Resumen legible para paneles: { RoomId, Nombre, Capacidad, Sentados = { {UserId, Nombre} }, DePie = {...} }.
function RoomService:Resumen(roomId)
	local ocupacion = self:Ocupacion(roomId)
	local function conNombres(ids)
		local lista = {}
		for _, userId in ipairs(ids) do
			local player = Players:GetPlayerByUserId(userId)
			table.insert(lista, {
				UserId = userId,
				Nombre = player and player.DisplayName or tostring(userId),
				Usuario = player and player.Name or "",
			})
		end
		return lista
	end
	return {
		RoomId = roomId,
		Nombre = nombreAula(roomId),
		Capacidad = ocupacion.Capacidad,
		Sentados = conNombres(ocupacion.Sentados),
		DePie = conNombres(ocupacion.DePie),
	}
end

-- Copia de la presencia calculada (diagnóstico): { roomId = { userId = true } }.
function RoomService:PresenciaCalculada()
	local copia = {}
	for roomId, presentes in pairs(self._presencia) do
		copia[roomId] = copiarConjunto(presentes)
	end
	return copia
end

-- Detiene el bucle y libera conexiones (uso en pruebas / reinstalación).
function RoomService:Detener()
	self.activo = false
	self._maidAsientos:DoCleaning()
	self.maid:DoCleaning()
	for userId, maid in pairs(self._maidsJugador) do
		maid:DoCleaning()
		self._maidsJugador[userId] = nil
	end
end

return RoomService
]=] }
FUENTES["ServerScriptService/ColegioRP/Services/SchoolDayService"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: ServerScriptService.ColegioRP.Services.SchoolDayService
	Tipo: ModuleScript
	Jornada escolar (docs/ARQUITECTURA.md §3 y §6). Máquina de estados ESPERA -> ENTRADA -> CLASE_1 -> TRANSICION ->
	DESCANSO -> CLASE_2 -> ALMUERZO -> CLASE_3 -> SALIDA -> REINICIO -> (ESPERA) con las duraciones de
	TimetableDefinitions (configurables en caliente), modo Automatica (ciclo continuo) o Manual (espera a que la
	dirección pulse Iniciar), Pausar/Reanudar/Saltar/Reiniciar y snapshot para el HUD (reloj escolar interpolable).
	Timbres con subtítulo y sonido opcional, asignación balanceada de aulas (atributo Salon del Player), asistencia
	por aula en cada clase (Presente/Tardanza/Ausente con recompensa, progreso y aviso al docente de la sesión),
	cierre de la jornada (sesiones, guardado, limpieza) y handlers de JornadaControl, StateSnapshot y SettingsUpdate
	(este último solo si DataService no lo registra).
]]

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local SoundService = game:GetService("SoundService")

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RP = ReplicatedStorage:WaitForChild("ColegioRP")
local Shared = RP:WaitForChild("Shared")
local Config = require(Shared:WaitForChild("Config"))
local TimetableDefinitions = require(Shared:WaitForChild("TimetableDefinitions"))
local RoleDefinitions = require(Shared:WaitForChild("RoleDefinitions"))
local RemoteContracts = require(Shared:WaitForChild("RemoteContracts"))
