local dibujo = { Activo = false, EsRaton = false, Entrada = nil, Puntos = {}, Ultimo = 0, Previa = {}, RoomId = nil, Continuacion = false }
local cola = {} -- { RoomId, Vectores, Previa = {Frame...} }
local procesandoCola = false
