	UIBuilder.Disposicion(sentados, { Espaciado = 4 })
	self.ui.AlSentados = sentados
	self.ui.TituloDePie = UIBuilder.Subtitulo(pagina, "De pie", { LayoutOrder = siguiente() })
	local dePie = UIBuilder.Marco(pagina, { AutoAlto = true, LayoutOrder = siguiente(), Nombre = "DePie" })
	UIBuilder.Disposicion(dePie, { Espaciado = 4 })
	self.ui.AlDePie = dePie
end

---------------------------------------------------------------------------------------------------
-- Filas reutilizables de las listas
---------------------------------------------------------------------------------------------------
function ClassroomController:_Fila(parent, texto, orden, botones, color)
	local fila = Instance.new("Frame")
	fila.Name = "Fila"
	fila.BackgroundColor3 = color or Colores.Gris
	fila.BackgroundTransparency = 0.35
	fila.BorderSizePixel = 0
	fila.Size = UDim2.new(1, 0, 0, 0)
	fila.AutomaticSize = Enum.AutomaticSize.Y
	fila.LayoutOrder = orden or 0
	UIBuilder.Esquinas(fila, UITheme.RadioPequeno)
	UIBuilder.Relleno(fila, 6, 6, 10, 6)
	UIBuilder.Disposicion(fila, { Espaciado = 4 })
	UIBuilder.Texto(fila, texto, { LayoutOrder = 1, Tamano = "Pequeno" })
	if typeof(botones) == "table" and #botones > 0 then
		local filaBotones = UIBuilder.Fila(fila, { LayoutOrder = 2, Espaciado = 6 })
		local creados = {}
		for i, def in ipairs(botones) do
			local boton = UIBuilder.Boton(filaBotones, def.Texto, def.Accion, {
				Estilo = def.Estilo or "Secundario", Ancho = def.Ancho or 130, LayoutOrder = i, Tamano = "Pequeno",
				Desactivado = def.Desactivado == true,
			})
			table.insert(creados, boton)
		end
		UIBuilder.Encadenar(creados, true)
	end
	fila.Parent = parent
	return fila
end

local function textoVacio(parent, texto)
	UIBuilder.Texto(parent, texto, { Tamano = "Pequeno", Color = Colores.TextoApagado, LayoutOrder = 0 })
end

-- Vacía y reconstruye una lista conservando el foco del mando: las listas se rehacen en cada actualización
-- (ocupación, respuestas, manos...) y, si el botón enfocado estaba dentro, se enfoca el que ocupa la misma
-- posición en la lista nueva en lugar de perder la selección.
function ClassroomController:_Rehacer(marco, construir)
	local seleccionado = GuiService.SelectedObject
	local posicion = nil
	if seleccionado ~= nil and seleccionado:IsDescendantOf(marco) then
		for i, control in ipairs(seleccionablesDe(marco)) do
			if control == seleccionado then
				posicion = i
				break
			end
		end
	end
	limpiarHijos(marco)
	construir()
	if posicion then
		local nuevos = seleccionablesDe(marco)
		local destino = nuevos[math.min(posicion, #nuevos)]
		if destino then
			pcall(function()
				GuiService.SelectedObject = destino
			end)
		end
	end
end

---------------------------------------------------------------------------------------------------
-- Render dinámico
---------------------------------------------------------------------------------------------------

-- Botones de opción de la actividad del estudiante (solo se rehacen al cambiar de actividad o de estado).
function ClassroomController:_RenderOpciones()
	local marco = self.ui and self.ui.ActOpciones
	if not marco or marco.Parent == nil then
		return
	end
	self:_Rehacer(marco, function()
		local act = self.actividad
		if not act or act.Type ~= "Opciones" or typeof(act.Options) ~= "table" then
			return
		end
		local enClase = self:_EnClase()
		local puede = act.Estado == "Abierta" and self.miRespuesta == nil and enClase and self:_Presente()
			and ahoraServidor() <= (tonumber(act.DueAt) or 0)
		local creados = {}
		for i, texto in ipairs(act.Options) do
			local elegido = self.miRespuesta and self.miRespuesta.Indice == i
			local boton = UIBuilder.Boton(marco, (LETRAS[i] or tostring(i)) .. ")  " .. tostring(texto), function()
				self:_ResponderOpcion(i)
			end, {
				Estilo = elegido and "Primario" or "Secundario", LayoutOrder = i, Size = UDim2.new(1, 0, 0, UIBuilder.AltoBoton()),
				Alineacion = Enum.TextXAlignment.Left, Desactivado = not puede and not elegido,
			})
			if elegido then
				boton:SetAttribute("Desactivado", false)
			end
			table.insert(creados, boton)
		end
		UIBuilder.Encadenar(creados, false)
	end)
end

function ClassroomController:_RenderResumen(marco, resumen)
	if not marco or marco.Parent == nil then
		return
	end
	limpiarHijos(marco)
	if typeof(resumen) ~= "table" then
		textoVacio(marco, "Aún no hay resultados publicados.")
		return
	end
	local orden = 0
	local function siguiente()
		orden = orden + 1
		return orden
	end
	UIBuilder.Texto(marco, tostring(resumen.Prompt or ""), { LayoutOrder = siguiente(), Tamano = "Pequeno" })
	local total = tonumber(resumen.Total) or 0
	UIBuilder.Texto(marco, string.format("%d respuesta(s) · %d presente(s)", total, tonumber(resumen.Presentes) or 0), {
		LayoutOrder = siguiente(), Tamano = "Pequeno", Color = Colores.TextoSecundario,
	})
	if typeof(resumen.Opciones) == "table" then
		for i, opcion in ipairs(resumen.Opciones) do
			local marca = opcion.EsCorrecta and "  ✓" or ""
			UIBuilder.Texto(marco, string.format("%s) %s — %d voto(s)%s", LETRAS[i] or tostring(i), tostring(opcion.Texto), tonumber(opcion.Votos) or 0, marca), {
				LayoutOrder = siguiente(), Tamano = "Pequeno", Color = opcion.EsCorrecta and Colores.Verde or Colores.TextoPrincipal,
			})
			local fraccion = 0
			if total > 0 then
				fraccion = (tonumber(opcion.Votos) or 0) / total
			end
			UIBuilder.Barra(marco, fraccion, { LayoutOrder = siguiente(), Color = opcion.EsCorrecta and Colores.Verde or Colores.Azul })
		end
	end
	if resumen.Correctas ~= nil then
		UIBuilder.Texto(marco, string.format("Aciertos: %d (%s)", tonumber(resumen.Correctas) or 0, Format.Porcentaje(resumen.PorcentajeCorrectas or 0)), {
			LayoutOrder = siguiente(), Tamano = "Pequeno", Color = Colores.Verde,
		})
	end
	if resumen.Promedio ~= nil then
		UIBuilder.Texto(marco, string.format("Nota media: %s / 10 (%d calificada(s))", tostring(resumen.Promedio), tonumber(resumen.Calificadas) or 0), {
			LayoutOrder = siguiente(), Tamano = "Pequeno", Color = Colores.TextoSecundario,
		})
	end
end

function ClassroomController:_RenderResultados()
	local marco = self.ui.ActResultados
	if not marco or marco.Parent == nil then
		return
	end
	limpiarHijos(marco)
	if #self.resultados == 0 then
		textoVacio(marco, "Todavía no tienes resultados en esta clase.")
		return
	end
	for i, resultado in ipairs(self.resultados) do
		local partes = { tostring(resultado.Prompt or "Actividad") }
		if resultado.Correcta ~= nil then
			table.insert(partes, resultado.Correcta and "✓ Correcta" or "✗ Incorrecta")
		end
		if resultado.RespuestaCorrecta and resultado.Correcta == false then
			table.insert(partes, "Correcta: " .. tostring(resultado.RespuestaCorrecta))
		end
		if resultado.Puntos ~= nil then
			table.insert(partes, "Nota: " .. tostring(resultado.Puntos) .. " / 10")
		end
		if typeof(resultado.Comentario) == "string" and resultado.Comentario ~= "" then
			table.insert(partes, "“" .. resultado.Comentario .. "”")
		end
		self:_Fila(marco, table.concat(partes, "\n"), i, nil, resultado.Correcta == false and Colores.RojoOscuro or nil)
	end
end

function ClassroomController:_RenderRespuestas()
	local marco = self.ui.RespLista
	if not marco or marco.Parent == nil then
		return
	end
	local act = self.actividadDocente
	if self.ui.RespTitulo then
		if act then
			self.ui.RespTitulo.Text = string.format("%s · %s · %d respuesta(s)", tostring(act.Prompt), act.Estado == "Abierta" and "abierta" or "cerrada", #self.respuestas)
		else
			self.ui.RespTitulo.Text = "Crea una actividad para recibir respuestas."
		end
	end
	self:_Rehacer(marco, function()
		if #self.respuestas == 0 then
			textoVacio(marco, "Sin respuestas todavía.")
			return
		end
		for i, registro in ipairs(self.respuestas) do
			local partes = { tostring(registro.Nombre) .. ": " .. tostring(registro.Respuesta or "") }
			if registro.Correcta ~= nil then
				table.insert(partes, registro.Correcta and "✓ Correcta" or "✗ Incorrecta")
			end
			if registro.Puntos ~= nil then
				local comentario = ""
				if typeof(registro.Comentario) == "string" and registro.Comentario ~= "" then
					comentario = " · “" .. registro.Comentario .. "”"
				end
				table.insert(partes, "Nota: " .. tostring(registro.Puntos) .. " / 10" .. comentario)
			end
			local copia = registro
			self:_Fila(marco, table.concat(partes, "\n"), i, {
				{ Texto = registro.Puntos ~= nil and "Cambiar nota" or "Calificar", Estilo = "Primario", Ancho = 140, Accion = function()
					self:_AbrirCalificar(copia)
				end },
			})
		end
	end)
end

function ClassroomController:_RenderAlumnos()
	if not self.ui.AlManos or self.ui.AlManos.Parent == nil then
		return
	end
	local enSesion = self:_SoyDocenteDeSesion()
	local enClase = self:_EnClase()
	self:_Rehacer(self.ui.AlManos, function()
		if #self.manos == 0 then
			textoVacio(self.ui.AlManos, "Nadie tiene la mano levantada.")
			return
		end
		for i, mano in ipairs(self.manos) do
			local id = mano.UserId
			self:_Fila(self.ui.AlManos, "✋  " .. tostring(mano.Nombre), i, {
				{ Texto = "Invitar al tablero", Estilo = "Primario", Ancho = 170, Desactivado = not (enSesion and enClase), Accion = function()
					self:_Invitar(id, mano.Nombre)
				end },
			}, Colores.Azul)
		end
	end)
	if self.ui.TituloManos then
		self.ui.TituloManos.Text = "Manos levantadas (" .. #self.manos .. ")"
	end

	local ocupacion = self.ocupacion or { Sentados = {}, DePie = {} }
	local function rellenar(marco, lista, titulo, etiqueta)
		if titulo then
			titulo.Text = etiqueta .. " (" .. #lista .. ")"
		end
		self:_Rehacer(marco, function()
			if #lista == 0 then
				textoVacio(marco, "Nadie.")
				return
			end
			for i, alumno in ipairs(lista) do
				local id = alumno.UserId
				local nombre = alumno.Nombre
				self:_Fila(marco, tostring(nombre), i, {
					{ Texto = "Ver cuaderno", Ancho = 130, Desactivado = not enSesion, Accion = function()
						self:_VerCuadernoDe(id, nombre)
					end },
					{ Texto = "Invitar", Ancho = 100, Desactivado = not (enSesion and enClase), Accion = function()
						self:_Invitar(id, nombre)
					end },
				})
			end
		end)
	end
	rellenar(self.ui.AlSentados, ocupacion.Sentados or {}, self.ui.TituloSentados, "Sentados")
	rellenar(self.ui.AlDePie, ocupacion.DePie or {}, self.ui.TituloDePie, "De pie")
end

---------------------------------------------------------------------------------------------------
-- Refresco general
---------------------------------------------------------------------------------------------------
function ClassroomController:_RefrescarTodo()
	if not self.ui or not self.ui.Info or self.ui.Info.Parent == nil then
		return
	end
	local enClase, motivo = self:_EnClase()
	local bannerVisible = (not enClase) and self.modo ~= "Personal"
	if self.ui.Banner.Visible ~= bannerVisible then
		self.ui.Banner.Visible = bannerVisible
		self:_Reubicar()
	end
	self.ui.Banner.Text = motivo or ""

	-- Título e información de cabecera.
	if self.ui.Titulo then
		if self.modo == "Personal" then
			self.ui.Titulo.Text = "Mi cuaderno"
		elseif self.sala then
			self.ui.Titulo.Text = "Aula " .. self.sala .. " · " .. nombreAula(self.sala)
		else
			self.ui.Titulo.Text = "Aula"
		end
	end
	self.ui.Info.Text = self:_TextoInfo()

	if self.modo == "Docente" then
		self:_RefrescarDocente(enClase)
	elseif self.modo == "Estudiante" then
		self:_RefrescarAlumno(enClase)
	end
	self:_RefrescarEstadoCuaderno()
	self:_RefrescarTemporizadores()
end

function ClassroomController:_TextoInfo()
	if self.modo == "Personal" then
		return "Tus apuntes se guardan en tu perfil."
	end
	if not self.sala then
		return "No tienes un aula asignada y no estás en ninguna aula."
	end
	local partes = {}
	if self.aulaActual == self.sala then
		table.insert(partes, "Estás en el aula")
	elseif self.aulaActual then
		table.insert(partes, "Estás en " .. self.aulaActual .. " (no es tu aula)")
	else
		table.insert(partes, "Fuera del aula")
	end
	local estado = self.estado
	if estado and estado.SesionAbierta then
		local clase = "Clase abierta"
		if estado.NombreMateria then
			clase = clase .. " de " .. estado.NombreMateria
		end
		if estado.Docente and estado.DocenteUserId ~= player.UserId then
			clase = clase .. " con " .. estado.Docente
		end
		table.insert(partes, clase)
		if typeof(estado.Tema) == "string" and estado.Tema ~= "" then
			table.insert(partes, "Tema: " .. estado.Tema)
		end
	elseif estado then
		table.insert(partes, "Sin clase en curso")
	else
		table.insert(partes, "Consultando…")
	end
	return table.concat(partes, " · ")
end

function ClassroomController:_RefrescarDocente(enClase)
	local estado = self.estado
	local propia = self:_SoyDocenteDeSesion()
	local otraPersona = estado and estado.SesionAbierta and not propia
	if self.ui.SesAula then
		self.ui.SesAula.Text = self.sala and ("Aula: " .. self.sala .. " — " .. nombreAula(self.sala)) or "Aula: entra en tu aula para dirigir la clase."
	end
	if self.ui.SesEstado then
		if propia then
			local presentes = self.ocupacion and tonumber(self.ocupacion.Total) or 0
			self.ui.SesEstado.Text = string.format("Sesión abierta desde las %s · %d estudiante(s) en el aula%s",
				horaLocal(estado.StartedAt), presentes, estado.NombreMateria and (" · " .. estado.NombreMateria) or "")
			self.ui.SesEstado.TextColor3 = Colores.Verde
		elseif otraPersona then
			self.ui.SesEstado.Text = "Esta aula tiene una sesión abierta por " .. tostring(estado.Docente) .. "."
			self.ui.SesEstado.TextColor3 = Colores.Amarillo
		else
			self.ui.SesEstado.Text = "Sesión cerrada."
			self.ui.SesEstado.TextColor3 = Colores.TextoSecundario
		end
	end
	local puedeAbrir = (not propia) and (not otraPersona) and enClase and self.sala ~= nil
	UIBuilder.Habilitar(self.ui.BotonAbrirSesion, puedeAbrir)
	UIBuilder.Habilitar(self.ui.BotonCerrarSesion, propia)
	UIBuilder.Habilitar(self.ui.BotonTema, propia)
	UIBuilder.Habilitar(self.ui.BotonAviso, propia)
	UIBuilder.Habilitar(self.ui.BotonTableroDocente, self.sala ~= nil)
	UIBuilder.Habilitar(self.ui.BotonCrear, propia and enClase)
	local act = self.actividadDocente
	UIBuilder.Habilitar(self.ui.BotonCerrarAct, propia and act ~= nil and act.Estado == "Abierta")
	UIBuilder.Habilitar(self.ui.BotonPublicar, propia and act ~= nil)
	UIBuilder.Habilitar(self.ui.BotonAsistencia, propia)
	UIBuilder.Habilitar(self.ui.BotonRevocar, propia and (self.turno ~= nil or self.invitacionDocente ~= nil))
	if self.ui.DocActInfo then
		if act then
			self.ui.DocActInfo.Text = string.format("%s\n%s · %d respuesta(s)", tostring(act.Prompt),
				act.Estado == "Abierta" and "Abierta" or "Cerrada", tonumber(act.Respuestas) or #self.respuestas)
		else
			self.ui.DocActInfo.Text = "Ninguna."
		end
	end
	if self.ui.AlAsistencia then
		if self.asistencia then
			self.ui.AlAsistencia.Text = string.format("Última asistencia: %d presente(s) de %d asiento(s).",
				tonumber(self.asistencia.Total) or 0, tonumber(self.asistencia.Capacidad) or 0)
		else
			self.ui.AlAsistencia.Text = "Pulsa «Tomar asistencia» para registrar a los presentes."
		end
	end
	self:_RenderResumen(self.ui.DocResumen, self.resumen)
	self:_RenderRespuestas()
	self:_RenderAlumnos()
end

function ClassroomController:_RefrescarAlumno(enClase)
	local estado = self.estado
	local abierta = self:_SesionAbierta()
	local presente = self:_Presente()
	local act = self.actividad

	-- Actividad
	if self.ui.ActPregunta then
		if act then
			self.ui.ActPregunta.Text = tostring(act.Prompt)
		elseif abierta then
			self.ui.ActPregunta.Text = "No hay ninguna actividad activa. Espera a que el docente publique una."
		else
			self.ui.ActPregunta.Text = "No hay una clase abierta en esta aula."
		end
	end
	local esTexto = act ~= nil and act.Type == "Texto"
	local puedeResponder = act ~= nil and act.Estado == "Abierta" and self.miRespuesta == nil and enClase and presente
		and ahoraServidor() <= (tonumber(act.DueAt) or 0) and not self.enviandoRespuesta
	if self.ui.EntradaRespuesta then
		self.ui.EntradaRespuesta.Visible = esTexto
		self.ui.EntradaRespuesta.TextEditable = puedeResponder
	end
	if self.ui.BotonResponder then
		self.ui.BotonResponder.Visible = esTexto
		UIBuilder.Habilitar(self.ui.BotonResponder, puedeResponder)
	end
	if self.ui.ActEstado then
		if self.miRespuesta then
			self.ui.ActEstado.Text = "Respuesta enviada ✓  (" .. tostring(self.miRespuesta.Respuesta or "") .. ")"
			self.ui.ActEstado.TextColor3 = Colores.Verde
		elseif act and not presente then
			self.ui.ActEstado.Text = "Debes estar dentro del aula para responder."
			self.ui.ActEstado.TextColor3 = Colores.Amarillo
		elseif act and act.Estado ~= "Abierta" then
			self.ui.ActEstado.Text = "La actividad está cerrada."
			self.ui.ActEstado.TextColor3 = Colores.TextoSecundario
		else
			self.ui.ActEstado.Text = ""
		end
	end
	self:_RenderOpciones()
	self:_RenderResultados()
	self:_RenderResumen(self.ui.ActResumen, self.resumen)

	-- Clase
	if self.ui.ClaseInfo then
		if abierta then
			self.ui.ClaseInfo.Text = string.format("Docente: %s%s", tostring(estado.Docente or "—"),
				estado.NombreMateria and ("\nMateria: " .. estado.NombreMateria) or "")
		elseif self.sala then
			self.ui.ClaseInfo.Text = "No hay una clase abierta en " .. self.sala .. "."
		else
			self.ui.ClaseInfo.Text = "No tienes un aula asignada."
		end
	end
	if self.ui.ClaseTema then
		local tema = abierta and estado.Tema or nil
		self.ui.ClaseTema.Text = (typeof(tema) == "string" and tema ~= "") and ("Tema: " .. tema) or ""
		self.ui.ClaseTema.Visible = self.ui.ClaseTema.Text ~= ""
	end
	if self.ui.BotonMano then
		UIBuilder.TextoBoton(self.ui.BotonMano, self.mano and "✋  Bajar la mano" or "✋  Levantar la mano")
		UIBuilder.Habilitar(self.ui.BotonMano, abierta and presente and enClase)
	end
	UIBuilder.Habilitar(self.ui.BotonTableroAlumno, self.sala ~= nil)
	if self.ui.InvCaja then
		self.ui.InvCaja.Visible = self.invitacion ~= nil
		UIBuilder.Habilitar(self.ui.BotonAceptar, self.invitacion ~= nil and enClase and presente)
	end
	if self.ui.ClaseAsistencia then
		self.ui.ClaseAsistencia.Text = self.asistenciaPropia and "Asistencia registrada: presente ✓" or ""
		self.ui.ClaseAsistencia.Visible = self.asistenciaPropia
	end
	if self.ui.ClaseAviso then
		local aviso = ""
		if self.sala and not presente and abierta then
			aviso = "Dirígete al aula " .. self.sala .. " para participar."
		end
		self.ui.ClaseAviso.Text = aviso
		self.ui.ClaseAviso.Visible = aviso ~= ""
	end
end

-- Temporizadores (actividad, invitación, turno). Se llama desde el bucle de 1 Hz.
function ClassroomController:_RefrescarTemporizadores()
	local ahora = ahoraServidor()
	local act = self.actividad
	if self.ui.ActTiempo then
		if act and act.Estado == "Abierta" then
			local restante = (tonumber(act.DueAt) or ahora) - ahora
			if restante > 0 then
				self.ui.ActTiempo.Text = "Tiempo restante: " .. Format.Tiempo(restante)
			else
				self.ui.ActTiempo.Text = "Tiempo agotado."
				if not self._agotadoRender then
					self._agotadoRender = true
					self:_RenderOpciones()
					if self.ui.BotonResponder then
						UIBuilder.Habilitar(self.ui.BotonResponder, false)
					end
				end
			end
		else
			self.ui.ActTiempo.Text = ""
			self._agotadoRender = false
		end
	end
	local actDoc = self.actividadDocente
	if self.ui.DocActTiempo then
		if actDoc and actDoc.Estado == "Abierta" then
			self.ui.DocActTiempo.Text = "Tiempo restante: " .. Format.Tiempo((tonumber(actDoc.DueAt) or ahora) - ahora)
		else
			self.ui.DocActTiempo.Text = ""
		end
	end
	if self.ui.InvTexto and self.invitacion then
		local restante = (tonumber(self.invitacion.Expira) or ahora) - ahora
		if restante <= 0 then
			self.invitacion = nil
			if self.ui.InvCaja then
				self.ui.InvCaja.Visible = false
			end
		else
			self.ui.InvTexto.Text = string.format("%s te invita al tablero. Responde en %d s.",
				tostring(self.invitacion.Docente or "El docente"), math.ceil(restante))
		end
	end
	local textoTurno = ""
	if self.turno and self.turno.Hasta then
		local restante = self.turno.Hasta - ahora
		if restante > 0 then
			local quien = self.turno.UserId == player.UserId and "Tú" or tostring(self.turno.Nombre)
			textoTurno = "Turno del tablero: " .. quien .. " (" .. Format.Tiempo(restante) .. ")"
		else
			self.turno = nil
		end
	end
	if textoTurno == "" and self.invitacionDocente then
		local restante = (tonumber(self.invitacionDocente.Expira) or ahora) - ahora
		if restante > 0 then
			textoTurno = string.format("Invitación pendiente: %s (%d s)", tostring(self.invitacionDocente.Nombre), math.ceil(restante))
		else
			self.invitacionDocente = nil
		end
	end
	if self.ui.ClaseTurno then
		self.ui.ClaseTurno.Text = textoTurno
		self.ui.ClaseTurno.Visible = textoTurno ~= ""
	end
	if self.ui.AlTurno then
		self.ui.AlTurno.Text = textoTurno ~= "" and textoTurno or "Tablero: sin turno de estudiantes."
	end
end

function ClassroomController:_RefrescarFormularioActividad()
	if not self.ui.SelectorTipo or not self.ui.MarcoOpciones then
		return
	end
	self.ui.MarcoOpciones.Visible = self.ui.SelectorTipo:Valor() == "Opciones"
end

---------------------------------------------------------------------------------------------------
-- Acciones del docente
---------------------------------------------------------------------------------------------------
function ClassroomController:_AbrirSesion()
	local sala = self.aulaActual or self.sala
	if not sala then
		self:_Notificar("Entra en tu aula para abrir la sesión.", "aviso")
		return
	end
	local tema = self.ui.EntradaTema and recortar(self.ui.EntradaTema.Text) or ""
	local datos = {}
	if tema ~= "" then
		datos.Tema = tema
	end
	self:_Accion("AbrirSesion", datos, function(d)
		self:_Notificar("Sesión abierta en " .. tostring(d.RoomId or sala) .. ".", "exito")
		self:_AplicarEstado(d)
	end, { Sala = sala })
end

function ClassroomController:_CrearActividad()
	local tipo = self.ui.SelectorTipo:Valor()
	local pregunta = recortar(self.ui.EntradaPregunta.Text)
	if pregunta == "" then
		self:_Notificar("Escribe la pregunta de la actividad.", "aviso")
		return
	end
	local datos = { Type = tipo, Prompt = pregunta, Segundos = self.ui.SelectorTiempo:Valor() }
	if tipo == "Opciones" then
		local opciones = {}
		local mapa = {}
		for i, entrada in ipairs(self.ui.EntradasOpcion) do
			local texto = recortar(entrada.Text)
			if texto ~= "" then
				table.insert(opciones, texto)
				mapa[i] = #opciones
			end
		end
		if #opciones < 2 then
			self:_Notificar("Escribe al menos dos opciones.", "aviso")
			return
		end
		datos.Options = opciones
		local correcta = self.ui.SelectorCorrecta:Valor()
		if correcta and correcta > 0 then
			if not mapa[correcta] then
				self:_Notificar("La opción marcada como correcta está vacía.", "aviso")
				return
			end
			datos.Correcta = mapa[correcta]
		end
	end
	UIBuilder.Habilitar(self.ui.BotonCrear, false)
	self:_Accion("CrearActividad", datos, function(d)
		if typeof(d.Actividad) == "table" then
			self.actividadDocente = d.Actividad
		end
		self.respuestas = {}
		self.ui.EntradaPregunta.Text = ""
		for _, entrada in ipairs(self.ui.EntradasOpcion) do
			entrada.Text = ""
		end
		self.ui.SelectorCorrecta:Fijar(0, true)
	end)
end

function ClassroomController:_Invitar(userId, nombre)
	self:_Accion("InvitarTablero", { ObjetivoUserId = userId }, function(d)
		self.invitacionDocente = { UserId = userId, Nombre = d.Invitado or nombre, Expira = d.Expira }
		self:_Notificar("Invitación al tablero enviada a " .. tostring(d.Invitado or nombre) .. ".", "exito")
	end)
end

function ClassroomController:_AbrirCalificar(registro)
	local actividadId = self.actividadDocente and self.actividadDocente.Id or nil
	local selector, entrada = nil, nil
	UIBuilder.Modal("Calificar a " .. tostring(registro.Nombre), function(cuerpo)
		UIBuilder.Texto(cuerpo, "Respuesta: " .. tostring(registro.Respuesta or "—"), { LayoutOrder = 1, Tamano = "Pequeno", Color = Colores.TextoSecundario })
		local opciones = {}
		for i = 0, 10 do
			table.insert(opciones, { Valor = i, Texto = tostring(i) })
		end
		local inicial = tonumber(registro.Puntos)
		if inicial then
			inicial = math.floor(inicial + 0.5)
		elseif registro.Correcta == true then
			inicial = 10
		elseif registro.Correcta == false then
			inicial = 0
		else
			inicial = 7
		end
		selector = UIBuilder.Selector(cuerpo, "Nota (0–10)", opciones, inicial, nil, { LayoutOrder = 2, AnchoGrupo = 170 })
		entrada = UIBuilder.Entrada(cuerpo, "Comentario privado (opcional, máx. 120)", {
			Max = 120, LayoutOrder = 3, Texto = typeof(registro.Comentario) == "string" and registro.Comentario or "",
		})
	end, {
		{ Texto = "Cancelar", Estilo = "Secundario" },
		{ Texto = "Guardar nota", Estilo = "Primario", Accion = function()
			local datos = { ActividadId = actividadId, ObjetivoUserId = registro.UserId, Puntos = selector and selector:Valor() or 0 }
			local comentario = entrada and recortar(entrada.Text) or ""
			if comentario ~= "" then
				datos.Comentario = comentario
			end
			self:_Accion("Calificar", datos, function(d)
				registro.Puntos = d.Puntos
				registro.Comentario = d.Comentario
				self:_Notificar("Nota enviada en privado a " .. tostring(registro.Nombre) .. ".", "exito")
			end)
		end },
	}, { Ancho = 400 })
end

function ClassroomController:_VerCuadernoDe(userId, nombre)
	task.spawn(function()
		local ok, respuesta = Net.Invocar("NotebookUpdate", { Accion = "Ver", ObjetivoUserId = userId })
		if not ok then
			self:_Notificar(mensajeDe(respuesta), "error")
			return
		end
		local d = respuesta.datos or {}
		UIBuilder.Modal("Cuaderno de " .. tostring(d.Nombre or nombre), function(cuerpo)
			local paginas = typeof(d.Paginas) == "table" and d.Paginas or {}
			if #paginas == 0 then
				UIBuilder.Texto(cuerpo, "Este estudiante no ha compartido páginas.", { LayoutOrder = 1, Color = Colores.TextoSecundario })
				return
			end
			local lista = UIBuilder.Lista(cuerpo, { Espaciado = 6 })
			lista.LayoutOrder = 1
			lista.Size = UDim2.new(1, 0, 0, math.min(360, math.max(160, UIBuilder.AltoUI() * 0.5)))
			for i, pagina in ipairs(paginas) do
				self:_Fila(lista, string.format("Página %d · %s\n%s", tonumber(pagina.Pagina) or i,
					TimetableDefinitions.NombreMateria(pagina.Materia), tostring(pagina.Texto or "")), i)
			end
		end, { { Texto = "Cerrar", Estilo = "Primario" } }, { Ancho = 520 })
	end)
end

---------------------------------------------------------------------------------------------------
-- Acciones del estudiante
---------------------------------------------------------------------------------------------------
function ClassroomController:_ResponderOpcion(indice)
	local act = self.actividad
	if not act or self.miRespuesta or self.enviandoRespuesta then
		return
	end
	self.enviandoRespuesta = true
	self:_Accion("Responder", { ActividadId = act.Id, Indice = indice }, function(d)
		self.miRespuesta = { Indice = indice, Respuesta = act.Options and act.Options[indice] or "", T = d.T }
		self.enviandoRespuesta = false
		self:_Notificar("Respuesta enviada.", "exito", 3)
		self:_RenderOpciones()
	end, { AlFallar = function()
		self.enviandoRespuesta = false
	end })
end

function ClassroomController:_ResponderTexto()
	local act = self.actividad
	if not act or self.miRespuesta or self.enviandoRespuesta or not self.ui.EntradaRespuesta then
		return
	end
	local texto = recortar(self.ui.EntradaRespuesta.Text)
	if texto == "" then
		self:_Notificar("Escribe tu respuesta primero.", "aviso")
		return
	end
	self.enviandoRespuesta = true
	self:_Accion("Responder", { ActividadId = act.Id, Respuesta = texto }, function(d)
		self.miRespuesta = { Respuesta = texto, T = d.T }
		self.enviandoRespuesta = false
		self:_Notificar("Respuesta enviada.", "exito", 3)
	end, { AlFallar = function()
		self.enviandoRespuesta = false
	end })
end

function ClassroomController:_AlternarMano()
	local levantar = not self.mano
	self:_Accion("LevantarMano", { Levantar = levantar }, function(d)
		self.mano = d.Levantada == true
		self:_Notificar(self.mano and "Levantaste la mano." or "Bajaste la mano.", "info", 2)
	end)
end

function ClassroomController:_ResponderInvitacion(aceptar)
	if not self.invitacion then
		return
	end
	self:_Accion("AceptarInvitacion", { Aceptar = aceptar }, function(d)
		self.invitacion = nil
		if d.Aceptada then
			self.turno = { UserId = player.UserId, Nombre = player.DisplayName, Hasta = tonumber(d.Hasta) }
		end
	end, { AlFallar = function()
		self.invitacion = nil
	end })
end

---------------------------------------------------------------------------------------------------
-- Cuaderno
---------------------------------------------------------------------------------------------------
function ClassroomController:_HayPendientes()
	return next(self.pendientes) ~= nil
end

-- Página local n (crea las intermedias vacías como hace el servidor al guardar).
function ClassroomController:_PaginaLocal(n)
	if not self.cuaderno then
		return nil
	end
	local paginas = self.cuaderno.Paginas
	while #paginas < n do
		local materia = (self.jornada and TimetableDefinitions.MateriaDe(self.jornada.Estado)) or "MAT"
		table.insert(paginas, { Pagina = #paginas + 1, Materia = materia, Texto = "", Actualizado = 0, Compartida = false })
	end
	return paginas[n]
end

function ClassroomController:_CargarCuaderno()
	if self.cargandoCuaderno then
		return
	end
	self.cargandoCuaderno = true
	self.ultimoIntentoCuaderno = os.clock()
	task.spawn(function()
		local ok, respuesta = Net.Invocar("NotebookUpdate", { Accion = "Cargar" })
		self.cargandoCuaderno = false
		if not ok or typeof(respuesta.datos) ~= "table" then
			-- _Tick reintenta la carga: el aviso no se repite en cada intento.
			if os.clock() - self.ultimoErrorCuaderno > 30 then
				self.ultimoErrorCuaderno = os.clock()
				self:_Notificar(mensajeDe(respuesta), "error")
			end
			return
		end
		local d = respuesta.datos
		local paginas = {}
		for i, pagina in ipairs(d.Paginas or {}) do
			paginas[i] = {
				Pagina = i, Materia = pagina.Materia or "MAT", Texto = tostring(pagina.Texto or ""),
				Actualizado = pagina.Actualizado or 0, Compartida = pagina.Compartida == true,
			}
		end
		-- Conserva los borradores locales que aún no se guardaron.
		if self.cuaderno then
			for n in pairs(self.pendientes) do
				local local_ = self.cuaderno.Paginas[n]
				if local_ then
					paginas[n] = local_
				end
			end
		end
		-- Sin huecos: un borrador más allá de las páginas del servidor deja intermedias vacías (como el servidor).
		local ultima = 0
		for n in pairs(paginas) do
			if typeof(n) == "number" and n > ultima then
				ultima = n
			end
		end
		for n = 1, ultima do
			if paginas[n] == nil then
				paginas[n] = { Pagina = n, Materia = "MAT", Texto = "", Actualizado = 0, Compartida = false }
			end
		end
		self.cuaderno = { Titulo = d.Titulo or "Mi cuaderno", Paginas = paginas }
		if tonumber(d.MaxPaginas) then
			self.MaxPaginas = tonumber(d.MaxPaginas)
		end
		if tonumber(d.EsperaGuardado) and d.EsperaGuardado > 0 then
			self.ultimoGuardado = os.clock() - self.MinIntervaloGuardado + d.EsperaGuardado
		end
		if self.paginaActual > self.MaxPaginas then
			self.paginaActual = 1
		end
		self:_MostrarPaginaCuaderno()
	end)
end

function ClassroomController:_MostrarPaginaCuaderno()
	if not self.cuaderno or not self.ui.EntradaCuaderno then
		return
	end
	local pagina = self:_PaginaLocal(self.paginaActual)
	self._cargandoTexto = true
	self.ui.EntradaCuaderno.Text = pagina.Texto or ""
	if self.ui.SelectorPagina then
		self.ui.SelectorPagina:Fijar(self.paginaActual, true)
	end
	if self.ui.SelectorMateria and TimetableDefinitions.ExisteMateria(pagina.Materia) then
		self.ui.SelectorMateria:Fijar(pagina.Materia, true)
	end
	self._cargandoTexto = false
	if self.ui.CuadernoTitulo then
		self.ui.CuadernoTitulo.Text = tostring(self.cuaderno.Titulo or "Mi cuaderno")
	end
	self:_RefrescarEstadoCuaderno()
end

function ClassroomController:_CambiarPagina(n)
	if not self.cuaderno then
		return
	end
	if self.pendientes[self.paginaActual] then
		self.guardarPronto = true
	end
	self.paginaActual = math.clamp(math.floor(tonumber(n) or 1), 1, self.MaxPaginas)
	self:_MostrarPaginaCuaderno()
end

function ClassroomController:_RefrescarEstadoCuaderno()
	if not self.ui.EstadoGuardado or self.ui.EstadoGuardado.Parent == nil then
		return
	end
	-- Sin cuaderno cargado no se puede escribir: lo tecleado no quedaría pendiente y la carga lo sustituiría.
	if self.ui.EntradaCuaderno then
		self.ui.EntradaCuaderno.TextEditable = self.cuaderno ~= nil
	end
	local pagina = self.cuaderno and self.cuaderno.Paginas[self.paginaActual] or nil
	if self.ui.ContadorCuaderno then
		local n = pagina and (utf8.len(pagina.Texto or "") or 0) or 0
		self.ui.ContadorCuaderno.Text = n .. " / " .. self.MaxCaracteres
	end
	local texto, color
	if not self.cuaderno then
		texto, color = "Cargando…", Colores.TextoSecundario
	elseif self.guardando then
		texto, color = "Guardando…", Colores.TextoSecundario
	elseif self:_HayPendientes() then
		texto, color = "Sin guardar", Colores.Amarillo
	else
		texto, color = "Guardado ✓", Colores.Verde
	end
	if pagina and pagina.Compartida then
		texto = texto .. " · Compartida"
	end
	self.ui.EstadoGuardado.Text = texto
	self.ui.EstadoGuardado.TextColor3 = color
	if self.ui.BotonCompartir then
		UIBuilder.TextoBoton(self.ui.BotonCompartir, (pagina and pagina.Compartida) and "Dejar de compartir" or "Compartir")
		UIBuilder.Habilitar(self.ui.BotonCompartir, self.cuaderno ~= nil)
	end
	UIBuilder.Habilitar(self.ui.BotonGuardar, self.cuaderno ~= nil)
	UIBuilder.Habilitar(self.ui.BotonVaciar, self.cuaderno ~= nil)
end

-- Cola de guardado: respeta el mínimo del servidor (1 guardado / 10 s) y el autoguardado periódico.
function ClassroomController:_ProcesarGuardado(forzar)
	if self.guardando or not self.cuaderno or not self:_HayPendientes() then
		return
	end
	local ahora = os.clock()
	if ahora - self.ultimoGuardado < self.MinIntervaloGuardado + 0.25 then
		return
	end
	if not forzar and not self.guardarPronto then
		if ahora - self.ultimoAutoguardado < self.AutoguardadoSeg then
			return
		end
	end
	local numero = nil
	if self.pendientes[self.paginaActual] then
		numero = self.paginaActual
	else
		for n in pairs(self.pendientes) do
			if numero == nil or n < numero then
				numero = n
			end
		end
	end
	if numero then
		self.ultimoAutoguardado = ahora
		self:_Guardar(numero)
	end
end

function ClassroomController:_Guardar(numero)
	local pagina = self.cuaderno and self.cuaderno.Paginas[numero]
	if not pagina then
		self.pendientes[numero] = nil
		return
	end
	self.guardando = true
	self:_RefrescarEstadoCuaderno()
	local textoEnviado = pagina.Texto or ""
	local materiaEnviada = pagina.Materia
	task.spawn(function()
		local datos = { Accion = "Guardar", Pagina = numero, Texto = textoEnviado }
		if TimetableDefinitions.ExisteMateria(materiaEnviada) then
			datos.Materia = materiaEnviada
		end
		local ok, respuesta = Net.Invocar("NotebookUpdate", datos)
		self.guardando = false
		if ok then
			self.ultimoGuardado = os.clock()
			local d = respuesta.datos or {}
			pagina.Actualizado = d.Actualizado or pagina.Actualizado
			pagina.Compartida = d.Compartida == true
			if pagina.Texto == textoEnviado and pagina.Materia == materiaEnviada then
				self.pendientes[numero] = nil
			end
			if not self:_HayPendientes() then
				self.guardarPronto = false
			end
			if typeof(d.Aviso) == "string" then
				self:_Notificar(d.Aviso, "aviso")
			end
		else
			local reintentar = typeof(respuesta.datos) == "table" and tonumber(respuesta.datos.Reintentar) or nil
			if reintentar then
				self.ultimoGuardado = os.clock() - self.MinIntervaloGuardado + reintentar
			else
				self.ultimoGuardado = os.clock()
				if os.clock() - self.ultimoErrorGuardado > 30 then
					self.ultimoErrorGuardado = os.clock()
					self:_Notificar("No se pudo guardar el cuaderno: " .. mensajeDe(respuesta), "error")
				end
			end
		end
		self:_RefrescarEstadoCuaderno()
	end)
end

function ClassroomController:_GuardarAhora()
	if not self.cuaderno then
		return
	end
	if not self:_HayPendientes() then
		self:_Notificar("No hay cambios por guardar.", "info", 2)
		return
	end
	self.guardarPronto = true
	local restante = self.MinIntervaloGuardado + 0.25 - (os.clock() - self.ultimoGuardado)
	if restante > 0 and not self.guardando then
		self:_Notificar(string.format("Se guardará en %d s (máximo un guardado cada %d s).", math.ceil(restante), self.MinIntervaloGuardado), "info", 3)
	end
	self:_ProcesarGuardado(true)
end

function ClassroomController:_Compartir()
	if not self.cuaderno then
		return
	end
	local numero = self.paginaActual
	if self.pendientes[numero] then
		self.guardarPronto = true
		self:_ProcesarGuardado(true)
		self:_Notificar("Guarda la página antes de compartirla (se guardará en unos segundos).", "aviso")
		return
	end
	task.spawn(function()
		local ok, respuesta = Net.Invocar("NotebookUpdate", { Accion = "Compartir", Pagina = numero })
		if not ok then
			self:_Notificar(mensajeDe(respuesta), "error")
			return
		end
		local d = respuesta.datos or {}
		local pagina = self.cuaderno and self.cuaderno.Paginas[numero]
		if pagina then
			pagina.Compartida = d.Compartida == true
		end
		self:_Notificar(d.Compartida and "Página compartida con tu docente." or "La página ya no está compartida.", "exito", 3)
		self:_RefrescarEstadoCuaderno()
	end)
end

function ClassroomController:_ConfirmarVaciar()
	if not self.cuaderno then
		return
	end
	local numero = self.paginaActual
	UIBuilder.Confirmar("Vaciar página", "Se borrará el texto de la página " .. numero .. ". Esta acción no se puede deshacer.", function()
		task.spawn(function()
			local ok, respuesta = Net.Invocar("NotebookUpdate", { Accion = "Vaciar", Pagina = numero })
			if not ok then
				self:_Notificar(mensajeDe(respuesta), "error")
				return
			end
			local pagina = self:_PaginaLocal(numero)
			if pagina then
				pagina.Texto = ""
				pagina.Compartida = false
			end
			self.pendientes[numero] = nil
			if numero == self.paginaActual then
				self:_MostrarPaginaCuaderno()
			end
			self:_Notificar("Página vaciada.", "info", 2)
		end)
	end, "Vaciar", "Peligro")
end

return ClassroomController
]=] }
FUENTES["StarterPlayer/StarterPlayerScripts/ColegioRP/Controllers/FoodController"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: StarterPlayer.StarterPlayerScripts.ColegioRP.Controllers.FoodController
	Tipo: ModuleScript
	Panel del comedor gratuito (docs/ARQUITECTURA.md §7): muestra el ESTADO (abierto/cerrado y periodo, raciones,
	lote, menú y el tiempo que falta para el próximo reclamo propio) cuando el jugador está en COCINA, en la fila de
	la ventana de servicio o en los comedores (detección de zona a 1 Hz). El reclamo se hace con el ProximityPrompt
	físico "Reclamar almuerzo" (lo procesa el servidor) o con el botón del panel junto a la ventana de servicio
	(FoodAction "Reclamar"; el servidor valida distancia, periodo, cooldown y raciones). Para el personal de cocina
	añade el panel de cocina: receta activa, pasos, progreso, lote y botones que llaman a FoodAction (IniciarReceta,
	Paso, Entregar, Reponer). Oculta localmente los prompts de las estaciones a quien no tiene permiso de cocina.
	ScreenGui "ColegioRP_Comedor" (DisplayOrder de paneles). Escucha EventoCliente Tipo "Comida".
]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local TIMEOUT = 30
local function esperarHijo(padre, nombre)
	local hijo = nil
	if padre then
		hijo = padre:FindFirstChild(nombre) or padre:WaitForChild(nombre, TIMEOUT)
	end
	if not hijo then
		error("[ColegioRP][FoodController] No apareció '" .. tostring(nombre) .. "' en " .. TIMEOUT .. " s")
	end
	return hijo
end

local RP = esperarHijo(ReplicatedStorage, "ColegioRP")
local Shared = esperarHijo(RP, "Shared")
local Util = esperarHijo(Shared, "Util")
local Config = require(esperarHijo(Shared, "Config"))
local UITheme = require(esperarHijo(Shared, "UITheme"))
local Catalogs = require(esperarHijo(Shared, "Catalogs"))
local MapaLogico = require(esperarHijo(Shared, "MapaLogico"))
local RoleDefinitions = require(esperarHijo(Shared, "RoleDefinitions"))
local Net = require(esperarHijo(Util, "Net"))
local Maid = require(esperarHijo(Util, "Maid"))
local Format = require(esperarHijo(Util, "Format"))
local Zones = require(esperarHijo(Util, "Zones"))
local UIBuilder = require(esperarHijo(esperarHijo(script.Parent.Parent, "UI"), "UIBuilder"))

local LocalPlayer = Players.LocalPlayer
local Colores = UITheme.Colores

local FoodController = {}
FoodController.Nombre = "FoodController"
-- Este controlador atiende su propio evento "AbrirPanel" (InteractionController no lo delega).
FoodController.ManejaAperturaPropia = true

---------------------------------------------------------------------------------------------------
-- Constantes
---------------------------------------------------------------------------------------------------
local LOG = "[ColegioRP][FoodController] "
local ORDEN_PANTALLA = (UITheme.Capas and UITheme.Capas.Panel) or 50
local ZONA_COCINA = "COCINA"
local ZONAS_COMEDOR = { COCINA = true, COMEDOR = true, COMEDOR_COCINA = true }
local ACCION_HUD = "Comedor"
local CARPETA_MAPA = (Config.Nombres and Config.Nombres.CarpetaMapa) or "ColegioRP_Mapa"
local CARPETA_PROPIA = "ColegioRP_Comedor"
local INTERVALO_ZONA = 1
local INTERVALO_UI = 0.2
local CONSULTA_MIN_SEG = 5
local ANCHO_PANEL = 330
local ALTO_ESTADO = 340 -- incluye el botón «Reclamar almuerzo»
local ALTO_COCINA = 560
local MARGEN_BOTONES_HUD = 176 -- alto aproximado de la columna de botones del HUD (esquina superior derecha)
local RACIONES_POR_LOTE = math.max(1, math.floor(tonumber(Config.Comedor and Config.Comedor.RacionesPorLote) or 40))

local DISTANCIA_ESTACION_ZONA = 14 -- cerca de una estación se considera "en la cocina" (algunas quedan fuera de la caja)
local FILA = nil
local PUNTOS_ESTACION = {}
do
	local cocina = MapaLogico.Zonas and MapaLogico.Zonas[ZONA_COCINA]
	if cocina and typeof(cocina.FilaEstudiantes) == "table" and typeof(cocina.FilaEstudiantes.Centro) == "Vector3" and typeof(cocina.FilaEstudiantes.Tamano) == "Vector3" then
		FILA = cocina.FilaEstudiantes
	end
	if cocina and typeof(cocina.Estaciones) == "table" then
		for _, punto in pairs(cocina.Estaciones) do
			if typeof(punto) == "Vector3" then
				table.insert(PUNTOS_ESTACION, punto)
			end
		end
	end
end

local function hex(color)
	return string.format("#%02X%02X%02X", math.floor(color.R * 255 + 0.5), math.floor(color.G * 255 + 0.5), math.floor(color.B * 255 + 0.5))
end
local HEX_VERDE = hex(Colores.Verde)
local HEX_ROJO = hex(Colores.Rojo)
local HEX_AMARILLO = hex(Colores.Amarillo)
local HEX_APAGADO = hex(Colores.TextoApagado)

---------------------------------------------------------------------------------------------------
-- Estado
---------------------------------------------------------------------------------------------------
local activo = false
local abierto = false
local cerradoPorUsuario = false
local forzarCocina = false
local estado = nil -- último estado del comedor (servidor)
local personal = { ProximoReclamo = 0 }
local pasoActual = nil -- { Estacion, NombreEstacion, FinServidor, Duracion }
local zonaActual = nil -- "COCINA" | "COMEDOR" | "COMEDOR_COCINA" | "FILA" | nil
local pidiendo = false
local ultimaConsulta = -math.huge
local maid = Maid.new()
local maidPanel = Maid.new()
local maidPrompts = Maid.new()
local carpetasVigiladas = {}
local ui = {}

---------------------------------------------------------------------------------------------------
-- Utilidades
---------------------------------------------------------------------------------------------------
local function obtenerControlador(nombre)
	local registro = FoodController.registro
	if typeof(registro) ~= "table" or typeof(registro.Get) ~= "function" then
		return nil
	end
	local ok, controlador = pcall(registro.Get, nombre)
	if ok and typeof(controlador) == "table" then
		return controlador
	end
	return nil
end

local function notificar(texto, nivel, duracion)
	local Notif = obtenerControlador("NotificationController")
	if Notif and typeof(Notif.Notificar) == "function" then
		pcall(Notif.Notificar, Notif, texto, nivel or "info", duracion)
	else
		print(LOG .. tostring(texto))
	end
end

local function ahoraServidor()
	local ok, t = pcall(function()
		return workspace:GetServerTimeNow()
	end)
	if ok and typeof(t) == "number" then
		return t
	end
	return os.time()
end

local function tiene(permiso)
	return RoleDefinitions.Tiene(LocalPlayer:GetAttribute("Cargo"), permiso) == true
end

local function esCocina()
	return tiene("cocina.operar")
end

local function puedeReponer()
	return tiene("comedor.reponer")
end

local function nombreEstacion(nombre)
	return (Catalogs.Estaciones and Catalogs.Estaciones[nombre]) or tostring(nombre or "")
end

local function posicionPropia()
	local personaje = LocalPlayer.Character
	local raiz = personaje and (personaje:FindFirstChild("HumanoidRootPart") or personaje.PrimaryPart)
	if raiz and raiz:IsA("BasePart") then
		return raiz.Position
	end
	return nil
end

-- Zona relevante para el comedor en la que está el jugador (o nil).
local function detectarZona()
	local pos = posicionPropia()
	if not pos then
		return nil
	end
	if Zones.Contiene(ZONA_COCINA, pos) then
		return ZONA_COCINA
	end
	for _, punto in ipairs(PUNTOS_ESTACION) do
		if (pos - punto).Magnitude <= DISTANCIA_ESTACION_ZONA then
			return ZONA_COCINA
		end
	end
	if FILA then
		local d = pos - FILA.Centro
		if math.abs(d.X) <= FILA.Tamano.X / 2 and math.abs(d.Y) <= FILA.Tamano.Y / 2 and math.abs(d.Z) <= FILA.Tamano.Z / 2 then
			return "FILA"
		end
	end
	local ok, zona = pcall(Zones.ZonaDe, pos)
	if ok and typeof(zona) == "table" and ZONAS_COMEDOR[zona.Id] then
		return zona.Id
	end
	return nil
end

local function mostrarCocina()
	if not (esCocina() or puedeReponer()) then
		return false
	end
	return zonaActual == ZONA_COCINA or forzarCocina
end

---------------------------------------------------------------------------------------------------
-- Prompts de las estaciones: se ocultan localmente a quien no puede usarlos (el servidor valida igual)
---------------------------------------------------------------------------------------------------
local function aplicarPrompt(prompt)
	if typeof(prompt) ~= "Instance" or not prompt:IsA("ProximityPrompt") then
		return
	end
	if prompt:GetAttribute("RPTipo") ~= "Cocina" then
		return
	end
	local permitido = esCocina()
	if prompt:GetAttribute("RPId") == "Reposicion" then
		permitido = puedeReponer()
	end
	pcall(function()
		prompt.Enabled = permitido
	end)
end

local function revisarCarpeta(carpeta)
	for _, d in ipairs(carpeta:GetDescendants()) do
		if d:IsA("ProximityPrompt") then
			aplicarPrompt(d)
		end
	end
end

local function vigilarCarpeta(carpeta)
	if typeof(carpeta) ~= "Instance" or carpetasVigiladas[carpeta] then
		return
	end
	carpetasVigiladas[carpeta] = true
	maidPrompts:GiveTask(carpeta.DescendantAdded:Connect(function(d)
		if d:IsA("ProximityPrompt") then
			task.defer(aplicarPrompt, d)
		end
	end))
	maidPrompts:GiveTask(carpeta.AncestryChanged:Connect(function(_, padre)
		if padre == nil then
			carpetasVigiladas[carpeta] = nil
		end
	end))
	revisarCarpeta(carpeta)
end

local function buscarCarpetas()
	local mapa = workspace:FindFirstChild(CARPETA_MAPA)
	if mapa then
		local cocina = mapa:FindFirstChild("Cocina")
		if cocina then
			vigilarCarpeta(cocina)
		end
		if not carpetasVigiladas[mapa] then
			carpetasVigiladas[mapa] = true
			maidPrompts:GiveTask(mapa.ChildAdded:Connect(function(hijo)
				if hijo.Name == "Cocina" then
					task.defer(vigilarCarpeta, hijo)
				end
			end))
			maidPrompts:GiveTask(mapa.AncestryChanged:Connect(function(_, padre)
				if padre == nil then
					carpetasVigiladas[mapa] = nil
				end
			end))
		end
	end
	local propia = workspace:FindFirstChild(CARPETA_PROPIA)
	if propia then
		vigilarCarpeta(propia)
	end
end

local function revisarPrompts()
	for carpeta in pairs(carpetasVigiladas) do
		if carpeta.Parent ~= nil and carpeta.Name ~= CARPETA_MAPA then
			revisarCarpeta(carpeta)
		end
	end
end

---------------------------------------------------------------------------------------------------
-- Construcción del panel
---------------------------------------------------------------------------------------------------
local function texto(parent, contenido, orden, props)
	props = props or {}
	props.LayoutOrder = orden
	return UIBuilder.Texto(parent, contenido, props)
end

local function botonAncho(parent, contenido, onClick, orden, estilo, nombre)
	local alto = UIBuilder.AltoBoton()
	local boton = UIBuilder.Boton(parent, contenido, onClick, {
		Estilo = estilo or "Secundario", Alto = alto, LayoutOrder = orden, Nombre = nombre,
		Size = UDim2.new(1, 0, 0, alto),
	})
	return boton
end

local pedir -- declarada más abajo

local function construirUI()
	local gui = UIBuilder.Pantalla("Comedor", ORDEN_PANTALLA)
	ui.Gui = gui
	local contenedor = UIBuilder.Contenedor(gui)
	ui.Contenedor = contenedor
	local panel, lista = UIBuilder.Panel(contenedor, {
		Nombre = "PanelComedor",
		Titulo = "Comedor escolar",
		AlCerrar = function()
			FoodController.Cerrar(true)
		end,
		Scroll = true,
		Espaciado = 6,
		Size = UDim2.new(0, ANCHO_PANEL, 0, ALTO_ESTADO),
		Position = UDim2.new(1, 0, 0, MARGEN_BOTONES_HUD),
		AnchorPoint = Vector2.new(1, 0),
	})
	pcall(function()
		panel.SelectionGroup = true
	end)
	panel.Visible = false
	ui.Panel = panel
	ui.Lista = lista

	ui.Estado = texto(lista, "Cargando el estado del comedor…", 1, { Rico = true, Fuente = "Subtitulo" })
	ui.Raciones = texto(lista, "", 2)
	ui.BarraRaciones = UIBuilder.Barra(lista, 0, { LayoutOrder = 3, Alto = 8, Color = Colores.Verde, Nombre = "BarraRaciones" })
	ui.Lotes = texto(lista, "", 4, { Tamano = "Pequeno", Color = Colores.TextoSecundario })
	ui.Menu = texto(lista, "", 5, { Color = Colores.TextoSecundario })
	ui.Turno = texto(lista, "", 6, { Rico = true, Fuente = "Subtitulo" })
	-- Reclamo desde el panel (solo junto a la ventana de servicio; el servidor vuelve a validarlo todo).
	ui.BotonReclamar = botonAncho(lista, "Reclamar almuerzo", function()
		pedir("Reclamar", nil)
	end, 7, "Exito", "Reclamar")
	ui.Ayuda = texto(lista, "El almuerzo es gratis: acércate a la ventana de servicio de la cocina y usa «Reclamar almuerzo».", 8, {
		Tamano = "Pequeno", Color = Colores.TextoApagado,
	})

	-- Sección de cocina (solo personal con cocina.operar / comedor.reponer).
	local cocina = UIBuilder.Marco(lista, { Nombre = "Cocina", AutoAlto = true, LayoutOrder = 9 })
	UIBuilder.Disposicion(cocina, { Espaciado = 6 })
	ui.Cocina = cocina
	UIBuilder.Separador(cocina, { LayoutOrder = 1 })
	UIBuilder.Subtitulo(cocina, "Cocina", { LayoutOrder = 2, Color = Colores.TextoPrincipal })
	ui.Receta = texto(cocina, "", 3)
	ui.Pasos = texto(cocina, "", 4, { Rico = true })
	ui.PasoTexto = texto(cocina, "", 5, { Tamano = "Pequeno", Color = Colores.Amarillo })
	ui.BarraPaso = UIBuilder.Barra(cocina, 0, { LayoutOrder = 6, Alto = 10, Color = Colores.Amarillo, Nombre = "BarraPaso" })

	ui.BotonesReceta = {}
	local orden = 10
	for _, receta in ipairs(Catalogs.Recetas or {}) do
		local id = receta.Id
		local boton = botonAncho(cocina, "Preparar: " .. tostring(receta.Nombre), function()
			pedir("IniciarReceta", { RecetaId = id })
		end, orden, "Primario", "Receta_" .. tostring(id))
		table.insert(ui.BotonesReceta, boton)
		orden = orden + 1
	end
	ui.BotonPaso = botonAncho(cocina, "Hacer paso", function()
		local esperado = estado and estado.PasoEsperado
		pedir("Paso", { Estacion = esperado })
	end, 30, "Primario", "HacerPaso")
	ui.BotonEntregar = botonAncho(cocina, "Entregar en el mostrador", function()
		pedir("Entregar", nil)
	end, 31, "Exito", "Entregar")
	ui.BotonReponer = botonAncho(cocina, "Reponer lote (congeladores)", function()
		pedir("Reponer", nil)
	end, 32, "Secundario", "Reponer")
	ui.AyudaCocina = texto(cocina, "Acércate a la estación indicada (máx. 12 studs) y pulsa el botón o usa el aviso de la estación. Cada paso tarda unos segundos: no te alejes.", 40, {
		Tamano = "Pequeno", Color = Colores.TextoApagado,
	})
end

local function asegurarUI()
	if not ui.Gui or ui.Gui.Parent == nil or not ui.Panel or ui.Panel.Parent == nil then
		construirUI()
	end
end

-- Tamaño y posición: a la derecha bajo los botones del HUD; centrado si la pantalla es estrecha o baja.
local function ajustarPanel()
	if not ui.Panel or ui.Panel.Parent == nil then
		return
	end
	local esp = UITheme.Espaciado
	local escala = math.max(0.5, UIBuilder.EscalaTotal())
	local arriba = math.ceil(UIBuilder.InsetSuperior() / escala) + esp
	local abajo = math.ceil(UIBuilder.MargenInferiorTactil() / escala) + esp
	local disponible = UIBuilder.AltoUI() - arriba - abajo
	local ancho = math.floor(math.min(ANCHO_PANEL, UIBuilder.AnchoUI() - 2 * esp - 8))
	local deseado = ALTO_ESTADO
	if ui.Cocina and ui.Cocina.Visible then
		deseado = ALTO_COCINA
	end
	local bajoHUD = disponible - MARGEN_BOTONES_HUD
	if not UIBuilder.EsEstrecho() and bajoHUD >= math.min(deseado, 240) then
		ui.Panel.AnchorPoint = Vector2.new(1, 0)
		ui.Panel.Position = UDim2.new(1, 0, 0, MARGEN_BOTONES_HUD)
		ui.Panel.Size = UDim2.new(0, ancho, 0, math.floor(math.min(deseado, bajoHUD)))
	else
		ui.Panel.AnchorPoint = Vector2.new(0.5, 0.5)
		ui.Panel.Position = UDim2.new(0.5, 0, 0.5, 0)
		ui.Panel.Size = UDim2.new(0, ancho, 0, math.floor(math.max(160, math.min(deseado, disponible))))
	end
end

---------------------------------------------------------------------------------------------------
-- Refresco
---------------------------------------------------------------------------------------------------
local function restanteReclamo()
	local proximo = tonumber(personal.ProximoReclamo) or 0
	if proximo <= 0 then
		return 0
	end
	return math.max(0, proximo - ahoraServidor())
end

local function textoTurno()
	if not estado then
		return ""
	end
	if not estado.Abierto then
		return "<font color=\"" .. HEX_APAGADO .. "\">Solo se sirve en el descanso y el almuerzo.</font>"
	end
	local restante = restanteReclamo()
	if restante > 0 then
		return "<font color=\"" .. HEX_AMARILLO .. "\">Próximo almuerzo en " .. Format.Tiempo(restante) .. "</font>"
	end
	if (tonumber(estado.RacionesDisponibles) or 0) <= 0 then
		return "<font color=\"" .. HEX_AMARILLO .. "\">Sin raciones por ahora: la cocina está preparando más.</font>"
	end
	return "<font color=\"" .. HEX_VERDE .. "\">¡Puedes reclamar tu almuerzo!</font>"
end

-- Botón de reclamo: visible en la fila de la ventana de servicio o en la cocina; activo si el servidor lo permitiría.
local function refrescarReclamo()
	if not ui.BotonReclamar then
		return
	end
	local visible = estado ~= nil and (zonaActual == "FILA" or zonaActual == ZONA_COCINA)
	ui.BotonReclamar.Visible = visible
	if visible then
		local raciones = tonumber(estado.RacionesDisponibles) or 0
		UIBuilder.Habilitar(ui.BotonReclamar, not pidiendo and estado.Abierto == true and restanteReclamo() <= 0 and raciones > 0)
	end
end

local function refrescarPaso()
	if not ui.PasoTexto then
		return
	end
	if pasoActual and tonumber(pasoActual.FinServidor) then
		local duracion = math.max(0.1, tonumber(pasoActual.Duracion) or 1)
		local restante = math.max(0, pasoActual.FinServidor - ahoraServidor())
		ui.PasoTexto.Text = "En curso: " .. tostring(pasoActual.NombreEstacion or nombreEstacion(pasoActual.Estacion)) .. " (" .. math.ceil(restante) .. " s)"
		ui.PasoTexto.Visible = true
		ui.BarraPaso.Frame.Visible = true
		ui.BarraPaso:Fijar(1 - restante / duracion, false)
	else
		ui.PasoTexto.Visible = false
		ui.BarraPaso.Frame.Visible = false
	end
end

local function textoPasos(receta)
	local lineas = {}
	local actual = tonumber(receta.PasoActual) or 1
	local incluyeEntrega = false
	for i, paso in ipairs(receta.Pasos or {}) do
		if paso == "Entrega" then
			incluyeEntrega = true
		end
		local icono = "○"
		local color = HEX_APAGADO
		if i < actual or receta.Lista then
			icono = "✔"
			color = HEX_VERDE
		elseif i == actual then
			icono = "▶"
			color = HEX_AMARILLO
		end
		table.insert(lineas, "<font color=\"" .. color .. "\">" .. icono .. "</font> " .. i .. ". " .. nombreEstacion(paso))
	end
	if not incluyeEntrega then
		local icono, color = "○", HEX_APAGADO
		if receta.Lista then
			icono, color = "▶", HEX_AMARILLO
		end
		table.insert(lineas, "<font color=\"" .. color .. "\">" .. icono .. "</font> " .. nombreEstacion("Entrega"))
	end
	return table.concat(lineas, "\n")
end

local function refrescarCocina()
	if not ui.Cocina then
		return
	end
	local visible = mostrarCocina()
	ui.Cocina.Visible = visible
	if not visible then
		return
	end
	local cocinero = esCocina()
	local receta = estado and estado.Receta
	local lotesRestantes = estado and tonumber(estado.LotesRestantes) or 0
	if not estado then
		ui.Receta.Text = "Esperando datos de la cocina…"
		ui.Pasos.Visible = false
	elseif typeof(receta) == "table" then
		local autor = ""
		if typeof(receta.Cocinero) == "string" and receta.Cocinero ~= "" then
			autor = " · " .. receta.Cocinero
		end
		ui.Receta.Text = "Receta: " .. tostring(receta.Nombre) .. autor .. " (" .. tostring(receta.Raciones or RACIONES_POR_LOTE) .. " raciones)"
		ui.Pasos.Text = textoPasos(receta)
		ui.Pasos.Visible = true
	else
		if lotesRestantes > 0 then
			ui.Receta.Text = "No hay receta en preparación. Quedan " .. Format.Plural(lotesRestantes, "lote", "lotes") .. " en esta jornada."
		else
			ui.Receta.Text = "La cocina ya preparó todos los lotes de esta jornada."
		end
		ui.Pasos.Visible = false
	end
	refrescarPaso()

	local hayReceta = typeof(receta) == "table"
	for _, boton in ipairs(ui.BotonesReceta) do
		boton.Visible = cocinero and estado ~= nil and not hayReceta
		UIBuilder.Habilitar(boton, not pidiendo and lotesRestantes > 0)
	end
	local esperado = estado and estado.PasoEsperado
	local listo = hayReceta and receta.Lista == true
	ui.BotonPaso.Visible = cocinero and hayReceta and not listo
	if ui.BotonPaso.Visible then
		UIBuilder.TextoBoton(ui.BotonPaso, "Hacer paso: " .. nombreEstacion(esperado))
		UIBuilder.Habilitar(ui.BotonPaso, not pidiendo and pasoActual == nil)
	end
	ui.BotonEntregar.Visible = cocinero and listo
	UIBuilder.Habilitar(ui.BotonEntregar, not pidiendo)
	ui.BotonReponer.Visible = puedeReponer() and estado ~= nil
	if ui.BotonReponer.Visible then
		local raciones = tonumber(estado.RacionesDisponibles) or 0
		local porLote = tonumber(estado.RacionesPorLote) or RACIONES_POR_LOTE
		UIBuilder.Habilitar(ui.BotonReponer, not pidiendo and lotesRestantes > 0 and raciones < porLote)
	end
end

local function refrescar()
	if not ui.Panel or ui.Panel.Parent == nil then
		return
	end
	if not estado then
		ui.Estado.Text = "Cargando el estado del comedor…"
		ui.Raciones.Text = ""
		ui.Lotes.Text = ""
		ui.Menu.Text = ""
		ui.Turno.Text = ""
		ui.BarraRaciones:Fijar(0, false)
	else
		local periodo = tostring(estado.Periodo or "")
		if estado.Abierto then
			ui.Estado.Text = "<font color=\"" .. HEX_VERDE .. "\">●</font> Abierto · " .. periodo
		else
			ui.Estado.Text = "<font color=\"" .. HEX_ROJO .. "\">●</font> Cerrado · " .. periodo
		end
		local raciones = math.max(0, math.floor(tonumber(estado.RacionesDisponibles) or 0))
		local porLote = math.max(1, tonumber(estado.RacionesPorLote) or RACIONES_POR_LOTE)
		ui.Raciones.Text = "Raciones disponibles: " .. raciones
		ui.BarraRaciones:Fijar(math.min(1, raciones / porLote), true)
		local lotes = "Lotes de la jornada: " .. tostring(estado.LoteActual or 0) .. " de " .. tostring(estado.LotesPorJornada or 0)
		if estado.ModoNPC then
			lotes = lotes .. " · servicio automático"
		end
		ui.Lotes.Text = lotes
		if typeof(estado.Menu) == "string" and estado.Menu ~= "" then
			ui.Menu.Text = "Menú: " .. estado.Menu
		else
			ui.Menu.Text = "Menú: aún sin preparar"
		end
		ui.Turno.Text = textoTurno()
	end
	refrescarReclamo()
	refrescarCocina()
	ajustarPanel()
end

---------------------------------------------------------------------------------------------------
-- Datos del servidor
---------------------------------------------------------------------------------------------------
local function aplicarPaso(receta)
	if typeof(receta) == "table" and typeof(receta.PasoEnCurso) == "table" then
		pasoActual = {
			Estacion = receta.PasoEnCurso.Estacion,
			NombreEstacion = receta.PasoEnCurso.NombreEstacion,
			FinServidor = tonumber(receta.PasoEnCurso.FinServidor),
			Duracion = tonumber(receta.PasoEnCurso.Duracion),
		}
	else
		pasoActual = nil
	end
end

-- Respuesta de FoodAction: Estado + Personal.
local function aplicarDatos(datos)
	if typeof(datos) ~= "table" then
		return
	end
	if datos.RacionesDisponibles ~= nil then
		estado = datos
		aplicarPaso(datos.Receta)
	end
	if typeof(datos.Personal) == "table" then
		personal.ProximoReclamo = tonumber(datos.Personal.ProximoReclamo) or 0
	end
end

local function consultarEstado(forzar)
	if not activo then
		return
	end
	if not forzar and os.clock() - ultimaConsulta < CONSULTA_MIN_SEG then
		return
	end
	ultimaConsulta = os.clock()
	task.spawn(function()
		local ok, respuesta = Net.Invocar("FoodAction", { Accion = "Estado" })
		if ok and typeof(respuesta.datos) == "table" then
			aplicarDatos(respuesta.datos)
			refrescar()
		end
	end)
end

pedir = function(accion, extra)
	if pidiendo or not activo then
		return
	end
	pidiendo = true
	refrescarReclamo()
	refrescarCocina()
	task.spawn(function()
		local datos = { Accion = accion }
		for clave, valor in pairs(extra or {}) do
			datos[clave] = valor
		end
		local ok, respuesta = Net.Invocar("FoodAction", datos)
		pidiendo = false
		if typeof(respuesta) == "table" and typeof(respuesta.datos) == "table" then
			aplicarDatos(respuesta.datos)
		end
		if not ok then
			notificar(UIBuilder.MensajeError(respuesta and respuesta.error), "aviso", 5)
		end
		refrescar()
	end)
end

local function alEvento(datos)
	local sub = datos.Sub
	if sub == "Estado" then
		estado = datos
		aplicarPaso(datos.Receta)
	elseif sub == "Paso" then
		if datos.Fase == "Inicio" then
			pasoActual = {
				Estacion = datos.Estacion,
				NombreEstacion = datos.NombreEstacion,
				FinServidor = tonumber(datos.FinServidor),
				Duracion = tonumber(datos.Duracion),
			}
		else
			pasoActual = nil
			if datos.Fase == "Cancelado" and (esCocina() and zonaActual == ZONA_COCINA) then
				notificar(tostring(datos.Motivo or "El paso se canceló."), "aviso", 5)
			end
		end
	elseif sub == "Reclamado" then
		personal.ProximoReclamo = tonumber(datos.ProximoReclamo) or 0
		if estado and datos.RacionesDisponibles ~= nil then
			estado.RacionesDisponibles = datos.RacionesDisponibles
		end
	elseif sub == "Lote" then
		if estado then
			estado.RacionesDisponibles = datos.RacionesDisponibles or estado.RacionesDisponibles
			estado.LoteActual = datos.LoteActual or estado.LoteActual
			estado.Menu = datos.Menu or estado.Menu
		end
		if zonaActual then
			notificar("Nuevo lote en el comedor: +" .. tostring(datos.Raciones or 0) .. " raciones (" .. tostring(datos.Menu or "menú del día") .. ").", "info", 4)
		end
	elseif sub == "AbrirPanel" then
		forzarCocina = datos.Seccion == "Cocina"
		cerradoPorUsuario = false
		FoodController.Abrir(true)
		return
	end
	refrescar()
end

---------------------------------------------------------------------------------------------------
-- Zona
---------------------------------------------------------------------------------------------------
local function quitarAccionHUD()
	local HUD = obtenerControlador("HUDController")
	if HUD and typeof(HUD.AccionContextual) == "function" then
		pcall(HUD.AccionContextual, HUD, ACCION_HUD, nil)
	end
end

local function ponerAccionHUD()
	local HUD = obtenerControlador("HUDController")
	if HUD and typeof(HUD.AccionContextual) == "function" then
		local ok = pcall(HUD.AccionContextual, HUD, ACCION_HUD, function()
			cerradoPorUsuario = false
			FoodController.Alternar()
		end)
		return ok
	end
	return false
end

local function alCambiarZona(anterior, nueva)
	if nueva == nil then
		forzarCocina = false
		quitarAccionHUD()
		FoodController.Cerrar(false)
		cerradoPorUsuario = false
		return
	end
	if anterior == nil then
		local conBoton = ponerAccionHUD()
		consultarEstado(false)
		-- En pantallas amplias el estado se muestra solo; en estrechas, con el botón "Comedor" del HUD.
		if not cerradoPorUsuario and (not UIBuilder.EsEstrecho() or not conBoton) then
			FoodController.Abrir(false)
		end
	end
	if nueva ~= ZONA_COCINA then
		forzarCocina = false
	end
	refrescar()
end

---------------------------------------------------------------------------------------------------
-- API pública (admite llamada con punto o con dos puntos)
---------------------------------------------------------------------------------------------------
function FoodController.EstaAbierto()
	return abierto
end

-- Abre el panel. enfocar = true pone el foco de mando en el panel (apertura explícita).
function FoodController.Abrir(a, b)
	if not activo then
		return
	end
	local enfocar = a
	if a == FoodController then
		enfocar = b
	end
	local ok, err = pcall(asegurarUI)
	if not ok then
		warn(LOG .. "No se pudo construir el panel: " .. tostring(err))
		return
	end
	consultarEstado(false)
	refrescar()
	if abierto then
		if enfocar then
			UIBuilder.EnfocarPrimero(ui.Panel)
		end
		return
	end
	abierto = true
	ui.Gui.Enabled = true
	UIBuilder.Aparecer(ui.Panel)
	local conexion = UIBuilder.TeclaCerrar(function()
		FoodController.Cerrar(true)
	end)
	if conexion then
		maidPanel:GiveTask(conexion)
	end
	if enfocar then
		task.defer(function()
			if abierto and ui.Panel and ui.Panel.Parent ~= nil then
				UIBuilder.EnfocarPrimero(ui.Panel)
			end
		end)
	end
end

-- Cierra el panel. porUsuario = true evita que se vuelva a abrir solo hasta salir de la zona.
function FoodController.Cerrar(a, b)
	local porUsuario = a
	if a == FoodController then
		porUsuario = b
	end
	if porUsuario == true then
		cerradoPorUsuario = true
	end
	if not abierto then
		return
	end
	abierto = false
	maidPanel:DoCleaning()
	if ui.Panel and ui.Panel.Parent ~= nil then
		UIBuilder.Desenfocar(ui.Panel)
		UIBuilder.Desaparecer(ui.Panel)
	end
end

function FoodController.Alternar()
	if abierto then
		FoodController.Cerrar(true)
	else
		FoodController.Abrir(true)
	end
end

-- Último estado del comedor recibido del servidor (o nil).
function FoodController.Estado()
	return estado
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function FoodController:Init(registro)
	self.registro = registro
end

function FoodController:Start()
	if activo then
		return
	end
	activo = true
	local ok, err = pcall(construirUI)
	if not ok then
		warn(LOG .. "No se pudo construir el panel: " .. tostring(err))
	end

	-- Canal servidor -> cliente.
	task.spawn(function()
		local remoto = Net.Evento("EventoCliente")
		if not remoto then
			warn(LOG .. "EventoCliente no disponible; el panel del comedor no recibirá actualizaciones.")
			return
		end
		maid:GiveTask(remoto.OnClientEvent:Connect(function(carga)
			if typeof(carga) ~= "table" or carga.Tipo ~= "Comida" then
				return
			end
			local datos = carga.Datos
			if typeof(datos) ~= "table" then
				return
			end
			local exito, errEvento = pcall(alEvento, datos)
			if not exito then
				warn(LOG .. tostring(errEvento))
			end
		end))
	end)

	-- Cargo: visibilidad de prompts y de la sección de cocina.
	maid:GiveTask(LocalPlayer:GetAttributeChangedSignal("Cargo"):Connect(function()
		revisarPrompts()
		refrescar()
	end))
	maid:GiveTask(workspace.ChildAdded:Connect(function(hijo)
		if hijo.Name == CARPETA_MAPA or hijo.Name == CARPETA_PROPIA then
			task.defer(buscarCarpetas)
		end
	end))
	task.spawn(function()
		local mapa = workspace:FindFirstChild(CARPETA_MAPA) or workspace:WaitForChild(CARPETA_MAPA, TIMEOUT)
		if mapa then
			buscarCarpetas()
		end
	end)

	-- Cambio de tamaño de pantalla.
	local function vigilarCamara()
		local camara = workspace.CurrentCamera
		if camara then
			maid:GiveTask(camara:GetPropertyChangedSignal("ViewportSize"):Connect(function()
				if abierto then
					ajustarPanel()
				end
			end))
		end
	end
	pcall(vigilarCamara)

	-- Detección de zona (1 Hz).
	maid:GiveTask(task.spawn(function()
		while activo do
			local exito, zona = pcall(detectarZona)
			if exito and zona ~= zonaActual then
				local anterior = zonaActual
				zonaActual = zona
				local okZona, errZona = pcall(alCambiarZona, anterior, zona)
				if not okZona then
					warn(LOG .. tostring(errZona))
				end
			end
			task.wait(INTERVALO_ZONA)
		end
	end))

	-- Cuenta atrás del reclamo y progreso del paso (solo con el panel abierto).
	maid:GiveTask(task.spawn(function()
		local acumulado = 0
		while activo do
			task.wait(INTERVALO_UI)
			if abierto and ui.Panel and ui.Panel.Parent ~= nil then
				refrescarPaso()
				acumulado = acumulado + INTERVALO_UI
				if acumulado >= 1 then
					acumulado = 0
					if ui.Turno then
						ui.Turno.Text = textoTurno()
					end
					-- El cooldown vence en el cliente: el botón de reclamo vuelve a activarse sin esperar al servidor.
					refrescarReclamo()
					if pasoActual and tonumber(pasoActual.FinServidor) and ahoraServidor() > pasoActual.FinServidor + 3 then
						-- El paso debió terminar y no llegó la confirmación: se pide el estado.
						pasoActual = nil
						consultarEstado(true)
					end
				end
			end
		end
	end))
end

return FoodController
]=] }
FUENTES["StarterPlayer/StarterPlayerScripts/ColegioRP/Controllers/FootballController"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: StarterPlayer.StarterPlayerScripts.ColegioRP.Controllers.FootballController
	Tipo: ModuleScript
	Interfaz de la cancha (docs/ARQUITECTURA.md §7, prueba P11). Al entrar en la zona CANCHA (comprobación a 1 Hz)
	muestra un panel compacto con marcador, tiempo, equipo propio y botones (Unirse A/B, Iniciar si procede,
	Reiniciar/Finalizar para árbitros, Salir) y habilita la patada: PC = tecla E o clic sobre el balón, mando =
	ButtonX, táctil = botón grande abajo a la derecha, a la izquierda del botón de salto y por encima de los
	controles. La fuerza depende del tiempo de pulsación (0.4..1.0, barra de carga de hasta 1 s) y la dirección
	mezcla 70/30 (jugador->balón horizontal) con la dirección de la cámara. Envía FootballKick y FootballAction;
	no predice físicas: el servidor es la autoridad. Colorea a los jugadores por el atributo EquipoFutbol
	(Highlight local) y muestra un efecto local de "¡Gol!". Se oculta fuera de la zona.
]]

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")

local FootballController = {}
FootballController.Nombre = "FootballController"
FootballController.PeriodoZonaSeg = 1 -- Comprobación de zona, resaltados y posición del botón táctil.
FootballController.PeriodoTextoSeg = 0.25 -- Reloj, estado y disponibilidad de la patada (solo en la zona).
FootballController.CargaMaxSeg = 1 -- Tiempo de pulsación para la fuerza máxima.
FootballController.FuerzaMin = 0.4 -- Fuerza con una pulsación corta.
FootballController.FuerzaMaxima = 1 -- Fuerza con la carga completa.
FootballController.MezclaBalon = 0.7 -- Peso de la dirección jugador->balón (el resto es la cámara).
FootballController.ElevacionBase = 0.1 -- Componente vertical añadida (el servidor la limita al 35 %).
FootballController.MargenCooldownSeg = 0.05 -- Margen local sobre Config.Futbol.CooldownPatada.
FootballController.SoltarAutomaticoSeg = 2.5 -- Una carga mantenida más de esto se suelta sola.
FootballController.RadioClicBalon = 2.2 -- Tolerancia (studs) del clic sobre el balón.
FootballController.DistanciaClicMax = 250
FootballController.EsperaEstadoSeg = 2 -- Si el servidor no envió el estado al entrar, se pide tras esto.
FootballController.MaxResaltados = 20 -- Highlights simultáneos (límite del motor: 31).
FootballController.DuracionGolSeg = 2.6
FootballController.DuracionPistaSeg = 3
FootballController.TamanoBotonPatear = 104 -- Unidades de UI (antes de la UIScale).

local UIBuilder, UITheme, Net, Maid, Format, Zones, Config

local player = Players.LocalPlayer
local ATRIBUTO_EQUIPO = "EquipoFutbol"

local function requerir(padre, nombre)
	if not padre then
		error("no se encontró la carpeta para " .. nombre)
	end
	local modulo = padre:FindFirstChild(nombre) or padre:WaitForChild(nombre, 10)
	if not modulo then
		error("no se encontró el módulo " .. nombre)
	end
	return require(modulo)
end

local function valida(instancia)
	return typeof(instancia) == "Instance" and instancia.Parent ~= nil
end

local function numero(valor)
	local n = tonumber(valor)
	if n == nil or n ~= n or n == math.huge or n == -math.huge then
		return nil
	end
	return n
end

local function servidorAhora()
	local ok, t = pcall(function()
		return workspace:GetServerTimeNow()
	end)
	if ok and numero(t) then
		return t
	end
	return os.time()
end

-- HumanoidRootPart del personaje local si está vivo.
local function raizLocal()
	local personaje = player.Character
	if not personaje then
		return nil
	end
	local humanoide = personaje:FindFirstChildOfClass("Humanoid")
	if humanoide and humanoide.Health <= 0 then
		return nil
	end
	local raiz = personaje:FindFirstChild("HumanoidRootPart")
	if raiz and raiz:IsA("BasePart") then
		return raiz
	end
	return nil
end

local function hex(color)
	return string.format("#%02X%02X%02X", math.floor(color.R * 255 + 0.5), math.floor(color.G * 255 + 0.5), math.floor(color.B * 255 + 0.5))
end

local function miEquipo()
	local equipo = player:GetAttribute(ATRIBUTO_EQUIPO)
	if equipo == "A" or equipo == "B" then
		return equipo
	end
	return nil
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function FootballController:Init(registro)
	self.registro = registro
	Config = registro.Config
	UIBuilder = registro.UIBuilder
	if not UIBuilder then
		error("UIBuilder no está disponible")
	end
	local Shared = registro.Shared
	local Util = Shared:FindFirstChild("Util") or Shared:WaitForChild("Util", 10)
	UITheme = requerir(Shared, "UITheme")
	Net = requerir(Util, "Net")
	Maid = requerir(Util, "Maid")
	Format = requerir(Util, "Format")
	Zones = requerir(Util, "Zones")

	local cfg = Config.Futbol or {}
	self.distanciaPatada = numero(cfg.DistanciaPatada) or 9
	self.cooldown = numero(cfg.CooldownPatada) or 0.6
	self.duracion = numero(cfg.DuracionPartidoSeg) or 300
	self.maxPorEquipo = numero(cfg.JugadoresPorEquipoMax) or 7
	self.colorA = UITheme.Colores.Rojo
	self.colorB = UITheme.Aclarar(UITheme.Colores.Azul, 0.35)

	self.maid = Maid.new()
	self.zonaId = "CANCHA"
	self.enZona = false
	self.estado = nil -- último estado recibido del servidor
	self.estadoRecibidoClock = -math.huge
	self.entradaZonaClock = nil
	self.pedidoEstado = false
	self.cargando = nil -- { Fuente, Inicio, Input }
	self.cooldownHasta = 0
	self.ocupado = false
	self.minimizado = false
	self.autoMinimizado = false -- minimizado por el controlador (teléfono en partido), no por el jugador
	self.resaltados = {} -- Player -> Highlight
	self.balon = nil
	self.carpeta = nil
	self.acumZona = 0
	self.acumTexto = 0
	self.ui = nil
	self.tokenGol = 0
	self.tokenPista = 0
	self.pistaHasta = 0
	self.patearHabilitado = nil
end

function FootballController:Start()
	local okUI, errUI = pcall(self._Construir, self)
	if not okUI then
		warn("[ColegioRP] FootballController: no se pudo construir la interfaz: " .. tostring(errUI))
		return
	end
	self:_ConectarEntrada()

	self.maid:GiveTask(RunService.Heartbeat:Connect(function(dt)
		self:_Paso(dt)
	end))
	self.maid:GiveTask(player:GetAttributeChangedSignal(ATRIBUTO_EQUIPO):Connect(function()
		self:_Refrescar()
	end))
	self.maid:GiveTask(Players.PlayerRemoving:Connect(function(otro)
		self:_QuitarResaltado(otro)
	end))
	pcall(function()
		local camara = workspace.CurrentCamera
		self.maid:GiveTask(camara:GetPropertyChangedSignal("ViewportSize"):Connect(function()
			self:_PosicionarBotonPatear()
		end))
	end)

	task.spawn(function()
		local remoto = Net.Evento("EventoCliente")
		if not remoto then
			warn("[ColegioRP] FootballController: EventoCliente no disponible; la cancha no recibirá datos del servidor.")
			return
		end
		self.maid:GiveTask(remoto.OnClientEvent:Connect(function(carga)
			if typeof(carga) ~= "table" or carga.Tipo ~= "Futbol" or typeof(carga.Datos) ~= "table" then
				return
			end
			local ok, err = pcall(self._AlEvento, self, carga.Datos)
			if not ok then
				warn("[ColegioRP] FootballController: " .. tostring(err))
			end
		end))
	end)

	task.spawn(function()
		pcall(self._ResolverBalon, self, true)
	end)
	-- Precarga de los remotos (Net los guarda en caché) para que la primera patada no espere.
	task.spawn(function()
		Net.Evento("FootballKick")
		Net.Funcion("FootballAction")
	end)
end

-- Libera conexiones, resaltados e interfaz.
function FootballController:Destruir()
	self:_CancelarCarga()
	self:_QuitarResaltados()
	if self.maid then
		self.maid:DoCleaning()
	end
	self.ui = nil
	self.enZona = false
end

---------------------------------------------------------------------------------------------------
-- Balón y zona
---------------------------------------------------------------------------------------------------

-- Busca Workspace.ColegioRP_Mapa.Futbol.Balon (esperando con timeout si 'esperar').
function FootballController:_ResolverBalon(esperar)
	local nombreRaiz = (Config.Nombres and Config.Nombres.CarpetaMapa) or "ColegioRP_Mapa"
	local raiz = workspace:FindFirstChild(nombreRaiz)
	if not raiz and esperar then
		raiz = workspace:WaitForChild(nombreRaiz, 20)
	end
	if not raiz then
		return nil
	end
	local carpeta = raiz:FindFirstChild("Futbol")
	if not carpeta and esperar then
		carpeta = raiz:WaitForChild("Futbol", 10)
	end
	if not carpeta then
		return nil
	end
	self.carpeta = carpeta
	local zona = carpeta:GetAttribute("ZoneId")
	if typeof(zona) == "string" and Zones.Zona(zona) then
		self.zonaId = zona
	end
	local distancia = numero(carpeta:GetAttribute("DistanciaPatada"))
	if distancia and distancia > 0 then
		self.distanciaPatada = distancia
	end
	local cooldown = numero(carpeta:GetAttribute("CooldownPatada"))
	if cooldown and cooldown > 0 then
		self.cooldown = cooldown
	end
	local balon = carpeta:FindFirstChild("Balon")
	if not balon and esperar then
		balon = carpeta:WaitForChild("Balon", 10)
	end
	if balon and balon:IsA("BasePart") then
		self.balon = balon
	end
	return self.balon
end

function FootballController:_DistanciaBalon()
	local balon = self.balon
	local raiz = raizLocal()
	if not valida(balon) or not raiz then
		return nil
	end
	return (raiz.Position - balon.Position).Magnitude
end

function FootballController:_Paso(dt)
	self.acumZona = self.acumZona + dt
	if self.acumZona >= self.PeriodoZonaSeg then
		self.acumZona = 0
		local ok, err = pcall(self._RevisarZona, self)
		if not ok then
			warn("[ColegioRP] FootballController: " .. tostring(err))
		end
	end
	if self.enZona then
		self.acumTexto = self.acumTexto + dt
		if self.acumTexto >= self.PeriodoTextoSeg then
			self.acumTexto = 0
			pcall(self._RefrescarDinamico, self)
		end
	end
end

function FootballController:_RevisarZona()
	local raiz = raizLocal()
	local dentro = false
	if raiz then
		dentro = Zones.Contiene(self.zonaId, raiz.Position)
	end
	if dentro ~= self.enZona then
		self.enZona = dentro
		if dentro then
			self:_AlEntrar()
		else
			self:_AlSalir()
		end
	end
	if not dentro then
		return
	end
	if not valida(self.balon) then
		self:_ResolverBalon(false)
	end
	self:_ActualizarResaltados()
	self:_PosicionarBotonPatear()
	-- Respaldo: el servidor envía el estado al entrar; si no llegó, se pide una vez.
	if not self.pedidoEstado and self.entradaZonaClock and os.clock() - self.entradaZonaClock >= self.EsperaEstadoSeg
		and self.estadoRecibidoClock < self.entradaZonaClock then
		self.pedidoEstado = true
		self:_Accion("Estado", nil, true)
	end
end

function FootballController:_AlEntrar()
	self.entradaZonaClock = os.clock()
	self.pedidoEstado = false
	if self.ui then
		self.ui.Gui.Enabled = true
		UIBuilder.Aparecer(self.ui.Panel)
	end
	self:_Refrescar()
	self:_PosicionarBotonPatear()
end

function FootballController:_AlSalir()
	self:_CancelarCarga()
	self:_QuitarResaltados()
	self.entradaZonaClock = nil
	if self.ui then
		UIBuilder.Desenfocar(self.ui.Gui)
		self.ui.Gui.Enabled = false
		self.ui.GolMarco.Visible = false
	end
end

-- ¿Está el jugador local en la cancha?
function FootballController:EnZona()
	return self.enZona == true
end

-- Último estado de la cancha recibido del servidor (o nil).
function FootballController:Estado()
	return self.estado
end

---------------------------------------------------------------------------------------------------
-- Interfaz
---------------------------------------------------------------------------------------------------
function FootballController:_Construir()
	local Colores = UITheme.Colores
	local capa = (UITheme.Capas and UITheme.Capas.Panel) or 50
	local gui = UIBuilder.Pantalla("Futbol", capa, { Visible = false })
	self.maid:GiveTask(gui)
	local contenido = UIBuilder.Contenedor(gui, { Nombre = "Contenido" })
	local tactil = UIBuilder.EsTactil()
	local estrecho = UIBuilder.EsEstrecho()
	local ancho = 340
	if estrecho then
		ancho = 300
	end
	local ui = { Gui = gui, Contenido = contenido, Tactil = tactil }

	-- Panel compacto. Táctil: arriba al centro (lejos del joystick y del salto). PC/mando: derecha, a media altura.
	local posicion = UDim2.new(1, 0, 0.55, 0)
	local ancla = Vector2.new(1, 0.5)
	if tactil then
		posicion = UDim2.new(0.5, 0, 0, 0)
		ancla = Vector2.new(0.5, 0)
	end
	local panel, cuerpo = UIBuilder.Panel(contenido, {
		Nombre = "PanelFutbol", AutoAlto = true, Espaciado = 6, Transparencia = 0.12,
		Size = UDim2.new(0, ancho, 0, 0), Position = posicion, AnchorPoint = ancla,
	})
	ui.Panel = panel

	-- Fila 1: equipos, marcador, tiempo y minimizar.
	local altoFila = 34
	if tactil then
		altoFila = math.max(34, UIBuilder.MinimoTactil())
	end
	local fila = UIBuilder.Marco(cuerpo, { Nombre = "Marcador", Alto = altoFila, LayoutOrder = 1 })
	local comunes = { AutoAlto = false, Ajustar = false, AlineacionY = Enum.TextYAlignment.Center, Fuente = "Titulo" }
	local function texto(padre, valor, props)
		local copia = {}
		for clave, v in pairs(comunes) do
			copia[clave] = v
		end
		for clave, v in pairs(props) do
			copia[clave] = v
		end
		return UIBuilder.Texto(padre, valor, copia)
	end
	ui.EquipoA = texto(fila, "A", { Nombre = "EquipoA", Tamano = "Subtitulo", Color = self.colorA, Alineacion = Enum.TextXAlignment.Center,
		Size = UDim2.new(0, 26, 1, 0), Position = UDim2.new(0, 0, 0, 0) })
	ui.Marcador = texto(fila, "0 - 0", { Nombre = "Goles", Tamano = "Titulo", Alineacion = Enum.TextXAlignment.Center,
		Size = UDim2.new(0, 84, 1, 0), Position = UDim2.new(0, 26, 0, 0) })
	ui.EquipoB = texto(fila, "B", { Nombre = "EquipoB", Tamano = "Subtitulo", Color = self.colorB, Alineacion = Enum.TextXAlignment.Center,
		Size = UDim2.new(0, 26, 1, 0), Position = UDim2.new(0, 110, 0, 0) })
	local anchoMin = 36
	if tactil then
		anchoMin = UIBuilder.MinimoTactil()
	end
	ui.Tiempo = texto(fila, Format.Tiempo(self.duracion), { Nombre = "Tiempo", Tamano = "Subtitulo", Color = Colores.Amarillo,
		Alineacion = Enum.TextXAlignment.Right, Size = UDim2.new(1, -(140 + anchoMin + 6), 1, 0), Position = UDim2.new(0, 140, 0, 0) })
	ui.Minimizar = UIBuilder.Boton(fila, "–", function()
		self.autoMinimizado = false
		self:_Minimizar(not self.minimizado)
	end, {
		Nombre = "Minimizar", Estilo = "Fantasma", Ancho = anchoMin, Alto = altoFila, Tamano = "Subtitulo",
		Position = UDim2.new(1, 0, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5),
	})

	-- Filas 2 y 3: estado del partido y equipo propio.
	ui.Estado = UIBuilder.Texto(cuerpo, "Conectando con la cancha…", { Nombre = "Estado", Tamano = "Pequeno", Color = Colores.TextoSecundario, LayoutOrder = 2 })
	ui.Equipo = UIBuilder.Texto(cuerpo, "No estás en un equipo", { Nombre = "MiEquipo", Tamano = "Pequeno", LayoutOrder = 3 })

	-- Fila 4: botones (se reparten en varias líneas si no caben).
	local botones = UIBuilder.Marco(cuerpo, { Nombre = "Botones", AutoAlto = true, LayoutOrder = 4 })
	UIBuilder.Disposicion(botones, { Horizontal = true, Espaciado = 6, Alineacion = Enum.HorizontalAlignment.Center, Wraps = true })
	-- Tres botones por línea; el texto se reduce (8..13) si no cabe para no truncarse.
	local interior = ancho - 2 * (UITheme.Espaciado + 6)
	local anchoBoton = math.floor((interior - 2 * 6) / 3)
	local function boton(nombre, etiqueta, estilo, orden, fn)
		local b = UIBuilder.Boton(botones, etiqueta, fn, { Nombre = nombre, Estilo = estilo, Ancho = anchoBoton, LayoutOrder = orden, Tamano = "Pequeno" })
		pcall(function()
			b.TextScaled = true
			local limite = Instance.new("UITextSizeConstraint")
			limite.MinTextSize = 8
			limite.MaxTextSize = UITheme.Tamanos.Pequeno
			limite.Parent = b
		end)
		return b
	end
	ui.UnirseA = boton("UnirseA", "Unirse A", "Secundario", 1, function()
		self:_Accion("Unirse", "A")
	end)
	ui.UnirseB = boton("UnirseB", "Unirse B", "Secundario", 2, function()
		self:_Accion("Unirse", "B")
	end)
	ui.Iniciar = boton("Iniciar", "Iniciar", "Exito", 3, function()
		self:_Accion("Iniciar", nil)
	end)
	ui.Reiniciar = boton("Reiniciar", "Reiniciar", "Secundario", 4, function()
		self:_Accion("Reiniciar", nil)
	end)
	ui.Finalizar = boton("Finalizar", "Finalizar", "Peligro", 5, function()
		self:_Accion("Finalizar", nil)
	end)
	ui.Salir = boton("Salir", "Salir", "Fantasma", 6, function()
		self:_Accion("Salir", nil)
	end)
	ui.Botones = botones
	ui.ListaBotones = { ui.UnirseA, ui.UnirseB, ui.Iniciar, ui.Reiniciar, ui.Finalizar, ui.Salir }
	for _, b in ipairs({ ui.UnirseA, ui.UnirseB }) do
		pcall(function()
			b.RichText = true
		end)
	end

	-- Filas 5 y 6: pista de controles / mensajes y barra de carga.
	ui.Pista = UIBuilder.Texto(cuerpo, "", { Nombre = "Pista", Tamano = "Pequeno", Color = Colores.TextoSecundario, LayoutOrder = 5 })
	ui.Barra = UIBuilder.Barra(cuerpo, 0, { Nombre = "Carga", Alto = 8, LayoutOrder = 6, Color = Colores.Amarillo })
	ui.Barra.Frame.Visible = false
	ui.Detalles = { ui.Estado, ui.Equipo, botones, ui.Pista }

	-- Botón táctil de patada (abajo a la derecha, por encima de los controles táctiles).
	if tactil then
		local tam = self.TamanoBotonPatear
		local patear = UIBuilder.Boton(contenido, "PATEAR", nil, {
			Nombre = "Patear", Estilo = "Primario", Ancho = tam, Alto = tam, Tamano = "Subtitulo",
			Position = UDim2.new(1, 0, 1, 0), AnchorPoint = Vector2.new(1, 1),
		})
		local esquina = patear:FindFirstChildOfClass("UICorner")
		if esquina then
			esquina.CornerRadius = UDim.new(0.5, 0)
		end
		patear.Selectable = false
		local barra = UIBuilder.Barra(patear, 0, {
			Nombre = "CargaTactil", Alto = 6, Size = UDim2.new(0.7, 0, 0, 6),
			Position = UDim2.new(0.5, 0, 1, -16), AnchorPoint = Vector2.new(0.5, 1),
			Color = Colores.Amarillo, ColorFondo = Colores.RojoOscuro,
		})
		barra.Frame.Visible = false
		self.maid:GiveTask(patear.InputBegan:Connect(function(entrada)
			local tipo = entrada.UserInputType
			if tipo == Enum.UserInputType.Touch or tipo == Enum.UserInputType.MouseButton1 then
				self:_IniciarCarga("Tactil", entrada)
			end
		end))
		self.maid:GiveTask(patear.InputEnded:Connect(function(entrada)
			local c = self.cargando
			if not c or c.Fuente ~= "Tactil" then
				return
			end
			local tipo = entrada.UserInputType
			if tipo == Enum.UserInputType.Touch or tipo == Enum.UserInputType.MouseButton1 then
				self:_SoltarCarga()
			end
		end))
		ui.Patear = patear
		ui.BarraTactil = barra
	end

	-- Efecto local de gol (centro de la pantalla).
	local golMarco = Instance.new("Frame")
	golMarco.Name = "Gol"
	golMarco.BackgroundColor3 = Colores.GrisPanel
	golMarco.BackgroundTransparency = 0.15
	golMarco.BorderSizePixel = 0
	golMarco.AnchorPoint = Vector2.new(0.5, 0.5)
	golMarco.Position = UDim2.new(0.5, 0, 0.42, 0)
	golMarco.Size = UDim2.new(0, 360, 0, 0)
	golMarco.AutomaticSize = Enum.AutomaticSize.Y
	golMarco.Visible = false
	golMarco.ZIndex = 20
	UIBuilder.Esquinas(golMarco, UITheme.Radio)
	ui.GolBorde = UIBuilder.Borde(golMarco, Colores.Amarillo, 2)
	UIBuilder.Relleno(golMarco, 10, 12, 14, 14)
	UIBuilder.Disposicion(golMarco, { Espaciado = 2, Alineacion = Enum.HorizontalAlignment.Center })
	ui.GolTitulo = UIBuilder.Texto(golMarco, "¡GOL!", {
		Nombre = "Titulo", Fuente = "Titulo", Tamano = 44, Color = Colores.Amarillo, Alineacion = Enum.TextXAlignment.Center, LayoutOrder = 1, ZIndex = 21,
	})
	ui.GolDetalle = UIBuilder.Texto(golMarco, "", {
		Nombre = "Detalle", Tamano = "Subtitulo", Alineacion = Enum.TextXAlignment.Center, LayoutOrder = 2, ZIndex = 21,
	})
	golMarco.Parent = contenido
	ui.GolMarco = golMarco

	self.ui = ui
	self:_Refrescar()
end

function FootballController:_Minimizar(minimizado)
	self.minimizado = minimizado == true
	local ui = self.ui
	if not ui then
		return
	end
	for _, fila in ipairs(ui.Detalles) do
		fila.Visible = not self.minimizado
	end
	if self.minimizado then
		ui.Barra.Frame.Visible = false
		UIBuilder.TextoBoton(ui.Minimizar, "+")
	else
		UIBuilder.TextoBoton(ui.Minimizar, "–")
	end
	self:_RefrescarBotones()
end

-- Coloca el botón táctil a la izquierda del botón de salto de Roblox (o con un margen de respaldo).
function FootballController:_PosicionarBotonPatear()
	local ui = self.ui
	if not ui or not valida(ui.Patear) then
		return
	end
	local escala = math.max(0.5, UIBuilder.EscalaTotal())
	local anchoPx = UIBuilder.Viewport().X
	local derechaPx = nil
	local okSalto, salto = pcall(function()
		local playerGui = player:FindFirstChildOfClass("PlayerGui")
		local touchGui = playerGui and playerGui:FindFirstChild("TouchGui")
		local marco = touchGui and touchGui:FindFirstChild("TouchControlFrame")
		return marco and marco:FindFirstChild("JumpButton")
	end)
	if okSalto and salto and salto:IsA("GuiObject") and salto.Visible and salto.AbsoluteSize.X > 0 then
		derechaPx = (anchoPx - salto.AbsolutePosition.X) + 12
	end
	if not derechaPx or derechaPx <= 0 or derechaPx > anchoPx * 0.5 then
		derechaPx = 190
		if UIBuilder.EsEstrecho() then
			derechaPx = 110
		end
	end
	-- En pantallas estrechas también se deja libre la columna de botones del HUD (arriba a la derecha).
	if UIBuilder.EsEstrecho() then
		derechaPx = math.max(derechaPx, 132 * escala)
	end
	local desplazamiento = math.max(0, math.floor(derechaPx / escala - UITheme.Espaciado))
	ui.Patear.Position = UDim2.new(1, -desplazamiento, 1, 0)
end

-- Refresco completo tras un cambio de estado.
function FootballController:_Refrescar()
	local ui = self.ui
	if not ui then
		return
	end
	local estado = self.estado or {}
	local marcador = estado.Marcador or { A = 0, B = 0 }
	ui.Marcador.Text = Format.Marcador(marcador.A or 0, marcador.B or 0)
	local mio = miEquipo()
	local conteo = estado.Conteo or { A = 0, B = 0 }
	local maximo = numero(estado.MaxPorEquipo) or self.maxPorEquipo
	local resumen = string.format("A %d/%d · B %d/%d", conteo.A or 0, maximo, conteo.B or 0, maximo)
	if mio then
		ui.Equipo.Text = "Tu equipo: " .. Format.Equipo(mio) .. "  ·  " .. resumen
		if mio == "A" then
			ui.Equipo.TextColor3 = self.colorA
		else
			ui.Equipo.TextColor3 = self.colorB
		end
	else
		ui.Equipo.Text = "No estás en un equipo  ·  " .. resumen
		ui.Equipo.TextColor3 = UITheme.Colores.TextoPrincipal
	end
	self:_RefrescarBotones()
	self:_RefrescarDinamico()
end

function FootballController:_RefrescarBotones()
	local ui = self.ui
	if not ui then
		return
	end
	local estado = self.estado or {}
	local enJuego = estado.Estado == "EnJuego"
	local mio = miEquipo()
	local esArbitro = estado.EsArbitro == true
	local punto = "● "
	if mio == "B" then
		UIBuilder.TextoBoton(ui.UnirseA, '<font color="' .. hex(self.colorA) .. '">' .. punto .. "</font>Cambiar a A")
	else
		UIBuilder.TextoBoton(ui.UnirseA, '<font color="' .. hex(self.colorA) .. '">' .. punto .. "</font>Unirse A")
	end
	if mio == "A" then
		UIBuilder.TextoBoton(ui.UnirseB, '<font color="' .. hex(self.colorB) .. '">' .. punto .. "</font>Cambiar a B")
	else
		UIBuilder.TextoBoton(ui.UnirseB, '<font color="' .. hex(self.colorB) .. '">' .. punto .. "</font>Unirse B")
	end
	ui.UnirseA.Visible = mio ~= "A"
	ui.UnirseB.Visible = mio ~= "B"
	ui.Iniciar.Visible = estado.PuedeIniciar == true and not enJuego
	ui.Reiniciar.Visible = esArbitro and enJuego
	ui.Finalizar.Visible = esArbitro and enJuego
	ui.Salir.Visible = mio ~= nil
	local visibles = {}
	for _, b in ipairs(ui.ListaBotones) do
		UIBuilder.Habilitar(b, not self.ocupado)
		if b.Visible then
			table.insert(visibles, b)
		end
	end
	UIBuilder.Encadenar(visibles, true)
end

-- Reloj, estado del partido, pista de controles y disponibilidad de la patada (4 Hz en la zona).
function FootballController:_RefrescarDinamico()
	local ui = self.ui
	if not ui then
		return
	end
	local estado = self.estado
	local ahora = servidorAhora()
	local texto = "Conectando con la cancha…"
	if estado then
		local cuentaAtras = numero(estado.AutoInicioServidor)
		if estado.Estado == "EnJuego" and numero(estado.InicioServidor) then
			local duracion = numero(estado.Duracion) or self.duracion
			local restante = math.max(0, duracion - (ahora - estado.InicioServidor))
			ui.Tiempo.Text = Format.Tiempo(restante)
			texto = "Partido en juego"
			if estado.Origen == "Arbitro" and estado.IniciadoPor then
				texto = texto .. " · árbitro: " .. tostring(estado.IniciadoPor)
			elseif estado.Origen == "Automatico" then
				texto = texto .. " · inicio automático"
			end
		else
			if estado.Estado == "Terminado" then
				ui.Tiempo.Text = "Final"
			else
				ui.Tiempo.Text = Format.Tiempo(numero(estado.Duracion) or self.duracion)
			end
			if cuentaAtras then
				texto = string.format("El partido empieza solo en %d s", math.max(0, math.ceil(cuentaAtras - ahora)))
			elseif estado.Estado == "Terminado" and typeof(estado.UltimoResultado) == "table" then
				local r = estado.UltimoResultado
				local goles = r.Goles or { A = 0, B = 0 }
				if r.Ganador == "A" or r.Ganador == "B" then
					texto = "Final: gana el " .. Format.Equipo(r.Ganador) .. " (" .. Format.Marcador(goles.A or 0, goles.B or 0) .. ")"
				else
					texto = "Final: empate (" .. Format.Marcador(goles.A or 0, goles.B or 0) .. ")"
				end
			elseif estado.PuedeIniciar then
				texto = "Cancha libre · forma los equipos e inicia el partido"
			elseif estado.ArbitroConectado then
				texto = "Cancha libre · un docente puede iniciar el partido"
			elseif estado.PermiteDeporte == false then
				texto = "Cancha libre · los partidos son en descanso y almuerzo"
			else
				texto = "Cancha libre · con jugadores en A y B el partido empieza solo"
			end
		end
	end
	ui.Estado.Text = texto

	-- Disponibilidad de la patada.
	local distancia = self:_DistanciaBalon()
	local enAlcance = distancia ~= nil and distancia <= self.distanciaPatada
	local enCooldown = os.clock() < self.cooldownHasta
	if ui.Patear then
		local habilitado = enAlcance and not enCooldown
		if habilitado ~= self.patearHabilitado then
			self.patearHabilitado = habilitado
			UIBuilder.Habilitar(ui.Patear, habilitado)
			ui.Patear.Selectable = false
		end
		if self.cargando then
			UIBuilder.TextoBoton(ui.Patear, "SOLTAR")
		elseif enAlcance then
			UIBuilder.TextoBoton(ui.Patear, "PATEAR")
		else
			UIBuilder.TextoBoton(ui.Patear, "ACÉRCATE")
		end
	end
	if os.clock() >= self.pistaHasta then
		ui.Pista.TextColor3 = UITheme.Colores.TextoSecundario
		if ui.Tactil then
			ui.Pista.Text = ""
			ui.Pista.Visible = false
		else
			ui.Pista.Visible = not self.minimizado
			local control = "E o clic en el balón"
			if UIBuilder.TieneMando() then
				control = "E / X (mando) o clic en el balón"
			end
			if enAlcance then
				ui.Pista.Text = control .. ": patear (mantén para más fuerza)"
			else
				ui.Pista.Text = string.format("Acércate al balón (a menos de %d studs) para patear", math.floor(self.distanciaPatada))
			end
		end
	end
end

-- Mensaje temporal en el panel.
function FootballController:_Pista(texto, nivel)
	local ui = self.ui
	if not ui then
		return
	end
	self.tokenPista = self.tokenPista + 1
	self.pistaHasta = os.clock() + self.DuracionPistaSeg
	ui.Pista.Text = tostring(texto or "")
	ui.Pista.Visible = not self.minimizado
	local color = UITheme.Colores.TextoPrincipal
	if nivel == "error" then
		color = UITheme.Colores.Error
	elseif nivel == "aviso" then
		color = UITheme.Colores.Aviso
	elseif nivel == "exito" then
		color = UITheme.Colores.Exito
	end
	ui.Pista.TextColor3 = color
end

-- Notificación por NotificationController (si existe) o pista en el panel.
function FootballController:_Notificar(texto, nivel, duracion)
	local Notificaciones = self.registro and self.registro.Get("NotificationController")
	if Notificaciones and typeof(Notificaciones.Notificar) == "function" then
		local ok = pcall(Notificaciones.Notificar, Notificaciones, texto, nivel or "info", duracion, { Titulo = "Fútbol" })
		if ok then
			return
		end
	end
	self:_Pista(texto, nivel)
end

---------------------------------------------------------------------------------------------------
-- Resaltado de equipos (Highlight local por atributo EquipoFutbol)
---------------------------------------------------------------------------------------------------
function FootballController:_ActualizarResaltados()
	local vistos = {}
	local cantidad = 0
	for _, otro in ipairs(Players:GetPlayers()) do
		local equipo = otro:GetAttribute(ATRIBUTO_EQUIPO)
		local personaje = otro.Character
		if (equipo == "A" or equipo == "B") and personaje and personaje.Parent and cantidad < self.MaxResaltados then
			cantidad = cantidad + 1
			vistos[otro] = true
			local resaltado = self.resaltados[otro]
			if not valida(resaltado) or resaltado.Parent ~= personaje then
				if resaltado then
					UIBuilder.Destruir(resaltado)
				end
				resaltado = Instance.new("Highlight")
				resaltado.Name = "ColegioRP_EquipoFutbol"
				resaltado.FillTransparency = 0.88
				resaltado.OutlineTransparency = 0.15
				resaltado.DepthMode = Enum.HighlightDepthMode.Occluded
				resaltado.Adornee = personaje
				resaltado.Parent = personaje
				self.resaltados[otro] = resaltado
			end
			local color = self.colorB
			if equipo == "A" then
				color = self.colorA
			end
			resaltado.OutlineColor = color
			resaltado.FillColor = color
		end
	end
	for otro, resaltado in pairs(self.resaltados) do
		if not vistos[otro] then
			UIBuilder.Destruir(resaltado)
			self.resaltados[otro] = nil
		end
	end
end

function FootballController:_QuitarResaltado(otro)
	local resaltado = self.resaltados[otro]
	if resaltado then
		UIBuilder.Destruir(resaltado)
		self.resaltados[otro] = nil
	end
end

function FootballController:_QuitarResaltados()
	for otro, resaltado in pairs(self.resaltados) do
		UIBuilder.Destruir(resaltado)
		self.resaltados[otro] = nil
	end
end

---------------------------------------------------------------------------------------------------
-- Patada
---------------------------------------------------------------------------------------------------
function FootballController:_ConectarEntrada()
	self.maid:GiveTask(UserInputService.InputBegan:Connect(function(entrada, procesado)
		if not self.enZona then
			return
		end
		local tecla = entrada.KeyCode
		if tecla == Enum.KeyCode.E or tecla == Enum.KeyCode.ButtonX then
			if procesado or UserInputService:GetFocusedTextBox() ~= nil then
				return
			end
			local fuente = "Teclado"
			if tecla == Enum.KeyCode.ButtonX then
				fuente = "Mando"
			end
			self:_IniciarCarga(fuente, entrada)
		elseif entrada.UserInputType == Enum.UserInputType.MouseButton1 then
			if procesado then
				return
			end
			if self:_ClicSobreBalon(entrada.Position) then
				self:_IniciarCarga("Clic", entrada)
			end
		end
	end))
	self.maid:GiveTask(UserInputService.InputEnded:Connect(function(entrada)
		local c = self.cargando
		if not c then
			return
		end
		if c.Fuente == "Teclado" and entrada.KeyCode == Enum.KeyCode.E then
			self:_SoltarCarga()
		elseif c.Fuente == "Mando" and entrada.KeyCode == Enum.KeyCode.ButtonX then
			self:_SoltarCarga()
		elseif c.Fuente == "Clic" and entrada.UserInputType == Enum.UserInputType.MouseButton1 then
			self:_SoltarCarga()
		elseif c.Fuente == "Tactil" and entrada == c.Input then
			self:_SoltarCarga()
		end
	end))
	-- Si la ventana pierde el foco, la carga se cancela sin patear.
	self.maid:GiveTask(UserInputService.WindowFocusReleased:Connect(function()
		self:_CancelarCarga()
	end))
end

-- ¿El clic (coordenadas de GUI) apunta al balón? Distancia del centro del balón al rayo de la cámara.
function FootballController:_ClicSobreBalon(posicion)
	local balon = self.balon
	local camara = workspace.CurrentCamera
	if not valida(balon) or not camara or typeof(posicion) ~= "Vector3" then
		return false
	end
	local ok, rayo = pcall(camara.ScreenPointToRay, camara, posicion.X, posicion.Y)
	if not ok or not rayo then
		return false
	end
	local origen = rayo.Origin
	local direccion = rayo.Direction.Unit
	local centro = balon.Position
	local t = (centro - origen):Dot(direccion)
	if t < 0 or t > self.DistanciaClicMax then
		return false
	end
	local cercano = origen + direccion * t
	return (centro - cercano).Magnitude <= self.RadioClicBalon
end

function FootballController:_FuerzaDe(segundos)
	local fraccion = math.clamp(segundos / math.max(0.05, self.CargaMaxSeg), 0, 1)
	return self.FuerzaMin + (self.FuerzaMaxima - self.FuerzaMin) * fraccion
end

function FootballController:_MostrarBarras(visible, valor, color)
	local ui = self.ui
	if not ui then
		return
	end
	ui.Barra.Frame.Visible = visible and not self.minimizado and not ui.Tactil
	if color then
		ui.Barra.Relleno.BackgroundColor3 = color
	end
	ui.Barra:Fijar(valor or 0, false)
	if ui.BarraTactil then
		ui.BarraTactil.Frame.Visible = visible
		ui.BarraTactil:Fijar(valor or 0, false)
	end
end

function FootballController:_IniciarCarga(fuente, entrada)
	if self.cargando or not self.enZona then
		return
	end
	if os.clock() < self.cooldownHasta then
		self:_Pista("Espera un momento antes de volver a patear.", "aviso")
		return
	end
	if not raizLocal() then
		return
	end
	local distancia = self:_DistanciaBalon()
	if not distancia then
		self:_Pista("No se encuentra el balón.", "aviso")
		return
	end
	if distancia > self.distanciaPatada then
		self:_Pista("Acércate al balón para patear.", "aviso")
		return
	end
	self.cargando = { Fuente = fuente, Inicio = os.clock(), Input = entrada }
	self:_MostrarBarras(true, 0, UITheme.Colores.Amarillo)
	self.maid.Carga = RunService.RenderStepped:Connect(function()
		local c = self.cargando
		if not c then
			return
		end
		local transcurrido = os.clock() - c.Inicio
		self:_MostrarBarras(true, math.clamp(transcurrido / math.max(0.05, self.CargaMaxSeg), 0, 1), nil)
		if transcurrido >= self.SoltarAutomaticoSeg then
			self:_SoltarCarga()
		end
	end)
	if self.ui and self.ui.Patear then
		UIBuilder.TextoBoton(self.ui.Patear, "SOLTAR")
	end
end

function FootballController:_CancelarCarga()
	self.cargando = nil
	if self.maid then
		self.maid.Carga = nil
	end
	self:_MostrarBarras(false, 0, nil)
end

function FootballController:_SoltarCarga()
	local c = self.cargando
	if not c then
		return
	end
	self.cargando = nil
	self.maid.Carga = nil
	local fuerza = self:_FuerzaDe(os.clock() - c.Inicio)
	self:_Patear(fuerza)
end

-- Dirección = (balón - jugador) horizontal mezclada 70/30 con la cámara (sin inclinación hacia el suelo).
function FootballController:_DireccionPatada(raiz, balon)
	local hacia = Vector3.new(balon.Position.X - raiz.Position.X, 0, balon.Position.Z - raiz.Position.Z)
	if hacia.Magnitude < 0.05 then
		local frente = raiz.CFrame.LookVector
		hacia = Vector3.new(frente.X, 0, frente.Z)
	end
	if hacia.Magnitude < 1e-3 then
		hacia = Vector3.new(0, 0, -1)
	end
	hacia = hacia.Unit
	local camara = workspace.CurrentCamera
	local mirada = hacia
	if camara then
		local look = camara.CFrame.LookVector
		local ajustada = Vector3.new(look.X, math.max(look.Y, 0), look.Z)
		if ajustada.Magnitude > 1e-3 then
			mirada = ajustada.Unit
		end
	end
	local direccion = hacia * self.MezclaBalon + mirada * (1 - self.MezclaBalon) + Vector3.new(0, self.ElevacionBase, 0)
	if direccion.Magnitude < 1e-3 then
		direccion = hacia
	end
	return direccion.Unit
end

function FootballController:_Patear(fuerza)
	local raiz = raizLocal()
	local balon = self.balon
	self:_MostrarBarras(false, 0, nil)
	if not raiz or not valida(balon) then
		return
	end
	if (raiz.Position - balon.Position).Magnitude > self.distanciaPatada then
		self:_Pista("El balón se alejó: acércate de nuevo.", "aviso")
		return
	end
	local direccion = self:_DireccionPatada(raiz, balon)
	fuerza = math.clamp(fuerza, 0, 1)
	task.spawn(function()
		local enviado = Net.Disparar("FootballKick", { Direccion = direccion, Fuerza = fuerza })
		if not enviado then
			self:_Pista("No se pudo enviar la patada.", "error")
		end
	end)
	-- Cooldown local: la patada queda deshabilitada mientras dure.
	local espera = self.cooldown + self.MargenCooldownSeg
	self.cooldownHasta = os.clock() + espera
	self.patearHabilitado = nil
	self:_MostrarBarras(true, 1, UITheme.Colores.Desactivado)
	pcall(self._RefrescarDinamico, self)
	task.delay(espera, function()
		if not self.cargando then
			self:_MostrarBarras(false, 0, nil)
		end
		self.patearHabilitado = nil
		pcall(self._RefrescarDinamico, self)
	end)
end

---------------------------------------------------------------------------------------------------
-- Acciones de equipo / partido
---------------------------------------------------------------------------------------------------
local TEXTOS_ACCION = {
	Unirse = "Te uniste al equipo",
	Salir = "Saliste del equipo.",
	Reiniciar = "Partido reiniciado.",
	Finalizar = "Partido finalizado.",
}

function FootballController:_Accion(accion, equipo, silencioso)
	if self.ocupado then
		return
	end
	self.ocupado = true
	self:_RefrescarBotones()
	task.spawn(function()
		local ok, respuesta = Net.Invocar("FootballAction", { Accion = accion, Equipo = equipo })
		self.ocupado = false
		if ok then
			local datos = respuesta and respuesta.datos
			if typeof(datos) == "table" then
				self:_AplicarEstado(datos)
			end
			if not silencioso and TEXTOS_ACCION[accion] then
				if accion == "Unirse" then
					local mio = miEquipo() or (typeof(datos) == "table" and datos.MiEquipo) or equipo
					self:_Pista(TEXTOS_ACCION.Unirse .. " " .. tostring(mio or "") .. ".", "exito")
				else
					self:_Pista(TEXTOS_ACCION[accion], "exito")
				end
			end
		elseif not silencioso then
			self:_Pista(UIBuilder.MensajeError(respuesta and respuesta.error), "error")
		end
		self:_Refrescar()
	end)
end

function FootballController:_AplicarEstado(estado)
	if typeof(estado) ~= "table" then
		return
	end
	self.estado = estado
	self.estadoRecibidoClock = os.clock()
	local distancia = numero(estado.DistanciaPatada)
	if distancia and distancia > 0 then
		self.distanciaPatada = distancia
	end
	local cooldown = numero(estado.CooldownPatada)
	if cooldown and cooldown > 0 then
		self.cooldown = cooldown
	end
	if typeof(estado.ZonaId) == "string" and Zones.Zona(estado.ZonaId) then
		self.zonaId = estado.ZonaId
	end
	self:_Refrescar()
end

---------------------------------------------------------------------------------------------------
-- Eventos del servidor (EventoCliente, Tipo "Futbol")
---------------------------------------------------------------------------------------------------
function FootballController:_AlEvento(datos)
	local sub = datos.Sub
	if sub == "Estado" then
		self:_AplicarEstado(datos.Estado)
	elseif sub == "Gol" then
		if self.estado and typeof(datos.Marcador) == "table" and datos.Amistoso ~= true then
			self.estado.Marcador = datos.Marcador
		end
		self:_EfectoGol(datos)
		self:_Refrescar()
	elseif sub == "Inicio" or sub == "Reinicio" then
		if self.estado then
			self.estado.Estado = "EnJuego"
			self.estado.Marcador = { A = 0, B = 0 }
			self.estado.InicioServidor = numero(datos.InicioServidor) or servidorAhora()
			self.estado.Duracion = numero(datos.Duracion) or self.duracion
			self.estado.AutoInicioServidor = nil
		end
		if sub == "Inicio" then
			self:_Notificar("¡Comienza el partido! Duración: " .. Format.Duracion(numero(datos.Duracion) or self.duracion) .. ".", "exito", 4)
			-- En teléfonos el panel se compacta durante el partido para dejar ver la cancha.
			if self.ui and self.ui.Tactil and UIBuilder.EsEstrecho() and not self.minimizado then
				self.autoMinimizado = true
				self:_Minimizar(true)
			end
		else
			self:_Pista("El árbitro reinició el partido.", "info")
		end
		self:_Refrescar()
	elseif sub == "Fin" then
		local marcador = typeof(datos.Marcador) == "table" and datos.Marcador or { A = 0, B = 0 }
		if self.estado then
			self.estado.Estado = "Terminado"
			self.estado.Marcador = marcador
			self.estado.UltimoResultado = { Goles = marcador, Ganador = datos.Ganador, Motivo = datos.Motivo }
		end
		local texto = "Final del partido: "
		if datos.Ganador == "A" or datos.Ganador == "B" then
			texto = texto .. "gana el " .. Format.Equipo(datos.Ganador)
		else
			texto = texto .. "empate"
		end
		texto = texto .. " (" .. Format.Marcador(marcador.A or 0, marcador.B or 0) .. ")."
		if typeof(datos.Motivo) == "string" and datos.Motivo ~= "" then
			texto = texto .. " " .. datos.Motivo .. "."
		end
		self:_Notificar(texto, "info", 6)
		if self.autoMinimizado then
			self.autoMinimizado = false
			self:_Minimizar(false)
		end
		self:_Refrescar()
	elseif sub == "PatadaRechazada" then
		self:_Pista(typeof(datos.Texto) == "string" and datos.Texto or "Patada no válida.", "aviso")
	elseif sub == "Rescate" then
		self:_Pista("El balón volvió al centro de la cancha.", "info")
	elseif sub == "Saque" then
		self:_Pista("¡Saque desde el centro!", "info")
	end
end

-- Efecto local de gol: rótulo animado (respeta MovimientoReducido) y sonido Config.Sonidos.Gol si existe.
function FootballController:_EfectoGol(datos)
	local ui = self.ui
	if not ui or not self.enZona then
		return
	end
	self.tokenGol = self.tokenGol + 1
	local token = self.tokenGol
	local equipo = datos.Equipo
	local color = UITheme.Colores.Amarillo
	if equipo == "A" then
		color = self.colorA
	elseif equipo == "B" then
		color = self.colorB
	end
	if datos.Amistoso then
		ui.GolTitulo.Text = "¡GOL! (amistoso)"
	else
		ui.GolTitulo.Text = "¡GOL!"
	end
	local detalle = Format.Equipo(equipo)
	if typeof(datos.Autor) == "string" and datos.Autor ~= "" then
		detalle = detalle .. " · " .. datos.Autor
	end
	if datos.Autogol then
		detalle = detalle .. " (autogol)"
	end
	if datos.Amistoso ~= true and typeof(datos.Marcador) == "table" then
		detalle = detalle .. "  ·  " .. Format.Marcador(datos.Marcador.A or 0, datos.Marcador.B or 0)
	end
	ui.GolDetalle.Text = detalle
	ui.GolBorde.Color = color
	ui.GolMarco.Visible = true
	UIBuilder.Aparecer(ui.GolMarco)
	UIBuilder.Sonido("Gol", 0.6)
	task.delay(self.DuracionGolSeg, function()
		if self.tokenGol == token and self.ui and valida(self.ui.GolMarco) then
			UIBuilder.Desaparecer(self.ui.GolMarco)
		end
	end)
end

return FootballController
]=] }
FUENTES["StarterPlayer/StarterPlayerScripts/ColegioRP/Controllers/HUDController"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: StarterPlayer.StarterPlayerScripts.ColegioRP.Controllers.HUDController
	Tipo: ModuleScript
	HUD del jugador: hora real del dispositivo (aprox., 12/24 h), hora escolar y estado de la jornada interpolados
	con workspace:GetServerTimeNow(), cargo, salón, próxima actividad, avisos oficiales, saldo, botones (Menú,
	Cuaderno, Panel de cargo), acciones contextuales y minimizar. Solo renderiza: el servidor es la autoridad.
]]

local Players = game:GetService("Players")

local HUDController = {}
HUDController.Nombre = "HUDController"
HUDController.MaxAvisos = 3 -- Avisos oficiales visibles en el HUD.

local UIBuilder, UITheme, Net, Maid, Format, RoleDefinitions, TimetableDefinitions, MapaLogico, Config

local player = Players.LocalPlayer

local function requerir(padre, nombre)
	if not padre then
		error("no se encontró la carpeta para " .. nombre)
	end
	local modulo = padre:FindFirstChild(nombre) or padre:WaitForChild(nombre, 10)
	if not modulo then
		error("no se encontró el módulo " .. nombre)
	end
	return require(modulo)
end

local function numero(valor)
	local n = tonumber(valor)
	if n == nil or n ~= n or n == math.huge or n == -math.huge then
		return nil
	end
	return n
end

-- string.upper que también convierte las vocales acentuadas y la ñ (UTF-8).
local ACENTOS = { ["á"] = "Á", ["é"] = "É", ["í"] = "Í", ["ó"] = "Ó", ["ú"] = "Ú", ["ñ"] = "Ñ", ["ü"] = "Ü" }
local function mayusculas(valor)
	local resultado = string.upper(tostring(valor or ""))
	for minuscula, mayuscula in pairs(ACENTOS) do
		resultado = string.gsub(resultado, minuscula, mayuscula)
	end
	return resultado
end

-- Hora del servidor sincronizada (segundos Unix con decimales); respaldo: reloj local.
local function ahoraServidor()
	local ok, valor = pcall(function()
		return workspace:GetServerTimeNow()
	end)
	if ok and typeof(valor) == "number" then
		return valor
	end
	return os.time()
end

-- Acepta segundos del día (número) o "HH:MM" (texto); nil si no es válido.
local function segundosDeHora(valor)
	local n = numero(valor)
	if n then
		return n
	end
	if typeof(valor) == "string" then
		return TimetableDefinitions.HHMMASegundos(valor)
	end
	return nil
end

-- Segundos hasta el siguiente cambio de segundo del reloj (para refrescar en el momento justo).
local function esperaAlSiguienteSegundo()
	local ok, ms = pcall(function()
		return DateTime.now().UnixTimestampMillis
	end)
	if ok and typeof(ms) == "number" then
		return math.max(0.05, (1000 - (ms % 1000)) / 1000 + 0.02)
	end
	return 1
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function HUDController:Init(registro)
	self.registro = registro
	Config = registro.Config
	UIBuilder = registro.UIBuilder
	if not UIBuilder then
		error("UIBuilder no está disponible")
	end
	local Shared = registro.Shared
	local Util = Shared:FindFirstChild("Util") or Shared:WaitForChild("Util", 10)
	UITheme = requerir(Shared, "UITheme")
	RoleDefinitions = requerir(Shared, "RoleDefinitions")
	TimetableDefinitions = requerir(Shared, "TimetableDefinitions")
	MapaLogico = requerir(Shared, "MapaLogico")
	Net = requerir(Util, "Net")
	Maid = requerir(Util, "Maid")
	Format = requerir(Util, "Format")

	self.maid = Maid.new()
	self.jornada = nil
	self.progresoCongelado = nil
	self.cargo = player:GetAttribute("Cargo")
	self.salon = player:GetAttribute("Salon")
	self.saldo = nil
	self.avisos = {}
	self.acciones = {}
	self.ordenAcciones = 0
	self.minimizado = false
	self.visible = true
	self.activo = true
	self:_Construir()
	self:_RefrescarTodo()
end

function HUDController:Start()
	-- Atributos replicados del jugador (los fija el servidor).
	self.maid:GiveTask(player:GetAttributeChangedSignal("Cargo"):Connect(function()
		self:FijarCargo(player:GetAttribute("Cargo"), nil)
	end))
	self.maid:GiveTask(player:GetAttributeChangedSignal("Salon"):Connect(function()
		local salon = player:GetAttribute("Salon")
		if salon == nil then
			salon = false
		end
		self:FijarCargo(nil, salon)
	end))
	self.maid:GiveTask(player:GetAttributeChangedSignal("CertificadoLocal"):Connect(function()
		self:_RefrescarCargo()
	end))
	self.maid:GiveTask(player:GetAttributeChangedSignal("Atendido"):Connect(function()
		self:_RefrescarAtendido()
	end))

	-- Reloj: una actualización por segundo (no por fotograma).
	self.maid:GiveTask(task.spawn(function()
		while self.activo do
			local ok, err = pcall(self._ActualizarReloj, self)
			if not ok then
				warn("[ColegioRP] HUDController: " .. tostring(err))
			end
			task.wait(esperaAlSiguienteSegundo())
		end
	end))

	-- Canal servidor -> cliente.
	task.spawn(function()
		local remoto = Net.Evento("EventoCliente")
		if not remoto then
			warn("[ColegioRP] HUDController: EventoCliente no disponible; el HUD no recibirá actualizaciones.")
			return
		end
		self.maid:GiveTask(remoto.OnClientEvent:Connect(function(carga)
			if typeof(carga) ~= "table" or typeof(carga.Tipo) ~= "string" then
				return
			end
			local datos = carga.Datos
			if typeof(datos) ~= "table" then
				datos = {}
			end
			local ok, err = true, nil
			if carga.Tipo == "Jornada" then
				ok, err = pcall(self.FijarEstado, self, datos)
			elseif carga.Tipo == "Rol" then
				ok, err = pcall(self._AplicarRol, self, datos)
			elseif carga.Tipo == "Economia" then
				ok, err = pcall(self._FijarSaldo, self, datos.Saldo)
			elseif carga.Tipo == "Aviso" then
				ok, err = pcall(self._AgregarAviso, self, datos)
			end
			if not ok then
				warn("[ColegioRP] HUDController: " .. tostring(err))
			end
		end))
	end)

	-- Snapshot inicial (con reintentos si el servidor todavía no está listo o se superó el límite).
	task.spawn(function()
		local esperas = { 0, 3, 6 }
		for intento, espera in ipairs(esperas) do
			if not self.activo then
				return
			end
			if espera > 0 then
				task.wait(espera)
			end
			local ok, respuesta = Net.Invocar("StateSnapshot", {})
			if ok and typeof(respuesta.datos) == "table" then
				self.snapshot = respuesta.datos
				local okAplicar, err = pcall(self._AplicarSnapshot, self, respuesta.datos)
				if not okAplicar then
					warn("[ColegioRP] HUDController: " .. tostring(err))
				end
				return
			end
			if intento == #esperas then
				warn("[ColegioRP] HUDController: no se pudo obtener StateSnapshot: " .. tostring(respuesta and respuesta.error))
			end
		end
	end)
end

-- Libera conexiones, el hilo del reloj y la pantalla.
function HUDController:Destruir()
	self.activo = false
	if self.maid then
		self.maid:DoCleaning()
	end
	UIBuilder.Destruir(self.gui)
end

---------------------------------------------------------------------------------------------------
-- Construcción de la interfaz
---------------------------------------------------------------------------------------------------
local function etiqueta(parent, contenido, orden, props)
	props = props or {}
	props.LayoutOrder = orden
	return UIBuilder.Texto(parent, contenido, props)
end

function HUDController:_Construir()
	local gui = UIBuilder.Pantalla("HUD", (UITheme.Capas and UITheme.Capas.HUD) or 10)
	self.gui = gui
	self.maid:GiveTask(gui)
	local contenido = UIBuilder.Contenedor(gui, { Nombre = "Contenido" })
	self.contenido = contenido
	local estrecho = UIBuilder.EsEstrecho()
	local Colores = UITheme.Colores

	-----------------------------------------------------------------------------------------------
	-- Esquina superior izquierda: horas, estado, cargo, salón, saldo y avisos
	-----------------------------------------------------------------------------------------------
	local info = Instance.new("Frame")
	info.Name = "Info"
	info.BackgroundColor3 = Colores.GrisPanel
	info.BackgroundTransparency = 0.2
	info.BorderSizePixel = 0
	info.Size = UDim2.new(0, estrecho and 214 or 262, 0, 0)
	info.AutomaticSize = Enum.AutomaticSize.Y
	info.Position = UDim2.new(0, 0, 0, 0)
	UIBuilder.Esquinas(info, UITheme.Radio)
	UIBuilder.Borde(info, Colores.Borde, 1, 0.3)
	UIBuilder.Relleno(info, 6, 8, 10, 6)
	UIBuilder.Disposicion(info, { Espaciado = 2 })
	info.Parent = contenido
	self.info = info

	local altoCabecera = 28
	if UIBuilder.EsTactil() then
		altoCabecera = UIBuilder.AltoBoton()
	end
	local cabecera = UIBuilder.Marco(info, { Alto = altoCabecera, Nombre = "Cabecera", LayoutOrder = 1 })
	UIBuilder.Texto(cabecera, mayusculas(Config.NombreCorto or "Colegio Jean Piaget"), {
		Nombre = "Colegio", Tamano = "Etiqueta", Fuente = "Titulo", Color = Colores.TextoSecundario,
		AutoAlto = false, Ajustar = false, Truncar = true, AlineacionY = Enum.TextYAlignment.Center,
		Size = UDim2.new(1, -44, 1, 0),
	})
	self.botonMinimizar = UIBuilder.Boton(cabecera, "–", function()
		self:Minimizar(not self.minimizado)
	end, {
		Estilo = "Fantasma", Ancho = 40, Alto = altoCabecera, Nombre = "Minimizar", Tamano = "Subtitulo",
		Position = UDim2.new(1, 4, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5),
	})

	self.lblHoraReal = etiqueta(info, "Hora real: --:-- (aprox.)", 2, { Tamano = "Pequeno", Color = Colores.TextoSecundario, Nombre = "HoraReal" })
	self.sepHora = UIBuilder.Espacio(info, 4, 3)
	self.lblHoraEscolar = etiqueta(info, "Hora escolar: --:--", 4, { Tamano = "Subtitulo", Fuente = "Titulo", Nombre = "HoraEscolar" })
	self.lblEstado = etiqueta(info, "Estado: esperando datos…", 5, { Tamano = "Pequeno", Nombre = "Estado" })
	self.lblProxima = etiqueta(info, "Próxima actividad: —", 6, { Tamano = "Pequeno", Color = Colores.TextoSecundario, Nombre = "Proxima" })
	self.sepDatos = UIBuilder.Separador(info, { LayoutOrder = 7, Color = Colores.Borde })
	self.lblCargo = etiqueta(info, "Cargo: —", 8, { Tamano = "Pequeno", Nombre = "Cargo" })
	self.lblSalon = etiqueta(info, "Salón: sin asignar", 9, { Tamano = "Pequeno", Nombre = "Salon" })
	self.lblSaldo = etiqueta(info, "Saldo: —", 10, { Tamano = "Pequeno", Color = Colores.Amarillo, Nombre = "Saldo" })
	self.etqAtendido = UIBuilder.Etiqueta(info, "Atendido en enfermería", Colores.Verde, { LayoutOrder = 11, Nombre = "Atendido", Visible = false })

	local avisos = UIBuilder.Marco(info, { Nombre = "Avisos", AutoAlto = true, LayoutOrder = 12 })
	UIBuilder.Disposicion(avisos, { Espaciado = 2 })
	avisos.Visible = false
	UIBuilder.Separador(avisos, { LayoutOrder = 0, Color = Colores.Borde })
	UIBuilder.Texto(avisos, "AVISOS OFICIALES", { Tamano = "Etiqueta", Fuente = "Titulo", Color = Colores.Amarillo, LayoutOrder = 1, Nombre = "TituloAvisos" })
	self.marcoAvisos = avisos
	self.lblAvisos = {}
	for i = 1, self.MaxAvisos do
		self.lblAvisos[i] = UIBuilder.Texto(avisos, "", { Tamano = "Pequeno", LayoutOrder = 1 + i, Nombre = "Aviso" .. i, Visible = false })
	end

	-- Filas que se ocultan al minimizar (quedan la hora escolar y el estado).
	self.detalles = { self.lblHoraReal, self.sepHora, self.lblProxima, self.sepDatos, self.lblCargo, self.lblSalon, self.lblSaldo }

	-----------------------------------------------------------------------------------------------
	-- Esquina superior derecha: botones
	-----------------------------------------------------------------------------------------------
	local anchoBoton = estrecho and 120 or 148
	local botones = UIBuilder.Marco(contenido, {
		Nombre = "Botones", AutoAlto = true,
		Size = UDim2.new(0, anchoBoton, 0, 0),
		Position = UDim2.new(1, 0, 0, 0), AnchorPoint = Vector2.new(1, 0),
	})
	UIBuilder.Disposicion(botones, { Espaciado = 6, Alineacion = Enum.HorizontalAlignment.Right })
	self.botonMenu = UIBuilder.Boton(botones, "Menú", function()
		self:_AbrirMenu()
	end, { Estilo = "Primario", Icono = "☰", Ancho = anchoBoton, LayoutOrder = 1, Nombre = "Menu" })
	self.botonCuaderno = UIBuilder.Boton(botones, "Cuaderno", function()
		self:_AbrirCuaderno()
	end, { Estilo = "Secundario", Ancho = anchoBoton, LayoutOrder = 2, Nombre = "Cuaderno" })
	self.botonPanel = UIBuilder.Boton(botones, "Panel de cargo", function()
		self:_AbrirPanelCargo()
	end, { Estilo = "Secundario", Ancho = anchoBoton, LayoutOrder = 3, Nombre = "PanelCargo", Visible = false })
	UIBuilder.Encadenar({ self.botonMenu, self.botonCuaderno, self.botonPanel })

	-----------------------------------------------------------------------------------------------
	-- Inferior centro: acciones contextuales (por encima de los controles táctiles)
	-----------------------------------------------------------------------------------------------
	local filaAcciones = UIBuilder.Marco(contenido, {
		Nombre = "Acciones", Alto = UIBuilder.AltoBoton(),
		Position = UDim2.new(0.5, 0, 1, 0), AnchorPoint = Vector2.new(0.5, 1),
	})
	UIBuilder.Disposicion(filaAcciones, { Horizontal = true, Espaciado = 8, Alineacion = Enum.HorizontalAlignment.Center })
	filaAcciones.Visible = false
	self.filaAcciones = filaAcciones
end

---------------------------------------------------------------------------------------------------
-- Refrescos de texto
---------------------------------------------------------------------------------------------------
function HUDController:_Ajustes()
	local Settings = self.registro and self.registro.Get("SettingsController")
	if Settings and typeof(Settings.Ajustes) == "function" then
		local ok, ajustes = pcall(Settings.Ajustes, Settings)
		if ok and typeof(ajustes) == "table" then
			return ajustes
		end
	end
	return {}
end

function HUDController:_Formato12()
	local formato = tonumber(self:_Ajustes().FormatoHora)
	return formato == 12
end

-- Calcula hora escolar (segundos del día), segundos restantes del periodo y progreso a partir del snapshot.
function HUDController:_CalcularJornada()
	local j = self.jornada
	if typeof(j) ~= "table" or typeof(j.Estado) ~= "string" then
		return nil
	end
	local inicio = segundosDeHora(j.HoraEscolarInicio) or TimetableDefinitions.HoraEscolarSegundos(j.Estado) or 0
	local fin = segundosDeHora(j.HoraEscolarFin) or TimetableDefinitions.HoraEscolarFinSegundos(j.Estado) or inicio
	local duracion = numero(j.Duracion)
	if duracion == nil then
		local periodo = TimetableDefinitions.Periodo(j.Estado)
		duracion = periodo and periodo.Duracion or 0
	end
	local progreso = 0
	local transcurrido = 0
	if j.Pausada == true then
		progreso = self.progresoCongelado or 0
		transcurrido = progreso * duracion
	else
		local inicioServidor = numero(j.InicioServidor)
		if inicioServidor then
			transcurrido = ahoraServidor() - inicioServidor
		end
		if duracion > 0 then
			progreso = transcurrido / duracion
		end
	end
	progreso = math.clamp(progreso, 0, 1)
	local hora = inicio + (fin - inicio) * progreso
	local restante = math.max(0, duracion - transcurrido)
	return hora, restante, progreso
end

function HUDController:_ActualizarReloj()
	if not self.lblHoraReal or self.lblHoraReal.Parent == nil then
		return
	end
	local formato12 = self:_Formato12()
	local t = os.date("*t")
	local segundosDia = 0
	if typeof(t) == "table" then
		segundosDia = (t.hour or 0) * 3600 + (t.min or 0) * 60
	end
	self.lblHoraReal.Text = "Hora real: " .. Format.HoraHHMM(segundosDia, formato12) .. " (aprox.)"

	local hora, restante = self:_CalcularJornada()
	if hora == nil then
		self.lblHoraEscolar.Text = "Hora escolar: --:--"
		self.lblEstado.Text = "Estado: esperando datos de la jornada…"
		return
	end
	local j = self.jornada
	self.lblHoraEscolar.Text = "Hora escolar: " .. Format.HoraHHMM(hora, formato12)
	local nombre = j.Nombre
	if typeof(nombre) ~= "string" or nombre == "" then
		nombre = TimetableDefinitions.Nombre(j.Estado)
	end
	local partes = { "Estado: " .. nombre }
	if typeof(j.Materia) == "string" and j.Materia ~= "" then
		table.insert(partes, " · " .. TimetableDefinitions.NombreMateria(j.Materia))
	end
	if j.Pausada == true then
		-- SchoolDayService marca Pausada también mientras espera el inicio (EnEspera / MotivoPausa "espera_inicio").
		if j.EnEspera == true or j.MotivoPausa == "espera_inicio" then
			table.insert(partes, " (esperando inicio)")
		else
			table.insert(partes, " (en pausa)")
		end
	else
		table.insert(partes, " (" .. Format.Tiempo(restante) .. ")")
	end
	if j.Modo == "Manual" then
		table.insert(partes, " · manual")
	end
	self.lblEstado.Text = table.concat(partes)
end

function HUDController:_RefrescarProxima()
	local j = self.jornada
	local proximo = nil
	if typeof(j) == "table" then
		proximo = j.ProximoNombre
		if (typeof(proximo) ~= "string" or proximo == "") and typeof(j.Estado) == "string" then
			proximo = TimetableDefinitions.Nombre(TimetableDefinitions.Siguiente(j.Estado))
		end
	end
	if typeof(proximo) ~= "string" or proximo == "" then
		proximo = "—"
	end
	self.lblProxima.Text = "Próxima actividad: " .. Format.Truncar(proximo, 40)
end

function HUDController:_RefrescarCargo()
	local cargo = self.cargo
	if typeof(cargo) == "string" and cargo ~= "" then
		self.lblCargo.Text = "Cargo: " .. RoleDefinitions.Nombre(cargo)
	else
		self.lblCargo.Text = "Cargo: sin elegir"
	end
	local salon = self.salon
	if typeof(salon) == "string" and salon ~= "" then
		local zona = MapaLogico.Zonas and MapaLogico.Zonas[salon]
		local textoSalon = salon
		if zona and typeof(zona.Nombre) == "string" and zona.Nombre ~= salon then
			textoSalon = salon .. " · " .. zona.Nombre
		end
		local certificado = player:GetAttribute("CertificadoLocal")
		if typeof(certificado) == "string" and certificado ~= "" then
			textoSalon = textoSalon .. " (" .. (string.match(certificado, "^Certificado (%S+)") or certificado) .. ")"
		end
		self.lblSalon.Text = "Salón: " .. Format.Truncar(textoSalon, 60)
	else
		self.lblSalon.Text = "Salón: sin asignar"
	end
	-- El panel de cargo solo aparece para cargos distintos de Estudiante.
	local esPersonal = RoleDefinitions.Existe(cargo) and cargo ~= "Estudiante"
	if self.botonPanel then
		self.botonPanel.Visible = esPersonal == true
	end
end

function HUDController:_RefrescarSaldo()
	if self.saldo == nil then
		self.lblSaldo.Text = "Saldo: —"
	else
		self.lblSaldo.Text = "Saldo: " .. Format.Moneda(self.saldo)
	end
end

function HUDController:_RefrescarAtendido()
	if self.etqAtendido then
		self.etqAtendido.Visible = player:GetAttribute("Atendido") == true
	end
end

function HUDController:_RefrescarAvisos()
	local total = #self.avisos
	for i = 1, self.MaxAvisos do
		local lbl = self.lblAvisos[i]
		-- El más reciente primero.
		local aviso = self.avisos[total - i + 1]
		if aviso then
			local firma = ""
			if aviso.Cargo ~= "" or aviso.Autor ~= "" then
				firma = "[" .. Format.Recortar(aviso.Cargo .. " " .. aviso.Autor) .. "] "
			end
			lbl.Text = "• " .. firma .. aviso.Texto
			lbl.Visible = true
		else
			lbl.Text = ""
			lbl.Visible = false
		end
	end
	self.marcoAvisos.Visible = total > 0 and not self.minimizado
end

function HUDController:_RefrescarTodo()
	pcall(self._ActualizarReloj, self)
	self:_RefrescarProxima()
	self:_RefrescarCargo()
	self:_RefrescarSaldo()
	self:_RefrescarAtendido()
	self:_RefrescarAvisos()
end

---------------------------------------------------------------------------------------------------
-- Datos del servidor
---------------------------------------------------------------------------------------------------
function HUDController:_AplicarSnapshot(datos)
	if typeof(datos.Jornada) == "table" then
		self:FijarEstado(datos.Jornada)
	end
	if typeof(datos.Rol) == "table" then
		self:_AplicarRol(datos.Rol)
	elseif typeof(datos.Rol) == "string" then
		self:FijarCargo(datos.Rol, nil)
	end
	if typeof(datos.Economia) == "table" then
		self:_FijarSaldo(datos.Economia.Saldo)
	end
	if typeof(datos.Anuncios) == "table" then
		local inicio = math.max(1, #datos.Anuncios - self.MaxAvisos + 1)
		for i = inicio, #datos.Anuncios do
			local anuncio = datos.Anuncios[i]
			if typeof(anuncio) == "table" then
				self:_AgregarAviso(anuncio, true)
			end
		end
		self:_RefrescarAvisos()
	end
end

function HUDController:_AplicarRol(datos)
	local salon = datos.Salon
	if salon == nil then
		salon = player:GetAttribute("Salon")
	end
	if salon == nil then
		salon = false
	end
	self:FijarCargo(datos.Cargo, salon)
end

function HUDController:_FijarSaldo(saldo)
	local n = numero(saldo)
	if n == nil then
		return
	end
	self.saldo = math.floor(n)
	self:_RefrescarSaldo()
end

function HUDController:_AgregarAviso(datos, sinRefrescar)
	if typeof(datos) ~= "table" or typeof(datos.Texto) ~= "string" or datos.Texto == "" then
		return
	end
	local cargo = ""
	if typeof(datos.Cargo) == "string" and datos.Cargo ~= "" then
		if RoleDefinitions.Existe(datos.Cargo) then
			cargo = RoleDefinitions.Nombre(datos.Cargo)
		else
			cargo = Format.Truncar(datos.Cargo, 24)
		end
	end
	local autor = ""
	if typeof(datos.Autor) == "string" then
		autor = Format.Truncar(datos.Autor, 24)
	end
	table.insert(self.avisos, {
		Texto = Format.Truncar(datos.Texto, 100),
		Cargo = cargo,
		Autor = autor,
		Alcance = datos.Alcance,
	})
	while #self.avisos > self.MaxAvisos do
		table.remove(self.avisos, 1)
	end
	if not sinRefrescar then
		self:_RefrescarAvisos()
	end
end

---------------------------------------------------------------------------------------------------
-- Botones
---------------------------------------------------------------------------------------------------
function HUDController:_Notificar(texto, nivel)
	local Notificaciones = self.registro and self.registro.Get("NotificationController")
	if Notificaciones and typeof(Notificaciones.Notificar) == "function" then
		pcall(Notificaciones.Notificar, Notificaciones, texto, nivel)
	end
end

function HUDController:_AbrirMenu()
	local Menu = self.registro.Get("MenuController")
	if Menu and typeof(Menu.Abrir) == "function" then
		Menu:Abrir()
	else
		self:_Notificar("El menú principal no está disponible.", "aviso")
	end
end

function HUDController:_AbrirCuaderno()
	local Aula = self.registro.Get("ClassroomController")
	if Aula and typeof(Aula.AbrirCuaderno) == "function" then
		Aula:AbrirCuaderno()
	else
		self:_Notificar("Disponible en el aula", "info")
	end
end

function HUDController:_AbrirPanelCargo()
	local Staff = self.registro.Get("StaffController")
	if Staff and typeof(Staff.Abrir) == "function" then
		Staff:Abrir()
	else
		self:_Notificar("El panel de cargo no está disponible todavía.", "aviso")
	end
end

---------------------------------------------------------------------------------------------------
-- API pública
---------------------------------------------------------------------------------------------------

-- Aplica un snapshot de jornada { Estado, Nombre, Indice, InicioServidor, Duracion, HoraEscolarInicio,
-- HoraEscolarFin, Materia, Pausada, ProximoNombre, Modo }. Si Pausada, el reloj escolar no avanza.
function HUDController:FijarEstado(snapshot)
	if typeof(snapshot) ~= "table" or typeof(snapshot.Estado) ~= "string" then
		return
	end
	-- Descarta snapshots más antiguos que el último aplicado (p. ej. la respuesta de StateSnapshot que llega
	-- después de un evento "Jornada" más reciente): evita saltos hacia atrás del reloj escolar.
	local horaSnapshot = numero(snapshot.HoraServidor)
	if horaSnapshot and self.horaUltimaJornada and horaSnapshot < self.horaUltimaJornada then
		return
	end
	if horaSnapshot then
		self.horaUltimaJornada = horaSnapshot
	end
	local copia = {}
	for clave, valor in pairs(snapshot) do
		copia[clave] = valor
	end
	self.jornada = copia
	self.progresoCongelado = nil
	if copia.Pausada == true then
		local duracion = numero(copia.Duracion) or 0
		local transcurrido = numero(copia.Transcurrido)
		if transcurrido == nil then
			local inicioServidor = numero(copia.InicioServidor)
			transcurrido = inicioServidor and (ahoraServidor() - inicioServidor) or 0
		end
		if duracion > 0 then
			self.progresoCongelado = math.clamp(transcurrido / duracion, 0, 1)
		else
			self.progresoCongelado = 0
		end
	end
	self:_RefrescarProxima()
	pcall(self._ActualizarReloj, self)
end

-- Fija el cargo (id de RoleDefinitions) y el salón (id de zona de MapaLogico). nil conserva el valor;
-- false o "" en salon lo borra.
function HUDController:FijarCargo(cargo, salon)
	if typeof(cargo) == "string" and cargo ~= "" then
		self.cargo = cargo
	end
	if salon == false or salon == "" then
		self.salon = nil
	elseif typeof(salon) == "string" then
		self.salon = salon
	end
	self:_RefrescarCargo()
end

-- Añade (callback = función) o quita (callback = nil) un botón de acción contextual en la fila inferior.
-- Devuelve el botón creado (o nil al quitar).
function HUDController:AccionContextual(nombre, callback)
	if typeof(nombre) ~= "string" or nombre == "" then
		return nil
	end
	local existente = self.acciones[nombre]
	if existente then
		self.acciones[nombre] = nil
		UIBuilder.Destruir(existente)
	end
	local resultado = nil
	if typeof(callback) == "function" then
		self.ordenAcciones = self.ordenAcciones + 1
		local longitud = utf8.len(nombre) or #nombre
		local ancho = math.clamp(longitud * 9 + 40, 110, 260)
		resultado = UIBuilder.Boton(self.filaAcciones, nombre, function()
			callback()
		end, { Estilo = "Primario", Ancho = ancho, LayoutOrder = self.ordenAcciones, Nombre = "Accion_" .. nombre })
		self.acciones[nombre] = resultado
	end
	local hay = next(self.acciones) ~= nil
	self.filaAcciones.Visible = hay
	return resultado
end

-- Muestra u oculta todo el HUD.
function HUDController:Visible(visible)
	self.visible = visible ~= false
	if self.gui and self.gui.Parent then
		self.gui.Enabled = self.visible
	end
	if not self.visible then
		UIBuilder.Desenfocar(self.gui)
	end
end

-- ¿El HUD está visible?
function HUDController:EstaVisible()
	return self.visible == true
end

-- Minimiza (true) o expande (false) el panel de información.
function HUDController:Minimizar(minimizado)
	self.minimizado = minimizado == true
	for _, fila in ipairs(self.detalles) do
		if fila and fila.Parent then
			fila.Visible = not self.minimizado
		end
	end
	self:_RefrescarAvisos()
	if self.minimizado then
		UIBuilder.TextoBoton(self.botonMinimizar, "+")
	else
		UIBuilder.TextoBoton(self.botonMinimizar, "–")
	end
end

-- Último snapshot completo recibido de StateSnapshot (o nil).
function HUDController:Snapshot()
	return self.snapshot
end

return HUDController
]=] }
FUENTES["StarterPlayer/StarterPlayerScripts/ColegioRP/Controllers/HelpController"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: StarterPlayer.StarterPlayerScripts.ColegioRP.Controllers.HelpController
	Tipo: ModuleScript
	Panel de AYUDA: secciones de Catalogs.Ayuda (lista a la izquierda o pestañas en pantallas estrechas),
	párrafos con desplazamiento, controles del dispositivo detectado (Catalogs.Controles), preguntas
	frecuentes (Catalogs.FAQ) y búsqueda simple por texto (sin distinguir mayúsculas ni tildes).
]]

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local TIMEOUT = 30
local function esperarHijo(padre, nombre)
	local hijo = nil
	if padre then
		hijo = padre:FindFirstChild(nombre) or padre:WaitForChild(nombre, TIMEOUT)
	end
	if not hijo then
		error("[ColegioRP][HelpController] No apareció '" .. tostring(nombre) .. "' en " .. TIMEOUT .. " s")
	end
	return hijo
end

local RP = esperarHijo(ReplicatedStorage, "ColegioRP")
local Shared = esperarHijo(RP, "Shared")
local Util = esperarHijo(Shared, "Util")
local UITheme = require(esperarHijo(Shared, "UITheme"))
local Catalogs = require(esperarHijo(Shared, "Catalogs"))
local Signal = require(esperarHijo(Util, "Signal"))
local Maid = require(esperarHijo(Util, "Maid"))
local Format = require(esperarHijo(Util, "Format"))
local UIBuilder = require(esperarHijo(esperarHijo(script.Parent.Parent, "UI"), "UIBuilder"))

local Colores = UITheme.Colores

local HelpController = {}
HelpController.Nombre = "HelpController"
HelpController.Abierto = Signal.new()
HelpController.Cerrado = Signal.new()

---------------------------------------------------------------------------------------------------
-- Constantes y datos
---------------------------------------------------------------------------------------------------
local LOG = "[ColegioRP][HelpController] "
-- Capa de paneles (50). MenuController oculta su fondo al delegar, así que el panel queda visible.
local ORDEN_PANTALLA = UITheme.Capas.Panel
local ANCHO_LISTA = 230
local MAX_BUSQUEDA = 40
local MIN_BUSQUEDA = 2
local MAX_PARRAFOS_RESULTADO = 3
local ESPERA_BUSQUEDA = 0.25

local SECCIONES = Catalogs.Ayuda or {}
local FAQ = Catalogs.FAQ or {}
local CONTROLES = Catalogs.Controles or {}

-- Catalogs.Controles tiene PC, Movil y Mando; la tableta usa los controles táctiles.
local CLAVE_CONTROLES = { PC = "PC", Movil = "Movil", Tableta = "Movil", Mando = "Mando" }
local PLATAFORMAS = {
	{ Clave = "PC", Texto = "PC" },
	{ Clave = "Movil", Texto = "Móvil / tableta" },
	{ Clave = "Mando", Texto = "Mando" },
}
local NOMBRE_PLATAFORMA = { PC = "PC (teclado y ratón)", Movil = "móvil o tableta (táctil)", Mando = "mando" }

---------------------------------------------------------------------------------------------------
-- Estado
---------------------------------------------------------------------------------------------------
local activo = false
local abierto = false
local maidPanel = Maid.new()
local ui = {
	Gui = nil, Panel = nil, Busqueda = nil, Contenido = nil, Botones = {}, Estrecho = nil,
}
local seccionActual = nil
local plataformaControles = nil
local consultaActual = ""
local generacionBusqueda = 0

---------------------------------------------------------------------------------------------------
-- Utilidades de texto
---------------------------------------------------------------------------------------------------
local REEMPLAZOS = {
	{ "á", "a" }, { "é", "e" }, { "í", "i" }, { "ó", "o" }, { "ú", "u" }, { "ü", "u" }, { "ñ", "n" },
	{ "Á", "a" }, { "É", "e" }, { "Í", "i" }, { "Ó", "o" }, { "Ú", "u" }, { "Ü", "u" }, { "Ñ", "n" },
}

-- Minúsculas y sin tildes, para comparar sin distinguir mayúsculas ni acentos.
local function normalizar(texto)
	local resultado = string.lower(tostring(texto or ""))
	for _, par in ipairs(REEMPLAZOS) do
		resultado = string.gsub(resultado, par[1], par[2])
	end
	return resultado
end

-- Palabras de la consulta (separadas por espacios), ya normalizadas.
local function terminos(consulta)
	local lista = {}
	for palabra in string.gmatch(normalizar(consulta), "%S+") do
		table.insert(lista, palabra)
	end
	return lista
end

-- ¿El texto contiene todas las palabras? (búsqueda literal, sin patrones)
local function coincide(texto, palabras)
	if #palabras == 0 then
		return false
	end
	local normal = normalizar(texto)
	for _, palabra in ipairs(palabras) do
		if not string.find(normal, palabra, 1, true) then
			return false
		end
	end
	return true
end

local function obtenerControlador(nombre)
	local registro = HelpController.registro
	if typeof(registro) ~= "table" or typeof(registro.Get) ~= "function" then
		return nil
	end
	local ok, controlador = pcall(registro.Get, nombre)
	if ok and typeof(controlador) == "table" then
		return controlador
	end
	return nil
end

-- Pestañas horizontales en móvil o en pantallas estrechas; lista lateral en el resto.
local function usarPestanas()
	return UIBuilder.EsEstrecho() or UITheme.Dispositivo() == "Movil"
end

local function plataformaDetectada()
	return CLAVE_CONTROLES[UITheme.Dispositivo()] or "PC"
end

---------------------------------------------------------------------------------------------------
-- Contenido
---------------------------------------------------------------------------------------------------
local function limpiarContenido()
	local contenido = ui.Contenido
	if not contenido then
		return
	end
	for _, hijo in ipairs(contenido:GetChildren()) do
		if hijo:IsA("GuiObject") then
			hijo:Destroy()
		end
	end
	pcall(function()
		contenido.CanvasPosition = Vector2.new(0, 0)
	end)
end

local function parrafo(texto, orden, props)
	props = props or {}
	return UIBuilder.Texto(ui.Contenido, texto, {
		LayoutOrder = orden,
		Color = props.Color or Colores.TextoSecundario,
		Tamano = props.Tamano or "Texto",
		Fuente = props.Fuente,
		Nombre = props.Nombre or "Parrafo",
	})
end

-- Tabla "acción — control" de una plataforma.
local function tablaControles(clave, ordenInicial)
	local orden = ordenInicial
	for _, fila in ipairs(CONTROLES[clave] or {}) do
		orden = orden + 1
		local marco = UIBuilder.Marco(ui.Contenido, { Nombre = "Control", LayoutOrder = orden, AutoAlto = true, Color = Colores.Gris, Transparencia = 0.55 })
		UIBuilder.Esquinas(marco, UITheme.RadioPequeno)
		UIBuilder.Relleno(marco, 6, 6, 10, 10)
		UIBuilder.Disposicion(marco, { Espaciado = 2 })
		UIBuilder.Texto(marco, tostring(fila.Accion or ""), { LayoutOrder = 1, Fuente = "Subtitulo", Tamano = "Texto" })
		UIBuilder.Texto(marco, tostring(fila.Control or ""), { LayoutOrder = 2, Color = Colores.Amarillo, Tamano = "Pequeno" })
	end
	return orden
end

local mostrarSeccion -- (id) declarado más abajo.

local function selectorPlataforma(orden)
	local fila = UIBuilder.Fila(ui.Contenido, { LayoutOrder = orden, Nombre = "Plataformas", Espaciado = 6 })
	local botones = {}
	for i, plataforma in ipairs(PLATAFORMAS) do
		local estilo = "Secundario"
		if plataforma.Clave == plataformaControles then
			estilo = "Primario"
		end
		local boton = UIBuilder.Boton(fila, plataforma.Texto, function()
			plataformaControles = plataforma.Clave
			mostrarSeccion("Controles")
		end, { Estilo = estilo, Ancho = 150, LayoutOrder = i, Nombre = "Plataforma_" .. plataforma.Clave })
		table.insert(botones, boton)
	end
	UIBuilder.Encadenar(botones, true)
end

local function bloqueFAQ(entrada, orden)
	local marco = UIBuilder.Marco(ui.Contenido, { Nombre = "Pregunta", LayoutOrder = orden, AutoAlto = true, Color = Colores.Gris, Transparencia = 0.55 })
	UIBuilder.Esquinas(marco, UITheme.RadioPequeno)
	UIBuilder.Relleno(marco, 8, 8, 10, 10)
	UIBuilder.Disposicion(marco, { Espaciado = 4 })
	UIBuilder.Texto(marco, tostring(entrada.Pregunta or ""), { LayoutOrder = 1, Fuente = "Subtitulo" })
	UIBuilder.Texto(marco, tostring(entrada.Respuesta or ""), { LayoutOrder = 2, Color = Colores.TextoSecundario, Tamano = "Pequeno" })
end

local function marcarBotones()
	for id, boton in pairs(ui.Botones) do
		if boton and boton.Parent ~= nil then
			if id == seccionActual and consultaActual == "" then
				boton:SetAttribute("Estilo", "Primario")
			else
				boton:SetAttribute("Estilo", "Fantasma")
			end
			UIBuilder.Habilitar(boton, true) -- Repinta con el estilo nuevo.
		end
	end
end

mostrarSeccion = function(id)
	local seccion = Catalogs.SeccionAyuda(id) or SECCIONES[1]
	if not seccion or not ui.Contenido then
		return
	end
	seccionActual = seccion.Id
	limpiarContenido()
	local orden = 0
	local function siguiente()
		orden = orden + 1
		return orden
	end
	UIBuilder.Titulo(ui.Contenido, seccion.Titulo or seccion.Id, { LayoutOrder = siguiente(), Tamano = "Subtitulo" })
	for _, texto in ipairs(seccion.Parrafos or {}) do
		parrafo(texto, siguiente())
	end
	if seccion.Id == "Controles" then
		if plataformaControles == nil then
			plataformaControles = plataformaDetectada()
		end
		UIBuilder.Espacio(ui.Contenido, 4, siguiente())
		parrafo("Dispositivo detectado: " .. (NOMBRE_PLATAFORMA[plataformaDetectada()] or "PC") .. ". Mostrando controles de " .. (NOMBRE_PLATAFORMA[plataformaControles] or plataformaControles) .. ":", siguiente(), { Color = Colores.TextoPrincipal, Tamano = "Pequeno" })
		selectorPlataforma(siguiente())
		orden = tablaControles(plataformaControles, orden)
	elseif seccion.Id == "FAQ" then
		for _, entrada in ipairs(FAQ) do
			bloqueFAQ(entrada, siguiente())
		end
	end
	marcarBotones()
end

-- Resultados de búsqueda: secciones (título o párrafos), controles y preguntas frecuentes.
local function mostrarResultados(consulta)
	if not ui.Contenido then
		return
	end
	local palabras = terminos(consulta)
	limpiarContenido()
	local orden = 0
	local function siguiente()
		orden = orden + 1
		return orden
	end
	UIBuilder.Titulo(ui.Contenido, "Resultados para «" .. Format.Truncar(consulta, MAX_BUSQUEDA) .. "»", { LayoutOrder = siguiente(), Tamano = "Subtitulo" })
	local encontrados = 0

	for _, seccion in ipairs(SECCIONES) do
		local enTitulo = coincide(seccion.Titulo, palabras)
		local parrafos = {}
		for _, texto in ipairs(seccion.Parrafos or {}) do
			if coincide(texto, palabras) then
				table.insert(parrafos, texto)
			end
		end
		if enTitulo or #parrafos > 0 then
			encontrados = encontrados + 1
			local fila = UIBuilder.Fila(ui.Contenido, { LayoutOrder = siguiente(), Nombre = "Resultado" })
			UIBuilder.Boton(fila, (seccion.Titulo or seccion.Id) .. "  ›", function()
				if ui.Busqueda then
					ui.Busqueda.Text = ""
				end
				consultaActual = ""
				mostrarSeccion(seccion.Id)
			end, { Estilo = "Secundario", Ancho = 360, Alineacion = Enum.TextXAlignment.Left, Nombre = "IrSeccion" })
			for i, texto in ipairs(parrafos) do
				if i <= MAX_PARRAFOS_RESULTADO then
					parrafo(texto, siguiente(), { Tamano = "Pequeno" })
				end
			end
		end
	end

	local controlesEncontrados = {}
	for _, plataforma in ipairs(PLATAFORMAS) do
		for _, fila in ipairs(CONTROLES[plataforma.Clave] or {}) do
			if coincide(tostring(fila.Accion) .. " " .. tostring(fila.Control), palabras) then
				table.insert(controlesEncontrados, plataforma.Texto .. ": " .. tostring(fila.Accion) .. " — " .. tostring(fila.Control))
			end
		end
	end
	if #controlesEncontrados > 0 then
		encontrados = encontrados + #controlesEncontrados
		UIBuilder.Subtitulo(ui.Contenido, "Controles", { LayoutOrder = siguiente() })
		for _, texto in ipairs(controlesEncontrados) do
			parrafo(texto, siguiente(), { Tamano = "Pequeno", Color = Colores.TextoPrincipal })
		end
	end

	local faqEncontradas = {}
	for _, entrada in ipairs(FAQ) do
		if coincide(tostring(entrada.Pregunta) .. " " .. tostring(entrada.Respuesta), palabras) then
			table.insert(faqEncontradas, entrada)
		end
	end
	if #faqEncontradas > 0 then
		encontrados = encontrados + #faqEncontradas
		UIBuilder.Subtitulo(ui.Contenido, "Preguntas frecuentes", { LayoutOrder = siguiente() })
		for _, entrada in ipairs(faqEncontradas) do
			bloqueFAQ(entrada, siguiente())
		end
	end

	if encontrados == 0 then
		parrafo("Sin resultados. Prueba con otra palabra (por ejemplo «cuaderno», «comida» o «asistencia») o envía una Duda desde SOPORTE.", siguiente())
	end
	marcarBotones()
end

local function buscar(texto)
	local consulta = Format.Recortar(texto or "")
	if Format.Longitud(consulta) < MIN_BUSQUEDA then
		if consultaActual ~= "" then
			consultaActual = ""
			mostrarSeccion(seccionActual)
		end
		return
	end
	consultaActual = consulta
	mostrarResultados(consulta)
end

-- Búsqueda con espera breve tras la última tecla (no se reconstruye por cada pulsación).
local function programarBusqueda(texto)
	generacionBusqueda = generacionBusqueda + 1
	local generacion = generacionBusqueda
	task.delay(ESPERA_BUSQUEDA, function()
		if generacion == generacionBusqueda and abierto then
			buscar(texto)
		end
	end)
end

---------------------------------------------------------------------------------------------------
-- Construcción del panel
---------------------------------------------------------------------------------------------------
local function construirUI()
	local gui = UIBuilder.Pantalla("Ayuda", ORDEN_PANTALLA)
	ui.Gui = gui
	ui.Botones = {}
	ui.Estrecho = usarPestanas()
	-- Panel a casi toda la altura: con la franja táctil de 150 px quedaría de ~160 px en un teléfono horizontal.
	local contenedor = UIBuilder.Contenedor(gui, { SinMargenTactil = true })
	local panel, cuerpo = UIBuilder.Panel(contenedor, {
		Nombre = "PanelAyuda",
		Titulo = "Ayuda",
		AlCerrar = function()
			HelpController.Cerrar()
		end,
		Size = UDim2.new(1, 0, 1, 0),
	})
	local limite = Instance.new("UISizeConstraint")
	limite.MaxSize = Vector2.new(900, 760)
	limite.Parent = panel
	pcall(function()
		panel.SelectionGroup = true
	end)
	panel.Visible = false
	ui.Panel = panel

	local altoControl = UIBuilder.AltoBoton()
	local espacio = UITheme.Espaciado

	-- Barra de búsqueda.
	local barra = UIBuilder.Marco(cuerpo, { Nombre = "Busqueda", Alto = altoControl })
	ui.Busqueda = UIBuilder.Entrada(barra, "Buscar en la ayuda (p. ej. «cuaderno»)…", {
		Max = MAX_BUSQUEDA,
		Size = UDim2.new(1, -(altoControl + espacio), 1, 0),
		AlCambiar = programarBusqueda,
		AlEnviar = function(texto)
			generacionBusqueda = generacionBusqueda + 1
			buscar(texto)
		end,
	})
	UIBuilder.Boton(barra, "✕", function()
		if ui.Busqueda then
			ui.Busqueda.Text = ""
		end
		generacionBusqueda = generacionBusqueda + 1
		consultaActual = ""
		mostrarSeccion(seccionActual)
	end, { Estilo = "Secundario", Ancho = altoControl, Alto = altoControl, Nombre = "LimpiarBusqueda", Position = UDim2.new(1, 0, 0, 0), AnchorPoint = Vector2.new(1, 0) })

	local arriba = altoControl + espacio
	local navegacion
	if ui.Estrecho then
		-- Móvil o pantallas estrechas: pestañas horizontales con desplazamiento.
		local altoPestanas = altoControl + 10
		navegacion = UIBuilder.Lista(cuerpo, {
			Nombre = "Pestanas", Horizontal = true, Espaciado = 6,
			Size = UDim2.new(1, 0, 0, altoPestanas), Position = UDim2.new(0, 0, 0, arriba),
		})
		local contenido = UIBuilder.Lista(cuerpo, {
			Nombre = "Contenido", Espaciado = 8,
			Size = UDim2.new(1, 0, 1, -(arriba + altoPestanas + espacio)),
			Position = UDim2.new(0, 0, 0, arriba + altoPestanas + espacio),
		})
		ui.Contenido = contenido
	else
		-- Pantallas anchas: lista de secciones a la izquierda y contenido a la derecha.
		navegacion = UIBuilder.Lista(cuerpo, {
			Nombre = "Secciones", Espaciado = 4,
			Size = UDim2.new(0, ANCHO_LISTA, 1, -arriba), Position = UDim2.new(0, 0, 0, arriba),
		})
		UIBuilder.Separador(cuerpo, {
			Size = UDim2.new(0, 1, 1, -arriba), Position = UDim2.new(0, ANCHO_LISTA + espacio, 0, arriba),
		})
		local contenido = UIBuilder.Lista(cuerpo, {
			Nombre = "Contenido", Espaciado = 8,
			Size = UDim2.new(1, -(ANCHO_LISTA + espacio * 2 + 1), 1, -arriba),
			Position = UDim2.new(0, ANCHO_LISTA + espacio * 2 + 1, 0, arriba),
		})
		ui.Contenido = contenido
	end
	-- El contenido es solo texto: seleccionable para que el mando pueda desplazarlo con el stick.
	ui.Contenido.Selectable = true

	local botones = {}
	for i, seccion in ipairs(SECCIONES) do
		local props = { Estilo = "Fantasma", LayoutOrder = i, Nombre = "Seccion_" .. tostring(seccion.Id) }
		if ui.Estrecho then
			props.Ancho = 170
		else
			props.Size = UDim2.new(1, 0, 0, altoControl)
			props.Alineacion = Enum.TextXAlignment.Left
		end
		local boton = UIBuilder.Boton(navegacion, seccion.Titulo or seccion.Id, function()
			if ui.Busqueda then
				ui.Busqueda.Text = ""
			end
			generacionBusqueda = generacionBusqueda + 1
			consultaActual = ""
			mostrarSeccion(seccion.Id)
		end, props)
		ui.Botones[seccion.Id] = boton
		table.insert(botones, boton)
	end
	UIBuilder.Encadenar(botones, ui.Estrecho == true)

	mostrarSeccion(seccionActual or (SECCIONES[1] and SECCIONES[1].Id))
end

local function asegurarUI()
	local necesita = not ui.Gui or ui.Gui.Parent == nil or not ui.Panel or ui.Panel.Parent == nil
	-- Si cambió el ancho de pantalla (rotación, ventana), se rehace con la disposición adecuada.
	if not necesita and ui.Estrecho ~= usarPestanas() then
		necesita = true
	end
	if necesita then
		construirUI()
	end
end

local function cerrarHermanos()
	for _, nombre in ipairs({ "SettingsController", "SupportController" }) do
		local otro = obtenerControlador(nombre)
		if otro and typeof(otro.Cerrar) == "function" then
			local estaAbierto = true
			if typeof(otro.EstaAbierto) == "function" then
				local ok, valor = pcall(otro.EstaAbierto)
				estaAbierto = ok and valor == true
			end
			if estaAbierto then
				pcall(otro.Cerrar)
			end
		end
	end
end

---------------------------------------------------------------------------------------------------
-- API pública (admite llamada con punto o con dos puntos)
---------------------------------------------------------------------------------------------------
function HelpController.EstaAbierto()
	return abierto
end

-- Abre la ayuda; opcionalmente en una sección (Id de Catalogs.Ayuda: "Controles", "FAQ", ...).
function HelpController.Abrir(a, b)
	if not activo then
		return
	end
	local seccionId = a
	if a == HelpController then
		seccionId = b
	end
	local ok, err = pcall(asegurarUI)
	if not ok then
		warn(LOG .. "No se pudo construir el panel: " .. tostring(err))
		return
	end
	if typeof(seccionId) == "string" and Catalogs.SeccionAyuda(seccionId) then
		if ui.Busqueda then
			ui.Busqueda.Text = ""
		end
		consultaActual = ""
		mostrarSeccion(seccionId)
	end
	if abierto then
		UIBuilder.EnfocarPrimero(ui.Panel)
		return
	end
	cerrarHermanos()
	abierto = true
	ui.Gui.Enabled = true
	UIBuilder.Aparecer(ui.Panel)
	local conexion = UIBuilder.TeclaCerrar(function()
		HelpController.Cerrar()
	end)
	if conexion then
		maidPanel:GiveTask(conexion)
	end
	task.delay(UITheme.Animacion.Rapida + 0.05, function()
		if abierto and ui.Panel and ui.Panel.Parent ~= nil then
			ui.Panel.Visible = true
		end
	end)
	task.defer(function()
		if abierto then
			local boton = seccionActual and ui.Botones[seccionActual]
			if boton then
				UIBuilder.Enfocar(boton)
			else
				UIBuilder.EnfocarPrimero(ui.Panel)
			end
		end
	end)
	HelpController.Abierto:Fire()
end

function HelpController.Cerrar()
	if not abierto then
		return
	end
	abierto = false
	generacionBusqueda = generacionBusqueda + 1
	maidPanel:DoCleaning()
	if ui.Busqueda then
		pcall(function()
			ui.Busqueda:ReleaseFocus()
		end)
	end
	if ui.Panel and ui.Panel.Parent ~= nil then
		UIBuilder.Desenfocar(ui.Panel)
		UIBuilder.Desaparecer(ui.Panel)
	end
	HelpController.Cerrado:Fire()
end

function HelpController.Alternar()
	if abierto then
		HelpController.Cerrar()
	else
		HelpController.Abrir()
	end
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function HelpController:Init(registro)
	self.registro = registro
end

function HelpController:Start()
	if activo then
		return
	end
	activo = true
	seccionActual = SECCIONES[1] and SECCIONES[1].Id or nil
	local ok, err = pcall(construirUI)
	if not ok then
		warn(LOG .. "No se pudo construir el panel: " .. tostring(err))
	end
end

return HelpController
]=] }
FUENTES["StarterPlayer/StarterPlayerScripts/ColegioRP/Controllers/InteractionController"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: StarterPlayer.StarterPlayerScripts.ColegioRP.Controllers.InteractionController
	Tipo: ModuleScript
	Interacciones físicas del cliente (docs/ARQUITECTURA.md §7, prueba P10). Solo pide y renderiza: los
	ProximityPrompt los crea y los resuelve el servidor (Triggered llega al servidor con el jugador).
	- Ayuda contextual: al mostrarse un prompt de Colegio RP (atributo RPTipo) añade en el HUD la acción con su tecla
	  (HUDController:AccionContextual); en táctil no añade botones (los prompts ya son táctiles).
	- Tecla F: abre/cierra la puerta más cercana con prompt (DoorAction Abrir/Cerrar según el atributo Estado).
	- Filtros locales: el prompt de bloqueo solo se habilita para cargos autorizados (RPCargos / RPPermiso) y el de
	  privacidad solo dentro del baño (RPPunto / RPNormal / RPReferencia). El servidor vuelve a validarlo todo.
	- EventoCliente: "Puerta" (toasts de bloqueo y mensajes), "PC" AbrirEscritorio -> PCController:Abrir,
	  "Cafeteria" AbrirPanel -> CafeteriaController:Abrir, "Comida" Abrir* -> FoodController solo si no atiende
	  su propio evento (delegación tolerante, sin doble apertura).
]]

local Players = game:GetService("Players")
local ProximityPromptService = game:GetService("ProximityPromptService")
local UserInputService = game:GetService("UserInputService")
local CollectionService = game:GetService("CollectionService")

local InteractionController = {}
InteractionController.Nombre = "InteractionController"
InteractionController.TeclaPuerta = Enum.KeyCode.F -- Atajo de teclado para la puerta más cercana.
InteractionController.DistanciaTecla = 10 -- Studs máximos para la tecla F (el servidor admite 14).
InteractionController.IntervaloTeclaSeg = 0.4 -- Pulsaciones de F más rápidas se ignoran (respeta el cooldown).
InteractionController.IntervaloFiltroSeg = 0.5 -- Revisión de los prompts de privacidad (dentro/fuera).
InteractionController.IntervaloAvisoSinPuertaSeg = 4
InteractionController.TagPrompt = "ColegioRP_PromptPuerta"
InteractionController.TagPromptBloqueo = "ColegioRP_PromptBloqueo"
InteractionController.TagPromptPrivacidad = "ColegioRP_PromptPrivacidad"

local UIBuilder, UITheme, Net, Maid, Format, RoleDefinitions, Zones, Config

local player = Players.LocalPlayer

-- Delegación de aperturas de panel: Tipo de EventoCliente -> { Sub -> { Controlador, Metodo } }.
local DELEGACIONES = {
	PC = {
		AbrirEscritorio = { "PCController", "Abrir" },
	},
	Cafeteria = {
		AbrirPanel = { "CafeteriaController", "Abrir" },
		AbrirVenta = { "CafeteriaController", "Abrir" },
	},
	Comida = {
		AbrirPanel = { "FoodController", "Abrir" },
		AbrirReclamo = { "FoodController", "Abrir" },
		AbrirCocina = { "FoodController", "AbrirCocina", "Abrir" },
	},
}

-- Controladores que ya escuchan su propio evento de apertura (no se delega para no abrir el panel dos veces).
-- FoodController atiende "Comida" { Sub = "AbrirPanel" } por sí mismo. Otro controlador puede declararlo con
-- ManejaAperturaPropia = true en su tabla.
local APERTURA_PROPIA = {
	FoodController = true,
}

local NOMBRE_FUNCION = {
	PCController = "El escritorio escolar",
	CafeteriaController = "La tienda escolar",
	FoodController = "El comedor",
}

local function requerir(padre, nombre)
	if not padre then
		error("no se encontró la carpeta para " .. nombre)
	end
	local modulo = padre:FindFirstChild(nombre) or padre:WaitForChild(nombre, 10)
	if not modulo then
		error("no se encontró el módulo " .. nombre)
	end
	return require(modulo)
end

local function plano(v)
	return Vector3.new(v.X, 0, v.Z)
end

local function posicionPropia()
	local personaje = player.Character
	local raiz = personaje and personaje:FindFirstChild("HumanoidRootPart")
	if raiz and raiz:IsA("BasePart") then
		return raiz.Position
	end
	return nil
end

-- Posición en el mundo de un prompt (padre Attachment, BasePart o Model).
local function posicionPrompt(prompt)
	local padre = prompt.Parent
	if not padre then
		return nil
	end
	if padre:IsA("Attachment") then
		return padre.WorldPosition
	end
	if padre:IsA("BasePart") then
		return padre.Position
	end
	if padre:IsA("Model") then
		local ok, cf = pcall(function()
			return padre:GetPivot()
		end)
		if ok and typeof(cf) == "CFrame" then
			return cf.Position
		end
	end
	return nil
end

local function esPromptRP(prompt)
	return typeof(prompt) == "Instance" and prompt:IsA("ProximityPrompt") and typeof(prompt:GetAttribute("RPTipo")) == "string"
end

local function nombreTecla(codigo)
	if typeof(codigo) ~= "EnumItem" then
		return "E"
	end
	local nombre = codigo.Name
	local sinBoton = string.match(nombre, "^Button(.+)$")
	if sinBoton then
		return sinBoton
	end
	return nombre
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function InteractionController:Init(registro)
	self.registro = registro
	Config = registro.Config
	UIBuilder = registro.UIBuilder
	local Shared = registro.Shared
	local Util = Shared:FindFirstChild("Util") or Shared:WaitForChild("Util", 10)
	UITheme = requerir(Shared, "UITheme")
	RoleDefinitions = requerir(Shared, "RoleDefinitions")
	Net = requerir(Util, "Net")
	Maid = requerir(Util, "Maid")
	Format = requerir(Util, "Format")
	Zones = requerir(Util, "Zones")

	self.maid = Maid.new()
	self.activo = true
	self.visibles = {} -- prompt -> true (prompts RP mostrados ahora)
	self.actual = nil -- prompt elegido para la ayuda contextual
	self.etiquetaHUD = nil -- texto de la acción contextual publicada en el HUD
	self.promptsPuerta = {} -- prompt -> true
	self.promptsBloqueo = {} -- prompt -> true
	self.promptsPrivacidad = {} -- prompt -> true
	self.estados = {} -- puertaId -> último { Estado, Bloqueada, ... } recibido
	self.enCurso = {} -- puertaId -> true mientras hay una petición DoorAction en vuelo
	self.ultimaTecla = 0
	self.ultimoAvisoSinPuerta = 0
	self.avisosDelegacion = {}
	self.gui = nil
	self.etiquetaAyuda = nil
end

function InteractionController:Start()
	-- Prompts mostrados / ocultos / activados (cliente).
	self.maid:GiveTask(ProximityPromptService.PromptShown:Connect(function(prompt)
		if esPromptRP(prompt) then
			self.visibles[prompt] = true
			self:_ElegirActual()
		end
	end))
	self.maid:GiveTask(ProximityPromptService.PromptHidden:Connect(function(prompt)
		if self.visibles[prompt] then
			self.visibles[prompt] = nil
			if self.actual == prompt then
				self:_ElegirActual()
			end
		end
	end))
	self.maid:GiveTask(ProximityPromptService.PromptTriggered:Connect(function(prompt)
		if esPromptRP(prompt) and UIBuilder then
			pcall(UIBuilder.Sonar)
		end
	end))

	-- Atajo F (solo teclado; se ignora mientras se escribe o si el juego ya procesó la tecla).
	self.maid:GiveTask(UserInputService.InputBegan:Connect(function(entrada, procesado)
		if procesado or entrada.KeyCode ~= self.TeclaPuerta then
			return
		end
		if UserInputService:GetFocusedTextBox() ~= nil then
			return
		end
		local ok, err = pcall(self._AlPulsarTeclaPuerta, self)
		if not ok then
			warn("[ColegioRP] InteractionController: " .. tostring(err))
		end
	end))

	-- Registro de prompts de puerta por tag (replicados desde el servidor).
	self:_SeguirTag(self.TagPrompt, self.promptsPuerta, nil)
	self:_SeguirTag(self.TagPromptBloqueo, self.promptsBloqueo, function(prompt)
		self:_FiltrarBloqueo(prompt)
	end)
	self:_SeguirTag(self.TagPromptPrivacidad, self.promptsPrivacidad, function(prompt)
		self:_FiltrarPrivacidad(prompt, posicionPropia())
	end)
	self.maid:GiveTask(player:GetAttributeChangedSignal("Cargo"):Connect(function()
		for prompt in pairs(self.promptsBloqueo) do
			self:_FiltrarBloqueo(prompt)
		end
	end))

	-- Al reaparecer se limpia la ayuda (los prompts se vuelven a mostrar solos).
	self.maid:GiveTask(player.CharacterAdded:Connect(function()
		table.clear(self.visibles)
		self:_ElegirActual()
	end))

	-- Revisión periódica de los prompts de privacidad (solo hay unos pocos; nada por fotograma).
	self.maid:GiveTask(task.spawn(function()
		while self.activo do
			task.wait(self.IntervaloFiltroSeg)
			if next(self.promptsPrivacidad) ~= nil then
				local pos = posicionPropia()
				for prompt in pairs(self.promptsPrivacidad) do
					pcall(self._FiltrarPrivacidad, self, prompt, pos)
				end
			end
		end
	end))

	-- Canal servidor -> cliente.
	task.spawn(function()
		local remoto = Net.Evento("EventoCliente")
		if not remoto then
			warn("[ColegioRP] InteractionController: EventoCliente no disponible; no habrá avisos de puertas.")
			return
		end
		self.maid:GiveTask(remoto.OnClientEvent:Connect(function(carga)
			if typeof(carga) ~= "table" or typeof(carga.Tipo) ~= "string" then
				return
			end
			local datos = carga.Datos
			if typeof(datos) ~= "table" then
				datos = {}
			end
			local ok, err = true, nil
			if carga.Tipo == "Puerta" then
				ok, err = pcall(self._AlEventoPuerta, self, datos)
			elseif DELEGACIONES[carga.Tipo] then
				ok, err = pcall(self._Delegar, self, carga.Tipo, datos)
			end
			if not ok then
				warn("[ColegioRP] InteractionController: " .. tostring(err))
			end
		end))
	end)
end

-- Libera conexiones, la ayuda del HUD y la pantalla propia (si se creó).
function InteractionController:Destruir()
	self.activo = false
	self:_PublicarAyuda(nil)
	if self.maid then
		self.maid:DoCleaning()
	end
	if self.gui and UIBuilder then
		UIBuilder.Destruir(self.gui)
	end
	self.gui = nil
end

---------------------------------------------------------------------------------------------------
-- Registro por tags y filtros locales
---------------------------------------------------------------------------------------------------
function InteractionController:_SeguirTag(tag, tabla, alAgregar)
	local function agregar(instancia)
		if typeof(instancia) == "Instance" and instancia:IsA("ProximityPrompt") then
			tabla[instancia] = true
			if alAgregar then
				pcall(alAgregar, instancia)
			end
		end
	end
	local ok, lista = pcall(CollectionService.GetTagged, CollectionService, tag)
	if ok and typeof(lista) == "table" then
		for _, instancia in ipairs(lista) do
			agregar(instancia)
		end
	end
	local okA, senalA = pcall(CollectionService.GetInstanceAddedSignal, CollectionService, tag)
	if okA and senalA then
		self.maid:GiveTask(senalA:Connect(agregar))
	end
	local okR, senalR = pcall(CollectionService.GetInstanceRemovedSignal, CollectionService, tag)
	if okR and senalR then
		self.maid:GiveTask(senalR:Connect(function(instancia)
			tabla[instancia] = nil
			if self.visibles[instancia] then
				self.visibles[instancia] = nil
				self:_ElegirActual()
			end
		end))
	end
end

-- Prompt de bloqueo: visible solo para cargos de RPCargos o con el permiso RPPermiso (cambio local).
function InteractionController:_FiltrarBloqueo(prompt)
	local cargo = player:GetAttribute("Cargo")
	local permitido = false
	if typeof(cargo) == "string" and cargo ~= "" then
		local cargos = prompt:GetAttribute("RPCargos")
		if typeof(cargos) == "string" then
			for nombre in string.gmatch(cargos, "[^,]+") do
				if nombre == cargo then
					permitido = true
				end
			end
		end
		local permiso = prompt:GetAttribute("RPPermiso")
		if not permitido and typeof(permiso) == "string" and permiso ~= "" then
			local ok, tiene = pcall(RoleDefinitions.Tiene, cargo, permiso)
			permitido = ok and tiene == true
		end
	end
	if prompt.Enabled ~= permitido then
		prompt.Enabled = permitido
	end
end

-- ¿La posición está dentro del cubículo/baño? Misma regla que DoorService (lado del plano de la hoja).
function InteractionController:_DentroPrivacidad(prompt, pos)
	if typeof(pos) ~= "Vector3" then
		return false
	end
	local punto = prompt:GetAttribute("RPPunto")
	local normal = prompt:GetAttribute("RPNormal")
	local referencia = prompt:GetAttribute("RPReferencia")
	if typeof(punto) == "Vector3" and typeof(normal) == "Vector3" and typeof(referencia) == "Vector3" then
		local n = plano(normal)
		if n.Magnitude > 0.01 then
			n = n.Unit
			local dp = plano(pos - punto):Dot(n)
			local dr = plano(referencia - punto):Dot(n)
			if math.abs(dp) < 0.75 then
				return plano(pos - punto).Magnitude < 4
			end
			if math.abs(dr) >= 0.5 then
				return (dp > 0) == (dr > 0)
			end
		end
	end
	local zona = prompt:GetAttribute("RPZona")
	if typeof(zona) == "string" and zona ~= "" then
		return Zones.Contiene(zona, pos)
	end
	return true
end

function InteractionController:_FiltrarPrivacidad(prompt, pos)
	if prompt.Parent == nil then
		return
	end
	local dentro = self:_DentroPrivacidad(prompt, pos)
	if prompt.Enabled ~= dentro then
		prompt.Enabled = dentro
	end
end

---------------------------------------------------------------------------------------------------
-- Ayuda contextual (HUD o, si no hay HUD, una etiqueta propia)
---------------------------------------------------------------------------------------------------
function InteractionController:_ElegirActual()
	local pos = posicionPropia()
	local mejor, mejorDist = nil, math.huge
	for prompt in pairs(self.visibles) do
		if prompt.Parent ~= nil and prompt.Enabled then
			local p = posicionPrompt(prompt)
			local d = math.huge
			if pos and p then
				d = (p - pos).Magnitude
			end
			if mejor == nil or d < mejorDist then
				mejor, mejorDist = prompt, d
			end
		else
			self.visibles[prompt] = nil
		end
	end
	if mejor ~= self.actual then
		self.actual = mejor
		self.maid.TextoActual = nil
		if mejor then
			-- Si el servidor cambia el texto (Abrir -> Cerrar), se actualiza la ayuda.
			self.maid.TextoActual = mejor:GetPropertyChangedSignal("ActionText"):Connect(function()
				if self.actual == mejor then
					self:_PublicarAyuda(mejor)
				end
			end)
		end
	end
	self:_PublicarAyuda(mejor)
end

function InteractionController:_EsPuerta(prompt)
	return prompt:GetAttribute("RPTipo") == "Puerta" and prompt:GetAttribute("RPAccion") == "Alternar"
end

function InteractionController:_TextoAyuda(prompt)
	local accion = tostring(prompt.ActionText or "")
	local objeto = tostring(prompt.ObjectText or "")
	local tecla
	local mando = UIBuilder and UIBuilder.EsMando() or false
	if mando then
		tecla = nombreTecla(prompt.GamepadKeyCode)
	elseif self:_EsPuerta(prompt) then
		tecla = nombreTecla(self.TeclaPuerta)
	else
		tecla = nombreTecla(prompt.KeyboardKeyCode)
	end
	local texto = accion
	if objeto ~= "" then
		texto = accion .. " · " .. Format.Truncar(objeto, 18)
	end
	return texto .. " [" .. tecla .. "]"
end

-- Publica (prompt) o retira (nil) la acción contextual. En táctil nunca añade botones.
function InteractionController:_PublicarAyuda(prompt)
	local HUD = self.registro and self.registro.Get("HUDController")
	local texto = nil
	if prompt and prompt.Parent ~= nil and not (UIBuilder and UIBuilder.EsTactil()) then
		texto = self:_TextoAyuda(prompt)
	end
	if texto == self.etiquetaHUD then
		return
	end
	local usaHUD = HUD and typeof(HUD.AccionContextual) == "function"
	if self.etiquetaHUD and usaHUD then
		pcall(HUD.AccionContextual, HUD, self.etiquetaHUD, nil)
	end
	self.etiquetaHUD = texto
	if texto == nil then
		self:_AyudaPropia(nil)
		return
	end
	if usaHUD then
		local objetivo = prompt
		local ok = pcall(HUD.AccionContextual, HUD, texto, function()
			self:_EjecutarPrompt(objetivo)
		end)
		if ok then
			self:_AyudaPropia(nil)
			return
		end
	end
	self:_AyudaPropia(texto)
end

-- Respaldo sin HUD: etiqueta inferior centrada en una ScreenGui propia (DisplayOrder del HUD).
function InteractionController:_AyudaPropia(texto)
	if texto == nil then
		if self.etiquetaAyuda and self.etiquetaAyuda.Parent then
			self.etiquetaAyuda.Visible = false
		end
		return
	end
	if not self:_AsegurarPantalla() then
		return
	end
	self.etiquetaAyuda.Text = texto
	self.etiquetaAyuda.Visible = true
end

-- Crea (una sola vez) la ScreenGui propia "ColegioRP_Interaccion" con la etiqueta de ayuda. Devuelve true si existe.
function InteractionController:_AsegurarPantalla()
	if not UIBuilder then
		return false
	end
	if not self.gui or self.gui.Parent == nil or not self.etiquetaAyuda or self.etiquetaAyuda.Parent == nil then
		local capa = (UITheme.Capas and UITheme.Capas.HUD) or 10
		local gui = UIBuilder.Pantalla("Interaccion", capa)
		self.gui = gui
		local etiqueta = UIBuilder.Texto(gui, "", {
			Nombre = "Ayuda",
			Alineacion = Enum.TextXAlignment.Center,
			AlineacionY = Enum.TextYAlignment.Center,
			AutoAlto = false,
			Size = UDim2.new(0, 320, 0, 36),
			Position = UDim2.new(0.5, 0, 1, -(24 + UIBuilder.MargenInferiorTactil())),
			AnchorPoint = Vector2.new(0.5, 1),
			Truncar = true,
		})
		etiqueta.BackgroundTransparency = UITheme.Transparencias and UITheme.Transparencias.Fondo or 0.35
		etiqueta.BackgroundColor3 = (UITheme.Colores and UITheme.Colores.GrisPanel) or Color3.fromRGB(24, 25, 28)
		UIBuilder.Esquinas(etiqueta, UITheme.Radio)
		etiqueta.Visible = false
		self.etiquetaAyuda = etiqueta
	end
	return true
end

-- Ejecuta la acción de un prompt desde el botón del HUD: puertas por DoorAction; el resto simulando la pulsación.
function InteractionController:_EjecutarPrompt(prompt)
	if not prompt or prompt.Parent == nil or not prompt.Enabled then
		return
	end
	if self:_EsPuerta(prompt) then
		self:AccionPuerta(prompt)
		return
	end
	local espera = math.max(0, tonumber(prompt.HoldDuration) or 0) + 0.05
	local ok = pcall(function()
		prompt:InputHoldBegin()
	end)
	if ok then
		task.delay(espera, function()
			pcall(function()
				prompt:InputHoldEnd()
			end)
		end)
	end
end

---------------------------------------------------------------------------------------------------
-- Puertas
---------------------------------------------------------------------------------------------------

-- Prompt de puerta más cercano: primero los que se ven ahora, después los registrados a <= DistanciaTecla.
function InteractionController:_PuertaMasCercana()
	local pos = posicionPropia()
	if not pos then
		return nil
	end
	local mejor, mejorDist = nil, self.DistanciaTecla
	local function considerar(prompt)
		if prompt.Parent ~= nil and self:_EsPuerta(prompt) then
			local p = posicionPrompt(prompt)
			if p then
				local d = (p - pos).Magnitude
				if d <= mejorDist then
					mejor, mejorDist = prompt, d
				end
			end
		end
	end
	for prompt in pairs(self.visibles) do
		considerar(prompt)
	end
	if mejor then
		return mejor
	end
	for prompt in pairs(self.promptsPuerta) do
		considerar(prompt)
	end
	return mejor
end

function InteractionController:_AlPulsarTeclaPuerta()
	local ahora = os.clock()
	if ahora - self.ultimaTecla < self.IntervaloTeclaSeg then
		return
	end
	self.ultimaTecla = ahora
	local prompt = self:_PuertaMasCercana()
	if not prompt then
		if ahora - self.ultimoAvisoSinPuerta >= self.IntervaloAvisoSinPuertaSeg then
			self.ultimoAvisoSinPuerta = ahora
			self:_Notificar("No hay ninguna puerta cerca.", "info", 2)
		end
		return
	end
	self:AccionPuerta(prompt)
end

-- Estado conocido de la puerta del prompt: atributo del prompt > atributo de la hoja > último evento.
function InteractionController:_EstadoDe(prompt, puertaId)
	local estado = prompt:GetAttribute("Estado")
	if typeof(estado) == "string" then
		return estado
	end
	local actual = prompt.Parent
	for _ = 1, 3 do
		if not actual then
			break
		end
		local valor = actual:GetAttribute("Estado")
		if typeof(valor) == "string" then
			return valor
		end
		actual = actual.Parent
	end
	local cache = self.estados[puertaId]
	if cache and typeof(cache.Estado) == "string" then
		return cache.Estado
	end
	if prompt.ActionText == "Cerrar" then
		return "Abierta"
	end
	return "Cerrada"
end

-- Abre o cierra la puerta del prompt pidiéndolo al servidor (DoorAction). Devuelve true si se envió.
function InteractionController:AccionPuerta(prompt)
	if not prompt or prompt.Parent == nil then
		return false
	end
	local puertaId = prompt:GetAttribute("RPId")
	if typeof(puertaId) ~= "string" or puertaId == "" then
		return false
	end
	if self.enCurso[puertaId] then
		return false
	end
	local accion = "Abrir"
	if self:_EstadoDe(prompt, puertaId) == "Abierta" then
		accion = "Cerrar"
	end
	self.enCurso[puertaId] = true
	task.spawn(function()
		local ok, respuesta = Net.Invocar("DoorAction", { PuertaId = puertaId, Accion = accion })
		self.enCurso[puertaId] = nil
		if not ok then
			local texto = respuesta and respuesta.error
			if UIBuilder then
				texto = UIBuilder.MensajeError(texto)
			end
			self:_Notificar(texto or "No se pudo usar la puerta.", "aviso")
		end
	end)
	return true
end

-- Evento "Puerta": mensajes dirigidos y avisos de bloqueo para quien está en la zona (no para el autor).
function InteractionController:_AlEventoPuerta(datos)
	local sub = datos.Sub
	if sub == "Mensaje" then
		if typeof(datos.Texto) == "string" and datos.Texto ~= "" then
			self:_Notificar(datos.Texto, datos.Nivel or "info")
		end
		return
	end
	if sub ~= "Estado" or typeof(datos.PuertaId) ~= "string" then
		return
	end
	self.estados[datos.PuertaId] = datos
	if datos.ActorUserId == player.UserId then
		return
	end
	local accion = datos.Accion
	if accion == "Bloquear" then
		if datos.Fijada then
			self:_Notificar("El personal dejó la puerta fijada abierta.", "info", 3)
		else
			self:_Notificar("El personal bloqueó la puerta: desde dentro siempre se puede salir.", "info", 4)
		end
	elseif accion == "Desbloquear" then
		self:_Notificar("La puerta se desbloqueó.", "info", 3)
	elseif accion == "AbrirTodas" then
		self:_Notificar("Todas las puertas se abrieron.", "aviso", 4)
	end
end

-- Estado de puerta conocido por el cliente (último evento) o nil.
function InteractionController:EstadoPuerta(puertaId)
	return self.estados[puertaId]
end

---------------------------------------------------------------------------------------------------
-- Delegación de paneles y notificaciones
---------------------------------------------------------------------------------------------------
function InteractionController:_Delegar(tipo, datos)
	local tabla = DELEGACIONES[tipo]
	local def = tabla and typeof(datos.Sub) == "string" and tabla[datos.Sub] or nil
	if not def then
		return
	end
	local nombreControlador = def[1]
	local controlador = self.registro and self.registro.Get(nombreControlador)
	-- Un controlador que ya atiende su propio evento no recibe la delegación (evita la doble apertura).
	if controlador and (controlador.ManejaAperturaPropia == true or (APERTURA_PROPIA[nombreControlador] and controlador.ManejaAperturaPropia ~= false)) then
		return
	end
	local metodo = nil
	if controlador then
		for i = 2, #def do
			if typeof(controlador[def[i]]) == "function" then
				metodo = controlador[def[i]]
				break
			end
		end
	end
	if metodo then
		local ok, err = pcall(metodo, controlador, datos)
		if not ok then
			warn("[ColegioRP] InteractionController: " .. nombreControlador .. " falló al abrir: " .. tostring(err))
			self:_Notificar("No se pudo abrir el panel. Inténtalo de nuevo.", "error")
		end
		return
	end
	if not self.avisosDelegacion[nombreControlador] then
		self.avisosDelegacion[nombreControlador] = true
		self:_Notificar((NOMBRE_FUNCION[nombreControlador] or "Esta función") .. " todavía no está disponible.", "aviso")
	end
end

function InteractionController:_Notificar(texto, nivel, duracion)
	if typeof(texto) ~= "string" or texto == "" then
		return
	end
	local Notificaciones = self.registro and self.registro.Get("NotificationController")
	if Notificaciones and typeof(Notificaciones.Notificar) == "function" then
		local ok = pcall(Notificaciones.Notificar, Notificaciones, texto, nivel, duracion)
		if ok then
			return
		end
	end
	-- Respaldo sin NotificationController: toast en la pantalla propia.
	if self:_AsegurarPantalla() then
		local nivelToast = "Info"
		if nivel == "aviso" then
			nivelToast = "Aviso"
		elseif nivel == "error" then
			nivelToast = "Error"
		elseif nivel == "exito" then
			nivelToast = "Exito"
		end
		local contenedor = self.gui:FindFirstChild("Toasts")
		if not contenedor then
			contenedor = Instance.new("Frame")
			contenedor.Name = "Toasts"
			contenedor.BackgroundTransparency = 1
			contenedor.Size = UDim2.new(0, 360, 0, 0)
			contenedor.AutomaticSize = Enum.AutomaticSize.Y
			contenedor.AnchorPoint = Vector2.new(0.5, 0)
			contenedor.Position = UDim2.new(0.5, 0, 0, UIBuilder.InsetSuperior() + 8)
			local lista = Instance.new("UIListLayout")
			lista.Padding = UDim.new(0, 6)
			lista.SortOrder = Enum.SortOrder.LayoutOrder
			lista.Parent = contenedor
			contenedor.Parent = self.gui
		end
		pcall(UIBuilder.Toast, contenedor, Format.Truncar(texto, 160), nivelToast, tonumber(duracion) or 4)
	end
end

return InteractionController
]=] }
FUENTES["StarterPlayer/StarterPlayerScripts/ColegioRP/Controllers/MenuController"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: StarterPlayer.StarterPlayerScripts.ColegioRP.Controllers.MenuController
	Tipo: ModuleScript
	Menú principal a pantalla completa tras la carga: JUGAR (lista de cargos por equipo con disponibilidad del
	servidor -> RequestJoinRole), ACTUALIZACIONES, EQUIPO, AJUSTES, AYUDA y SOPORTE (delegados a sus controladores).
	Reabrible con la tecla M, el botón ☰ del HUD o Start del mando; oculta el HUD mientras está abierto.
]]

local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")

local MenuController = {}
MenuController.Nombre = "MenuController"
MenuController.EsperaUnionSeg = 20 -- Tiempo máximo esperando RequestJoinRole antes de reactivar los botones.

local UIBuilder, UITheme, Net, Maid, Format, RoleDefinitions, Catalogs, Config

local player = Players.LocalPlayer

local function requerir(padre, nombre)
	if not padre then
		error("no se encontró la carpeta para " .. nombre)
	end
	local modulo = padre:FindFirstChild(nombre) or padre:WaitForChild(nombre, 10)
	if not modulo then
		error("no se encontró el módulo " .. nombre)
	end
	return require(modulo)
end

-- string.upper que también convierte las vocales acentuadas y la ñ (UTF-8).
local ACENTOS = { ["á"] = "Á", ["é"] = "É", ["í"] = "Í", ["ó"] = "Ó", ["ú"] = "Ú", ["ñ"] = "Ñ", ["ü"] = "Ü" }
local function mayusculas(valor)
	local resultado = string.upper(tostring(valor or ""))
	for minuscula, mayuscula in pairs(ACENTOS) do
		resultado = string.gsub(resultado, minuscula, mayuscula)
	end
	return resultado
end

-- "2026-10-26" -> "26/10/2026" (o el texto tal cual si no tiene ese formato).
local function fechaLegible(fecha)
	if typeof(fecha) ~= "string" then
		return ""
	end
	local a, m, d = string.match(fecha, "^(%d%d%d%d)%-(%d%d)%-(%d%d)$")
	if a then
		return d .. "/" .. m .. "/" .. a
	end
	return fecha
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function MenuController:Init(registro)
	self.registro = registro
	Config = registro.Config
	UIBuilder = registro.UIBuilder
	if not UIBuilder then
		error("UIBuilder no está disponible")
	end
	local Shared = registro.Shared
	local Util = Shared:FindFirstChild("Util") or Shared:WaitForChild("Util", 10)
	UITheme = requerir(Shared, "UITheme")
	RoleDefinitions = requerir(Shared, "RoleDefinitions")
	Catalogs = requerir(Shared, "Catalogs")
	Net = requerir(Util, "Net")
	Maid = requerir(Util, "Maid")
	Format = requerir(Util, "Format")

	self.maid = Maid.new()
	self.abierto = false
	self.haJugado = false
	self.puedeContinuar = false
	self.uniendo = false
	self.vista = "Principal"
	self.tokenVista = 0
	self.tokenSuspension = 0
	self.suspendido = nil
	self:_Construir()
end

function MenuController:Start()
	-- Tecla M (si no se está escribiendo), Start del mando para alternar; B del mando para volver.
	self.maid:GiveTask(UserInputService.InputBegan:Connect(function(entrada, procesado)
		local tecla = entrada.KeyCode
		if tecla == Enum.KeyCode.M then
			if procesado or UserInputService:GetFocusedTextBox() ~= nil then
				return
			end
			self:Alternar()
		elseif tecla == Enum.KeyCode.ButtonStart then
			self:Alternar()
		elseif tecla == Enum.KeyCode.ButtonB then
			if self.abierto and not self.suspendido and self.vista ~= "Principal" then
				self:_MostrarPrincipal()
			end
		end
	end))

	-- Si el servidor asigna un cargo (por defecto al entrar o por un administrador), se puede continuar sin elegir.
	local function revisarCargo()
		if RoleDefinitions.Existe(player:GetAttribute("Cargo")) and not self.puedeContinuar then
			self.puedeContinuar = true
			self:_ActualizarBotones()
		end
	end
	self.maid:GiveTask(player:GetAttributeChangedSignal("Cargo"):Connect(revisarCargo))
	revisarCargo()

	-- La escala de texto del perfil llega después de construir el menú: se reajusta la disposición.
	local Settings = self.registro.Get("SettingsController")
	if Settings and typeof(Settings.Cambiado) == "table" and typeof(Settings.Cambiado.Connect) == "function" then
		self.maid:GiveTask(Settings.Cambiado:Connect(function()
			if self.abierto and not self.suspendido and self.vista == "Principal" and self:_EsBajo() ~= self.bajo then
				self:_MostrarPrincipal()
			end
		end))
	end
end

---------------------------------------------------------------------------------------------------
-- Construcción
---------------------------------------------------------------------------------------------------
function MenuController:_Construir()
	local Colores = UITheme.Colores
	local gui = UIBuilder.Pantalla("Menu", (UITheme.Capas and UITheme.Capas.Menu) or 90, { Visible = false })
	self.gui = gui
	self.maid:GiveTask(gui)

	local fondo = Instance.new("Frame")
	fondo.Name = "Fondo"
	fondo.BackgroundColor3 = Colores.Fondo
	fondo.BackgroundTransparency = 0.12
	fondo.BorderSizePixel = 0
	fondo.Size = UDim2.new(1, 0, 1, 0)
	fondo.Active = true
	fondo.Parent = gui
	local degradado = Instance.new("UIGradient")
	degradado.Rotation = 90
	degradado.Color = ColorSequence.new(Colores.Fondo, UITheme.Oscurecer(Colores.RojoOscuro, 0.75))
	degradado.Parent = fondo
	self.fondo = fondo

	-- El menú cubre la pantalla y no se juega mientras está abierto: no reserva los 150 px táctiles inferiores.
	local contenido = UIBuilder.Contenedor(fondo, { Nombre = "Contenido", SinMargenTactil = true })
	self.contenido = contenido

	-- Créditos.
	UIBuilder.Texto(contenido, tostring(Config.Productora or "Horizon Studios") .. " " .. tostring(Config.Autor or "by Adrian") .. " · v" .. tostring(Config.Version or "?"), {
		Nombre = "Creditos", Tamano = "Pequeno", Color = Colores.TextoApagado,
		Alineacion = Enum.TextXAlignment.Center, AlineacionY = Enum.TextYAlignment.Bottom, AutoAlto = false,
		Size = UDim2.new(1, 0, 0, 20), Position = UDim2.new(0.5, 0, 1, 0), AnchorPoint = Vector2.new(0.5, 1),
	})

	-- Vista principal: logo central y botones.
	local principal = Instance.new("Frame")
	principal.Name = "Principal"
	principal.BackgroundTransparency = 1
	principal.Size = UDim2.new(1, 0, 1, -28)
	principal.Parent = contenido
	self.principal = principal

	local bajo = self:_EsBajo()
	self.bajo = bajo
	UIBuilder.Disposicion(principal, {
		Horizontal = bajo,
		Espaciado = bajo and 40 or 18,
		Alineacion = Enum.HorizontalAlignment.Center,
		AlineacionVertical = Enum.VerticalAlignment.Center,
	})

	local anchoMarca = bajo and 320 or 460
	local marca = Instance.new("Frame")
	marca.Name = "Marca"
	marca.BackgroundTransparency = 1
	marca.Size = UDim2.new(0, anchoMarca, 0, 0)
	marca.AutomaticSize = Enum.AutomaticSize.Y
	marca.LayoutOrder = 1
	marca.Parent = principal
	UIBuilder.Disposicion(marca, { Espaciado = 8, Alineacion = Enum.HorizontalAlignment.Center })
	UIBuilder.Logo(marca, bajo and 140 or 176, { LayoutOrder = 1 })
	UIBuilder.Titulo(marca, mayusculas(Config.NombreColegio or "Instituto Educativo Jean Piaget"), {
		LayoutOrder = 2, Alineacion = Enum.TextXAlignment.Center, Tamano = bajo and "Titulo" or "TituloGrande",
	})
	UIBuilder.Subtitulo(marca, tostring(Config.Lema or ""), { LayoutOrder = 3, Alineacion = Enum.TextXAlignment.Center, Tamano = "Texto" })

	local columna
	if bajo then
		-- Pantalla baja (teléfono en horizontal): 7 botones de 44 px no caben; la columna se desplaza.
		columna = Instance.new("ScrollingFrame")
		columna.Size = UDim2.new(0, 300, 1, 0)
		columna.CanvasSize = UDim2.new(0, 0, 0, 0)
		columna.AutomaticCanvasSize = Enum.AutomaticSize.Y
		columna.ScrollingDirection = Enum.ScrollingDirection.Y
		columna.ScrollBarThickness = 4
		columna.ScrollBarImageColor3 = Colores.Borde
		columna.BorderSizePixel = 0
		columna.Selectable = false
		columna.ElasticBehavior = Enum.ElasticBehavior.WhenScrollable
	else
		columna = Instance.new("Frame")
		columna.Size = UDim2.new(0, 300, 0, 0)
		columna.AutomaticSize = Enum.AutomaticSize.Y
	end
	columna.Name = "Botones"
	columna.BackgroundTransparency = 1
	columna.LayoutOrder = 2
	columna.Parent = principal
	UIBuilder.Disposicion(columna, {
		Espaciado = 8,
		Alineacion = Enum.HorizontalAlignment.Center,
		AlineacionVertical = bajo and Enum.VerticalAlignment.Center or nil,
	})
	if bajo then
		-- Margen interior para que el borde de foco del mando no quede recortado por el ScrollingFrame.
		UIBuilder.Relleno(columna, 4, 4, 4, 8)
	end
	self.columna = columna

	local alto = UIBuilder.AltoBoton() + 4
	local function boton(textoBoton, orden, estilo, accion)
		return UIBuilder.Boton(columna, textoBoton, accion, {
			Estilo = estilo, Size = UDim2.new(1, 0, 0, alto), LayoutOrder = orden, Tamano = "Subtitulo", Nombre = textoBoton,
		})
	end
	self.botonContinuar = boton("CONTINUAR", 1, "Exito", function()
		self:Cerrar()
	end)
	self.botonJugar = boton("JUGAR", 2, "Primario", function()
		self:_VistaJugar()
	end)
	self.botonActualizaciones = boton("ACTUALIZACIONES", 3, "Secundario", function()
		self:_VistaActualizaciones()
	end)
	self.botonEquipo = boton("EQUIPO", 4, "Secundario", function()
		self:_VistaEquipo()
	end)
	self.botonAjustes = boton("AJUSTES", 5, "Secundario", function()
		self:_Delegar("SettingsController", "Los ajustes no están disponibles todavía.")
	end)
	self.botonAyuda = boton("AYUDA", 6, "Secundario", function()
		self:_Delegar("HelpController", "La ayuda no está disponible todavía.")
	end)
	self.botonSoporte = boton("SOPORTE", 7, "Secundario", function()
		self:_Delegar("SupportController", "El soporte no está disponible todavía.")
	end)

	-- Botón flotante mientras un panel delegado (Ajustes, Ayuda, Soporte) está abierto.
	local escala = math.max(0.5, UIBuilder.EscalaTotal())
	self.botonVolverMenu = UIBuilder.Boton(gui, "Volver al menú", function()
		self:_Reanudar()
	end, {
		Estilo = "Primario", Icono = "☰", Ancho = 200, Nombre = "VolverMenu", Visible = false,
		Position = UDim2.new(0.5, 0, 1, -(math.ceil(UIBuilder.MargenInferiorTactil() / escala) + 16)),
		AnchorPoint = Vector2.new(0.5, 1),
	})

	self:_ActualizarBotones()
end

-- ¿Pantalla baja (teléfono en horizontal, escala de texto grande)? Decide la disposición del menú principal.
function MenuController:_EsBajo()
	return UIBuilder.AltoUI() < 700
end

-- Si cambió el alto disponible (escala de texto del perfil, ventana, rotación) se rehace la pantalla
-- para que los 7 botones sigan cabiendo. Solo desde la vista principal (no hay vistas que perder).
function MenuController:_RevisarDisposicion()
	if self.bajo == nil or self:_EsBajo() == self.bajo then
		return false
	end
	self.panelVista = nil
	self:_Construir()
	self.gui.Enabled = self.abierto == true
	return true
end

-- Visibilidad de CONTINUAR y navegación con mando entre los botones visibles.
function MenuController:_ActualizarBotones()
	if not self.botonContinuar then
		return
	end
	self.botonContinuar.Visible = self.haJugado or self.puedeContinuar
	local lista = {}
	for _, b in ipairs({ self.botonContinuar, self.botonJugar, self.botonActualizaciones, self.botonEquipo, self.botonAjustes, self.botonAyuda, self.botonSoporte }) do
		if b.Visible then
			table.insert(lista, b)
		end
	end
	UIBuilder.Encadenar(lista)
end

function MenuController:_PrimerBoton()
	if self.botonContinuar and self.botonContinuar.Visible then
		return self.botonContinuar
	end
	return self.botonJugar
end

---------------------------------------------------------------------------------------------------
-- Vistas
---------------------------------------------------------------------------------------------------
function MenuController:_MostrarPrincipal()
	self.tokenVista = self.tokenVista + 1
	if self.panelVista then
		UIBuilder.Destruir(self.panelVista)
		self.panelVista = nil
	end
	self:_RevisarDisposicion()
	self.vista = "Principal"
	self.principal.Visible = true
	self:_ActualizarBotones()
	UIBuilder.Aparecer(self.columna)
	task.defer(function()
		if self.abierto and self.vista == "Principal" then
			UIBuilder.Enfocar(self:_PrimerBoton())
		end
	end)
end

-- Crea un panel de vista secundaria con botón Volver. Devuelve { Panel, Lista, Siguiente(), Token, Volver }.
function MenuController:_NuevaVista(titulo)
	self.tokenVista = self.tokenVista + 1
	if self.panelVista then
		UIBuilder.Destruir(self.panelVista)
		self.panelVista = nil
	end
	self.principal.Visible = false
	self.vista = titulo
	local ancho = math.floor(math.min(UITheme.AnchoPanelAncho or 640, math.max(260, UIBuilder.AnchoUI() - 24)))
	local panel, lista = UIBuilder.Panel(self.contenido, {
		Titulo = titulo,
		Nombre = "Vista",
		Scroll = true,
		Size = UDim2.new(0, ancho, 1, -28),
		Position = UDim2.new(0.5, 0, 0, 0),
		AnchorPoint = Vector2.new(0.5, 0),
		AlCerrar = function()
			self:_MostrarPrincipal()
		end,
	})
	self.panelVista = panel
	-- Vistas de solo texto (ACTUALIZACIONES, EQUIPO): la lista es seleccionable para desplazarla con el mando.
	lista.Selectable = true
	local orden = 0
	local function siguiente()
		orden = orden + 1
		return orden
	end
	local volver = UIBuilder.Boton(lista, "Volver", function()
		self:_MostrarPrincipal()
	end, { Estilo = "Secundario", Icono = "‹", Ancho = 150, LayoutOrder = siguiente(), Nombre = "Volver" })
	UIBuilder.Aparecer(panel)
	return { Panel = panel, Lista = lista, Siguiente = siguiente, Token = self.tokenVista, Volver = volver }
end

function MenuController:_VistaVigente(vista)
	return self.abierto and vista.Token == self.tokenVista and vista.Panel.Parent ~= nil
end

-- JUGAR: lista de cargos agrupada por equipo con la disponibilidad que decide el servidor.
function MenuController:_VistaJugar()
	local vista = self:_NuevaVista("Elige tu cargo")
	local Colores = UITheme.Colores
	local estado = UIBuilder.Texto(vista.Lista, "Cargando cargos…", { LayoutOrder = vista.Siguiente(), Color = Colores.TextoSecundario, Nombre = "Estado" })
	UIBuilder.Enfocar(vista.Volver)

	task.spawn(function()
		local ok, respuesta = Net.Invocar("RequestRoleList", {})
		if not self:_VistaVigente(vista) then
			return
		end
		if not ok or typeof(respuesta.datos) ~= "table" or typeof(respuesta.datos.Cargos) ~= "table" then
			self.puedeContinuar = true
			estado.Text = "No se pudo obtener la lista de cargos: " .. UIBuilder.MensajeError(respuesta and respuesta.error)
			estado.TextColor3 = Colores.Amarillo
			local fila = UIBuilder.Fila(vista.Lista, { LayoutOrder = vista.Siguiente(), Nombre = "Acciones" })
			local reintentar = UIBuilder.Boton(fila, "Reintentar", function()
				self:_VistaJugar()
			end, { Estilo = "Primario", Ancho = 160, LayoutOrder = 1 })
			UIBuilder.Boton(fila, "Cerrar menú", function()
				self:Cerrar()
			end, { Estilo = "Secundario", Ancho = 160, LayoutOrder = 2 })
			UIBuilder.Enfocar(reintentar)
			return
		end
		estado.Text = "Elige un cargo para entrar al colegio. Los cargos deshabilitados requieren autorización (la decide el servidor)."
		self:_PintarCargos(vista, respuesta.datos)
	end)
end

function MenuController:_PintarCargos(vista, datos)
	local Colores = UITheme.Colores
	local porEquipo = {}
	local ordenEquipos = {}
	for _, nombre in ipairs(RoleDefinitions.OrdenEquipos or {}) do
		table.insert(ordenEquipos, nombre)
		porEquipo[nombre] = {}
	end
	for _, cargo in ipairs(datos.Cargos) do
		if typeof(cargo) == "table" and typeof(cargo.Id) == "string" and RoleDefinitions.Existe(cargo.Id) then
			local equipo = cargo.Equipo
			if typeof(equipo) ~= "string" or equipo == "" then
				equipo = RoleDefinitions.Equipo(cargo.Id) or "Otros"
			end
			if not porEquipo[equipo] then
				porEquipo[equipo] = {}
				table.insert(ordenEquipos, equipo)
			end
			table.insert(porEquipo[equipo], cargo)
		end
	end

	local actual = datos.Actual
	if typeof(actual) ~= "string" then
		actual = player:GetAttribute("Cargo")
	end
	local botones = {}
	local disponibles = {}
	local primerDisponible = nil

	for _, equipo in ipairs(ordenEquipos) do
		local lista = porEquipo[equipo]
		if lista and #lista > 0 then
			local info = RoleDefinitions.Equipos and RoleDefinitions.Equipos[equipo]
			UIBuilder.Espacio(vista.Lista, 4, vista.Siguiente())
			UIBuilder.Subtitulo(vista.Lista, mayusculas(equipo), {
				LayoutOrder = vista.Siguiente(), Fuente = "Titulo", Color = (info and info.Color3) or Colores.TextoSecundario,
			})
			if info and typeof(info.Descripcion) == "string" then
				UIBuilder.Texto(vista.Lista, info.Descripcion, { LayoutOrder = vista.Siguiente(), Tamano = "Pequeno", Color = Colores.TextoApagado })
			end
			for _, cargo in ipairs(lista) do
				local id = cargo.Id
				local disponible = cargo.Disponible == true
				local nombre = cargo.Nombre
				if typeof(nombre) ~= "string" or nombre == "" then
					nombre = RoleDefinitions.Nombre(id)
				end
				local etiquetaBoton = nombre
				if id == actual then
					etiquetaBoton = nombre .. "  · actual"
				end
				local boton = UIBuilder.Boton(vista.Lista, etiquetaBoton, function()
					self:_Unirse(id, nombre, vista, botones, disponibles)
				end, {
					Estilo = disponible and "Primario" or "Secundario",
					Size = UDim2.new(1, 0, 0, UIBuilder.AltoBoton()),
					Alineacion = Enum.TextXAlignment.Left,
					Desactivado = not disponible,
					Selectable = disponible,
					LayoutOrder = vista.Siguiente(),
					Nombre = "Cargo_" .. id,
				})
				table.insert(botones, boton)
				disponibles[boton] = disponible
				if disponible and primerDisponible == nil then
					primerDisponible = boton
				end
				local explicacion
				if disponible then
					local def = RoleDefinitions.Obtener(id)
					explicacion = def and def.Descripcion or ""
				else
					-- RoleService envía Motivo (código interno) y MotivoTexto (texto legible para el jugador).
					explicacion = "Requiere autorización"
					if typeof(cargo.MotivoTexto) == "string" and cargo.MotivoTexto ~= "" then
						explicacion = Format.Truncar(cargo.MotivoTexto, 120)
					end
				end
				if explicacion ~= "" then
					UIBuilder.Texto(vista.Lista, explicacion, {
						LayoutOrder = vista.Siguiente(), Tamano = "Pequeno",
						Color = disponible and Colores.TextoSecundario or Colores.Amarillo,
					})
				end
			end
		end
	end

	vista.EstadoUnion = UIBuilder.Texto(vista.Lista, "", { LayoutOrder = vista.Siguiente(), Color = Colores.TextoSecundario, Visible = false, Nombre = "EstadoUnion" })

	local navegables = { vista.Volver }
	for _, b in ipairs(botones) do
		if disponibles[b] then
			table.insert(navegables, b)
		end
	end
	UIBuilder.Encadenar(navegables)
	if primerDisponible then
		UIBuilder.Enfocar(primerDisponible)
	else
		self.puedeContinuar = true
	end
end

function MenuController:_Unirse(id, nombre, vista, botones, disponibles)
	if self.uniendo or not RoleDefinitions.Existe(id) then
		return
	end
	self.uniendo = true
	self.tokenUnion = (self.tokenUnion or 0) + 1
	local tokenUnion = self.tokenUnion
	for _, b in ipairs(botones) do
		UIBuilder.Habilitar(b, false)
	end
	if vista.EstadoUnion then
		vista.EstadoUnion.Text = "Entrando como " .. nombre .. "…"
		vista.EstadoUnion.Visible = true
	end
	-- InvokeServer no tiene tiempo máximo: si el servidor no responde, se reactivan los botones (nunca se bloquea).
	task.delay(self.EsperaUnionSeg, function()
		if not self.uniendo or self.tokenUnion ~= tokenUnion then
			return
		end
		self.uniendo = false
		self.puedeContinuar = true
		if self:_VistaVigente(vista) then
			for _, b in ipairs(botones) do
				if disponibles[b] then
					UIBuilder.Habilitar(b, true)
				end
			end
			if vista.EstadoUnion then
				vista.EstadoUnion.Text = "El servidor tarda en responder. Inténtalo de nuevo o cierra el menú."
				vista.EstadoUnion.TextColor3 = UITheme.Colores.Amarillo
			end
		end
	end)
	task.spawn(function()
		local ok, respuesta = Net.Invocar("RequestJoinRole", { Cargo = id })
		if self.tokenUnion == tokenUnion then
			self.uniendo = false
		end
		if ok then
			local datos = typeof(respuesta.datos) == "table" and respuesta.datos or {}
			local cargo = RoleDefinitions.Existe(datos.Cargo) and datos.Cargo or id
			self.haJugado = true
			self:Cerrar()
			local HUD = self.registro.Get("HUDController")
			if HUD then
				if typeof(HUD.FijarCargo) == "function" then
					local salon = datos.Salon
					if typeof(salon) ~= "string" or salon == "" then
						salon = nil
					end
					pcall(HUD.FijarCargo, HUD, cargo, salon)
				end
				if typeof(HUD.Visible) == "function" then
					pcall(HUD.Visible, HUD, true)
				end
			end
			local mensaje = "Ahora eres " .. RoleDefinitions.Nombre(cargo) .. "."
			if typeof(datos.Salon) == "string" and datos.Salon ~= "" then
				mensaje = mensaje .. " Tu salón: " .. Format.Truncar(datos.Salon, 24) .. "."
			end
			self:_Notificar(mensaje, "exito")
			return
		end
		local mensajeError = UIBuilder.MensajeError(respuesta and respuesta.error)
		-- RoleService: { error = "no_autorizado", datos = { MotivoTexto } } o { error = "cooldown", datos = { RestanteSeg } }.
		local extra = typeof(respuesta) == "table" and typeof(respuesta.datos) == "table" and respuesta.datos or nil
		if extra and typeof(extra.MotivoTexto) == "string" and extra.MotivoTexto ~= "" then
			mensajeError = Format.Truncar(extra.MotivoTexto, 120)
		elseif extra and tonumber(extra.RestanteSeg) then
			mensajeError = "Espera " .. math.max(1, math.floor(tonumber(extra.RestanteSeg))) .. " s antes de cambiar de cargo."
		end
		if self.tokenUnion ~= tokenUnion then
			return -- Respuesta tardía de un intento ya reactivado por la vigilancia.
		end
		self.puedeContinuar = true
		if self:_VistaVigente(vista) then
			for _, b in ipairs(botones) do
				if disponibles[b] then
					UIBuilder.Habilitar(b, true)
				end
			end
			if vista.EstadoUnion then
				vista.EstadoUnion.Text = "No se pudo entrar como " .. nombre .. ": " .. mensajeError
				vista.EstadoUnion.TextColor3 = UITheme.Colores.Amarillo
			end
		end
		self:_Notificar(mensajeError, "error")
	end)
end

-- ACTUALIZACIONES: Catalogs.Changelog.
function MenuController:_VistaActualizaciones()
	local vista = self:_NuevaVista("Actualizaciones")
	local Colores = UITheme.Colores
	local registros = Catalogs.Changelog or {}
	if #registros == 0 then
		UIBuilder.Texto(vista.Lista, "Todavía no hay notas de versión.", { LayoutOrder = vista.Siguiente(), Color = Colores.TextoSecundario })
	end
	for _, entrada in ipairs(registros) do
		if typeof(entrada) == "table" then
			UIBuilder.Espacio(vista.Lista, 4, vista.Siguiente())
			local cabecera = "Versión " .. tostring(entrada.Version or "?")
			local fecha = fechaLegible(entrada.Fecha)
			if fecha ~= "" then
				cabecera = cabecera .. " · " .. fecha
			end
			UIBuilder.Subtitulo(vista.Lista, cabecera, { LayoutOrder = vista.Siguiente(), Fuente = "Titulo", Color = Colores.Blanco })
			for _, linea in ipairs(entrada.Resumen or {}) do
				UIBuilder.Texto(vista.Lista, "• " .. tostring(linea), { LayoutOrder = vista.Siguiente(), Tamano = "Texto", Color = Colores.TextoSecundario })
			end
		end
	end
	UIBuilder.Enfocar(vista.Volver)
end

-- EQUIPO: Catalogs.Equipo.
function MenuController:_VistaEquipo()
	local vista = self:_NuevaVista("Equipo del proyecto")
	local Colores = UITheme.Colores
	UIBuilder.Texto(vista.Lista, "Producción: " .. tostring(Config.Productora or "Horizon Studios") .. " " .. tostring(Config.Autor or "by Adrian"), {
		LayoutOrder = vista.Siguiente(), Fuente = "Subtitulo", Color = Colores.TextoSecundario,
	})
	for _, miembro in ipairs(Catalogs.Equipo or {}) do
		if typeof(miembro) == "table" then
			local fila = Instance.new("Frame")
			fila.Name = "Miembro"
			fila.BackgroundColor3 = Colores.Gris
			fila.BackgroundTransparency = 0.4
			fila.BorderSizePixel = 0
			fila.Size = UDim2.new(1, 0, 0, 0)
			fila.AutomaticSize = Enum.AutomaticSize.Y
			fila.LayoutOrder = vista.Siguiente()
			UIBuilder.Esquinas(fila, UITheme.RadioPequeno)
			UIBuilder.Relleno(fila, 8, 8, 12, 12)
			UIBuilder.Disposicion(fila, { Espaciado = 2 })
			UIBuilder.Texto(fila, tostring(miembro.Nombre or "—"), { LayoutOrder = 1, Fuente = "Titulo" })
			UIBuilder.Texto(fila, tostring(miembro.Rol or ""), { LayoutOrder = 2, Tamano = "Pequeno", Color = Colores.TextoSecundario })
			fila.Parent = vista.Lista
		end
	end
	UIBuilder.Enfocar(vista.Volver)
end

---------------------------------------------------------------------------------------------------
-- Paneles delegados (Ajustes, Ayuda, Soporte)
---------------------------------------------------------------------------------------------------
function MenuController:_Notificar(texto, nivel)
	local Notificaciones = self.registro and self.registro.Get("NotificationController")
	if Notificaciones and typeof(Notificaciones.Notificar) == "function" then
		pcall(Notificaciones.Notificar, Notificaciones, texto, nivel)
	end
end

function MenuController:_Delegar(nombreControlador, mensajeAusente)
	local controlador = self.registro.Get(nombreControlador)
	if not controlador or typeof(controlador.Abrir) ~= "function" then
		self:_Notificar(mensajeAusente, "aviso")
		return
	end
	-- El menú se oculta (queda un botón flotante) para que el panel delegado quede visible.
	self:_Suspender(controlador)
	local ok, err = pcall(controlador.Abrir, controlador)
	if not ok then
		warn("[ColegioRP] MenuController: " .. nombreControlador .. ": " .. tostring(err))
		self:_Reanudar()
		self:_Notificar("No se pudo abrir el panel; inténtalo de nuevo.", "error")
	end
end

function MenuController:_Suspender(controlador)
	self.tokenSuspension = self.tokenSuspension + 1
	local token = self.tokenSuspension
	self.suspendido = controlador
	self.fondo.Visible = false
	UIBuilder.Desenfocar(self.gui)
	-- Si el controlador informa de su estado, el menú vuelve solo al cerrarse el panel y el botón flotante
	-- (que taparía el panel) solo aparece como respaldo si el panel no llega a abrirse.
	self.botonVolverMenu.Visible = typeof(controlador.EstaAbierto) ~= "function"
	if typeof(controlador.EstaAbierto) == "function" then
		local visto = false
		local inicio = os.clock()
		local function vigilar()
			if self.tokenSuspension ~= token or self.suspendido ~= controlador or not self.abierto then
				return
			end
			local ok, abierto = pcall(controlador.EstaAbierto, controlador)
			if ok and abierto == true then
				visto = true
			elseif ok and abierto == false and visto then
				self:_Reanudar()
				return
			end
			if not visto and os.clock() - inicio > 1.5 then
				-- El panel no llegó a abrirse: se restaura el menú para no dejar al jugador sin interfaz.
				self:_Reanudar()
				self:_Notificar("No se pudo abrir el panel; inténtalo de nuevo.", "aviso")
				return
			end
			task.delay(0.5, vigilar)
		end
		task.defer(vigilar)
	end
end

function MenuController:_Reanudar()
	self.tokenSuspension = self.tokenSuspension + 1
	self.suspendido = nil
	if self.botonVolverMenu then
		self.botonVolverMenu.Visible = false
	end
	if not self.abierto then
		return
	end
	self.fondo.Visible = true
	if self.vista == "Principal" then
		self:_MostrarPrincipal()
	end
end

---------------------------------------------------------------------------------------------------
-- API pública
---------------------------------------------------------------------------------------------------

-- Abre el menú principal (oculta el HUD). Si un panel delegado lo tenía suspendido, lo restaura.
function MenuController:Abrir()
	if self.abierto then
		if self.suspendido then
			self:_Reanudar()
		end
		return
	end
	self.abierto = true
	self.gui.Enabled = true
	self.fondo.Visible = true
	self.botonVolverMenu.Visible = false
	self.suspendido = nil
	local HUD = self.registro.Get("HUDController")
	if HUD and typeof(HUD.Visible) == "function" then
		pcall(HUD.Visible, HUD, false)
	end
	self.fondo.BackgroundTransparency = 1
	UIBuilder.Tween(self.fondo, { BackgroundTransparency = 0.12 }, "Normal")
	self:_MostrarPrincipal()
end

-- Cierra el menú y muestra el HUD.
function MenuController:Cerrar()
	if not self.abierto then
		return
	end
	self.abierto = false
	self.tokenVista = self.tokenVista + 1
	self.tokenSuspension = self.tokenSuspension + 1
	self.suspendido = nil
	UIBuilder.Desenfocar(self.gui)
	if self.panelVista then
		UIBuilder.Destruir(self.panelVista)
		self.panelVista = nil
	end
	self.vista = "Principal"
	self.principal.Visible = true
	self.botonVolverMenu.Visible = false
	self.gui.Enabled = false
	local HUD = self.registro.Get("HUDController")
	if HUD and typeof(HUD.Visible) == "function" then
		pcall(HUD.Visible, HUD, true)
	end
end

-- Abre o cierra el menú.
function MenuController:Alternar()
	if self.abierto then
		self:Cerrar()
	else
		self:Abrir()
	end
end

-- ¿El menú está abierto (aunque esté suspendido por un panel delegado)?
function MenuController:EstaAbierto()
	return self.abierto == true
end

return MenuController
]=] }
FUENTES["StarterPlayer/StarterPlayerScripts/ColegioRP/Controllers/NametagController"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: StarterPlayer.StarterPlayerScripts.ColegioRP.Controllers.NametagController
	Tipo: ModuleScript
	Etiquetas sobre la cabeza (BillboardGui local por personaje): nombre mostrado, icono del colegio y
	abreviatura del cargo (atributo Cargo del Player, con su color). Visible a 60 studs, también la propia en
	tercera persona; se ocultan todas con el ajuste OcultarEtiquetas. Sustituye localmente la etiqueta de Roblox.
]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local TIMEOUT = 30
local function esperarHijo(padre, nombre)
	local hijo = nil
	if padre then
		hijo = padre:FindFirstChild(nombre) or padre:WaitForChild(nombre, TIMEOUT)
	end
	if not hijo then
		error("[ColegioRP][NametagController] No apareció '" .. tostring(nombre) .. "' en " .. TIMEOUT .. " s")
	end
	return hijo
end

local RP = esperarHijo(ReplicatedStorage, "ColegioRP")
local Shared = esperarHijo(RP, "Shared")
local Util = esperarHijo(Shared, "Util")
local Config = require(esperarHijo(Shared, "Config"))
local UITheme = require(esperarHijo(Shared, "UITheme"))
local RoleDefinitions = require(esperarHijo(Shared, "RoleDefinitions"))
local Maid = require(esperarHijo(Util, "Maid"))
local Format = require(esperarHijo(Util, "Format"))
local UIBuilder = require(esperarHijo(esperarHijo(script.Parent.Parent, "UI"), "UIBuilder"))

local LocalPlayer = Players.LocalPlayer
local PlayerGui = esperarHijo(LocalPlayer, "PlayerGui")
local Colores = UITheme.Colores

local NametagController = {}
NametagController.Nombre = "NametagController"

---------------------------------------------------------------------------------------------------
-- Constantes
---------------------------------------------------------------------------------------------------
local LOG = "[ColegioRP][NametagController] "
local PREFIJO = ((Config.Nombres and Config.Nombres.PrefijoPantallas) or "ColegioRP_") .. "Etiqueta_"
local DISTANCIA_MAX = 60 -- studs
local ANCHO, ALTO = 220, 50 -- píxeles (tamaño constante en pantalla)
local DESPLAZAMIENTO = Vector3.new(0, 2.2, 0) -- sobre la cabeza
local DESPLAZAMIENTO_SIN_CABEZA = Vector3.new(0, 4.2, 0) -- sobre el HumanoidRootPart
local TAMANO_ICONO = 18
local INTERVALO_CAMARA = 0.25 -- comprobación de primera/tercera persona (no por frame)
local DISTANCIA_PRIMERA_PERSONA = 2 -- studs entre cámara y cabeza
local MAX_NOMBRE = 24

---------------------------------------------------------------------------------------------------
-- Estado
---------------------------------------------------------------------------------------------------
local activo = false
local ocultarTodas = false
local terceraPersona = true
local maid = Maid.new()
local jugadores = {} -- [Player] = { Maid, Etiqueta = { Gui, Nombre, Pastilla, TextoCargo }, Personaje }

---------------------------------------------------------------------------------------------------
-- Visibilidad
---------------------------------------------------------------------------------------------------
local function debeVerse(player)
	if ocultarTodas then
		return false
	end
	if player == LocalPlayer then
		return terceraPersona
	end
	return true
end

local function aplicarVisibilidad(player)
	local estado = jugadores[player]
	if estado and estado.Etiqueta and estado.Etiqueta.Gui and estado.Etiqueta.Gui.Parent ~= nil then
		estado.Etiqueta.Gui.Enabled = debeVerse(player)
	end
end

local function aplicarVisibilidadTodas()
	for player in pairs(jugadores) do
		aplicarVisibilidad(player)
	end
end

---------------------------------------------------------------------------------------------------
-- Contenido de la etiqueta
---------------------------------------------------------------------------------------------------
local function actualizarEtiqueta(player)
	local estado = jugadores[player]
	local etiqueta = estado and estado.Etiqueta
	if not etiqueta or not etiqueta.Gui or etiqueta.Gui.Parent == nil then
		return
	end
	local nombre = player.DisplayName
	if typeof(nombre) ~= "string" or nombre == "" then
		nombre = player.Name
	end
	etiqueta.Nombre.Text = Format.Truncar(nombre, MAX_NOMBRE)
	local cargo = player:GetAttribute("Cargo")
	local rol = RoleDefinitions.Obtener(cargo)
	if rol then
		local color = rol.Color or Colores.Gris
		etiqueta.Pastilla.Visible = true
		etiqueta.Pastilla.BackgroundColor3 = color
		etiqueta.TextoCargo.Text = RoleDefinitions.Abrev(cargo)
		etiqueta.TextoCargo.TextColor3 = UITheme.TextoSobre(color)
	else
		etiqueta.Pastilla.Visible = false
		etiqueta.TextoCargo.Text = ""
	end
	aplicarVisibilidad(player)
end

local function construirEtiqueta(player, adorno, sinCabeza)
	local gui = Instance.new("BillboardGui")
	gui.Name = PREFIJO .. tostring(player.UserId)
	gui.Adornee = adorno
	gui.Size = UDim2.new(0, ANCHO, 0, ALTO)
	if sinCabeza then
		gui.StudsOffset = DESPLAZAMIENTO_SIN_CABEZA
	else
		gui.StudsOffset = DESPLAZAMIENTO
	end
	gui.MaxDistance = DISTANCIA_MAX
	gui.AlwaysOnTop = false
	gui.LightInfluence = 0
	gui.ResetOnSpawn = false
	gui.ClipsDescendants = false
	gui.Active = false
	gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	gui.Enabled = debeVerse(player)

	local raiz = Instance.new("Frame")
	raiz.Name = "Contenido"
	raiz.BackgroundTransparency = 1
	raiz.Size = UDim2.new(1, 0, 1, 0)
	raiz.Parent = gui
	local layout = Instance.new("UIListLayout")
	layout.FillDirection = Enum.FillDirection.Vertical
	layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
	layout.VerticalAlignment = Enum.VerticalAlignment.Bottom
	layout.SortOrder = Enum.SortOrder.LayoutOrder
	layout.Padding = UDim.new(0, 2)
	layout.Parent = raiz

	-- Fila 1: icono del colegio + nombre mostrado.
	local fila = Instance.new("Frame")
	fila.Name = "FilaNombre"
	fila.BackgroundTransparency = 1
	fila.Size = UDim2.new(1, 0, 0, 24)
	fila.LayoutOrder = 1
	fila.Parent = raiz
	local layoutFila = Instance.new("UIListLayout")
	layoutFila.FillDirection = Enum.FillDirection.Horizontal
	layoutFila.HorizontalAlignment = Enum.HorizontalAlignment.Center
	layoutFila.VerticalAlignment = Enum.VerticalAlignment.Center
	layoutFila.SortOrder = Enum.SortOrder.LayoutOrder
	layoutFila.Padding = UDim.new(0, 5)
	layoutFila.Parent = fila

	-- Logo: ImageLabel si Config.LogoAssetId > 0; si no, círculo rojo con "JP" (UIBuilder.Logo).
	UIBuilder.Logo(fila, TAMANO_ICONO, { Texto = false, LayoutOrder = 1, Nombre = "Icono" })

	local nombre = Instance.new("TextLabel")
	nombre.Name = "Nombre"
	nombre.BackgroundTransparency = 1
	nombre.Font = UITheme.Fuente("Titulo")
	nombre.TextSize = 16
	nombre.TextColor3 = Colores.Blanco
	nombre.TextStrokeColor3 = Colores.Sombra
	nombre.TextStrokeTransparency = 0.45
	nombre.AutomaticSize = Enum.AutomaticSize.X
	nombre.Size = UDim2.new(0, 0, 1, 0)
	nombre.TextXAlignment = Enum.TextXAlignment.Center
	nombre.LayoutOrder = 2
	nombre.Text = ""
	nombre.Parent = fila
	local limiteNombre = Instance.new("UISizeConstraint")
	limiteNombre.MaxSize = Vector2.new(ANCHO - TAMANO_ICONO - 10, 24)
	limiteNombre.Parent = nombre
	nombre.TextTruncate = Enum.TextTruncate.AtEnd

	-- Fila 2: pastilla con la abreviatura del cargo en su color.
	local pastilla = Instance.new("Frame")
	pastilla.Name = "Cargo"
	pastilla.BackgroundColor3 = Colores.Gris
	pastilla.BorderSizePixel = 0
	pastilla.AutomaticSize = Enum.AutomaticSize.X
	pastilla.Size = UDim2.new(0, 0, 0, 18)
	pastilla.LayoutOrder = 2
	pastilla.Visible = false
	pastilla.Parent = raiz
	local esquina = Instance.new("UICorner")
	esquina.CornerRadius = UDim.new(0.5, 0)
	esquina.Parent = pastilla
	local relleno = Instance.new("UIPadding")
	relleno.PaddingLeft = UDim.new(0, 8)
	relleno.PaddingRight = UDim.new(0, 8)
	relleno.Parent = pastilla
	local textoCargo = Instance.new("TextLabel")
	textoCargo.Name = "Abrev"
	textoCargo.BackgroundTransparency = 1
	textoCargo.Font = UITheme.Fuente("Titulo")
	textoCargo.TextSize = UITheme.Tamanos.Etiqueta
	textoCargo.TextColor3 = Colores.Blanco
	textoCargo.AutomaticSize = Enum.AutomaticSize.X
	textoCargo.Size = UDim2.new(0, 0, 1, 0)
	textoCargo.Text = ""
	textoCargo.Parent = pastilla

	gui.Parent = PlayerGui
	return { Gui = gui, Nombre = nombre, Pastilla = pastilla, TextoCargo = textoCargo }
end

---------------------------------------------------------------------------------------------------
-- Personajes
---------------------------------------------------------------------------------------------------
local function quitarEtiqueta(estado)
	if estado and estado.Etiqueta then
		UIBuilder.Destruir(estado.Etiqueta.Gui)
		estado.Etiqueta = nil
	end
	if estado and estado.MaidPersonaje then
		estado.MaidPersonaje:DoCleaning()
	end
	if estado then
		estado.Personaje = nil
	end
end

local function etiquetarPersonaje(player, personaje)
	local estado = jugadores[player]
	if not estado or not personaje then
		return
	end
	quitarEtiqueta(estado)
	estado.Personaje = personaje
	local maidPersonaje = estado.MaidPersonaje
	maidPersonaje:GiveTask(task.spawn(function()
		local cabeza = personaje:FindFirstChild("Head") or personaje:WaitForChild("Head", 10)
		local adorno = cabeza
		if not adorno then
			adorno = personaje:FindFirstChild("HumanoidRootPart") or personaje:WaitForChild("HumanoidRootPart", 5)
		end
		if not activo or estado.Personaje ~= personaje or jugadores[player] ~= estado or not adorno then
			return
		end
		-- Sustituye la etiqueta de Roblox solo localmente y solo en personajes que etiquetamos.
		local humanoide = personaje:FindFirstChildOfClass("Humanoid") or personaje:WaitForChild("Humanoid", 5)
		if humanoide then
			pcall(function()
				humanoide.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
			end)
		end
		if estado.Personaje ~= personaje then
			return
		end
		local ok, etiqueta = pcall(construirEtiqueta, player, adorno, cabeza == nil)
		if not ok then
			warn(LOG .. "No se pudo crear la etiqueta de " .. player.Name .. ": " .. tostring(etiqueta))
			return
		end
		estado.Etiqueta = etiqueta
		actualizarEtiqueta(player)
		-- Si la cabeza se reemplaza (cambio de avatar), se reengancha.
		maidPersonaje:GiveTask(personaje.ChildAdded:Connect(function(hijo)
			if hijo.Name == "Head" and hijo:IsA("BasePart") and estado.Etiqueta and estado.Etiqueta.Gui then
				estado.Etiqueta.Gui.Adornee = hijo
				estado.Etiqueta.Gui.StudsOffset = DESPLAZAMIENTO
			end
		end))
	end))
end

local function agregarJugador(player)
	if jugadores[player] then
		return
	end
	local estado = { Maid = Maid.new(), MaidPersonaje = Maid.new(), Etiqueta = nil, Personaje = nil }
	jugadores[player] = estado
	estado.Maid:GiveTask(player.CharacterAdded:Connect(function(personaje)
		etiquetarPersonaje(player, personaje)
	end))
	estado.Maid:GiveTask(player.CharacterRemoving:Connect(function(personaje)
		if estado.Personaje == personaje then
			quitarEtiqueta(estado)
		end
	end))
	estado.Maid:GiveTask(player:GetAttributeChangedSignal("Cargo"):Connect(function()
		actualizarEtiqueta(player)
	end))
	estado.Maid:GiveTask(player:GetPropertyChangedSignal("DisplayName"):Connect(function()
		actualizarEtiqueta(player)
	end))
	if player.Character then
		etiquetarPersonaje(player, player.Character)
	end
end

local function quitarJugador(player)
	local estado = jugadores[player]
	if not estado then
		return
	end
	jugadores[player] = nil
	quitarEtiqueta(estado)
	estado.Maid:DoCleaning()
end

---------------------------------------------------------------------------------------------------
-- Ajuste OcultarEtiquetas (atributo local del Player y SettingsController)
---------------------------------------------------------------------------------------------------
local function fijarOcultar(valor)
	valor = valor == true
	if valor == ocultarTodas then
		return
	end
	ocultarTodas = valor
	aplicarVisibilidadTodas()
end

local function leerAjuste(registro)
	local valor = LocalPlayer:GetAttribute("OcultarEtiquetas")
	if valor ~= nil then
		return valor == true
	end
	local Settings = registro and typeof(registro.Get) == "function" and registro.Get("SettingsController")
	if Settings and typeof(Settings.Ajustes) == "function" then
		local ok, ajustes = pcall(Settings.Ajustes, Settings)
		if ok and typeof(ajustes) == "table" then
			return ajustes.OcultarEtiquetas == true
		end
	end
	return false
end

---------------------------------------------------------------------------------------------------
-- Primera / tercera persona (solo afecta a la etiqueta propia)
---------------------------------------------------------------------------------------------------
local function calcularTerceraPersona()
	if LocalPlayer.CameraMode == Enum.CameraMode.LockFirstPerson then
		return false
	end
	local camara = workspace.CurrentCamera
	local personaje = LocalPlayer.Character
	local cabeza = personaje and personaje:FindFirstChild("Head")
	if not camara or not cabeza then
		return true
	end
	return (camara.CFrame.Position - cabeza.Position).Magnitude > DISTANCIA_PRIMERA_PERSONA
end

---------------------------------------------------------------------------------------------------
-- API pública
---------------------------------------------------------------------------------------------------

-- Fuerza la actualización de la etiqueta de un jugador (o de todas si no se indica).
function NametagController.Actualizar(a, b)
	local player = a
	if a == NametagController then
		player = b
	end
	if typeof(player) == "Instance" and player:IsA("Player") then
		actualizarEtiqueta(player)
		return
	end
	for jugador in pairs(jugadores) do
		actualizarEtiqueta(jugador)
	end
end

-- ¿Están ocultas todas las etiquetas por el ajuste?
function NametagController.Ocultas()
	return ocultarTodas
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function NametagController:Init(registro)
	self.registro = registro
end

function NametagController:Start()
	if activo then
		return
	end
	activo = true
	local registro = self.registro
	ocultarTodas = leerAjuste(registro)

	-- Limpia etiquetas huérfanas de una ejecución anterior (reconexión del script).
	for _, hijo in ipairs(PlayerGui:GetChildren()) do
		if hijo:IsA("BillboardGui") and string.sub(hijo.Name, 1, #PREFIJO) == PREFIJO then
			UIBuilder.Destruir(hijo)
		end
	end

	maid:GiveTask(LocalPlayer:GetAttributeChangedSignal("OcultarEtiquetas"):Connect(function()
		fijarOcultar(LocalPlayer:GetAttribute("OcultarEtiquetas") == true)
	end))
	local Settings = registro and typeof(registro.Get) == "function" and registro.Get("SettingsController")
	if Settings and typeof(Settings.Cambiado) == "table" and typeof(Settings.Cambiado.Connect) == "function" then
		maid:GiveTask(Settings.Cambiado:Connect(function(ajustes)
			if typeof(ajustes) == "table" and ajustes.OcultarEtiquetas ~= nil then
				fijarOcultar(ajustes.OcultarEtiquetas == true)
			end
		end))
	end

	maid:GiveTask(Players.PlayerAdded:Connect(agregarJugador))
	maid:GiveTask(Players.PlayerRemoving:Connect(quitarJugador))
	for _, player in ipairs(Players:GetPlayers()) do
		agregarJugador(player)
	end

	-- Etiqueta propia solo en tercera persona (comprobación cada 0.25 s, no por frame).
	maid:GiveTask(task.spawn(function()
		while activo do
			local ok, tercera = pcall(calcularTerceraPersona)
			if ok and tercera ~= terceraPersona then
				terceraPersona = tercera
				aplicarVisibilidad(LocalPlayer)
			end
			task.wait(INTERVALO_CAMARA)
		end
	end))
end

-- Detiene el controlador y retira todas las etiquetas.
function NametagController:Stop()
	if not activo then
		return
	end
	activo = false
	maid:DoCleaning()
	local lista = {}
	for player in pairs(jugadores) do
		table.insert(lista, player)
	end
	for _, player in ipairs(lista) do
		quitarJugador(player)
	end
end

return NametagController
]=] }
FUENTES["StarterPlayer/StarterPlayerScripts/ColegioRP/Controllers/NotificationController"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: StarterPlayer.StarterPlayerScripts.ColegioRP.Controllers.NotificationController
	Tipo: ModuleScript
	Notificaciones del cliente: toasts arriba al centro (cola de máx. 4 visibles, sin tapar los controles táctiles
	inferiores), avisos oficiales destacados (8 s) y subtítulos de timbre según el ajuste Subtitulos. Escucha los
	tipos "Notificacion", "Aviso" y "Jornada" (timbre al cambiar de periodo) del canal EventoCliente.
]]

local ReplicatedFirst = game:GetService("ReplicatedFirst")
local TextChatService = game:GetService("TextChatService")

local NotificationController = {}
NotificationController.Nombre = "NotificationController"
NotificationController.MaxVisibles = 4 -- Toasts simultáneos en pantalla.
NotificationController.MaxPendientes = 20 -- Toasts en espera (los más antiguos se descartan).
NotificationController.DuracionAviso = 8 -- Segundos que permanece un aviso oficial.
NotificationController.VentanaTimbreSeg = 3 -- Dos timbres dentro de esta ventana se consideran el mismo.

local UIBuilder, UITheme, Net, Maid, Format, RoleDefinitions, Config

-- Niveles públicos (en minúsculas) -> nivel visual de UIBuilder.Toast y duración por defecto.
local NIVELES = {
	info = { Nivel = "Info", Duracion = 4 },
	exito = { Nivel = "Exito", Duracion = 4 },
	aviso = { Nivel = "Aviso", Duracion = 5 },
	error = { Nivel = "Error", Duracion = 6 },
	timbre = { Nivel = "Info", Duracion = 5, Icono = "♪" },
}

local ALIAS_NIVEL = {
	["Info"] = "info", ["Información"] = "info", ["Exito"] = "exito", ["Éxito"] = "exito", ["éxito"] = "exito",
	["Aviso"] = "aviso", ["Advertencia"] = "aviso", ["Error"] = "error", ["Timbre"] = "timbre",
}

local function normalizarNivel(nivel)
	if typeof(nivel) ~= "string" then
		return "info"
	end
	if NIVELES[nivel] then
		return nivel
	end
	if ALIAS_NIVEL[nivel] then
		return ALIAS_NIVEL[nivel]
	end
	local minusculas = string.lower(nivel)
	if NIVELES[minusculas] then
		return minusculas
	end
	return "info"
end

-- require seguro con WaitForChild acotado; lanza un error legible si falta (Init falla y Main lo registra).
local function requerir(padre, nombre)
	if not padre then
		error("no se encontró la carpeta para " .. nombre)
	end
	local modulo = padre:FindFirstChild(nombre) or padre:WaitForChild(nombre, 10)
	if not modulo then
		error("no se encontró el módulo " .. nombre)
	end
	return require(modulo)
end

local function texto(valor)
	if valor == nil then
		return ""
	end
	return tostring(valor)
end

---------------------------------------------------------------------------------------------------
-- Ciclo de vida
---------------------------------------------------------------------------------------------------
function NotificationController:Init(registro)
	self.registro = registro
	Config = registro.Config
	UIBuilder = registro.UIBuilder
	if not UIBuilder then
		error("UIBuilder no está disponible")
	end
	local Shared = registro.Shared
	local Util = Shared:FindFirstChild("Util") or Shared:WaitForChild("Util", 10)
	UITheme = requerir(Shared, "UITheme")
	RoleDefinitions = requerir(Shared, "RoleDefinitions")
	Net = requerir(Util, "Net")
	Maid = requerir(Util, "Maid")
	Format = requerir(Util, "Format")

	self.maid = Maid.new()
	self.visibles = {} -- { Texto, Nivel, Destacado, Marco, Cerrar }
	self.pendientes = {}
	self.contador = 0
	self.ultimoTimbre = -math.huge
	self.ultimoEstadoJornada = nil
	self.tokenSubtitulo = 0
	self:_Construir()
end

-- Silencio de moderación: el servidor ya bloquea el envío (TextSource.CanSend); aquí se desactiva la barra
-- de chat y se explica hasta cuándo, también en el chat heredado donde solo existe el atributo.
function NotificationController:_VigilarSilencio()
	local jugador = game:GetService("Players").LocalPlayer
	local function aplicar()
		local silenciado = jugador:GetAttribute("Silenciado") == true
		pcall(function()
			local barra = TextChatService:FindFirstChildOfClass("ChatInputBarConfiguration")
			if barra then
				barra.Enabled = not silenciado
			end
		end)
		if silenciado then
			local hasta = tonumber(jugador:GetAttribute("SilenciadoHasta"))
			local cuando = ""
			if hasta and hasta > 0 then
				cuando = " hasta las " .. os.date("%H:%M", math.floor(hasta))
			end
			self:Notificar("Estás silenciado" .. cuando .. ". No puedes escribir en el chat.", "aviso", 6)
		end
	end
	jugador:GetAttributeChangedSignal("Silenciado"):Connect(aplicar)
	if jugador:GetAttribute("Silenciado") == true then
		aplicar()
	end
end

function NotificationController:Start()
	pcall(self._VigilarSilencio, self)
	-- Aviso de la pantalla de carga si continuó sin todos los recursos.
	local nombre = (Config.Nombres and Config.Nombres.SenalCargaLista) or "ColegioRP_CargaLista"
	local senal = ReplicatedFirst:FindFirstChild(nombre)
	if senal and senal:GetAttribute("AvisoRecursos") == true then
		self:Notificar("Algunos recursos siguen cargando; la escena puede tardar unos segundos en verse completa.", "aviso", 6)
	end

	task.spawn(function()
		local remoto = Net.Evento("EventoCliente")
		if not remoto then
			warn("[ColegioRP] NotificationController: EventoCliente no disponible; no se recibirán avisos del servidor.")
			return
		end
		self.maid:GiveTask(remoto.OnClientEvent:Connect(function(carga)
			if typeof(carga) ~= "table" or typeof(carga.Tipo) ~= "string" then
				return
			end
			local datos = carga.Datos
			if typeof(datos) ~= "table" then
				datos = {}
			end
			local ok, err = true, nil
			if carga.Tipo == "Notificacion" then
				ok, err = pcall(self._AlRecibirNotificacion, self, datos)
			elseif carga.Tipo == "Aviso" then
				ok, err = pcall(self.Aviso, self, datos)
			elseif carga.Tipo == "Jornada" then
				ok, err = pcall(self._AlRecibirJornada, self, datos)
			end
			if not ok then
				warn("[ColegioRP] NotificationController: " .. tostring(err))
			end
		end))
	end)
end

---------------------------------------------------------------------------------------------------
-- Interfaz
---------------------------------------------------------------------------------------------------
function NotificationController:_Construir()
	local capa = ((UITheme.Capas and UITheme.Capas.Menu) or 90) + 5
	local gui = UIBuilder.Pantalla("Notificaciones", capa)
	self.gui = gui

	local contenedor = Instance.new("Frame")
	contenedor.Name = "Toasts"
	contenedor.BackgroundTransparency = 1
	contenedor.BorderSizePixel = 0
	contenedor.AutomaticSize = Enum.AutomaticSize.Y
	contenedor.AnchorPoint = Vector2.new(0.5, 0)
	contenedor.Parent = gui
	UIBuilder.Disposicion(contenedor, { Espaciado = 6, Alineacion = Enum.HorizontalAlignment.Center })
	self.contenedor = contenedor

	local subtitulo = Instance.new("TextLabel")
	subtitulo.Name = "Subtitulo"
	subtitulo.BackgroundColor3 = UITheme.Colores.Sombra
	subtitulo.BackgroundTransparency = 0.35
	subtitulo.BorderSizePixel = 0
	subtitulo.Font = UITheme.Fuente("Subtitulo")
	subtitulo.TextSize = UITheme.Tamanos.Subtitulo
	subtitulo.TextColor3 = UITheme.Colores.Blanco
	subtitulo.TextWrapped = true
	subtitulo.AutomaticSize = Enum.AutomaticSize.Y
	subtitulo.AnchorPoint = Vector2.new(0.5, 1)
	subtitulo.Text = ""
	subtitulo.Visible = false
	UIBuilder.Esquinas(subtitulo, UITheme.RadioPequeno)
	UIBuilder.Relleno(subtitulo, 6, 6, 12, 12)
	subtitulo.Parent = gui
	self.subtitulo = subtitulo

	self:_Reubicar()
	pcall(function()
		local camara = workspace.CurrentCamera
		self.maid:GiveTask(camara:GetPropertyChangedSignal("ViewportSize"):Connect(function()
			self:_Reubicar()
		end))
	end)
end

-- Ancho y posición según el tamaño de pantalla: arriba al centro bajo la barra de Roblox; subtítulos
-- abajo al centro por encima de los controles táctiles y de las acciones contextuales del HUD.
function NotificationController:_Reubicar()
	if not self.contenedor or self.contenedor.Parent == nil then
		return
	end
	local escala = math.max(0.5, UIBuilder.EscalaTotal())
	local anchoUI = UIBuilder.AnchoUI()
	local arriba = math.ceil(UIBuilder.InsetSuperior() / escala) + 8
	local ancho = math.floor(math.min(420, math.max(220, anchoUI - 32)))
	self.contenedor.Size = UDim2.new(0, ancho, 0, 0)
	self.contenedor.Position = UDim2.new(0.5, 0, 0, arriba)
	local abajo = math.ceil(UIBuilder.MargenInferiorTactil() / escala) + UIBuilder.AltoBoton() + 28
	self.subtitulo.Size = UDim2.new(0, math.floor(math.min(560, math.max(220, anchoUI - 48))), 0, 0)
	self.subtitulo.Position = UDim2.new(0.5, 0, 1, -abajo)
end

---------------------------------------------------------------------------------------------------
-- Cola de toasts
---------------------------------------------------------------------------------------------------
function NotificationController:_Duplicado(item)
	for _, visible in ipairs(self.visibles) do
		if visible.Texto == item.Texto and visible.Nivel == item.Nivel then
			return true
		end
	end
	for _, pendiente in ipairs(self.pendientes) do
		if pendiente.Texto == item.Texto and pendiente.Nivel == item.Nivel then
			return true
		end
	end
	return false
end

function NotificationController:_Encolar(item)
	if self:_Duplicado(item) then
		return
	end
	if #self.visibles < self.MaxVisibles then
		self:_Mostrar(item)
		return
	end
	if item.Destacado then
		-- Un aviso oficial se muestra de inmediato: entra primero en la cola y se retira el toast más antiguo.
		table.insert(self.pendientes, 1, item)
		for _, visible in ipairs(self.visibles) do
			if not visible.Destacado and not visible.Cerrando then
				visible.Cerrando = true
				pcall(visible.Cerrar)
				break
			end
		end
	else
		table.insert(self.pendientes, item)
	end
	while #self.pendientes > self.MaxPendientes do
		local indice = #self.pendientes
		for i, pendiente in ipairs(self.pendientes) do
			if not pendiente.Destacado then
				indice = i
				break
			end
		end
		table.remove(self.pendientes, indice)
	end
end

function NotificationController:_Mostrar(item)
	if not self.contenedor or self.contenedor.Parent == nil then
		return
	end
	self.contador = self.contador + 1
	local orden = self.contador
	if item.Destacado then
		orden = orden - 1000000
	end
	local entrada = { Texto = item.Texto, Nivel = item.Nivel, Destacado = item.Destacado == true }
	local marco, cerrar = UIBuilder.Toast(self.contenedor, item.Texto, item.Nivel, item.Duracion, {
		Titulo = item.Titulo,
		Icono = item.Icono,
		LayoutOrder = orden,
		AlCerrar = function()
			self:_AlCerrarToast(entrada)
		end,
	})
	if not marco then
		return
	end
	entrada.Marco = marco
	entrada.Cerrar = cerrar
	table.insert(self.visibles, entrada)

	if item.Destacado then
		local borde = marco:FindFirstChildOfClass("UIStroke")
		if borde then
			borde.Color = UITheme.Colores.Amarillo
			borde.Thickness = 2
		end
	end

	-- Tocar o pulsar el toast lo cierra.
	local zona = Instance.new("TextButton")
	zona.Name = "Cerrar"
	zona.BackgroundTransparency = 1
	zona.Text = ""
	zona.Selectable = false
	zona.AutoButtonColor = false
	zona.Size = UDim2.new(1, 58, 1, 0)
	zona.Position = UDim2.new(0, -46, 0, 0)
	zona.ZIndex = marco.ZIndex + 5
	zona.Parent = marco
	zona.Activated:Connect(function()
		if typeof(cerrar) == "function" then
			cerrar()
		end
	end)

	if item.Destacado or item.Nivel == "Aviso" or item.Nivel == "Error" then
		UIBuilder.Sonido("Notificacion", 0.5)
	end
end

function NotificationController:_AlCerrarToast(entrada)
	for i, visible in ipairs(self.visibles) do
		if visible == entrada then
			table.remove(self.visibles, i)
			break
		end
	end
	task.defer(function()
		while #self.visibles < self.MaxVisibles and #self.pendientes > 0 do
			local siguiente = table.remove(self.pendientes, 1)
			self:_Mostrar(siguiente)
		end
	end)
end

---------------------------------------------------------------------------------------------------
-- API pública
---------------------------------------------------------------------------------------------------

-- Muestra una notificación. nivel: "info" | "exito" | "aviso" | "error" | "timbre". duracion en segundos (opcional).
-- opciones (opcional): { Titulo = string, Destacado = bool, Icono = string }.
function NotificationController:Notificar(contenido, nivel, duracion, opciones)
	local mensaje = Format.Truncar(texto(contenido), 220)
	if mensaje == "" then
		return
	end
	local clave = normalizarNivel(nivel)
	if clave == "timbre" then
		self:Timbre(mensaje, duracion, typeof(opciones) == "table" and opciones.SonidoServidor == true)
		return
	end
	local def = NIVELES[clave]
	local segundos = tonumber(duracion) or def.Duracion
	if segundos ~= segundos then
		segundos = def.Duracion
	end
	segundos = math.clamp(segundos, 1, 20)
	opciones = typeof(opciones) == "table" and opciones or {}
	self:_Encolar({
		Texto = mensaje,
		Nivel = def.Nivel,
		Duracion = segundos,
		Icono = opciones.Icono or def.Icono,
		Titulo = opciones.Titulo,
		Destacado = opciones.Destacado == true,
	})
end

-- Timbre escolar: sonido (si Config.Sonidos.Timbre > 0) y subtítulo si el ajuste Subtitulos está activo;
-- con los subtítulos desactivados se muestra como toast informativo.
function NotificationController:Timbre(contenido, duracion, sonidoServidor)
	local ahora = os.clock()
	if ahora - self.ultimoTimbre < self.VentanaTimbreSeg then
		return
	end
	self.ultimoTimbre = ahora
	local mensaje = Format.Truncar(texto(contenido), 160)
	if not sonidoServidor then
		UIBuilder.Sonido("Timbre", 0.6) -- el servidor ya reproduce el timbre cuando SonidoServidor = true
	end
	if mensaje == "" then
		mensaje = "Suena el timbre"
	end
	if self:SubtitulosActivos() then
		self:Subtitulo("♪ [Timbre] " .. mensaje, tonumber(duracion) or 5)
	else
		self:_Encolar({ Texto = mensaje, Nivel = "Info", Duracion = tonumber(duracion) or 5, Icono = "♪" })
	end
end

-- Muestra un subtítulo abajo al centro durante 'duracion' segundos (reemplaza al anterior).
function NotificationController:Subtitulo(contenido, duracion)
	local etiqueta = self.subtitulo
	if not etiqueta or etiqueta.Parent == nil then
		return
	end
	self.tokenSubtitulo = self.tokenSubtitulo + 1
	local token = self.tokenSubtitulo
	etiqueta.Text = Format.Truncar(texto(contenido), 200)
	etiqueta.TextTransparency = 1
	etiqueta.BackgroundTransparency = 1
	etiqueta.Visible = true
	UIBuilder.Tween(etiqueta, { TextTransparency = 0, BackgroundTransparency = 0.35 }, "Rapida")
	local segundos = tonumber(duracion) or 5
	if segundos ~= segundos then
		segundos = 5
	end
	task.delay(math.clamp(segundos, 1, 15), function()
		if self.tokenSubtitulo ~= token or etiqueta.Parent == nil then
			return
		end
		UIBuilder.Tween(etiqueta, { TextTransparency = 1, BackgroundTransparency = 1 }, "Normal", function()
			if self.tokenSubtitulo == token and etiqueta.Parent ~= nil then
				etiqueta.Visible = false
			end
		end)
	end)
end

-- Aviso oficial { Texto, Autor, Cargo, Alcance }: toast destacado durante 8 s.
function NotificationController:Aviso(datos)
	if typeof(datos) ~= "table" then
		return
	end
	local maximo = (Config.Limites and Config.Limites.MaxAvisoCaracteres) or 160
	local mensaje = Format.Truncar(texto(datos.Texto), maximo)
	if mensaje == "" then
		return
	end
	local titulo = "AVISO OFICIAL"
	if datos.Alcance == "Aula" then
		titulo = "AVISO DEL AULA"
	end
	local firma = {}
	if typeof(datos.Cargo) == "string" and datos.Cargo ~= "" then
		if RoleDefinitions.Existe(datos.Cargo) then
			table.insert(firma, RoleDefinitions.Nombre(datos.Cargo))
		else
			table.insert(firma, Format.Truncar(datos.Cargo, 32))
		end
	end
	if typeof(datos.Autor) == "string" and datos.Autor ~= "" then
		table.insert(firma, Format.Truncar(datos.Autor, 32))
	end
	if #firma > 0 then
		titulo = titulo .. " · " .. table.concat(firma, " ")
	end
	self:_Encolar({
		Texto = mensaje,
		Nivel = "Aviso",
		Duracion = self.DuracionAviso,
		Titulo = titulo,
		Icono = "!",
		Destacado = true,
	})
end

-- Cierra todos los toasts y vacía la cola.
function NotificationController:Limpiar()
	table.clear(self.pendientes)
	local copia = {}
	for i, visible in ipairs(self.visibles) do
		copia[i] = visible
	end
	for _, visible in ipairs(copia) do
		if typeof(visible.Cerrar) == "function" then
			pcall(visible.Cerrar)
		end
	end
end

-- ¿Están activos los subtítulos? (ajuste Subtitulos de SettingsController; por defecto sí).
function NotificationController:SubtitulosActivos()
	local Settings = self.registro and self.registro.Get("SettingsController")
	if Settings and typeof(Settings.Ajustes) == "function" then
		local ok, ajustes = pcall(Settings.Ajustes, Settings)
		if ok and typeof(ajustes) == "table" and ajustes.Subtitulos ~= nil then
			return ajustes.Subtitulos == true
		end
	end
	return true
end

---------------------------------------------------------------------------------------------------
-- Eventos del servidor
---------------------------------------------------------------------------------------------------
function NotificationController:_AlRecibirNotificacion(datos)
	if typeof(datos.Texto) ~= "string" then
		return
	end
	local duracion = tonumber(datos.Duracion)
	if duracion ~= nil and duracion ~= duracion then
		duracion = nil
	end
	if duracion then
		duracion = math.clamp(duracion, 1, 15)
	end
	-- Algunos servicios (RoleService, FootballService) envían también Titulo y el nivel en Tipo.
	local opciones = nil
	if typeof(datos.Titulo) == "string" and datos.Titulo ~= "" then
		opciones = { Titulo = Format.Truncar(datos.Titulo, 60) }
	end
	if datos.SonidoServidor == true then
		opciones = opciones or {}
		opciones.SonidoServidor = true
	end
	self:Notificar(datos.Texto, datos.Nivel or datos.Tipo, duracion, opciones)
end

-- Cambio de periodo de la jornada -> timbre (el primer snapshot solo fija la referencia).
function NotificationController:_AlRecibirJornada(datos)
	local estado = datos.Estado
	if typeof(estado) ~= "string" then
		return
	end
	local anterior = self.ultimoEstadoJornada
	self.ultimoEstadoJornada = estado
	if anterior == nil or anterior == estado or datos.Timbre == false then
		return
	end
	local nombre = datos.Nombre
	if typeof(nombre) ~= "string" or nombre == "" then
		nombre = estado
	end
	self:Timbre("Comienza: " .. nombre)
end

return NotificationController
]=] }
FUENTES["StarterPlayer/StarterPlayerScripts/ColegioRP/Controllers/PCController"] = { clase = "ModuleScript", fuente = [=[
--[[
	Ruta en el Explorer: StarterPlayer.StarterPlayerScripts.ColegioRP.Controllers.PCController
	Tipo: ModuleScript
	"Escritorio escolar" de los computadores de la sala de tecnología (docs/ARQUITECTURA.md §7). Solo se abre
	cuando el servidor lo indica (EventoCliente "PC" Sub = "AbrirEscritorio") o con PCController.Abrir(datos).
	Barra superior (nombre del colegio, reloj escolar, Apagar, Salir) y aplicaciones en pestañas:
	- Procesador de texto: documento con contador; «Guardar en cuaderno» -> PCAction Resultado { App = "Procesador" }.
	- Cuestionario: cuestionarios públicos de Catalogs o la actividad abierta del aula; corrige el servidor.
	- Simulador educativo: caída libre y péndulo; «Calcular» es local (solo para mostrar) y «Validar» lo
	  comprueba el servidor con tolerancia del 2 %.
	- Programación básica: editor de comandos con ayuda y retos; el servidor ejecuta el programa y devuelve la
	  traza, que se anima localmente en una cuadrícula 8×8 dibujada con Frames.
	- Pantalla de clase: texto proyectado por el docente (y, con pc.bloquear, controles de proyección y bloqueo).
	Ventana centrada en PC y a pantalla completa con pestañas en móvil; navegable con mando; nunca tapa los
	controles táctiles (UIBuilder.Contenedor). Se cierra con «Salir» (envía PCAction Salir) o cuando el servidor
	informa "Estado" sin ocupante. Nunca simula Internet real ni controla un PC real.
]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local TIMEOUT = 30
local function esperarHijo(padre, nombre)
	local hijo = nil
	if padre then
		hijo = padre:FindFirstChild(nombre) or padre:WaitForChild(nombre, TIMEOUT)
	end
	if not hijo then
		error("[ColegioRP][PCController] No apareció '" .. tostring(nombre) .. "' en " .. TIMEOUT .. " s")
	end
	return hijo
end

local RP = esperarHijo(ReplicatedStorage, "ColegioRP")
local Shared = esperarHijo(RP, "Shared")
local Util = esperarHijo(Shared, "Util")
local Config = require(esperarHijo(Shared, "Config"))
local UITheme = require(esperarHijo(Shared, "UITheme"))
local Catalogs = require(esperarHijo(Shared, "Catalogs"))
local RemoteContracts = require(esperarHijo(Shared, "RemoteContracts"))
local RoleDefinitions = require(esperarHijo(Shared, "RoleDefinitions"))
local TimetableDefinitions = require(esperarHijo(Shared, "TimetableDefinitions"))
local Net = require(esperarHijo(Util, "Net"))
local Signal = require(esperarHijo(Util, "Signal"))
local Maid = require(esperarHijo(Util, "Maid"))
local Format = require(esperarHijo(Util, "Format"))
local UIBuilder = require(esperarHijo(esperarHijo(script.Parent.Parent, "UI"), "UIBuilder"))

local LocalPlayer = Players.LocalPlayer
local Colores = UITheme.Colores

local PCController = {}
PCController.Nombre = "PCController"
-- InteractionController no delega "AbrirEscritorio": este controlador ya atiende su propio evento.
PCController.ManejaAperturaPropia = true
PCController.Abierto = Signal.new() -- (pcId)
PCController.Cerrado = Signal.new() -- (pcId)

---------------------------------------------------------------------------------------------------
-- Constantes
---------------------------------------------------------------------------------------------------
local LOG = "[ColegioRP][PCController] "
local ORDEN_PANTALLA = UITheme.Capas.Panel
local MAX_TEXTO = (Config.Cuaderno and Config.Cuaderno.MaxCaracteresPagina) or 1200
local MAX_PROYECCION = 300
local MAX_RESPUESTA = (Config.Limites and Config.Limites.MaxRespuestaCaracteres) or 300
