		nombre = CORTOS[app.Id] or app.Nombre
	end
	local texto = (app.Icono and (tostring(app.Icono) .. "  ") or "") .. nombre
	if app.Id == APP_PANTALLA and estado.Novedad then
		texto = texto .. " •"
	end
