	lista.Name = "Pestanas"
	lista.ScrollBarThickness = 4
	ui.ListaPestanas = lista
	ui.AltoPestanas = alto + 10
	local botones = {}
	for i, app in ipairs(APPS) do
		local id = app.Id
		local boton = UIBuilder.Boton(lista, textoPestana(app), function()
			seleccionarApp(id, true)
