local function copiar(tabla)
	local copia = {}
	for clave, valor in pairs(tabla) do
		copia[clave] = valor
	end
	return copia
end

local function clamp(valor, minimo, maximo)
	return math.max(minimo, math.min(maximo, valor))
end

